insert into public.exercises
  (slug, name, name_en, persona_type, level, categories, short_description, detail_full, common_mistakes, photo_path, source)
values
  ('3-4-sit-up', 'Brzuszki 3/4', '3/4 Sit-Up', 'motor_coach', 'beginner', array['Siłowe', 'Brzuch'], 'Wariant brzuszków, w którym opuszczasz tułów tylko do 3/4 drogi, utrzymując stałe napięcie brzucha. Wzmacnia mięśnie brzucha, głównie prosty brzucha.', '1. Połóż się na podłodze i podeprzyj stopy. Nogi powinny być zgięte w kolanach.
2. Połóż dłonie za głową lub z boku głowy. Zaczynasz z plecami na ziemi. To będzie pozycja startowa.
3. Zegnij biodra i kręgosłup, aby unieść tułów w kierunku kolan.
4. Na szczycie spięcia tułów powinien być prostopadły do podłoża. Odwróć ruch, schodząc tylko do 3/4 drogi.
5. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/3_4_Sit-Up/0.jpg', 'free_exercise_db'),
  ('90-90-hamstring', 'Rozciąganie dwugłowego uda 90/90', '90/90 Hamstring', 'motor_coach', 'beginner', array['Rozciąganie', 'Dwugłowe uda'], 'Ćwiczenie rozciągające mięśnie tylnej części uda w leżeniu na plecach. Jedna noga wyprostowana, druga zgięta pod kątem 90 stopni w biodrze i kolanie.', '1. Połóż się na plecach z jedną nogą wyprostowaną.
2. Drugą nogę zegnij w biodrze i kolanie pod kątem 90 stopni. W razie potrzeby podeprzyj nogę dłońmi. To będzie pozycja startowa.
3. Wyprostuj nogę pionowo w górę, chwilę zatrzymując się na górze. Wróć nogą do pozycji startowej.
4. Powtórz 10–20 powtórzeń, a następnie zmień nogę.', NULL, 'free-exercise-db/90_90_Hamstring/0.jpg', 'free_exercise_db'),
  ('ab-crunch-machine', 'Maszyna do brzuszków', 'Ab Crunch Machine', 'motor_coach', 'intermediate', array['Siłowe', 'Brzuch'], 'Ćwiczenie na maszynie izolujące mięśnie brzucha. Łączy unoszenie nóg ze spięciem górnej części tułowia.', '1. Wybierz lekki opór i usiądź na maszynie, wsuwając stopy pod poduszki i chwytając górne uchwyty. Ramiona powinny być zgięte pod kątem 90 stopni, a przedramiona oparte na poduszkach. To będzie pozycja startowa.
2. Jednocześnie zacznij unosić nogi w górę, robiąc spięcie górną częścią tułowia. Robisz wydech podczas tego ruchu. Wskazówka: Używaj powolnego i kontrolowanego ruchu. Koncentruj się na pracy brzuchem przy poruszaniu ciężarem, rozluźniając nogi i stopy.
3. Po sekundowej pauzie powoli wróć do pozycji startowej, robiąc wdech.
4. Powtórz ruch zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Ab_Crunch_Machine/0.jpg', 'free_exercise_db'),
  ('ab-roller', 'Ab Roller (kółko do brzucha)', 'Ab Roller', 'motor_coach', 'intermediate', array['Siłowe', 'Brzuch'], 'Ćwiczenie z kółkiem treningowym wzmacniające całe ciało, ze szczególnym naciskiem na mięśnie głębokie. Polega na przetaczaniu kółka w przód i z powrotem z klęku.', '1. Chwyć Ab Roller obiema rękami i uklęknij na podłodze.
2. Połóż kółko na podłodze przed sobą, tak abyś był na czworakach (jak w pozycji do pompek na kolanach). To będzie pozycja startowa.
3. Powoli przetaczaj kółko prosto do przodu, rozciągając ciało do prawie prostej pozycji. Wskazówka: Zejdź tak nisko, jak tylko możesz, nie dotykając podłogi ciałem. Wdech w tej fazie ruchu.
4. Po pauzie w pozycji rozciągniętej zacznij przyciągać się z powrotem do pozycji startowej, robiąc wydech. Wskazówka: Rób to powoli i trzymaj mięśnie głębokie napięte przez cały czas.', NULL, 'free-exercise-db/Ab_Roller/0.jpg', 'free_exercise_db'),
  ('adductor', 'Rozluźnianie przywodzicieli (rolowanie)', 'Adductor', 'motor_coach', 'intermediate', array['Rozciąganie', 'Przywodziciele'], 'Automasaż wewnętrznej strony uda z użyciem wałka. Polega na przetaczaniu wewnętrznej części uda po wałku z zatrzymywaniem się na bolesnych punktach.', '1. Połóż się na brzuchu z jedną nogą na wałku.
2. Obróć nogę tak, aby wałek dociskał do wewnętrznej strony uda. Przenieś na wałek tyle ciężaru, ile dasz radę znieść.
3. Starając się rozluźnić mięśnie wewnętrznej strony uda, przetaczaj się po wałku między biodrem a kolanem, zatrzymując się na punktach napięcia na 10–30 sekund. Powtórz na drugiej nodze.', NULL, 'free-exercise-db/Adductor/0.jpg', 'free_exercise_db'),
  ('adductor-groin', 'Przywodziciele/pachwiny (rozciąganie z partnerem)', 'Adductor/Groin', 'motor_coach', 'intermediate', array['Rozciąganie', 'Przywodziciele'], 'Ćwiczenie rozciągające przywodziciele (wewnętrzną stronę ud) wykonywane z partnerem. Partner stawia opór, a potem pogłębia rozciąganie.', '1. Połóż się na plecach ze stopami uniesionymi w stronę sufitu.
2. Partner trzyma Twoje stopy lub kostki. Odsuń nogi od siebie tak daleko, jak możesz. To będzie pozycja startowa.
3. Próbuj ściskać nogi razem przez 10 lub więcej sekund, podczas gdy partner uniemożliwia Ci to.
4. Teraz rozluźnij mięśnie nóg, a partner rozepchnie Twoje stopy, rozciągając tak daleko, jak jest dla Ciebie komfortowe. Koniecznie daj partnerowi znać, gdy rozciąganie jest wystarczające, aby uniknąć przeciążenia lub kontuzji.', NULL, 'free-exercise-db/Adductor_Groin/0.jpg', 'free_exercise_db'),
  ('advanced-kettlebell-windmill', 'Zaawansowany młyn z kettlebell', 'Advanced Kettlebell Windmill', 'motor_coach', 'intermediate', array['Siłowe', 'Brzuch'], 'Zaawansowane ćwiczenie z kettlebell trzymanym nad głową. Wzmacnia barki i mięśnie głębokie, poprawia mobilność bioder.', '1. Wykonaj wybur (clean) i wyciśnij kettlebell nad głowę jedną ręką.
2. Trzymając kettlebell cały czas zablokowany nad głową, wypchnij pośladki w kierunku ręki z kettlebellem. Niepracującą rękę trzymaj za plecami i skieruj stopy pod kątem 45 stopni od ręki z kettlebellem.
3. Opuść się tak nisko, jak to możliwe.
4. Zatrzymaj się na sekundę i odwróć ruch, wracając do pozycji startowej.', NULL, 'free-exercise-db/Advanced_Kettlebell_Windmill/0.jpg', 'free_exercise_db'),
  ('air-bike', 'Brzuch rowerzysty', 'Air Bike', 'motor_coach', 'beginner', array['Siłowe', 'Brzuch'], 'Ćwiczenie brzucha łączące spięcia z ruchem nóg naśladującym pedałowanie. Angażuje mięśnie skośne brzucha i mięśnie głębokie.', '1. Połóż się płasko na podłodze z odcinkiem lędźwiowym dociśniętym do ziemi. Do tego ćwiczenia będziesz potrzebować dłoni przy głowie. Uważaj jednak, aby nie obciążać karku podczas wykonywania. Unieś barki do pozycji spięcia.
2. Podnieś kolana do pozycji prostopadłej do podłogi, z dolną częścią nóg równoległą do podłogi. To będzie pozycja startowa.
3. Teraz jednocześnie, powoli wykonuj ruch pedałowania, kopiąc prawą nogą do przodu i przyciągając kolano lewej nogi. Przyciągnij prawy łokieć blisko lewego kolana, robiąc spięcie na bok, robiąc wydech.
4. Wróć do pozycji początkowej, robiąc wdech.
5. Zrób spięcie na przeciwną stronę, pedałując nogami i przyciągając lewy łokieć bliżej prawego kolana, robiąc wydech.
6. Kontynuuj naprzemiennie w ten sposób, aż wykonasz wszystkie zalecane powtórzenia dla każdej strony.', NULL, 'free-exercise-db/Air_Bike/0.jpg', 'free_exercise_db'),
  ('all-fours-quad-stretch', 'Rozciąganie czworogłowego uda na czworakach', 'All Fours Quad Stretch', 'motor_coach', 'intermediate', array['Rozciąganie', 'Uda'], 'Rozciąganie mięśnia czworogłowego uda i zginaczy biodra w pozycji na czworakach. Chwytasz stopę ręką i utrzymujesz kolano mocno zgięte.', '1. Zacznij na czworakach, następnie unieś nogę nad podłogę i złap stopę ręką.
2. Użyj ręki, aby trzymać stopę lub kostkę, utrzymując kolano całkowicie zgięte, rozciągając czworogłowe uda i zginacze biodra.
3. Skup się na wyproście bioder, pchając je w stronę podłogi. Trzymaj 10–20 sekund, a następnie zmień strony.', NULL, 'free-exercise-db/All_Fours_Quad_Stretch/0.jpg', 'free_exercise_db'),
  ('alternate-hammer-curl', 'Uginanie ramion młotkowe naprzemiennie', 'Alternate Hammer Curl', 'motor_coach', 'beginner', array['Siłowe', 'Biceps'], 'Uginanie hantli chwytem młotkowym, naprzemiennie każdą ręką. Wzmacnia biceps i mięsień ramienno-promieniowy (przedramię).', '1. Stań z tułowiem wyprostowanym, z hantlą w każdej ręce opuszczoną wzdłuż ciała. Łokcie powinny być blisko tułowia.
2. Dłonie powinny być skierowane w stronę tułowia. To będzie pozycja startowa.
3. Trzymając ramię nieruchomo, ugnij prawą rękę do przodu, napinając biceps, robiąc wydech. Kontynuuj ruch, aż biceps będzie całkowicie napięty, a hantle na wysokości barków. Utrzymaj pozycję spięcia przez sekundę, mocno zaciskając biceps. Wskazówka: Powinny poruszać się tylko przedramiona.
4. Powoli zacznij opuszczać hantle do pozycji startowej, robiąc wdech.
5. Powtórz ruch lewą ręką. To stanowi jedno powtórzenie.
6. Kontynuuj naprzemiennie w ten sposób przez zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Alternate_Hammer_Curl/0.jpg', 'free_exercise_db'),
  ('alternate-heel-touchers', 'Dotykanie pięt naprzemiennie', 'Alternate Heel Touchers', 'motor_coach', 'beginner', array['Siłowe', 'Brzuch'], 'Ćwiczenie brzucha w leżeniu z ugiętymi nogami. Polega na unoszeniu tułowia i dotykaniu dłonią pił na przemian po obu stronach. Angażuje mięśnie skośne.', '1. Połóż się na podłodze z ugiętymi kolanami i stopami na podłodze rozstawionymi na około 45–60 cm. Ramiona powinny być wyprostowane wzdłuż ciała. To będzie pozycja startowa.
2. Unieś tułów do przodu i w górę o około 7–10 cm w prawą stronę i dotknij prawej pięty, utrzymując spięcie przez sekundę. Wydech podczas wykonywania tego ruchu.
3. Teraz wróć powoli do pozycji startowej, robiąc wdech.
4. Teraz zrób spięcie tułowiem do przodu i w górę o około 7–10 cm w lewą stronę i dotknij lewej pięty, utrzymując spięcie przez sekundę. Wydech podczas wykonywania tego ruchu, a następnie wróć do pozycji startowej, robiąc wdech. Gdy dotknąłeś obu pięt, to stanowi 1 powtórzenie.
5. Kontynuuj naprzemiennie strony w ten sposób, aż wykonasz wszystkie zalecane powtórzenia.', NULL, 'free-exercise-db/Alternate_Heel_Touchers/0.jpg', 'free_exercise_db'),
  ('alternate-incline-dumbbell-curl', 'Uginanie hantli na ławce skośnej naprzemiennie', 'Alternate Incline Dumbbell Curl', 'motor_coach', 'beginner', array['Siłowe', 'Biceps'], 'Uginanie hantli leżąc na ławce skośnej, naprzemiennie każdą ręką, z rotacją nadgarstka. Skutecznie izoluje biceps.', '1. Usiądź na ławce skośnej z hantlą w każdej ręce opuszczoną wzdłuż ciała. Wskazówka: Trzymaj łokcie blisko tułowia. To będzie pozycja startowa.
2. Trzymając ramię nieruchomo, ugnij prawą rękę do przodu, napinając biceps, robiąc wydech. Podczas tego ruchu obróć nadgarstek tak, aby dłoń była skierowana do góry. Kontynuuj ruch, aż biceps będzie całkowicie napięty, a hantle na wysokości barków. Utrzymaj pozycję spięcia przez sekundę, mocno zaciskając biceps. Wskazówka: Powinny poruszać się tylko przedramiona.
3. Powoli zacznij opuszczać hantlę do pozycji startowej, robiąc wdech.
4. Powtórz ruch lewą ręką. To stanowi jedno powtórzenie.
5. Kontynuuj naprzemiennie w ten sposób przez zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Alternate_Incline_Dumbbell_Curl/0.jpg', 'free_exercise_db'),
  ('alternate-leg-diagonal-bound', 'Skoki diagonalne na przemian nogami', 'Alternate Leg Diagonal Bound', 'motor_coach', 'beginner', array['Plyometryka', 'Uda'], 'Ćwiczenie plyometryczne rozwijające moc nóg. Polega na wykonywaniu skoków po skosie z nogi na nogę, pokrywając jak największą odległość na boki.', '1. Przyjmij wygodną postawę z jedną stopą lekko z przodu.
2. Zacznij od odbicia nogą przednią, wybijając przeciwne kolano do przodu i jak najwyżej przed lądowaniem. Staraj się pokryć jak największą odległość na każdej stronie przy każdym skoku.
3. Może pomóc użycie linii na ziemi do oceny odległości między stronami.
4. Powtórz sekwencję drugą nogą.', NULL, 'free-exercise-db/Alternate_Leg_Diagonal_Bound/0.jpg', 'free_exercise_db'),
  ('alternating-cable-shoulder-press', 'Wyciskanie z wyciągów nad głowę naprzemiennie', 'Alternating Cable Shoulder Press', 'motor_coach', 'beginner', array['Siłowe', 'Barki'], 'Wyciskanie nad głowę na wyciągach, naprzemiennie każdą ręką. Wzmacnia barki i triceps.', '1. Ustaw linki na dole wieży i wybierz odpowiedni ciężar.
2. Chwyć linki i trzymaj je na wysokości barków, dłońmi skierowanymi do przodu. To będzie pozycja startowa.
3. Trzymając głowę i klatkę piersiową uniesioną, wyprostuj łokieć, wyciskając jedną ręką prosto nad głowę.
4. Po pauzie na górze wróć do pozycji startowej i powtórz po przeciwnej stronie.', NULL, 'free-exercise-db/Alternating_Cable_Shoulder_Press/0.jpg', 'free_exercise_db'),
  ('alternating-deltoid-raise', 'Unoszenie hantli naprzemiennie (przód/bok)', 'Alternating Deltoid Raise', 'motor_coach', 'beginner', array['Siłowe', 'Barki'], 'Ćwiczenie na barki z hantlami. Naprzemiennie unosisz hantle przed siebie i na boki, angażując przednią i boczną część barków.', '1. W pozycji stojącej trzymaj parę hantli przy bokach.
2. Trzymając łokcie lekko zgięte, unieś ciężary bezpośrednio przed siebie do wysokości barków, unikając jakiegokolwiek kołysania lub oszukiwania.
3. Opuszczaj ciężary z powrotem do boków.
4. Przy następnym powtórzeniu unieś ciężary na boki, rozprowadzając je na zewnątrz do około wysokości barków.
5. Wróć ciężarami do pozycji startowej i kontynuuj naprzemiennie do przodu i na boki.', NULL, 'free-exercise-db/Alternating_Deltoid_Raise/0.jpg', 'free_exercise_db'),
  ('alternating-floor-press', 'Wyciskanie kettlebell leżąc na podłodze naprzemiennie', 'Alternating Floor Press', 'motor_coach', 'beginner', array['Siłowe', 'Klatka piersiowa'], 'Wyciskanie dwóch kettlebelli leżąc na podłodze, naprzemiennie każdą ręką. Wzmacnia klatkę piersiową, triceps i barki.', '1. Połóż się na podłodze z dwoma kettlebellami obok barków.
2. Ustaw jeden na klatce piersiowej, a potem drugi, chwytając kettlebelle za uchwyt dłońmi skierowanymi do przodu.
3. Wyprostuj oba ramiona, tak aby kettlebelle były trzymane nad klatką piersiową. Opuść jeden kettlebell, przyciągając go do klatki piersiowej i obracając nadgarstek w kierunku drugiego kettlebella.
4. Unieś kettlebell i powtórz po przeciwnej stronie.', NULL, 'free-exercise-db/Alternating_Floor_Press/0.jpg', 'free_exercise_db'),
  ('alternating-hang-clean', 'Wybur z kolana (hang clean) naprzemiennie z kettlebell', 'Alternating Hang Clean', 'motor_coach', 'intermediate', array['Siłowe', 'Dwugłowe uda'], 'Dynamiczne ćwiczenie z dwoma kettlebellami. Naprzemiennie podrzucasz kettlebell na ramię, wykorzystując moc nóg i bioder.', '1. Połóż dwa kettlebelle między stopami. Aby przyjąć pozycję startową, wypchnij pośladki do tyłu i patrz prosto przed siebie.
2. Wykonaj wybur jednym kettlebellem na ramię, trzymając drugi kettlebell w pozycji wiszącej. Wykonaj wybur kettlebella na ramię, prostując nogi i biodra, przyciągając kettlebell w kierunku barków. Obróć nadgarstek podczas tego ruchu.
3. Opuść wyburowany kettlebell do pozycji wiszącej i wykonaj wybur drugim kettlebellem. Powtarzaj.', NULL, 'free-exercise-db/Alternating_Hang_Clean/0.jpg', 'free_exercise_db'),
  ('alternating-kettlebell-press', 'Wyciskanie kettlebell naprzemiennie', 'Alternating Kettlebell Press', 'motor_coach', 'intermediate', array['Siłowe', 'Barki'], 'Wyciskanie dwóch kettlebelli nad głowę naprzemiennie. Buduje siłę barków i stabilność mięśni głębokich.', '1. Wykonaj wybur dwóch kettlebelli na ramiona. Wykonaj wybur, prostując nogi i biodra, przyciągając kettlebelle w kierunku barków. Obróć nadgarstki podczas tego ruchu.
2. Wyciśnij jeden kettlebell prosto nad głowę, prostując łokieć, obracając go tak, aby dłoń była skierowana do przodu, trzymając drugi kettlebell nieruchomo.
3. Opuść wyciśnięty kettlebell do pozycji startowej i natychmiast wyciśnij drugą ręką.', NULL, 'free-exercise-db/Alternating_Kettlebell_Press/0.jpg', 'free_exercise_db'),
  ('alternating-kettlebell-row', 'Wiosłowanie kettlebell naprzemiennie', 'Alternating Kettlebell Row', 'motor_coach', 'intermediate', array['Siłowe', 'Środek pleców'], 'Wiosłowanie w pochyleniu z dwoma kettlebellami, naprzemiennie każdą ręką. Wzmacnia plecy, szczególnie najszerszy grzbietu i równoległoboczny.', '1. Połóż dwa kettlebelle przed stopami. Lekko ugnij kolana i maksymalnie wypchnij pośladki do tyłu. Pochylając się, aby przyjąć pozycję startową, chwyć oba kettlebelle za uchwyty.
2. Odetgnij jeden kettlebell od podłogi, trzymając drugi kettlebell. Ściągnij łopatkę strony pracującej, zginając łokieć, przyciągając kettlebell w kierunku brzucha lub żeber.
3. Opuść kettlebell w pracującej ręce i powtórz drugą ręką.', NULL, 'free-exercise-db/Alternating_Kettlebell_Row/0.jpg', 'free_exercise_db'),
  ('alternating-renegade-row', 'Wiosłowanie renegada naprzemiennie', 'Alternating Renegade Row', 'motor_coach', 'advanced', array['Siłowe', 'Środek pleców'], 'Zaawansowane ćwiczenie łączące pozycję deski z wiosłowaniem kettlebelli. Wzmacnia plecy, barki i mięśnie głębokie.', '1. Połóż dwa kettlebelle na podłodze na szerokość barków. Ustaw się na palcach i dłoniach, jak do pompek, z ciałem prostym i wyprostowanym. Używaj uchwytów kettlebelli do podparcia górnej części ciała. Może być potrzebne rozstawienie stóp szerzej dla stabilności.
2. Dociśnij jeden kettlebell do podłogi i wiosłuj drugim kettlebellem, ściągając łopatkę strony pracującej, zginając łokieć, przyciągając go do boku.
3. Potem opuść kettlebell na podłogę i zacznij wiosłować kettlebellem w przeciwnej ręce. Powtórz kilka razy.', NULL, 'free-exercise-db/Alternating_Renegade_Row/0.jpg', 'free_exercise_db'),
  ('ankle-circles', 'Krążenia stawu skokowego', 'Ankle Circles', 'motor_coach', 'beginner', array['Rozciąganie', 'Łydki'], 'Mobilizacja stawu skokowego poprzez rysowanie kół paluchem. Proste ćwiczenie rozgrzewkowe poprawiające zakres ruchu w kostce.', '1. Użyj stabilnego przedmiotu, jak stojak do przysiadów, aby się podeprzeć.
2. Unieś prawą nogę w górę (tuż około 5 cm nad podłogą) i wykonaj ruch kołowy paluchem. Wyobraź sobie, że rysujesz nim duże koło. Wskazówka: Jedno koło to 1 powtórzenie. Oddychaj normalnie podczas wykonywania ruchu.
3. Kiedy skończysz prawą stopą, powtórz lewą nogą.', NULL, 'free-exercise-db/Ankle_Circles/0.jpg', 'free_exercise_db'),
  ('ankle-on-the-knee', 'Kostka na kolanie (rozciąganie)', 'Ankle On The Knee', 'motor_coach', 'beginner', array['Rozciąganie', 'Pośladki'], 'Rozciąganie bioder i pośladków w pozycji leżącej. Kostka jednej nogi opiera się na przeciwległym kolanie, a obie nogi są przyciągane do klatki piersiowej.', '1. Z pozycji leżącej ugnij kolana i trzymaj stopy na podłodze.
2. Połóż kostkę jednej stopy na przeciwległym kolanie.
3. Chwyć udo lub kolano dolnej nogi i przyciągnij obie nogi do klatki piersiowej. Rozluźnij kark i barki. Trzymaj 10–20 sekund, a następnie zmień strony.', NULL, 'free-exercise-db/Ankle_On_The_Knee/0.jpg', 'free_exercise_db'),
  ('anterior-tibialis-smr', 'Rolowanie piszczeli przednich (SMR)', 'Anterior Tibialis-SMR', 'motor_coach', 'intermediate', array['Rozciąganie', 'Łydki'], 'Automasaż mięśni zewnętrznej strony piszczeli za pomocą wałka. Pomaga rozluźnić napięcia w przednim mięśniu piszczelowym.', '1. Zacznij siedząc na ziemi z ugiętymi nogami i stopami na podłodze.
2. Za pomocą wałka do masażu lub wałka do ciasta wywieraj nacisk na mięśnie zewnętrznej strony piszczeli. Pracuj od tuż pod kolanem do powyżej kostki, zatrzymując się na punktach napięcia na 10–30 sekund. Powtórz na drugiej nodze.', NULL, 'free-exercise-db/Anterior_Tibialis-SMR/0.jpg', 'free_exercise_db'),
  ('anti-gravity-press', 'Wyciskanie antygrawitacyjne', 'Anti-Gravity Press', 'motor_coach', 'beginner', array['Siłowe', 'Barki'], 'Nietypowe ćwiczenie na barki z sztangą w leżeniu na brzuchu na ławce skośnej. Wzmacnia tylne aktony i górną część pleców.', '1. Połóż sztangę na ziemi za głową ławki skośnej.
2. Połóż się na ławce na brzuchu. Chwytem nachwytem podnieś sztangę z podłogi. Zegnij łokcie, wykonując odwrotne uginanie, aby przynieść sztangę blisko klatki piersiowej. To będzie pozycja startowa.
3. Zacznij wyciskać sztangę przed głowę, prostując łokcie. Trzymaj ramiona równolegle do podłoża przez cały ruch.
4. Wróć do pozycji startowej i powtórz, aby wykonać serię.', NULL, 'free-exercise-db/Anti-Gravity_Press/0.jpg', 'free_exercise_db'),
  ('arm-circles', 'Krążenia ramion', 'Arm Circles', 'motor_coach', 'beginner', array['Rozciąganie', 'Barki'], 'Proste ćwiczenie rozgrzewkowe polegające na wykonywaniu okręgów wyprostowanymi ramionami. Rozgrzewa barki i poprawia krążenie.', '1. Stań i wyciągnij ramiona prosto na boki. Ramiona powinny być równoległe do podłogi i prostopadłe (pod kątem 90 stopni) do tułowia. To będzie pozycja startowa.
2. Powoli zacznij wykonywać okręgi o średnicy około 30 cm każdym wyciągniętym ramieniem. Oddychaj normalnie podczas wykonywania ruchu.
3. Kontynuuj ruch okrężny wyciągniętych ramion przez około 10 sekund. Następnie odwróć ruch, krążąc w przeciwnym kierunku.', NULL, 'free-exercise-db/Arm_Circles/0.jpg', 'free_exercise_db'),
  ('arnold-dumbbell-press', 'Wyciskanie Arnolda', 'Arnold Dumbbell Press', 'motor_coach', 'intermediate', array['Siłowe', 'Barki'], 'Wyciskanie hantli nad głowę z rotacją nadgarstków. Angażuje całe barki, ze szczególnym naciskiem na przednią część.', '1. Usiądź na ławce z podparciem pleców i trzymaj dwie hantle przed sobą na wysokości górnej części klatki piersiowej, dłońmi skierowanymi do ciała i łokciami zgiętymi. Wskazówka: Ramiona powinny być przy tułowiu. Pozycja startowa powinna wyglądać jak spięta faza uginania hantli.
2. Teraz, aby wykonać ruch, unieś hantle, obracając dłonie, aż będą skierowane do przodu.
3. Kontynuuj unoszenie hantli, aż ramiona będą wyprostowane nad Tobą w pełnym wyproście. Robisz wydech podczas tej fazy ruchu.
4. Po sekundowej pauzie na górze zacznij opuszczać hantle do pierwotnej pozycji, obracając dłonie w swoją stronę. Wskazówka: Lewe ramię będzie obracało się przeciwnie do wskazówek zegara, a prawe zgodnie z wskazówkami zegara. Wdech podczas tej fazy ruchu.
5. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Arnold_Dumbbell_Press/0.jpg', 'free_exercise_db'),
  ('around-the-worlds', 'Dookoła świata (hantle leżąc)', 'Around The Worlds', 'motor_coach', 'intermediate', array['Siłowe', 'Klatka piersiowa'], 'Ćwiczenie rozciągające klatkę piersiową z hantlami w leżeniu na ławce. Polega na opisywaniu półkola hantlami od bioder nad głowę.', '1. Połóż się na płaskiej ławce trzymając hantlę w każdej ręce dłońmi skierowanymi do sufitu. Wskazówka: Ramiona powinny być równoległe do podłogi i przy udach. Aby uniknąć kontuzji, upewnij się, że trzymasz łokcie lekko zgięte. To będzie pozycja startowa.
2. Teraz przesuwaj hantle, opisując półkole, przemieszczając je z początkowej pozycji nad głowę. Cały ruch powinien odbywać się z ramionami równoległymi do podłogi przez cały czas. Wdech podczas tej fazy ruchu.
3. Odwróć ruch, aby wrócić ciężarami do pozycji startowej, robiąc wydech.', NULL, 'free-exercise-db/Around_The_Worlds/0.jpg', 'free_exercise_db'),
  ('atlas-stone-trainer', 'Symulator kamienia atlasowego', 'Atlas Stone Trainer', 'motor_coach', 'intermediate', array['Strongman', 'Dolny odcinek pleców'], 'Przyrząd treningowy imitujący podnoszenie kamienia atlasowego, zwykle wykonany z końcówek sztangi lub ciężkiej rury. Rozwija siłę potrzebną do podnoszenia kamieni atlasowych.', '1. Ten symulator jest skuteczny do rozwijania siły do kamieni atlasowych dla osób, które nie mają dostępu do kamieni, i jest zazwyczaj wykonany z końcówek sztangi lub ciężkiej rury.
2. Zacznij od załadowania pożądanego ciężaru na sztangę. Rozstaw nogi nad ciężarem, obejmując ramionami przyrząd, zginając się w biodrach.
3. Zacznij od przyciągnięcia ciężaru ponad kolana, prostując biodra. Gdy ciężar minie kolana, można go położyć na udach, siadając i mocno przyciskając go do klatki piersiowej.
4. Zakończ ruch prostując biodra i kolana, aby unieść ciężar tak wysoko, jak to możliwe. Ciężar można odłożyć na uda lub na ziemię, aby wykonać kolejne powtórzenia.', NULL, 'free-exercise-db/Atlas_Stone_Trainer/0.jpg', 'free_exercise_db'),
  ('atlas-stones', 'Kamienie atlasowe', 'Atlas Stones', 'motor_coach', 'advanced', array['Strongman', 'Dolny odcinek pleców'], 'Podnoszenie ciężkiego kamienia z ziemi na podest lub platformę. Klasyczne ćwiczenie strongmana rozwijające całe ciało, szczególnie plecy, biodra i ramiona.', '1. Zacznij z kamieniem atlasowym między stopami. Zegnij się w biodrach, aby objąć kamień ramionami pionowo, próbując wsunąć palce pod kamień. Wiele kamieni ma mały płaski fragment na spodzie, co ułatwia trzymanie kamienia.
2. Przyciągając kamień do tułowia, odbij się z tylnej części stóp, aby oderwać kamień od ziemi.
3. Gdy kamień mija kolana, połóż go na udach, siadając do tyłu i przyciągając kamień na uda.
4. Usiądź nisko, umieszczając kamień wysoko na klatce piersiowej, zmieniając chwyt, aby objąć kamień. Wstań, pracując biodrami. Zbliż się do platformy załadunkowej i pochył się do tyłu, prostując biodra, aby umieścić kamień tak wysoko, jak to możliwe.', NULL, 'free-exercise-db/Atlas_Stones/0.jpg', 'free_exercise_db'),
  ('axle-deadlift', 'Martwy ciąg na osi (grubej sztandze)', 'Axle Deadlift', 'motor_coach', 'intermediate', array['Strongman', 'Dolny odcinek pleców'], 'Martwy ciąg wykonywany na grubej sztandze zwanej osią. Wzmacnia plecy, pośladki i siłę chwytu.', '1. Podejdź do sztangi tak, aby była wyśrodkowana nad stopami. Stopy powinny być rozstawione około na szerokość bioder. Zegnij się w biodrach, aby chwycić sztangę na szerokość barków, pozwalając łopatkom się rozproszyć. Zazwyczaj stosuje się chwyt mieszany (jeden nachwyt, jeden podchwyt).
2. Z ustawionymi stopami i chwytem weź duży wdech, a następnie obniż biodra i ugnij kolana, aż piszczele dotkną sztangi. Patrz przed siebie, trzymaj klatkę piersiową uniesioną i plecy wygięte, i zacznij odbijać się piętami, aby przesunąć ciężar w górę.
3. Po tym, jak sztanga mija kolana, energicznie przyciągnij sztangę do siebie, ściągnij łopatki razem, pchając biodra do przodu w kierunku sztangi.
4. Opuszczaj sztangę, zginając się w biodrach i prowadząc ją do podłogi.', NULL, 'free-exercise-db/Axle_Deadlift/0.jpg', 'free_exercise_db'),
  ('back-flyes-with-bands', 'Rozpiętki tylnych aktonów z gumą oporową', 'Back Flyes - With Bands', 'motor_coach', 'beginner', array['Siłowe', 'Barki'], 'Ćwiczenie na tylne aktony z gumą oporową. Polega na rozprowadzaniu wyprostowanych ramion na boki napinając tylną część barków.', '1. Załóż gumę wokół nieruchomego słupka, np. stojaka do przysiadów.
2. Chwyć gumę za uchwyty i odsuń się, aby napięcie w gumie wzrosło.
3. Wyprostuj i unieś ramiona prosto przed siebie. Wskazówka: Ramiona powinny być proste i równoległe do podłogi, a zarazem prostopadłe do tułowia. Stopy powinny być mocno oparte na podłodze rozstawione na szerokość barków. To będzie pozycja startowa.
4. Robiąc wydech, przesuwaj ramiona na boki i do tyłu. Trzymaj ramiona wyprostowane i równoległe do podłogi. Kontynuuj ruch, aż ramiona będą wyciągnięte na boki.
5. Po pauzie wróć do pozycji początkowej, robiąc wdech.
6. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Back_Flyes_-_With_Bands/0.jpg', 'free_exercise_db'),
  ('backward-drag', 'Ciągnięcie sanek do tyłu', 'Backward Drag', 'motor_coach', 'beginner', array['Strongman', 'Uda'], 'Ćwiczenie siłowe polegające na ciągnięciu obciążonych sanek do tyłu. Rozwija siłę nóg, wytrzymałość i kondycję.', '1. Załaduj sanki pożądanym ciężarem, przymocowując linę lub pasy do sanek, za które możesz się trzymać.
2. Zacznij ćwiczenie, cofając się na zadaną odległość. Pochylając się do tyłu, prostuj nogi, robiąc krótkie kroki, aby poruszać się jak najszybciej.', NULL, 'free-exercise-db/Backward_Drag/0.jpg', 'free_exercise_db'),
  ('backward-medicine-ball-throw', 'Rzut piłką lekarską za głowę', 'Backward Medicine Ball Throw', 'motor_coach', 'beginner', array['Plyometryka', 'Barki'], 'Wybuchowy rzut piłką lekarską nad głowę do tyłu. Rozwija moc całego ciała, szczególnie bioder i pleców.', '1. To ćwiczenie najlepiej wykonywać z partnerem. Jeśli nie masz partnera, piłkę można rzucić i przynieść z powrotem lub rzucić o ścianę.
2. Zacznij, stojąc kilka metrów przed partnerem, obaj patrząc w tym samym kierunku. Zacznij, trzymając piłkę między nogami.
3. Przysiadnij, a następnie gwałtownie odwróć kierunek, dochodząc do pełnego wyprostu, wyrzucając piłkę nad głowę do partnera.
4. Partner może następnie przetoczyć piłkę z powrotem do Ciebie. Powtórz pożądaną liczbę powtórzeń.', NULL, 'free-exercise-db/Backward_Medicine_Ball_Throw/0.jpg', 'free_exercise_db'),
  ('balance-board', 'Balansowanie na desce balansowej', 'Balance Board', 'motor_coach', 'beginner', array['Siłowe', 'Łydki'], 'Ćwiczenie równowagi na specjalnej desce balansowej. Poprawia stabilność, koordynację i czucie głębokie stawów skokowych.', '1. Połóż deskę balansową przed sobą.
2. Wejdź na nią i spróbuj utrzymać równowagę.
3. Utrzymuj równowagę tak długo, jak chcesz.', NULL, 'free-exercise-db/Balance_Board/0.jpg', 'free_exercise_db'),
  ('ball-leg-curl', 'Uginanie nóg z piłką gimnastyczną', 'Ball Leg Curl', 'motor_coach', 'beginner', array['Siłowe', 'Dwugłowe uda'], 'Ćwiczenie na dwugłowe uda z piłką gimnastyczną. W leżeniu na plecach przyciągasz piłkę stopami, zginając kolana.', '1. Zacznij na podłodze, leżąc na plecach ze stopami na piłce.
2. Ustaw piłkę tak, aby gdy nogi są wyprostowane, kostki były na szczycie piłki. To będzie pozycja startowa.
3. Unieś biodra nad ziemię, utrzymując ciężar na łopatkach i stopach.
4. Zegnij kolana, przyciągając piłkę jak najbliżej siebie, napinając dwugłowe uda.
5. Po krótkiej pauzie wróć do pozycji startowej.', NULL, 'free-exercise-db/Ball_Leg_Curl/0.jpg', 'free_exercise_db'),
  ('band-assisted-pull-up', 'Podciąganie z asystą gumy', 'Band Assisted Pull-Up', 'motor_coach', 'beginner', array['Siłowe', 'Najszersze grzbietu'], 'Podciąganie na drążku z pomocą gumy oporowej. Guma zmniejsza obciążenie, ułatwiając naukę podciągania.', '1. Załóż gumę wokół środka drążka do podciągania. Możesz używać różnych gum, aby uzyskać różne poziomy asysty.
2. Pociągnij koniec gumy w dół i wsadź jedno zgięte kolano w pętlę, upewniając się, że nie wyślizgnie się. Złap drążek chwytem średnim lub szerokim. To będzie pozycja startowa.
3. Podciągaj się w górę, napinając najszerszy grzbietu, zginając łokcie. Łokcie powinny być prowadzone do boku. Podciągaj się z przodu, próbując przenieść brodę nad drążek. Unikaj kołysania lub szarpania.
4. Po krótkiej pauzie wróć do pozycji startowej.', NULL, 'free-exercise-db/Band_Assisted_Pull-Up/0.jpg', 'free_exercise_db'),
  ('band-good-morning', 'Dzień dobry z gumą oporową', 'Band Good Morning', 'motor_coach', 'beginner', array['Trójbój', 'Dwugłowe uda'], 'Skłon tułowiu w przód z gumą oporową na karku. Wzmacnia dolne plecy, pośladki i dwugłowe uda.', '1. Używając gumy o długości ok. 104 cm (41 cali), stań na jednym jej końcu, lekko rozstawiając stopy. Zegnij się w biodrach, aby założyć drugi koniec gumy za kark. To będzie pozycja startowa.
2. Trzymając nogi proste, prostuj biodra, aby wrócić do prawie pionowej pozycji.
3. Upewnij się, że nie zaokrąglasz pleców, schodząc z powrotem do pozycji startowej.', NULL, 'free-exercise-db/Band_Good_Morning/0.jpg', 'free_exercise_db'),
  ('band-good-morning-pull-through', 'Dzień dobry z gumą (skłon w przód)', 'Band Good Morning (Pull Through)', 'motor_coach', 'beginner', array['Trójbój', 'Dwugłowe uda'], 'Skłon w przód z gumą oporową założoną za kark, mocowana do słupka. Wzmacnia dolne plecy, pośladki i dwugłowe uda.', '1. Załóż gumę wokół słupka. Stojąc trochę dalej, załóż przeciwległy koniec za kark. Dłonie mogą pomóc utrzymać gumę w pozycji.
2. Zacznij od zgięcia w biodrach, wypychając pośladki jak najdalej do tyłu. Trzymaj plecy płaskie i pochyl się do przodu do około 90 stopni. Kolana powinny być tylko lekko zgięte.
3. Wróć do pozycji startowej, prostując biodra, aby wrócić do pozycji stojącej.', NULL, 'free-exercise-db/Band_Good_Morning_Pull_Through/0.jpg', 'free_exercise_db'),
  ('band-hip-adductions', 'Przywodzenie biodra z gumą', 'Band Hip Adductions', 'motor_coach', 'beginner', array['Siłowe', 'Przywodziciele'], 'Ćwiczenie na przywodziciele uda z gumą oporową. Unosisz nogę na boki i przywodzisz ją do środka, pokonując opór gumy.', '1. Zamocuj gumę wokół solidnego słupka lub innego przedmiotu.
2. Stań lewym bokiem do słupka i wsuń prawą stopę w gumę, tak aby obejmowała kostkę.
3. Stań prosto i trzymaj się słupka, jeśli to potrzebne. To będzie pozycja startowa.
4. Trzymając kolano proste, unieś prawą nogę na bok jak najdalej.
5. Wróć do pozycji startowej i powtórz pożądaną liczbę powtórzeń.
6. Zmień strony.', NULL, 'free-exercise-db/Band_Hip_Adductions/0.jpg', 'free_exercise_db'),
  ('band-pull-apart', 'Rozciąganie gumy przed sobą', 'Band Pull Apart', 'motor_coach', 'beginner', array['Siłowe', 'Barki'], 'Ćwiczenie z gumą oporową na tylne aktony i górną część pleców. Rozciągasz gumę przed klatką piersiową, rozprowadzając ramiona na boki.', '1. Zacznij z ramionami wyprostowanymi przed sobą, trzymając gumę obiema rękami.
2. Rozpocznij ruch wykonując odwrotną rozpiętkę, przesuwając dłonie na boki.
3. Trzymaj łokcie wyprostowane podczas wykonywania ruchu, doprowadzając gumę do klatki piersiowej. Upewnij się, że barki są cofnięte podczas ćwiczenia.
4. Zatrzymaj się chwilę po ukończeniu ruchu, wracając do pozycji startowej pod kontrolą.', NULL, 'free-exercise-db/Band_Pull_Apart/0.jpg', 'free_exercise_db'),
  ('band-skull-crusher', 'Prostowanie ramion z gumą (francuskie wyciskanie)', 'Band Skull Crusher', 'motor_coach', 'beginner', array['Siłowe', 'Triceps'], 'Wyciskanie francuskie z gumą oporową w leżeniu na ławce. Izoluje triceps.', '1. Zamocuj gumę u podstawy stojaka lub ławki. Połóż się na ławce tak, aby guma była w linii Twojej głowy.
2. Chwyć gumę, unosząc łokcie tak, aby ramię było prostopadłe do podłogi. Przy zgiętym łokciu guma powinna znajdować się nad głową. To będzie pozycja startowa.
3. Wyprostuj łokieć, aby wyprostować ramię, trzymając ramię nieruchomo. Zatrzymaj się na szczycie ruchu i wróć do pozycji startowej.', NULL, 'free-exercise-db/Band_Skull_Crusher/0.jpg', 'free_exercise_db'),
  ('barbell-ab-rollout', 'Przetaczanie sztangi (ab rollout)', 'Barbell Ab Rollout', 'motor_coach', 'intermediate', array['Siłowe', 'Brzuch'], 'Zaawansowane ćwiczenie na mięśnie głębokie z obciążoną sztangą w pozycji jak do pompek. Polega na przetaczaniu sztangi w przód i z powrotem.', '1. Do tego ćwiczenia musisz przyjąć pozycję jak do pompek, ale zamiast opierać dłonie na podłodze, będziesz chwycić sztangę olimpijską (obciążoną 2–5 kg z każdej strony). To będzie pozycja startowa.
2. Utrzymując lekkie wygięcie pleców, unieś biodra i przetaczaj sztangę w kierunku stóp, robiąc wydech. Wskazówka: Podczas wykonywania ruchu pośladki powinny się unosić, mięśnie głębokie napięte, a postawa pleców zachowana przez cały czas. Ramiona również powinny pozostawać prostopadłe do podłogi przez cały ruch. Jeśli tego nie zrobisz, będziesz pracował bardziej barkami i plecami niż brzuchem.
3. Po sekundowym spięciu na górze zacznij powoli przetaczać sztangę z powrotem do przodu, do pozycji startowej, robiąc wdech.
4. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Barbell_Ab_Rollout/0.jpg', 'free_exercise_db'),
  ('barbell-ab-rollout-on-knees', 'Przetaczanie sztangi na kolanach', 'Barbell Ab Rollout - On Knees', 'motor_coach', 'advanced', array['Siłowe', 'Brzuch'], 'Wariant przetaczania sztangi na brzuch wykonywany na kolanach. Wzmacnia mięśnie głębokie i core.', '1. Chwyć sztangę olimpijską obciążoną 2–5 kg z każdej strony i uklęknij na podłodze.
2. Połóż sztangę na podłodze przed sobą, tak abyś był na czworakach (jak w pozycji do pompek na kolanach). To będzie pozycja startowa.
3. Powoli przetaczaj sztangę prosto do przodu, rozciągając ciało do prawie prostej pozycji. Wskazówka: Zejdź tak nisko, jak tylko możesz, nie dotykając podłogi ciałem. Wdech w tej fazie ruchu.
4. Po sekundowej pauzie w pozycji rozciągniętej zacznij przyciągać się z powrotem do pozycji startowej, robiąc wydech. Wskazówka: Rób to powoli i trzymaj mięśnie głębokie napięte przez cały czas.', NULL, 'free-exercise-db/Barbell_Ab_Rollout_-_On_Knees/0.jpg', 'free_exercise_db'),
  ('barbell-bench-press-medium-grip', 'Wyciskanie sztangi leżąc (chwytem średnim)', 'Barbell Bench Press - Medium Grip', 'motor_coach', 'beginner', array['Siłowe', 'Klatka piersiowa'], 'Klasyczne wyciskanie sztangi leżąc na płaskiej ławce chwytem średnim. Główne ćwiczenie budujące siłę i masę klatki piersiowej, angażuje też triceps i barki.', '1. Połóż się na płaskiej ławce. Używając średniej szerokości chwytu (taki, który tworzy kąt 90 stopni w środku ruchu między przedramieniem a ramieniem), zdejmij sztangę ze stojaka i trzymaj ją prosto nad sobą z wyprostowanymi ramionami. To będzie pozycja startowa.
2. Z pozycji startowej weź wdech i zacznij powoli schodzić, aż sztanga dotknie środkowej części klatki piersiowej.
3. Po krótkiej pauzie wypchnij sztangę z powrotem do pozycji startowej, robiąc wydech. Skup się na wypychaniu sztangi mięśniami klatki piersiowej. Zablokuj ramiona i ściśnij klatkę piersiową w spiętej pozycji na szczycie ruchu, utrzymaj przez sekundę, a potem zacznij znów powoli schodzić. Wskazówka: Idealnie, opuszczanie ciężaru powinno trwać około dwa razy dłużej niż jego unoszenie.
4. Powtórz ruch zalecaną liczbę powtórzeń.
5. Kiedy skończysz, odłóż sztangę z powrotem na stojak.', NULL, 'free-exercise-db/Barbell_Bench_Press_-_Medium_Grip/0.jpg', 'free_exercise_db'),
  ('barbell-curl', 'Uginanie ramion ze sztangą', 'Barbell Curl', 'motor_coach', 'beginner', array['Siłowe', 'Biceps'], 'Podstawowe ćwiczenie na biceps wykonywane ze sztangą w staniu. Uginasz ramiona, unosząc sztangę do wysokości barków.', '1. Stań z tułowiem wyprostowanym, trzymając sztangę chwytem na szerokość barków. Dłonie powinny być skierowane do przodu, a łokcie blisko tułowia. To będzie pozycja startowa.
2. Trzymając ramiona nieruchomo, ugnij ramiona do przodu, napinając biceps, robiąc wydech. Wskazówka: Powinny poruszać się tylko przedramiona.
3. Kontynuuj ruch, aż biceps będzie całkowicie napięty, a sztanga na wysokości barków. Utrzymaj spiętą pozycję przez sekundę i mocno zaciśnij biceps.
4. Powoli zacznij opuszczać sztangę do pozycji startowej, robiąc wdech.
5. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Barbell_Curl/0.jpg', 'free_exercise_db'),
  ('barbell-curls-lying-against-an-incline', 'Uginanie ramion ze sztangą w oparciu o ławkę skośną', 'Barbell Curls Lying Against An Incline', 'motor_coach', 'beginner', array['Siłowe', 'Biceps'], 'Uginanie ramion ze sztangą stojąc tyłem do ławki skośnej, z ramionami skierowanymi w dół. Silnie izoluje biceps, eliminując możliwość oszukiwania.', '1. Oprzyj się o ławkę skośną, z ramionami trzymającymi sztangę zwisającą w linii poziomej. To będzie pozycja startowa.
2. Trzymając ramiona nieruchomo, ugnij ramiona tak wysoko, jak możesz, zaciskając biceps. Robisz wydech podczas tej fazy ruchu. Wskazówka: Powinny poruszać się tylko przedramiona. Nie kołysz ramionami.
3. Po sekundowym spięciu powoli wróć do pozycji startowej, robiąc wdech. Wskazówka: Upewnij się, że schodzisz aż do samego dołu.
4. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Barbell_Curls_Lying_Against_An_Incline/0.jpg', 'free_exercise_db'),
  ('barbell-deadlift', 'Martwy ciąg ze sztangą', 'Barbell Deadlift', 'motor_coach', 'intermediate', array['Siłowe', 'Dolny odcinek pleców'], 'Jedno z podstawowych ćwiczeń siłowych — podnoszenie sztangi z ziemi do pełnego wyprostu ciała. Buduje całe ciało: plecy, nogi, pośladki i chwyt.', '1. Stań przed obciążoną sztangą.
2. Trzymając plecy maksymalnie prosto, ugnij kolana, pochyl się do przodu i chwyć sztangę średnim (na szerokość barków) chwytem nachwytem. To będzie pozycja startowa ćwiczenia. Wskazówka: Jeśli trudno Ci utrzymać sztangę tym chwytem, zmień chwyt na mieszany lub użyj pasków na nadgarstki.
3. Trzymając sztangę, rozpocznij unoszenie odpychając nogami, jednocześnie prostując tułów do pozycji pionowej, robiąc wydech. W pozycji pionowej wypchnij klatkę piersiową do przodu i napij plecy, cofając łopatki. Pomyśl o tym, jak wyglądają żołnierze stojąc na baczność.
4. Wróć do pozycji startowej, zginając kolana, jednocześnie pochylając tułów do przodu w biodrach, trzymając plecy prosto. Gdy ciężary na sztandze dotkną podłogi, jesteś w pozycji startowej i gotowy do wykonania kolejnego powtórzenia.
5. Wykonaj liczbę powtórzeń przewidzianą w programie.', NULL, 'free-exercise-db/Barbell_Deadlift/0.jpg', 'free_exercise_db'),
  ('barbell-full-squat', 'Przysiad ze sztangą (głęboki)', 'Barbell Full Squat', 'motor_coach', 'intermediate', array['Siłowe', 'Uda'], 'Głęboka wersja przysiadu ze sztangą, schodząca aż do styku ud z łydkami. Najskuteczniejsze ćwiczenie na nogi i pośladki.', '1. To ćwiczenie najlepiej wykonywać w stojaku do przysiadów dla bezpieczeństwa. Na początek ustaw sztangę na stojaku tuż powyżej poziomu barków. Gdy wybierzesz właściwą wysokość i załadujesz sztangę, wsuń się pod nią i oprzyj ją na tylnej części barków (lekko poniżej karku).
2. Chwyć sztangę obiema rękami po bokach i zdejmij ją ze stojaka, najpierw odpychając nogami, a jednocześnie prostując tułów.
3. Odejdź od stojaka i ustaw nogi na średnią szerokość barków z palcami lekko skierowanymi na zewnątrz. Cały czas trzymaj głowę uniesioną i utrzymuj proste plecy. To będzie pozycja startowa.
4. Zacznij powoli opuszczać sztangę, zginając kolana i wysuwając biodra do tyłu, zachowując prostą postawę z głową uniesioną. Schodź, aż dwugłowe uda będą na łydkach. Wdech podczas tej fazy ruchu.
5. Zacznij unośić sztangę robiąc wydech, odpychając podłogę piętą lub środkiem stopy, prostując nogi i biodra, aby wrócić do pozycji startowej.
6. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Barbell_Full_Squat/0.jpg', 'free_exercise_db'),
  ('barbell-glute-bridge', 'Mostek biodrowy ze sztangą', 'Barbell Glute Bridge', 'motor_coach', 'intermediate', array['Trójbój', 'Pośladki'], 'Unoszenie bioder ze sztangą w leżeniu na plecach. Świetne ćwiczenie izolujące pośladki i dwugłowe uda.', '1. Usiądź na ziemi z obciążoną sztangą nad nogami. Gruba sztanga lub osłona na gryfie może znacznie zmniejszyć dyskomfort związany z tym ćwiczeniem. Przetocz sztangę tak, aby była bezpośrednio nad biodrami, i połóż się płasko na podłodze.
2. Rozpocznij ruch odbijając się piętami, prostując biodra pionowo w górę pod sztangę. Twój ciężar powinien być podparty na górnej części pleców i piętach.
3. Wyprostuj się tak wysoko, jak to możliwe, a następnie odwróć ruch, aby wrócić do pozycji startowej.', NULL, 'free-exercise-db/Barbell_Glute_Bridge/0.jpg', 'free_exercise_db'),
  ('barbell-guillotine-bench-press', 'Wyciskanie gilotynowe (sztanga przy szyi)', 'Barbell Guillotine Bench Press', 'motor_coach', 'intermediate', array['Siłowe', 'Klatka piersiowa'], 'Ekstremalne wyciskanie sztangi leżąc, w którym sztangę opuszczasz tuż przy gardle. Mocno rozciąga i angażuje klatkę piersiową — wymaga dużej ostrożności.', '1. Używając średniej szerokości chwytu (takiego, który tworzy kąt 90 stopni w środku ruchu między przedramieniem a ramieniem), zdejmij sztangę ze stojaka i trzymaj ją prosto nad szyją z wyprostowanymi ramionami. To będzie pozycja startowa.
2. Biorąc wdech, opuszczaj sztangę powoli, aż znajdzie się około 2–3 cm od szyi.
3. Po sekundowej pauzie wróć sztangą do pozycji startowej robiąc wydech, wypychając sztangę mięśniami klatki piersiowej. Zablokuj ramiona i ściśnij klatkę piersiową w spiętej pozycji, utrzymaj przez sekundę, a potem zacznij znów powoli schodzić. Opuszczanie powinno trwać co najmniej dwa razy dłużej niż unoszenie.
4. Powtórz ruch zalecaną liczbę powtórzeń.
5. Kiedy skończysz, odłóż sztangę z powrotem na stojak.', NULL, 'free-exercise-db/Barbell_Guillotine_Bench_Press/0.jpg', 'free_exercise_db'),
  ('barbell-hack-squat', 'Hack przysiad ze sztangą', 'Barbell Hack Squat', 'motor_coach', 'intermediate', array['Siłowe', 'Uda'], 'Przysiad ze sztangą trzymaną za plecami. Wzmacnia nogi, szczególnie czworogłowe uda, odciążając kręgosłup mniej niż klasyczny przysiad.', '1. Stań prosto trzymając sztangę za sobą na wyciągniętych ramionach, ze stopami na szerokość barków. Wskazówka: Najlepszy jest chwyt na szerokość barków z dłońmi skierowanymi do tyłu. Do tego ćwiczenia możesz użyć owinięć na nadgarstki dla lepszego chwytu. To będzie pozycja startowa.
2. Trzymając głowę i wzrok uniesione, a plecy proste, przysiadnij, aż górna część ud będzie równoległa do podłogi. Wdech podczas powolnego schodzenia.
3. Odpychając głównie piętą stopy i zaciskając uda, wracaj w górę robiąc wydech.
4. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Barbell_Hack_Squat/0.jpg', 'free_exercise_db'),
  ('barbell-hip-thrust', 'Hip thrust ze sztangą (unoszenie bioder)', 'Barbell Hip Thrust', 'motor_coach', 'intermediate', array['Trójbój', 'Pośladki'], 'Unoszenie bioder ze sztangą, z górną częścią pleców opartą o ławkę. Jedno z najskuteczniejszych ćwiczeń na pośladki.', '1. Usiądź na ziemi z ławką bezpośrednio za Tobą. Masz obciążoną sztangę nad nogami. Gruba sztanga lub osłona na gryfie może znacznie zmniejszyć dyskomfort związany z tym ćwiczeniem.
2. Przetocz sztangę tak, aby była bezpośrednio nad biodrami, i oprzyj się plecami o ławkę tak, aby łopatki były blisko jej górnej krawędzi.
3. Rozpocznij ruch odbijając się stopami, prostując biodra pionowo w górę pod sztangę. Twój ciężar powinien być podparty na łopatkach i stopach. Wyprostuj się tak wysoko, jak to możliwe, a następnie odwróć ruch, aby wrócić do pozycji startowej.', NULL, 'free-exercise-db/Barbell_Hip_Thrust/0.jpg', 'free_exercise_db'),
  ('barbell-incline-bench-press-medium-grip', 'Wyciskanie sztangi na ławce skośnej (chwytem średnim)', 'Barbell Incline Bench Press - Medium Grip', 'motor_coach', 'beginner', array['Siłowe', 'Klatka piersiowa'], 'Wyciskanie sztangi leżąc na ławce skośnej. Angażuje głównie górną część klatki piersiowej oraz barki i triceps.', '1. Połóż się na ławce skośnej. Używając średniej szerokości chwytu (takiego, który tworzy kąt 90 stopni w środku ruchu między przedramieniem a ramieniem), zdejmij sztangę ze stojaka i trzymaj ją prosto nad sobą z wyprostowanymi ramionami. To będzie pozycja startowa.
2. Biorąc wdech, schodź powoli, aż poczujesz sztangę na górnej części klatki piersiowej.
3. Po sekundowej pauzie wróć sztangą do pozycji startowej robiąc wydech, wypychając sztangę mięśniami klatki piersiowej. Zablokuj ramiona w spiętej pozycji, ściśnij klatkę piersiową, utrzymaj przez sekundę, a potem zacznij znów powoli schodzić. Wskazówka: Opuszczanie powinno trwać co najmniej dwa razy dłużej niż unoszenie.
4. Powtórz ruch zalecaną liczbę powtórzeń.
5. Kiedy skończysz, odłóż sztangę z powrotem na stojak.', NULL, 'free-exercise-db/Barbell_Incline_Bench_Press_-_Medium_Grip/0.jpg', 'free_exercise_db'),
  ('barbell-incline-shoulder-raise', 'Unoszenie barków ze sztangą na ławce skośnej', 'Barbell Incline Shoulder Raise', 'motor_coach', 'beginner', array['Siłowe', 'Barki'], 'Ćwiczenie na mięsień zębaty przedni i górną część klatki piersiowej. Wykonujesz je wypychając barki w górę, leżąc na ławce skośnej ze sztangą.', '1. Połóż się na ławce skośnej. Używając średniej szerokości chwytu (lekko szerszego niż szerokość barków), zdejmij sztangę ze stojaka i trzymaj ją prosto nad sobą z wyprostowanymi ramionami. To będzie pozycja startowa.
2. Trzymając ramiona wyprostowane, unieś sztangę, wysuwając łopatki do przodu, unosząc barki nad ławkę, robiąc wydech.
3. Wróć sztangą do pozycji startowej, robiąc wdech.
4. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Barbell_Incline_Shoulder_Raise/0.jpg', 'free_exercise_db'),
  ('barbell-lunge', 'Wykrok ze sztangą', 'Barbell Lunge', 'motor_coach', 'intermediate', array['Siłowe', 'Uda'], 'Wykroki z sztangą na barkach. Buduje nogi i pośladki, poprawia równowagę i stabilność.', '1. To ćwiczenie najlepiej wykonywać w stojaku do przysiadów dla bezpieczeństwa. Na początek ustaw sztangę na stojaku tuż poniżej poziomu barków. Gdy wybierzesz właściwą wysokość i załadujesz sztangę, wsuń się pod nią i oprzyj ją na tylnej części barków (lekko poniżej karku).
2. Chwyć sztangę obiema rękami po bokach i zdejmij ją ze stojaka, najpierw odpychając nogami, a jednocześnie prostując tułów.
3. Odejdź od stojaka i zrób krok w przód prawą nogą, opuszczając biodra w dół, trzymając tułów pionowo i zachowując równowagę. Wdech podczas schodzenia. Uwaga: Nie pozwól, aby kolano wysunęło się poza palce stopy podczas schodzenia, ponieważ wywiera to nadmierne obciążenie na staw kolanowy.
4. Odpychając głównie piętą stopy, wróć do pozycji startowej robiąc wydech.
5. Powtórz ruch zalecaną liczbę powtórzeń, a następnie wykonaj lewą nogą.', NULL, 'free-exercise-db/Barbell_Lunge/0.jpg', 'free_exercise_db'),
  ('barbell-rear-delt-row', 'Wiosłowanie sztangą na tylne aktony', 'Barbell Rear Delt Row', 'motor_coach', 'beginner', array['Siłowe', 'Barki'], 'Wiosłowanie sztangą w pochyleniu z rozstawionymi łokciami. Ukierunkowane na tylne aktony i górną część pleców.', '1. Stań prosto trzymając sztangę szerokim (szerszym niż szerokość barków) chwytem nachwytem (dłonie skierowane w stronę ciała).
2. Lekko ugnij kolana i pochyl się do przodu, zachowując naturalne wygięcie pleców. Pozwól ramionom zwisać przed Tobą, trzymając sztangę. Gdy tułów będzie równoległy do podłogi, rozstaw łokcie na boki i od ciała. Wskazówka: Tułów i ramiona powinny przypominać literę "T". Teraz jesteś gotowy, aby rozpocząć ćwiczenie.
3. Trzymając ramiona prostopadle do tułowia, przyciągnij sztangę w górę w kierunku górnej części klatki piersiowej, zaciskając tylne aktony i robiąc wydech. Wskazówka: Wykonane poprawnie, to ćwiczenie powinno przypominać odwrotność wyciskania leżąc. Powstrzymaj się też od używania bicepsa do pracy. Skup się na tylnych aktonach; ramiona powinny działać jedynie jako haki.
4. Powoli wróć do pozycji początkowej, robiąc wdech.
5. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Barbell_Rear_Delt_Row/0.jpg', 'free_exercise_db'),
  ('barbell-rollout-from-bench', 'Przetaczanie sztangi z ławki', 'Barbell Rollout from Bench', 'motor_coach', 'intermediate', array['Siłowe', 'Brzuch'], 'Zaawansowane przetaczanie sztangi wykonywane w klęku na ławce. Bardzo silnie angażuje mięśnie głębokie.', '1. Połóż obciążoną sztangę na ziemi, przy końcu ławki. Uklęknij obiema nogami na ławce i złap sztangę chwytem średnim lub wąskim. To będzie pozycja startowa.
2. Aby rozpocząć, prostuj biodra, powoli przetaczając sztangę do przodu. Podczas przetaczania zginaj bark, aby przetoczyć sztangę ponad głowę. Upewnij się, że ramiona pozostają wyprostowane przez cały ruch.
3. Gdy sztanga zostanie przesunięta tak daleko do przodu, jak to możliwe, wróć do pozycji startowej.', NULL, 'free-exercise-db/Barbell_Rollout_from_Bench/0.jpg', 'free_exercise_db'),
  ('barbell-seated-calf-raise', 'Wspięcia na palce siedząc ze sztangą', 'Barbell Seated Calf Raise', 'motor_coach', 'beginner', array['Siłowe', 'Łydki'], 'Wspięcia na palce w siadzie ze sztangą na udach. Izoluje mięśnie łydek (między innyme brzuścem).', '1. Postaw klocek (podest) około 30 cm przed płaską ławką.
2. Usiądź na ławce i umieść przedstopie na klocku.
3. Pozwól komuś położyć sztangę na Twoich udach około 7 cm nad kolanami i przytrzymać ją tam. To będzie pozycja startowa.
4. Unoś się na palcach tak wysoko, jak to możliwe, zaciskając łydki i robiąc wydech.
5. Po sekundowym spięciu powoli wróć do pozycji startowej. Wskazówka: Aby uzyskać maksymalne korzyści, rozciągnij łydki jak najdalej.
6. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Barbell_Seated_Calf_Raise/0.jpg', 'free_exercise_db'),
  ('barbell-shoulder-press', 'Wyciskanie sztangi nad głowę siedząc', 'Barbell Shoulder Press', 'motor_coach', 'intermediate', array['Siłowe', 'Barki'], 'Wyciskanie sztangi nad głowę w siadzie z podparciem pleców. Podstawowe ćwiczenie budujące masę i siłę barków.', '1. Usiądź na ławce z podparciem pleców w stojaku do przysiadów. Ustaw sztangę na wysokości tuż powyżej głowy. Chwyć sztangę chwytem nachwytem (dłonie skierowane do przodu).
2. Po złapaniu sztangi właściwą szerokością chwytu unieś ją nad głowę, blokując ramiona. Zatrzymaj ją na wysokości barków, lekko przed głową. To jest Twoja pozycja startowa.
3. Opuszczaj sztangę powoli do barków, biorąc wdech.
4. Unoś sztangę z powrotem do pozycji startowej, robiąc wydech.
5. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Barbell_Shoulder_Press/0.jpg', 'free_exercise_db'),
  ('barbell-shrug', 'Szrusgi ze sztangą (unoszenie barków)', 'Barbell Shrug', 'motor_coach', 'beginner', array['Siłowe', 'Czworoboczne'], 'Unoszenie barków ze sztangą w dłoniach. Proste i skuteczne ćwiczenie na mięsień czworoboczny grzbietu (trapez).', '1. Stań prosto ze stopami na szerokość barków, trzymając sztangę obiema rękami przed sobą chwytem nachwytem (dłonie skierowane do ud). Wskazówka: Dłonie powinny być nieco szerzej niż szerokość barków. Możesz użyć owinięć na nadgarstki dla lepszego chwytu. To będzie pozycja startowa.
2. Unoś barki jak najwyżej, robiąc wydech, i utrzymaj spięcie przez sekundę. Wskazówka: Powstrzymaj się od prób unoszenia sztangi za pomocą bicepsów.
3. Powoli wróć do pozycji startowej, robiąc wdech.
4. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Barbell_Shrug/0.jpg', 'free_exercise_db'),
  ('barbell-shrug-behind-the-back', 'Szrusgi ze sztangą za plecami', 'Barbell Shrug Behind The Back', 'motor_coach', 'beginner', array['Siłowe', 'Czworoboczne'], 'Wariant szrusgów ze sztangą trzymaną za plecami. Nieco inny kąt pracy mięśnia czworobocznego grzbietu.', '1. Stań prosto ze stopami na szerokość barków, trzymając sztangę obiema rękami za plecami chwytem nachwytem (dłonie skierowane do tyłu). Wskazówka: Dłonie powinny być nieco szerzej niż szerokość barków. Możesz użyć owinięć na nadgarstki dla lepszego chwytu. To będzie pozycja startowa.
2. Unoś barki jak najwyżej, robiąc wydech, i utrzymaj spięcie przez sekundę. Wskazówka: Powstrzymaj się od prób unoszenia sztangi za pomocą bicepsów. Ramiona powinny pozostać wyciągnięte przez cały czas.
3. Powoli wróć do pozycji startowej, robiąc wdech.
4. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Barbell_Shrug_Behind_The_Back/0.jpg', 'free_exercise_db'),
  ('barbell-side-bend', 'Skłony boczne ze sztangą', 'Barbell Side Bend', 'motor_coach', 'beginner', array['Siłowe', 'Brzuch'], 'Skłony na boki ze sztangą na barkach. Wzmacniają mięśnie skośne brzucha i dolne plecy.', '1. Stań prosto, trzymając sztangę umieszczoną na tylnej części barków (lekko poniżej karku). Stopy powinny być rozstawione na szerokość barków. To będzie pozycja startowa.
2. Trzymając plecy proste, a głowę uniesioną, zegnij się tylko w pasie w prawo tak daleko, jak to możliwe. Wdech podczas skłonu na bok. Potem zatrzymaj się na sekundę i wracaj do pozycji startowej robiąc wydech. Wskazówka: Trzymaj resztę ciała nieruchomo.
3. Teraz powtórz ruch, ale skłaniając się w lewo. Zatrzymaj się na sekundę i wróć do pozycji startowej.
4. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Barbell_Side_Bend/0.jpg', 'free_exercise_db'),
  ('barbell-side-split-squat', 'Przysiad bokiem ze sztangą (side split squat)', 'Barbell Side Split Squat', 'motor_coach', 'beginner', array['Siłowe', 'Uda'], 'Przysiad w szerokim rozkroku na bok ze sztangą na barkach. Rozciąga przywodziciele i wzmacnia nogi.', '1. Stań prosto, trzymając sztangę umieszczoną na tylnej części barków (lekko poniżej karku). Stopy powinny być rozstawione szeroko, ze stopą nogi prowadzącej skierowaną na zewnątrz. To będzie pozycja startowa.
2. Opuść ciało w stronę nogi z obróconą stopą, zginając kolano i biodro nogi prowadzącej, trzymając przeciwną nogę tylko lekko ugiętą. Wdech podczas opuszczania ciała.
3. Wróć do pozycji startowej, prostując biodro i kolano nogi prowadzącej. Robisz wydech podczas tego ruchu.
4. Po wykonaniu zalecanej liczby powtórzeń powtórz ruch drugą nogą.', NULL, 'free-exercise-db/Barbell_Side_Split_Squat/0.jpg', 'free_exercise_db'),
  ('barbell-squat', 'Przysiad ze sztangą', 'Barbell Squat', 'motor_coach', 'beginner', array['Siłowe', 'Uda'], 'Król wszystkich ćwiczeń siłowych — przysiad ze sztangą na barkach. Buduje nogi, pośladki i całą siłę ciała.', '1. To ćwiczenie najlepiej wykonywać w stojaku do przysiadów dla bezpieczeństwa. Na początek ustaw sztangę na stojaku tuż poniżej poziomu barków. Gdy wybierzesz właściwą wysokość i załadujesz sztangę, wsuń się pod nią i oprzyj ją na tylnej części barków (lekko poniżej karku).
2. Chwyć sztangę obiema rękami po bokach i zdejmij ją ze stojaka, najpierw odpychając nogami, a jednocześnie prostując tułów.
3. Odejdź od stojaka i ustaw nogi na średnią szerokość barków z palcami lekko skierowanymi na zewnątrz. Cały czas trzymaj głowę uniesioną i utrzymuj proste plecy. To będzie pozycja startowa. (Uwaga: W tym opisie używamy średniej postawy opisanej powyżej, która celuje w ogólny rozwój; jednak możesz wybrać dowolną z trzech postaw omówionych w sekcji o ustawieniu stóp.)
4. Zacznij powoli opuszczać sztangę, zginając kolana i biodra, zachowując prostą postawę z głową uniesioną. Schodź, aż kąt między udami a łydkami stanie się nieznacznie mniejszy niż 90 stopni. Wdech podczas tej fazy ruchu. Wskazówka: Jeśli wykonałeś ćwiczenie poprawnie, przednia część kolan powinna tworzyć wyimaginowaną linię prostą z palcami stóp, prostopadłą do frontu. Jeśli Twoje kolana przekraczają tę linię (jeśli są dalej niż palce stóp), to wywierasz nadmierne obciążenie na kolano i ćwiczenie zostało wykonane niepoprawnie.
5. Zacznij unośić sztangę robiąc wydech, odpychając podłogę piętą stopy, ponownie prostując nogi, aby wrócić do pozycji startowej.
6. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Barbell_Squat/0.jpg', 'free_exercise_db'),
  ('barbell-squat-to-a-bench', 'Przysiad ze sztangą do ławki', 'Barbell Squat To A Bench', 'motor_coach', 'advanced', array['Siłowe', 'Uda'], 'Przysiad ze sztangą z siadaniem na ławkę lub skrzynię. Pomaga nauczyć się cofać biodra i osiągać właściwą głębokość przysiadu.', '1. To ćwiczenie najlepiej wykonywać w stojaku do przysiadów dla bezpieczeństwa. Na początek postaw płaską ławkę lub skrzynię za sobą. Płaska ławka służy do nauki cofania bioder i osiągania głębokości.
2. Następnie ustaw sztangę na stojaku najlepiej dopasowanym do Twojego wzrostu. Gdy wybierzesz właściwą wysokość i załadujesz sztangę, wsuń się pod nią i oprzyj ją na tylnej części barków (lekko poniżej karku).
3. Chwyć sztangę obiema rękami po bokach i zdejmij ją ze stojaka, najpierw odpychając nogami, a jednocześnie prostując tułów.
4. Odejdź od stojaka i ustaw nogi na średnią szerokość barków z palcami lekko skierowanymi na zewnątrz. Cały czas trzymaj głowę uniesioną, ponieważ patrzenie w dół zaburzy równowagę, i utrzymuj proste plecy. To będzie pozycja startowa. (Uwaga: W tym opisie używamy średniej postawy opisanej powyżej, która celuje w ogólny rozwój; jednak możesz wybrać dowolną z trzech postaw omówionych w sekcji o ustawieniu stóp.)
5. Zacznij powoli opuszczać sztangę, zginając kolana i cofając biodra, zachowując prostą postawę z głową uniesioną. Schodź, aż lekko dotkniesz ławki za sobą. Wdech podczas tej fazy ruchu. Wskazówka: Jeśli wykonałeś ćwiczenie poprawnie, przednia część kolan powinna tworzyć wyimaginowaną linię prostą z palcami stóp, prostopadłą do frontu. Jeśli Twoje kolana przekraczają tę linię (jeśli są dalej niż palce stóp), to wywierasz nadmierne obciążenie na kolano i ćwiczenie zostało wykonane niepoprawnie.
6. Zacznij unośić sztangę robiąc wydech, odpychając podłogę piętą stopy, prostując nogi i biodra, aby wrócić do pozycji startowej.
7. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Barbell_Squat_To_A_Bench/0.jpg', 'free_exercise_db'),
  ('barbell-step-ups', 'Wejścia na podwyższenie ze sztangą', 'Barbell Step Ups', 'motor_coach', 'intermediate', array['Siłowe', 'Uda'], 'Wejścia na platformę lub skrzynię ze sztangą na barkach. Buduje nogi i pośladki, poprawia stabilność i równowagę.', '1. Stań prosto, trzymając sztangę umieszczoną na tylnej części barków (lekko poniżej karku) i stań wyprostowany przed podwyższoną platformą (np. taką, jaka używa się do asekuracji za płaską ławką). To jest Twoja pozycja startowa.
2. Połóż prawą stopę na podwyższonej platformie. Wejdź na platformę, prostując biodro i kolano prawej nogi. Używaj głównie pięty, aby unieść resztę ciała do góry i połóż stopę lewej nogi również na platformie. Robisz wydech podczas wykonywania siły potrzebnej do wejścia na górę.
3. Zejdź lewą nogą, zginając biodro i kolano prawej nogi, biorąc wdech. Wróć do pierwotnej pozycji stojącej, stawiając prawą stopę obok lewej w pozycji początkowej.
4. Powtórz prawą nogą zalecaną liczbę powtórzeń, a następnie wykonaj lewą nogą.', NULL, 'free-exercise-db/Barbell_Step_Ups/0.jpg', 'free_exercise_db'),
  ('barbell-walking-lunge', 'Wykroki chodzone ze sztangą', 'Barbell Walking Lunge', 'motor_coach', 'beginner', array['Siłowe', 'Uda'], 'Chodzone wykroki ze sztangą na barkach. Dynamiczne ćwiczenie budujące nogi, pośladki i stabilizatory bioder.', '1. Zacznij stojąc ze stopami rozstawionymi na szerokość barków i sztangą na górnej części pleców.
2. Zrób krok w przód jedną nogą, zginając kolana, aby opuścić biodra. Schodź, aż tylne kolano prawie dotknie ziemi. Postawa powinna pozostać wyprostowana, a przednie kolano powinno pozostawać nad przednią stopą.
3. Odbij się piętą nogi prowadzącej i wyprostuj oba kolana, aby unieść się z powrotem do góry.
4. Zrób krok w przód tylną nogą, powtarzając wykrok na przeciwległej nodze.', NULL, 'free-exercise-db/Barbell_Walking_Lunge/0.jpg', 'free_exercise_db'),
  ('battling-ropes', 'Trening z linami (battling ropes)', 'Battling Ropes', 'motor_coach', 'beginner', array['Siłowe', 'Barki'], 'Intensywne ćwiczenie kondycyjne z ciężkimi linami. Naprzemiennie uderzasz linami o podłogę, budując wytrzymałość i moc ramion.', '1. Do tego ćwiczenia potrzebujesz ciężkiej liny zakotwiczonej w swoim środku 4,5–6 m od Ciebie. Stojąc przed liną, weź jej koniec w każdą rękę z ramionami wyciągniętymi przy bokach. To będzie pozycja startowa.
2. Rozpocznij ruch szybko unosząc jedno ramię do wysokości barków, jak najszybciej, jak potrafisz.
3. Kiedy opuszczasz to ramię do pozycji startowej, unieś przeciwległą stronę.
4. Kontynuuj naprzemienne unoszenie lewego i prawego ramienia, smagając linami w górę i w dół tak szybko, jak potrafisz.', NULL, 'free-exercise-db/Battling_Ropes/0.jpg', 'free_exercise_db'),
  ('bear-crawl-sled-drags', 'Ciągnięcie sanek w chodzie niedźwiedzia', 'Bear Crawl Sled Drags', 'motor_coach', 'beginner', array['Strongman', 'Uda'], 'Ciągnięcie sanek w pozycji na czworakach (chod niedźwiedzia). Intensywne ćwiczenie całego ciała budujące siłę i kondycję.', '1. W uprzęży lub luźnym pasie z ciężarami przymocuj łańcuch z tyłu tak, abyś był odwrócony tyłem do sanek. Schyl się tak, aby dłonie były na ziemi. Plecy powinny być płaskie, a kolana zgięte. To jest pozycja startowa.
2. Zacznij odpychać się nogami, naprzemiennie lewą i prawą. Używaj dłoni do utrzymania równowagi i pomocy w ciągnięciu. Staraj się utrzymać plecy płaskie podczas przemieszczania się na zadany dystans.', NULL, 'free-exercise-db/Bear_Crawl_Sled_Drags/0.jpg', 'free_exercise_db'),
  ('behind-head-chest-stretch', 'Rozciąganie klatki piersiowej z rękami za głową', 'Behind Head Chest Stretch', 'motor_coach', 'advanced', array['Rozciąganie', 'Klatka piersiowa'], 'Rozciąganie klatki piersiowej i barków z partnerem. Ręce za głową, partner delikatnie pogłębia rozciąganie cofając łokcie.', '1. Usiądź wyprostowany na podłodze z partnerem za Tobą.
2. Połóż dłonie za głową i wypchnij łokcie jak najdalej do tyłu. Partner powinien trzymać Twoje łokcie. To będzie pozycja startowa.
3. Delikatnie próbuj pociągnąć łokcie do przodu z dłońmi nadal za głową przez 10 lub więcej sekund. Partner powinien uniemożliwiać poruszanie się łokci.
4. Teraz rozluźnij mięśnie i pozwól partnerowi delikatnie pociągnąć łokcie do tyłu tak daleko, jak jest to dla Ciebie komfortowe. Koniecznie daj partnerowi znać, gdy rozciąganie jest wystarczające, aby uniknąć przeciążenia lub kontuzji.', NULL, 'free-exercise-db/Behind_Head_Chest_Stretch/0.jpg', 'free_exercise_db'),
  ('bench-dips', 'Pompki w oparciu o ławkę (dipy)', 'Bench Dips', 'motor_coach', 'beginner', array['Siłowe', 'Triceps'], 'Proste ćwiczenie na triceps wykonywane w oparciu o ławkę lub krzesło. Opuszczasz ciało zginając łokcie, a potem wracasz do góry.', '1. Do tego ćwiczenia musisz postawić ławkę za swoimi plecami. Z ławką prostopadłą do ciała i patrząc od niej, chwyć krawędź ławki dłońmi całkowicie wyprostowanymi, rozstawionymi na szerokość barków. Nogi będą wyprostowane do przodu, zgięte w biodrach i prostopadłe do tułowia. To będzie pozycja startowa.
2. Powoli opuszczaj ciało, biorąc wdech, zginając łokcie, aż zejdziesz wystarczająco nisko, gdzie kąt między ramieniem a przedramieniem będzie nieznacznie mniejszy niż 90 stopni. Wskazówka: Trzymaj łokcie jak najbliżej ciała przez cały ruch. Przedramiona powinny być zawsze skierowane w dół.
3. Używając tricepsa, aby unieść tułów znowu do góry, podnieś się z powrotem do pozycji startowej.
4. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Bench_Dips/0.jpg', 'free_exercise_db'),
  ('bench-jump', 'Skoki przez ławkę', 'Bench Jump', 'motor_coach', 'intermediate', array['Plyometryka', 'Uda'], 'Plyometryczne skoki przez ławkę lub skrzynię. Rozwijają moc nóg, wybuchowość i kondycję.', '1. Zacznij ze skrzynią lub ławką 30–60 cm przed Tobą. Stań ze stopami rozstawionymi na szerokość barków. To będzie pozycja startowa.
2. Wykonaj krótki przysiad w przygotowaniu do skoku; zamachnij się ramionami za siebie.
3. Wybij z tej pozycji, prostując biodra, kolana i kostki, aby skoczyć jak najwyżej. Zamachnij się ramionami do przodu i w górę.
4. Przeskocz nad ławką, lądując z ugiętymi kolanami, amortyzując uderzenie nogami.
5. Obróć się i stań twarzą w przeciwnym kierunku, a następnie przeskocz z powrotem nad ławką.', NULL, 'free-exercise-db/Bench_Jump/0.jpg', 'free_exercise_db'),
  ('bench-press-powerlifting', 'Wyciskanie leżąc (styl powerliftingowy)', 'Bench Press - Powerlifting', 'motor_coach', 'intermediate', array['Trójbój', 'Triceps'], 'Wyciskanie sztangi leżąc w technice trójboku siłowego — z mostkiem, ściśniętymi łopatkami i napiętym całym ciałem. Pozwala podnieść maksymalny ciężar.', '1. Zacznij od położenia się na ławce, jeśli to możliwe z głową za sztangą. Wsuń stopy pod siebie i wygnij plecy. Używając sztangi do wspomagania podtrzymania ciężaru, oderwij barki od ławki i ściągnij je, zaciskając łopatki razem. Użyj stóp, aby wepchnąć mięśnie czworoboczne w ławkę. Utrzymuj tę napiętą pozycję ciała przez cały ruch.
2. Niezależnie od szerokości chwytu, powinien on zakrywać pierścień na sztandze. Zdejmij sztangę ze stojaka bez wysuwania barków do przodu. Skup się na ściskaniu sztangi i próbie jej rozciągnięcia.
3. Opuszczaj sztangę do dolnej części klatki piersiowej lub górnej części brzucha. Sztanga, nadgarstek i łokieć powinny pozostawać w linii przez cały czas.
4. Zatrzymaj się, gdy sztanga dotknie tułowia, a następnie wypchnij sztangę w górę z jak największą siłą. Łokcie powinny być blisko ciała aż do pełnego wyprostu.', NULL, 'free-exercise-db/Bench_Press_-_Powerlifting/0.jpg', 'free_exercise_db'),
  ('bench-press-with-bands', 'Wyciskanie leżąc z gumami oporowymi', 'Bench Press - With Bands', 'motor_coach', 'beginner', array['Siłowe', 'Klatka piersiowa'], 'Wyciskanie leżąc wykonywane z gumami oporowymi zamocowanymi pod nogami ławki. Guma dodaje rosnący opór podczas unoszenia ciężaru.', '1. Używając płaskiej ławki, zamocuj gumę pod nogą ławki najbliższą Twojej głowy.
2. Gdy guma jest już zamocowana, złap ją za oba uchwyty i połóż się na ławce.
3. Wyprostuj ramiona tak, abyś trzymał uchwyty gumy przed sobą na szerokość barków.
4. Na szerokości barków obróć nadgarstki do przodu tak, aby dłonie były skierowane od Ciebie. To będzie pozycja startowa.
5. Opuszczaj uchwyty powoli, aż łokieć utworzy kąt 90 stopni. Zachowuj pełną kontrolę przez cały czas.
6. Robiąc wydech, unoś uchwyty w górę mięśniami klatki piersiowej. Zablokuj ramiona w spiętej pozycji, ściśnij klatkę piersiową, utrzymaj przez sekundę, a potem zacznij schodzić powoli. Wskazówka: Opuszczanie powinno trwać co najmniej dwa razy dłużej niż unoszenie.
7. Powtórz ruch zalecaną liczbę powtórzeń Twojego programu treningowego.', NULL, 'free-exercise-db/Bench_Press_-_With_Bands/0.jpg', 'free_exercise_db'),
  ('bench-press-with-chains', 'Wyciskanie leżąc z łańcuchami', 'Bench Press with Chains', 'motor_coach', 'advanced', array['Trójbój', 'Triceps'], 'Wyciskanie sztangi leżąd obciążonej dodatkowo łańcuchami. Im wyżej unosisz sztangę, tym więcej ogniw łańcucha unosi się i tym większy opór.', '1. Dopasuj łańcuch prowadzący, skracając go do pożądanej długości. Załóż łańcuchy na tuleje sztangi.
2. Leżąc na ławce, umieść głowę za sztangą, jeśli to możliwe. Wsuń stopy pod siebie i wygnij plecy. Używając sztangi do wspomagania podtrzymania ciężaru, oderwij barki od ławki i ściągnij je, zaciskając łopatki razem. Użyj stóp, aby wepchnąć mięśnie czworoboczne w ławkę. Utrzymuj tę napiętą pozycję ciała przez cały ruch. Niezależnie od szerokości chwytu, powinien on zakrywać pierścień na sztandze.
3. Zdejmij sztangę ze stojaka bez wysuwania barków do przodu. Skup się na ściskaniu sztangi i próbie jej rozciągnięcia. Opuszczaj sztangę do dolnej części klatki piersiowej lub górnej części brzucha. Sztanga, nadgarstek i łokieć powinny pozostawać w linii przez cały czas.
4. Zatrzymaj się, gdy sztanga dotknie tułowia, a następnie wypchnij sztangę w górę z jak największą siłą. Łokcie powinny być blisko ciała aż do pełnego wyprostu.', NULL, 'free-exercise-db/Bench_Press_with_Chains/0.jpg', 'free_exercise_db'),
  ('bench-sprint', 'Sprinty na ławce (szybkie stepy)', 'Bench Sprint', 'motor_coach', 'beginner', array['Plyometryka', 'Uda'], 'Szybkie naprzemienne wstawanie jedną nogą na ławkę lub skrzyń. Ćwiczenie kondycyjno-mocowe angażujące nogi i pośladki.', '1. Stań na ziemi z jedną stopą opartą na ławce lub skrzyni, z piętą blisko krawędzi.
2. Odbij się stopą znajdującą się na ławce, prostując biodro i kolano.
3. Wyląduj przeciwległą stopą na skrzyni, cofając drugą stopę do pozycji startowej.
4. Kontynuuj naprzemianowanie z nogi na nogę, aby wykonać serię.', NULL, 'free-exercise-db/Bench_Sprint/0.jpg', 'free_exercise_db'),
  ('bent-arm-barbell-pullover', 'Przenoszenie sztangi za głowę (pullover) z ugiętymi ramionami', 'Bent-Arm Barbell Pullover', 'motor_coach', 'intermediate', array['Siłowe', 'Najszersze grzbietu'], 'Pullover ze sztangą w leżeniu na ławce, z lekko ugiętymi ramionami. Rozciąga i wzmacnia klatkę piersiową oraz najszerszy grzbietu.', '1. Połóż się na płaskiej ławce ze sztangą chwytem na szerokość barków.
2. Trzymaj sztangę prosto nad klatką piersiową z lekkim zgięciem w ramionach. To będzie pozycja startowa.
3. Utrzymując zgięcie w ramionach, opuszczaj ciężar powoli łukiem za głowę, biorąc wdech, aż poczujesz rozciągnięcie w klatce piersiowej.
4. W tym momencie wróć sztangą do pozycji startowej tym samym łukiem, którym była opuszczana, robiąc wydech podczas tego ruchu.
5. Utrzymaj ciężar w pozycji początkowej przez sekundę i powtórz ruch zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Bent-Arm_Barbell_Pullover/0.jpg', 'free_exercise_db'),
  ('bent-arm-dumbbell-pullover', 'Przenoszenie hantli za głowę (pullover) z ugiętymi ramionami', 'Bent-Arm Dumbbell Pullover', 'motor_coach', 'intermediate', array['Siłowe', 'Klatka piersiowa'], 'Pullover z hantlą w poprzecznej pozycji na ławce. Rozciąga klatkę piersiową i najszerszy grzbietu.', '1. Postaw hantlę pionowo na płaskiej ławce.
2. Upewniwszy się, że hantla jest bezpiecznie umieszczona na szczycie ławki, połóż się poprzecznie na ławce (tułów w poprzek, tworząc krzyż) tylko z barkami na jej powierzchni. Biodra powinny być poniżej ławki, a nogi zgięte ze stopami mocno na podłodze. Głowa również będzie poza ławką.
3. Chwyć hantlę obiema rękami i trzymaj ją prosto nad klatką piersiową z lekkim zgięciem w ramionach. Obie dłonie powinny dociskać do spodu jednej z stron hantli. To będzie pozycja startowa. Ostrzeżenie: Zawsze upewnij się, że używana hantla jest bezpieczna. Hantla z luźnymi talerzami może się rozpaść i spaść Ci na twarz.
4. Utrzymując ramiona zablokowane w pozycji zgiętej, opuszczaj ciężar powoli łukiem za głowę, biorąc wdech, aż poczujesz rozciągnięcie w klatce piersiowej.
5. W tym momencie wróć hantlą do pozycji startowej tym samym łukiem, którym była opuszczana, robiąc wydech podczas tego ruchu.
6. Utrzymaj ciężar w pozycji początkowej przez sekundę i powtórz ruch zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Bent-Arm_Dumbbell_Pullover/0.jpg', 'free_exercise_db'),
  ('bent-knee-hip-raise', 'Unoszenie bioder z ugiętymi kolanami', 'Bent-Knee Hip Raise', 'motor_coach', 'beginner', array['Siłowe', 'Brzuch'], 'Ćwiczenie brzucha w leżeniu na plecach — przyciągasz kolana do klatki piersiowej i unosisz biodra. Angażuje dolną część mięśnia prostego brzucha.', '1. Połóż się płasko na podłodze z rękami wzdłuż boków.
2. Teraz ugnij kolana pod kątem około 75 stopni i unieś stopy nad podłogę o około 5 cm.
3. Używając dolnych partií brzucha, przyciągaj kolana do siebie, zachowując kąt zgięcia nóg 75 stopni. Kontynuuj ten ruch, aż uniesiesz biodra nad podłogę, odchylając miednicę do tyłu. Robisz wydech podczas tej fazy ruchu. Wskazówka: Na końcu ruchu kolana będą nad klatką piersiową.
4. Zaciśnij mięśnie brzucha na szczycie ruchu przez sekundę, a następnie wróć powoli do pozycji startowej, robiąc wdech. Wskazówka: Utrzymuj kontrolowany ruch przez cały czas.
5. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Bent-Knee_Hip_Raise/0.jpg', 'free_exercise_db'),
  ('bent-over-barbell-row', 'Wiosłowanie sztangą w pochyleniu', 'Bent Over Barbell Row', 'motor_coach', 'beginner', array['Siłowe', 'Środek pleców'], 'Podstawowe wiosłowanie sztangą w pochyleniu tułowia. Buduje masę i grubość pleców — najszerszy grzbietu, równoległoboczny i bicepsy.', '1. Trzymając sztangę chwytem nachwytem (dłonie skierowane w dół), lekko ugnij kolana i pochyl tułów do przodu, zginając się w pasie, trzymając plecy proste, aż będzie prawie równoległa do podłogi. Wskazówka: Upewnij się, że trzymasz głowę uniesioną. Sztanga powinna zwisać bezpośrednio przed Tobą, a ramiona wisieć prostopadle do podłogi i tułowia. To jest pozycja startowa.
2. Teraz, utrzymując tułów nieruchomo, zrób wydech i przyciągnij sztangę do siebie. Trzymaj łokcie blisko ciała i używaj przedramion tylko do trzymania ciężaru. W spiętej pozycji na górze zaciśnij mięśnie pleców i utrzymaj krótką pauzę.
3. Potem weź wdech i powoli opuść sztangę z powrotem do pozycji startowej.
4. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Bent_Over_Barbell_Row/0.jpg', 'free_exercise_db'),
  ('bent-over-dumbbell-rear-delt-raise-with-head-on-bench', 'Unoszenie hantli na tylne aktony z głową na ławce', 'Bent Over Dumbbell Rear Delt Raise With Head On Bench', 'motor_coach', 'beginner', array['Siłowe', 'Barki'], 'Unoszenie hantli na boki w pochylnej pozycji z czołem opartym o ławkę. Izoluje tylne aktony, eliminując kołysanie tułowia.', '1. Stań prosto trzymając hantlę w każdej ręce, z ławką skośną przed sobą.
2. Trzymając plecy proste i zachowując ich naturalne wygięcie, pochyl się do przodu, aż czoło dotknie ławki. Pozwól ramionom zwisać przed Tobą prostopadle do ziemi. Dłonie powinny być skierowane ku sobie, a tułów równoległy do podłogi. To będzie pozycja startowa.
3. Utrzymując tułów pochylony i nieruchomy, a ramiona proste z lekkim zgięciem w łokciach, unieś hantle prosto na boki, aż oba ramiona będą równoległe do podłogi. Robisz wydech unosząc ciężary. Ostrzeżenie: Unikaj kołysania tułowiem lub przyciągania ramion do tyłu zamiast na boki.
4. Po sekundowym spięciu na górze powoli opuść hantle z powrotem do pozycji startowej.
5. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Bent_Over_Dumbbell_Rear_Delt_Raise_With_Head_On_Bench/0.jpg', 'free_exercise_db'),
  ('bent-over-low-pulley-side-lateral', 'Wznosy na boki z dolnego wyciągu w pochyleniu', 'Bent Over Low-Pulley Side Lateral', 'motor_coach', 'beginner', array['Siłowe', 'Barki'], 'Unoszenie ramienia na bok z linką dolnego wyciągu, w pozycji pochylonej. Izoluje boczną część barków (aktony).', '1. Wybierz ciężar i chwyć uchwyt dolnego wyciągu prawą ręką.
2. Zegnij się w pasie, aż tułów będzie prawie równoległy do podłogi. Nogi powinny być lekko ugięte, a lewa dłoń oparta na lewym udzie. Prawe ramię powinno zwisać z barku przed Tobą, z lekkim zgięciem w łokciu. To będzie pozycja startowa.
3. Unieś prawe ramię, z łokciem lekko zgiętym, na bok, aż ramię będzie równoległe do podłogi i w linii prawego ucha. Wykonujesz wydech podczas tego kroku.
4. Powoli opuść ciężar z powrotem do pozycji startowej, biorąc wdech.
5. Powtórz zalecaną liczbę powtórzeń i powtórz ruch drugą ręką.', NULL, 'free-exercise-db/Bent_Over_Low-Pulley_Side_Lateral/0.jpg', 'free_exercise_db'),
  ('bent-over-one-arm-long-bar-row', 'Wiosłowanie t-bar jednorącz w pochyleniu', 'Bent Over One-Arm Long Bar Row', 'motor_coach', 'beginner', array['Siłowe', 'Środek pleców'], 'Wiosłowanie sztangą t-bar jedną ręką w pochyleniu. Silnie buduje plecy z jednoczesnym rozciągnięciem najszerszego grzbietu.', '1. Załaduj ciężar na jeden koniec sztangi olimpijskiej. Upewnij się, że albo umieszczasz drugi koniec sztangi w narożniku dwóch ścian, albo położysz ciężki przedmiot na ziemi, aby sztanga nie mogła się przesunąć do tyłu.
2. Pochyl się do przodu, aż tułów będzie tak blisko równoległości do podłogi, jak możesz, i utrzymuj kolana lekko zgięte.
3. Teraz złap sztangę jedną ręką tuż za talerzami po stronie z ciężarem, a drugą dłoń oprzyj na kolanie. To będzie pozycja startowa.
4. Przyciągaj sztangę prosto w górę z łokciem przy ciele (aby zmaksymalizować pracę pleców), aż talerze dotkną dolnej części klatki piersiowej. Zaciskaj mięśnie pleców unosząc ciężar i utrzymaj sekundę na szczycie ruchu. Robisz wydech unosząc ciężar. Wskazówka: Nie pozwól na żadne kołysanie tułowia. Powinna poruszać się tylko ręka.
5. Powoli opuść sztangę do pozycji startowej, uzyskując dobre rozciągnięcie najszerszych grzbietu. Wskazówka: Nie pozwól talerzom dotknąć podłogi. Aby zapewnić najlepszy zakres ruchu, zalecam używanie małych talerzy (ok. 10–12 kg), a nie większych (typu 15–20 kg).
6. Powtórz zalecaną liczbę powtórzeń i zmień rękę.', NULL, 'free-exercise-db/Bent_Over_One-Arm_Long_Bar_Row/0.jpg', 'free_exercise_db'),
  ('bent-over-two-arm-long-bar-row', 'Wiosłowanie t-bar oburącz w pochyleniu', 'Bent Over Two-Arm Long Bar Row', 'motor_coach', 'intermediate', array['Siłowe', 'Środek pleców'], 'Wiosłowanie sztangą t-bar dwiema rękami w pochyleniu. Mocne ćwiczenie na całe plecy, szczególnie najszerszy grzbietu.', '1. Załaduj ciężar na jeden koniec sztangi olimpijskiej. Upewnij się, że albo umieszczasz drugi koniec sztangi w narożniku dwóch ścian, albo położysz ciężki przedmiot na ziemi, aby sztanga nie mogła się przesunąć do tyłu.
2. Pochyl się do przodu, aż tułów będzie tak blisko równoległości do podłogi, jak możesz, i utrzymuj kolana lekko zgięte.
3. Teraz złap sztangę obiema rękami tuż za talerzami po stronie z ciężarem. To będzie pozycja startowa.
4. Przyciągaj sztangę prosto w górę z łokciami przy ciele (aby zmaksymalizować pracę pleców), aż talerze dotkną dolnej części klatki piersiowej. Zaciskaj mięśnie pleców unosząc ciężar i utrzymaj sekundę na szczycie ruchu. Robisz wydech unosząc ciężar. Wskazówka: Możesz użyć strzemienia lub podwójnego uchwytu do linek zahaczając go pod końcem sztangi.
5. Powoli opuść sztangę do pozycji startowej, uzyskując dobre rozciągnięcie najszerszych grzbietu. Wskazówka: Nie pozwól talerzom dotknąć podłogi. Aby zapewnić najlepszy zakres ruchu, zalecam używanie małych talerzy (ok. 10–12 kg), a nie większych (typu 15–20 kg).
6. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Bent_Over_Two-Arm_Long_Bar_Row/0.jpg', 'free_exercise_db'),
  ('bent-over-two-dumbbell-row', 'Wiosłowanie hantlami w pochyleniu', 'Bent Over Two-Dumbbell Row', 'motor_coach', 'beginner', array['Siłowe', 'Środek pleców'], 'Wiosłowanie dwiema hantlami w pochyleniu tułowia. Buduje masę i grubość pleców.', '1. Z hantlą w każdej ręce (dłonie skierowane w stronę tułowia), lekko ugnij kolana i pochyl tułów do przodu, zginając się w pasie; podczas pochylenia upewnij się, że trzymasz plecy proste, aż będzie prawie równoległa do podłogi. Wskazówka: Upewnij się, że trzymasz głowę uniesioną. Ciężary powinny zwisać bezpośrednio przed Tobą, a ramiona wisieć prostopadle do podłogi i tułowia. To jest pozycja startowa.
2. Utrzymując tułów nieruchomo, unoś hantle na boki (robiąc wydech), trzymając łokcie blisko ciała (nie wykonuj żadnej siły przedramieniem poza trzymaniem ciężarów). W spiętej pozycji na górze zaciśnij mięśnie pleców i utrzymaj sekundę.
3. Powoli opuść ciężary ponownie do pozycji startowej, biorąc wdech.
4. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Bent_Over_Two-Dumbbell_Row/0.jpg', 'free_exercise_db'),
  ('bent-over-two-dumbbell-row-with-palms-in', 'Wiosłowanie hantlami w pochyleniu (chwyt neutralny)', 'Bent Over Two-Dumbbell Row With Palms In', 'motor_coach', 'beginner', array['Siłowe', 'Środek pleców'], 'Wiosłowanie dwiema hantlami w pochyleniu z chwytem neutralnym (dłonie ku sobie). Angażuje środkowe partie pleców, mocno ściąga łopatki.', '1. Z hantlą w każdej ręce (dłonie skierowane ku sobie), lekko ugnij kolana i pochyl tułów do przodu, zginając się w pasie, trzymając plecy proste, aż będzie prawie równoległa do podłogi. Wskazówka: Upewnij się, że trzymasz głowę uniesioną. Ciężary powinny zwisać bezpośrednio przed Tobą, a ramiona wisieć prostopadle do podłogi i tułowia. To jest pozycja startowa.
2. Utrzymując tułów nieruchomo, unoś hantle na boki robiąc wydech, ściągaając łopatki razem. W spiętej pozycji na górze zaciśnij mięśnie pleców i utrzymaj sekundę.
3. Powoli opuść ciężary ponownie do pozycji startowej, biorąc wdech.
4. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Bent_Over_Two-Dumbbell_Row_With_Palms_In/0.jpg', 'free_exercise_db'),
  ('bent-press', 'Press bent press z kettlebell', 'Bent Press', 'motor_coach', 'advanced', array['Siłowe', 'Brzuch'], 'Klasyczne ćwiczenie siłowe z kettlebellem — wyciskanie nad głowę z jednoczesnym skłonem tułowia na bok. Rozwija barki i stabilność całego ciała.', '1. Wykonaj wybur (clean) kettlebella na ramię. Wykonaj wybur, prostując nogi i biodra, unosząc kettlebell w kierunku barku. Nadgarstek powinien się obracać podczas tego ruchu. To będzie pozycja startowa.
2. Zacznij od pochylenia się na bok przeciwny do strony kettlebella, kontynuując, aż będziesz mógł dotknąć ziemi wolną ręką, trzymając wzrok na kettlebellu. Podczas tego ruchu wyciskaj ciężar pionowo, prostując łokieć, trzymając ramię prostopadłe do ziemi.
3. Wróć do pozycji pionowej, z kettlebellem nad głową. Odetgnij kettlebell do barku i powtórz pożądaną liczbę powtórzeń.', NULL, 'free-exercise-db/Bent_Press/0.jpg', 'free_exercise_db'),
  ('bicycling', 'Jazda na rowerze', 'Bicycling', 'motor_coach', 'beginner', array['Cardio', 'Uda'], 'Klasyczna jazda na rowerze — świetne ćwiczenie aerobowe wzmacniające nogi i poprawiające kondycję.', '1. Na początku usiądź na rowerze i dostosuj wysokość siodełka do swojego wzrostu.', NULL, 'free-exercise-db/Bicycling/0.jpg', 'free_exercise_db'),
  ('bicycling-stationary', 'Rower stacjonarny', 'Bicycling, Stationary', 'motor_coach', 'beginner', array['Cardio', 'Uda'], 'Trening cardio na rowerze stacjonarnym. Pozwala regulować opór i monitorować tętno oraz spalone kalorie.', '1. Na początku usiądź na rowerze i dostosuj wysokość siodełka do swojego wzrostu.
2. Wybierz żądaną opcję z menu. Może być konieczne rozpoczęcie pedałowania, aby go włączyć. Możesz użyć trybu ręcznego lub wybrać program. Zazwyczaj możesz wprowadzić swój wiek i wagę, aby oszacować ilość spalanych kalorii podczas ćwiczeń. Poziom oporu można zmieniać podczas treningu. Uchwyty mogą służyć do monitorowania tętna, aby pomóc Ci utrzymać odpowiednią intensywność.', NULL, 'free-exercise-db/Bicycling_Stationary/0.jpg', 'free_exercise_db'),
  ('board-press', 'Wyciskanie na deskach (board press)', 'Board Press', 'motor_coach', 'intermediate', array['Trójbój', 'Triceps'], 'Wariant wyciskania leżącego z deskami na klatce piersiowej ograniczającymi zakres ruchu. Buduje siłę w górnej fazie wyciskania i chroni barki.', '1. Zacznij od położenia się na ławce, jeśli to możliwe z głową za sztangą. Od jednej do pięciu desek, wykonanych z desek 5x15 cm, można skręcić razem i przytrzymać przez partnera treningowego, gumami lub po prostu wsunąć pod koszulkę.
2. Wsuń stopy pod siebie i wygnij plecy. Używając sztangi do wspomagania podtrzymania ciężaru, oderwij barki od ławki i ściągnij je, zaciskając łopatki razem. Użyj stóp, aby wepchnąć mięśnie czworoboczne w ławkę. Utrzymuj tę napiętą pozycję ciała przez cały ruch.
3. Możesz użyć standardowego chwytu do wyciskania lub chwytu na szerokość barków, aby skupić się na tricepsie. Zdejmij sztangę ze stojaka bez wysuwania barków do przodu. Sztanga, nadgarstek i łokieć powinny pozostawać w linii przez cały czas. Skup się na ściskaniu sztangi i próbie jej rozciągnięcia.
4. Opuszczaj sztangę na deski, a następnie wypychaj ją w górę z jak największą siłą. Łokcie powinny być blisko ciała aż do pełnego wyprostu.', NULL, 'free-exercise-db/Board_Press/0.jpg', 'free_exercise_db'),
  ('body-tricep-press', 'Prostowanie ramion z drążkiem (masa własnego ciała)', 'Body Tricep Press', 'motor_coach', 'beginner', array['Siłowe', 'Triceps'], 'Prostowanie tricepsa z wykorzystaniem masy własnego ciała i sztangi na stojaku. Opierasz się na drążku, zginając i prostując łokcie.', '1. Ustaw drążek na stojaku na wysokości klatki piersiowej.
2. Stojąc, złap drążek chwytem na szerokość barków i zrób krok lub dwa do tyłu, ze stopami razem i ramionami wyprostowanymi, tak abyś opierał się na drążku. To będzie pozycja startowa.
3. Zacznij od zgięcia łokci, opuszczając ciało w kierunku drążka.
4. Zatrzymaj się, a następnie odwróć ruch prostując łokcie.
5. Aby progresować ponad masę własnego ciała, dodajaj łańcuchy na ramiona.', NULL, 'free-exercise-db/Body_Tricep_Press/0.jpg', 'free_exercise_db'),
  ('body-up', 'Body-up (przejście z deski do pompy)', 'Body-Up', 'motor_coach', 'intermediate', array['Siłowe', 'Triceps'], 'Ćwiczenie łączące deskę z pompką — przechodzisz z podporu na przedramionach do podporu na dłoniach. Wzmacnia mięśnie głębokie, klatkę piersiową i triceps.', '1. Przyjmij pozycję deski na ziemi. Powinieneś podpierać ciężar ciała na palcach i przedramionach, trzymając tułów prosto. Przedramiona powinny być rozstawione na szerokość barków. To będzie pozycja startowa.
2. Mocno dociskając dłonie do ziemi, wyprostuj łokcie, aby unieść ciało od ziemi. Trzymaj tułów sztywno podczas wykonywania ruchu.
3. Powoli opuść przedramiona z powrotem na ziemię, pozwalając łokciom się zgiąć.
4. Powtarzaj.', NULL, 'free-exercise-db/Body-Up/0.jpg', 'free_exercise_db'),
  ('bodyweight-flyes', 'Rozpiętki z masą ciała (na sztangach EZ)', 'Bodyweight Flyes', 'motor_coach', 'intermediate', array['Siłowe', 'Klatka piersiowa'], 'Niecodzienne rozpiętki klatki piersiowej — w podporze na dwóch leżących sztangach EZ rozsuwasz ręcznie sztangi na boki. Klatka pracuje podobnie jak przy rozpiętkach z hantlami.', '1. Ustaw dwie jednakowo obciążone sztangi EZ na ziemi obok siebie. Upewnij się, że mogą się toczyć.
2. Przyjmij pozycję pompek nad sztangami, podpierając ciężar ciała na palcach i dłoniach, z ramionami wyprostowanymi i ciałem prostym.
3. Połóż dłonie na sztangach. To będzie pozycja startowa.
4. Powolnym i kontrolowanym ruchem odsuwaj dłonie od linii środka ciała, tocząc sztangi na boki. Wdech podczas tej fazy ruchu.
5. Po rozsunięciu sztang jak najdalej, wróć do pozycji startowej, przyciągając je z powrotem do siebie. Robisz wydech podczas tego ruchu.', NULL, 'free-exercise-db/Bodyweight_Flyes/0.jpg', 'free_exercise_db'),
  ('bodyweight-mid-row', 'Wiosłowanie masą ciała na drążku', 'Bodyweight Mid Row', 'motor_coach', 'intermediate', array['Siłowe', 'Środek pleców'], 'Wiosłowanie z wykorzystaniem masy własnego ciała na drążku do podciągania. Zwisa z kolanami przy klatce i przyciągasz ciało w górę.', '1. Zacznij od średniego lub szerokiego chwytu na drążku do podciągania, z dłońmi skierowanymi od Ciebie. Z pozycji zwisu przyciągnij kolana do klatki piersiowej, odchylając się do tyłu i przerzucając nogi na swoją stronę drążka. To będzie pozycja startowa.
2. Zaczynając z prostymi ramionami, zegnij łokcie i ściągnij łopatki, aby unieść ciało w górę, aż nogi dotkną drążka do podciągania.
3. Po krótkiej pauzie wróć do pozycji startowej.', NULL, 'free-exercise-db/Bodyweight_Mid_Row/0.jpg', 'free_exercise_db'),
  ('bodyweight-squat', 'Przysiad bez obciążenia (masa ciała)', 'Bodyweight Squat', 'motor_coach', 'beginner', array['Siłowe', 'Uda'], 'Podstawowy przysiad z wykorzystaniem tylko masy własnego ciała. Fundament techniki przysiadu — wzmacnia nogi i pośladki.', '1. Stań ze stopami rozstawionymi na szerokość barków. Możesz położyć dłonie za głową. To będzie pozycja startowa.
2. Rozpocznij ruch zginając kolana i biodra, cofając biodra do tyłu.
3. Schodź do pełnej głębokości, jeśli potrafisz, i szybko odwróć ruch, aż wrócisz do pozycji startowej. Podczas przysiadu trzymaj głowę i klatkę piersiową uniesione, a kolana wypychaj na zewnątrz.', NULL, 'free-exercise-db/Bodyweight_Squat/0.jpg', 'free_exercise_db'),
  ('bodyweight-walking-lunge', 'Wykroki chodzone bez obciążenia', 'Bodyweight Walking Lunge', 'motor_coach', 'beginner', array['Siłowe', 'Uda'], 'Chodzone wykroki z wykorzystaniem tylko masy własnego ciała. Świetne ćwiczenie na nogi i pośladki bez sprzętu.', '1. Zacznij stojąc ze stopami rozstawionymi na szerokość barków i dłońmi na biodrach.
2. Zrób krok w przód jedną nogą, zginając kolana, aby opuścić biodra. Schodź, aż tylne kolano prawie dotknie ziemi. Postawa powinna pozostać wyprostowana, a przednie kolano powinno pozostawać nad przednią stopą.
3. Odbij się piętą nogi prowadzącej i wyprostuj oba kolana, aby unieść się z powrotem do góry.
4. Zrób krok w przód tylną nogą, powtarzając wykrok na przeciwległej nodze.', NULL, 'free-exercise-db/Bodyweight_Walking_Lunge/0.jpg', 'free_exercise_db'),
  ('bosu-ball-cable-crunch-with-side-bends', 'Brzuszki na Bosu z linkami wyciągu i skłonami bocznymi', 'Bosu Ball Cable Crunch With Side Bends', 'motor_coach', 'beginner', array['Siłowe', 'Brzuch'], 'Zaawansowane ćwiczenie brzucha na piłce bosu z linkami wyciągu, zakończone skłonami bocznymi na mięśnie skośne.', '1. Podłącz standardowy uchwyt do każdego ramienia maszyny z linkami i ustaw je w najbardziej dolnej pozycji.
2. Weź piłkę bosu i umieść ją z przodu, na środku maszyny z linkami.
3. Połóż się na piłce bosu z odcinkiem lędźwiowym wygiętym wokół piłki. Twój tył powinien być blisko podłogi, nie dotykając jej.
4. Obiema rękami sięgnij do tyłu i złap uchwyt każdej linki.
5. Ze stopami w szerokiej postawie, wyciągnij ramiona prosto przed siebie i między kolana. Dłonie powinny być na wysokości kolan.
6. Trzymaj ramiona proste i w linii z górnym kątem linki. Unoś tułów ruchem spięcia, nie opuszczając ani nie zginając ramion.
7. Utrzymuj sztywną pozycję z ramionami. Powoli opuszczaj się z powrotem do pozycji startowej z plecami wygiętymi wokół piłki bosu i wydłużonymi mięsniami brzucha.
8. Powtarzaj tę samą serię ruchów aż do upadku mięśniowego.
9. Gdy osiągniesz upadek mięśniowy, trzymaj mięśnie brzucha napięte i unoś tułów do pozycji deski, tak aby plecy były uniesione nad piłką bosu.
10. Opuść ramiona na boki; trzymaj je proste. Zacznij robić naprzemienne skłony boczne; sięgaj do pięt! Ten końcowy ruch skupi się na mięśniach skośnych brzucha.', NULL, 'free-exercise-db/Bosu_Ball_Cable_Crunch_With_Side_Bends/0.jpg', 'free_exercise_db'),
  ('bottoms-up', 'Unoszenie nóg i bioder w leżeniu (bottoms up)', 'Bottoms Up', 'motor_coach', 'beginner', array['Siłowe', 'Brzuch'], 'Ćwiczenie brzucha w leżeniu na plecach — przyciągasz kolana do klatki, a następnie wypychasz nogi w górę unosząc pośladki. Angażuje dolną część brzucha.', '1. Zacznij leżąc na plecach na ziemi. Nogi powinny być proste, a ręce przy bokach. To będzie pozycja startowa.
2. Aby wykonać ruch, przyciągnij kolana do klatki piersiowej, zginając biodra i kolana. Następnie wypchnij nogi prosto nad siebie, tak aby były prostopadłe do ziemi. Obróć i unieś miednicę, aby oderwać pośladki od podłogi.
3. Po krótkiej pauzie wróć do pozycji startowej.', NULL, 'free-exercise-db/Bottoms_Up/0.jpg', 'free_exercise_db'),
  ('bottoms-up-clean-from-the-hang-position', 'Wybur z wisu dołem (bottoms-up clean)', 'Bottoms-Up Clean From The Hang Position', 'motor_coach', 'intermediate', array['Siłowe', 'Przedramiona'], 'Dynamiczne podrzucenie kettlebella na ramię z pozycji wisu, z chwytem dołem. Rozwija moc bioder i siłę chwytu.', '1. Rozpocznij ćwiczenie stojąc wyprostowany z kettlebellem w jednej ręce.
2. Energicznie zamachnij kettlebellem do tyłu, a następnie gwałtownie odwróć ruch. Ściskaj uchwyt kettlebella jak najmocniej i unieś kettlebell do barku.', NULL, 'free-exercise-db/Bottoms-Up_Clean_From_The_Hang_Position/0.jpg', 'free_exercise_db'),
  ('box-jump-multiple-response', 'Skoki na skrzynię (wieloodpowiedziowe)', 'Box Jump (Multiple Response)', 'motor_coach', 'beginner', array['Plyometryka', 'Dwugłowe uda'], 'Plyometryczne skoki na skrzynię lub platformę z natychmiastowym powrotem do pozycji startowej. Rozwija moc i wybuchowość nóg.', '1. Przyjmij rozluźnioną postawę twarzą do skrzyni lub platformy w odległości około długości ramienia. Ramiona powinny być opuszczone wzdłuż ciał, a nogi lekko zgięte.
2. Używając ramion do wspomagania początkowego wybicia, skocz w górę i do przodu, lądując jednocześnie obiema stopami na szczycie skrzyni lub platformy.
3. Natychmiast zeskocz lub opuść się z powrotem na pierwotne miejsce startu; następnie powtórz sekwencję.', NULL, 'free-exercise-db/Box_Jump_Multiple_Response/0.jpg', 'free_exercise_db')
on conflict (slug) do nothing;

insert into public.exercises
  (slug, name, name_en, persona_type, level, categories, short_description, detail_full, common_mistakes, photo_path, source)
values
  ('box-skip', 'Skip A na skrzynie', 'Box Skip', 'motor_coach', 'beginner', array['Plyometryka', 'Dwugłowe uda'], 'Skocznościowe skipy między skrzyniami ustawionymi w rzędzie. Rozwija moc odbicia, koordynację i wybuchowość nóg.', '1. Będziesz potrzebował kilku skrzyń ustawionych w rzędzie około 2,4 m od siebie.
2. Zacznij twarzą do pierwszej skrzyni, z jedną nogą lekko cofniętą za drugą.
3. Odbij się od nogi tylnej, próbując uzyskać jak największą wysokość bioder.
4. Natychmiast po lądowaniu na skrzyni wybierz drugą nogę do przodu i w górę, aby uzyskać wysokość i dystans, wyskakując ze skrzyni. Wyląduj między pierwszymi dwoma skrzyniami na tej samej nodze, która wylądowała na pierwszej skrzyni.
5. Następnie przejdź do następnej skrzyni i powtórz.', NULL, 'free-exercise-db/Box_Skip/0.jpg', 'free_exercise_db'),
  ('box-squat', 'Przysiad na skrzynię (box squat)', 'Box Squat', 'motor_coach', 'intermediate', array['Trójbój', 'Uda'], 'Przysiad z siadaniem na skrzynię, zwykle wykonywany w stojaku siłowym. Uczy właściwej głębokości i rozwija siłę wybuchową w przysiadzie.', '1. Box squat pozwala przysiadać do pożądanej głębokości i rozwijać siłę wybuchową w ruchu przysiadu. Zacznij w stojaku siłowym ze skrzynią odpowiedniej wysokości za sobą. Zazwyczaj celujesz w wysokość skrzyni dającą przysiad do równoległości, ale możesz trenować wyżej lub niżej, jeśli chcesz.
2. Zacznij od wsunięcia się pod sztangę i położenia jej na tylnej części barków. Ściągnij łopatki razem i obróć łokcie do przodu, próbując zgiąć sztangę na barkach. Zdejmij sztangę ze stojaka, tworząc ciasne wygięcie w dolnych plecach, i cofnij się do pozycji. Rozstaw stopy szerzej dla większego nacisku na plecy, pośladki, przywodziciele i dwugłowe uda, albo bliżej dla bardziej rozwoju czworogłowych. Trzymaj głowę skierowaną do przodu.
3. Z plecami, barkami i mięśniami głębokimi napiętymi, wypychaj kolana i pośladki na zewnątrz, rozpoczynając zejście. Siadaj biodrami do tyłu, aż usiądziesz na skrzyni. Idealnie, twoje piszczele powinny być prostopadłe do ziemi. Zatrzymaj się, gdy osiągniesz skrzynię, i rozluźnij zginacze bioder. Nigdy nie odbijaj się od skrzyni.
4. Utrzymując ciężar na piętach i wypychając stopy i kolana na zewnątrz, wypchnij się w górę ze skrzyni prowadząc ruch głową. Kontynuuj w górę, utrzymując napięcie od głowy do palców.', NULL, 'free-exercise-db/Box_Squat/0.jpg', 'free_exercise_db'),
  ('box-squat-with-bands', 'Przysiad na skrzynię z gumami', 'Box Squat with Bands', 'motor_coach', 'advanced', array['Trójbój', 'Uda'], 'Przysiad na skrzynię z dodatkowym oporem gum oporowych. Opór rośnie wraz z unoszeniem się — świetne narzędzie do budowania siły wybuchowej.', '1. Zacznij w stojaku siłowym ze skrzynią odpowiedniej wysokości za sobą. Zamocuj gumy na tulejach sztangi, przymocowane do kołków, stojaka lub hantli, tak aby było odpowiednie napięcie. Jeśli używasz hantli, zabezpiecz je, aby się nie poruszały. Upewnij się też, że używane hantle są wystarczająco ciężkie dla gum, których używasz. Dodatkowe talerze mogą służyć do dociążenia hantli. Jeśli potrzebujesz więcej napięcia, możesz rozszerzyć podstawę na podłodze albo skrócić gumy. Zazwyczaj celujesz w wysokość skrzyni dającą przysiad do równoległości, ale możesz trenować wyżej lub niżej, jeśli chcesz.
2. Zacznij od wsunięcia się pod sztangę i położenia jej na tylnej części barków. Ściągnij łopatki razem i obróć łokcie do przodu, próbując zgiąć sztangę na barkach. Zdejmij sztangę ze stojaka, tworząc ciasne wygięcie w dolnych plecach, i cofnij się do pozycji. Rozstaw stopy szerzej dla większego nacisku na plecy, pośladki, przywodziciele i dwugłowe uda, albo bliżej dla bardziej rozwoju czworogłowych. Trzymaj głowę skierowaną do przodu.
3. Z plecami, barkami i mięśniami głębokimi napiętymi, wypychaj kolana i pośladki na zewnątrz, rozpoczynając zejście. Siadaj biodrami do tyłu, aż usiądziesz na skrzyni. Idealnie, twoje piszczele powinny być prostopadłe do ziemi. Zatrzymaj się, gdy osiągniesz skrzynię, i rozluźnij zginacze bioder. Nigdy nie odbijaj się od skrzyni.
4. Utrzymując ciężar na piętach i wypychając stopy i kolana na zewnątrz, wypchnij się w górę ze skrzyni prowadząc ruch głową. Kontynuuj w górę, utrzymując napięcie od głowy do palców. Ostrożnie odłóż sztangę z powrotem na stojak.', NULL, 'free-exercise-db/Box_Squat_with_Bands/0.jpg', 'free_exercise_db'),
  ('box-squat-with-chains', 'Przysiad na skrzynię z łańcuchami', 'Box Squat with Chains', 'motor_coach', 'advanced', array['Siłowe', 'Uda'], 'Przysiad na skrzynię z łańcuchami zawieszonymi na sztandze. Im wyżej jesteś, tym więcej łańcucha unosi się i tym większy opór — buduje siłę wybuchową.', '1. Zacznij w stojaku siłowym ze skrzynią odpowiedniej wysokości za sobą. Zazwyczaj celujesz w wysokość skrzyni dającą przysiad do równoległości, ale możesz trenować wyżej lub niżej, jeśli chcesz.
2. Aby ustawić łańcuchy, zacznij od zawieszenia łańcucha prowadzącego na tulejach sztangi. Ciężki łańcuch powinien być przymocowany karabińczykiem. Dopasuj długość łańcucha prowadzącego tak, aby kilka ogniw wciąż leżało na podłodze na szczycie ruchu.
3. Zacznij od wsunięcia się pod sztangę i położenia jej na tylnej części barków. Ściągnij łopatki razem i obróć łokcie do przodu, próbując zgiąć sztangę na barkach. Zdejmij sztangę ze stojaka, tworząc ciasne wygięcie w dolnych plecach, i cofnij się do pozycji. Rozstaw stopy szerzej dla większego nacisku na plecy, pośladki, przywodziciele i dwugłowe uda, albo bliżej dla bardziej rozwoju czworogłowych. Trzymaj głowę skierowaną do przodu.
4. Z plecami, barkami i mięśniami głębokimi napiętymi, wypychaj kolana i pośladki na zewnątrz, rozpoczynając zejście. Siadaj biodrami do tyłu, aż usiądziesz na skrzyni. Idealnie, twoje piszczele powinny być prostopadłe do ziemi. Zatrzymaj się, gdy osiągniesz skrzynię, i rozluźnij zginacze bioder. Nigdy nie odbijaj się od skrzyni.
5. Utrzymując ciężar na piętach i wypychając stopy i kolana na zewnątrz, wypchnij się w górę ze skrzyni prowadząc ruch głową. Kontynuuj w górę, utrzymując napięcie od głowy do palców.', NULL, 'free-exercise-db/Box_Squat_with_Chains/0.jpg', 'free_exercise_db'),
  ('brachialis-smr', 'Rolowanie ramienia (mięsień ramienny, SMR)', 'Brachialis-SMR', 'motor_coach', 'intermediate', array['Rozciąganie', 'Biceps'], 'Automasaż zewnętrznej części ramienia wałkiem. Rozluźnia mięsień ramienny i biceps.', '1. Połóż się na boku, z górną częścią ramienia opartą o wałek. Ramię powinno być mniej więcej w linii z ciałem, z zewnętrzną częścią bicepsa dociśniętą do wałka.
2. Unoś biodra nad podłogą, podpierając ciężar ciała na ramieniu i stopach. Trzymaj 10–30 sekund, a następnie zmień strony.', NULL, 'free-exercise-db/Brachialis-SMR/0.jpg', 'free_exercise_db'),
  ('bradford-rocky-presses', 'Wyciskanie Bradfora/Rocky''ego (za głowę)', 'Bradford/Rocky Presses', 'motor_coach', 'beginner', array['Siłowe', 'Barki'], 'Wyciskanie sztangi nad głowę z przenoszeniem jej z przodu za głowę. Kompleksowe ćwiczenie na barki.', '1. Usiądź na ławce do wyciskania wojskowego ze sztangą na wysokości barków chwytem nachwytem (dłonie skierowane do przodu). Wskazówka: Chwyt powinien być szerszy niż szerokość barków i tworzyć kąt 90 stopni między przedramieniem a ramieniem, gdy sztanga schodzi. To jest pozycja startowa.
2. Po złapaniu sztangi właściwą szerokością chwytu unieś sztangę nad głowę, blokując ramiona.
3. Teraz opuszczaj sztangę powoli za głowę, biorąc wdech.
4. Unoś sztangę z powrotem do pozycji startowej, robiąc wydech.
5. Opuszczaj sztangę powoli do pozycji startowej z przodu, biorąc wdech. To stanowi jedno powtórzenie.
6. Naprzemiennie w ten sposób, aż wykonasz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Bradford_Rocky_Presses/0.jpg', 'free_exercise_db'),
  ('butt-lift-bridge', 'Mostek biodrowy (unoszenie pośladków)', 'Butt Lift (Bridge)', 'motor_coach', 'beginner', array['Siłowe', 'Pośladki'], 'Unoszenie bioder z ziemi w leżeniu na plecach z ugiętymi nogami. Proste ćwiczenie aktywujące pośladki i dwugłowe uda.', '1. Połóż się płasko na podłodze na plecach z rękami wzdłuż ciała i ugiętymi kolanami. Stopy powinny być rozstawione około na szerokość barków. To będzie pozycja startowa.
2. Odpychając głównie piętami, unoś biodra nad podłogę, trzymając plecy proste. Robisz wydech podczas tej części ruchu i utrzymaj na szczycie przez sekundę.
3. Powoli wróć do pozycji startowej, biorąc wdech.', NULL, 'free-exercise-db/Butt_Lift_Bridge/0.jpg', 'free_exercise_db'),
  ('butt-ups', 'Unoszenie pośladków w desce (butt-ups)', 'Butt-Ups', 'motor_coach', 'beginner', array['Siłowe', 'Brzuch'], 'W pozycji deski na przedramionach unoś pośladki w górę, zbliżając klatkę piersiową do bioder. Wzmacnia mięśnie głębokie i dolną część brzucha.', '1. Zacznij w pozycji pompek, ale z łokciami na ziemi i ciężarem na przedramionach. Ramiona powinny być zgięte pod kątem 90 stopni.
2. Lekko wygnij plecy do góry zamiast trzymać je całkowicie prosto.
3. Unoś pośladki w kierunku sufitu, mocno zaciskając mięśnie brzucha, aby zmniejszyć odległość między żebrami a biodrami. Efektem końcowym będzie znalezienie się w wysokiej pozycji mostka. Robisz wydech podczas tej fazy ruchu.
4. Powoli opuść się z powrotem do pozycji startowej, biorąc wdech. Wskazówka: Nie pozwól, aby plecy zapadały się w dół.
5. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Butt-Ups/0.jpg', 'free_exercise_db'),
  ('butterfly', 'Motylek (rozpiętki na maszynie)', 'Butterfly', 'motor_coach', 'beginner', array['Siłowe', 'Klatka piersiowa'], 'Rozpiętki klatki piersiowej na maszynie (motylku). Ściąganie uchwytów przed sobą izoluje i buduje mięśnie klatki piersiowej.', '1. Usiądź na maszynie z plecami płasko na oparciu.
2. Chwyć uchwyty. Wskazówka: Twoje ramiona powinny być ustawione równolegle do podłogi; dostosuj maszynę odpowiednio. To będzie pozycja startowa.
3. Ściągaj uchwyty razem powoli, zaciskając klatkę piersiową w środku. Robisz wydech w tej części ruchu i utrzymuj spięcie przez sekundę.
4. Wróć powoli do pozycji startowej, biorąc wdech, aż mięśnie klatki piersiowej zostaną całkowicie rozciągnięte.
5. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Butterfly/0.jpg', 'free_exercise_db'),
  ('cable-chest-press', 'Wyciskanie na wyciągu siedząc', 'Cable Chest Press', 'motor_coach', 'beginner', array['Siłowe', 'Klatka piersiowa'], 'Ćwiczenie klatki piersiowej na wyciągu siedząc. Z uchwytami przy klatce prostujesz łokcie, wypychając je prosto przed siebie.', '1. Ustaw odpowiedni ciężar, usiądź i złap za uchwyty. Twoje ramiona powinny być pod kątem około 45 stopni względem ciała, głowa i klatka uniesione, a łokcie zgięte pod kątem około 90 stopni. To pozycja startowa.
2. Zacznij od wyprostu w łokciach, wyciskając uchwyty przed sobą tak, by zbliżyły się do siebie. W trakcie ruchu trzymaj ściągnięte łopatki.
3. Po pauzie w pełnym wyproście wróć do pozycji startowej, zachowując napięcie linek.
4. To ćwiczenie możesz też wykonywać z plecami odsuniętymi od oparcia, na skosie dodatnim lub ujemnym albo naprzemiennie każdą ręką.', NULL, 'free-exercise-db/Cable_Chest_Press/0.jpg', 'free_exercise_db'),
  ('cable-crossover', 'Rozpiętki krzyżowane na wyciągu', 'Cable Crossover', 'motor_coach', 'beginner', array['Siłowe', 'Klatka piersiowa'], 'Izolacja klatki piersiowej na dwóch wyciągach górnych. Ramiona prowadzisz szerokim łukiem na boki aż poczujesz rozciągnięcie klatki, a potem łączysz je przed sobą.', '1. Aby przyjąć pozycję startową, umieść krążki w wysokiej pozycji (powyżej głowy), wybierz opór i trzymaj po jednym uchwycie w każdej dłoni.
2. Zrób krok do przodu przed umowną linię łączącą oba krążki, łącząc ramiona z przodu ciała. Tułów powinien mieć niewielkie pochylenie od pasa. To pozycja startowa.
3. Z lekkim ugięciem łokci, aby zapobiec naprężeniu ścięgna bicepsa, prowadź ramiona na boki (prosto na obie strony) szerokim łukiem, aż poczujesz rozciągnięcie klatki piersiowej. Wdech wykonuj podczas tej fazy ruchu. Wskazówka: Pamiętaj, że w całym ruchu ramiona i tułów pozostają nieruchome; ruch zachodzi tylko w stawie barkowym.
4. Wróć ramiona do pozycji startowej robiąc wydech. Upewnij się, że używasz tego samego łuku ruchu, którym opuszczałeś ciężar.
5. Zatrzymaj się na sekundę w pozycji startowej i powtórz ruch zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Cable_Crossover/0.jpg', 'free_exercise_db'),
  ('cable-crunch', 'Spięcia brzucha na wyciągu (klęk)', 'Cable Crunch', 'motor_coach', 'beginner', array['Siłowe', 'Brzuch'], 'Crunch wykonywany w klęku przy wyciągu górnym z linką. Ściągasz łokcie w stronę ud, spinając mięśnie brzucha.', '1. Uklęknij pod wysokim krążkiem wyciągu z linką zamocowaną do karabińczyka.
2. Złap za końce liny i opuść ją tak, aby twoje dłonie znalazły się obok twarzy.
3. Lekko zegnij biodra i pozwól, by ciężar wygiął dolny odcinek pleców w przeprost. To pozycja startowa.
4. Trzymając biodra nieruchomo, zegnij pas brzuszny, spinając mięśnie brzucha tak, aby łokcie poprowadzić w kierunku środkowej części ud. Wydech wykonuj podczas tej fazy ruchu i utrzymaj spięcie przez sekundę.
5. Powoli wróć do pozycji startowej robiąc wdech. Wskazówka: Zadbaj o stałe napięcie mięśni brzucha w całym ruchu. Nie wybieraj też ciężaru tak dużego, żeby to dolne plecy przejmowały większość pracy.
6. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Cable_Crunch/0.jpg', 'free_exercise_db'),
  ('cable-deadlifts', 'Martwy ciąg na wyciągu', 'Cable Deadlifts', 'motor_coach', 'beginner', array['Siłowe', 'Uda'], 'Wariant martwego ciągu między wieżami wyciągu z linkami na najniższej pozycji. Siadasz po uchwyty, a następnie prostujesz biodra i kolana, unosząc ciężar.', '1. Przesuń linki na dół wież i wybierz odpowiedni ciężar. Stań dokładnie między słupkami.
2. Na początek siadnij, zginając biodra i kolana, aż sięgniesz po uchwyty.
3. Po złapaniu ich zacznij wstawać. Odpychając się piętami, wyprostuj biodra i kolana, trzymając ręce swobodnie zwisające przy bokach. W całym ruchu trzymaj głowę i klatkę piersiową uniesioną.
4. Gdy osiągniesz pełną pozycję stojącą, wróć do pozycji startowej i powtórz.', NULL, 'free-exercise-db/Cable_Deadlifts/0.jpg', 'free_exercise_db'),
  ('cable-hammer-curls-rope-attachment', 'Uginanie ramion młotkowe na wyciągu z linką', 'Cable Hammer Curls - Rope Attachment', 'motor_coach', 'beginner', array['Siłowe', 'Biceps'], 'Młotkowe uginanie ramion na dolnym wyciągu z linką. Trzymasz ją chwytem neutralnym (kciuki do góry) i zginasz łokcie, angażując biceps i przedramiona.', '1. Zamocuj linkę na dolnym krążku i stań przodem do maszyny około 30 cm od niej.
2. Złap linkę chwytem neutralnym (dłonie skierowane do środka) i stań prosto, zachowując naturalną krzywiznę pleców i nieruchomy tułów.
3. Przyciągnij łokcie do boków i trzymaj je tam nieruchomo przez cały ruch. Wskazówka: Poruszać się powinny tylko przedramiona; nie ramiona. To pozycja startowa.
4. Angażując biceps, unoś ramiona przy wydechu, aż biceps dotknie przedramienia. Wskazówka: Pamiętaj, żeby trzymać łokcie przy tulowie i ramiona nieruchomo.
5. Po sekundzie spięcia bicepsa powoli zacznij opuszczać ciężar do pozycji wyjściowej.
6. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Cable_Hammer_Curls_-_Rope_Attachment/0.jpg', 'free_exercise_db'),
  ('cable-hip-adduction', 'Przyciąganie nogi w bok na wyciągu (przywodziciele)', 'Cable Hip Adduction', 'motor_coach', 'beginner', array['Siłowe', 'Uda'], 'Ćwiczenie przywodzicieli uda przy dolnym wyciągu z mankietem na kostce. Nogą z mankietem przyciągasz ją przed drugą nogę, pracując wewnętrzną częścią uda.', '1. Stań przodem do dolnego krążka z jedną nogą przy wyciągu, a drugą dalej.
2. Zamocuj mankiet na kostkę do linki oraz na kostkę nogi bliżej wyciągu.
3. Teraz zrób szeroki krok w bok, oddalając się od stosu ciężarów, i złap za poręcz systemu wyciągu.
4. Opuść się na stopę bez mankietu (ta dalsza noga) i pozwól, by noga z mankietem została pociągnięta w stronę dolnego krążka. To pozycja startowa.
5. Wykonaj ruch, przesuwając nogę z mankietem przed dalszą nogę, używając wewnętrznych partii ud. Wydech wykonuj podczas tej fazy ruchu.
6. Powoli wróć do pozycji startowej robiąc wdech.
7. Powtórz zalecaną liczbę powtórzeń, a następnie wykonaj ten sam ruch drugą nogą.', NULL, 'free-exercise-db/Cable_Hip_Adduction/0.jpg', 'free_exercise_db'),
  ('cable-incline-pushdown', 'Prostowanie ramion na wyciągu leżąc na skosie', 'Cable Incline Pushdown', 'motor_coach', 'beginner', array['Siłowe', 'Najszersze grzbietu'], 'Prostowanie ramion (triceps) na wyciągu górnym, leżąc na ławce skośnej tyłem do maszyny. Prostujesz ramiona nad głową pracą tricepsa.', '1. Połóż się na ławce skośnej tyłem do maszyny z wyciągiem górnym, która ma zamontowany prosty drążek.
2. Złap prosty drążek nad głową nachwytem (dłonie skierowane w dół) na szerokość barków i wyprostuj ramiona przed sobą. Drążek powinien znajdować się około 5 cm nad udami. To pozycja startowa.
3. Trzymając ramiona nieruchomo, unoś ramiona półkolistym ruchem, aż drążek znajdzie się prosto nad twoją głową. Wdech wykonuj podczas tej fazy ruchu.
4. Powoli wróć do pozycji startowej pracą najszerszych mięśni pleców i utrzymaj spięcie po osiągnięciu pozycji startowej. Wydech wykonuj podczas tej fazy ruchu.
5. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Cable_Incline_Pushdown/0.jpg', 'free_exercise_db'),
  ('cable-incline-triceps-extension', 'Prostowanie ramion na wyciągu na skosie (triceps)', 'Cable Incline Triceps Extension', 'motor_coach', 'beginner', array['Siłowe', 'Triceps'], 'Prostowanie ramion na wyciągu górnym, leżąc na ławce skośnej tyłem do maszyny. Prostujesz ramiona nad głową, koncentrując pracę na tricepsie.', '1. Połóż się na ławce skośnej tyłem do maszyny z wyciągiem górnym, która ma zamontowany prosty drążek.
2. Złap prosty drążek nad głową nachwytem (dłonie skierowane w dół) wąsko, mniej niż na szerokość barków, i trzymaj łokcie blisko tułowia. Twoje ramiona powinny tworzyć kąt około 25 stopni mierzony względem podłogi.
3. Trzymając ramiona nieruchomo, prostuj ramiona, spinając triceps. Wydech wykonuj podczas tej fazy ruchu i utrzymaj spięcie przez sekundę.
4. Powoli wróć do pozycji startowej.
5. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Cable_Incline_Triceps_Extension/0.jpg', 'free_exercise_db'),
  ('cable-internal-rotation', 'Rotacja wewnętrzna barku na wyciągu', 'Cable Internal Rotation', 'motor_coach', 'beginner', array['Siłowe', 'Barki'], 'Izolacja rotatorów barku — rotacja wewnętrzna na dolnym wyciągu. Siedzisz bokiem do wyciągu i przyciągasz uchwyt do brzucha obracając bark do wewnątrz.', '1. Usiądź bokiem do dolnego krążka (z nogami wyprostowanymi przed sobą lub skrzyżowanymi) i złap jednoręczny uchwyt wyciągu ręką bliższą wyciągowi. Wskazówka: Jeśli możesz regulować wysokość krążka, możesz zamiast tego usiąść na płaskiej ławce.
2. Ustaw łokieć przy boku, zgięty pod kątem 90 stopni, z przedramieniem skierowanym w stronę wyciągu. To pozycja startowa.
3. Pociągnij jednoręczny uchwyt w kierunku ciała, obracając bark do wewnątrz, aż przedramię przejdzie w poprzek brzucha. Będziesz kreślić wyobrażone półkole. Wskazówka: Przedramię powinno być cały czas prostopadłe do tułowia.
4. Powoli wróć do pozycji wyjściowej.
5. Powtórz zalecaną liczbę powtórzeń, a następnie wykonaj ten sam ruch drugą ręką.', NULL, 'free-exercise-db/Cable_Internal_Rotation/0.jpg', 'free_exercise_db'),
  ('cable-iron-cross', 'Żelazny krzyż na wyciągach', 'Cable Iron Cross', 'motor_coach', 'beginner', array['Siłowe', 'Klatka piersiowa'], 'Ćwiczenie klatki piersiowej na dwóch wyciągach górnych. Stoisz między wyciągami z ramionami rozłożonymi na boki i ściągasz uchwyty prosto w dół wzdłuż tulowa.', '1. Zacznij od ustawienia krążków w wysokiej pozycji, wyboru oporu i chwycenia po jednym uchwycie w każdej dłoni.
2. Stań dokładnie między oboma krążkami z ramionami wyciągniętymi na boki. Głowa i klatka piersiowa uniesione, a ramiona tworzą literę „T”. To pozycja startowa.
3. Trzymając łokcie wyprostowane, ściagnij ramiona prosto w dół wzdłuż boków.
4. Po pauzie w szczycowym spięciu wróć ramiona do pozycji startowej.
5. Kontynuuj ruch zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Cable_Iron_Cross/0.jpg', 'free_exercise_db'),
  ('cable-judo-flip', 'Przerzut judo na wyciągu', 'Cable Judo Flip', 'motor_coach', 'beginner', array['Siłowe', 'Brzuch'], 'Dynamiczne ćwiczenie całego ciała na wyciągu dolnym z linką. Obracasz tułów od wyciągu, przerzucając linkę ponad bark jak przy rzucie judo, spinając brzuch.', '1. Zamocuj linkę do wieży i ustaw linkę na najniższej pozycji krążka. Stań bokiem do linki w szerokim rozkroku i złap ją oburącz.
2. Obróć tułów od wyciągu, przerzucając linkę ponad bark, jakbyś wykonywał rzut judo.
3. Przenoś ciężar ciała między stopami, gdy się obracasz i spinasz brzuch w przód, ciągnąc linkę w dół.
4. Wróć do pozycji startowej i powtarzaj do upadku mięśni.
5. Następnie zmień pozycję i powtórz tę samą serię ruchów po drugiej stronie.', NULL, 'free-exercise-db/Cable_Judo_Flip/0.jpg', 'free_exercise_db'),
  ('cable-lying-triceps-extension', 'Francuskie wyciskanie na wyciągu leżąc', 'Cable Lying Triceps Extension', 'motor_coach', 'beginner', array['Siłowe', 'Triceps'], 'Francuskie wyciskanie na wyciągu leżąc na płaskiej ławce z prostym drążkiem dolnego wyciągu. Opuszczasz drążek do czoła, zginając łokcie, i wracasz do wyprostu pracą tricepsa.', '1. Połóż się na płaskiej ławce i złap prosty drążek dolnego wyciągu wąskim nachwytem. Wskazówka: Najłatwiej zrobić to tak, aby ktoś podał ci drążek, gdy już się położysz.
2. Z wyprostowanymi ramionami ustaw drążek nad torsem. Ramiona i tułów powinny tworzyć kąt 90 stopni. To pozycja startowa.
3. Opuszczaj drążek, zginając w łokciach, trzymając ramiona nieruchomo i łokcie blisko tułowia. Schodź, aż drążek delikatnie dotknie twojego czoła. Wdech wykonuj podczas tej fazy ruchu.
4. Spinaj triceps, unosząc drążek z powrotem do pozycji startowej. Wydech wykonuj podczas tej fazy ruchu.
5. Zatrzymaj się na sekundę w pozycji spiętej i powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Cable_Lying_Triceps_Extension/0.jpg', 'free_exercise_db'),
  ('cable-one-arm-tricep-extension', 'Jednoręczne prostowanie ramienia na wyciągu (triceps)', 'Cable One Arm Tricep Extension', 'motor_coach', 'beginner', array['Siłowe', 'Triceps'], 'Prostowanie ramienia jednorącz na wyciągu górnym z pojedynczym uchwytem. Łokieć zostaje przy tułowiu, a przedramię prostuje się w dół pracą tricepsa.', '1. Prawą ręką złap za pojedynczy uchwyt zamocowany do wyciągu górnego chwytem podchwytem (dłonie skierowane do góry). Powinieneś stać dokładnie przed stosem ciężarów.
2. Teraz pociągnij uchwyt w dół tak, aby ramię i łokieć były dociśnięte do boku ciała. Ramię i przedramię powinny tworzyć kąt ostry (mniejszy niż 90 stopni). Drugą rękę możesz trzymać przy pasie, a dla lepszej równowagi wystawić jedną nogę do przodu, a drugą cofnąć. To pozycja startowa.
3. Spinając triceps, prowadź uchwyt w dół przy boku, aż ramię będzie proste. Wydech wykonuj podczas tego ruchu. Wskazówka: Poruszać się powinno tylko przedramię. Ramiona powinny pozostać nieruchome przez cały czas.
4. Zaciśnij triceps i utrzymaj spięcie przez sekundę w tej pozycji.
5. Powoli wróć uchwytem do pozycji startowej.
6. Powtórz zalecaną liczbę powtórzeń, a następnie wykonaj ten sam ruch drugą ręką.', NULL, 'free-exercise-db/Cable_One_Arm_Tricep_Extension/0.jpg', 'free_exercise_db'),
  ('cable-preacher-curl', 'Uginanie ramion na modlitewniku na wyciągu', 'Cable Preacher Curl', 'motor_coach', 'beginner', array['Siłowe', 'Biceps'], 'Uginanie ramion na biceps na modlitewniku przy dolnym wyciągu z prostym drążkiem. Łokcie spoczywają na oparciu, a Ty zginaś ramiona w kierunku barków.', '1. Ustaw modlitewnik około 60 cm przed maszyną z wyciągiem.
2. Zamocuj prosty drążek do dolnego krążka.
3. Usiądź przy modlitewniku opierając pewnie łokcie i ramiona na górnej części poduszki i poproś kogoś, by podał ci drążek z dolnego wyciągu.
4. Złap drążek i w pełni wyprostuj ramiona na oparciu modlitewnika. To pozycja startowa.
5. Teraz zacznij ciągnąć ciężar w kierunku barków i mocno zaciśnij biceps na górze ruchu. Wydech wykonuj podczas tego ruchu. Zatrzymaj się też na sekundę na górze.
6. Teraz powoli opuść ciężar do pozycji startowej.
7. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Cable_Preacher_Curl/0.jpg', 'free_exercise_db'),
  ('cable-rear-delt-fly', 'Rozpiętki odwrotne na wyciągach (tylne aktony)', 'Cable Rear Delt Fly', 'motor_coach', 'beginner', array['Siłowe', 'Barki'], 'Izolacja tylnej partii barków na dwóch wyciągach. Krzyżujesz ręce przed sobą i otwierasz ramiona na boki do tyłu, trzymając je wyprostowane.', '1. Ustaw krążki na odpowiedniej wysokości i dobierz ciężar. Krążki powinny znajdować się powyżej twojej głowy.
2. Złap lewy uchwyt prawą ręką, a prawy lewą, krzyżując je przed sobą. To pozycja startowa.
3. Rozpocznij ruch, prowadząc ramiona do tyłu i na boki, utrzymując je wyprostowane w trakcie ruchu.
4. Zatrzymaj się na końcu ruchu, zanim wrócisz uchwytami do pozycji startowej.', NULL, 'free-exercise-db/Cable_Rear_Delt_Fly/0.jpg', 'free_exercise_db'),
  ('cable-reverse-crunch', 'Odwrócone spięcia brzucha na wyciągu', 'Cable Reverse Crunch', 'motor_coach', 'beginner', array['Siłowe', 'Brzuch'], 'Odwrócony crunch na wyciągu dolnym z mankietami na kostkach. Leżysz na macie, podnosisz biodra i przyciągasz kolana do torsu, spinając dolną część brzucha.', '1. Zamocuj pasek na kostki do dolnego wyciągu i połóż matę na podłodze przed nim.
2. Usiądź stopami w kierunku wyciągu i zapinij mankiet na kostkach.
3. Połóż się, unoś nogi i zegnij kolana pod kątem 90 stopni. Twoje nogi i linka powinny być w jednej linii. Jeśli nie są, dostosuj wysokość krążka, aż będą.
4. Z dłońmi za głową przyciągnij kolana do wewnątrz w kierunku torsu i unoś biodra ponad podłogę.
5. Zatrzymaj się na moment i w sposób powolny i kontrolowany opuść biodra, wracając nogami do startowego kąta 90 stopni. Mięśnie brzucha powinny nadal pozostawać napięte w pozycji spoczynkowej.
6. Powtarzaj ten sam ruch do upadku mięśni.', NULL, 'free-exercise-db/Cable_Reverse_Crunch/0.jpg', 'free_exercise_db'),
  ('cable-rope-overhead-triceps-extension', 'Prostowanie ramion z linką nad głową na wyciągu', 'Cable Rope Overhead Triceps Extension', 'motor_coach', 'beginner', array['Siłowe', 'Triceps'], 'Prostowanie ramion nad głową z linką na wyciągu dolnym. Trzymasz linkę nad głową chwytem neutralnym i opuszczasz ją za głowę, rozciągając triceps, po czym prostujesz ramiona.', '1. Zamocuj linkę do dolnego krążka maszyny z wyciągiem.
2. Trzymając linkę oburącz, wyprostuj ramiona z dłońmi bezpośrednio nad głową chwytem neutralnym (dłonie zwrócone ku sobie). Łokcie powinny być blisko głowy, ramiona prostopadłe do podłogi, a kostki dłoni skierowane do sufitu. To pozycja startowa.
3. Powoli opuść linkę za głowę, trzymając ramiona nieruchomo. Robiąc wdech, wykonuj ten ruch i zatrzymaj się, gdy triceps będzie w pełni rozciągnięty.
4. Wróć do pozycji startowej spinając triceps przy wydechu.
5. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Cable_Rope_Overhead_Triceps_Extension/0.jpg', 'free_exercise_db'),
  ('cable-rope-rear-delt-rows', 'Wiosłowanie z linką na wyciągu (tylne aktony)', 'Cable Rope Rear-Delt Rows', 'motor_coach', 'beginner', array['Siłowe', 'Barki'], 'Wiosłowanie na dolnym wyciągu siedząc z linką, z szeroko rozprowadzonymi na boki łokciami. Angażuje górną część pleców i tylne aktony barków.', '1. Usiądź na stanowisku dolnego wyciągu w tej samej pozycji co przy wiosłowaniu siedząc na plecy.
2. Zamocuj linkę do krążka i złap ją nachwytem. Twoje ramiona powinny być wyprostowane i równoległe do podłogi, z łokciami skierowanymi na zewnątrz.
3. Trzymaj dolny odcinek pleców pionowo i cofnij biodra tak, aby kolana były lekko ugięte. To pozycja startowa.
4. Pociągnij przyczep linkowy w stronę górnej części klatki piersiowej, tuż pod szyją, trzymając łokcie wysoko i na boki. Kontynuuj ten ruch przy wydechu, aż łokcie przejdą nieco za tułów. Wskazówka: Trzymaj ramiona poziomo, prostopadle do tułowia i równolegle do podłogi w całym ruchu.
5. Wróć do pozycji wyjściowej, gdzie ramiona są wyprostowane, a barki rozciągnięte w przód. Wdech wykonuj podczas tej fazy ruchu.
6. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Cable_Rope_Rear-Delt_Rows/0.jpg', 'free_exercise_db'),
  ('cable-russian-twists', 'Skręty torsu rosyjskie na wyciągu', 'Cable Russian Twists', 'motor_coach', 'beginner', array['Siłowe', 'Brzuch'], 'Rosyjskie skręty torsu z oporem wyciągu wykonywane na piłce gimnastycznej. Trzymasz uchwyt oburącz nad klatką i obracasz tors w bok od wyciągu, spinając mięśnie głębokie.', '1. Podłącz standardowy uchwyt i ustaw linkę na środkowej pozycji krążka.
2. Połóż się poprzecznie na piłce gimnastycznej prostopadle do linki i złap uchwyt jedną ręką. Powinieneś być mniej więcej na odległość ramienia od wyciągu, z napięciem ciężaru na linie.
3. Złap uchwyt oburącz i w pełni wyprostuj ramiona nad klatką piersiową. Dłonie powinny być dokładnie w linii z wyciągiem. Jeśli nie są, dostosuj wysokość krążka, aż będą.
4. Trzymaj biodra uniesione, a mięśnie brzucha napięte. Obróć tors od wyciągu o ćwierć obrotu. Ciało powinno być płaskie od głowy do kolan.
5. Zatrzymaj się na moment i w sposób powolny i kontrolowany wróć do pozycji startowej. W pozycji spoczynkowej na linie nadal powinno działać boczne napięcie.
6. Powtarzaj ten sam ruch do upadku mięśni.
7. Następnie zmień pozycję i powtórz tę samą serię ruchów po drugiej stronie.', NULL, 'free-exercise-db/Cable_Russian_Twists/0.jpg', 'free_exercise_db'),
  ('cable-seated-crunch', 'Spięcia brzucha na wyciągu siedząc', 'Cable Seated Crunch', 'motor_coach', 'beginner', array['Siłowe', 'Brzuch'], 'Crunch siedząc na ławce plecami do wyciągu górnego, z linką trzymaną nad barkami. Zegnasz pas brzuszny, prowadząc łokcie w kierunku bioder.', '1. Usiądź na płaskiej ławce plecami do wyciągu górnego.
2. Złap przyczep linowy oburącz (dłonie zwrócone ku sobie) i umieść dłonie pewnie nad oboma barkami. Wskazówka: Pozwól, by ciężar lekko wygiął dolny odcinek pleców w przeprost. To pozycja startowa.
3. Trzymając biodra nieruchomo, zegnij pas brzuszny tak, aby łokcie poprowadzić w kierunku bioder. Wydech wykonuj podczas tego kroku.
4. Robiąc wdech, powoli wróć do pozycji wyjściowej.
5. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Cable_Seated_Crunch/0.jpg', 'free_exercise_db'),
  ('cable-seated-lateral-raise', 'Wznosy boczne na wyciągach siedząc', 'Cable Seated Lateral Raise', 'motor_coach', 'beginner', array['Siłowe', 'Barki'], 'Wznosy boczne barków na dwóch dolnych wyciągach, wykonywane siedząc na ławce. Unoś ramiona na boki do wysokości barków, pracując boczną częścią barków.', '1. Stań między dwoma dolnymi krążkami skierowanymi ku sobie i postaw płaską ławkę zaraz za sobą (prostopadle do ciebie; za tobą powinien być wąski koniec ławki). Wybierz ciężar na każdym z krążków.
2. Teraz usiądź na krawędzi płaskiej ławki za tobą ze stopami ustawionymi przed kolanami.
3. Pochyl się do przodu, zachowując płaskie plecy, i oprzyj tułów na udach.
4. Poproś kogoś, by podał ci jednoręczne uchwyty zamocowane do wyciągów. Po wybraniu ciężaru złap lewy uchwyt prawą ręką, a prawy lewą. Linki powinny biec pod kolanami, a ramiona będą wyprostowane, z dłońmi zwróconymi ku sobie i lekkim ugięciem w łokciach. To pozycja startowa.
5. Trzymając ramiona nieruchomo, unoś górną część ramion na boki, aż będą równoległe do podłogi i na wysokości barków. Wydech wykonuj podczas tego ruchu i utrzymaj spięcie przez sekundę.
6. Powoli opuść ramiona do pozycji startowej robiąc wdech.
7. Powtórz zalecaną liczbę powtórzeń. Wskazówka: Utrzymuj ramiona prostopadle do tułowia i stałą pozycję łokci (kąt od 10 do 30 stopni) w całym ćwiczeniu.', NULL, 'free-exercise-db/Cable_Seated_Lateral_Raise/0.jpg', 'free_exercise_db'),
  ('cable-shoulder-press', 'Wyciskanie barków na wyciągu', 'Cable Shoulder Press', 'motor_coach', 'beginner', array['Siłowe', 'Barki'], 'Wyciskanie nad głowę stojąc między dwiema wieżami wyciągu. Uchwyty trzymasz na wysokości barków i wyciskasz je prosto nad głowę.', '1. Przesuń linki na dół wież i wybierz odpowiedni ciężar.
2. Stań dokładnie między słupkami. Złap linki i trzymaj je na wysokości barków, dłońmi skierowanymi do przodu. To pozycja startowa.
3. Trzymając głowę i klatkę piersiową uniesioną, wyprostuj łokcie, wyciskając uchwyty prosto nad głowę.
4. Po pauzie na górze wróć do pozycji startowej i powtórz.', NULL, 'free-exercise-db/Cable_Shoulder_Press/0.jpg', 'free_exercise_db'),
  ('cable-shrugs', 'Szruhsy barkami na wyciągu', 'Cable Shrugs', 'motor_coach', 'beginner', array['Siłowe', 'Czworoboczne'], 'Unoszenie barków (szruhsy) przy dolnym wyciągu z drążkiem. Podnosisz barki maksymalnie w górę, w kierunku uszu, angażując mięsień czworoboczny.', '1. Złap drążek mocowany do dolnego krążka nachwytem na szerokość barków lub nieco szerszą (dłonie skierowane w dół).
2. Stań wyprostowany blisko wyciągu z ramionami wyprostowanymi przed sobą, trzymając drążek. To pozycja startowa.
3. Unoś drążek, unosząc barki maksymalnie wysoko przy wydechu. Utrzymaj spięcie na górze przez sekundę. Wskazówka: Ramiona powinny pozostawać wyprostowane przez cały czas. Powstrzymaj się od pomagania sobie bicepsem przy unoszeniu drążka. W górę i w dół powinny poruszać się tylko barki.
4. Opuść drążek z powrotem do pozycji wyjściowej.
5. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Cable_Shrugs/0.jpg', 'free_exercise_db'),
  ('cable-wrist-curl', 'Uginanie nadgarstków na wyciągu', 'Cable Wrist Curl', 'motor_coach', 'beginner', array['Siłowe', 'Przedramiona'], 'Izolacja zginaczy nadgarstka przy dolnym wyciągu. Przedramiona opierają się na udach, a ruch wykonują tylko nadgarstki, zginając je w górę i opuszczając.', '1. Zacznij od ustawienia płaskiej ławki przed dolnym wyciągiem z prostym drążkiem.
2. Rękami złap drążek wyciągu chwytem podchwytem (dłonie do góry) na szerokość od wąskiej do szerokości barków i unoś je tak, aby przedramiona opierały się o wierzch ud. Nadgarstki powinny zwisać tuż za kolanami.
3. Zacznij od uginania nadgarstków w górę przy wydechu. Utrzymaj spięcie przez sekundę.
4. Powoli opuść nadgarstki z powrotem do pozycji startowej robiąc wdech.
5. Twoje przedramiona powinny pozostać nieruchome, bo to nadgarstki wykonują jedyny potrzebny ruch w tym ćwiczeniu.
6. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Cable_Wrist_Curl/0.jpg', 'free_exercise_db'),
  ('calf-machine-shoulder-shrug', 'Szruhsy barkami na maszynie do łydek', 'Calf-Machine Shoulder Shrug', 'motor_coach', 'beginner', array['Siłowe', 'Czworoboczne'], 'Unoszenie barków (szruhsy) na maszynie do łydek. Poduszki maszyny opierają się na barkach, które unoś w górę w kierunku uszu.', '1. Umieść się na maszynie do łydek tak, aby poduszki były powyżej twoich barków. Tułów powinien być prosty, a ramiona normalnie opuszczone wzdłuż ciała. To pozycja startowa.
2. Unoś barki w kierunku uszu przy wydechu i utrzymaj spięcie przez pełną sekundę.
3. Powoli wróć do pozycji startowej robiąc wdech.
4. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Calf-Machine_Shoulder_Shrug/0.jpg', 'free_exercise_db'),
  ('calf-press', 'Wypychanie łydek na maszynie', 'Calf Press', 'motor_coach', 'beginner', array['Siłowe', 'Łydki'], 'Ćwiczenie łydek na maszynie z platformą. Śródstopie opiera się o platformę, którą odpychasz pracą łydek, prostując kostki.', '1. Dostosuj siedzisko tak, aby nogi były tylko lekko ugięte w pozycji startowej. Śródstopie powinno pewnie opierać się o platformę.
2. Wybierz odpowiedni ciężar i złap za uchwyty. To pozycja startowa.
3. Wyprostuj nogi prostując kolana, ledwo unosząc ciężar ze stosu. Kostka powinna być w pełni zgięta grzbietowo, palce skierowane w górę. Wykonaj ruch, odpychając platformę śródstopiem maksymalnie daleko.
4. Po krótkiej pauzie odwróć ruch i powtórz.', NULL, 'free-exercise-db/Calf_Press/0.jpg', 'free_exercise_db'),
  ('calf-press-on-the-leg-press-machine', 'Wypychanie łydek na maszynie do wyciskania nóg', 'Calf Press On The Leg Press Machine', 'motor_coach', 'beginner', array['Siłowe', 'Łydki'], 'Wariant wypychania łydek na maszynie do wyciskania nóg (leg press). Palce stopy opierasz o platformę i wypychasz ją pracą łydek, prostując kostki.', '1. Korzystając z maszyny do wyciskania nóg, usiądź i oprzyj nogi o platformę bezpośrednio przed sobą w średnim rozstawie (szerokość barków).
2. Opuść blokady bezpieczeństwa trzymające platformę i wypchnij ją maksymalnie w górę, aż nogi będą w pełni wyprostowane, bez blokowania kolan. (Uwaga: W niektórych maszynach można zostawić blokady bezpieczeństwa dla większego bezpieczeństwa. Jeśli twoja maszyna na to pozwala, jest to preferowany sposób.) Twój tułów i nogi powinny tworzyć idealny kąt 90 stopni. Teraz ostrożnie połóż palce i śródstopie na dolnej części platformy, tak aby pięty wystawały poza jej krawędź. Palce mogą być skierowane do przodu, na zewnątrz lub do wewnątrz, jak opisano na początku rozdziału. To pozycja startowa.
3. Wypchnij platformę, unoś pięty przy wydechu, prostując kostki maksymalnie wysoko i spinając łydki. Upewnij się, że kolana pozostają nieruchome przez cały czas. W żadnym momencie nie powinno dochodzić do ich uginania. Utrzymaj pozycję spiętą przez sekundę, zanim zaczniesz schodzić w dół.
4. Wróć powoli do pozycji startowej robiąc wdech, opuszczając pięty i zginając kostki, aż łydki zostaną rozciągnięte.
5. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Calf_Press_On_The_Leg_Press_Machine/0.jpg', 'free_exercise_db'),
  ('calf-raise-on-a-dumbbell', 'Wspięcia na palce na hantli', 'Calf Raise On A Dumbbell', 'motor_coach', 'intermediate', array['Siłowe', 'Łydki'], 'Wspięcia na palce stojąc na hantli z okrągłymi talerzami, która toczy się pod stopą. Dla balansu trzymasz się stabilnego punktu, a łydkę napinasz na szczycie ruchu.', '1. Złap się czegoś stabilnego dla zachowania równowagi i stań na uchwycie hantli — najlepiej z okrągłymi talerzami, aby się toczyła, bo wtedy musisz ciężej pracować, by się ustabilizować; zwiększa to skuteczność ćwiczenia.
2. Teraz przetocz stopę lekko do przodu, aby uzyskać dobre rozciągnięcie łydki. To pozycja startowa.
3. Unoś się na łydce, przetaczając stopę przez górę uchwytu, tak aby uzyskać pełny wyprost. Wydech wykonuj podczas tego ruchu. Mocno zepnij łydkę na górze i utrzymaj sekundę. Wskazówka: Gdy się unośisz, przetocz hantle lekko do tyłu.
4. Teraz zrób wdech i przetocz hantle lekko do przodu, schodząc w dół, aby uzyskać lepsze rozciągnięcie.
5. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Calf_Raise_On_A_Dumbbell/0.jpg', 'free_exercise_db'),
  ('calf-raises-with-bands', 'Wspięcia na palce z gumą oporową', 'Calf Raises - With Bands', 'motor_coach', 'beginner', array['Siłowe', 'Łydki'], 'Wspięcia na palce z oporem gumy oporowej. Stajesz na gumie, trzymasz jej końce przy barkach i wstajesz na palce, spinając łydki.', '1. Złap gumę oporową i stań na niej palcami, dbając o to, aby długość gumy między stopą a ramionami była taka sama po obu stronach.
2. Trzymając uchwyty gumy, unoś ramiona na boki głowy, jakbyś przygotowywał się do wyciskania barków. Dłonie zwrócone do przodu, łokcie ugięte i skierowane na boki. Ten ruch napnie gumę. To pozycja startowa.
3. Trzymając dłonie przy barkach, wstań na palce przy wydechu i mocno zepnij łydki na szczycie ruchu.
4. Po sekundzie spięcia powoli wróć w dół do pozycji startowej.
5. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Calf_Raises_-_With_Bands/0.jpg', 'free_exercise_db'),
  ('calf-stretch-elbows-against-wall', 'Rozciąganie łydek z przedramionami o ścianę', 'Calf Stretch Elbows Against Wall', 'motor_coach', 'beginner', array['Rozciąganie', 'Łydki'], 'Statyczne rozciąganie łydek przy ścianie. Opierasz się o ściane przedramionami, starając się utrzymać pięty na ziemi.', '1. Stań przodem do ściany w odległości około metra.
2. Oprzyj się o ściane, przenosząc ciężar ciała na przedramiona.
3. Staraj się utrzymać pięty na ziemi. Wytrzymaj 10–20 sekund. Możesz oddalić się od ściany lub podejść bliżej, co odpowiednio zwiększy lub zmniejszy trudność.', NULL, 'free-exercise-db/Calf_Stretch_Elbows_Against_Wall/0.jpg', 'free_exercise_db'),
  ('calf-stretch-hands-against-wall', 'Rozciąganie łydek z dłońmi o ścianę', 'Calf Stretch Hands Against Wall', 'motor_coach', 'beginner', array['Rozciąganie', 'Łydki'], 'Statyczne rozciąganie łydek przy ścianie w rozkroku z jedną nogą wysuniętą do przodu. Opierasz dłonie o ściane i starasz się utrzymać piętę tylnej nogi na ziemi.', '1. Stań przodem do ściany w odległości kilku stóp. Ustaw nogi w wykroku, wystawiając jedną stopę do przodu.
2. Pochyl się do przodu i oprzyj dłonie o ściane, utrzymując piętę, biodro i głowę w jednej linii prostej.
3. Postaraj się utrzymać piętę na ziemi. Wytrzymaj 10–20 sekund, a następnie zmień strony.', NULL, 'free-exercise-db/Calf_Stretch_Hands_Against_Wall/0.jpg', 'free_exercise_db'),
  ('calves-smr', 'Rolowanie łydek (SMR)', 'Calves-SMR', 'motor_coach', 'intermediate', array['Rozciąganie', 'Łydki'], 'Samomasaż łydek wałkiem (rolką). Siedzisz na podłodze, umieszczasz wałek pod łydką i przetaczasz go od kolana do kostki, zatrzymując się na punktach napięcia.', '1. Zacznij siedząc na podłodze. Połóż wałek pod dolną częścią nogi. Druga noga może być skrzyżowana nad pierwszą lub oparta na podłodze, podpierając część twojego ciężaru. To pozycja startowa.
2. Ułóż dłonie po bokach lub tuż za sobą i dociśnij w dół, unoś biodra ponad podłogę, tak aby większość twojego ciężaru spoczęła na mięśniu łydki. Przetaczaj od poniżej kolana do powyżej kostki, zatrzymując się na punktach napięcia na 10–30 sekund. Powtórz na drugiej nodze.', NULL, 'free-exercise-db/Calves-SMR/0.jpg', 'free_exercise_db'),
  ('car-deadlift', 'Martwy ciąg z autem (strongman)', 'Car Deadlift', 'motor_coach', 'intermediate', array['Strongman', 'Uda'], 'Konkurencja strongman — martwy ciąg z bardzo ciężkim aparatem (np. samochodem). Podchodzisz do uchwytów, chwaszczysz je i prostujesz biodra i kolana, unosząc ciężar.', '1. Ten aparat zawodów ma zazwyczaj uchwyty o chwycie neutralnym, jednak niektóre mają prosty drążek, do którego można podejść jak do zwykłego martwego ciągu. Aparat może być obciążony pojazdem lub innymi ciężkimi przedmiotami, takimi jak opony ciągnikowe czy beczki.
2. Ustaw się centralnie między uchwytami, jeśli jesteś silnym przysiadowcem, lub cofnij się o kilka centymetrów, jeśli jesteś silnym martwociągowcem. Stopy powinny być około szerokości bioder. Zegnij się w biodrze, aby chwycić uchwyty. Gdy stopy i chwyt są ustawione, weź głęboki oddech, a następnie obniż biodra i zegnij kolana.
3. Patrz przed siebie, trzymaj klatkę piersiową uniesioną i plecy wygięte, i zacznij odpychać się piętami, aby ruszyć ciężar w górę. Gdy ciężar idzie w górę, ściągnij łopatki do siebie, wypychając biodra do przodu.
4. Opuszczaj ciężar, zginając się w biodrach i prowadząc go na podłogę.', NULL, 'free-exercise-db/Car_Deadlift/0.jpg', 'free_exercise_db'),
  ('car-drivers', 'Kręcenie kierownicą z talerzem', 'Car Drivers', 'motor_coach', 'beginner', array['Siłowe', 'Barki'], 'Ćwiczenie mobilności i siły obrotowej barków. Trzymasz talerz obciążenia przed sobą oburącz i obraca nim jak kierownicą raz w jedną, raz w drugą stronę.', '1. Stojąc wyprostowany, trzymaj talerz obciążenia oburąacz w pozycjach godziny 3 i 9. Dłonie zwrócone ku sobie, ramiona wyciągnięte prosto przed siebie. To pozycja startowa.
2. Rozpocznij ruch, obracając talerzem maksymalnie w jedną stronę. Użyj tego samego rodzaju ruchu, jakiego użyłbyś do przekręcenia kierownicy w jedną stronę.
3. Odwróć ruch, obracając talerz aż do przeciwnej strony.
4. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Car_Drivers/0.jpg', 'free_exercise_db'),
  ('carioca-quick-step', 'Carioca quick step', 'Carioca Quick Step', 'motor_coach', 'beginner', array['Plyometryka', 'Przywodziciele'], 'Ćwiczenie koordynacyjne inspirowane krokiem karaoke. Wykonujesz szybkie kroki boczne z krzyżowaniem nóg, podnosząc kolano i pracując ramionami.', '1. Zacznij ze stopami rozstawionymi na kilka centymetrów, z lewym ramieniem uniesionym w luźnej, atletycznej pozycji.
2. Prawą stopą wykonaj szybki krok za siebie i podciągnij kolano do góry.
3. Wyrzuć ramiona z powrotem do góry, podciągając prawe kolano, dbając o to, by kolano poruszało się prosto w górę i w dół. Unikaj obracania stóp podczas ruchu i patrz cały czas przed siebie, przesuwając się w bok.', NULL, 'free-exercise-db/Carioca_Quick_Step/0.jpg', 'free_exercise_db'),
  ('cat-stretch', 'Rozciąganie kota', 'Cat Stretch', 'motor_coach', 'beginner', array['Rozciąganie', 'Dolny odcinek pleców'], 'Delikatne rozciąganie pleców na czworakach. Wciągasz brzuch i zaokrąglasz kręgosłup, opuszczając głowę.', '1. Ustaw się na podłodze na czworakach.
2. Wciągnij brzuch i zaokrąglij kręgosłup, dolne plecy, barki i szyję, opuszczając głowę.
3. Wytrzymaj 15 sekund.', NULL, 'free-exercise-db/Cat_Stretch/0.jpg', 'free_exercise_db'),
  ('catch-and-overhead-throw', 'Łapanie i rzut znad głowy', 'Catch and Overhead Throw', 'motor_coach', 'beginner', array['Plyometryka', 'Najszersze grzbietu'], 'Ćwiczenie plyometryczne z piłką lekarską. Trzymasz piłkę za głową i gwałtownie wyrzucasz ją do przodu, łapiąc ją po odbiciu.', '1. Zacznij na stojąco, twarzą do ściany lub partnera.
2. Trzymając piłkę oburącz, ustaw ją za głową, maksymalnie się rozciągając, i gwałtownie wyrzuć piłkę do przodu.
3. Upewnij się, że prowadzisz rzut do końca, będąc gotowym przyjąć piłkę wracającą po rzucie. Jeśli rzucasz o ścianę, upewnij się, że stoisz wystarczająco blisko ściany, by przyjąć odbicie, i celuj nieco wyżej niż przy partnerze.', NULL, 'free-exercise-db/Catch_and_Overhead_Throw/0.jpg', 'free_exercise_db'),
  ('chain-handle-extension', 'Prostowanie ramion z uchwytami na łańcuchach', 'Chain Handle Extension', 'motor_coach', 'intermediate', array['Trójbój', 'Triceps'], 'Wariant francuskiego wyciskania na wyciągu z uchwytami połączonymi łańcuchami, wykonywany leżąc na ławce. Prostujesz ramiona nad sobą pracą tricepsa.', '1. Do tego ćwiczenia będziesz potrzebował dwóch uchwytów wyciągu, płaskiej ławki oraz łańcuchów. Przypnij środek łańcuchów do uchwytów i ustaw się na płaskiej ławce. Twoje łokcie powinny być skierowane prosto w górę.
2. Zacznij od wyprostu w łokciach, trzymając ramiona nieruchomo, z nadgarstkami w pronacji.
3. Zatrzymaj się w pełnym wyproście, a następnie odwróć ruch, aby wrócić do pozycji startowej.', NULL, 'free-exercise-db/Chain_Handle_Extension/0.jpg', 'free_exercise_db'),
  ('chain-press', 'Wyciskanie z łańcuchami', 'Chain Press', 'motor_coach', 'intermediate', array['Trójbój', 'Klatka piersiowa'], 'Wyciskanie leżące z uchwytami połączonymi łańcuchami. Opuszczasz uchwyty do klatki, a część łańcucha opada na podłogę, zmieniając opór w trakcie ruchu.', '1. Zacznij od połączenia łańcuchów z uchwytami wyciągu. Ustaw się na płaskiej ławce w tej samej pozycji co przy wyciskaniu hantli. Nadgarstki w pronacji, ramiona prostopadłe do podłogi. To pozycja startowa.
2. Opuszczaj łańcuchy, zginając łokcie, tak aby część łańcucha opadła na podłogę.
3. Kontynuuj, aż łokieć utworzy kąt 90 stopni, a następnie odwróć ruch, prostując łokcie do pełnego wyprostu.', NULL, 'free-exercise-db/Chain_Press/0.jpg', 'free_exercise_db'),
  ('chair-leg-extended-stretch', 'Rozciąganie nogi na krześle', 'Chair Leg Extended Stretch', 'motor_coach', 'beginner', array['Rozciąganie', 'Dwugłowe uda'], 'Rozciąganie siedząc na krześle. Unoś i wyprostowana nogę, zginasz kostkę, po czym odprowadzasz nogę na zewnątrz.', '1. Usiądź prosto na krześle i chwyć siedzisko po bokach.
2. Unoś jedną nogę, prostując kolano i zginając kostkę w trakcie.
3. Powoli odprowadzaj tę nogę na zewnątrz, tak daleko jak możesz, a następnie z powrotem do środka i w dół.
4. Powtórz na drugiej nodze.', NULL, 'free-exercise-db/Chair_Leg_Extended_Stretch/0.jpg', 'free_exercise_db'),
  ('chair-lower-back-stretch', 'Rozciąganie dolnych pleców na krześle', 'Chair Lower Back Stretch', 'motor_coach', 'beginner', array['Rozciąganie', 'Najszersze grzbietu'], 'Proste rozciąganie boczne dolnego odcinka pleców siedząc na krześle. Zegnasz się w bok z ramieniem nad głową.', '1. Usiądź prosto na krześle.
2. Zegnij się w jedną stronę z ramieniem nad głową. Wolną ręką możesz trzymać się krzesła.
3. Wytrzymaj 10 sekund i powtórz na drugą stronę.', NULL, 'free-exercise-db/Chair_Lower_Back_Stretch/0.jpg', 'free_exercise_db'),
  ('chair-squat', 'Przysiad z drążkiem na plecach (styl krzesła)', 'Chair Squat', 'motor_coach', 'beginner', array['Siłowe', 'Uda'], 'Wariant przysiadu z drążkiem na plecach, w którym schodzisz nisko, jakbyś miał usiąść na krześle. Wzmacnia nogi i pośladki, ucząc prawidłowego wzorca przysiadu.', '1. Na początek ustaw drążek na wysokości najlepiej dopasowanej do twojego wzrostu. Gdy drążek jest załadowany, wejdź pod niego i ustaw go na tylnej części barków.
2. Złap drążek dłońmi skierowanymi do przodu, odblokuj go i podnieś z regału, prostując nogi.
3. Przesuń stopy do przodu około 45 cm przed drążek. Ustaw nogi na szerokość barków z palcami lekko skierowanymi na zewnątrz. Cały czas patrz przed siebie i utrzymuj neutralny lub lekko wygięty kręgosłup. To pozycja startowa.
4. Powoli opuszczaj drążek, zginając kolana, utrzymując prostą postawę z uniesioną głową. Schodź, aż kąt między udem a podudciem przekroczy 90 stopni.
5. Zacznij unośić drążek przy wydechu, odpychając podłogę piętami, prostując kolana i wracając do pozycji startowej.
6. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Chair_Squat/0.jpg', 'free_exercise_db'),
  ('chair-upper-body-stretch', 'Rozciąganie górnej części ciała na krześle', 'Chair Upper Body Stretch', 'motor_coach', 'beginner', array['Rozciąganie', 'Barki'], 'Rozciąganie górnej części ciała siedząc na krawędzi krzesła. Trzymasz się oparcia, prostujesz ramiona i pociągasz górną część ciała do przodu, czując rozciągnięcie.', '1. Usiądź na krawędzi krzesła, trzymając się jego oparcia.
2. Wyprostuj ramiona, zachowując proste plecy, i pociągnij górną część ciała do przodu, aż poczujesz rozciągnięcie. Wytrzymaj 20–30 sekund.', NULL, 'free-exercise-db/Chair_Upper_Body_Stretch/0.jpg', 'free_exercise_db'),
  ('chest-and-front-of-shoulder-stretch', 'Rozciąganie klatki i przedniej części barków', 'Chest And Front Of Shoulder Stretch', 'motor_coach', 'beginner', array['Rozciąganie', 'Klatka piersiowa'], 'Rozciąganie klatki piersiowej i przednich aktonów z gryfem lub kijem. Trzymasz kij przed sobą i przenosisz go nad głowę do tyłu.', '1. Zacznij stojąc z nogami złączonymi, trzymając bodybar lub zwykły kij do miotły.
2. Złap kij nieco szerzej niż na szerokość barków i trzymaj go przed sobą dłońmi skierowanymi w dół.
3. Ostrożnie unoś kij w górę i za głowę.', NULL, 'free-exercise-db/Chest_And_Front_Of_Shoulder_Stretch/0.jpg', 'free_exercise_db'),
  ('chest-push-from-3-point-stance', 'Wypchnięcie piłki klatką z pozycji trzypunktowej', 'Chest Push from 3 point stance', 'motor_coach', 'beginner', array['Plyometryka', 'Klatka piersiowa'], 'Ćwiczenie eksplozywne z piłką lekarską z pozycji trzypunktowej (jak na starcie sprintu). Wyrzucasz piłkę do przodu przy pierwszych krokach startu.', '1. Zacznij w pozycji trzypunktowej, w przysiadzie z płaskimi plecami i jedną ręką na ziemi. Połóż piłkę lekarską bezpośrednio przed sobą.
2. Na start wykonaj pierwszy krok, przyciągając piłkę do klatki piersiowej i układając obie dłonie do rzutu.
3. Wykonując drugi krok, eksplozywnie wyrzuć piłkę do przodu maksymalną siłą.', NULL, 'free-exercise-db/Chest_Push_from_3_point_stance/0.jpg', 'free_exercise_db'),
  ('chest-push-multiple-response', 'Wypchnięcie piłki klatką (reakcja wielokrotna)', 'Chest Push (multiple response)', 'motor_coach', 'beginner', array['Plyometryka', 'Klatka piersiowa'], 'Plyometryczny rzut piłką lekarską klatką piersiową w klęku. Wypychasz piłkę maksymalną siłą i natychmiast wracasz do pozycji, by powtórzyć.', '1. Zacznij w klęku twarzą do ściany lub korzystając z partnera. Trzymaj piłkę oburącz mocno dociśniętą do klatki piersiowej.
2. Wykonaj podanie, wybijając się do przodu i na zewnątrz biodrami, wypychając piłkę maksymalnie silnie.
3. Prowadź ruch do końca, padając do przodu i amortyzując upadek dłońmi.
4. Natychmiast wróć do pozycji wyprostowanej. Powtórz żądaną liczbę powtórzeń.', NULL, 'free-exercise-db/Chest_Push_multiple_response/0.jpg', 'free_exercise_db'),
  ('chest-push-single-response', 'Wypchnięcie piłki klatką (reakcja pojedyncza)', 'Chest Push (single response)', 'motor_coach', 'beginner', array['Plyometryka', 'Klatka piersiowa'], 'Pojedynczy plyometryczny rzut piłką lekarską klatką piersiową w klęku. Wypychasz piłkę maksymalną siłą i prowadzisz ruch do końca.', '1. Zacznij w klęku, trzymając piłkę lekarską oburącz mocno dociśniętą do klatki piersiowej.
2. Wykonaj podanie, wybijając się do przodu i na zewnątrz biodrami, wypychając piłkę tak daleko, jak to możliwe.
3. Prowadź ruch do końca, padając do przodu i amortyzując upadek dłońmi.', NULL, 'free-exercise-db/Chest_Push_single_response/0.jpg', 'free_exercise_db'),
  ('chest-push-with-run-release', 'Wypchnięcie piłki klatką z biegiem', 'Chest Push with Run Release', 'motor_coach', 'beginner', array['Plyometryka', 'Klatka piersiowa'], 'Ćwiczenie łączące rzut piłką lekarską z natychmiastowym sprintem. Wypychasz piłkę do przodu i od razu ruszasz biegiem przez 10 jardów.', '1. Zacznij w atletycznej pozycji z ugiętymi kolanami, cofniętymi biodrami i płaskimi plecami. Trzymaj piłkę lekarską blisko nóg. To pozycja startowa.
2. Wykonując pierwszy krok, przyciągnij piłkę lekarską do klatki piersiowej.
3. Wykonując drugi krok, eksplozywnie wypchnij piłkę do przodu, natychmiast ruszając sprintem na 10 jardów po wypuszczeniu piłki. Jeśli jesteś naprawdę szybki, możesz złapać własne podanie!', NULL, 'free-exercise-db/Chest_Push_with_Run_Release/0.jpg', 'free_exercise_db'),
  ('chest-stretch-on-stability-ball', 'Rozciąganie klatki na piłce gimnastycznej', 'Chest Stretch on Stability Ball', 'motor_coach', 'beginner', array['Rozciąganie', 'Klatka piersiowa'], 'Rozciąganie klatki piersiowej z piłką gimnastyczną. Klęczysz przy piłce, opierasz o nią łokieć ramienia i opuszczasz tułów w dół.', '1. Ustaw się na czworakach obok piłki do ćwiczeń.
2. Połóż łokcie na wierzchu piłki, trzymając ramię wyciągnięte na bok. To pozycja startowa.
3. Opuszczaj tułów w kierunku podłogi, trzymając łokieć na piłce. Wytrzymaj w rozciągnięciu 20–30 sekund i powtórz na drugą ramię.', NULL, 'free-exercise-db/Chest_Stretch_on_Stability_Ball/0.jpg', 'free_exercise_db'),
  ('childs-pose', 'Pozycja dziecka', 'Child''s Pose', 'motor_coach', 'beginner', array['Rozciąganie', 'Dolny odcinek pleców'], 'Relaksacyjna pozycja jogi rozciągająca kręgosłup, barki i plecy. Siedzisz na piętach, wyciągając ramiona przed siebie i kładąc czoło na podłodze.', '1. Ustaw się na czworakach i wysuń ręce przed siebie.
2. Opuść pośladki w dół, siadając na piętach. Pozwól ramionom sunąć po podłodze, gdy siadasz z powrotem, rozciągając cały kręgosłup.
3. Gdy usiądziesz na piętach, przysuń dłonie obok stóp i rozluźnij się. „Oddychaj” w plecy. Oprzyj czoło na podłodze. Unikaj tej pozycji, jeśli masz problemy z kolanami.', NULL, 'free-exercise-db/Childs_Pose/0.jpg', 'free_exercise_db'),
  ('chin-to-chest-stretch', 'Rozciąganie brody do klatki', 'Chin To Chest Stretch', 'motor_coach', 'beginner', array['Rozciąganie', 'Kark'], 'Rozciąganie tylnej części szyi. Siedzisz na podłodze, obejmujesz dłońmi z tyłu głowy i delikatnie przyciągasz brodę do klatki piersiowej.', '1. Usiądź na podłodze.
2. Połóż obie dłonie z tyłu głowy, splecione palcami, z kciukami skierowanymi w dół i łokciami skierowanymi prosto przed siebie. Powoli przyciągnij głowę w dół do klatki piersiowej. Wytrzymaj 20–30 sekund.', NULL, 'free-exercise-db/Chin_To_Chest_Stretch/0.jpg', 'free_exercise_db'),
  ('chin-up', 'Podciąganie podchwytem', 'Chin-Up', 'motor_coach', 'beginner', array['Siłowe', 'Najszersze grzbietu'], 'Podciąganie na drążku chwytem podchwytem (dłonie do siebie), węższym niż szerokość barków. Silnie angażuje biceps oraz mięśnie pleców.', '1. Złap drążek do podciągania chwytem, w którym dłonie zwrócone są w stronę tułowia, na rozstaw mniejszy niż szerokość barków.
2. Gdy oba ramiona są wyprostowane przed tobą i trzymasz drążek w wybranym rozstawie, trzymaj tułów tak prosto, jak to możliwe, tworząc wygięcie w dolnych plecach i wypychając klatkę piersiową do przodu. To pozycja startowa. Wskazówka: Utrzymywanie tulowa tak prosto, jak to możliwe, maksymalizuje stymulację bicepsa, minimalizując udział pleców.
3. Wydech wykonuj, podciągając tułów w górę, aż głowa znajdzie się mniej więcej na poziomie drążka. Koncentruj się na pracy mięśni bicepsa. Trzymaj łokcie blisko ciała. Wskazówka: Górna część tulowa powinna pozostać nieruchoma, a poruszać się powinny tylko ramiona. Przedramiona nie powinny wykonywać żadnej innej pracy niż trzymanie drążka.
4. Po sekundzie spięcia bicepsa w pozycji spiętej powoli opuść tulów z powrotem do pozycji startowej, gdy ramiona są w pełni wyprostowane. Wdech wykonuj podczas tej fazy ruchu.
5. Powtórz ten ruch zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Chin-Up/0.jpg', 'free_exercise_db'),
  ('circus-bell', 'Circus Bell (ogromna hantla strongman)', 'Circus Bell', 'motor_coach', 'advanced', array['Strongman', 'Barki'], 'Circus bell to przewymiarowana hantla z grubym uchwytem używana w strongmanie. Podnosisz ją na bark, a następnie wyciskasz nad głowę.', '1. Circus bell to przewymiarowana hantla z grubym uchwytem. Zacznij z hantlą między stopami i złap uchwyt oburącz.
2. Wykonaj wyruk hantli, prostując biodra i kolana, aby dostarczyć sprzęt na wybrane ramię, puszczając drugą ręką.
3. Upewnij się, że jedna z głów hantli znalazła się za barkiem, abyś nie stracił równowagi. Aby unieść ją nad głowę, zrób przysiad zegnając kolana, a następnie wybij się w górę, prostując hantlę nad głowę, lekko odchylając się od niej w trakcie.
4. Ostrożnie zaprowadź dzwon z powrotem na podłogę, utrzymując go pod kontrolą. Najlepiej wykonywać tę konkurencję na grubej gumowej macie, aby zapobiec uszkodzeniu podłogi.', NULL, 'free-exercise-db/Circus_Bell/0.jpg', 'free_exercise_db'),
  ('clean', 'Wyruk', 'Clean', 'motor_coach', 'intermediate', array['Podnoszenie ciężarów', 'Dwugłowe uda'], 'Olimpijskie ćwiczenie polegające na przeniesieniu sztangi z podłogi na barki jednym płynnym ruchem. Składa się z trzech faz ciągnięcia i odbioru sztangi w przysiadzie przednim.', '1. Ze sztangą na podłodze blisko piszczeli złap drążek nachwytem (lub chwytem haczkowym) tuż na zewnątrz nóg. Obniż biodra z ciężarem skupionym na piętach, plecy proste, głowa skierowana do przodu, klatka uniesiona, a barki tuż przed drążkiem. To pozycja startowa.
2. Rozpocznij pierwszy ciąg, odpychając się piętami i prostując kolana. Kąt twoich pleców powinien pozostać taki sam, a ramiona wyprostowane. Prowadź ciężar z kontrolą, kontynuując aż powyżej kolan.
3. Następnie następuje drugi ciąg, główne źródło przyspieszenia w wyruku. Gdy drążek zbliża się do pozycji środkowej części uda, zacznij prostować biodra. W ruchu podobnym do wyskoku przyspiesz, prostując biodra, kolana i kostki, używając szybkości, aby ruszyć drążek w górę. Nie ma potrzeby aktywnego ciągnięcia ramionami, aby przyspeedzieć ciężar; na końcu drugiego ciągu ciało powinno być w pełni wyprostowane, lekko odchylone do tyłu, z ramionami nadal wyprostowanymi.
4. Gdy osiągnięty zostanie pełny wyprost, przejdź do trzeciego ciągu, agresywnie unosząc barki i zginając ramiona z łokciami skierowanymi w górę i na boki. Przy szczycie wyprostu agresywnie pociągnij siebie w dół, obracając łokcie pod drążek. Przyjmij drążek w pozycji przysiadu przedniego, której głębokość zależy od wysokości drążka na końcu trzeciego ciągu. Drążek powinien zostać przyjęty na wysunięte barki, delikatnie dotykając gardła, z rozluźnionymi dłońmi. Kontynuuj opuszczanie do dolnej pozycji przysiadu, co pomoże w powrocie.
5. Natychmiast wróć do góry, odpychając się piętami, utrzymując tułów wyprostowany i łokcie wysoko. Kontynuuj, aż wstaniesz do pozycji stojącej.', NULL, 'free-exercise-db/Clean/0.jpg', 'free_exercise_db'),
  ('clean-and-jerk', 'Wyruk i podrzut', 'Clean and Jerk', 'motor_coach', 'advanced', array['Podnoszenie ciężarów', 'Barki'], 'Olimpijskie dwubojowe ćwiczenie. Najpierw wyrukujesz sztangę na barki, a następnie podrzucasz ją nad głowę dynamicznym wybiciem.', '1. Ze sztangą na podłodze blisko piszczeli złap drążek nachwytem lub chwytem haczkowym tuż na zewnątrz nóg. Obniż biodra z ciężarem skupionym na piętach, plecy proste, głowa skierowana do przodu, klatka uniesiona, a barki tuż przed drążkiem. To pozycja startowa.
2. Rozpocznij pierwszy ciąg, odpychając się piętami i prostując kolana. Kąt pleców powinien pozostać taki sam, a ramiona wyprostowane. Prowadź ciężar z kontrolą, kontynuując aż powyżej kolan.
3. Następnie następuje drugi ciąg, główne źródło przyspieszenia w wyruku. Gdy drążek zbliża się do pozycji środkowej części uda, zacznij prostować biodra. W ruchu podobnym do wyskoku przyspiesz, prostując biodra, kolana i kostki, używając szybkości, aby ruszyć drążek w górę. Nie ma potrzeby aktywnego ciągnięcia ramionami, aby przyspeedzieć ciężar; na końcu drugiego ciągu ciało powinno być w pełni wyprostowane, lekko odchylone do tyłu, z ramionami nadal wyprostowanymi.
4. Gdy osiągnięty zostanie pełny wyprost, przejdź do trzeciego ciągu, agresywnie unosząc barki i zginając ramiona z łokciami skierowanymi w górę i na boki. Przy szczycie wyprostu agresywnie pociągnij siebie w dół, obracając łokcie pod drążek. Przyjmij drążek w pozycji przysiadu przedniego, której głębokość zależy od wysokości drążka na końcu trzeciego ciągu. Drążek powinien zostać przyjęty na wysunięte barki, delikatnie dotykając gardła, z rozluźnionymi dłońmi. Kontynuuj opuszczanie do dolnej pozycji przysiadu, co pomoże w powrocie.
5. Natychmiast wróć do góry, odpychając się piętami, utrzymując tułów wyprostowany i łokcie wysoko. Kontynuuj, aż wstaniesz do pozycji stojącej.
6. Druga faza to podrzut, który unosi ciężar nad głowę. Stojąc z ciężarem na przedniej części barków, zacznij od przysiadu przygotowawczego. Ze stopami dokładnie pod biodrami zegnij kolana, nie cofając bioder do tyłu. Schodź tylko nieznacznie i odwróć kierunek ruchu maksymalnie gwałtownie.
7. Odpychaj się piętami, generując maksymalną szybkość i siłę, i pamiętaj, aby odsunąć głowę z drogi, gdy drążek opuszcza barki.
8. W tym momencie, gdy stopy opuszczają podłogę, muszą zostać ustawione w pozycji odbioru tak szybko, jak to możliwe. W krótkiej chwili, gdy stopy nie odpychają aktywnie od platformy, wysiłek zawodnika, by wypchnąć drążek w górę, sprawi, że opadnie on w dół. Stopy powinny być w rozkroku — jedna noga z przodu, druga z tyłu. Przyjmij drążek z ramionami zablokowanymi nad głową. Wróć do pozycji stojącej.', NULL, 'free-exercise-db/Clean_and_Jerk/0.jpg', 'free_exercise_db'),
  ('clean-and-press', 'Wyruk i wyciskanie', 'Clean and Press', 'motor_coach', 'intermediate', array['Siłowe', 'Barki'], 'Połączenie wyruku sztangi na barki z wyciskaniem jej nad głowę. Najpierw wyrukujesz sztangę, po czym wyciskasz ją nad głowę bez pomocy nóg.', '1. Przyjmij rozstaw na szerokość barków, z kolanami wewnątrz ramion. Zachowując płaskie plecy, zegnij kolana i biodra, aby chwycić drążek z wyprostowanymi ramionami i chwytem nachwytem nieco szerszym niż szerokość barków. Skieruj łokcie na boki. Drążek powinien być blisko piszczeli. Ustaw barki nad drążkiem lub nieco przed nim. Przyjmij postawę z płaskimi plecami. To pozycja startowa.
2. Zacznij ciągnąć drążek, prostując kolana. Prowadź biodra do przodu i unoś barki w tym samym tempie, zachowując stały kąt pleców; kontynuuj unośenie drążka prosto w górę, trzymając go blisko ciała.
3. Gdy drążek mija kolano, gwałtownie wyprostuj kostki, kolana i biodra, podobnie jak przy wyskoku. Kontynuuj prowadzenie drążka rękami, unosząc barki i używając pędu ruchu, aby pociągnąć drążek maksymalnie wysoko. Drążek powinien podróżować blisko ciała, a łokcie trzymaj na boki.
4. Przy maksymalnej wysokości stopy mogą oderwać się od podłogi i zacznij pociągać siebie pod drążek. Mechanika może się nieco różnić w zależności od użytego ciężaru. Powinieneś opaść do pozycji przysiadu, pociągając siebie pod drążek.
5. Gdy drążek osiągnie najwyższy punkt, obróć łokcie wokół i pod drążek. Przyjmij drążek na przednią część barków, utrzymując tors wyprostowany i zginając biodra i kolana, aby przejąć wagę drążka.
6. Wstań do pełnej wysokości, trzymając drążek w pozycji wyruku.
7. Bez przestawiania stóp wyciśnij drążek nad głowę przy wydechu. Opuść drążek z kontrolą.', NULL, 'free-exercise-db/Clean_and_Press/0.jpg', 'free_exercise_db'),
  ('clean-deadlift', 'Martwy ciąg stylem wyruku', 'Clean Deadlift', 'motor_coach', 'beginner', array['Podnoszenie ciężarów', 'Dwugłowe uda'], 'Martwy ciąg techniką stosowaną w wyruku. Podnosisz sztangę z podłogi z bardziej pionowym torsem i sztangą blisko ciała, kończąc pełnym wyprostem bioder i kolan.', '1. Zacznij stojąc ze sztangą blisko piszczeli. Stopy dokładnie pod biodrami, lekko skierowane na zewnątrz. Chwyć drążek podchwytem oburącz lub chwytem haczkowym, około na szerokość barków. Siądź do drążka. Kręgosłup w pełnym wyproście, z kątem pleców takim, który umieszcza barki przed drążkiem, a plecy tak pionowe, jak to możliwe.
2. Zacznij od odpychania się od podłogi przez przednią część pięt. Gdy drążek podróżuje w górę, utrzymuj stały kąt pleców. Rozprowadź kolana na boki, aby pomóc utrzymać je poza torem drążka.
3. Po tym, jak drążek minie kolana, zakończ podnoszenie, wpychając biodra w drążek, aż biodra i kolana będą wyprostowane.', NULL, 'free-exercise-db/Clean_Deadlift/0.jpg', 'free_exercise_db'),
  ('clean-from-blocks', 'Wyruk z bloków', 'Clean from Blocks', 'motor_coach', 'intermediate', array['Podnoszenie ciężarów', 'Uda'], 'Wariant wyruku startujący ze sztangą ustawionej na blokach lub podstawach zamiast na podłodze. Technika identyczna jak w wyruku, ale skrócony zakres ruchu.', '1. Ze sztangą na skrzyniach lub podstawach o żądanej wysokości złap drążek nachwytem lub chwytem haczkowym tuż na zewnątrz nóg. Obniż biodra z ciężarem skupionym na piętach, plecy proste, głowa skierowana do przodu, klatka uniesiona, a barki tuż przed drążkiem. To pozycja startowa.
2. Rozpocznij pierwszy ciąg, odpychając się piętami i prostując kolana. Kąt pleców powinien pozostać taki sam, a ramiona wyprostowane z łokciami skierowanymi na zewnątrz.
3. Gdy osiągnięty zostanie pełny wyprost, przejdź do pozycji odbioru, agresywnie unosząc barki i zginając ramiona z łokciami skierowanymi w górę i na boki. Agresywnie pociągnij siebie w dół, obracając łokcie pod drążek. Przyjmij drążek w pozycji przysiadu przedniego, której głębokość zależy od wysokości drążka na końcu trzeciego ciągu. Drążek powinien zostać przyjęty na wysunięte barki, delikatnie dotykając gardła, z rozluźnionymi dłońmi. Kontynuuj opuszczanie do dolnej pozycji przysiadu, co pomoże w powrocie.
4. Natychmiast wróć do góry, odpychając się piętami, utrzymując tułów wyprostowany i łokcie wysoko. Kontynuuj, aż wstaniesz do pozycji stojącej. Opuść ciężar z powrotem na skrzynie do następnego powtórzenia.', NULL, 'free-exercise-db/Clean_from_Blocks/0.jpg', 'free_exercise_db'),
  ('clean-pull', 'Ciąg wyruku (clean pull)', 'Clean Pull', 'motor_coach', 'intermediate', array['Podnoszenie ciężarów', 'Uda'], 'Fragment wyruku treningowy bez odbioru sztangi na barki. Wykonujesz dwa ciągi, eksplozywnie prostując biodra, kolana i kostki, unosząc sztangę maksymalnie wysoko.', '1. Ze sztangą na podłodze blisko piszczeli złap drążek nachwytem lub chwytem haczkowym tuż na zewnątrz nóg. Obniż biodra z ciężarem skupionym na piętach, plecy proste, głowa skierowana do przodu, klatka uniesiona, a barki tuż przed drążkiem. To pozycja startowa.
2. Rozpocznij pierwszy ciąg, odpychając się piętami i prostując kolana. Kąt pleców powinien pozostać taki sam, a ramiona wyprostowane z łokciami skierowanymi na zewnątrz. Prowadź ciężar z kontrolą, kontynuując aż powyżej kolan.
3. Następnie następuje drugi ciąg, główne źródło przyspieszenia w wyruku. Gdy drążek zbliża się do pozycji środkowej części uda, zacznij prostować biodra. W ruchu podobnym do wyskoku przyspiesz, prostując biodra, kolana i kostki, używając szybkości, aby ruszyć drążek w górę. Nie ma potrzeby aktywnego ciągnięcia ramionami, aby przyspeedzieć ciężar; na końcu drugiego ciągu ciało powinno być w pełni wyprostowane, lekko odchylone do tyłu, z ramionami nadal wyprostowanymi. Pełny wyprost powinien być gwałtowny i zdecydowany; nie przedłużaj wyprostu dłużej, niż to konieczne.', NULL, 'free-exercise-db/Clean_Pull/0.jpg', 'free_exercise_db'),
  ('clean-shrug', 'Szruhsy stylem wyruku', 'Clean Shrug', 'motor_coach', 'beginner', array['Podnoszenie ciężarów', 'Czworoboczne'], 'Szruhsy w technice wyruku, z drążkiem na wysokości środka uda. Barki wyrzucasz agresywnie w górę, w kierunku uszu.', '1. Zacznij z chwytem na szerokość barków, podchwytem oburącz lub chwytem haczkowym, z drążkiem wiszącym na wysokości środka uda. Plecy proste i lekko pochylone do przodu.
2. Wyrzuć barki w kierunku uszu. Choć to ćwiczenie można zwykle obciążać większym ciężarem niż wyruk, unikaj przeładowania do tego stopnia, że wykonanie zwalnia.', NULL, 'free-exercise-db/Clean_Shrug/0.jpg', 'free_exercise_db'),
  ('clock-push-up', 'Pompki zegarowe', 'Clock Push-Up', 'motor_coach', 'intermediate', array['Siłowe', 'Klatka piersiowa'], 'Dynamiczna wersja pompki z przeskokiem w bok po każdej powtórzeniu. Poruszasz się wokół własnej osi jak wskazówka zegara, pracując klatką, barkami i mięśniami głębokimi.', '1. Przyjmij pozycję leżącą przodem na podłodze, podpierając się na dłoniach i palcach stóp.
2. Ramiona powinny być w pełni wyprostowane, dłonie około na szerokość barków. Trzymaj ciało prosto w całym ruchu. To pozycja startowa.
3. Opuszczaj się, zginając łokcie, obniżając klatkę w kierunku podłogi.
4. Na dole odwróć ruch, odpychając się w górę przez wyprost łokci tak szybko, jak to możliwe, aż oderwiesz się od ziemi. Celuj w "przeskok" o 30–45 cm w jedną stronę.
5. Przyspieszając w górę, przesuń zewnętrzną stopę w kierunku przeciwnym do kierunku ruchu. Odrając się od ziemi, obróć ciało o około 30 stopni do kolejnego powtórzenia.
6. Wróć do pozycji startowej i powtarzaj ćwiczenie, obchodząc pełne koło, aż wrócisz do punktu wyjścia.', NULL, 'free-exercise-db/Clock_Push-Up/0.jpg', 'free_exercise_db'),
  ('close-grip-barbell-bench-press', 'Wyciskanie sztangi leżąc wąskim chwytem', 'Close-Grip Barbell Bench Press', 'motor_coach', 'beginner', array['Siłowe', 'Triceps'], 'Wyciskanie sztangi leżąc na płaskiej ławce wąskim chwytem (szerokość barków). Mocno angażuje triceps, obok klatki piersiowej.', '1. Połóż się na płaskiej ławce. Wąskim chwytem (około szerokości barków) podnieś sztangę z regału i trzymaj ją prosto nad sobą z wyprostowanymi ramionami. To pozycja startowa.
2. Wdech wykonuj, schodząc powoli, aż poczujesz sztangę na środkowej części klatki piersiowej. Wskazówka: W przeciwieństwie do zwykłego wyciskania na ławce trzymaj łokcie blisko tułowia przez cały czas, aby zmaksymalizować udział tricepsa.
3. Po pauzie wróć sztangę do pozycji startowej przy wydechu, wypychając ją pracą tricepsa. Zablokuj ramiona w pozycji spiętej, zatrzymaj się na sekundę, a potem znów zacznij schodzić powoli. Wskazówka: Zejście powinno trwać co najmniej dwa razy dłużej niż wypchanie.
4. Powtórz ruch zalecaną liczbę powtórzeń.
5. Po zakończeniu odłóż sztangę z powrotem na regał.', NULL, 'free-exercise-db/Close-Grip_Barbell_Bench_Press/0.jpg', 'free_exercise_db'),
  ('close-grip-dumbbell-press', 'Wyciskanie hantli wąskim chwytem', 'Close-Grip Dumbbell Press', 'motor_coach', 'beginner', array['Siłowe', 'Triceps'], 'Wyciskanie jednej hantli oburącz leżąc na ławce, z dłońmi dociśniętymi do boków hantli. Wariant wyciskania skupiony na tricepsie i wewnętrznej części klatki.', '1. Postaw hantlę pionowo na płaskiej ławce.
2. Dbając o to, by hantla była bezpiecznie umieszczona na górze ławki, połóż się prostopadle do ławki, tak aby na jej powierzchni spoczywały tylko barki. Biodra poniżej ławki, nogi ugięte ze stopami pewnie na podłodze.
3. Złap hantlę oburącz i trzymaj ją prosto nad klatką na wyprostowanych ramionach. Obie dłonie powinny dociskać się do dolnych boków hantli. To pozycja startowa.
4. Rozpocznij ruch, opuszczając hantlę do klatki piersiowej.
5. Wróć do pozycji startowej prostując łokcie.', NULL, 'free-exercise-db/Close-Grip_Dumbbell_Press/0.jpg', 'free_exercise_db'),
  ('close-grip-ez-bar-curl', 'Uginanie ramion wąskim chwytem na gryfie EZ', 'Close-Grip EZ Bar Curl', 'motor_coach', 'beginner', array['Siłowe', 'Biceps'], 'Klasyczne uginanie ramion na biceps gryfem EZ w wąskim podchwycie, stojąc. Łokcie blisko tulowa, ruch tylko w łokciach.', '1. Stań z wyprostowanym tulowem trzymając gryf EZ na wewnętrznym, bliższym uchwycie. Dłonie zwrócone do przodu, lekko przechylone do środka przez kształt gryfu. Łokcie blisko tulowa. To pozycja startowa.
2. Trzymając ramiona nieruchomo, unoś ciężar do przodu spinając biceps przy wydechu. Wskazówka: Poruszać się powinny tylko przedramiona.
3. Kontynuuj ruch, aż biceps będzie w pełni spięty, a gryf na wysokości barków. Utrzymaj pozycję spiętą przez sekundę i mocno zaciśnij biceps.
4. Powoli zacznij wracać gryfem do pozycji startowej robiąc wdech.
5. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Close-Grip_EZ_Bar_Curl/0.jpg', 'free_exercise_db'),
  ('close-grip-ez-bar-curl-with-band', 'Uginanie ramion wąskim chwytem na gryfie EZ z gumą', 'Close-Grip EZ-Bar Curl with Band', 'motor_coach', 'beginner', array['Siłowe', 'Biceps'], 'Uginanie ramion na biceps gryfem EZ w wąskim podchwycie z dodatkowym oporem gumy oporowej. Stajesz na gumie, aby zwiększyć napięcie w górnej fazie ruchu.', '1. Zamocuj gumę na każdym końcu gryfu. Weź gryf, stając stopą na środku gumy. Stań wyprostowany z wąskim chwytem podchwytem na gryfie EZ. Łokcie blisko tułowia. To pozycja startowa.
2. Trzymając ramiona w miejscu, zginasz łokcie wykonując uginanie. Wydech wykonuj podczas unośenia ciężaru.
3. Kontynuuj ruch, aż biceps będzie w pełni spięty, a gryf na wysokości barków. Utrzymaj pozycję spiętą przez sekundę i mocno zaciśnij biceps.
4. Powoli zacznij wracać gryfem do pozycji startowej robiąc wdech.
5. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Close-Grip_EZ-Bar_Curl_with_Band/0.jpg', 'free_exercise_db'),
  ('close-grip-ez-bar-press', 'Wyciskanie wąskim chwytem gryfu EZ', 'Close-Grip EZ-Bar Press', 'motor_coach', 'beginner', array['Siłowe', 'Triceps'], 'Wyciskanie leżące gryfem EZ wąskim chwytem, z łokciami blisko tulowa. Wariant wyciskania skupiony na tricepsie.', '1. Połóż się na płaskiej ławce z gryfem EZ załadowanym odpowiednim ciężarem.
2. Wąskim chwytem podnieś gryf i trzymaj go prosto nad torsem z łokciami blisko ciała. Ramiona powinny być prostopadłe do podłogi. To pozycja startowa.
3. Teraz opuść gryf do dolnej części klatki piersiowej robiąc wdech. Trzymaj łokcie blisko tułowia podczas tego ruchu.
4. Wypchnij gryf z powrotem do pozycji startowej pracą tricepsa, prostując łokcie przy wydechu.
5. Powtórz.', NULL, 'free-exercise-db/Close-Grip_EZ-Bar_Press/0.jpg', 'free_exercise_db'),
  ('close-grip-front-lat-pulldown', 'Ściąganie drążka wyciągu górnego wąskim chwytem', 'Close-Grip Front Lat Pulldown', 'motor_coach', 'beginner', array['Siłowe', 'Najszersze grzbietu'], 'Ściąganie drążka wyciągu górnego wąskim chwytem do górnej części klatki. Angażuje najszersze mięśnie pleców i biceps.', '1. Usiądź przy maszynie do ściągania z szerokim drążkiem zamocowanym do górnego krążka. Upewnij się, że regulacja poduszki kolanowej pasuje do twojego wzrostu. Te poduszki zapobiegną unośeniu ciała przez opór drążka.
2. Złap drążek dłońmi skierowanymi do przodu w przepisanym rozstawie. Uwaga o chwytach: Przy szerokim chwycie dłonie muszą być rozstawione szerzej niż szerokość barków. Przy średnim chwycie — na szerokość barków, a przy wąskim — węższej niż szerokość barków.
3. Gdy oba ramiona są wyprostowane przed tobą — trzymając drążek w wybranym rozstawie — odchyl tułów do tyłu o około 30 stopni, tworząc wygięcie w dolnych plecach i wypychając klatkę piersiową do przodu. To pozycja startowa.
4. Wydech wykonuj, ściągając drążek w dół, aż dotknie górnej części klatki piersiowej, prowadząc barki i ramiona w dół i do tyłu. Wskazówka: Koncentruj się na spięciu mięśni pleców, gdy osiągniesz pełną pozycję spiętą. Górna część tulowa powinna pozostać nieruchoma (poruszać się powinny tylko ramiona). Przedramiona nie powinny wykonywać żadnej innej pracy poza trzymaniem drążka; nie próbuj więc ściągać drążka pracą przedramion.
5. Po sekundzie w pozycji spiętej, spinając łopatki do siebie, powoli unoś drążek z powrotem do pozycji startowej, gdy ramiona są w pełni wyprostowane, a najszersze mięśnie pleców w pełni rozciągnięte. Wdech wykonuj podczas tej fazy ruchu.
6. 6. Powtórz ten ruch zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Close-Grip_Front_Lat_Pulldown/0.jpg', 'free_exercise_db'),
  ('close-grip-push-up-off-of-a-dumbbell', 'Pompki wąskie na hantli', 'Close-Grip Push-Up off of a Dumbbell', 'motor_coach', 'intermediate', array['Siłowe', 'Triceps'], 'Wąskie pompki z jedną dłonią na stojącej hantli. Triceps pracuje intensywniej dzięki wąskiej pozycji łokci przy tulowie.', '1. Połóż się na podłodze i połóż dłonie na stojącej hantli. Podpierając się na palcach stóp i dłoniach, trzymaj tors sztywny, a łokcie blisko ciała z ramionami wyprostowanymi. To pozycja startowa.
2. Opuszczaj ciało, pozwalając łokciom się zginać, robiąc wdech. Trzymaj ciało prosto, nie pozwalając biodrom się unośić ani opadać.
3. Odepchnij się z powrotem do pozycji startowej prostując łokcie. Wydech wykonuj podczas tego kroku.
4. Po pauzie w pozycji spiętej powtórz ruch zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Close-Grip_Push-Up_off_of_a_Dumbbell/0.jpg', 'free_exercise_db'),
  ('close-grip-standing-barbell-curl', 'Uginanie ramion ze sztangą wąskim chwytem stojąc', 'Close-Grip Standing Barbell Curl', 'motor_coach', 'beginner', array['Siłowe', 'Biceps'], 'Uginanie ramion na biceps sztangą w wąskim podchwycie, stojąc. Ruch tylko w łokciach; ramiona i łokcie pozostają nieruchome przy tulowie.', '1. Trzymaj sztangę oburącz, dłońmi do góry, kilka centymetrów od siebie.
2. Stań z prostym tulowem i uniesioną głową. Stopy około na szerokość barków, łokcie blisko tulowa. To pozycja startowa. Wskazówka: Ramiona i łokcie pozostają nieruchome w całym ruchu.
3. Unoś sztangę półkolistym ruchem, aż przedramiona dotkną bicepsów. Wydech wykonuj podczas tej fazy ruchu i mocno zepnij biceps na sekundę na górze. Wskazówka: Unikaj wyginania pleców lub ruchów wymachowych przy unośeniu ciężaru. Poruszać się powinny tylko przedramiona.
4. Powoli wróć do pozycji startowej robiąc wdech.
5. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Close-Grip_Standing_Barbell_Curl/0.jpg', 'free_exercise_db'),
  ('cocoons', 'Kokony (crunch z nogami i ramionami)', 'Cocoons', 'motor_coach', 'beginner', array['Siłowe', 'Brzuch'], 'Crunch z jednoczesnym przyciąganiem kolan do klatki i ramion znad głowy. Leżysz na plecach i spinasz cały mięsień prosty brzucha.', '1. Zacznij leżąc na plecach na podłodze. Nogi proste, ramiona wyciągnięte za głową. To pozycja startowa.
2. Aby wykonać ruch, przyciągnij kolana w kierunku klatki, obracając miednicę, aby unoś pośladki ponad podłogę. Jednocześnie zegnij kręgosłup, prowadząc ramiona z powrotem nad głowę, wykonując jednoczesny ruch spięcia.
3. Po krótkiej pauzie wróć do pozycji startowej.', NULL, 'free-exercise-db/Cocoons/0.jpg', 'free_exercise_db'),
  ('conans-wheel', 'Koło Conana (strongman)', 'Conan''s Wheel', 'motor_coach', 'intermediate', array['Strongman', 'Uda'], 'Konkurencja strongman polegająca na noszeniu ciężkiego aparatu zaczepionego pod łokciami. Idziesz po okręgu, utrzymując ciężar, aż stracisz siłę.', '1. Z załadowanym ciężarem złap koniec aparatu chwytem zurcher. Połóż drążek w zagięciu łokcia i trzymaj się swojego nadgarstka. Staraj się nie przenosić ciężaru na przedramiona.
2. Zacznij od unośenia ciężaru z ziemi. Zachowaj ciasną, wyprostowaną postawę, gdy zaczniesz chodzić, robiąc krótkie, szybkie kroki. Patrz w górę i w bok, obracając się po kole. Nie wstrzymuj oddechu podczas konkurencji. Chodź dalej, aż wykonasz jeden lub więcej pełnych obrotów.', NULL, 'free-exercise-db/Conans_Wheel/0.jpg', 'free_exercise_db'),
  ('concentration-curls', 'Uginanie ramion koncentrowane', 'Concentration Curls', 'motor_coach', 'beginner', array['Siłowe', 'Biceps'], 'Izolowane uginanie ramion na biceps siedząc, z łokciem opartym o wewnętrzną część uda. Klasyczne ćwiczenie budujące szczyt bicepsa.', '1. Usiądź na płaskiej ławce z hantlą przed sobą między nogami. Nogi rozstawione, kolana ugięte, stopy na podłodze.
2. Prawą ręką podnieś hantlę. Umieść tylną część prawego ramienia na wewnętrznej części prawego uda. Obróć dłoń, aż będzie skierowana do przodu, od uda. Wskazówka: Ramię powinno być wyprostowane, a hantla nad podłogą. To pozycja startowa.
3. Trzymając ramię nieruchomo, unoś ciężar do przodu spinając biceps przy wydechu. Poruszać się powinno tylko przedramię. Kontynuuj ruch, aż biceps będzie w pełni spięty, a hantla na wysokości barków. Wskazówka: Na górze ruchu upewnij się, że mały palec twojej ręki jest wyżej niż kciuk. Gwarantuje to dobre spięcie. Utrzymaj pozycję spiętą przez sekundę, spinając biceps.
4. Powoli zacznij wracać hantlą do pozycji startowej robiąc wdech. Uwaga: Unikaj ruchów wymachowych w każdej chwili.
5. Powtórz zalecaną liczbę powtórzeń. Następnie wykonaj ten sam ruch lewą ręką.', NULL, 'free-exercise-db/Concentration_Curls/0.jpg', 'free_exercise_db'),
  ('cross-body-crunch', 'Spięcia brzucha na krzyż', 'Cross-Body Crunch', 'motor_coach', 'beginner', array['Siłowe', 'Brzuch'], 'Crunch z jednoczesnym łączeniem przeciwległego łokcia i kolana. Angażuje mięsień prosty i skośne brzucha.', '1. Połóż się płasko na plecach i zegnij kolana o około 60 stopni.
2. Trzymaj stopy płasko na podłodze i połóż dłonie luźno za głową. To pozycja startowa.
3. Teraz unoś się i prowadź prawy łokieć i bark przez ciało, jednocześnie przyciągając lewe kolano w kierunku lewego barku. Sięgaj łokciem, próbując dotknąć kolana. Wydech wykonuj podczas tego ruchu. Wskazówka: Spróbuj unoś bark w kierunku kolana, a nie tylko łokieć; kluczem jest spinanie mięśni brzucha podczas ruchu, a nie samo przesuwanie łokcia.
4. Teraz wróć w dół do pozycji startowej robiąc wdech i powtórz z lewym łokciem i prawym kolanem.
5. Kontynuuj naprzemiennie w ten sposób, aż wszystkie zalecane powtórzenia zostaną wykonane.', NULL, 'free-exercise-db/Cross-Body_Crunch/0.jpg', 'free_exercise_db'),
  ('cross-body-hammer-curl', 'Młotkowe uginanie ramion na krzyż', 'Cross Body Hammer Curl', 'motor_coach', 'beginner', array['Siłowe', 'Biceps'], 'Młotkowe uginanie hantli w kierunku przeciwnego barku. Bez rotacji ramienia; angażuje biceps i przedramiona.', '1. Stań wyprostowany z hantlą w każdej dłoni. Ręce swobodnie przy bokach, dłonie skierowane do środka.
2. Trzymając dłonie skierowane do środka i bez obracania ramienia, unoś prawą hantlę w kierunku lewego barku przy wydechu. Dotknij szczytem hantli barku i utrzymaj spięcie przez sekundę.
3. Powoli opuść hantlę tą samą drogą robiąc wdech, a następnie powtórz ten sam ruch dla lewej ręki.
4. Kontynuuj naprzemiennie w ten sposób, aż wykonasz zalecaną liczbę powtórzeń dla każdej ręki.', NULL, 'free-exercise-db/Cross_Body_Hammer_Curl/0.jpg', 'free_exercise_db'),
  ('cross-over-with-bands', 'Krzyżowanie ramion z gumą oporową', 'Cross Over - With Bands', 'motor_coach', 'beginner', array['Siłowe', 'Klatka piersiowa'], 'Wariant rozpiętek krzyżowanych na klatkę z gumą oporową zaczepioną za Tobą. Ramiona łączysz przed klatką półkolistym ruchem.', '1. Zaczep gumę oporową wokół stabilnego słupa.
2. Tyłem do słupa złap uchwyty na obu końcach gumy i zrób krok do przodu, aby napnąć gumę.
3. Unoś ramiona na boki, równolegle do podłogi, prostopadle do tulowa (tulów i ramiona powinny przypominać literę "T") i z dłońmi skierowanymi do przodu. Ramiona wyprostowane z lekkim ugięciem łokci. To pozycja startowa.
4. Trzymając ramiona prosto, przeciągnij je w poprzek klatki półkolistym ruchem do przodu przy wydechu, spinając mięśnie klatki. Utrzymaj spięcie przez sekundę.
5. Powoli wróć do pozycji startowej robiąc wdech.
6. Wykonuj zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Cross_Over_-_With_Bands/0.jpg', 'free_exercise_db'),
  ('crossover-reverse-lunge', 'Wykrok wsteczny z przejściem na ukos', 'Crossover Reverse Lunge', 'motor_coach', 'intermediate', array['Rozciąganie', 'Dolny odcinek pleców'], 'Wykrok w tył z jednoczesnym obrotem tulowa przez przednią nogę. Angażuje nogi, pośladki i mięśnie skośne brzucha.', '1. Stań ze stopami na szerokość barków. To pozycja startowa.
2. Wykonaj wykrok w tył, cofając jedną stopę i zginając biodra oraz kolano przedniej nogi. Przy tym obróć tulów przez przednią nogę.
3. Po krótkiej pauzie wróć do pozycji startowej i powtórz na drugiej stronie, kontynuując naprzemiennie.', NULL, 'free-exercise-db/Crossover_Reverse_Lunge/0.jpg', 'free_exercise_db'),
  ('crucifix', 'Krzyż (utrzymanie ciężarów na bokach)', 'Crucifix', 'motor_coach', 'beginner', array['Strongman', 'Barki'], 'Konkurencja strongman — statyczne utrzymanie ciężarów w wyciągniętych ramionach na bokach przez czas. Buduje wytrzymałość barków.', '1. W krzyżu statycznie trzymasz ciężary na bokach przez czas. Choć konkurencję można ćwiczyć z hantlami, najlepiej ćwiczyć z jednym z różnych sprzętów, takich jak topory czy młoty, ponieważ czuje się to inaczej.
2. Zacznij stojąc, i unoś ramiona na boki trzymając sprzęt. Ramiona powinny być równoległe do ziemi. Na zawodach sędziowie lub czujniki informują cię, kiedy złamiesz równoległość. Trzymaj tak długo, jak możesz. Zazwyczaj ciężary powinny być na tyle duże, aby zawieść cię w 30–60 sekund.', NULL, 'free-exercise-db/Crucifix/0.jpg', 'free_exercise_db'),
  ('crunch-hands-overhead', 'Spięcia brzucha z ramionami nad głową', 'Crunch - Hands Overhead', 'motor_coach', 'beginner', array['Siłowe', 'Brzuch'], 'Crunch z ramionami wyciągniętymi nad głową. Unoś tylko łopatki ponad podłogę, spinając górną część mięśnia prostego brzucha.', '1. Leż na podłodze plecami płasko, z ugiętymi kolanami pod kątem około 60 stopni między dwugłowymi ud a łydkami.
2. Trzymaj stopy płasko na podłodze i wyciągnij ramiona nad głową z skrzyżowanymi dłońmi. To pozycja startowa.
3. Unoś górną część ciała do przodu, unoś łopatki tuż ponad podłogę. Cały czas trzymaj ramiona w linii z głową, szyją i barkiem. Nie przesuwaj ich do przodu z tej pozycji. Wydech wykonuj podczas tej fazy ruchu i utrzymaj spięcie przez sekundę.
4. Powoli opuszczaj się do pozycji startowej robiąc wdech.
5. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Crunch_-_Hands_Overhead/0.jpg', 'free_exercise_db'),
  ('crunch-legs-on-exercise-ball', 'Spięcia brzucha z nogami na piłce', 'Crunch - Legs On Exercise Ball', 'motor_coach', 'beginner', array['Siłowe', 'Brzuch'], 'Crunch z nogami opartymi na piłce gimnastycznej, kolanach ugiętych pod 90 stopni. Unoś tylko barki ponad podłogę, spinając mięśnie brzucha.', '1. Leż płasko na plecach ze stopami opartymi o piłkę do ćwiczeń i kolanami ugiętymi pod kątem 90 stopni.
2. Ustaw stopy w rozstawie 8–10 cm i skieruj palce do środka, tak aby się stykały.
3. Połóż dłonie lekko po obu stronach głowy, trzymając łokcie blisko. Wskazówka: Nie splataj palców za głową.
4. Dociśnij dolną część pleców do podłogi, aby lepiej izolować mięśnie brzucha. To pozycja startowa.
5. Zacznij unośić barki ponad podłogę i kontynuuj dociskanie dolnych pleców do podłogi maksymalną siłą. Barki powinny unośić się ponad podłogę tylko o około 10 cm, a dolne plecy pozostają na podłodze. Wydech wykonuj podczas tej fazy ruchu. Mocno zepnij mięśnie brzucha na szczycie spięcia i utrzymaj sekundę. Wskazówka: Skoncentruj się na powolnym, kontrolowanym ruchu. Powstrzymaj się od używania pędu w każdej chwili.
6. Powoli wróć do pozycji startowej robiąc wdech.
7. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Crunch_-_Legs_On_Exercise_Ball/0.jpg', 'free_exercise_db'),
  ('crunches', 'Spięcia brzucha (crunches)', 'Crunches', 'motor_coach', 'beginner', array['Siłowe', 'Brzuch'], 'Klasyczne spięcia brzucha leżąc. Unoś tylko barki ponad podłogę, spinając mięśnie brzucha bez unoszenia dolnych pleców.', '1. Leż płasko na plecach ze stopami płasko na podłodze lub opartymi o ławkę, z kolanami ugiętymi pod kątem 90 stopni. Jeśli opierasz stopy o ławkę, ustaw je w rozstawie 8–10 cm i skieruj palce do środka, tak aby się stykały.
2. Teraz połóż dłonie lekko po obu stronach głowy, trzymając łokcie blisko. Wskazówka: Nie splataj palców za głową.
3. Dociskając dolną część pleców do podłogi, aby lepiej izolować mięśnie brzucha, zacznij unośić barki ponad podłogę.
4. Kontynuuj dociskanie dolnych pleców do podłogi maksymalną siłą, spinając mięśnie brzucha i wydychając powietrze. Barki powinny unośić się ponad podłogę tylko o około 10 cm, a dolne plecy pozostają na podłodze. Na szczycie ruchu mocno zepnij mięśnie brzucha i utrzymaj spięcie przez sekundę. Wskazówka: Skoncentruj się na powolnym, kontrolowanym ruchu — nie oszukuj się, używając pędu.
5. Po sekundzie spięcia zacznij powoli schodzić do pozycji startowej robiąc wdech.
6. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Crunches/0.jpg', 'free_exercise_db'),
  ('cuban-press', 'Press kubański', 'Cuban Press', 'motor_coach', 'intermediate', array['Siłowe', 'Barki'], 'Ćwiczenie barków łączące rotację zewnętrzną z wyciskaniem nad głowę. Wykonywane z hantlami w pozycji stracha na wróble.', '1. Weź hantlę do każdej dłoni chwytem nachwytem w pozycji stojącej. Unoś górne ramiona, aż będą równoległe do podłogi, pozwalając przedramionom zwisać w pozycji "stracha na wróble". To pozycja startowa.
2. Aby rozpocząć ruch, obróć barki na zewnątrz, aby przesunąć górne ramiona o 180 stopni. Trzymaj górne ramiona w miejscu, obracając je, aż nadgarstki znajdą się bezpośrednio nad łokciami, a przedramiona prostopadłe do podłogi.
3. Teraz wyciśnij hantle prostując łokcie, wyprostowując ramiona nad głowę.
4. Wróć do pozycji startowej robiąc wdech, odwracając kroki.
5. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Cuban_Press/0.jpg', 'free_exercise_db'),
  ('dancers-stretch', 'Rozciąganie tancerza', 'Dancer''s Stretch', 'motor_coach', 'beginner', array['Rozciąganie', 'Dolny odcinek pleców'], 'Rozciąganie skrętné tułowia siedząc na podłodze. Krzyżujesz nogi i obracasz górną część ciała w bok, rozciągając plecy i pośladki.', '1. Usiądź prosto na podłodze.
2. Krzyżuj prawą nogę nad lewą, trzymając kolano ugięte. Lewa noga prosta i oparta na podłodze.
3. Połóż lewe ramię na prawej nodze, a prawą dłoń na podłodze.
4. Obróć górną część ciała w prawo i wytrzymaj 10–20 sekund. Zmień strony.', NULL, 'free-exercise-db/Dancers_Stretch/0.jpg', 'free_exercise_db'),
  ('dead-bug', 'Martwy robak (dead bug)', 'Dead Bug', 'motor_coach', 'beginner', array['Siłowe', 'Brzuch'], 'Ćwiczenie mięśni głębokich leżąc na plecach. Ramiona i nogi unosisz pod kątem 90 stopni, a potem opuszczasz naprzemiennie nogę i utrzymujesz kontakt dolnych pleców z podłogą.', '1. Zacznij leżąc na plecach z ramionami wyciągniętymi nad sobą w kierunku sufitu.
2. Unoś stopy, kolana i biodra do kąta 90 stopni.
3. Mocno wydychaj, aby opuścić klatkę żebrową i przylgnąć pleców do podłogi, obracając miednicę w górę i spinając pośladki. Utrzymaj tę pozycję w całym ruchu. To pozycja startowa.
4. Rozpocznij ćwiczenie, prostując jedną nogę, wyprostowując kolano i biodro, aby doprowadzić nogę tuż nad podłogę.
5. Utrzymaj pozycję odcinka lędźwiowego i miednicy podczas ruchu, ponieważ plecy będą chciały się wygiąć.
6. Pozostań napięty i wróć pracującą nogę do pozycji startowej.
7. Powtórz po przeciwnej stronie, naprzemiennie, aż seria zostanie zakończona.', NULL, 'free-exercise-db/Dead_Bug/0.jpg', 'free_exercise_db'),
  ('deadlift-with-bands', 'Martwy ciąg z gumami oporowymi', 'Deadlift with Bands', 'motor_coach', 'advanced', array['Trójbój', 'Dolny odcinek pleców'], 'Martwy ciąg z dodatkowym oporem gum oporowych. Krótkie gumy zakładasz na drążek, długie kotwisz do stabilnej podstawy. Technika jak przy klasycznym martwym ciągu.', '1. Aby robić martwy ciąg z krótkimi gumami, po prostu nałóż je na drążek przed rozpoczęciem i wsuń się w nie przygotowując się. Długie gumy trzeba zakotwić do stabilnej podstawy, np. ciężkich hantli lub regału.
2. Gdy stopy i chwyt są ustawione, weź głęboki oddech, a następnie obniż biodra i zegnij kolana, aż piszczele dotkną drążka. Patrz przed siebie, trzymaj klatkę piersiową uniesioną i plecy wygięte, i zacznij odpychać się piętami, aby ruszyć ciężar w górę. Po przejściu drążka przez kolana agresywnie pociągnij drążek do tyłu, spinając łopatki i wypychając biodra do przodu w drążek.
3. Opuszczaj drążek, zginając się w biodrach i prowadząc go na podłogę.', NULL, 'free-exercise-db/Deadlift_with_Bands/0.jpg', 'free_exercise_db'),
  ('deadlift-with-chains', 'Martwy ciąg z łańcuchami', 'Deadlift with Chains', 'motor_coach', 'advanced', array['Trójbój', 'Dolny odcinek pleców'], 'Martwy ciąg z łańcuchami zawieszonymi na gryfie, które zwiększają opór w miarę unośenia sztangi. Technika jak przy klasycznym martwym ciągu.', '1. Możesz zaczepić łańcuchy na tulejach gryfu albo przewiesić ich środek przez gryf, aby uzyskać większy wzrost ciężaru podczas unośenia.
2. Podejdź do drążka tak, aby był wycentrowany nad stopami. Stopy około szerokości bioder. Zegnij się w biodrze, aby chwycić drążek na szerokość barków, pozwalając łopatkom się wysunąć. Zazwyczaj używa się chwytu nachwytem lub chwytu mieszanego przy większych ciężarach. Gdy stopy i chwyt są ustawione, weź głęboki oddech, a następnie obniż biodra i zegnij kolana, aż piszczele dotkną drążka.
3. Patrz przed siebie, trzymaj klatkę piersiową uniesioną i plecy wygięte, i zacznij odpychać się piętami, aby ruszyć ciężar w górę. Po przejściu drążka przez kolana agresywnie pociągnij drążek do tyłu, spinając łopatki i wypychając biodra do przodu w drążek.
4. Opuszczaj drążek, zginając się w biodrach i prowadząc go na podłogę.', NULL, 'free-exercise-db/Deadlift_with_Chains/0.jpg', 'free_exercise_db'),
  ('decline-barbell-bench-press', 'Wyciskanie sztangi leżąc na ławce negatywnej', 'Decline Barbell Bench Press', 'motor_coach', 'beginner', array['Siłowe', 'Klatka piersiowa'], 'Wyciskanie sztangi leżąc na ławce z ujemnym skosem. Angażuje dolne włókna klatki piersiowej i triceps.', '1. Zabezpiecz nogi na końcu ławki negatywnej i powoli połóż się na ławce.
2. Średnim chwytem (tworzącym kąt 90 stopni w środku ruchu między przedramieniem a ramieniem) podnieś sztangę z regału i trzymaj ją prosto nad sobą z zablokowanymi ramionami. Ramiona powinny być prostopadłe do podłogi. To pozycja startowa. Wskazówka: Aby chronić barki (bark), najlepiej, aby ktoś asystował ci przy unośeniu sztangi z regału.
3. Wdech wykonuj, schodząc powoli, aż poczujesz sztangę na dolnej części klatki piersiowej.
4. Po pauzie wróć sztangę do pozycji startowej przy wydechu, wypychając ją pracą mięśni klatki piersiowej. Zablokuj ramiona i zepnij klatkę w pozycji spiętej, zatrzymaj się na sekundę, a potem znów zacznij schodzić powoli. Wskazówka: Zejście powinno trwać co najmniej dwa razy dłużej niż wypchanie.
5. Powtórz ruch zalecaną liczbę powtórzeń.
6. Po zakończeniu odłóż sztangę z powrotem na regał.', NULL, 'free-exercise-db/Decline_Barbell_Bench_Press/0.jpg', 'free_exercise_db'),
  ('decline-close-grip-bench-to-skull-crusher', 'Wyciskanie wąskim chwytem na ławce negatywnej z francuskim', 'Decline Close-Grip Bench To Skull Crusher', 'motor_coach', 'intermediate', array['Siłowe', 'Triceps'], 'Połączenie wyciskania wąskim chwytem i francuskiego wyciskania na ławce negatywnej. Najpierw wyciskasz sztangę, potem opuszczasz ją do czoła pracą tricepsa.', '1. Zabezpiecz nogi na końcu ławki negatywnej i powoli połóż się na ławce.
2. Wąskim chwytem (nieco mniejszym niż szerokość barków) podnieś sztangę z regału i trzymaj ją prosto nad sobą z zablokowanymi ramionami i łokciami blisko ciała. Ramiona prostopadłe do podłogi. To pozycja startowa. Wskazówka: Aby chronić bark, najlepiej, by ktoś asystował ci przy unośeniu sztangi z regału.
3. Teraz opuść sztangę do dolnej części klatki piersiowej robiąc wdech. Trzymaj łokcie blisko tułowia podczas tego ruchu.
4. Wypchnij sztangę z powrotem do pozycji startowej pracą tricepsa przy wydechu.
5. Robiąc wdech i trzymając ramiona nieruchomo, powoli opuść sztangę, prowadząc przedramiona półkolistym ruchem w swoją stronę, aż sztanga delikatnie dotknie czoła. Wdech wykonuj podczas tej fazy ruchu.
6. Unoś sztangę z powrotem do pozycji startowej spinając triceps i wydychając powietrze.
7. Powtórz kroki 3–6, aż wykonasz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Decline_Close-Grip_Bench_To_Skull_Crusher/0.jpg', 'free_exercise_db'),
  ('decline-crunch', 'Spięcia brzucha na ławce negatywnej', 'Decline Crunch', 'motor_coach', 'intermediate', array['Siłowe', 'Brzuch'], 'Crunch na ławce z ujemnym skosem, z nogami zabezpieczonymi na końcu ławki. Unoś barki ponad ławkę, spinając mięśnie brzucha.', '1. Zabezpiecz nogi na końcu ławki negatywnej i połóż się.
2. Teraz połóż dłonie lekko po obu stronach głowy, trzymając łokcie blisko. Wskazówka: Nie splataj palców za głową.
3. Dociskając dolną część pleców do ławki, aby lepiej izolować mięśnie brzucha, zacznij unośić barki ponad nią.
4. Kontynuuj dociskanie dolnych pleców do ławki maksymalną siłą, spinając mięśnie brzucha i wydychając powietrze. Barki powinny unośić się ponad ławkę tylko o około 10 cm, a dolne plecy pozostają na ławce. Na szczycie ruchu mocno zepnij mięśnie brzucha i utrzymaj spięcie przez sekundę. Wskazówka: Skoncentruj się na powolnym, kontrolowanym ruchu — nie oszukuj się, używając pędu.
5. Po sekundzie spięcia zacznij powoli schodzić do pozycji startowej robiąc wdech.
6. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Decline_Crunch/0.jpg', 'free_exercise_db'),
  ('decline-dumbbell-bench-press', 'Wyciskanie hantli na ławce negatywnej', 'Decline Dumbbell Bench Press', 'motor_coach', 'beginner', array['Siłowe', 'Klatka piersiowa'], 'Wyciskanie hantli leżąc na ławce z ujemnym skosem. Angażuje dolne włókna klatki piersiowej.', '1. Zabezpiecz nogi na końcu ławki negatywnej i połóż się z hantlą w każdej ręce na udach. Dłonie zwrócone ku sobie.
2. Po położeniu się przesuń hantle przed sobą na szerokość barków.
3. Na szerokości barków obróć nadgarstki do przodu, tak aby dłonie były zwrócone od ciebie. To pozycja startowa.
4. Powoli opuszczaj ciężary na boki robiąc wdech. Cały czas zachowuj pełną kontrolę nad hantlami. Wskazówka: W całym ruchu przedramiona powinny zawsze być prostopadłe do podłogi.
5. Wydech wykonuj, wypychając hantle w górę pracą mięśni klatki piersiowej. Zablokuj ramiona w pozycji spiętej, zepnij klatkę, zatrzymaj się na sekundę i zacznij schodzić powoli. Wskazówka: Zejście powinno trwać co najmniej dwa razy dłużej niż wypchanie.
6. Powtórz ruch zalecaną liczbę powtórzeń zgodnie z twoim programem treningowym.', NULL, 'free-exercise-db/Decline_Dumbbell_Bench_Press/0.jpg', 'free_exercise_db'),
  ('decline-dumbbell-flyes', 'Rozpiętki hantlami na ławce negatywnej', 'Decline Dumbbell Flyes', 'motor_coach', 'beginner', array['Siłowe', 'Klatka piersiowa'], 'Rozpiętki hantlami leżąc na ławce z ujemnym skosem. Rozprowadzasz ramiona szerokim łukiem, rozciągając dolną część klatki piersiowej.', '1. Zabezpiecz nogi na końcu ławki negatywnej i połóż się z hantlą w każdej ręce na udach. Dłonie zwrócone ku sobie.
2. Po położeniu się przesuń hantle przed sobą na szerokość barków. Dłonie zwrócone ku sobie, ramiona prostopadłe do podłogi i w pełni wyprostowane. To pozycja startowa.
3. Z lekkim ugięciem łokci, aby zapobiec naprężeniu ścięgna bicepsa, opuszczaj ramiona na obie strony szerokim łukiem, aż poczujesz rozciągnięcie klatki piersiowej. Wdech wykonuj podczas tej fazy ruchu. Wskazówka: Pamiętaj, że w całym ruchu ramiona pozostają nieruchome; ruch zachodzi tylko w stawie barkowym.
4. Wróć ramiona do pozycji startowej spinając mięśnie klatki i robiąc wydech. Wskazówka: Upewnij się, że używasz tego samego łuku ruchu, którym opuszczałeś ciężary.
5. Zatrzymaj się na sekundę w pozycji spiętej i powtórz ruch zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Decline_Dumbbell_Flyes/0.jpg', 'free_exercise_db'),
  ('decline-dumbbell-triceps-extension', 'Prostowanie ramion hantlami na ławce negatywnej', 'Decline Dumbbell Triceps Extension', 'motor_coach', 'beginner', array['Siłowe', 'Triceps'], 'Francuskie wyciskanie hantlami leżąc na ławce z ujemnym skosem. Opuszczasz hantle obok uszu, zginając łokcie, i wracasz do wyprostu pracą tricepsa.', '1. Zabezpiecz nogi na końcu ławki negatywnej i połóż się z hantlą w każdej ręce na udach. Dłonie zwrócone ku sobie.
2. Po położeniu się przesuń hantle przed sobą na szerokość barków. Dłonie zwrócone ku sobie, ramiona prostopadłe do podłogi i w pełni wyprostowane. To pozycja startowa.
3. Robiąc wdech i trzymając ramiona nieruchomo (z łokciami blisko), opuszczaj hantle powoli, prowadząc przedramiona półkolistym ruchem w swoją stronę, aż kciuki znajdą się obok uszu. Wdech wykonuj podczas tej fazy ruchu.
4. Unoś hantle z powrotem do pozycji startowej spinając triceps i robiąc wydech.
5. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Decline_Dumbbell_Triceps_Extension/0.jpg', 'free_exercise_db')
on conflict (slug) do nothing;

insert into public.exercises
  (slug, name, name_en, persona_type, level, categories, short_description, detail_full, common_mistakes, photo_path, source)
values
  ('decline-ez-bar-triceps-extension', 'Prostowanie ramion gryfem EZ na ławce negatywnej', 'Decline EZ Bar Triceps Extension', 'motor_coach', 'beginner', array['Siłowe', 'Triceps'], 'Francuskie wyciskanie gryfem EZ leżąc na ławce z ujemnym skosem. Opuszczasz gryf do czoła i wracasz do wyprostu pracą tricepsa.', '1. Zabezpiecz nogi na końcu ławki negatywnej i powoli połóż się na ławce.
2. Wąskim chwytem podnieś gryf EZ z regału i trzymaj go prosto nad sobą z zablokowanymi ramionami i łokciami blisko ciała. Ramiona prostopadłe do podłogi. To pozycja startowa. Wskazówka: Aby chronić bark, najlepiej, by ktoś asystował ci przy unośeniu gryfu z regału.
3. Robiąc wdech i trzymając ramiona nieruchomo, opuść gryf powoli, prowadząc przedramiona półkolistym ruchem w swoją stronę, aż poczuć, że gryf delikatnie dotyka czoła. Wdech wykonuj podczas tej fazy ruchu.
4. Unoś gryf z powrotem do pozycji startowej spinając triceps i robiąc wydech.
5. Powtarzaj, aż wykonasz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Decline_EZ_Bar_Triceps_Extension/0.jpg', 'free_exercise_db'),
  ('decline-oblique-crunch', 'Skosne spięcia brzucha na ławce negatywnej', 'Decline Oblique Crunch', 'motor_coach', 'beginner', array['Siłowe', 'Brzuch'], 'Crunch z rotacją tulowa na ławce z ujemnym skosem. Unoś się skręcając tulów, tak aby łokieć dotknął przeciwległego kolana.', '1. Zabezpiecz nogi na końcu ławki negatywnej i powoli połóż się na ławce.
2. Unoś górną część ciała ponad ławkę, aż tulów będzie pod kątem około 35–45 stopni względem podłogi.
3. Połóż jedną dłoń obok głowy, a drugą na udzie. To pozycja startowa.
4. Powoli unoś górną część ciała z pozycji startowej, obracając tulów w lewo. Kontynuuj spinanie w górę przy wydechu, aż prawy łokieć dotknie lewego kolana. Utrzymaj tę pozycję spiętą przez sekundę. Wskazówka: Skoncentruj się na utrzymaniu napięcia mięśni brzucha i powolnym, kontrolowanym ruchu.
5. Powoli opuść ciało z powrotem do pozycji startowej robiąc wdech.
6. Po wykonaniu jednej serii na prawą stronę zalecaną liczbą powtórzeń zmień na lewą stronę. Wskazówka: Skoncentruj się na mocnym skręcaniu tulowa i poczuciu spięcia w pozycji górnej.', NULL, 'free-exercise-db/Decline_Oblique_Crunch/0.jpg', 'free_exercise_db'),
  ('decline-push-up', 'Pompki z nogami na podwyższeniu', 'Decline Push-Up', 'motor_coach', 'beginner', array['Siłowe', 'Klatka piersiowa'], 'Pompki ze stopami opartymi o skrzynię lub ławkę. Silniej angażują górną część klatki piersiowej i barki.', '1. Połóż się na podłodze twarzą w dół i ustaw dłonie około 90 cm od siebie, trzymając tulów uniesiony na wyprostowanych ramionach. Unoś stopy na skrzynię lub ławkę. To pozycja startowa.
2. Następnie opuszczaj się w dół, aż klatka niemal dotknie podłogi, robiąc wdech.
3. Teraz wydychaj powietrze i wypchnij górną część ciała z powrotem do pozycji startowej, spinając klatkę piersiową.
4. Po krótkiej pauzie w spiętej pozycji górnej możesz zacząć ponownie opuszczać się, wykonując tyle powtórzeń, ile potrzebujesz.', NULL, 'free-exercise-db/Decline_Push-Up/0.jpg', 'free_exercise_db'),
  ('decline-reverse-crunch', 'Odwrócone spięcia brzucha na ławce negatywnej', 'Decline Reverse Crunch', 'motor_coach', 'beginner', array['Siłowe', 'Brzuch'], 'Odwrócony crunch na ławce z ujemnym skosem, trzymając się góry ławki. Przyciągasz kolana do klatki, unośąc biodra ponad ławkę.', '1. Połóż się na plecach na ławce negatywnej i złap się góry ławki oburącz. Nie pozwól ciału zsuwać się z tej pozycji.
2. Trzymaj nogi równolegle do podłogi, używając mięśni brzucha, z kolanami i stopami złączonymi. Wskazówka: Nogi powinny być w pełni wyprostowane z lekkim ugięciem kolana. To pozycja startowa.
3. Wydychając powietrze, prowadź nogi w kierunku tulowa, obracając miednicę do tyłu i unośąc biodra ponad ławkę. Na końcu tego ruchu kolana będą dotykać klatki piersiowej.
4. Utrzymaj spięcie przez sekundę i wróć nogami do pozycji startowej robiąc wdech.
5. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Decline_Reverse_Crunch/0.jpg', 'free_exercise_db'),
  ('decline-smith-press', 'Wyciskanie na ławce negatywnej w Smithie', 'Decline Smith Press', 'motor_coach', 'beginner', array['Siłowe', 'Klatka piersiowa'], 'Wyciskanie sztangi na maszynie Smitha leżąc na ławce z ujemnym skosem. Angażuje dolną część klatki piersiowej.', '1. Ustaw ławkę negatywną pod maszyną Smitha. Teraz ustaw sztangę na wysokości, którą możesz dosięgnąć leżąc, z prawie w pełni wyprostowanymi ramionami. Chwytem nachwytem szerszym niż szerokość barków odblokuj sztangę z regału i trzymaj ją prosto nad sobą z wyprostowanymi ramionami. To pozycja startowa.
2. Robiąc wdech, opuszczaj sztangę z kontrolą, pozwalając łokciom się zginać, delikatnie dotykając tulowem.
3. Po krótkiej pauzie wróć sztangę do pozycji startowej prostując łokcie, robiąc przy tym wydech.
4. Powtórz ruch zalecaną liczbę powtórzeń.
5. Po zakończeniu serii zablokuj sztangę z powrotem w regale.', NULL, 'free-exercise-db/Decline_Smith_Press/0.jpg', 'free_exercise_db'),
  ('deficit-deadlift', 'Martwy ciąg z deficytu', 'Deficit Deadlift', 'motor_coach', 'intermediate', array['Trójbój', 'Dolny odcinek pleców'], 'Martwy ciąg stojąc na podwyższeniu (1–3 cali), które pogłębia zakres ruchu. Silniej rozciąga plecy i wzmacnia dolną fazę ciągu.', '1. Zacznij od przygotowania podwyższenia lub talerzy, na których staniesz, zazwyczaj o wysokości 2,5–7,5 cm. Podejdź do drążka tak, aby był wycentrowany nad stopami. Stopy około szerokości bioder. Zegnij się w biodrze, aby chwycić drążek na szerokość barków, pozwalając łopatkom się wysunąć. Zazwyczaj używa się chwytu nachwytem lub chwytu mieszanego przy większych ciężarach.
2. Gdy stopy i chwyt są ustawione, weź głęboki oddech, a następnie obniż biodra i zegnij kolana, aż piszczele dotkną drążka. Patrz przed siebie, trzymaj klatkę piersiową uniesioną i plecy wygięte, i zacznij odpychać się piętami, aby ruszyć ciężar w górę. Po przejściu drążka przez kolana agresywnie pociągnij drążek do tyłu, spinając łopatki i wypychając biodra do przodu w drążek.
3. Opuszczaj drążek, zginając się w biodrach i prowadząc go na podłogę.', NULL, 'free-exercise-db/Deficit_Deadlift/0.jpg', 'free_exercise_db'),
  ('depth-jump-leap', 'Skok w głąb z wybiciem', 'Depth Jump Leap', 'motor_coach', 'beginner', array['Plyometryka', 'Uda'], 'Ćwiczenie plyometryczne: zeskakujesz z niższego skrzynia i natychmiast wybijasz się maksymalnie w górę na wyższy skrzyn. Rozwija moc wybicia.', '1. Do tego ćwiczenia potrzebujesz dwóch skrzyń lub ławek — jednej 30–40 cm i drugiej 55–65 cm wysokości.
2. Stań na jednym z dwóch skrzyń z ramionami przy bokach; stopy razem, lekko wystające poza krawędź, jak przy skoku w głąb. Drugą skrzynię ustaw około 60–90 cm przed tobą, frontem do ciebie.
3. Zacznij od zeskok z początkowej skrzyni, lądując i natychmiast wybijając się obiema nogami.
4. Wybij się w górę i na zewnątrz maksymalnie intensywnie, używając ramion i pełnego wyprostu ciała, aby skoczyć na wyższą skrzyn. Ponownie pozwól nogom absorbować wstrząs przy lądowaniu.', NULL, 'free-exercise-db/Depth_Jump_Leap/0.jpg', 'free_exercise_db'),
  ('dip-machine', 'Dipy na maszynie', 'Dip Machine', 'motor_coach', 'beginner', array['Siłowe', 'Triceps'], 'Prostowanie ramion (dipy) na maszynie z obciążeniem. Uchwyty wypychasz w dół pracą tricepsa, z łokciami blisko tulowa.', '1. Usiądź stabilnie w maszynie do dipów, wybierz ciężar i pewnie złap uchwyty.
2. Teraz trzymaj łokcie blisko boków, aby skupić pracę na tricepsie. Łokcie powinny być zgięte pod kątem 90 stopni.
3. Spinając triceps, prostuj ramiona w dół przy wydechu. Wskazówka: Na dole ruchu skoncentruj się na zachowaniu lekkiego ugięcia ramion, aby utrzymać napięcie tricepsa.
4. Teraz powoli pozwól ramionom wrócić w górę do pozycji startowej robiąc wdech.
5. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Dip_Machine/0.jpg', 'free_exercise_db'),
  ('dips-chest-version', 'Dipy na klatkę piersiową', 'Dips - Chest Version', 'motor_coach', 'intermediate', array['Siłowe', 'Klatka piersiowa'], 'Dipy na drążkach z pochyloną do przodu tulowem. Silniej angażują dolną część klatki piersiowej.', '1. Do tego ćwiczenia potrzebujesz dostępu do drążków równoległych. Aby przyjąć pozycję startową, utrzymuj ciało na wyprostowanych (zablokowanych) ramionach ponad drążkami.
2. Wdychając powietrze, opuszczaj się powoli z tulowem pochylonym do przodu o około 30 stopni i lekko rozprowadzonymi na boki łokciami, aż poczujesz lekkie rozciągnięcie klatki piersiowej.
3. Gdy poczujesz rozciągnięcie, użyj klatki piersiowej, aby wrócić ciałem do pozycji startowej przy wydechu. Wskazówka: Pamiętaj, aby zepnąć klatkę na szczycie ruchu przez sekundę.
4. Powtórz ruch zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Dips_-_Chest_Version/0.jpg', 'free_exercise_db'),
  ('dips-triceps-version', 'Dipy na triceps', 'Dips - Triceps Version', 'motor_coach', 'beginner', array['Siłowe', 'Triceps'], 'Dipy na drążkach z pionowym tulowem i łokciami blisko ciała. Koncentrują pracę na tricepsie.', '1. Aby przyjąć pozycję startową, utrzymuj ciało na wyprostowanych (prawie zablokowanych) ramionach ponad drążkami.
2. Teraz zrób wdech i opuszczaj się powoli w dół. Tulów powinien pozostać wyprostowany, a łokcie blisko ciała. To pomaga lepiej skupić się na pracy tricepsa. Opuszczaj się, aż między ramieniem a przedramieniem utworzy się kąt 90 stopni.
3. Następnie wydychaj powietrze i wypchnij tulów z powrotem w górę pracą tricepsa, aby wrócić do pozycji startowej.
4. Powtórz ruch zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Dips_-_Triceps_Version/0.jpg', 'free_exercise_db'),
  ('donkey-calf-raises', 'Wspięcia na palce w opadzie (donkey calf raises)', 'Donkey Calf Raises', 'motor_coach', 'intermediate', array['Siłowe', 'Łydki'], 'Wspięcia na palce na maszynie w pozycji z tulowem pochylonym do przodu. Pięty unośisz maksymalnie w górę, spinając łydki.', '1. Do tego ćwiczenia potrzebujesz dostępu do maszyny do wspięć na palce w opadzie. Zacznij od umieszczenia dolnych pleców i bioder pod wyściełanym ramieniem maszyny. Kontakt z poduszką powinna nawiązać okolica kości ogonowej.
2. Połóż obie ręce na bocznych uchwytach i ustaw śródstopie na bloku do łydek z piętami wystającymi poza jego krawędź. Skieruj palce do przodu, do środka lub na zewnątrz, w zależności od partii, którą chcesz celować, i wyprostuj kolana bez ich blokowania. To pozycja startowa.
3. Unoś pięty przy wydechu, prostując kostki maksymalnie wysoko i spinając łydki. Upewnij się, że kolana pozostają nieruchome przez cały czas. W żadnym momencie nie powinno dochodzić do ich uginania. Utrzymaj pozycję spiętą przez sekundę, zanim zaczniesz schodzić w dół.
4. Wróć powoli do pozycji startowej robiąc wdech, opuszczając pięty i zginając kostki, aż łydki zostaną rozciągnięte.
5. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Donkey_Calf_Raises/0.jpg', 'free_exercise_db'),
  ('double-kettlebell-alternating-hang-clean', 'Wyruk hang naprzemienny z dwoma kettlebellami', 'Double Kettlebell Alternating Hang Clean', 'motor_coach', 'intermediate', array['Siłowe', 'Dwugłowe uda'], 'Naprzemienne wyruki kettlebelli na bark z pozycji wiszącej. Jeden kettlebell opuszczasz, jednocześnie wyrukując drugi.', '1. Połóż dwa kettlebelle między stopami. Aby przyjąć pozycję startową, wypchnij pośladki do tyłu i patrz prosto przed siebie.
2. Wyrukuj jeden kettlebell na bark i trzymaj drugi kettlebell.
3. Płynnym ruchem opuść górny kettlebell, jednocześnie wypychając dolny w górę.', NULL, 'free-exercise-db/Double_Kettlebell_Alternating_Hang_Clean/0.jpg', 'free_exercise_db'),
  ('double-kettlebell-jerk', 'Podrzut z dwoma kettlebellami', 'Double Kettlebell Jerk', 'motor_coach', 'intermediate', array['Siłowe', 'Barki'], 'Podrzut dwóch kettlebelli nad głowę. Lekki przysiad i gwałtowne wyprost nóg dają pęd, którym wyciskasz kettlebelle nad głowę.', '1. Trzymaj kettlebell za uchwyt w każdej dłoni.
2. Wyrukuj kettlebelle na barki, prostując nogi i biodra, pociągając je w kierunku barków. Obróć nadgarstki, tak aby dłonie były zwrócone do przodu. To pozycja startowa.
3. Wykonaj przysiad zegnając kolana, trzymając tulów wyprostowany.
4. Natychmiast odwróć kierunek ruchu, odpychając się piętami — w istocie wyskakując, aby stworzyć pęd.
5. Przy tym wyciśnij kettlebelle nad głowę do pełnego wyprostu, prostując ramiona i wykorzystując pęd ciała do przeniesienia ciężarów.
6. Wróć stopami na podłogę w rozkroku, z jedną stopą z przodu, a drugą z tyłu.
7. Trzymając ciężary nad głową, wróć do pozycji stojącej, zsuwając stopy do siebie. Opuść ciężary, aby wykonać kolejne powtórzenie.', NULL, 'free-exercise-db/Double_Kettlebell_Jerk/0.jpg', 'free_exercise_db'),
  ('double-kettlebell-push-press', 'Push press z dwoma kettlebellami', 'Double Kettlebell Push Press', 'motor_coach', 'intermediate', array['Siłowe', 'Barki'], 'Wyciskanie dwóch kettlebelli nad głowę z pomocą nóg. Krótki przysiad i gwałtowny wyprost dają pęd do wypchnięcia ciężarów.', '1. Wyrukuj dwa kettlebelle na barki.
2. Siądź o kilka centymetrów i gwałtownie odwróć ruch. Użyj pędu z nóg, aby wypchnąć kettlebelle nad głowę.
3. Gdy kettlebelle zostaną zablokowane nad głową, opuść je na barki i powtórz.', NULL, 'free-exercise-db/Double_Kettlebell_Push_Press/0.jpg', 'free_exercise_db'),
  ('double-kettlebell-snatch', 'Rwanie z dwoma kettlebellami', 'Double Kettlebell Snatch', 'motor_coach', 'advanced', array['Siłowe', 'Barki'], 'Rwanie dwóch kettlebelli znad głowy jednym płynnym ruchem. Huśtasz nimi między nogami i wyrzucasz nad głowę pracą bioder.', '1. Połóż dwa kettlebelle za stopami. Zegnij kolana i siądź, aby podnieść kettlebelle.
2. Huśtaj kettlebelle między nogami gwałtownie i odwróć kierunek ruchu.
3. Wybierz się biodrami i zablokuj kettlebelle nad głową jednym nieprzerwanym ruchem.', NULL, 'free-exercise-db/Double_Kettlebell_Snatch/0.jpg', 'free_exercise_db'),
  ('double-kettlebell-windmill', 'Młyn z dwoma kettlebellami', 'Double Kettlebell Windmill', 'motor_coach', 'intermediate', array['Siłowe', 'Brzuch'], 'Młyn z dwoma kettlebellami: jeden utrzymujesz zablokowany nad głową, a drugi podnosisz z ziemi zginając się w biodrze w bok. Silnie angażuje barki, pośladki i mięśnie głębokie.', '1. Połóż kettlebell przed przednią stopą i wyrukuj oraz wyciśnij kettlebell nad głowę przeciwną ręką. Wyrukuj kettlebell na bark prostując nogi i biodra, pociągając go w kierunku barków. Obróć nadgarstek, tak aby dłoń była zwrócona do przodu.
2. Utrzymując kettlebell zablokowany nad głową przez cały czas, wypchnij pośladki w kierunku zablokowanego kettlebella. Skieruj stopy pod kątem 45 stopni od ramienia z zablokowanym kettlebellem.
3. Zegnasz się w biodrze w bok, wypychając pośladki, i powoli pochylaj się, aż sięgniesz po kettlebell z ziemi. Wzrok cały czas na kettlebellu trzymanym nad głową.
4. Zatrzymaj się na sekundę po podniesieniu kettlebella z ziemi i odwróć ruch z powrotem do pozycji startowej.', NULL, 'free-exercise-db/Double_Kettlebell_Windmill/0.jpg', 'free_exercise_db'),
  ('double-leg-butt-kick', 'Podwójny kopnięcie piętami (butt kick)', 'Double Leg Butt Kick', 'motor_coach', 'beginner', array['Plyometryka', 'Uda'], 'Plyometryczny skok w górę z podkurczaniem pięt w kierunku pośladków. Rozwija moc wybicia nóg.', '1. Zacznij stojąc z lekko ugiętymi kolanami.
2. Szybko siądź na krótkiej odległości, zginając biodra i kolana, i natychmiast wyprostuj się skacząc maksymalnie wysoko.
3. W górze podkurcz pięty zginając kolana, próbując dotknąć pośladków.
4. Zakończ ruch lądując z tylko częściowo ugiętymi kolanami, używając nóg do absorpcji wstrząsu.', NULL, 'free-exercise-db/Double_Leg_Butt_Kick/0.jpg', 'free_exercise_db'),
  ('downward-facing-balance', 'Balans na piłce w podporze', 'Downward Facing Balance', 'motor_coach', 'intermediate', array['Siłowe', 'Pośladki'], 'Ćwiczenie równowagi na piłce gimnastycznej. Leżysz brzuchem na piłce i idziesz rękami do przodu, unosząc nogi nad podłogą.', '1. Połóż się twarzą w dół na piłce do ćwiczeń.
2. Opierając się brzuchem na piłce, idź dłońmi do przodu po podłodze i unoś nogi, prostując łokcie i kolana.', NULL, 'free-exercise-db/Downward_Facing_Balance/0.jpg', 'free_exercise_db'),
  ('drag-curl', 'Uginanie ramion ze sztangą przy tułowiu', 'Drag Curl', 'motor_coach', 'intermediate', array['Siłowe', 'Biceps'], 'Wariant uginania ramion ze sztangą, w którym sztanga prowadzona jest tuż przy tułowiu, a łokcie cofnięte do tyłu. Świetnie izoluje biceps, ograniczając udział barków.', '1. Pochwyć sztangę chwytem podchwytem (dłonie skierowane do przodu) i ustaw łokcie blisko tułowia oraz cofnięte do tyłu. To będzie pozycja startowa.
2. Na wydechu uginaj sztangę w górę, trzymając łokcie cofnięte do tyłu i „przeciągając” sztangę wzdłuż ciała tak, by cały czas stykała się z tułowiem. Wskazówka: jak widzisz, łokci nie trzymasz przyciśniętych do boków, lecz cofasz je do tyłu. Nie unosisz też barków.
3. Powoli wróć do pozycji startowej, cały czas utrzymując kontakt sztangi z torsem.
4. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Drag_Curl/0.jpg', 'free_exercise_db'),
  ('drop-push', 'Pompki z zeskokiem', 'Drop Push', 'motor_coach', 'intermediate', array['Plyometryka', 'Klatka piersiowa'], 'Plyometryczna pompka wykonywana między dwiema niskimi platformami. Z pozycji na dłoniach na podwyższeniach zeskakujesz dłońmi na szerokość barków, amortyzując lądowanie.', '1. Ustaw niskie skrzynie lub inne platformy w odległości 60–90 cm od siebie.
2. Przyjmij pozycję do pompek między nimi, opierając się dłońmi na skrzyniach.
3. Zachowując prawidłową postawę, zeskocz z platform, odbijając się w górę i przenosząc dłonie na szerokość barków; złagodź lądowanie, amortyzując siłę uderzenia ramionami.', NULL, 'free-exercise-db/Drop_Push/0.jpg', 'free_exercise_db'),
  ('dumbbell-alternate-bicep-curl', 'Naprzemienne uginanie ramion z hantlami', 'Dumbbell Alternate Bicep Curl', 'motor_coach', 'beginner', array['Siłowe', 'Biceps'], 'Klasyczne uginanie ramion z hantlami wykonywane naprzemiennie, z obrotem nadgarstka podczas unoszenia. Buduje siłę i masę bicepsów.', '1. Stań prosto (tułów wyprostowany) z hantlą w każdej dłoni, ramiona swobodnie opuszczone. Łokcie powinny być blisko tułowia, a dłonie skierowane do ud.
2. Trzymając górną część ramienia nieruchomo, uginaj prawą hantlę, obracając nadgarstek aż dłoń skieruje się do przodu. Kontynuuj napinanie bicepsa na wydechu, aż będzie maksymalnie napięty, a hantla znajdzie się na wysokości barku. Przytrzymaj napiętą pozycję przez sekundę, zaciskając biceps. Wskazówka: poruszać się powinny tylko przedramiona.
3. Na wdechu powoli opuszczaj hantlę do pozycji startowej. Wskazówka: pamiętaj, aby podczas opuszczania obrócić nadgarstek z powrotem do pozycji wyjściowej (dłonie skierowane do ud).
4. Wykonaj ten sam ruch lewą ręką. To stanowi jedno pełne powtórzenie.
5. Kontynuuj naprzemiennie w ten sposób przez zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Dumbbell_Alternate_Bicep_Curl/0.jpg', 'free_exercise_db'),
  ('dumbbell-bench-press', 'Wyciskanie hantli na ławce płaskiej', 'Dumbbell Bench Press', 'motor_coach', 'beginner', array['Siłowe', 'Klatka piersiowa'], 'Podstawowe ćwiczenie na klatkę piersiową — wyciskanie dwóch hantli w leżeniu na ławce płaskiej. Angażuje też tricepsy i barki.', '1. Połóż się na ławce płaskiej z hantlą w każdej dłoni spoczywającą na udach. Dłonie powinny być zwrócone ku sobie.
2. Następnie, pomagając sobie udami, unoś hantle pojedynczo tak, aby móc trzymać je przed sobą na szerokość barków.
3. Gdy hantle są na szerokości barków, obróć nadgarstki do przodu, aby dłonie były skierowane od ciebie. Hantle powinny znajdować się po bokach klatki piersiowej, a ramię i przedramię mają tworzyć kąt 90 stopni. Pilnuj, aby cały czas zachować pełną kontrolę nad hantlami. To będzie pozycja startowa.
4. Teraz, na wydechu, wypchnij hantle w górę siłą klatki piersiowej. Zablokuj ramiona na szczycie ruchu i ściśnij mięśnie klatki piersiowej, przytrzymaj sekundę, po czym zacznij powoli opuszczać. Wskazówka: idealnie opuszczanie ciężaru powinno trwać około dwa razy dłużej niż jego unoszenie.
5. Powtarzaj ruch przez zaleconą w programie treningowym liczbę powtórzeń.', NULL, 'free-exercise-db/Dumbbell_Bench_Press/0.jpg', 'free_exercise_db'),
  ('dumbbell-bench-press-with-neutral-grip', 'Wyciskanie hantli na ławce płaskiej chwytem neutralnym', 'Dumbbell Bench Press with Neutral Grip', 'motor_coach', 'beginner', array['Siłowe', 'Klatka piersiowa'], 'Wariant wyciskania hantli leżąc, w którym dłonie są zwrócone ku sobie. Łagodniejszy dla barków, mocno pracują klatka piersiowa i tricepsy.', '1. Weź hantlę w każdą dłoń i połóż się na ławce płaskiej. Stopy powinny płasko stać na podłodze, a łopatki być ściągnięte.
2. Zachowując chwyt neutralny (dłonie zwrócone ku sobie), zacznij z ramionami wyprostowanymi dokładnie nad sobą, prostopadle do podłogi. To będzie pozycja startowa.
3. Rozpocznij ruch zginaniem łokcia, opuszczając ramiona na boki. Schodź, aż hantle będą przy tułowiu.
4. Zatrzymaj się na chwilę, po czym wyprostuj łokcie i wróć do pozycji startowej.', NULL, 'free-exercise-db/Dumbbell_Bench_Press_with_Neutral_Grip/0.jpg', 'free_exercise_db'),
  ('dumbbell-bicep-curl', 'Uginanie ramion z hantlami', 'Dumbbell Bicep Curl', 'motor_coach', 'beginner', array['Siłowe', 'Biceps'], 'Podstawowe ćwiczenie izolujące biceps z hantlami w obu dłoniach jednocześnie. Prosty ruch uginania ramion z pełnym napięciem na górze.', '1. Stań prosto z hantlą w każdej dłoni, ramiona opuszczone wzdłuż ciała. Trzymaj łokcie blisko tułowia i obróć dłonie, aż będą skierowane do przodu. To będzie pozycja startowa.
2. Teraz, trzymając ramiona nieruchomo, na wydechu uginaj hantle, napinając bicepsy. Podnoś ciężary, aż bicepsy będą maksymalnie napięte, a hantle znajdą się na wysokości barków. Przytrzymaj napiętą pozycję przez chwilę, mocno zaciskając bicepsy.
3. Następnie, na wdechu, powoli zacznij opuszczać hantle do pozycji startowej.
4. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Dumbbell_Bicep_Curl/0.jpg', 'free_exercise_db'),
  ('dumbbell-clean', 'Podrzut hantli na barki', 'Dumbbell Clean', 'motor_coach', 'intermediate', array['Siłowe', 'Dwugłowe uda'], 'Eksplozywny ruch ogólnorozwojowy: hantle z podłogi wynosisz jednym płynnym wyskokiem na barki. Rozwija moc nóg, bioder i grzbietu.', '1. Zacznij w staniu z hantlą w każdej dłoni, stopy rozstawione na szerokość barków.
2. Opuszczając ciężary do podłogi, zegnij biodra i kolana, cofając biodra do tyłu, aż hantle dotkną podłogi. To będzie pozycja startowa.
3. Aby rozpocząć ruch, gwałtownie wyskocz w górę, prostując biodra, kolana i kostki, rozpędzając hantle ku górze. Zachowaj neutralny chwyt na hantlach i trzymaj ramiona proste aż do osiągnięcia pełnego wyprostu.
4. Po pełnym wyproście ponownie zegnij biodra i kolana, aby przyjąć ciężar w przysiadzie. Pozwól ramionom się zgiąć, prowadząc hantle do barków.
5. Przyjąwszy ciężar w pozycji przysiadu, wyprostuj biodra i kolana, kończąc w staniu z hantlami na barkach.', NULL, 'free-exercise-db/Dumbbell_Clean/0.jpg', 'free_exercise_db'),
  ('dumbbell-floor-press', 'Wyciskanie hantli leżąc na podłodze', 'Dumbbell Floor Press', 'motor_coach', 'intermediate', array['Trójbój', 'Triceps'], 'Wyciskanie hantli leżąc na podłodze zamiast na ławce. Ograniczony zakres chroni barki, mocno pracują tricepsy i klatka piersiowa.', '1. Połóż się na podłodze z hantlami w dłoniach. Kolana mogą być ugięte. Zacznij z ramionami całkowicie wyprostowanymi nad sobą.
2. Opuszczaj ciężary, aż górna część ramienia dotknie podłogi. Możesz trzymać łokcie blisko tułowia, aby mocniej pracowały tricepsy, lub skierować ramiona na boki, żeby skupić się na klatce piersiowej.
3. Zatrzymaj się na dole, a następnie dociśnij ciężary do siebie na górze, prostując łokcie.', NULL, 'free-exercise-db/Dumbbell_Floor_Press/0.jpg', 'free_exercise_db'),
  ('dumbbell-flyes', 'Rozpietki z hantlami na ławce płaskiej', 'Dumbbell Flyes', 'motor_coach', 'beginner', array['Siłowe', 'Klatka piersiowa'], 'Rozpietki — izolowane ćwiczenie na klatkę piersiową w leżeniu na ławce. Ramiona opuszczasz szerokim łukiem, aż poczujesz rozciąganie, a potem zaciskasz klatkę piersiową.', '1. Połóż się na ławce płaskiej z hantlą w każdej dłoni spoczywającą na udach. Dłonie powinny być zwrócone ku sobie.
2. Następnie, pomagając sobie udami, unieś hantle pojedynczo tak, aby móc trzymać je przed sobą na szerokość barków z dłońmi zwróconymi ku sobie. Unoś hantle w górę jak przy wyciskaniu, ale zatrzymaj się i przytrzymaj tuż przed zablokowaniem łokci. To będzie pozycja startowa.
3. Z lekko ugiętymi łokciami, aby nie obciążać ścięgna bicepsa, opuszczaj ramiona na obie strony w szerokim łuku, aż poczujesz rozciąganie klatki piersiowej. Wykonuj wdech w tej części ruchu. Wskazówka: pamiętaj, że w trakcie całego ruchu ramiona powinny pozostać nieruchome; ruch powinien odbywać się tylko w stawie barkowym.
4. Wróć ramionami do pozycji startowej, zaciskając mięśnie klatki piersiowej i wykonując wydech. Wskazówka: użyj tego samego łuku ruchu, którym opuszczałeś ciężary.
5. Przytrzymaj sekundę w napiętej pozycji i powtarzaj ruch przez zaleconą w programie liczbę powtórzeń.', NULL, 'free-exercise-db/Dumbbell_Flyes/0.jpg', 'free_exercise_db'),
  ('dumbbell-incline-row', 'Wiosłowanie hantlami na ławce skośnej', 'Dumbbell Incline Row', 'motor_coach', 'beginner', array['Siłowe', 'Środek pleców'], 'Wiosłowanie hantlami w leżeniu przodem na ławce skośnej. Buduje górne plecy bez obciążania dolnych pleców.', '1. W chwycie neutralnym oprzyj klatkę piersiową na ławce skośnej.
2. Weź hantlę w każdą dłoń chwytem neutralnym, zaczynając z ramionami wyprostowanymi. To będzie pozycja startowa.
3. Ściągnij łopatki i zegnij łokcie, wiosłując hantlami w kierunku boków tułowia.
4. Zatrzymaj się na szczycie ruchu, po czym wróć do pozycji startowej.', NULL, 'free-exercise-db/Dumbbell_Incline_Row/0.jpg', 'free_exercise_db'),
  ('dumbbell-incline-shoulder-raise', 'Unoszenie barków z hantlami na ławce skośnej', 'Dumbbell Incline Shoulder Raise', 'motor_coach', 'beginner', array['Siłowe', 'Barki'], 'Unoszenie barków (szrug) wykonywane w leżeniu na ławce skośnej z hantlami. Izoluje górną część mięśnia trapezowego.', '1. Usiądź na ławce skośnej, trzymając hantlę w każdej dłoni na udach.
2. Unieś nogi, aby kopnąć ciężary w kierunku barków i pochyl się do tyłu. Ustaw hantle nad barkami z wyprostowanymi ramionami. Ramiona powinny być prostopadłe do podłogi, dłonie skierowane do przodu, a kostki ku sufitowi. To będzie pozycja startowa.
3. Trzymając ramiona proste i zablokowane, unoś hantle, podnosząc barki znad ławki na wydechu.
4. Na wdechu wróć hantlami do pozycji startowej.
5. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Dumbbell_Incline_Shoulder_Raise/0.jpg', 'free_exercise_db'),
  ('dumbbell-lunges', 'Wykroki z hantlami', 'Dumbbell Lunges', 'motor_coach', 'beginner', array['Siłowe', 'Uda'], 'Klasyczne wykroki z hantlami po bokach ciała. Buduje nogi i pośladki, poprawia równowagę.', '1. Stań z wyprostowanym torsem, trzymając dwie hantle po bokach ciała. To będzie pozycja startowa.
2. Zrób krok w przód prawą nogą na około 60 cm, pozostawiając drugą stopę nieruchomo z tyłu, i opuszczaj górną część ciała w dół, zachowując wyprostowany tułów i równowagę. Wykonuj wdech podczas schodzenia. Uwaga: podobnie jak w innych ćwiczeniach, nie dopuść, aby kolano wyszło przed linię palców stopy podczas opuszczania, ponieważ powoduje to nadmierne obciążenie stawu kolanowego. Pilnuj, aby przednia goleń pozostała prostopadła do podłoża.
3. Odbij się w górę głównie piętą i wróć do pozycji startowej na wydechu.
4. Powtórz zalecaną liczbę powtórzeń, a następnie wykonaj ćwiczenie lewą nogą.', NULL, 'free-exercise-db/Dumbbell_Lunges/0.jpg', 'free_exercise_db'),
  ('dumbbell-lying-one-arm-rear-lateral-raise', 'Jednoręczne unoszenie hantli w leżeniu na brzuchu (tylne aktony)', 'Dumbbell Lying One-Arm Rear Lateral Raise', 'motor_coach', 'intermediate', array['Siłowe', 'Barki'], 'Izolowana praca nad tylnym aktonem barku — jedno ramię w leżeniu przodem na ławce skośnej. Pozwala skupić się na słabszej stronie.', '1. Trzymając hantlę w jednej dłoni, połóż się klatką piersiową na lekko pochylonej (ok. 15 stopni nad podłogą) regulowanej ławce. Drugą ręką możesz trzymać się nogi ławki dla stabilizacji.
2. Ustaw dłoń trzymającą hantlę neutralnie (dłoń skierowana ku tułowiu), trzymając ramię wyprostowane z lekko ugiętym łokciem. To będzie pozycja startowa.
3. Teraz na wydechu unoś ramię z hantlą na bok, aż łokieć znajdzie się na wysokości barku, a rameleon mniej więcej równolegle do podłogi. Wskazówka: utrzymuj ramię prostopadle do tułowia i wyprostowane przez cały ruch. Przytrzymaj też napięcie na górze przez sekundę.
4. Na wdechu powoli opuść hantlę do pozycji startowej.
5. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Dumbbell_Lying_One-Arm_Rear_Lateral_Raise/0.jpg', 'free_exercise_db'),
  ('dumbbell-lying-pronation', 'Pronacja ramienia z hantlą w leżeniu na brzuchu', 'Dumbbell Lying Pronation', 'motor_coach', 'intermediate', array['Siłowe', 'Przedramiona'], 'Ćwiczenie rotacyjne barku w leżeniu przodem z lekką hantlą. Wzmacnia rotatory zewnętrzne i stabilizację stawu barkowego.', '1. Połóż się twarzą w dół na ławce płaskiej, jedną ręką trzymając hantlę, a drugą złożoną na ławce tak, aby oprzeć na niej głowę.
2. Zegnij łokieć ręki trzymającej hantlę tak, aby między ramieniem a przedramieniem powstał kąt 90 stopni.
3. Teraz unieś ramię tak, aby przedramię było prostopadłe do podłogi, a ramię prostopadłe do tułowia. Wskazówka: ramię powinno być równoległe do podłogi i tworzyć kąt 90 stopni z tułowiem. To będzie pozycja startowa.
4. Na wydechu wykonuj rotację zewnętrzną przedramienia, unosząc hantlę do przodu i zachowując kąt 90 stopni między ramieniem a przedramieniem. Kontynuuj tę rotację zewnętrzną, aż przedramię będzie równoległe do podłogi. W tym momencie przytrzymaj napięcie przez sekundę.
5. Na wdechu powoli wróć do pozycji startowej.
6. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Dumbbell_Lying_Pronation/0.jpg', 'free_exercise_db'),
  ('dumbbell-lying-rear-lateral-raise', 'Unoszenie hantli w leżeniu na brzuchu (tylne aktony)', 'Dumbbell Lying Rear Lateral Raise', 'motor_coach', 'intermediate', array['Siłowe', 'Barki'], 'Unoszenie obu ramion na boki w leżeniu przodem na ławce skośnej. Klasyczna praca na tylne aktony barków.', '1. Trzymając hantlę w każdej dłoni, połóż się klatką piersiową na lekko pochylonej (ok. 15 stopni nad podłogą) regulowanej ławce.
2. Ustaw dłonie neutralnie (dłonie skierowane ku tułowiom), trzymając ramiona wyprostowane z lekko ugiętymi łokciami. To będzie pozycja startowa.
3. Teraz na wydechu unoś ramiona na boki, aż łokcie będą na wysokości barków, a ramiona mniej więcej równoległe do podłogi. Wskazówka: utrzymuj ramiona prostopadle do tułowia i wyprostowane przez cały ruch. Przytrzymaj też napięcie na górze przez sekundę.
4. Na wdechu powoli opuść hantle do pozycji startowej.
5. Powtórz zalecaną liczbę powtórzeń, a następnie przejdź do drugiej ręki.', NULL, 'free-exercise-db/Dumbbell_Lying_Rear_Lateral_Raise/0.jpg', 'free_exercise_db'),
  ('dumbbell-lying-supination', 'Supinacja ramienia z hantlą w leżeniu na boku', 'Dumbbell Lying Supination', 'motor_coach', 'intermediate', array['Siłowe', 'Przedramiona'], 'Rotacja zewnętrzna barku w leżeniu na boku z lekką hantlą. Wzmacnia rotatory barku, popularne ćwiczenie prewencyjne.', '1. Połóż się na boku na ławce płaskiej, jedną ręką trzymając hantlę, a drugą złożoną na ławce tak, aby oprzeć na niej głowę.
2. Zegnij łokieć ręki trzymającej hantlę tak, aby między ramieniem a przedramieniem powstał kąt 90 stopni.
3. Teraz unieś ramię tak, aby przedramię było równoległe do podłogi i prostopadłe do tułowia (wskazówka: przedramię będzie wtedy bezpośrednio przed tobą). Ramię pozostaje nieruchomo przy tułowiu i powinno być równoległe do podłogi (cały czas w linii z tułowiem). To będzie pozycja startowa.
4. Na wydechu wykonuj rotację zewnętrzną przedramienia, unosząc hantlę ruchem półkolistym i zachowując kąt 90 stopni między ramieniem a przedramieniem. Kontynuuj tę rotację zewnętrzną, aż przedramię będzie prostopadłe do podłogi i tułowia, skierowane ku sufitowi. W tym momencie przytrzymaj napięcie przez sekundę.
5. Na wdechu powoli wróć do pozycji startowej.
6. Powtórz zalecaną liczbę powtórzeń, a następnie zmień rękę.', NULL, 'free-exercise-db/Dumbbell_Lying_Supination/0.jpg', 'free_exercise_db'),
  ('dumbbell-one-arm-shoulder-press', 'Jednoręczne wyciskanie hantli nad głowę', 'Dumbbell One-Arm Shoulder Press', 'motor_coach', 'intermediate', array['Siłowe', 'Barki'], 'Wyciskanie hantli nad głowę jedną ręką w pozycji siedzącej lub stojącej. Poprawia siłę barków i stabilność korpusu.', '1. Weź hantlę i usiądź na ławce do wyciskania lub zwykłej ławce z podparciem pleców, kładąc hantlę pionowo na udzie, albo stań prosto.
2. Podrzuć hantlę, aby wynieść ją na wysokość barku. Druga ręka może być całkowicie wyprostowana na boku, przy pasie albo trzymać się stabilnego punktu.
3. Obróć nadgarstek tak, aby dłoń była skierowana do przodu. To jest pozycja startowa.
4. Na wydechu wypchnij hantlę w górę, aż ramię będzie całkowicie wyprostowane.
5. Po sekundowej pauzie powoli opuść hantlę do pozycji startowej na wdechu.
6. Powtórz zalecaną liczbę powtórzeń, a następnie zmień rękę.', NULL, 'free-exercise-db/Dumbbell_One-Arm_Shoulder_Press/0.jpg', 'free_exercise_db'),
  ('dumbbell-one-arm-triceps-extension', 'Jednoręczne prostowanie ramienia z hantlą za głowę', 'Dumbbell One-Arm Triceps Extension', 'motor_coach', 'intermediate', array['Siłowe', 'Triceps'], 'Prostowanie ramienia z hantlą za głowę — izolacja tricepsa jednorącz. Dobrze rozciąga długą głowę tricepsa.', '1. Weź hantlę i usiądź na ławce do wyciskania lub zwykłej ławce z podparciem pleców, kładąc hantlę pionowo na udzie, albo stań prosto.
2. Podrzuć hantlę, aby wynieść ją na wysokość barku, a następnie wyprostuj ramię nad głową tak, aby całe ramię było prostopadłe do podłogi i znalazło się przy głowie. Hantla powinna być nad tobą. Druga ręka może być całkowicie wyprostowana na boku, przy pasie, podpierać ramię trzymające hantlę albo trzymać się stabilnego punktu.
3. Obróć nadgarstek tak, aby dłoń była skierowana do przodu, a mały palec ku sufitowi. To będzie pozycja startowa.
4. Powoli opuszczaj hantlę za głowę, trzymając ramię nieruchomo. Wykonuj wdech podczas tego ruchu i zatrzymaj się, gdy triceps będzie maksymalnie rozciągnięty.
5. Wróć do pozycji startowej, prostując ramię pracą tricepsa na wydechu. Wskazówka: kluczowe jest, aby poruszało się tylko przedramię. Ramię musi cały czas pozostać nieruchome przy głowie.
6. Powtórz zalecaną liczbę powtórzeń i zmień rękę.', NULL, 'free-exercise-db/Dumbbell_One-Arm_Triceps_Extension/0.jpg', 'free_exercise_db'),
  ('dumbbell-one-arm-upright-row', 'Jednoręczne podciąganie hantli wzdłuż tułowia', 'Dumbbell One-Arm Upright Row', 'motor_coach', 'intermediate', array['Siłowe', 'Barki'], 'Unoszenie hantli wzdłuż tułowia jedną ręką do wysokości brody. Angażuje boki barków i trapezius.', '1. Weź hantlę i stań prosto z ramieniem wyprostowanym przed sobą, z lekko ugiętym łokciem i prostymi plecami. To będzie pozycja startowa. Wskazówka: hantla powinna spoczywać na udzie, a dłoń być zwrócona ku udowi.
2. Drugą rękę trzymaj całkowicie wyprostowaną na boku, przy pasie albo obejmij nią stabilny punkt podparcia.
3. Na wydechu unieś hantlę siłą bocznej części barków. Hantla powinna pozostawać blisko ciała podczas unoszenia. Podnoś ją, aż znajdzie się prawie w linii z brodą. Wskazówka: to łokcie prowadzą ruch. Podczas unoszenia hantli łokieć zawsze powinien być wyżej niż przedramię. Trzymaj także tułów nieruchomo i zatrzymaj się na sekundę na szczycie ruchu.
4. Powoli opuść hantlę do pozycji startowej. Wykonuj wdech w tej części ruchu.
5. Powtórz zalecaną liczbę powtórzeń i zmień rękę.', NULL, 'free-exercise-db/Dumbbell_One-Arm_Upright_Row/0.jpg', 'free_exercise_db'),
  ('dumbbell-prone-incline-curl', 'Uginanie ramion z hantlami w leżeniu na ławce skośnej', 'Dumbbell Prone Incline Curl', 'motor_coach', 'intermediate', array['Siłowe', 'Biceps'], 'Uginanie ramion z hantlami w leżeniu przodem na ławce skośnej. Eliminuje oszukiwanie — biceps pracuje w pełnym zakresie.', '1. Weź hantlę w każdą dłoń i połóż się twarzą w dół na ławce skośnej z barkami blisko jej górnej krawędzi. Kolana możesz oprzeć na siedzisku albo rozłożyć nogi po obu stronach ławki (moim ulubionym sposobem).
2. Pozwól ramionom swobodnie zwisać przed tobą, tak aby były prostopadłe do podłogi.
3. Teraz przyciągnij łokcie do tułowia i skieruj dłonie do przodu. To będzie pozycja startowa.
4. Unoś hantle, napinając bicepsy, aż ramiona będą całkowicie ugięte. Wykonuj wydech w tej części ruchu i pilnuj, aby poruszały się tylko przedramiona. Górne części ramion muszą cały czas pozostać nieruchome.
5. Opuść hantle, aż ramiona będą całkowicie wyprostowane.
6. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Dumbbell_Prone_Incline_Curl/0.jpg', 'free_exercise_db'),
  ('dumbbell-raise', 'Podciąganie hantli wzdłuż tułowia', 'Dumbbell Raise', 'motor_coach', 'beginner', array['Siłowe', 'Barki'], 'Unoszenie obu hantli wzdłuż tułowia do wysokości brody (dwuręczny wariant upright row). Mocna praca bocznych barków i trapeziusa.', '1. Weź hantlę w każdą dłoń i stań prosto z ramionami opuszczonymi wzdłuż ciała, lekko ugiętymi w łokciach i prostymi plecami. To będzie pozycja startowa. Wskazówka: hantle powinny być przy udach, a dłonie skierowane do tyłu.
2. Na wydechu unieś hantle siłą bocznej części barków. Hantle powinny pozostawać przy bokach ciała podczas unoszenia. Podnoś je, aż znajdą się prawie w linii z brodą. Wskazówka: to łokcie prowadzą ruch. Podczas unoszenia hantli łokieć zawsze powinien być wyżej niż przedramię. Trzymaj także tułów nieruchomo i zatrzymaj się na sekundę na szczycie ruchu.
3. Powoli opuść hantle do pozycji startowej. Wykonuj wdech w tej części ruchu.
4. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Dumbbell_Raise/0.jpg', 'free_exercise_db'),
  ('dumbbell-rear-lunge', 'Wykroki w tył z hantlami', 'Dumbbell Rear Lunge', 'motor_coach', 'intermediate', array['Siłowe', 'Uda'], 'Wykrok wykonywany nogą w tył z hantlami po bokach. Łagodniejszy dla kolan niż wersja w przód, mocno angażuje pośladki.', '1. Stań z wyprostowanym torsem, trzymając dwie hantle po bokach ciała. To będzie pozycja startowa.
2. Zrób krok w tył prawą nogą na około 60 cm od lewej stopy i opuszczaj górną część ciała w dół, zachowując wyprostowany tułów i równowagę. Wykonuj wdech podczas schodzenia. Wskazówka: podobnie jak w innych ćwiczeniach, nie dopuść, aby przednie kolano wyszło przed linię palców stopy podczas opuszczania, ponieważ powoduje to nadmierne obciążenie stawu kolanowego. Pilnuj, aby przednia goleń pozostała prostopadła do podłoża. Utrzymuj tułów wyprostowany w trakcie wykroku; ważne są elastyczne zginacze bioder. Długi wykrok mocniej angażuje mięsień pośladkowy wielki, krótki — mięśnie czworogłowe uda.
3. Odbij się w górę i wróć do pozycji startowej na wydechu. Wskazówka: odbijaj się śródstopiem, aby mocniej pracowały mięśnie czworogłowe uda; aby skupić się na pośladkach, odpychaj się piętami.
4. Teraz powtórz ruch drugą nogą.', NULL, 'free-exercise-db/Dumbbell_Rear_Lunge/0.jpg', 'free_exercise_db'),
  ('dumbbell-scaption', 'Unoszenie ramion w płaszczyźnie łopatkowej', 'Dumbbell Scaption', 'motor_coach', 'beginner', array['Siłowe', 'Barki'], 'Ćwiczenie korekcyjne — unoszenie ramion przed sobą w płaszczyźnie łopatkowej (ok. 30 stopni od środka ciała) z lekkimi ciężarami. Wzmacnia mięśnie stabilizujące łopatkę.', '1. To ćwiczenie korekcyjne wzmacnia mięśnie stabilizujące łopatkę. Trzymaj lekki ciężar w każdej dłoni, swobodnie opuszczony po bokach ciała. Kciuki powinny być skierowane w górę.
2. Rozpocznij ruch, unosząc ramiona przed sobą, około 30 stopni od linii środkowej ciała. Ramiona powinny być całkowicie wyprostowane podczas wykonywania ruchu.
3. Kontynuuj, aż ramiona będą równoległe do podłoża, po czym wróć do pozycji startowej.', NULL, 'free-exercise-db/Dumbbell_Scaption/0.jpg', 'free_exercise_db'),
  ('dumbbell-seated-box-jump', 'Skoki na skrzynię z hantlami z siadu', 'Dumbbell Seated Box Jump', 'motor_coach', 'intermediate', array['Plyometryka', 'Uda'], 'Skok na skrzynię z pozycji siedzącej na ławce, z hantlą trzymaną przy klatce piersiowej. Rozwija eksplozywność nóg.', '1. Ustaw skrzynię około metra z boku ławki. Trzymaj hantlę przy klatce piersiowej oburącz i usiądź na ławce twarzą do skrzyni. To będzie pozycja startowa.
2. Zaprzyj stopy mocno o podłogę, pochyl się do przodu i wybij się, prostując biodra i kolana, aby wyskoczyć w górę i do przodu.
3. Wyląduj na skrzyni obiema stopami, amortyzując uderzenie zgięciem bioder i kolan.
4. Zejdź ze skrzyni i wróć do pozycji startowej.', NULL, 'free-exercise-db/Dumbbell_Seated_Box_Jump/0.jpg', 'free_exercise_db'),
  ('dumbbell-seated-one-leg-calf-raise', 'Wspięcia na palce jednonóż w siadzie z hantlą', 'Dumbbell Seated One-Leg Calf Raise', 'motor_coach', 'beginner', array['Siłowe', 'Łydki'], 'Wspięcia na palce jednej nogi w siadzie, z hantlą położoną na udzie. Izoluje łydkę i pozwala precyzyjnie kontrolować zakres ruchu.', '1. Połóż klocek na podłodze około 30 cm od ławki płaskiej.
2. Usiądź na ławce płaskiej i połóż hantlę na udzie lewej nogi, około 8 cm nad kolanem.
3. Teraz ustaw śródstopie lewej stopy na klocku. To będzie pozycja startowa.
4. Na wydechu unieś palce jak najwyżej, napinając mięsień łydki. Przytrzymaj napięcie przez sekundę.
5. Powoli wróć do pozycji startowej, rozciągając się maksymalnie w dół.
6. Powtórz zalecaną liczbę powtórzeń, a następnie wykonaj ćwiczenie prawą nogą.', NULL, 'free-exercise-db/Dumbbell_Seated_One-Leg_Calf_Raise/0.jpg', 'free_exercise_db'),
  ('dumbbell-shoulder-press', 'Wyciskanie hantli nad głowę w siadzie', 'Dumbbell Shoulder Press', 'motor_coach', 'intermediate', array['Siłowe', 'Barki'], 'Podstawowe wyciskanie hantli nad głowę w siadzie z podparciem pleców. Buduje masę i siłę całych barków.', '1. Trzymając hantlę w każdej dłoni, usiądź na ławce do wyciskania lub zwykłej ławce z podparciem pleców. Połóż hantle pionowo na udach.
2. Teraz unoś hantle na wysokość barków pojedynczo, pomagając sobie udami, aby je wynieść.
3. Pilnuj, aby obrócić nadgarstki tak, aby dłonie były skierowane do przodu. To jest pozycja startowa.
4. Teraz na wydechu wypychaj hantle w górę, aż zetkną się na szczycie.
5. Następnie, po krótkiej pauzie w napiętej pozycji na górze, powoli opuszczaj ciężary do pozycji startowej, robiąc wdech.
6. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Dumbbell_Shoulder_Press/0.jpg', 'free_exercise_db'),
  ('dumbbell-shrug', 'Unoszenie barków z hantlami', 'Dumbbell Shrug', 'motor_coach', 'beginner', array['Siłowe', 'Czworoboczne'], 'Unoszenie barków (szrug) z hantlami — proste ćwiczenie na górną część trapeziusa. Krótki ruch w górę i kontrolowane opuszczanie.', '1. Stań prosto z hantlą w każdej dłoni (dłonie zwrócone ku tułowiu), ramiona wyprostowane wzdłuż ciała.
2. Na wydechu unieś hantle, podnosząc barki jak najwyżej. Przytrzymaj napięcie na górze przez sekundę. Wskazówka: ramiona powinny cały czas pozostać wyprostowane. Nie pomagaj sobie bicepsem. W górę i w dół powinny poruszać się tylko barki.
3. Opuść hantle z powrotem do pozycji wyjściowej.
4. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Dumbbell_Shrug/0.jpg', 'free_exercise_db'),
  ('dumbbell-side-bend', 'Skłony boczne z hantlą', 'Dumbbell Side Bend', 'motor_coach', 'beginner', array['Siłowe', 'Brzuch'], 'Skłony boczne z hantlą w jednej dłoni. Wzmacnia mięskie boczne brzucha i poprawia stabilność korpusu.', '1. Stań prosto, trzymając hantlę w lewej dłoni (dłoń zwrócona ku tułowiu), a prawą ręką obejmując pas. Stopy rozstawione na szerokość barków. To będzie pozycja startowa.
2. Z prostymi plecami i głową uniesioną pochyl się tylko w pasie w prawo, jak najdalej. Wykonuj wdech podczas skłonu w bok. Następnie przytrzymaj sekundę i wróć do pozycji startowej na wydechu. Wskazówka: reszta ciała powinna pozostać nieruchoma.
3. Teraz powtórz ruch, ale pochylając się w lewo. Przytrzymaj sekundę i wróć do pozycji startowej.
4. Powtórz zalecaną liczbę powtórzeń, a następnie zmień rękę.', NULL, 'free-exercise-db/Dumbbell_Side_Bend/0.jpg', 'free_exercise_db'),
  ('dumbbell-squat', 'Przysiad z hantlami', 'Dumbbell Squat', 'motor_coach', 'beginner', array['Siłowe', 'Uda'], 'Przysiad z hantlami w obu dłoniach. Podstawowe ćwiczenie budujące nogi i pośladki.', '1. Stań prosto, trzymając hantlę w każdej dłoni (dłonie zwrócone ku udom).
2. Ustaw nogi w średnim rozstawie na szerokość barków, z palcami lekko skierowanymi na zewnątrz. Cały czas trzymaj głowę uniesioną, bo patrzenie w dół zaburza równowagę, i zachowuj proste plecy. To będzie pozycja startowa. Uwaga: w tym opisie stosujemy średni rozstaw opisany powyżej, który zapewnia wszechstronny rozwój; możesz jednak wybrać dowolny z trzech rozstawów opisanych w sekcji o ustawieniu stóp.
3. Zacznij powoli opuszczać tułów, uginając kolana, zachowując prostą sylwetkę z głową uniesioną. Schodź, aż uda będą równoległe do podłogi. Wskazówka: jeśli wykonałeś ćwiczenie poprawnie, przód kolan powinien tworzyć umowną prostą z palcami stóp, prostopadłą do frontu. Jeśli kolana przekroczą tę umowną linię (jadą poza palce), to nadwyrężasz kolano, a ćwiczenie zostało wykonane błędnie.
4. Zacznij prostować tułów na wydechu, odpychając się od podłogi głównie piętą, gdy ponownie prostujesz nogi i wracasz do pozycji startowej.
5. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Dumbbell_Squat/0.jpg', 'free_exercise_db'),
  ('dumbbell-squat-to-a-bench', 'Przysiad z hantlami do ławki', 'Dumbbell Squat To A Bench', 'motor_coach', 'intermediate', array['Siłowe', 'Uda'], 'Przysiad z hantlami wykonywany do delikatnego dotknięcia ławki za sobą. Pomaga nauczyć się prawidłowej głębokości i kontrolowanego ruchu.', '1. Stań prosto z ławką płaską za sobą, trzymając hantlę w każdej dłoni (dłonie zwrócone ku udom).
2. Ustaw nogi w średnim rozstawie na szerokość barków, z palcami lekko skierowanymi na zewnątrz. Cały czas trzymaj głowę uniesioną, bo patrzenie w dół zaburza równowagę, i zachowuj proste plecy. To będzie pozycja startowa. Uwaga: w tym opisie stosujemy średni rozstaw opisany powyżej, który zapewnia wszechstronny rozwój; możesz jednak wybrać dowolny z trzech rozstawów opisanych w sekcji o ustawieniu stóp.
3. Zacznij powoli opuszczać tułów, uginając kolana, zachowując prostą sylwetkę z głową uniesioną. Schodź, aż delikatnie dotkniesz ławki za sobą. Wykonuj wdech w tej części ruchu. Wskazówka: jeśli wykonałeś ćwiczenie poprawnie, przód kolan powinien tworzyć umowną prostą z palcami stóp, prostopadłą do frontu. Jeśli kolana przekroczą tę umowną linię (jadą poza palce), to nadwyrężasz kolano, a ćwiczenie zostało wykonane błędnie.
4. Zacznij unosić ciężar na wydechu, odpychając się od podłogi głównie piętą, gdy ponownie prostujesz nogi i wracasz do pozycji startowej.
5. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Dumbbell_Squat_To_A_Bench/0.jpg', 'free_exercise_db'),
  ('dumbbell-step-ups', 'Wejścia na podwyższenie z hantlami', 'Dumbbell Step Ups', 'motor_coach', 'intermediate', array['Siłowe', 'Uda'], 'Wejścia na podwyższenie z hantlami w dłoniach. Buduje nogi i pośladki, poprawiając równowagę i stabilność.', '1. Stań prosto, trzymając hantlę w każdej dłoni (dłonie zwrócone ku udom).
2. Postaw prawą stopę na podwyższonej platformie. Wejdź na platformę, prostując biodro i kolano prawej nogi. Użyj głównie pięty, aby unieść resztę ciała, i postaw również lewą stopę na platformie. Wykonuj wydech podczas generowania siły potrzebnej do wejścia.
3. Zejdź lewą nogą, uginając biodro i kolano prawej nogi na wdechu. Wróć do pierwotnej pozycji stojącej, stawiając prawą stopę obok lewej.
4. Powtarzaj prawą nogą zalecaną liczbę powtórzeń, a następnie wykonaj ćwiczenie lewą nogą.', NULL, 'free-exercise-db/Dumbbell_Step_Ups/0.jpg', 'free_exercise_db'),
  ('dumbbell-tricep-extension-pronated-grip', 'Prostowanie ramion z hantlami nad głowę chwytem nachwytem', 'Dumbbell Tricep Extension -Pronated Grip', 'motor_coach', 'beginner', array['Siłowe', 'Triceps'], 'Prostowanie ramion z hantlami nad głowę w leżeniu na ławce, chwytem nachwytem. Izoluje wszystkie głowy tricepsa.', '1. Połóż się na ławce płaskiej, trzymając dwie hantle dokładnie nad barkami. Ramiona powinny być całkowicie wyprostowane i tworzyć kąt 90 stopni względem tułowia i podłogi.
2. Dłonie powinny być skierowane do przodu, a łokcie przyciągnięte do siebie. To będzie pozycja startowa.
3. Teraz na wdechu powoli opuszczaj hantle, aż zbliżą się do uszu. Pilnuj, aby ramiona pozostały nieruchome, a łokcie przyciągnięte do siebie.
4. Następnie na wydechu prostuj ramiona pracą tricepsa, wracając ciężarem do pozycji startowej.', NULL, 'free-exercise-db/Dumbbell_Tricep_Extension_-Pronated_Grip/0.jpg', 'free_exercise_db'),
  ('dynamic-back-stretch', 'Dynamiczne rozciąganie pleców', 'Dynamic Back Stretch', 'motor_coach', 'beginner', array['Rozciąganie', 'Najszersze grzbietu'], 'Dynamiczna rozgrzewka pleców — wymachy prostymi ramionami w górę przed sobą. Przygotowuje barki i plecy do treningu.', '1. Stań ze stopami rozstawionymi na szerokość barków. To będzie pozycja startowa.
2. Trzymając ramiona proste, wymachuj nimi prosto w górę przed sobą 5–10 razy, zwiększając zakres ruchu z każdym powtórzeniem, aż ramiona znajdą się nad głową.', NULL, 'free-exercise-db/Dynamic_Back_Stretch/0.jpg', 'free_exercise_db'),
  ('dynamic-chest-stretch', 'Dynamiczne rozciąganie klatki piersiowej', 'Dynamic Chest Stretch', 'motor_coach', 'beginner', array['Rozciąganie', 'Klatka piersiowa'], 'Dynamiczne rozciąganie klatki piersiowej — szybkie odchylanie wyprostowanych ramion w tył i z powrotem. Idealne jako element rozgrzewki górnej części ciała.', '1. Stań ze złączonymi dłońmi i ramionami wyprostowanymi bezpośrednio przed sobą. To będzie pozycja startowa.
2. Trzymając ramiona proste, szybko odchylaj ramiona jak najdalej w tył i z powrotem, podobnie do przesadzonego klaśnięcia. Powtórz 5–10 razy, stopniowo przyspieszając.', NULL, 'free-exercise-db/Dynamic_Chest_Stretch/0.jpg', 'free_exercise_db'),
  ('elbow-circles', 'Krążenia łokci', 'Elbow Circles', 'motor_coach', 'beginner', array['Rozciąganie', 'Barki'], 'Krążenia łokciami z dłońmi położonymi na barkach. Prosta mobilizacja obręczy barkowej na rozgrzewkę.', '1. Usiądź lub stań ze stopami lekko rozstawionymi.
2. Połóż dłonie na barkach tak, aby łokcie były na wysokości barków i skierowane na zewnątrz.
3. Powoli wykonuj koło łokciami. Wykonuj wydech, gdy zaczynasz koło, i wdech, gdy je kończysz.', NULL, 'free-exercise-db/Elbow_Circles/0.jpg', 'free_exercise_db'),
  ('elbow-to-knee', 'Łokieć do kolana', 'Elbow to Knee', 'motor_coach', 'beginner', array['Siłowe', 'Brzuch'], 'Skośne spięcie brzucha w leżeniu — lewy łokieć do prawego kolana. Mocno pracują mięśnie skośne brzucha.', '1. Połóż się na podłodze, krzyżując prawą nogę nad ugiętym lewym kolanem. Splecionymi dłońmi za głową zacznij z ściągniętymi łopatkami na podłodze. To będzie pozycja startowa.
2. Wykonuj ruch, zginając kręgosłup i obracając tułów, aby doprowadzić lewy łokieć do prawego kolana.
3. Wróć do pozycji startowej i powtarzaj ruch żądaną liczbę powtórzeń, po czym zmień strony.', NULL, 'free-exercise-db/Elbow_to_Knee/0.jpg', 'free_exercise_db'),
  ('elbows-back', 'Łokcie do tyłu', 'Elbows Back', 'motor_coach', 'beginner', array['Rozciąganie', 'Klatka piersiowa'], 'Delikatne rozciąganie klatki piersiowej — dłonie na dolnych plecach i ściąganie łokci do tyłu. Dobre przerwanie długiego siedzenia.', '1. Stań prosto.
2. Połóż obie dłonie na dolnych plecach, palce skierowane w dół i łokcie na zewnątrz.
3. Następnie delikatnie prowadź łokcie do tyłu, starając się zetknąć ich końce.', NULL, 'free-exercise-db/Elbows_Back/0.jpg', 'free_exercise_db'),
  ('elevated-back-lunge', 'Wykroki w tył ze sztangą z podwyższenia', 'Elevated Back Lunge', 'motor_coach', 'intermediate', array['Siłowe', 'Uda'], 'Wykrok w tył ze sztangą na barkach, wykonywany stojąc na niskim podwyższeniu. Zwiększony zakres ruchu mocniej pracuje nogi i pośladki.', '1. Ustaw sztangę na stojaku na wysokości barków z odpowiednim obciążeniem. Postaw za sobą niskie podwyższenie.
2. Załóż sztangę na górną część pleców, trzymając plecy wygięte i napięte. Stań obiema stopami na podwyższeniu. To będzie pozycja startowa.
3. Zacznij od kroku w tył jedną nogą. Opuszczaj ciało, zginając biodra i kolana, aż kolano dotknie podłogi.
4. Zatrzymaj się, a następnie prostuj biodra i kolana, wstając i wracając całkowicie do pozycji startowej, zanim zmienisz nogę.', NULL, 'free-exercise-db/Elevated_Back_Lunge/0.jpg', 'free_exercise_db'),
  ('elevated-cable-rows', 'Wiosłowanie na wyciągu dolnym z podwyższeniem', 'Elevated Cable Rows', 'motor_coach', 'intermediate', array['Siłowe', 'Najszersze grzbietu'], 'Wiosłowanie linką wyciągu dolnego z podniesioną platformą pod stopy. Buduje grubość pleców z pełnym rozciągnięciem najszerszych mięśni.', '1. Znajdź jakąś platformę (może być platforma do aerobiku lub wspięć na palce) o wysokości około 10–15 cm.
2. Połóż ją na siedzisku maszyny do wiosłowania na wyciągu dolnym.
3. Usiądź na maszynie i połóż stopy na przedniej platformie lub poprzeczce, dbając o to, aby kolana były lekko ugięte, a nie zablokowane.
4. Pochyl się do przodu, zachowując naturalne ustawienie pleców, i złap uchwyt w kształcie litery V.
5. Z wyprostowanymi ramionami odchyl się do tyłu, aż tułów utworzy kąt 90 stopni z nogami. Plecy powinny być lekko wygięte, a klatka piersiowa wypchnięta do przodu. Trzymając drążek przed sobą, powinieneś czuć przyjemne rozciągnięcie najszerszych mięśni pleców. To jest pozycja startowa ćwiczenia.
6. Trzymając tułów nieruchomo, ciągnij uchwyty w kierunku tułowia, trzymając ramiona blisko niego, aż dotkniesz brzuchem uchwytów. Wykonuj wydech podczas tego ruchu. W tym momencie powinieneś mocno napinać mięśnie pleców. Przytrzymaj napięcie przez sekundę i powoli wracaj do pierwotnej pozycji na wdechu.
7. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Elevated_Cable_Rows/0.jpg', 'free_exercise_db'),
  ('elliptical-trainer', 'Orbitrek', 'Elliptical Trainer', 'motor_coach', 'intermediate', array['Cardio', 'Uda'], 'Trening cardio na orbitreku — mało obciąża stawy. Intensywność reguluje się oporem i nachyleniem maszyny.', '1. Aby rozpocząć, wejdź na orbitrek i wybierz żądaną opcję z menu. Większość orbitreków ma tryb manualny albo można wybrać program treningowy. Zazwyczaj można wpisać wiek i wagę, aby oszacować liczbę kalorii spalonych podczas ćwiczeń. Nachylenie można regulować, aby zmienić intensywność treningu.
2. Uchwyty mogą służyć do monitorowania tętna, aby pomóc utrzymać odpowiednią intensywność.', NULL, 'free-exercise-db/Elliptical_Trainer/0.jpg', 'free_exercise_db'),
  ('exercise-ball-crunch', 'Spięcia brzucha na piłce gimnastycznej', 'Exercise Ball Crunch', 'motor_coach', 'beginner', array['Siłowe', 'Brzuch'], 'Spięcia brzucha w leżeniu na piłce gimnastycznej. Większy zakres ruchu niż na podłodze i mocniejsze rozciągnięcie mięśni brzucha.', '1. Połóż się na piłce gimnastycznej tak, aby krzywizna dolnych pleców przylegała do kulistej powierzchni piłki. Kolana powinny być ugięte, a stopy pewnie oparte o podłogę. Górna część tułowia powinna zwisać ponad szczytem piłki. Ramiona trzymaj wzdłuż ciała lub skrzyżowane na klatce piersiowej, ponieważ te pozycje zapobiegają urazom szyi (w odróżnieniu od pozycji dłoni z tyłu głowy).
2. Opuszczaj tułów do pozycji rozciągania, cały czas trzymając szyję nieruchomo. To będzie pozycja startowa.
3. Z nieruchomymi biodrami zginaj pas, napinając mięśnie brzucha i podwijając barki oraz tułów w górę, aż poczujesz dobre napięcie mięśni brzucha. Jeśli ramiona są wzdłuż ciała, powinny po prostu sunąć po udach; jeśli skrzyżowane — pozostawać na klatce piersiowej. Dolne plecy powinny cały czas pozostawać w kontakcie z piłką. Wykonuj wydech podczas tego ruchu i przytrzymaj napięcie przez sekundę.
4. Na wdechu wróć do pozycji startowej.
5. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Exercise_Ball_Crunch/0.jpg', 'free_exercise_db'),
  ('exercise-ball-pull-in', 'Przyciąganie kolan na piłce gimnastycznej', 'Exercise Ball Pull-In', 'motor_coach', 'beginner', array['Siłowe', 'Brzuch'], 'Przyciąganie kolan do klatki piersiowej w podporze, z goleniami na piłce gimnastycznej. Świetne ćwiczenie na dolną część brzucha i stabilizację.', '1. Umieść piłkę gimnastyczną obok i połóż się na podłodze przed nią, z dłońmi opartymi o podłogę na szerokość barków w pozycji do pompek.
2. Teraz połóż dolne części goleni na piłce gimnastycznej. Wskazówka: w tym momencie nogi powinny być całkowicie wyprostowane z goléniami na piłce, a górna część ciała w pozycji podobnej do pompki, podparta dwiema wyprostowanymi ramionami przed tobą. To będzie pozycja startowa.
3. Trzymając plecy całkowicie proste i górną część ciała nieruchomo, przyciągaj kolana w kierunku klatki piersiowej na wydechu, pozwalając piłce turlać się do przodu pod kostkami. Zaciśnij mięśnie brzucha i przytrzymaj tę pozycję przez sekundę.
4. Teraz powoli wyprostuj nogi, tocząc piłkę z powrotem do pozycji startowej na wdechu.
5. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Exercise_Ball_Pull-In/0.jpg', 'free_exercise_db'),
  ('extended-range-one-arm-kettlebell-floor-press', 'Jednoręczne wyciskanie kettlebell leżąc na podłodze', 'Extended Range One-Arm Kettlebell Floor Press', 'motor_coach', 'beginner', array['Siłowe', 'Klatka piersiowa'], 'Jednoręczne wyciskanie kettlebell leżąc na podłodze, z pogłębionym zakresem ruchu. Buduje siłę klatki piersiowej i tricepsów, ucząc stabilności barku.', '1. Połóż się na podłodze i ustaw kettlebell tak, aby móc go wyciskać jedną ręką. Kettlebell powinien być trzymany za uchwyt. Noga po tej samej stronie, którą wyciskasz, powinna być ugięta, z kolanem przechodzącym za linię środka ciała.
2. Wyciśnij kettlebell, prostując łokieć i przywodząc ramię, wypychając go nad ciało. Wróć do pozycji startowej.', NULL, 'free-exercise-db/Extended_Range_One-Arm_Kettlebell_Floor_Press/0.jpg', 'free_exercise_db'),
  ('external-rotation', 'Rotacja zewnętrzna barku w leżeniu na boku', 'External Rotation', 'motor_coach', 'beginner', array['Siłowe', 'Barki'], 'Rotacja zewnętrzna barku w leżeniu na boku z lekką hantlą. Kluczowe ćwiczenie zdrowotne dla rotatorów barku.', '1. Połóż się na boku na ławce płaskiej, jedną ręką trzymając hantlę, a drugą złożoną na ławce tak, aby oprzeć na niej głowę.
2. Zegnij łokieć ręki trzymającej hantlę tak, aby między ramieniem a przedramieniem powstał kąt 90 stopni. Wskazówka: trzymaj ramię równolegle do tułowia.
3. Teraz ugnij łokieć, trzymając ramię nieruchomo. W ten sposób przedramię będzie równoległe do podłogi i prostopadłe do tułowia (wskazówka: przedramię będzie wtedy bezpośrednio przed tobą). Ramię pozostaje nieruchomo przy tułowiu i powinno być równoległe do podłogi (cały czas w linii z tułowiem). To będzie pozycja startowa.
4. Na wydechu wykonuj rotację zewnętrzną przedramienia, unosząc hantlę ruchem półkolistym i zachowując kąt 90 stopni między ramieniem a przedramieniem. Kontynuuj tę rotację zewnętrzną, aż przedramię będzie prostopadłe do podłogi i tułowia, skierowane ku sufitowi. W tym momencie przytrzymaj napięcie przez sekundę.
5. Na wdechu powoli wróć do pozycji startowej.
6. Powtórz zalecaną liczbę powtórzeń, a następnie zmień rękę.', NULL, 'free-exercise-db/External_Rotation/0.jpg', 'free_exercise_db'),
  ('external-rotation-with-band', 'Rotacja zewnętrzna barku z gumą oporową', 'External Rotation with Band', 'motor_coach', 'beginner', array['Siłowe', 'Barki'], 'Rotacja zewnętrzna barku z gumą oporową, przy łokciu dociśniętym do tułowia. Wzmacnia rotatory barku i stabilizuje staw barkowy.', '1. Owiń gumę wokół słupa. Guma powinna znajdować się na wysokości twojego łokcia. Stań lewym bokiem do gumy, w odległości około metra.
2. Złap koniec gumy prawą ręką i mocno dociśnij łokieć do tułowia. Zalecamy przytrzymanie poduszki lub rolki łokciem, aby utrzymać go pewnie w miejscu.
3. Z ramieniem w tej pozycji łokieć powinien być zgięty pod kątem 90 stopni, a dłoń sięgać przez przód tułowia. To będzie pozycja startowa.
4. Wykonaj ruch, obracając ramię ruchem jak przy uderzeniu grzbiecistem, utrzymując łokieć w miejscu.
5. Idź tak daleko, jak potrafisz, zatrzymaj się, a następnie wróć do pozycji startowej.', NULL, 'free-exercise-db/External_Rotation_with_Band/0.jpg', 'free_exercise_db'),
  ('external-rotation-with-cable', 'Rotacja zewnętrzna barku na wyciągu', 'External Rotation with Cable', 'motor_coach', 'beginner', array['Siłowe', 'Barki'], 'Rotacja zewnętrzna barku na wyciągu — wariant ze stałym oporem. Świetne do profilaktyki i rehabilitacji barku.', '1. Ustaw wyciąg na wysokość swojego łokcia. Stań lewym bokiem do niego w odległości około metra.
2. Złap uchwyt prawą ręką i mocno dociśnij łokieć do tułowia. Zalecamy przytrzymanie poduszki lub rolki łokciem, aby utrzymać go pewnie w miejscu.
3. Z ramieniem w tej pozycji łokieć powinien być zgięty pod kątem 90 stopni, a dłoń sięgać przez przód tułowia. To będzie pozycja startowa.
4. Wykonaj ruch, obracając ramię ruchem jak przy uderzeniu grzbiecistem, utrzymując łokieć w miejscu.', NULL, 'free-exercise-db/External_Rotation_with_Cable/0.jpg', 'free_exercise_db'),
  ('ez-bar-curl', 'Uginanie ramion ze sztangą łamaną', 'EZ-Bar Curl', 'motor_coach', 'beginner', array['Siłowe', 'Biceps'], 'Uginanie ramion ze sztangą łamaną — podstawowe ćwiczenie na biceps. Ergonomiczny kształt gryfu odciąża nadgarstki.', '1. Stań prosto, trzymając sztangę łamaną za szerokie, zewnętrzne uchwyty. Dłonie powinny być skierowane do przodu i lekko skręcone do wewnątrz ze względu na kształt gryfu. Trzymaj łokcie blisko tułowia. To będzie pozycja startowa.
2. Teraz, trzymając ramiona nieruchomo, na wydechu uginaj ciężar w przód, napinając bicepsy. Skup się na pracy samych przedramion.
3. Podnoś ciężar, aż bicepsy będą maksymalnie napięte, a sztanga znajdzie się na wysokości barków. Przytrzymaj chwilę napiętą pozycję na górze i mocno zaciśnij bicepsy.
4. Następnie na wdechu powoli opuść sztangę do pozycji startowej.
5. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/EZ-Bar_Curl/0.jpg', 'free_exercise_db'),
  ('ez-bar-skullcrusher', 'Wyciskanie francuskie ze sztangą łamaną', 'EZ-Bar Skullcrusher', 'motor_coach', 'beginner', array['Siłowe', 'Triceps'], 'Wyciskanie francuskie (skullcrusher) ze sztangą łamaną leżąc — izolacja tricepsa. Sztangę opuszczasz nad czoło, pracując tylko łokciami.', '1. Stosując wąski chwyt, podnieś sztangę łamaną i trzymaj ją z łokciami skierowanymi do wewnątrz, leżąc na ławce. Ramiona powinny być prostopadłe do podłogi. To będzie pozycja startowa.
2. Trzymając ramiona nieruchomo, opuszczaj sztangę, pozwalając łokciom się zgiąć. Wykonuj wdech w tej części ruchu. Zatrzymaj się, gdy sztanga znajdzie się dokładnie nad czołem.
3. Unieś sztangę z powrotem do pozycji startowej, prostując łokcie i wykonując wydech.
4. Powtarzaj.', NULL, 'free-exercise-db/EZ-Bar_Skullcrusher/0.jpg', 'free_exercise_db'),
  ('face-pull', 'Przyciąganie liny wyciągu do twarzy', 'Face Pull', 'motor_coach', 'intermediate', array['Siłowe', 'Barki'], 'Ciągnięcie liny wysokiego wyciągu w kierunku twarzy z rozchodzeniem dłoni. Wzmacnia tylne aktony i mięśnie międzyłopatkowe, poprawiając postawę.', '1. Stojąc twarzą do wysokiego wyciągu z przymocowaną liną lub dwoma uchwytami, ciągnij ciężar bezpośrednio w kierunku twarzy, rozsuwając przy tym dłonie. Trzymaj górne części ramion równolegle do podłoża.', NULL, 'free-exercise-db/Face_Pull/0.jpg', 'free_exercise_db'),
  ('farmers-walk', 'Marsz farmera', 'Farmer''s Walk', 'motor_coach', 'intermediate', array['Strongman', 'Przedramiona'], 'Marsz z ciężkim obciążeniem w obu dłoniach. Buduje siłę chwytu, mięśnie głębokie i całe ciało w bardzo praktyczny sposób.', '1. Do marszu farmera można wykorzystać różne przyrządy. Można go też wykonać z ciężkimi hantlami lub krótkimi sztangami, jeśli tych przyrządów nie ma. Zacznij od stania między nimi.
2. Po chwyceniu uchwytów unieś je, odpychając się piętami, z prostymi plecami i głową uniesioną.
3. Idź krótkimi, szybkimi krokami i nie zapominaj o oddychaniu. Pokonaj zadany dystans, zazwyczaj 15–30 metrów, jak najszybciej.', NULL, 'free-exercise-db/Farmers_Walk/0.jpg', 'free_exercise_db'),
  ('fast-skipping', 'Szybkie skipy', 'Fast Skipping', 'motor_coach', 'beginner', array['Plyometryka', 'Uda'], 'Szybkie skipy — dynamiczne podskoki z naprzemiennym odbiciem nóg. Rozwijają szybkość, rytm i sprężystość nóg.', '1. Zacznij w rozluźnionej pozycji z jedną nogą lekko wysuniętą w przód. To będzie pozycja startowa.
2. Skipuj, wykonując schemat krok-podskok: prawo-prawo-krok do lewo-lewo-krok i tak dalej, naprzemiennie w obie strony.
3. Wykonuj szybkie skipy, utrzymując bliski kontakt z podłożem i skracając fazę lotu, poruszając się jak najszybciej.', NULL, 'free-exercise-db/Fast_Skipping/0.jpg', 'free_exercise_db'),
  ('finger-curls', 'Uginanie palców ze sztangą', 'Finger Curls', 'motor_coach', 'beginner', array['Siłowe', 'Przedramiona'], 'Uginanie palców ze sztangą — specjalistyczne ćwiczenie na siłę chwytu i przedramiona.', '1. Trzymaj sztangę oburącz, dłońmi skierowanymi do góry; ręce rozstawione około na szerokość barków.
2. Ustaw stopy płasko na podłodze, w rozstawie nieco szerszym niż szerokość barków. To będzie pozycja startowa.
3. Opuszczaj sztangę jak najniżej, prostując palce. Pozwól sztandze stoczyć się w dłoniach i złap ją ostatnimi stawami palców.
4. Teraz uginaj sztangę jak najwyżej, zamykając dłonie na wydechu. Przytrzymaj napięcie na górze.', NULL, 'free-exercise-db/Finger_Curls/0.jpg', 'free_exercise_db'),
  ('flat-bench-cable-flyes', 'Rozpietki na wyciągach leżąc na ławce płaskiej', 'Flat Bench Cable Flyes', 'motor_coach', 'intermediate', array['Siłowe', 'Klatka piersiowa'], 'Rozpietki na wyciągach dolnych w leżeniu na ławce płaskiej. Linki zapewniają stałe napięcie mięśni w całym zakresie ruchu.', '1. Ustaw ławkę płaską między dwoma dolnymi wyciągami tak, aby leżąc na niej miałeś klatkę piersiową w linii rolek wyciągu.
2. Połóż się płasko na ławce i trzymaj stopy na ziemi.
3. Poproś kogoś, aby podał ci uchwyty do obu dłoni. Każdy uchwyt chwyta chwytem z dłońmi skierowanymi do góry (podchwytem).
4. Wyprowadź ramiona na boki z lekkim ugięciem w łokciach. Wskazówka: to ugięcie utrzymasz stałe przez cały ruch. Ramiona powinny być równoległe do podłogi. To jest pozycja startowa.
5. Teraz zacznij unosić ramiona ruchem półkolistym bezpośrednio przed sobą, ściągając linki, aż obie dłonie spotkają się na szczycie ruchu. Zaciśnij klatkę piersiową podczas tego ruchu i wykonuj wydech. Przytrzymaj też napięcie przez sekundę na górze. Wskazówka: przy poprawnym wykonaniu, w szczycie ruchu, ramiona powinny być prostopadłe do tułowia i podłogi, zetknięte nad klatką piersiową.
6. Powoli wróć do pozycji startowej.
7. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Flat_Bench_Cable_Flyes/0.jpg', 'free_exercise_db'),
  ('flat-bench-leg-pull-in', 'Przyciąganie kolan w leżeniu na ławce płaskiej', 'Flat Bench Leg Pull-In', 'motor_coach', 'beginner', array['Siłowe', 'Brzuch'], 'Przyciąganie kolan do klatki piersiowej w leżeniu na ławce. Ćwiczenie celuje w dolną część mięśni brzucha.', '1. Połóż się na macie gimnastycznej lub ławce płaskiej z nogami wystającymi za jej koniec.
2. Połóż dłonie pod pośladkami dłońmi w dół albo po bokach, trzymając się ławki (lub dłońmi w dół przy bokach na macie). Nogi wyciągnij prosto. To będzie pozycja startowa.
3. Ugnij kolana i przyciągaj uda w kierunku środka ciała na wydechu. Kontynuuj ten ruch, aż kolana znajdą się blisko klatki piersiowej. Przytrzymaj napiętą pozycję przez sekundę.
4. Na wdechu powoli wróć do pozycji startowej.
5. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Flat_Bench_Leg_Pull-In/0.jpg', 'free_exercise_db'),
  ('flat-bench-lying-leg-raise', 'Unoszenie nóg w leżeniu na ławce płaskiej', 'Flat Bench Lying Leg Raise', 'motor_coach', 'beginner', array['Siłowe', 'Brzuch'], 'Unoszenie wyprostowanych nóg do pionu w leżeniu na ławce. Mocno pracuje dolna partia mięśni brzucha.', '1. Połóż się plecami płasko na ławce z nogami wyciągniętymi przed siebie poza koniec ławki.
2. Połóż dłonie pod pośladkami dłońmi w dół albo po bokach, trzymając się ławki. To będzie pozycja startowa.
3. Trzymając nogi wyciągnięte, możliwie proste, z lekko ugiętymi, ale niezablokowanymi kolanami, unoś nogi, aż utworzą kąt 90 stopni z podłogą. Wykonuj wydech w tej części ruchu i przytrzymaj napięcie na górze przez sekundę.
4. Teraz na wdechu powoli opuść nogi do pozycji startowej.', NULL, 'free-exercise-db/Flat_Bench_Lying_Leg_Raise/0.jpg', 'free_exercise_db'),
  ('flexor-incline-dumbbell-curls', 'Uginanie ramion z hantlami na ławce skośnej z naciskiem na nadgarstki', 'Flexor Incline Dumbbell Curls', 'motor_coach', 'beginner', array['Siłowe', 'Biceps'], 'Wariant uginania ramion na ławce skośnej z hantlami trzymanymi bliżej górnej głowy i maksymalnie odchylonymi nadgarstkami w tył. Mocniej angażuje biceps oraz przedramiona.', '1. Trzymaj hantlę bliżej strony dalszej od siebie, tak aby większy ciężar znalazł się po stronie bliższej tobie. (To można zastosować z dobrym efektem we wszystkich ćwiczeniach na biceps z hantlą.) Teraz wykonaj normalne uginanie ramion z hantlami na ławce skośnej, ale trzymaj nadgarstki maksymalnie odchylone do tyłu, aby zniwelować działające na nie obciążenie.
2. Usiądź na ławce skośnej ustawionej pod kątem 45 stopni, trzymając hantlę w każdej dłoni.
3. Pozwól ramionom swobodnie zwisać po bokach ciała, z łokciami przy tułowiu, i obróć dłonie do przodu z kciukami skierowanymi na zewnątrz od ciała. Wskazówka: tę pozycję dłoni utrzymasz przez cały ruch, ponieważ nie powinno być żadnego obracania dłoni podczas unoszenia. To będzie pozycja startowa.
4. Uginaj obie hantle jednocześnie, aż bicepsy będą całkowicie napięte, wykonując wydech. Wskazówka: nie bujaj ramionami ani nie używaj rozpędu. Zachowuj kontrolowany ruch przez cały czas. Przytrzymaj napiętą pozycję przez sekundę na górze.
5. Na wdechu powoli wróć do pozycji startowej.
6. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Flexor_Incline_Dumbbell_Curls/0.jpg', 'free_exercise_db'),
  ('floor-glute-ham-raise', 'Glute-ham raise na podłodze', 'Floor Glute-Ham Raise', 'motor_coach', 'intermediate', array['Siłowe', 'Dwugłowe uda'], 'Prostowanie tułowia w klęku podpartym — ciężkie ćwiczenie na tylne uda i pośladki wykonywane przy zabezpieczeniu stóp. Na początku warto użyć rąk jako pomocy.', '1. Do tego ćwiczenia możesz wykorzystać partnera albo oprzeć stopy o coś stabilnego.
2. Zacznij na kolanach z udami i torsem wyprostowanymi pionowo. Jeśli korzystasz z partnera, pewnie będzie trzymał twoje stopy, utrzymując cię w pozycji. To będzie pozycja startowa.
3. Opuszczaj ciało prostując kolana, uważając, aby NIE zginać bioder podczas opuszczania się do przodu.
4. Połóż dłonie przed sobą, gdy dotrzesz do podłogi. Ten ruch jest bardzo trudny i być może nie uda ci się go wykonać bez pomocy. Użyj ramion, aby lekko odbić się od podłogi i wspomóc powrót do pozycji startowej.', NULL, 'free-exercise-db/Floor_Glute-Ham_Raise/0.jpg', 'free_exercise_db'),
  ('floor-press', 'Wyciskanie sztangi leżąc na podłodze', 'Floor Press', 'motor_coach', 'intermediate', array['Trójbój', 'Triceps'], 'Wyciskanie sztangi leżąc na podłodze w stojaku do przysiadów. Ograniczony zakres chroni barki, mocno pracują tricepsy i klatka piersiowa.', '1. Ustaw haki j-cup na odpowiedniej wysokości, aby założyć sztangę. Zacznij leżąc na podłodze z głową blisko końca stojaka. Trzymając ściągnięte łopatki, zdejmij sztangę z haków.
2. Opuszczaj sztangę w kierunku dolnej części klatki piersiowej lub górnej części brzucha, zaciskając palce na gryfie i próbując go „rozerwać” podczas opuszczania. Upewnij się, że łokcie są przyciągnięte do tułowia przez cały ruch. Opuszczaj sztangę, aż ramię dotknie podłoża, i zatrzymaj się, unikając jakiegokolwiek uderzenia czy odbicia ciężaru.
3. Wyciśnij sztangę w górę jak najszybciej, trzymając sztangę, nadgarstki i łokcie w linii.', NULL, 'free-exercise-db/Floor_Press/0.jpg', 'free_exercise_db'),
  ('floor-press-with-chains', 'Wyciskanie sztangi leżąc na podłodze z łańcuchami', 'Floor Press with Chains', 'motor_coach', 'intermediate', array['Trójbój', 'Triceps'], 'Wyciskanie na podłodze z dodatkowymi łańcuchami na gryfie. Rosnący opór w górnej fazie ruchu wzmacnia tricepsy i siłę eksplozywną.', '1. Ustaw haki j-cup na odpowiedniej wysokości, aby założyć sztangę. Do tego ćwiczenia zarzuć łańcuchy bezpośrednio na końcówki gryfu, starając się trzymać ich końce z dala od talerzy.
2. Zacznij leżąc na podłodze z głową blisko końca stojaka. Trzymając ściągnięte łopatki, zdejmij sztangę z haków.
3. Opuszczaj sztangę w kierunku dolnej części klatki piersiowej lub górnej części brzucha, zaciskając palce na gryfie i próbując go „rozerwać” podczas opuszczania. Upewnij się, że łokcie są przyciągnięte do tułowia przez cały ruch. Opuszczaj sztangę, aż ramię dotknie podłoża, i zatrzymaj się, unikając jakiegokolwiek uderzenia czy odbicia ciężaru.
4. Wyciśnij sztangę w górę jak najszybciej, trzymając sztangę, nadgarstki i łokcie w linii.', NULL, 'free-exercise-db/Floor_Press_with_Chains/0.jpg', 'free_exercise_db'),
  ('flutter-kicks', 'Nożyce w leżeniu na brzuchu na ławce', 'Flutter Kicks', 'motor_coach', 'beginner', array['Siłowe', 'Pośladki'], 'Naprzemienne unoszenie nóg w leżeniu przodem na ławce z biodrami na jej krawędzi. Wzmacnia dolne plecy, pośladki i tylne uda.', '1. Połóż się twarzą w dół na ławce płaskiej tak, aby biodra znajdowały się na jej krawędzi; nogi proste, z palcami wysoko nad podłogą, a ramiona położone na ławce, trzymające przednią krawędź.
2. Zaciśnij pośladki i mięśnie dwugłowe ud, a następnie wyprostuj nogi, aż będą równo z biodrami. To będzie pozycja startowa.
3. Rozpocznij ruch, unosząc lewą nogę wyżej niż prawą.
4. Potem opuść lewą nogę, unosząc prawą.
5. Kontynuuj naprzemiennie w ten sposób (jak przy nożycach w wodzie), aż wykonasz zalecaną liczbę powtórzeń dla każdej nogi. Pilnuj, aby ruch był cały czas kontrolowany. Wskazówka: podczas tego ruchu oddychaj normalnie.', NULL, 'free-exercise-db/Flutter_Kicks/0.jpg', 'free_exercise_db'),
  ('foot-smr', 'Rozmasowanie podeszwy stopy (SMR)', 'Foot-SMR', 'motor_coach', 'intermediate', array['Rozciąganie', 'Łydki'], 'Automasaż podeszwy stopy wałkiem lub rurką PVC. Rozluźnia powięź i zmniejsza napięcie stopy.', '1. To ćwiczenie rozciąga powięź mięśni stóp. Zacznij na siedząco bez butów. Używając rolki do stóp lub podobnego przedmiotu, np. krótkiego odcinka rurki PVC, oprzyj stopę o wałek w poprzek sklepienia stopy. To będzie pozycja startowa.
2. Dociśnij mocno i tocz wałek po sklepieniu stopy. Przytrzymaj 10–30 sekund, a następnie zmień stopę.', NULL, 'free-exercise-db/Foot-SMR/0.jpg', 'free_exercise_db'),
  ('forward-drag-with-press', 'Przeciąganie sanek do przodu z wypychaniem', 'Forward Drag with Press', 'motor_coach', 'intermediate', array['Strongman', 'Klatka piersiowa'], 'Przeciąganie sanek do przodu z naprzemiennym wypychaniem uchwytów w przód. Łączy pracę nóg z wyciskaniem i buduje ogólną kondycję.', '1. Przypnij linkę z dwoma uchwytami lub linkę do sanek. Powinieneś stać tyłem do sanek, trzymając uchwyt w każdej dłoni.
2. Rozpocznij ruch, robiąc krok w przód. Pochylając się do przodu, prostuj nogi i biodra, aby się poruszać; przy każdym kroku zatrzymaj się, aby wyprostować łokcie, wypychając ręce w przód. Idź w przód, aż wrócisz do punktu startu gotowy do wyciśnięcia.', NULL, 'free-exercise-db/Forward_Drag_with_Press/0.jpg', 'free_exercise_db'),
  ('frankenstein-squat', 'Frankenstein squat (przysiad z wyprostowanymi ramionami)', 'Frankenstein Squat', 'motor_coach', 'intermediate', array['Podnoszenie ciężarów', 'Uda'], 'Przysiad przedni z sztangą na barkach i wyprostowanymi ramionami przed sobą. Ćwiczenie techniczne uczące prawidłowej pozycji sztangi i ciała.', '1. To ćwiczenie uczy prawidłowego ustawienia zarówno sztangi, jak i ciała podczas podrzutu i przysiadu przedniego.
2. Połóż sztangę na przedzie barków, puść chwyt i wyciągnij ramiona przed sobą. Barki powinny być wypchnięte do przodu, tworząc półkę, a sztanga powinna stykać się z gardłem. Upewnij się, że poruszasz tylko łopatkami do przodu; nie zaokrąglij kręgosłupa piersiowego.
3. Wykonuj przysiad, zginając kolana i biodra, siadając między nogi. Trzymaj tułów pionowo, ramiona w górze, barki wypchnięte do przodu — sztanga powinna pozostać na miejscu. Zejdź do dna przysiadu, aż dwugłowe uda dotkną łydek.
4. Wróć do pozycji pionowej, odpychając się przednią częścią pięty i prostując kolana i biodra.', NULL, 'free-exercise-db/Frankenstein_Squat/0.jpg', 'free_exercise_db'),
  ('freehand-jump-squat', 'Skoki z przysiadu bez obciążenia', 'Freehand Jump Squat', 'motor_coach', 'intermediate', array['Siłowe', 'Uda'], 'Przysiad połączony z wyskokiem bez sprzętu. Buduje moc nóg i wytrzymałość siłową.', '1. Skrzyżuj ramiona na klatce piersiowej.
2. Z głową uniesioną i plecami prostymi ustaw stopy na szerokość barków.
3. Trzymając proste plecy i klatkę piersiową wypchniętą do przodu, schodź do przysiadu na wdechu, aż górne partie ud będą równoległe do podłogi lub niżej.
4. Teraz odbij się głównie śródstopiem i wyskocz prosto w górę jak najwyżej, używając ud jak sprężyn. Wykonuj wydech w tej części ruchu.
5. Gdy dotkniesz znów podłogi, natychmiast zejdź do przysiadu i wyskocz ponownie.
6. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Freehand_Jump_Squat/0.jpg', 'free_exercise_db'),
  ('frog-hops', 'Skoki żabki', 'Frog Hops', 'motor_coach', 'intermediate', array['Rozciąganie', 'Uda'], 'Skoki do przodu z przysiadu z dłońmi za głową. Intensywne ćwiczenie plyometryczne na nogi i pośladki.', '1. Stań z dłońmi za głową i zejdź do przysiadu, zachowując wyprostowany tułów i głowę uniesioną. To będzie pozycja startowa.
2. Skacz w przód kilka stóp, unikając zbędnie wysokiego wyskoku. Gdy stopy dotkną podłoża, amortyzuj uderzenie nogami i wyskocz ponownie. Powtórz ten ruch 5–10 razy.', NULL, 'free-exercise-db/Frog_Hops/0.jpg', 'free_exercise_db'),
  ('frog-sit-ups', 'Spięcia brzucha w pozycji żabki', 'Frog Sit-Ups', 'motor_coach', 'intermediate', array['Siłowe', 'Brzuch'], 'Brzuch w pozycji żabki: stopy złączone podeszwami, kolana rozłożone na boki. Krótkie spięcie górnej części tułowia izoluje mięsień prosty brzucha.', '1. Połóż się plecami płasko na podłodze (lub macie gimnastycznej) z nogami wyciągniętymi przed siebie.
2. Teraz ugnij kolana i połóż zewnętrzne strony ud przy podłodze (lub macie), łącząc podeszwy stóp.
3. Teraz spróbuj docisnąć obie podeszwy do siebie i przyciągnąć je jak najbliżej siebie, trzymając zewnętrzne strony ud przy podłodze (lub prawie przy niej). Wskazówka: w tej pozycji nogi powinny utworzyć kształt rombu.
4. Teraz skrzyżuj ramiona przed sobą, dotykając przeciwnych barków. To będzie pozycja startowa.
5. Na wydechu przyciśnij dolne plecy do podłogi, podwijając tułów w górę. Wskazówka: będzie to jak pierwsza 1/4 ruchu klasycznych spięć. Przytrzymaj sekundę na szczycie.
6. Na wdechu powoli opuść się do pozycji startowej.
7. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Frog_Sit-Ups/0.jpg', 'free_exercise_db'),
  ('front-barbell-squat', 'Przysiad przedni ze sztangą', 'Front Barbell Squat', 'motor_coach', 'advanced', array['Siłowe', 'Uda'], 'Przysiad przedni — sztanga spoczywa na barkach z przodu. Świetnie buduje nogi i wymaga wyprostowanej postawy oraz mobilności barków.', '1. To ćwiczenie najlepiej wykonywać w stojaku do przysiadów ze względów bezpieczeństwa. Najpierw ustaw sztangę na stojaku najlepiej dopasowanym do twojego wzrostu. Po dobraniu właściwej wysokości i załadowaniu sztangi wsuń ramiona pod sztangę, trzymając łokcie wysoko, a ramiona lekko powyżej równoległości do podłogi. Połóż sztangę na szczycie barków i skrzyżuj ramiona, obejmując gryf, aby mieć pełną kontrolę.
2. Zdejmij sztangę ze stojaka najpierw odpychając się nogami, jednocześnie prostując tułów.
3. Odsuń się od stojaka i ustaw nogi w średnim rozstawie na szerokość barków, z palcami lekko skierowanymi na zewnątrz. Cały czas trzymaj głowę uniesioną, bo patrzenie w dół zaburza równowagę, i zachowuj proste plecy. To będzie pozycja startowa. (Uwaga: w tym opisie stosujemy średni rozstaw opisany powyżej, który zapewnia wszechstronny rozwój; możesz jednak wybrać dowolny z trzech rozstawów opisanych w sekcji o ustawieniu stóp).
4. Zacznij powoli opuszczać sztangę, uginając kolana, zachowując prostą sylwetkę z głową uniesioną. Schodź, aż kąt między udami a łydkami stanie się nieco mniejszy niż 90 stopni (co oznacza, że uda są poniżej równoległości do podłogi). Wykonuj wdech w tej części ruchu. Wskazówka: jeśli wykonałeś ćwiczenie poprawnie, przód kolan powinien tworzyć umowną prostą z palcami stóp, prostopadłą do frontu. Jeśli kolana przekroczą tę umowną linię (jadą poza palce), to nadwyrężasz kolano, a ćwiczenie zostało wykonane błędnie.
5. Zacznij unosić sztangę na wydechu, odpychając się od podłogi głównie śródstopiem, gdy ponownie prostujesz nogi i wracasz do pozycji startowej.
6. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Front_Barbell_Squat/0.jpg', 'free_exercise_db'),
  ('front-barbell-squat-to-a-bench', 'Przysiad przedni ze sztangą do ławki', 'Front Barbell Squat To A Bench', 'motor_coach', 'advanced', array['Siłowe', 'Uda'], 'Przysiad przedni wykonywany do delikatnego dotknięcia ławką. Pomaga kontrolować głębokość i utrzymać pionowy tułów.', '1. To ćwiczenie najlepiej wykonywać w stojaku do przysiadów ze względów bezpieczeństwa. Najpierw ustaw ławkę płaską za sobą i sztangę na stojaku najlepiej dopasowanym do twojego wzrostu. Po dobraniu właściwej wysokości i załadowaniu sztangi wsuń ramiona pod sztangę, trzymając łokcie wysoko, a ramiona lekko powyżej równoległości do podłogi. Połóż sztangę na szczycie barków i skrzyżuj ramiona, obejmując gryf, aby mieć pełną kontrolę.
2. Zdejmij sztangę ze stojaka najpierw odpychając się nogami, jednocześnie prostując tułów.
3. Odsuń się od stojaka i ustaw nogi w średnim rozstawie na szerokość barków, z palcami lekko skierowanymi na zewnątrz. Cały czas trzymaj głowę uniesioną, bo patrzenie w dół zaburza równowagę, i zachowuj proste plecy. To będzie pozycja startowa. (Uwaga: w tym opisie stosujemy średni rozstaw opisany powyżej, który zapewnia wszechstronny rozwój; możesz jednak wybrać dowolny z trzech rozstawów opisanych w sekcji o ustawieniu stóp).
4. Zacznij powoli opuszczać sztangę, uginając kolana, zachowując prostą sylwetkę z głową uniesioną. Schodź, aż pośladkami dotkniesz ławki. Wykonuj wdech w tej części ruchu. Wskazówka: jeśli wykonałeś ćwiczenie poprawnie, przód kolan powinien tworzyć umowną prostą z palcami stóp, prostopadłą do frontu. Jeśli kolana przekroczą tę umowną linię (jadą poza palce), to nadwyrężasz kolano, a ćwiczenie zostało wykonane błędnie.
5. Zacznij unosić sztangę na wydechu, odpychając się od podłogi głównie piętą, gdy ponownie prostujesz nogi i wracasz do pozycji startowej.
6. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Front_Barbell_Squat_To_A_Bench/0.jpg', 'free_exercise_db'),
  ('front-box-jump', 'Skok na skrzynię od przodu', 'Front Box Jump', 'motor_coach', 'beginner', array['Plyometryka', 'Dwugłowe uda'], 'Klasyczny skok na skrzynię z pozycji stojącej twarzą do niej. Rozwija eksplozywność nóg i bioder.', '1. Zacznij ze skrzynią o odpowiedniej wysokości 30–60 cm przed sobą. Stań ze stopami rozstawionymi na szerokość barków. To będzie pozycja startowa.
2. Wykonaj krótki przysiad, przygotowując się do skoku, wymachując ramionami do tyłu.
3. Odbij się z tej pozycji, prostując biodra, kolana i kostki, aby wyskoczyć jak najwyżej. Wymachnij ramionami w przód i w górę.
4. Wyląduj na skrzyni z ugiętymi kolanami, amortyzując uderzenie nogami. Możesz wyskoczyć ze skrzyni z powrotem na ziemię albo, co lepsze, zejść pojedynczymi krokami.', NULL, 'free-exercise-db/Front_Box_Jump/0.jpg', 'free_exercise_db'),
  ('front-cable-raise', 'Unoszenie ramienia w przód na wyciągu dolnym', 'Front Cable Raise', 'motor_coach', 'beginner', array['Siłowe', 'Barki'], 'Unoszenie wyprostowanego ramienia w przód na wyciągu dolnym. Izoluje przedni akton barku z ciągłym napięciem linki.', '1. Ustaw ciężar na maszynie z dolnym wyciągiem i złap jednostronny uchwyt przymocowany do dolnego wyciągu lewą ręką.
2. Odwróć się tyłem do wyciągu i opuść ramię prosto w dół, z uchwytem przed udami, ramieniem swobodnie opuszczonym, dłońmi zwróconymi ku udem. To będzie pozycja startowa.
3. Trzymając tułów nieruchomo (bez bujania), unoś lewe ramię w przód z lekkim ugięciem w łokciu, dłonie zawsze skierowane w dół. Podnoś, aż ramię znajdzie się nieco powyżej równoległości do podłogi. Wykonuj wydech podczas tej części ruchu i zatrzymaj się na sekundę na górze.
4. Teraz na wdechu powoli opuść ramię do pozycji startowej.
5. Gdy wykonasz całą zalecaną liczbę powtórzeń dla tego ramienia, zmień rękę i wykonaj ćwiczenie prawą.', NULL, 'free-exercise-db/Front_Cable_Raise/0.jpg', 'free_exercise_db'),
  ('front-cone-hops-or-hurdle-hops', 'Podskoki nad pachołkami', 'Front Cone Hops (or hurdle hops)', 'motor_coach', 'beginner', array['Plyometryka', 'Uda'], 'Seria podskoków obunóż nad rzędem pachołków lub przeszkód. Rozwija sprężystość nóg i koordynację.', '1. Ustaw rząd pachołków lub innych małych przeszkód, rozmieszczonych w odstępach około metra.
2. Stań przed pierwszym pachołkiem ze stopami rozstawionymi na szerokość barków. To będzie pozycja startowa.
3. Zacznij od przeskoku obiema stopami nad pierwszym pachołkiem, wymachując oboma ramionami podczas skoku.
4. Amortyzuj uderzenie przy lądowaniu, uginając kolana, i natychmiast odbij się z pierwszego przeskoku, przeskakując nad kolejnym pachołkiem.
5. Kontynuuj, aż przeskoczysz wszystkie pachołki.', NULL, 'free-exercise-db/Front_Cone_Hops_or_hurdle_hops/0.jpg', 'free_exercise_db'),
  ('front-dumbbell-raise', 'Unoszenie hantli w przód naprzemiennie', 'Front Dumbbell Raise', 'motor_coach', 'beginner', array['Siłowe', 'Barki'], 'Naprzemienne unoszenie hantli przed sobą na wyprostowanych ramionach. Izoluje przednią część mięśnia naramiennego.', '1. Weź parę hantli i stań z wyprostowanym torsem, z hantlami przed udami, ramionami swobodnie opuszczonymi, dłońmi zwróconymi ku udom. To będzie pozycja startowa.
2. Trzymając tułów nieruchomo (bez bujania), unoś lewą hantlę w przód z lekkim ugięciem w łokciu, dłonie zawsze skierowane w dół. Podnoś, aż ramię znajdzie się nieco powyżej równoległości do podłogi. Wykonuj wydech podczas tej części ruchu i zatrzymaj się na sekundę na górze. Wykonaj wdech po pauzie.
3. Teraz opuszczaj hantlę powoli do pozycji startowej, jednocześnie unosząc prawą hantlę.
4. Kontynuuj naprzemiennie w ten sposób, aż wykonasz całą zalecaną liczbę powtórzeń dla każdego ramienia.', NULL, 'free-exercise-db/Front_Dumbbell_Raise/0.jpg', 'free_exercise_db'),
  ('front-incline-dumbbell-raise', 'Unoszenie hantli w przód na ławce skośnej', 'Front Incline Dumbbell Raise', 'motor_coach', 'beginner', array['Siłowe', 'Barki'], 'Unoszenie hantli przed sobą w leżeniu na ławce skośnej. Precyzyjna izolacja przednich aktonów.', '1. Usiądź na ławce skośnej ustawionej między 30 a 60 stopni, trzymając hantlę w każdej dłoni. Wskazówka: możesz zmieniać kąt, aby za każdym razem pracować na mięsień trochę inaczej.
2. Wyciągnij ramiona prosto przed siebie, dłońmi skierowanymi w dół, z hantlami uniesionymi około 2–3 cm nad udami. To będzie pozycja startowa.
3. Powoli unoś hantle prosto w górę, aż będą nieco powyżej barków, trzymając łokcie zablokowane. Zaciśnij mięśnie na sekundę na górze i pilnuj, aby wykonać wydech podczas tej części ruchu. Wskazówka: trzymaj głowę opartą o ławkę i nogi na podłodze przez cały czas.
4. Na wdechu opuść ramiona do pozycji startowej.
5. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Front_Incline_Dumbbell_Raise/0.jpg', 'free_exercise_db'),
  ('front-leg-raises', 'Wymachy nogą w przód', 'Front Leg Raises', 'motor_coach', 'beginner', array['Rozciąganie', 'Dwugłowe uda'], 'Dynamiczne wymachy wyprostowanej nogi w przód i w tył z podparciem. Mobilizują biodra i rozciągają zginacze bioder.', '1. Stań obok krzesła lub innego podparcia, trzymając się nim jedną ręką.
2. Machaj nogą do przodu, trzymając ją wyprostowaną. Kontynuuj wymachem w dół, prowadząc nogę jak najdalej do tyłu, na ile pozwala twoja gibkość. Powtórz 5–10 razy, a następnie zmień nogę.', NULL, 'free-exercise-db/Front_Leg_Raises/0.jpg', 'free_exercise_db'),
  ('front-plate-raise', 'Unoszenie talerza przed siebie', 'Front Plate Raise', 'motor_coach', 'intermediate', array['Siłowe', 'Barki'], 'Unoszenie talerza od obciążenia przed sobą na wyprostowanych ramionach do wysokości barków. Prosta izolacja przednich aktonów.', '1. Stojąc prosto, trzymaj talerz oburącz na godzinie 3 i 9. Dłonie powinny być zwrócone ku sobie, a ramiona wyprostowane i zablokowane z lekkim ugięciem w łokciach; talerz powinien znajdować się nisko, przy pasie, przed tobą, jak najdalej. Wskazówka: ramiona pozostaną w tej pozycji przez całe ćwiczenie. To będzie pozycja startowa.
2. Powoli unoś talerz na wydechu, aż będzie nieco powyżej poziomu barków. Przytrzymaj napięcie przez sekundę. Wskazówka: upewnij się, że nie bujasz ciężarem i nie zginasz łokci. Tułów również powinien pozostać nieruchomy przez cały ruch.
3. Na wdechu powoli opuść talerz do pozycji startowej.
4. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Front_Plate_Raise/0.jpg', 'free_exercise_db'),
  ('front-raise-and-pullover', 'Unoszenie sztangi przed siebie i przełożenie za głowę', 'Front Raise And Pullover', 'motor_coach', 'beginner', array['Siłowe', 'Klatka piersiowa'], 'Połączenie unoszenia sztangi w przód z przełożeniem jej za głowę w leżeniu. Angażuje barki, klatkę piersiową i najszersze mięśnie pleców.', '1. Połóż się na ławce płaskiej, trzymając sztangę chwytem nachwytem rozstawionym na około 40 cm.
2. Połóż sztangę na górnych udach, wyciągnij ramiona i zablokuj je, zachowując lekkie ugięcie w łokciach. To będzie pozycja startowa.
3. Teraz unoś ciężar ruchem półkolistym, trzymając ramiona proste, na wdechu. Kontynuuj ten sam ruch, aż sztanga znajdzie się po drugiej stronie, ponad twoją głową. (Wskazówka: sztanga przebyje około 180 stopni). W tym momencie ramiona powinny być równoległe do podłogi, a dłonie zwrócone ku sufitowi.
4. Teraz wróć sztangą do pozycji startowej, odwracając ruch na wydechu.
5. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Front_Raise_And_Pullover/0.jpg', 'free_exercise_db'),
  ('front-squat-clean-grip', 'Przysiad przedni (chwyt ciężarowy)', 'Front Squat (Clean Grip)', 'motor_coach', 'intermediate', array['Siłowe', 'Uda'], 'Przysiad przedni z chwytem ciężarowym — sztanga spoczywa na barkach, a dłonie tylko stabilizują gryf palcami. Fundament treningu siłowego i sportów siłowych.', '1. Najpierw ustaw sztangę na stojaku nieco poniżej wysokości barków. Połóż sztangę na szczycie barków, wciskając ją w obojczyki i lekko dotykając gardła. Dłonie powinny być w chwycie ciężarowym, dotykając sztangi tylko palcami, aby pomóc utrzymać ją w pozycji.
2. Zdejmij sztangę ze stojaka najpierw odpychając się nogami, jednocześnie prostując tułów. Odsuń się od stojaka i ustaw nogi w średnim rozstawie na szerokość barków, z palcami lekko skierowanymi na zewnątrz. Trzymaj głowę i łokcie wysoko przez cały czas. To będzie pozycja startowa.
3. Ugnij kolana, siadając między nogi. Schodź, aż dwugłowe uda położą się na łydkach. Trzymaj kolana w linii ze stopami, świadomie używając odwodzicieli, aby wypychać kolana na zewnątrz podczas przysiadu.
4. Zacznij unosić sztangę na wydechu, odpychając się od podłogi głównie piętą lub śródstopiem, gdy ponownie prostujesz nogi i wracasz do pozycji startowej.', NULL, 'free-exercise-db/Front_Squat_Clean_Grip/0.jpg', 'free_exercise_db'),
  ('front-squats-with-two-kettlebells', 'Przysiad przedni z dwoma kettlebell', 'Front Squats With Two Kettlebells', 'motor_coach', 'intermediate', array['Siłowe', 'Uda'], 'Przysiad przedni z dwoma kettlebell na barkach. Mocna praca nóg plus duże wymagania wobec mięśni głębokich i mobilności.', '1. Wykonaj podrzut dwóch kettlebell na barki. Wynieś je na barki, prostując nogi i biodra, ciągnąc kettlebell w ich kierunku. Obracaj nadgarstkami podczas tego ruchu.
2. Patrząc cały czas prosto przed siebie, zejdź do przysiadu jak najniżej i zatrzymaj się na dole. Podczas schodzenia wypychaj kolana na zewnątrz. Powinieneś siadać między nogi, zachowując wyprostowany tułów, z głową i klatką piersiową uniesionymi.
3. Wróć do góry, odpychając się piętami, i powtarzaj.', NULL, 'free-exercise-db/Front_Squats_With_Two_Kettlebells/0.jpg', 'free_exercise_db'),
  ('front-two-dumbbell-raise', 'Unoszenie hantli w przód jednocześnie', 'Front Two-Dumbbell Raise', 'motor_coach', 'beginner', array['Siłowe', 'Barki'], 'Jednoczesne unoszenie obu hantli przed sobą na wyprostowanych ramionach. Izoluje przednie aktony barków.', '1. Weź parę hantli i stań z wyprostowanym torsem, z hantlami przed udami, ramionami swobodnie opuszczonymi, dłońmi zwróconymi ku udom. To będzie pozycja startowa.
2. Trzymając tułów nieruchomo (bez bujania), unoś hantle w przód z lekkim ugięciem w łokciu, dłonie zawsze skierowane w dół. Podnoś, aż ramiona znajdą się nieco powyżej równoległości do podłogi. Wykonuj wydech podczas tej części ruchu i zatrzymaj się na sekundę na górze.
3. Na wdechu opuszczaj hantle powoli do pozycji startowej.
4. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Front_Two-Dumbbell_Raise/0.jpg', 'free_exercise_db'),
  ('full-range-of-motion-lat-pulldown', 'Ściąganie drążka w pełnym zakresie ruchu', 'Full Range-Of-Motion Lat Pulldown', 'motor_coach', 'intermediate', array['Siłowe', 'Najszersze grzbietu'], 'Wariant ściągania drążka w pełnym zakresie ruchu, z krzyżującymi się ramionami i rotacją dłoni. Maksymalnie angażuje najszersze mięśnie pleców.', '1. Stojąc lub siedząc na wysokiej ławce, złap dwa strzemiona linki przymocowane do wysokich wyciągów. Chwytaj przeciwną ręką, aby twoje ramiona były skrzyżowane przed tobą, a dłonie skierowane do przodu.
2. Trzymając klatkę piersiową uniesioną i lekki łuk w dolnych plecach, ciągnij uchwyty w dół, jak przy zwykłym ściąganiu. Zakres ruchu będzie bardziej łukowy. Podczas ruchu obróć dłonie tak, aby w dolnej pozycji dłonie były zwrócone ku sobie, a nie do przodu. Wróć powoli do pozycji startowej i powtarzaj.', NULL, 'free-exercise-db/Full_Range-Of-Motion_Lat_Pulldown/0.jpg', 'free_exercise_db'),
  ('gironda-sternum-chins', 'Podciąganie do mostka (styl Girondy)', 'Gironda Sternum Chins', 'motor_coach', 'intermediate', array['Siłowe', 'Najszersze grzbietu'], 'Podciąganie podchwytem z silnym odchyleniem do tyłu, doprowadzając mostek do drążka. Intensywny wariant na najszersze mięśnie pleców.', '1. Złap drążek do podciągania chwytem podchwytem na szerokość barków.
2. Teraz zawieś się z ramionami całkowicie wyprostowanymi, wypchnij klatkę piersiową do przodu i odchyl się do tyłu. Wskazówka: będziesz pochylony do tyłu przez cały ruch. To będzie pozycja startowa.
3. Zacznij przyciągać się w kierunku drążka z wygiętym kręgosłupem przez cały ruch i głową odchyloną jak najdalej od drążka. Wykonuj wydech podczas tej części ruchu. Wskazówka: w górnej fazie ruchu twoje biodra i nogi będą pod kątem około 45 stopni do podłogi.
4. Ciągnij dalej, aż obojczyk minie drążek, a dolna część klatki piersiowej lub mostek go dotknie. Przytrzymaj napięcie przez sekundę. Wskazówka: w momencie zakończenia tej fazy ruchu twoja głowa będzie równoległa do podłogi.
5. Powoli zacznij wracać do pozycji startowej na wdechu.
6. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Gironda_Sternum_Chins/0.jpg', 'free_exercise_db'),
  ('glute-ham-raise', 'Glute-ham raise na maszynie', 'Glute Ham Raise', 'motor_coach', 'intermediate', array['Trójbój', 'Dwugłowe uda'], 'Glute-ham raise na specjalnej maszynie — ciężkie prostowanie tułowia budujące tylne uda i pośladki. Klasyczne ćwiczenie siłowe.', '1. Zacznij od regulacji maszyny do swojego ciała. Połóż się twarzą w dół ze stopami opartymi o podnóżek, między wałkami. Kolana powinny znajdować się tuż za podparciem.
2. Zacznij od dna ruchu. Trzymaj plecy wygięte, rozpoczynając ruch zginaniem kolan. Wciskaj palce stóp w podnóżek podczas tego ruchu. Trzymaj górną część ciała prosto i kontynuuj, aż ciało znajdzie się w pozycji pionowej.
3. Wróć do pozycji startowej, kontrolując opuszczanie.', NULL, 'free-exercise-db/Glute_Ham_Raise/0.jpg', 'free_exercise_db')
on conflict (slug) do nothing;

insert into public.exercises
  (slug, name, name_en, persona_type, level, categories, short_description, detail_full, common_mistakes, photo_path, source)
values
  ('glute-kickback', 'Wyprost nogi w tył w klęku podpartym', 'Glute Kickback', 'motor_coach', 'beginner', array['Siłowe', 'Pośladki'], 'Klasyczne ćwiczenie na pośladki — unoszenie nogi w tył w klęku podpartym. Proste i skuteczne, idealne na początek treningu.', '1. Uklęknij na podłodze lub macie gimnastycznej i zegnij się w pasie, z ramionami wyprostowanymi przed sobą (prostopadle do tułowia), aby przyjąć pozycję klęku podpartego jak do pompek, ale z ramionami rozstawionymi na szerokość barków. Głowa powinna patrzeć w przód, a zgięcie kolan ma utworzyć kąt 90 stopni między dwugłowymi udami a łydkami. To będzie pozycja startowa.
2. Na wydechu unieś prawą nogę, aż dwugłowe uda będą w linii z plecami, zachowując kąt 90 stopni w kolanie. Napinaj pośladki przez cały ten ruch i przytrzymaj napięcie przez sekundę na górze. Wskazówka: na końcu ruchu udo powinno być równoległe do podłogi, a łydka prostopadła do niej.
3. Wróć do pozycji początkowej na wdechu i teraz powtórz z lewą nogą.
4. Kontynuuj naprzemiennie, aż zostanie wykonana cała zalecana liczba powtórzeń.', NULL, 'free-exercise-db/Glute_Kickback/0.jpg', 'free_exercise_db'),
  ('goblet-squat', 'Przysiad goblet z kettlebell', 'Goblet Squat', 'motor_coach', 'beginner', array['Siłowe', 'Uda'], 'Przysiad z kettlebell trzymanym przy klatce piersiowej jak kielich. Uczy głębokiego przysiadu i pomaga utrzymać wyprostowany tułów.', '1. Stań, trzymając lekki kettlebell za uchwyt („rogami”) blisko klatki piersiowej. To będzie pozycja startowa.
2. Zejdź do przysiadu między nogi, aż dwugłowe uda położą się na łydkach. Trzymaj klatkę piersiową i głowę uniesione, a plecy proste.
3. W dolnej pozycji zatrzymaj się i użyj łokci, aby wypchnąć kolana na zewnątrz. Wróć do pozycji startowej i powtarzaj 10–20 powtórzeń.', NULL, 'free-exercise-db/Goblet_Squat/0.jpg', 'free_exercise_db'),
  ('good-morning', 'Good morning (skłon ze sztangą)', 'Good Morning', 'motor_coach', 'intermediate', array['Trójbój', 'Dwugłowe uda'], 'Skłon tułowia w przód ze sztangą na plecach, na prostych nogach. Świetnie buduje tylne uda, pośladki i wzmacnia dolne plecy.', '1. Zacznij ze sztangą na stojaku na wysokości barków. Załóż sztangę na tył barków, jak przy power squat, nie na same barki. Trzymaj plecy napięte, łopatki ściągnięte, a kolana lekko ugięte. Odsuń się od stojaka.
2. Zacznij od zgięcia w biodrach, cofając je do tyłu podczas pochylania się do niemal równoległości do podłogi. Trzymaj plecy wygięte, a kręgosłup szyjny w prawidłowym ustawieniu.
3. Odwróć ruch, prostując biodra pracą pośladków i dwugłowych ud. Kontynuuj, aż wrócisz do pozycji startowej.', NULL, 'free-exercise-db/Good_Morning/0.jpg', 'free_exercise_db'),
  ('good-morning-off-pins', 'Good morning ze sztangą z bloków (pins)', 'Good Morning off Pins', 'motor_coach', 'intermediate', array['Trójbój', 'Dwugłowe uda'], 'Wariant good morning, w którym ruch zaczyna się od sztangi spoczywającej na blokach stojaka. Pozwala bezpiecznie budować siłę dolnych pleców, pośladków i tylnych ud.', '1. Zacznij ze sztangą na stojaku na wysokości mniej więcej twojego brzucha. Pochyl się pod sztangę i załóż ją na tył barków, jak przy power squat, nie na same barki. Przy właściwej wysokości powinieneś być blisko równoległości do podłogi podczas skłonu. Trzymaj plecy napięte, łopatki ściągnięte, a kolana lekko ugięte. Zachowaj plecy wygięte i kręgosłup szyjny w prawidłowym ustawieniu.
2. Rozpocznij ruch prostując biodra pracą pośladków i dwugłowych ud — wstajesz prosto z ciężarem. Powoli opuszczaj ciężar z powrotem na bloki, wracając do pozycji startowej.', NULL, 'free-exercise-db/Good_Morning_off_Pins/0.jpg', 'free_exercise_db'),
  ('gorilla-chin-crunch', 'Podciąganie z unoszeniem kolan (gorilla crunch)', 'Gorilla Chin/Crunch', 'motor_coach', 'intermediate', array['Siłowe', 'Brzuch'], 'Połączenie podciągania podchwytem z unoszeniem kolan do klatki piersiowej. Jednocześnie pracują plecy i mięśnie brzucha.', '1. Zawieś się na drążku chwytem podchwytem (dłonie skierowane ku tobie) nieco szerzej niż szerokość barków.
2. Teraz ugnij kolana pod kątem 90 stopni tak, aby łydki były równoległe do podłogi, a uda pozostały do niej prostopadłe. To będzie pozycja startowa.
3. Na wydechu przyciągaj się w górę, jednocześnie podciągając kolana ku górze, aż kolana znajdą się na wysokości klatki piersiowej. Zatrzymasz się, gdy tylko twój nos będzie na poziomie drążka. Wskazówka: gdy dotrzesz do tego punktu, powinien być też właśnie kończony spięcie brzucha.
4. Zacznij powoli wykonywać wdech, wracając do pozycji startowej.
5. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Gorilla_Chin_Crunch/0.jpg', 'free_exercise_db'),
  ('groin-and-back-stretch', 'Rozciąganie pachwin i pleców', 'Groin and Back Stretch', 'motor_coach', 'intermediate', array['Rozciąganie', 'Przywodziciele'], 'Rozciąganie pachwin i pleców w siadzie z połączonymi stopami. Skłon z prowadzeniem łokci do wewnętrznej strony ud.', '1. Usiądź na podłodze z ugiętymi kolanami i stopami złączonymi.
2. Spleć palce dłoni z tyłu głowy. To będzie pozycja startowa.
3. Pochyl się w dół, prowadząc łokcie w kierunku wewnętrznej strony ud. Po krótkiej pauzie wróć do pozycji startowej z głową uniesioną i prostymi plecami. Powtarzaj 10–20 powtórzeń.', NULL, 'free-exercise-db/Groin_and_Back_Stretch/0.jpg', 'free_exercise_db'),
  ('groiners', 'Przeskoki żabki z rozkrokiem', 'Groiners', 'motor_coach', 'intermediate', array['Rozciąganie', 'Przywodziciele'], 'Skoki obunóż do rąk z pozycji pompki i z powrotem. Dynamiczne ćwiczenie mobilizujące biodra i rozgrzewające całe ciało.', '1. Zacznij w pozycji pompki na podłodze. To będzie pozycja startowa.
2. Obiema nogami wyskocz do przodu, lądując stopami obok dłoni. Trzymaj głowę uniesioną podczas tego ruchu.
3. Wróć do pozycji startowej i natychmiast powtórz ruch, kontynuując przez 10–20 powtórzeń.', NULL, 'free-exercise-db/Groiners/0.jpg', 'free_exercise_db'),
  ('hack-squat', 'Przysiad hakowy na maszynie', 'Hack Squat', 'motor_coach', 'beginner', array['Siłowe', 'Uda'], 'Przysiad na specjalnej maszynie hack squat z plecami opartymi o podparcie. Buduje nogi, odciążając dolne plecy.', '1. Oprzyj tył tułowia o oparcie maszyny i zahacz barkami o dostępne poduszki naramienne.
2. Ustaw nogi na platformie w średnim rozstawie na szerokość barków, z palcami lekko skierowanymi na zewnątrz. Wskazówka: cały czas trzymaj głowę uniesioną i utrzymuj plecy na oparciu.
3. Połóż ręce na bocznych uchwytach maszyny i zwolnij blokady bezpieczeństwa (w większości konstrukcji wykonuje się to przez obrócenie bocznych uchwytów z pozycji przedniej na skośną).
4. Teraz wyprostuj nogi, nie blokując kolan. To będzie pozycja startowa. (Uwaga: w tym opisie stosujemy średni rozstaw opisany powyżej, który zapewnia wszechstronny rozwój; możesz jednak wybrać dowolny z trzech rozstawów opisanych w sekcji o ustawieniu stóp).
5. Zacznij powoli opuszczać sanię, uginając kolana, zachowując prostą sylwetkę z głową uniesioną (plecy cały czas na oparciu). Schodź, aż kąt między udami a łydkami stanie się nieco mniejszy niż 90 stopni (co oznacza, że uda są poniżej równoległości do podłogi). Wykonuj wdech w tej części ruchu. Wskazówka: jeśli wykonałeś ćwiczenie poprawnie, przód kolan powinien tworzyć umowną prostą z palcami stóp, prostopadłą do frontu. Jeśli kolana przekroczą tę umowną linię (jadą poza palce), to nadwyrężasz kolano, a ćwiczenie zostało wykonane błędnie.
6. Zacznij unosić sanię na wydechu, odpychając się od podłogi głównie piętą, gdy ponownie prostujesz nogi i wracasz do pozycji startowej.
7. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Hack_Squat/0.jpg', 'free_exercise_db'),
  ('hammer-curls', 'Uginanie ramion chwytem młotkowym', 'Hammer Curls', 'motor_coach', 'beginner', array['Siłowe', 'Biceps'], 'Uginanie ramion z hantlami trzymanymi neutralnie, jak młoty. Mocno angażuje biceps oraz mięsień ramienno-promieniowy przedramienia.', '1. Stań z wyprostowanym torsem, z hantlą w każdej dłoni trzymaną swobodnie opuszczoną. Łokcie powinny być blisko tułowia.
2. Dłonie powinny być zwrócone ku tułowiu. To będzie pozycja startowa.
3. Teraz, trzymając ramiona nieruchomo, na wydechu uginaj ciężar w przód, napinając bicepsy. Podnoś ciężar, aż biceps będzie całkowicie napięty, a hantla znajdzie się na wysokości barku. Przytrzymaj napiętą pozycję przez chwilę, zaciskając bicepsy. Wskazówka: skup się na utrzymaniu łokcia nieruchomo — porusza się tylko przedramię.
4. Po krótkiej pauzie, na wdechu, powoli zacznij opuszczać hantle do pozycji startowej.
5. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Hammer_Curls/0.jpg', 'free_exercise_db'),
  ('hammer-grip-incline-db-bench-press', 'Wyciskanie hantli na ławce skośnej chwytem neutralnym', 'Hammer Grip Incline DB Bench Press', 'motor_coach', 'beginner', array['Siłowe', 'Klatka piersiowa'], 'Wyciskanie hantli na ławce skośnej z dłońmi zwróconymi ku sobie. Górna część klatki piersiowej pracuje mocniej, a barki są odciążone.', '1. Połóż się na ławce skośnej z hantlą w każdej dłoni spoczywającą na udach. Dłonie powinny być zwrócone ku sobie.
2. Pomagając sobie udami, podrzuć hantle pojedynczo tak, aby móc trzymać je na szerokość barków.
3. Gdy hantle są na szerokości barków, utrzymuj chwyt neutralny (dłonie zwrócone ku sobie). Rozsuń łokcie na boki z ramionami w linii barków (prostopadle do tułowia), a łokcie ugięte tworząc kąt 90 stopni między ramieniem a przedramieniem. To będzie pozycja startowa.
4. Teraz opuszczaj ciężary powoli na boki na wdechu. Zachowuj pełną kontrolę nad hantlami przez cały czas.
5. Na wydechu wypychaj hantle w górę pracą mięśni piersiowych. Zablokuj ramiona w napiętej pozycji, przytrzymaj sekundę i zacznij schodzić powoli. Wskazówka: opuszczanie powinno trwać co najmniej dwa razy dłużej niż wypchnięcie.
6. Powtarzaj ruch przez zaleconą w programie liczbę powtórzeń.
7. Gdy skończysz, połóż hantle najpierw na udach, a potem na podłodze. To najbezpieczniejszy sposób odłożenia hantli.', NULL, 'free-exercise-db/Hammer_Grip_Incline_DB_Bench_Press/0.jpg', 'free_exercise_db'),
  ('hamstring-smr', 'Automasaż tylnych ud wałkiem (SMR)', 'Hamstring-SMR', 'motor_coach', 'beginner', array['Rozciąganie', 'Dwugłowe uda'], 'Rolowanie tylnych ud wałkiem piankowym. Rozluźnia napięte mięśnie i poprawia zakres ruchu w biodrze.', '1. W pozycji siedzącej wyciągnij nogi nad wałek tak, aby znajdował się na tylnej części ud. Połóż dłonie po bokach lub za sobą, aby wspomóc podparcie ciała. To będzie pozycja startowa.
2. Używając rąk, unieś biodra nad podłogę i przenieś ciężar ciała na wałek na jednej nodze. Rozluźnij mięśnie dwugłowe ud rolowanej nogi.
3. Tocz się po wałku od poniżej biodra do ponad tyłem kolana, zatrzymując się na 10–30 sekund w punktach napięcia. Powtórz dla drugiej nogi.', NULL, 'free-exercise-db/Hamstring-SMR/0.jpg', 'free_exercise_db'),
  ('hamstring-stretch', 'Rozciąganie tylnych ud z paskiem', 'Hamstring Stretch', 'motor_coach', 'beginner', array['Rozciąganie', 'Dwugłowe uda'], 'Rozciąganie tylnych ud w leżeniu na plecach, z paskiem lub gumą założoną na stopę. Bezpieczne i skuteczne rozciągnięcie dwugłowych ud.', '1. Połóż się na plecach z jedną nogą wyciągniętą nad sobą, z biodrem pod kątem 90 stopni. Druga noga płasko leży na podłodze.
2. Załóż pasek, gumę lub linę na śródstopie uniesionej stopy. To będzie pozycja startowa.
3. Pociągnij za pasek, aby wywołać napięcie w łydkach i dwugłowym udzie. Utrzymaj to rozciągnięcie przez 10–30 sekund, a następnie powtórz z drugą nogą.', NULL, 'free-exercise-db/Hamstring_Stretch/0.jpg', 'free_exercise_db'),
  ('handstand-push-ups', 'Pompki w staniu na rękach', 'Handstand Push-Ups', 'motor_coach', 'advanced', array['Siłowe', 'Barki'], 'Zaawansowane pompki w staniu na rękach przy ścianie. Buduje ogromną siłę barków i tricepsów; wymaga dobrego opanowania stania na rękach.', '1. Tyłem do ściany zegnij się w pasie i połóż obie dłonie na podłodze na szerokość barków.
2. Wybij się nogami do ściany z prostymi ramionami. Twoje ciało powinno być do góry nogami, z ramionami i nogami całkowicie wyprostowanymi. Trzymaj całe ciało jak najprościej. Wskazówka: jeśli robisz to po raz pierwszy, poproś kogoś o asekurację. Pilnuj też, aby patrzeć w ścianę głową, a nie w dół.
3. Powoli opuszczaj się na wdechu, aż głowa niemal dotknie podłogi. Wskazówka: niezwykle ważne jest, aby schodzić powoli, aby uniknąć urazu głowy.
4. Na wydechu powoli wypychaj się w górę, aż łokcie będą prawie zablokowane.
5. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Handstand_Push-Ups/0.jpg', 'free_exercise_db'),
  ('hang-clean', 'Podrzut z wisu (hang clean)', 'Hang Clean', 'motor_coach', 'intermediate', array['Podnoszenie ciężarów', 'Uda'], 'Ciężarowy podrzut sztangi z poziomu ud. Eksplozywny ruch rozwijający moc całego ciała.', '1. Zacznij w rozstawie na szerokość barków, chwytem nachwytem lub haczykowym, ze sztangą zawieszoną na wysokości środka uda. Plecy powinny być proste i lekko pochylone do przodu.
2. Zacznij od agresywnego wyprostu bioder, kolan i kostek, wypychając ciężar ku górze. Podczas tego ruchu unoś barki w kierunku uszu.
3. Natychmiast odbierz sztangę, odpychając się piętami, trzymając tułów pionowo i łokcie wysoko. Kontynuuj, aż staniesz w pozycji wyprostowanej.', NULL, 'free-exercise-db/Hang_Clean/0.jpg', 'free_exercise_db'),
  ('hang-clean-below-the-knees', 'Podrzut z wisu poniżej kolan', 'Hang Clean - Below the Knees', 'motor_coach', 'intermediate', array['Podnoszenie ciężarów', 'Uda'], 'Podrzut z wisu rozpoczynany poniżej kolan — dłuższy zakres niż klasyczny hang clean. Mocniej obciąża plecy i biodra, budując potężną eksplozję.', '1. Zacznij w rozstawie na szerokość barków, chwytem nachwytem lub haczykowym, ze sztangą zawieszoną tuż poniżej kolan. Plecy powinny być proste i lekko pochylone do przodu.
2. Zacznij od agresywnego wyprostu bioder, kolan i kostek, wypychając ciężar ku górze. Podczas tego ruchu unoś barki w kierunku uszu. Po osiągnięciu pełnego wyprostu przejdź do trzeciego ciągu, agresywnie unosząc barki i zginając ramiona z łokciami skierowanymi wysoko na zewnątrz.
3. Na szczycie wyprostu agresywnie przyciągnij się w dół, obracając łokcie pod sztangę. Odbierz sztangę w pozycji przysiadu przedniego, którego głębokość zależy od wysokości sztangi po trzecim ciągu. Sztangę należy położyć na wypchniętych barkach, lekko dotykając gardła, z rozluźnionymi dłońmi. Kontynuuj schodzenie do dna przysiadu, co pomoże w odbiorze.
4. Natychmiast odbierz sztangę, odpychając się piętami, trzymając tułów pionowo i łokcie wysoko. Kontynuuj, aż staniesz w pozycji wyprostowanej.', NULL, 'free-exercise-db/Hang_Clean_-_Below_the_Knees/0.jpg', 'free_exercise_db'),
  ('hang-snatch', 'Wytracenie z wisu (hang snatch)', 'Hang Snatch', 'motor_coach', 'advanced', array['Podnoszenie ciężarów', 'Dwugłowe uda'], 'Ciężarowe wytracenie sztangi nad głowę z poziomu bioder. Bardzo techniczne, eksplozywnie buduje całe ciało.', '1. Zacznij z szerokim chwytem na gryfie, chwytem nachwytem lub haczykowym. Stopy powinny znajdować się bezpośrednio pod biodrami, skierowane lekko na zewnątrz. Kolana powinny być lekko ugięte, a tułów pochylony do przodu. Kręgosłup powinien być całkowicie wyprostowany, a głowa skierowana w przód. Sztanga powinna być przy biodrach. To będzie pozycja startowa.
2. Agresywnie wyprostuj nogi i biodra. Na szczycie wyprostu unoś barki i pozwól łokciom zgiąć się na boki.
3. Przenosząc stopy do pozycji odbioru, gwałtownie przyciągnij się pod sztangę, wynosząc ją nad głowę. Odbierz sztangę z ciałem możliwie nisko i ramionami całkowicie wyprostowanymi nad głową.
4. Wróć do pozycji stojącej z ciężarem nad głową. Następnie kontrolowanie opuść ciężar na ziemię.', NULL, 'free-exercise-db/Hang_Snatch/0.jpg', 'free_exercise_db'),
  ('hang-snatch-below-knees', 'Wytracenie z wisu poniżej kolan', 'Hang Snatch - Below Knees', 'motor_coach', 'advanced', array['Podnoszenie ciężarów', 'Dwugłowe uda'], 'Wariant hang snatch z pozycji poniżej kolan. Dłuższy zakres ruchu zwiększa wymagania wobec pleców i bioder.', '1. Zacznij z szerokim chwytem na gryfie, chwytem nachwytem lub haczykowym. Stopy powinny znajdować się bezpośrednio pod biodrami, skierowane lekko na zewnątrz. Kolana powinny być lekko ugięte, a tułów pochylony do przodu. Kręgosłup powinien być całkowicie wyprostowany, a głowa skierowana w przód. Sztanga powinna znajdować się tuż poniżej kolan. To będzie pozycja startowa.
2. Agresywnie wyprostuj nogi i biodra. Na szczycie wyprostu unoś barki i pozwól łokciom zgiąć się na boki.
3. Przenosząc stopy do pozycji odbioru, gwałtownie przyciągnij się pod sztangę, wynosząc ją nad głowę. Odbierz sztangę z ciałem możliwie nisko i ramionami całkowicie wyprostowanymi nad głową.
4. Wróć do pozycji stojącej z ciężarem nad głową, a następnie kontrolowanie opuść ciężar na podłogę.', NULL, 'free-exercise-db/Hang_Snatch_-_Below_Knees/0.jpg', 'free_exercise_db'),
  ('hanging-bar-good-morning', 'Good morning na sztandze zawieszonej na linkach', 'Hanging Bar Good Morning', 'motor_coach', 'intermediate', array['Trójbój', 'Dwugłowe uda'], 'Wariant good morning ze sztangą zawieszoną na linkach lub łańcuchach, co wprowadza niestabilność. Zaawansowane wzmacnianie dolnych pleców i pośladków.', '1. Zacznij ze sztangą na stojaku na wysokości mniej więcej twojego brzucha. Zawieś sztangę używając łańcuchów lub linek treningowych.
2. Pochyl się pod sztangę i załóż ją na tył barków, jak przy power squat, nie na same trapeziusy. Przy właściwej wysokości powinieneś być blisko równoległości do podłogi podczas skłonu. Trzymaj plecy napięte, łopatki ściągnięte, a kolana lekko ugięte. Zachowaj plecy wygięte i kręgosłup szyjny w prawidłowym ustawieniu.
3. Rozpocznij ruch prostując biodra pracą pośladków i dwugłowych ud — wstajesz prosto z ciężarem.
4. Powoli opuszczaj ciężar do pozycji startowej, gdzie jest podtrzymywany przez łańcuchy.', NULL, 'free-exercise-db/Hanging_Bar_Good_Morning/0.jpg', 'free_exercise_db'),
  ('hanging-leg-raise', 'Unoszenie nóg w zwisie', 'Hanging Leg Raise', 'motor_coach', 'advanced', array['Siłowe', 'Brzuch'], 'Unoszenie wyprostowanych nóg w zwisie na drążku. Jedno z najlepszych ćwiczeń na dolną część mięśni brzucha.', '1. Zawieś się na drążku z oboma ramionami wyprostowanymi nad sobą, stosując szeroki lub średni chwyt. Nogi powinny być opuszczone prosto, z miednicą lekko podwiniętą do tyłu. To będzie pozycja startowa.
2. Unoś nogi, aż tułów utworzy kąt 90 stopni z nogami. Wykonuj wydech podczas tego ruchu i przytrzymaj napięcie przez około sekundę.
3. Powoli wracaj do pozycji startowej na wdechu.
4. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Hanging_Leg_Raise/0.jpg', 'free_exercise_db'),
  ('hanging-pike', 'Unoszenie nóg w zwisie (pike) z prostymi nogami', 'Hanging Pike', 'motor_coach', 'advanced', array['Siłowe', 'Brzuch'], 'Unoszenie wyprostowanych nóg aż do drążka w zwisie. Bardzo zaawansowana wersja pracy na brzuch, angażująca też zginacze bioder.', '1. Zawieś się na drążku chwytem nachwytem (dłonie odwrócone od ciebie) nieco szerzej niż szerokość barków, z nogami złączonymi. Wskazówka: możesz użyć pasków na nadgarstki, aby ułatwić utrzymanie się drążka.
2. Teraz ugnij kolana pod kątem 90 stopni i wyprowadź uda do przodu tak, aby łydki były prostopadłe do podłogi, a uda pozostały do niej równoległe. To będzie pozycja startowa.
3. Unoś nogi na wydechu, aż prawie dotkniesz piszczelami drążka nad sobą. Wskazówka: spróbuj wyprostować nogi maksymalnie na szczycie.
4. Opuszczaj nogi jak najwolniej, aż osiągniesz pozycję startową. Wskazówka: unikaj bujania i używania rozpędu przez cały czas.
5. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Hanging_Pike/0.jpg', 'free_exercise_db'),
  ('heaving-snatch-balance', 'Heaving snatch balance (podrzut równoważny)', 'Heaving Snatch Balance', 'motor_coach', 'intermediate', array['Podnoszenie ciężarów', 'Uda'], 'Ćwiczenie techniczne podnoszenia ciężarów — szybkie zejście do przysiadu z wypchnięciem sztangi nad głowę. Uczy pewnego odbioru sztangi przy nauce snatcha.', '1. To ćwiczenie pomaga nauczyć się wytracenia. Zacznij, trzymając lekki ciężar na tylnych częściach barków. Stopy powinny być nieco szerzej niż szerokość bioder, skierowane na zewnątrz — ta sama pozycja, którą przyjmujesz do przysiadu.
2. Zacznij od lekkiego ugięcia kolan (dip) i dynamicznego powrotu w górę, aby na moment odciążyć sztangę. Wypchnij się pod sztangę, wynosząc ją nad głowę podczas schodzenia do pełnego przysiadu.
3. Wróć do pozycji stojącej.', NULL, 'free-exercise-db/Heaving_Snatch_Balance/0.jpg', 'free_exercise_db'),
  ('heavy-bag-thrust', 'Pchnięcie worka treningowego', 'Heavy Bag Thrust', 'motor_coach', 'beginner', array['Plyometryka', 'Klatka piersiowa'], 'Mocne pchnięcie oburącz worka bokserskiego, angażujące korpus i barki. Ćwiczenie kondycyjne inspirowane sportami walki.', '1. Wykorzystaj worek treningowy do tego ćwiczenia. Przyjmij pozycję wyprostowaną obok worka, ze stopami rozstawionymi dość szeroko, jedna przed drugą. Połóż dłonie na worku na wysokości klatki piersiowej. To będzie pozycja startowa.
2. Zacznij od skręcenia w pasie, wypychając worek do przodu jak najmocniej. Wykonuj ten ruch szybko, odpychając worek od ciała.
3. Przyjmij worek, gdy wraca w tył, odwracając te kroki.', NULL, 'free-exercise-db/Heavy_Bag_Thrust/0.jpg', 'free_exercise_db'),
  ('high-cable-curls', 'Uginanie ramion na wysokich wyciągach', 'High Cable Curls', 'motor_coach', 'intermediate', array['Siłowe', 'Biceps'], 'Uginanie ramion na dwóch górnych wyciągach, z ramionami równoległymi do podłogi. Unikalne napięcie bicepsa w skróceniu.', '1. Stań między dwoma górnymi wyciągami i złap uchwyt każdą ręką. Ustaw górne części ramion równolegle do podłogi, dłońmi skierowanymi ku sobie. To będzie pozycja startowa.
2. Uginaj uchwyty w swoim kierunku, aż znajdą się obok uszu. Upewnij się, że podczas tego ruchu napinasz bicepsy i wykonujesz wydech. Ramiona powinny pozostać nieruchome — poruszać się powinny tylko przedramiona. Przytrzymaj sekundę w napiętej pozycji, zaciskając bicepsy.
3. Powoli wróć ramionami do pozycji startowej.
4. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/High_Cable_Curls/0.jpg', 'free_exercise_db'),
  ('hip-circles-prone', 'Krążenia kolanem w klęku podpartym', 'Hip Circles (prone)', 'motor_coach', 'beginner', array['Rozciąganie', 'Odwodziciele'], 'Krążenia ugiętym kolanem w klęku podpartym — mobilizacja stawu biodrowego. Prosty element rozgrzewki dolnej części ciała.', '1. Ustaw się na czworakach na podłodze. Zachowując prawidłową postawę, unieś jedno ugięte kolano nad ziemię. To będzie pozycja startowa.
2. Trzymając kolano w pozycji ugiętej, wykonuj koło kością udową, starając się nakreślić duże koło kolanem.
3. Wykonuj to powoli przez określoną liczbę powtórzeń, a następnie powtórz na drugiej stronie.', NULL, 'free-exercise-db/Hip_Circles_prone/0.jpg', 'free_exercise_db'),
  ('hip-extension-with-bands', 'Wyprost biodra z gumą oporową', 'Hip Extension with Bands', 'motor_coach', 'beginner', array['Siłowe', 'Pośladki'], 'Prostowanie biodra w tył z gumą oporową zakotwiczoną nisko. Izoluje pośladek i tylną część uda.', '1. Przymocuj jeden koniec gumy do dolnej części słupa, a drugi do kostki.
2. Stojąc twarzą do punktu mocowania gumy, złap się słupa dla stabilizacji.
3. Z głową i klatką piersiową uniesionymi prowadź nogę z oporem jak najdalej w tył, zachowując kolano proste.
4. Wróć nogą do pozycji startowej.', NULL, 'free-exercise-db/Hip_Extension_with_Bands/0.jpg', 'free_exercise_db'),
  ('hip-flexion-with-band', 'Zgięcie biodra z gumą oporową', 'Hip Flexion with Band', 'motor_coach', 'beginner', array['Siłowe', 'Uda'], 'Unoszenie kolana do góry z oporem gumy zakotwiczonej nisko. Wzmacnia zginacze bioder, ważne dla biegu i stabilności.', '1. Przymocuj jeden koniec gumy do dolnej części słupa, a drugi do kostki.
2. Stań tyłem do punktu mocowania gumy.
3. Z głową i klatką piersiową uniesionymi unieś kolano do 90 stopni i zatrzymaj się.
4. Wróć nogą do pozycji startowej.', NULL, 'free-exercise-db/Hip_Flexion_with_Band/0.jpg', 'free_exercise_db'),
  ('hip-lift-with-band', 'Unoszenie bioder z gumą oporową', 'Hip Lift with Band', 'motor_coach', 'beginner', array['Trójbój', 'Pośladki'], 'Mostek biodrowy z gumą dociskaną przez słupki stojaka. Mocna izolacja pośladków z dodatkowym oporem.', '1. Po wyborze odpowiedniej gumy połóż się na środku stojaka, po wcześniejszym zamocowaniu gumy po obu stronach. Jeśli twój stojak nie ma bolców, gumę można przymocować ciężkimi hantlami lub podobnymi przedmiotami — upewnij się tylko, że się nie poruszą.
2. Dostosuj pozycję tak, aby guma znalazła się dokładnie nad twoimi biodrami. Ugnij kolana i połóż stopy płasko na podłodze. Dłonie mogą być na podłodze albo trzymać gumę na miejscu.
3. Trzymając barki na podłożu, odpychaj się piętami, aby unieść biodra, wpychając je w gumę tak wysoko, jak potrafisz.
4. Zatrzymaj się na szczycie ruchu, a następnie wróć do pozycji startowej.', NULL, 'free-exercise-db/Hip_Lift_with_Band/0.jpg', 'free_exercise_db'),
  ('hug-a-ball', 'Przytulanie piłki gimnastycznej', 'Hug A Ball', 'motor_coach', 'beginner', array['Rozciąganie', 'Dolny odcinek pleców'], 'Ćwiczenie mobilizujące biodra i wzmacniające mięśnie przywodzicieli ud, wykonywane w siadzie z dużą piłką gimnastyczną między nogami. Angażuje też mięśnie dna miednicy.', '1. Usiądź na podłodze.
2. Obejmij nogami piłkę do ćwiczeń i opuść biodra w dół, w kierunku podłogi.
3. Obejmij ramionami piłkę, aby podeprzeć ciało. Ustaw nogi tak, by stopy płasko dotykały podłogi, a kolana znajdowały się nad kostkami. Trzymaj piłkę mocno, żeby się nie stoczyła i nie sprawiła, że przewrócisz się na pośladki.', NULL, 'free-exercise-db/Hug_A_Ball/0.jpg', 'free_exercise_db'),
  ('hug-knees-to-chest', 'Przyciąganie kolan do klatki piersiowej', 'Hug Knees To Chest', 'motor_coach', 'beginner', array['Rozciąganie', 'Dolny odcinek pleców'], 'Proste rozciąganie dolnego odcinka kręgosłupa i pośladków. Leżąc na plecach przyciągasz oba kolana do klatki piersiowej i przytrzymujesz je rękami.', '1. Połóż się na plecach i przyciągnij oba kolana do klatki piersiowej.
2. Chwyć ramiona pod kolanami, a nie nad nimi (chwyt nad kolanami wywiera zbyt duży nacisk na stawy kolanowe).
3. Powoli przyciągaj kolana w stronę barków. Rozciąga to również mięśnie pośladkowe.', NULL, 'free-exercise-db/Hug_Knees_To_Chest/0.jpg', 'free_exercise_db'),
  ('hurdle-hops', 'Skoki przez płotki', 'Hurdle Hops', 'motor_coach', 'beginner', array['Plyometryka', 'Dwugłowe uda'], 'Plyometryczne skoki obunóż przez rząd niskich płotków lub przeszkód. Rozwijają moc wybicia, koordynację i zdolność natychmiastowego odbicia między skokami.', '1. Ustaw rząd płotków lub innych niewielkich przeszkód, rozmieszczonych co kilkadziesiąt centymetrów.
2. Stań przed pierwszym płotkiem ze stopami na szerokość barków. To będzie pozycja startowa.
3. Zacznij od przeskoku obunóż nad pierwszym płotkiem, wymachując podczas skoku oboma ramionami.
4. Amortyzuj uderzenie przy lądowaniu uginając kolana i od razu odbij się z pierwszego wyskoku, przeskakując następny płotek. Kontynuuj, aż przeskoczysz wszystkie płotki.', NULL, 'free-exercise-db/Hurdle_Hops/0.jpg', 'free_exercise_db'),
  ('hyperextensions-back-extensions', 'Prostowanie tułowia na ławce rzymskiej', 'Hyperextensions (Back Extensions)', 'motor_coach', 'beginner', array['Siłowe', 'Dolny odcinek pleców'], 'Wzmacnia prostownik grzbietu, pośladki i dwugłowe uda. Zginasz tułów w dół z płaskimi plecami, a następnie unosisz korpus z powrotem do linii prostej.', '1. Połóż się twarzą w dół na ławce rzymskiej, wsuwając kostki bezpiecznie pod wałki.
2. Jeśli to możliwe, wyreguluj górny wałek tak, aby uda leżały płasko na szerokim podparciu, zostawiając wystarczająco dużo miejsca, by móc zginać się w pasie bez żadnych ograniczeń.
3. Z ciałem trzymanym prosto skrzyżuj ramiona przed sobą (preferowany sposób) lub za głową. To będzie pozycja startowa. Wskazówka: możesz także trzymać talerz dla dodatkowego oporu, przed sobą pod skrzyżowanymi ramionami.
4. Zacznij powoli zginać się w pasie tak daleko, jak to możliwe, trzymając plecy płaskie. Wdychaj powietrze podczas tego ruchu. Prowadź ruch do przodu, aż poczujesz przyjemne rozciągnięcie dwugłowych uda i nie będziesz mógł kontynuować bez zaokrąglenia pleców. Wskazówka: nigdy nie zaokrąglaj pleców podczas tego ćwiczenia. Niektórzy schodzą głębiej niż inni. Kluczowe jest, aby schodzić tak daleko, na ile pozwala ci ciało, bez zaokrąglania pleców.
5. Powoli unieś tułów z powrotem do pozycji początkowej, robiąc wdech. Wskazówka: opieraj się pokusie wyginania pleców ponad linię prostą. Nie wykonuj też nigdy wymachów tułowiem, aby chronić plecy przed urazem.
6. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Hyperextensions_Back_Extensions/0.jpg', 'free_exercise_db'),
  ('hyperextensions-with-no-hyperextension-bench', 'Prostowanie tułowia bez ławki rzymskiej', 'Hyperextensions With No Hyperextension Bench', 'motor_coach', 'intermediate', array['Siłowe', 'Dolny odcinek pleców'], 'Wariant prostowania tułowia na zwykłej ławce płaskiej, gdy brakuje ławki rzymskiej. Biodra wystają poza krawędź ławki, więc zakres ruchu jest mniejszy, ale praca mięśni podobna.', '1. Z partnerem trzymającym twoje nogi zsuń się po ławce płaskiej do jej końca, aż biodra wystaną poza krawędź ławki. Wskazówka: cały górny odcinek ciała powinien zwisać w dół, w kierunku podłogi. Jesteś w tej samej pozycji co na ławce rzymskiej, ale zakres ruchu będzie krótszy ze względu na wysokość ławki płaskiej w porównaniu z ławką rzymską.
2. Z ciałem trzymanym prosto skrzyżuj ramiona przed sobą (preferowany sposób) lub za głową. To będzie pozycja startowa. Wskazówka: możesz także trzymać talerz dla dodatkowego oporu, przed sobą pod skrzyżowanymi ramionami.
3. Zacznij powoli zginać się w pasie tak daleko, jak to możliwe, trzymając plecy płaskie. Wdychaj powietrze podczas tego ruchu. Schodź w dół, aż prawie dotkniesz podłogi albo poczujesz przyjemne rozciągnięcie dwugłowych uda (cokolwiek nastąpi pierwsze). Wskazówka: nigdy nie zaokrąglaj pleców podczas tego ćwiczenia.
4. Powoli unieś tułów z powrotem do pozycji początkowej, robiąc wydech. Wskazówka: opieraj się pokusie wyginania pleców ponad linię prostą. Nie wykonuj też nigdy wymachów tułowiem, aby chronić plecy przed urazem.
5. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Hyperextensions_With_No_Hyperextension_Bench/0.jpg', 'free_exercise_db'),
  ('iliotibial-tract-smr', 'Rolowanie pasa biodrowo-piszczelowego (SMR)', 'Iliotibial Tract-SMR', 'motor_coach', 'intermediate', array['Rozciąganie', 'Odwodziciele'], 'Automasaż wałkiem zewnętrznej części uda, od biodra do kolana. Leżąc na boku toczysz nogę po roli, zatrzymując się na miejscach napięcia.', '1. Połóż się na boku, umieszczając dolną nogę na wałku do masażu między biodrem a kolanem. Druga noga może być skrzyżowana z przodu.
2. Obciąż dolną nogę tyle, ile jesteś w stanie znieść; nie ma potrzeby, aby dolna noga dotykała podłogi. Pamiętaj o rozluźnieniu mięśni rozciąganej nogi.
3. Tocz nogę po wałku od biodra do kolana, zatrzymując się na 10–30 sekund w miejscach napięcia. Powtórz na drugiej nodze.', NULL, 'free-exercise-db/Iliotibial_Tract-SMR/0.jpg', 'free_exercise_db'),
  ('inchworm', 'Chodzenie rękami (inchworm)', 'Inchworm', 'motor_coach', 'beginner', array['Rozciąganie', 'Dwugłowe uda'], 'Dynamiczna rozgrzewka całego ciała: z pozycji stojącej przechodzisz rękami do pozycji do pompków, a następnie dokładasz stopy do rąk małymi krokami. Rozciąga tylne taśmy mięśniowe i angażuje mięśnie głębokie.', '1. Stań ze stopami blisko siebie. Trzymając nogi proste, pochyl się w dół i połóż ręce na podłodze bezpośrednio przed sobą. To będzie pozycja startowa.
2. Zacznij powoli przechodzić rękami do przodu, naprzemiennie lewą i prawą. Podczas tego ruchu zginaj się tylko w biodrach, trzymając nogi proste.
3. Kontynuuj, aż twoje ciało będzie równoległe do podłoża w pozycji do pompków.
4. Teraz, trzymając ręce w miejscu, wykonuj krótkie kroki stopami, przesuwając się tylko kilka centymetrów naraz.
5. Kontynuuj chodzenie, aż stopy będą przy twoich dłoniach, trzymając przy tym nogi proste.', NULL, 'free-exercise-db/Inchworm/0.jpg', 'free_exercise_db'),
  ('incline-barbell-triceps-extension', 'Francuskie wyciskanie na ławce skośnej', 'Incline Barbell Triceps Extension', 'motor_coach', 'intermediate', array['Siłowe', 'Triceps'], 'Izolowane ćwiczenie tricepsa wykonywane leżąc na ławce skośnej. Opuszczasz sztangę półkolistym ruchem za głowę i prostujesz ramiona — pracują tylko przedramiona.', '1. Chwyć sztangę nachwytem (palce skierowane w dół) nieco węziej niż szerokość barków.
2. Połóż się na ławce skośnej ustawionej pod dowolnym kątem między 45 a 75 stopni.
3. Unieś sztangę nad głowę z wyprostowanymi ramionami i łokciami skierowanymi do środka. Ramiona powinny tworzyć linię z tułowiem nad głową. To będzie pozycja startowa.
4. Teraz opuszczaj sztangę ruchem półkolistym za głowę, aż przedramiona dotkną bicepsów. Wdychaj powietrze podczas tego ruchu. Wskazówka: trzymaj ramiona nieruchomo i blisko głowy przez cały czas. Poruszać się powinny tylko przedramiona.
5. Wróć do pozycji startowej na wydechu, napinając triceps. Utrzymaj spięcie mięśnia przez sekundę.
6. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Incline_Barbell_Triceps_Extension/0.jpg', 'free_exercise_db'),
  ('incline-bench-pull', 'Wiosłowanie hantlami na ławce skośnej', 'Incline Bench Pull', 'motor_coach', 'beginner', array['Siłowe', 'Środek pleców'], 'Wiosłowanie hantlami w leżeniu przodem na ławce skośnej. Łokcie idą na boki, aż ramiona znajdą się na wysokości pleców — świetne ćwiczenie na tył obręczy barkowej.', '1. Weź hantlę w każdą rękę i połóż się twarzą w dół na ławce skośnej ustawionej pod kątem około 30 stopni.
2. Pozwól ramionom zwisać po bokach, w pełni wyprostowanym, z dłońmi skierowanymi w dół.
3. Obróć nadgarstki tak, aby dłonie miały chwyt nachwytem (palce skierowane w dół).
4. Teraz skieruj łokcie na boki. To będzie pozycja startowa.
5. Na wydechu zacznij ciągnąć hantle w górę, jakbyś robił odwrotne wyciskanie na ławce. Zrobisz to, zginając łokcie i unosząc ramiona, pozwalając przedramionom zwisać. Kontynuuj ten ruch, aż ramiona znajdą się na poziomie twoich pleców. Wskazówka: łokcie odejdą na boki, a ramiona i tułów powinny utworzyć literę „T” na szczycie ruchu. Utrzymaj spięcie na szczycie przez sekundę.
6. Powoli opuść się z powrotem do pozycji startowej, robiąc wdech.
7. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Incline_Bench_Pull/0.jpg', 'free_exercise_db'),
  ('incline-cable-chest-press', 'Skośne wyciskanie na wyciągu', 'Incline Cable Chest Press', 'motor_coach', 'beginner', array['Siłowe', 'Klatka piersiowa'], 'Wyciskanie w siadzie na wyciągu linkowym, ukierunkowane na górną część klatki piersiowej. Prostujesz ramiona przed sobą, dociskając uchwyty do siebie i ściągając łopatki.', '1. Ustaw odpowiedni ciężar, usiądź i złap za uchwyty. Twoje ramiona powinny być pod kątem około 45 stopni do ciała, z głową i klatką piersiową uniesionymi. Łokcie powinny być zgięte pod kątem około 90 stopni. To będzie pozycja startowa.
2. Zacznij od wyprostu w łokciach, dociskając uchwyty do siebie prosto przed siebie. Ściągaj łopatki podczas wykonywania ruchu.
3. Po pauzie przy pełnym wyproście wróć do pozycji startowej, utrzymując napięcie linek.', NULL, 'free-exercise-db/Incline_Cable_Chest_Press/0.jpg', 'free_exercise_db'),
  ('incline-cable-flye', 'Rozpiętki na wyciągu na ławce skośnej', 'Incline Cable Flye', 'motor_coach', 'intermediate', array['Siłowe', 'Klatka piersiowa'], 'Izolacja górnej części klatki piersiowej na wyciągach w leżeniu na ławce skośnej. Opuszczasz ramiona szerokim łukiem, a następnie wracasz, ściskając mięśnie piersiowe.', '1. Aby przejść do pozycji startowej, ustaw bloki na dolnej pozycji (najniżej możliwej na maszynie, poniżej twojego tułowia).
2. Umieść ławkę skośną (ustawioną pod kątem 45 stopni) między blokami, dobierz ciężar na każdym z nich i złap uchwyt każdą ręką.
3. Z uchwytem w każdej ręce połóż się na ławce skośnej i zbliż dłonie do siebie na wyciągniętych ramionach przed twarzą. To będzie pozycja startowa.
4. Z lekkim ugięciem łokci (aby zapobiec przeciążeniu ścięgna bicepsa) opuszczaj ramiona na obie strony szerokim łukiem, aż poczujesz rozciągnięcie w klatce piersiowej. Wdychaj powietrze podczas tej części ruchu. Wskazówka: pamiętaj, że przez cały ruch ramiona powinny pozostawać nieruchome. Ruch powinien odbywać się tylko w stawie barkowym.
5. Wróć ramionami do pozycji startowej, ściskając mięśnie piersiowe i robiąc wydech. Utrzymaj pozycję spięcia przez sekundę. Wskazówka: upewnij się, że używasz tego samego łuku ruchu, którym opuszczałeś ciężary.
6. Powtórz ruch zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Incline_Cable_Flye/0.jpg', 'free_exercise_db'),
  ('incline-dumbbell-bench-with-palms-facing-in', 'Wyciskanie hantli na ławce skośnej chwytem neutralnym', 'Incline Dumbbell Bench With Palms Facing In', 'motor_coach', 'beginner', array['Siłowe', 'Klatka piersiowa'], 'Wyciskanie hantli na ławce skośnej z dłońmi zwróconymi ku sobie (chwyt neutralny). Odmiana odciążająca barki, mocno pracuje górną częścią klatki piersiowej.', '1. Połóż się na ławce skośnej z hantlą w każdej dłoni na udach. Dłonie powinny być zwrócone ku sobie.
2. Używając ud jako pomocy, podrzuć hantle jednym ramieniem naraz tak, aby móc trzymać je na szerokości barków.
3. Gdy znajdziesz się na szerokości barków, utrzymuj chwyt neutralny (dłonie skierowane ku sobie). Trzymaj łokcie rozstawione na boki, z ramionami w linii barków (prostopadle do tułowia), a łokcie zgięte tworząc kąt 90 stopni między ramieniem a przedramieniem. To będzie pozycja startowa.
4. Teraz opuszczaj ciężary powoli w boki, robiąc wdech. Zachowuj pełną kontrolę nad hantlami przez cały czas.
5. Na wydechu wypchnij hantle w górę, używając mięśni piersiowych. Zablokuj ramiona w pozycji spięcia, przytrzymaj przez sekundę, a następnie zacznij powoli opuszczać. Wskazówka: opuszczanie powinno trwać co najmniej dwa razy dłużej niż unoszenie.
6. Powtórz ruch zalecaną liczbę powtórzeń.
7. Gdy skończysz, oprzyj hantle na udach, a następnie odłóż je na podłogę. To najbezpieczniejszy sposób odłożenia hantli.', NULL, 'free-exercise-db/Incline_Dumbbell_Bench_With_Palms_Facing_In/0.jpg', 'free_exercise_db'),
  ('incline-dumbbell-curl', 'Uginanie ramion z hantlami na ławce skośnej', 'Incline Dumbbell Curl', 'motor_coach', 'beginner', array['Siłowe', 'Biceps'], 'Uginanie hantli w oparciu o ławkę skośną, z ramionami cofniętymi za linię tułowia. Maksymalnie rozciąga i wzmacnia biceps.', '1. Oprzyj się na ławce skośnej z hantlą w każdej dłoni, trzymając je na wyciągniętych ramionach. Trzymaj łokcie blisko tułowia i obróć dłonie tak, aby były skierowane do przodu. To będzie pozycja startowa.
2. Trzymając ramię nieruchomo, uginaj ciężary do przodu, napinając biceps na wydechu. Poruszać się powinny tylko przedramiona. Kontynuuj ruch, aż biceps będzie w pełni spięty, a hantle na wysokości barków. Utrzymaj pozycję spięcia przez sekundę.
3. Powoli zacznij opuszczać hantle do pozycji startowej, robiąc wdech.
4. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Incline_Dumbbell_Curl/0.jpg', 'free_exercise_db'),
  ('incline-dumbbell-flyes', 'Rozpiętki z hantlami na ławce skośnej', 'Incline Dumbbell Flyes', 'motor_coach', 'beginner', array['Siłowe', 'Klatka piersiowa'], 'Klasyczne rozpiętki hantlami na ławce skośnej, izolujące górną część klatki piersiowej. Opuszczasz ramiona szerokim łukiem przy lekko ugiętych łokciach, a potem wracasz, ściskając klatkę.', '1. Trzymaj hantlę w każdej ręce i połóż się na ławce skośnej ustawionej pod kątem nie większym niż 30 stopni.
2. Wyprostuj ramiona nad sobą z lekkim ugięciem w łokciach.
3. Teraz obróć nadgarstki tak, aby dłonie były zwrócone ku sobie. Wskazówka: małe palce powinny znajdować się obok siebie. To będzie pozycja startowa.
4. Na wdechu zacznij powoli opuszczać ramiona na boki, utrzymując je wyprostowane i obracając nadgarstki, aż dłonie będą zwrócone ku sobie. Wskazówka: na końcu ruchu ramiona będą przy bokach, z dłońmi skierowanymi ku sufitowi.
5. Na wydechu zacznij unosić hantle z powrotem do pozycji startowej, odwracając ruch i obracając dłonie tak, aby małe palce znów były obok siebie. Wskazówka: pamiętaj, że ruch odbywa się tylko w stawie barkowym i nadgarstku. Żaden ruch nie zachodzi w stawie łokciowym.
6. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Incline_Dumbbell_Flyes/0.jpg', 'free_exercise_db'),
  ('incline-dumbbell-flyes-with-a-twist', 'Rozpiętki z hantlami na ławce skośnej z rotacją nadgarstków', 'Incline Dumbbell Flyes - With A Twist', 'motor_coach', 'beginner', array['Siłowe', 'Klatka piersiowa'], 'Rozpiętki na ławce skośnej z dodatkową rotacją dłoni w fazie unoszenia — mocniejsze spięcie klatki piersiowej dzięki obracaniu nadgarstków w górnej fazie ruchu.', '1. Trzymaj hantlę w każdej ręce i połóż się na ławce skośnej ustawionej pod kątem nie większym niż 30 stopni.
2. Wyprostuj ramiona nad sobą z lekkim ugięciem w łokciach.
3. Teraz obróć nadgarstki tak, aby dłonie były zwrócone ku sobie. Wskazówka: małe palce powinny znajdować się obok siebie. To będzie pozycja startowa.
4. Na wdechu zacznij powoli opuszczać ramiona na boki, utrzymując je wyprostowane i obracając nadgarstki, aż dłonie będą zwrócone ku sobie. Wskazówka: na końcu ruchu ramiona będą przy bokach, z dłońmi skierowanymi ku sufitowi.
5. Na wydechu zacznij unosić hantle z powrotem do pozycji startowej, odwracając ruch i obracając dłonie tak, aby małe palce znów były obok siebie. Wskazówka: pamiętaj, że ruch odbywa się tylko w stawie barkowym i nadgarstku. Żaden ruch nie zachodzi w stawie łokciowym.
6. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Incline_Dumbbell_Flyes_-_With_A_Twist/0.jpg', 'free_exercise_db'),
  ('incline-dumbbell-press', 'Wyciskanie hantli na ławce skośnej', 'Incline Dumbbell Press', 'motor_coach', 'beginner', array['Siłowe', 'Klatka piersiowa'], 'Podstawowe ćwiczenie na górną część klatki piersiowej z hantlami na ławce skośnej. Opuszczasz hantle na boki klatki i wyciskasz je w górę nad klatkę.', '1. Połóż się na ławce skośnej z hantlą w każdej dłoni na udach. Dłonie powinny być zwrócone ku sobie.
2. Następnie, używając ud jako pomocy do podrzucenia hantli, podnieś hantle jedną po drugiej, aby móc trzymać je na szerokości barków.
3. Gdy uniesiesz hantle na szerokość barków, obróć nadgarstki do przodu tak, aby dłonie były zwrócone od ciebie. To będzie pozycja startowa.
4. Pamiętaj, aby zachować pełną kontrolę nad hantlami przez cały czas. Następnie zrób wydech i wypchnij hantle w górę klatką piersiową.
5. Zablokuj ramiona na szczycie, przytrzymaj przez sekundę, a potem zacznij powoli opuszczać ciężar. Wskazówka: idealnie, opuszczanie ciężarów powinno trwać około dwa razy dłużej niż ich unoszenie.
6. Powtórz ruch zalecaną liczbę powtórzeń.
7. Gdy skończysz, oprzyj hantle na udach, a następnie odłóż je na podłogę. To najbezpieczniejszy sposób odłożenia hantli.', NULL, 'free-exercise-db/Incline_Dumbbell_Press/0.jpg', 'free_exercise_db'),
  ('incline-hammer-curls', 'Uginanie ramion chwytem młotkowym na ławce skośnej', 'Incline Hammer Curls', 'motor_coach', 'beginner', array['Siłowe', 'Biceps'], 'Uginanie hantli chwytem młotkowym w oparciu o ławkę skośną. Buduje biceps i mięsień ramieniowy, z dłońmi zwróconymi ku sobie przez cały ruch.', '1. Usiądź na ławce skośnej z hantlą w każdej dłoni. Powinieneś być mocno dociśnięty do oparcia, ze stopami złączonymi. Pozwól hantlom swobodnie zwisać wzdłuż boków, trzymając je chwytem neutralnym. To będzie pozycja startowa.
2. Rozpocznij ruch zginając łokieć, starając się utrzymać ramię nieruchomo.
3. Prowadź ruch do szczytu, zrób pauzę, a następnie powoli wróć do pozycji startowej.', NULL, 'free-exercise-db/Incline_Hammer_Curls/0.jpg', 'free_exercise_db'),
  ('incline-inner-biceps-curl', 'Uginanie ramion hantlami na boki na ławce skośnej', 'Incline Inner Biceps Curl', 'motor_coach', 'beginner', array['Siłowe', 'Biceps'], 'Wariant uginania hantli na ławce skośnej, w którym ciężary unoszone są na boki, w linii barków. Końcowe ułożenie ramion przypomina słynną pozę double biceps.', '1. Trzymaj hantlę w każdej dłoni i oprzyj się na ławce skośnej.
2. Hantle powinny zwisać swobodnie po bokach, a dłonie być skierowane na zewnątrz. To będzie pozycja startowa.
3. Teraz na wydechu uginaj ciężar na zewnątrz i w górę, trzymając przedramiona w linii z bocznymi aktonami barków. Kontynuuj uginanie, aż hantle znajdą się na wysokości barków, po bokach deltoidów. Wskazówka: koniec ruchu powinien wyglądać podobnie do pozy double biceps.
4. Po sekundzie spięcia na szczycie ruchu zacznij wdychać i powoli opuszczaj ciężary z powrotem do pozycji startowej, tą samą ścieżką, którą je unosiłeś.
5. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Incline_Inner_Biceps_Curl/0.jpg', 'free_exercise_db'),
  ('incline-push-up', 'Pompki z podwyższeniem', 'Incline Push-Up', 'motor_coach', 'beginner', array['Siłowe', 'Klatka piersiowa'], 'Łatwiejsza wersja pompków z dłońmi opartymi na ławce lub innym podwyższeniu. Idealne dla początkujących — mniej obciąża ramiona i klatkę piersiową.', '1. Stań twarzą do ławki lub stabilnego podwyższenia. Połóż dłonie na krawędzi ławki lub platformy, nieco szerzej niż szerokość barków.
2. Cofnij śródstopie od ławki lub platformy, z ramionami i ciałem wyprostowanymi. Ramiona powinny być prostopadłe do ciała. Trzymając ciało prosto, opuść klatkę piersiową do krawędzi skrzyni lub platformy, uginając ramiona.
3. Odepchnij ciało w górę, aż ramiona będą wyprostowane. Powtórz.', NULL, 'free-exercise-db/Incline_Push-Up/0.jpg', 'free_exercise_db'),
  ('incline-push-up-close-grip', 'Pompki z podwyższeniem chwytem wąskim', 'Incline Push-Up Close-Grip', 'motor_coach', 'beginner', array['Siłowe', 'Triceps'], 'Wariant pompków z podwyższeniem z dłońmi złożonymi obok siebie. Więcej pracy wykonują tricepsy.', '1. Stań twarzą do sztangi maszyny Smitha lub stabilnego podwyższenia na odpowiedniej wysokości.
2. Połóż dłonie obok siebie na sztandze.
3. Cofnij stopy od sztangi, z ramionami i ciałem wyprostowanymi. To będzie pozycja startowa.
4. Trzymając ciało prosto, opuść klatkę piersiową do sztangi, uginając ramiona.
5. Wróć do pozycji startowej, prostując łokcie i wypychając się w górę.', NULL, 'free-exercise-db/Incline_Push-Up_Close-Grip/0.jpg', 'free_exercise_db'),
  ('incline-push-up-depth-jump', 'Pompki z podwyższeniem z wyskokiem (depth jump)', 'Incline Push-Up Depth Jump', 'motor_coach', 'beginner', array['Plyometryka', 'Klatka piersiowa'], 'Plyometryczne ćwiczenie łączące pompki z podwyższeniem z przeskokiem rąk na stepy aerobikowe. Rozwija moc górnej części ciała i eksplozywność.', '1. Do tego ćwiczenia potrzebujesz skrzyni o wysokości około 30 cm oraz dwóch grubych mat lub stepów aerobikowych.
2. Ustaw stepy tuż na zewnątrz twoich barków, a stopy połóż na skrzyni, abyś znalazł się w pozycji pompki z podwyższeniem, z rękami tuż wewnątrz stepów. To będzie pozycja startowa.
3. Zacznij od ugięcia łokci, aby opuścić ciało, szybko odwracając ruch, aby odepchnąć ciało od podłoża. Gdy oderwiesz dłonie od podłoża, przenieś ręce na stepy, uginając łokcie, aby zamortyzować uderzenie.
4. Powtórz ruch, aby wrócić do pozycji startowej.', NULL, 'free-exercise-db/Incline_Push-Up_Depth_Jump/0.jpg', 'free_exercise_db'),
  ('incline-push-up-medium', 'Pompki z podwyższeniem — średni rozstaw rąk', 'Incline Push-Up Medium', 'motor_coach', 'beginner', array['Siłowe', 'Klatka piersiowa'], 'Pompki z podwyższeniem z rękami na szerokość barków. Uniwersalna wersja równomiernie angażująca klatkę piersiową i tricepsy.', '1. Stań twarzą do sztangi maszyny Smitha lub stabilnego podwyższenia na odpowiedniej wysokości.
2. Połóż ręce na sztandze, mniej więcej na szerokość barków.
3. Cofnij stopy od sztangi, z ramionami i ciałem wyprostowanymi. To będzie pozycja startowa.
4. Trzymając ciało prosto, opuść klatkę piersiową do sztangi, uginając ramiona.
5. Wróć do pozycji startowej, prostując łokcie i wypychając się w górę.', NULL, 'free-exercise-db/Incline_Push-Up_Medium/0.jpg', 'free_exercise_db'),
  ('incline-push-up-reverse-grip', 'Pompki z podwyższeniem chwytem odwróconym', 'Incline Push-Up Reverse Grip', 'motor_coach', 'beginner', array['Siłowe', 'Klatka piersiowa'], 'Wariant pompków z podwyższeniem z dłońmi na drążku chwytem podchwytem. Inaczej angażuje biceps i przedramiona.', '1. Stań twarzą do sztangi maszyny Smitha lub stabilnego podwyższenia na odpowiedniej wysokości.
2. Połóż ręce na sztandze chwytem podchwytem, mniej więcej na szerokość barków.
3. Cofnij stopy od sztangi, z ramionami i ciałem wyprostowanymi. To będzie pozycja startowa.
4. Trzymając ciało prosto, opuść klatkę piersiową do sztangi, uginając ramiona.
5. Wróć do pozycji startowej, prostując łokcie i wypychając się w górę.', NULL, 'free-exercise-db/Incline_Push-Up_Reverse_Grip/0.jpg', 'free_exercise_db'),
  ('incline-push-up-wide', 'Pompki z podwyższeniem — szeroki rozstaw rąk', 'Incline Push-Up Wide', 'motor_coach', 'beginner', array['Siłowe', 'Klatka piersiowa'], 'Wariant pompków z podwyższeniem z rękami szerzej niż barki. Mocniej angażuje zewnętrzne partie klatki piersiowej.', '1. Stań twarzą do sztangi maszyny Smitha lub stabilnego podwyższenia na odpowiedniej wysokości.
2. Połóż ręce na sztandze, szerzej niż szerokość barków.
3. Cofnij stopy od sztangi, z ramionami i ciałem wyprostowanymi. Ramiona powinny być prostopadłe do ciała. To będzie pozycja startowa.
4. Trzymając ciało prosto, opuść klatkę piersiową do sztangi, uginając ramiona.
5. Wróć do pozycji startowej, prostując łokcie i wypychając się w górę.', NULL, 'free-exercise-db/Incline_Push-Up_Wide/0.jpg', 'free_exercise_db'),
  ('intermediate-groin-stretch', 'Średniozaawansowane rozciąganie pachwin', 'Intermediate Groin Stretch', 'motor_coach', 'intermediate', array['Rozciąganie', 'Dwugłowe uda'], 'Rozciąganie pachwin i dwugłowych uda w leżeniu na plecach, z użyciem pasa lub gumy. Noga przenoszona jest możliwie najdalej na bok.', '1. Połóż się na plecach z nogami wyprostowanymi. Załóż pasek, linę lub gumę na jedną ze stóp i przenieś tę nogę możliwie najdalej na bok. To będzie pozycja startowa.
2. Delikatnie pociągnij za pasek, aby stworzyć napięcie w mięśniach pachwin i dwugłowym uda. Utrzymaj przez 10–20 sekund i powtórz na drugiej stronie.', NULL, 'free-exercise-db/Intermediate_Groin_Stretch/0.jpg', 'free_exercise_db'),
  ('intermediate-hip-flexor-and-quad-stretch', 'Średniozaawansowane rozciąganie zginaczy bioder i czworogłowych', 'Intermediate Hip Flexor and Quad Stretch', 'motor_coach', 'intermediate', array['Rozciąganie', 'Uda'], 'Rozciąganie zginaczy biodra i mięśnia czworogłowego uda w leżeniu na brzuchu, z pasem lub gumą wokół stopy. Kolano ugina się, a noga unosi z podłogi, tworząc napięcie.', '1. Połóż się twarzą w dół na podłodze, z liną, paskiem lub gumą założoną wokół jednej stopy.
2. Zegnij kolano i wyprostuj biodro rozciąganej nogi, używając obu rąk do pociągnięcia za pasek. Kolano i biodro powinny oderwać się od podłogi, tworząc napięcie w zginaczach biodra i mięśniu czworogłowym. Utrzymaj rozciąganie przez 10–20 sekund i powtórz na drugą nogę.', NULL, 'free-exercise-db/Intermediate_Hip_Flexor_and_Quad_Stretch/0.jpg', 'free_exercise_db'),
  ('internal-rotation-with-band', 'Rotacja wewnętrzna barku z gumą', 'Internal Rotation with Band', 'motor_coach', 'beginner', array['Siłowe', 'Barki'], 'Ćwiczenie rehabilitacyjne na wewnętrzne rotatory barku z gumą oporową przerzuconą przez słupek. Rotujesz ramię ruchem jak forehand, trzymając łokieć przy tułowiu.', '1. Owiń gumę wokół słupka. Guma powinna znajdować się na wysokości twojego łokcia. Stań prawym bokiem do gumy, w odległości około metra.
2. Chwyć koniec gumy prawą ręką i mocno dociśnij łokieć do boku. Zalecamy przytrzymanie poduszki lub wałka łokciem, aby utrzymać go pewnie w pozycji.
3. Z ramieniem w pozycji, łokieć powinien być zgięty pod kątem 90 stopni, z dłonią sięgającą w stronę przeciwną do tułowia. To będzie pozycja startowa.
4. Wykonaj ruch, obracając ramię ruchem jak forehand (jak w tenisie), trzymając łokieć w miejscu.
5. Kontynuuj tak daleko, jak potrafisz, zrób pauzę, a następnie wróć do pozycji startowej.', NULL, 'free-exercise-db/Internal_Rotation_with_Band/0.jpg', 'free_exercise_db'),
  ('inverted-row', 'Wiosłowanie w opadzie (australijskie)', 'Inverted Row', 'motor_coach', 'beginner', array['Siłowe', 'Środek pleców'], 'Wiosłowanie własnym ciężarem pod sztangą w stojaku — często nazywane „wiosłowaniem australijskim”. Ciało proste jak deska, ciągniesz klatkę do sztangi, ściągając łopatki.', '1. Ustaw sztangę w stojaku na wysokości około pasa. Możesz też użyć maszyny Smitha.
2. Złap sztangę chwytem nieco szerszym niż szerokość barków i ustaw się wisząc pod sztangą. Ciało powinno być wyprostowane, pięty na ziemi, ramiona w pełni wyprostowane. To będzie pozycja startowa.
3. Zacznij od zgięcia łokci, ciągnąc klatkę piersiową w kierunku sztangi. Ściągaj łopatki podczas wykonywania ruchu.
4. Zrób pauzę na szczycie ruchu, a następnie wróć do pozycji startowej.
5. Powtórz żądaną liczbę powtórzeń.', NULL, 'free-exercise-db/Inverted_Row/0.jpg', 'free_exercise_db'),
  ('inverted-row-with-straps', 'Wiosłowanie w opadzie z zawieszeniem (straps)', 'Inverted Row with Straps', 'motor_coach', 'beginner', array['Siłowe', 'Środek pleców'], 'Wiosłowanie australijskie na zawieszonych uchwytach lub linach (np. TRX). Ciągniesz klatkę do dłoni, utrzymując proste ciało — dodatkowo pracują mięśnie głębokie.', '1. Zawieś linę lub uchwyty treningowe na stojaku lub innym stabilnym obiekcie. Złap końce i ustaw się w pozycji leżącej na plecach, wisząc na linach. Ciało powinno być proste, pięty na ziemi, ramiona w pełni wyprostowane. To będzie pozycja startowa.
2. Zacznij od zgięcia łokci, ciągnąc klatkę piersiową w kierunku dłoni. Ściągaj łopatki podczas wykonywania ruchu.
3. Zrób pauzę na szczycie ruchu, a następnie wróć do pozycji startowej.
4. Powtórz żądaną liczbę powtórzeń.', NULL, 'free-exercise-db/Inverted_Row_with_Straps/0.jpg', 'free_exercise_db'),
  ('iron-crosses-stretch', 'Żelazny krzyż (rozciąganie)', 'Iron Crosses (stretch)', 'motor_coach', 'intermediate', array['Rozciąganie', 'Uda'], 'Dynamiczne rozciąganie dolnego odcinka pleców i pośladków w leżeniu na brzuchu, z ramionami rozłożonymi na boki. Przenosisz kolano przez ciało w stronę przeciwnej dłoni.', '1. Połóż się twarzą w dół na podłodze, z ramionami rozłożonymi na boki i dłońmi dociśniętymi do podłogi. To będzie pozycja startowa.
2. Zacznij od zgięcia jednego kolana i przeniesienia tej nogi przez tył ciała, próbując dotknąć nią podłogi w pobliżu przeciwnej dłoni.
3. Szybko wróć nogą do pozycji startowej i natychmiast powtórz drugą nogą. Kontynuuj naprzemiennie przez 10–20 powtórzeń.', NULL, 'free-exercise-db/Iron_Crosses_stretch/0.jpg', 'free_exercise_db'),
  ('isometric-chest-squeezes', 'Statyczne ściskanie dłoni (izometria klatki)', 'Isometric Chest Squeezes', 'motor_coach', 'beginner', array['Plyometryka', 'Klatka piersiowa'], 'Izometryczne ćwiczenie klatki piersiowej bez sprzętu. Dociskasz dłonie do siebie przed klatką piersiową i utrzymujesz napięcie przez kilka sekund.', '1. W siadzie lub na stojąco ugnij ramiona pod kątem 90 stopni i złóż dłonie dłońmi przed klatką piersiową. Wskazówka: dłonie powinny być otwarte, dłońmi do siebie, z palcami skierowanymi do przodu (prostopadle do tułowia).
2. Dociskaj obie dłonie do siebie, napinając klatkę piersiową. Zacznij od wolnego napięcia i zwiększaj je powoli. Oddychaj normalnie podczas wykonywania tego napięcia.
3. Utrzymaj przez zalecaną liczbę sekund.
4. Teraz powoli puść napięcie.
5. Odpocznij przez zalecany czas i powtórz.', NULL, 'free-exercise-db/Isometric_Chest_Squeezes/0.jpg', 'free_exercise_db'),
  ('isometric-neck-exercise-front-and-back', 'Izometryczne ćwiczenie karku — przód i tył', 'Isometric Neck Exercise - Front And Back', 'motor_coach', 'beginner', array['Siłowe', 'Kark'], 'Izometryczne ćwiczenie mięśni szyi: dociskasz dłonie do czoła i potylicy, nie pozwalając głowie na ruch. Wzmacnia mięśnie karku bez ruchu w stawach.', '1. Z głową i szyją w pozycji neutralnej (normalna pozycja z głową uniesioną, patrzącą do przodu), połóż obie ręce na przedniej części głowy.
2. Teraz delikatnie pchnij do przodu, napinając mięśnie szyi, ale opierając się wszelkiemu ruchowi głowy. Zacznij od wolnego napięcia i zwiększaj je powoli. Oddychaj normalnie podczas wykonywania tego napięcia.
3. Utrzymaj przez zalecaną liczbę sekund.
4. Teraz powoli puść napięcie.
5. Odpocznij przez zalecany czas i powtórz, tym razem z rękami położonymi na tylnej części głowy.', NULL, 'free-exercise-db/Isometric_Neck_Exercise_-_Front_And_Back/0.jpg', 'free_exercise_db'),
  ('isometric-neck-exercise-sides', 'Izometryczne ćwiczenie karku — strony', 'Isometric Neck Exercise - Sides', 'motor_coach', 'beginner', array['Siłowe', 'Kark'], 'Izometryczne ćwiczenie bocznych mięśni szyi. Dociskasz dłoń do boku głowy, opierając się ruchowi — naprzemiennie lewą i prawą ręką.', '1. Z głową i szyją w pozycji neutralnej (normalna pozycja z głową uniesioną, patrzącą do przodu), połóż lewą rękę na lewej stronie głowy.
2. Teraz delikatnie pchnij w lewo, napinając lewe mięśnie szyi, ale opierając się wszelkiemu ruchowi głowy. Zacznij od wolnego napięcia i zwiększaj je powoli. Oddychaj normalnie podczas wykonywania tego napięcia.
3. Utrzymaj przez zalecaną liczbę sekund.
4. Teraz powoli puść napięcie.
5. Odpocznij przez zalecany czas i powtórz z prawą ręką na prawej stronie głowy.', NULL, 'free-exercise-db/Isometric_Neck_Exercise_-_Sides/0.jpg', 'free_exercise_db'),
  ('isometric-wipers', 'Statyczne wycieraczki (izometria w pompce)', 'Isometric Wipers', 'motor_coach', 'beginner', array['Siłowe', 'Klatka piersiowa'], 'Izometryczny wariant pompki: w pozycji pompki przenosisz ciężar ciała maksymalnie na jedną rękę, uginając jej łokieć, a potem na drugą. Buduje siłę statyczną ramion i klatki.', '1. Przyjmij pozycję pompki, podpierając się na dłoniach i palcach stóp z ciałem utrzymanym prosto. Dłonie powinny znajdować się tuż poza szerokością barków. To będzie pozycja startowa.
2. Zacznij od przeniesienia ciężaru ciała możliwie jak najdalej na jedną stronę, pozwalając, aby łokieć po tej stronie uginał się, gdy opuszczasz ciało.
3. Odwróć ruch prostując ugięte ramię, wypychając się w górę, a następnie przechodząc na drugą stronę.
4. Powtórz żądaną liczbę powtórzeń.', NULL, 'free-exercise-db/Isometric_Wipers/0.jpg', 'free_exercise_db'),
  ('it-band-and-glute-stretch', 'Rozciąganie pasa biodrowo-piszczelowego i pośladka', 'IT Band and Glute Stretch', 'motor_coach', 'intermediate', array['Rozciąganie', 'Odwodziciele'], 'Rozciąganie leżąc z pasem lub gumą założoną na stopę. Noga przenoszona jest przez linię ciała na przeciwną stronę, co rozciąga pas biodrowo-piszczelowy i pośladek.', '1. Załóż pasek, linę lub gumę na jedną ze stóp i przenieś tę nogę przez linię ciała na przeciwną stronę, utrzymując nogę wyprostowaną, gdy leżysz na ziemi. To będzie pozycja startowa.
2. Trzymając stopę nad podłogą, pociągnij za pasek i wykorzystaj napięcie, aby pociągnąć palce stopy ku górze. Utrzymaj przez 10–20 sekund i powtórz na drugiej stronie.', NULL, 'free-exercise-db/IT_Band_and_Glute_Stretch/0.jpg', 'free_exercise_db'),
  ('jackknife-sit-up', 'Brzuszek scyzoryk (jackknife)', 'Jackknife Sit-Up', 'motor_coach', 'beginner', array['Siłowe', 'Brzuch'], 'Wzmacnianie mięśni brzucha: leżąc na plecach jednocześnie unoisz wyprostowane nogi i tułów, spotykając się w pozycji scyzoryka. Angażuje górną i dolną partię brzucha.', '1. Połóż się płasko na podłodze (lub macie do ćwiczeń) na plecach z ramionami wyciągniętymi prosto za głowę i nogami także wyprostowanymi. To będzie pozycja startowa.
2. Na wydechu zegnij się w pasie, jednocześnie unosząc nogi i ramiona, aby spotkały się w pozycji scyzoryka. Wskazówka: nogi powinny być wyprostowane i uniesione pod kątem około 35–45 stopni od podłogi, a ramiona wyprostowane i równoległe do nóg. Górna część tułowia powinna oderwać się od podłogi.
3. Robiąc wdech, opuść ramiona i nogi z powrotem do pozycji startowej.
4. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Jackknife_Sit-Up/0.jpg', 'free_exercise_db'),
  ('janda-sit-up', 'Brzuszek Jandy', 'Janda Sit-Up', 'motor_coach', 'beginner', array['Siłowe', 'Brzuch'], 'Szczególny rodzaj brzuszka z silnym napinaniem pośladków i dwugłowych uda. Napinanie tych mięśni wyłącza zginacze bioder, przez co pracuje właściwy mięsień prosty brzucha.', '1. Ustaw ciało na podłodze w podstawowej pozycji brzuszków: kolana pod kątem 90 stopni, stopy płasko na podłodze, ramiona skrzyżowane na klatce piersiowej lub po bokach. To będzie pozycja startowa.
2. Silnie napinając pośladki i dwugłowe uda, wypełnij płuca powietrzem i podczas powolnego (3–6-sekundowego) unoszenia tułowia powoli wydychaj. Wskazówka: ważne jest, aby napinać pośladki i dwugłowe uda, ponieważ wyłącza to zginacze bioder w procesie zwanym inhibicją wzajemną — mięśnie przeciwne do napinanych się rozluźniają.
3. Robiąc wdech, powoli i kontrolowanie wróć do pozycji startowej.
4. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Janda_Sit-Up/0.jpg', 'free_exercise_db'),
  ('jefferson-squats', 'Przysiad Jeffersona', 'Jefferson Squats', 'motor_coach', 'intermediate', array['Siłowe', 'Uda'], 'Przysiad z sztangą trzymaną pionowo przed sobą — jedna ręka z przodu, druga z tyłu. Nietypowe ćwiczenie budujące nogi, pośladki i siłę chwytu.', '1. Połóż sztangę na podłodze.
2. Stań wzdłuż osi sztangi, na środku jej długości.
3. Ugnij się w kolanach, trzymając plecy prosto, i złap przód sztangi prawą ręką. Twoja dłoń powinna być zwrócona do środka (chwyt neutralny), w kierunku lewej strony.
4. Złap tył sztangi lewą ręką. Dłoń powinna być w neutralnym chwycie (dłoń zwrócona w prawo). Wskazówka: upewnij się, że chwyt jest równomierny na sztandze. Twój tułów powinien znajdować się dokładnie w środku sztangi, a odległość między tułowiem a prawą dłonią (która jest z przodu) powinna być taka sama jak między tułowiem a lewą dłonią (która jest z tyłu).
5. Teraz wyprostuj się z ciężarem. Wskazówka: stopy powinny być na szerokość barków, a palce lekko skierowane na zewnątrz.
6. Opuszczaj się w przysiadzie, uginając kolana i trzymając plecy prosto, aż górne uda będą równoległe do podłogi. Wskazówka: trzymaj plecy maksymalnie pionowo względem podłogi, a głowę uniesioną. Pamiętaj też, aby nie dopuścić do przejścia kolan przed palce stóp. Wdychaj podczas tej części ruchu.
7. Teraz wypchnij się z powrotem do pozycji startowej, odpychając się stopami. Wskazówka: trzymaj sztangę wiszącą na wyciągniętych ramionach z lekko ugiętymi, zablokowanymi łokciami. Ramiona służą tylko jako haki — nie wykonuj nimi żadnego unoszenia. Unoszenie wykonuj udami, nie ramionami.', NULL, 'free-exercise-db/Jefferson_Squats/0.jpg', 'free_exercise_db'),
  ('jerk-balance', 'Wyrzut z balansem (jerk balance)', 'Jerk Balance', 'motor_coach', 'intermediate', array['Podnoszenie ciężarów', 'Barki'], 'Ćwiczenie techniczne podnoszenia ciężarów uczące dostatecznie niskiego zejścia w wyruku i korygujące cofanie się podczas ruchu. Po wyrzucie zostajesz w wykroku z ciężarem nad głową.', '1. To ćwiczenie pomaga nauczyć się schodzić wystarczająco nisko podczas wyruku i koryguje tych, którzy cofają się podczas ruchu. Zacznij z sztangą ułożoną na barkach w pozycji wyruku, barkami wysuniętymi do przodu, tułowiem pionowo i stopami lekko rozstawionymi.
2. Rozpocznij ruch jak przy normalnym wyruku: opadnij w kolanach, trzymając tułów pionowo, a następnie gwałtownie wypchnij się w górę, używając rozpędu, a nie ramion, aby unieść ciężar.
3. Utrzymaj tylną stopę w miejscu i używaj jej, aby wypchnąć ciało do przodu w pełny wykrok, wykonując wyrzut ciężaru. Wróć, prostując się z ciężarem nad głową.', NULL, 'free-exercise-db/Jerk_Balance/0.jpg', 'free_exercise_db'),
  ('jerk-dip-squat', 'Podchwyt w wyruku (jerk dip squat)', 'Jerk Dip Squat', 'motor_coach', 'intermediate', array['Podnoszenie ciężarów', 'Uda'], 'Siłowe ćwiczenie podnoszenia ciężarów wzmacniające fazę podchwytu (opadu) wyruku. Krótki, kontrolowany opad w kolanach i energiczny powrót z ciężarem na barkach.', '1. Ten ruch wzmacnia fazę opadu (podchwytu) w wyruku. Zacznij z sztangą ułożoną na barkach w pozycji wyruku, barkami wysuniętymi do przodu, tworząc półkę, a sztangą delikatnie dotykającą gardła. Stopy powinny być bezpośrednio pod biodrami, lekko skierowane na zewnątrz.
2. Trzymając tułów pionowo, opadnij uginając kolana, pozwalając im jechać do przodu i bez cofania bioder. Opad nie powinien być zbyt głęboki. Wróć z ciężarem do pozycji startowej, mocno odpychając się stopami.', NULL, 'free-exercise-db/Jerk_Dip_Squat/0.jpg', 'free_exercise_db'),
  ('jm-press', 'JM Press', 'JM Press', 'motor_coach', 'beginner', array['Siłowe', 'Triceps'], 'Hybryda wąskiego wyciskania sztangi leżąc i francuskiego prostowania tricepsa — cenione ćwiczenie na masywny, silny triceps. Sztanga opuszczana za głowę z „rolowaniem” łokci.', '1. Zacznij ćwiczenie tak samo, jak przy wąskim wyciskaniu sztangi leżąc. Leżysz na ławce płaskiej, trzymając sztangę na wyprostowanych ramionach z łokciami blisko tułowia. Jednak zamiast mieć ramiona prostopadle do tułowia, upewnij się, że sztanga znajduje się dokładnie w linii ponad górną częścią klatki piersiowej. To będzie pozycja startowa.
2. Teraz, zaczynając z pełnego wyprostu, opuszczaj sztangę w dół, jakbyś robił francuskie prostowanie leżąc. Wdychaj powietrze podczas tego ruchu. Gdy osiągniesz punkt pośredni, pozwól sztandze stoczyć się do tyłu o około 2–3 cm, przesuwając ramiona w kierunku nóg, aż staną prostopadle do tułowia. Wskazówka: zachowuj stały kąt w łokciach, gdy przemieszczasz ramiona do przodu.
3. Na wydechu wypchnij sztangę z powrotem w górę, używając tricepsów, jak w wąskim wyciskaniu sztangi leżąc.
4. Teraz wróć do pozycji startowej i zacznij od nowa.
5. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/JM_Press/0.jpg', 'free_exercise_db'),
  ('jogging-treadmill', 'Bieganie na bieżni mechanicznej', 'Jogging, Treadmill', 'motor_coach', 'beginner', array['Cardio', 'Uda'], 'Trening cardio na bieżni mechanicznej — wygodna alternatywa dla biegania w terenie, o mniejszym obciążeniu stawów. Regulujesz prędkość i nachylenie, a programy często szacują spalone kalorie.', '1. Na początku wejdź na bieżnię i wybierz żądaną opcję z menu. Większość bieżni ma tryb ręczny albo możesz wybrać program treningowy. Zazwyczaj można wprowadzić wiek i wagę, aby oszacować liczbę spalonych kalorii podczas ćwiczeń. Nachylenie można regulować, aby zmienić intensywność treningu.
2. Bieżnie oferują wygodę i korzyści sercowo-naczyniowe, a zazwyczaj mniej obciążają stawy niż bieganie na zewnątrz. Osoba ważąca ok. 70 kg spali prawie 250 kcal truchtając przez 30 minut, w porównaniu z ponad 450 kcal przy biegu. Zachowuj prawidłową postawę podczas biegu i trzymaj się uchwytów tylko wtedy, gdy to konieczne, np. przy zsiadaniu lub sprawdzaniu tętna.', NULL, 'free-exercise-db/Jogging_Treadmill/0.jpg', 'free_exercise_db'),
  ('keg-load', 'Ładowanie beczek (keg load)', 'Keg Load', 'motor_coach', 'intermediate', array['Strongman', 'Dolny odcinek pleców'], 'Ćwiczenie strongman: szybkie przenoszenie metalowych beczek i załadunek ich na platformę. Buduje siłę całego ciała, chwytu i wytrzymałość.', '1. Aby załadować beczki, ustaw żądaną liczbę beczek w pewnej odległości od platformy ładunkowej, typowo 9–15 metrów.
2. Zacznij od złapania bliższego uchwytu pierwszej beczki, przechylając ją na bok, aby chwycić przeciwną krawędź dna beczki. Unieś beczkę do klatki piersiowej.
3. Im wyżej możesz trzymać beczkę, tym szybciej powinieneś móc się poruszać do platformy. Opieranie beczki o bark zwykle nie jest dozwolone. Trzymaj beczkę pewnie. Ruszaj na platformę możliwie szybko i załaduj ją, wyprostowując biodra, kolana i kostki, aby unieść ją jak najwyżej.
4. Wróć do pozycji startowej, aby podnieść następną beczkę, i powtarzaj, aż konkurencja zostanie ukończona.', NULL, 'free-exercise-db/Keg_Load/0.jpg', 'free_exercise_db'),
  ('kettlebell-arnold-press', 'Wyciskanie Arnolda z kettlebell', 'Kettlebell Arnold Press', 'motor_coach', 'intermediate', array['Siłowe', 'Barki'], 'Wyciskanie Arnolda z ciężarkiem kettlebell — wyciskasz ciężar nad głowę z jednoczesną rotacją nadgarstka. Kompleksowo angażuje całą obręcz barkową.', '1. Podrzuć kettlebell na bark. Podrzucenie wykonaj prostując nogi i biodra, unosząc kettlebell w kierunku barku. Dłoń powinna być zwrócona do środka.
2. Patrząc prosto przed siebie, wyciśnij kettlebell w górę nad głowę, obracając nadgarstek tak, aby dłoń była zwrócona do przodu na szczycie ruchu.
3. Opuść kettlebell z powrotem do pozycji startowej, z dłonią zwróconą do środka.', NULL, 'free-exercise-db/Kettlebell_Arnold_Press/0.jpg', 'free_exercise_db'),
  ('kettlebell-dead-clean', 'Podrzut kettlebell z podłogi (dead clean)', 'Kettlebell Dead Clean', 'motor_coach', 'intermediate', array['Siłowe', 'Dwugłowe uda'], 'Podnoszenie kettlebell z podłogi na bark w jednym dynamicznym ruchu. Buduje siłę całego ciała i uczy sprawnego podrzucania ciężarka.', '1. Połóż kettlebell między stopami. Aby przyjąć pozycję startową, cofnij biodra i patrz prosto przed siebie.
2. Podrzuć kettlebell na bark. Podrzucenie wykonaj prostując nogi i biodra, unosząc kettlebell w kierunku barku. Nadgarstek powinien się przy tym obracać.
3. Opuść kettlebell, utrzymując napięcie dwugłowych uda — trzymaj plecy proste, a biodra cofnięte.', NULL, 'free-exercise-db/Kettlebell_Dead_Clean/0.jpg', 'free_exercise_db'),
  ('kettlebell-figure-8', 'Kettlebell ósemka (figure 8)', 'Kettlebell Figure 8', 'motor_coach', 'intermediate', array['Siłowe', 'Brzuch'], 'Kettlebell przekładany między nogami w kształcie ósemki. Dynamiczne ćwiczenie na koordynację, chwyt i mięśnie głębokie.', '1. Połóż jeden kettlebell między nogami i przyjmij postawę szerszą niż szerokość barków. Pochyl się, wypychając biodra do tyłu i trzymając plecy płaskie.
2. Podnieś kettlebell i przekaż go do drugiej ręki między nogami. Ręka przyjmująca powinna sięgać od tyłu między nogami. Przekładaj w tę i z powrotem przez kilka powtórzeń.', NULL, 'free-exercise-db/Kettlebell_Figure_8/0.jpg', 'free_exercise_db'),
  ('kettlebell-hang-clean', 'Podrzut kettlebell z pozycji wiszącej (hang clean)', 'Kettlebell Hang Clean', 'motor_coach', 'intermediate', array['Siłowe', 'Dwugłowe uda'], 'Podrzut kettlebell na bark z pozycji zawieszenia między nogami. Dynamiczne ćwiczenie mocy całego ciała.', '1. Połóż kettlebell między stopami. Aby przyjąć pozycję startową, cofnij biodra i patrz prosto przed siebie.
2. Podrzuć kettlebell na bark. Podrzucenie wykonaj prostując nogi i biodra, unosząc kettlebell w kierunku barku. Nadgarstek powinien się przy tym obracać.
3. Opuść kettlebell do pozycji zawieszenia między nogami, utrzymując napięcie dwugłowych uda. Trzymaj głowę uniesioną przez cały czas.', NULL, 'free-exercise-db/Kettlebell_Hang_Clean/0.jpg', 'free_exercise_db'),
  ('kettlebell-one-legged-deadlift', 'Martwy ciąg na jednej nodze z kettlebell', 'Kettlebell One-Legged Deadlift', 'motor_coach', 'intermediate', array['Siłowe', 'Dwugłowe uda'], 'Martwy ciąg na prostych nogach wykonywany na jednej nodze, z kettlebell w przeciwnej lub tej samej ręce. Buduje równowagę, pośladki i dwugłowe uda.', '1. Trzymaj kettlebell za uchwyt w jednej ręce. Stań na jednej nodze, po tej samej stronie, po której trzymasz kettlebell.
2. Trzymając to kolano lekko ugięte, wykonaj martwy ciąg na prostych nogach, zginając się w biodrze i wyciągając wolną nogę za siebie dla równowagi.
3. Kontynuuj opuszczanie kettlebella, aż będziesz równolegle do podłoża, a następnie wróć do pozycji wyprostowanej.', NULL, 'free-exercise-db/Kettlebell_One-Legged_Deadlift/0.jpg', 'free_exercise_db'),
  ('kettlebell-pass-between-the-legs', 'Przekazywanie kettlebell między nogami', 'Kettlebell Pass Between The Legs', 'motor_coach', 'intermediate', array['Siłowe', 'Brzuch'], 'Przekazywanie kettlebell między nogami z ręki do ręki w szerokim rozkroku. Ćwiczenie koordynacyjne angażujące mięśnie głębokie i chwyt.', '1. Połóż jeden kettlebell między nogami i przyjmij komfortową postawę. Pochyl się, wypychając biodra do tyłu i trzymając plecy płaskie.
2. Podnieś kettlebell i przekaż go do drugiej ręki między nogami, w kształcie litery „W”. Przekładaj w tę i z powrotem przez kilka powtórzeń.', NULL, 'free-exercise-db/Kettlebell_Pass_Between_The_Legs/0.jpg', 'free_exercise_db'),
  ('kettlebell-pirate-ships', 'Kettlebell pirate ships (huśtawka nad głowę)', 'Kettlebell Pirate Ships', 'motor_coach', 'beginner', array['Siłowe', 'Barki'], 'Huśtawka kettlebell nad głowę z rotacją tułowia — nazwa pochodzi od bujania się statku pirackiego. Angażuje barki, mięśnie głębokie i chwyt.', '1. W szerokiej postawie trzymaj kettlebell obiema rękami, pozwalając mu zwisać na wysokości pasa z wyprostowanymi ramionami. To będzie pozycja startowa.
2. Rozpocznij ruch obracając się na jedną stronę i huśtając kettlebell na wysokość głowy. Krótko zatrzymaj się na szczycie ruchu.
3. Pozwól ciężarkowi opaść, obracając się na przeciwną stronę, ponownie unosząc kettlebell na wysokość głowy.
4. Powtórz żądaną liczbę powtórzeń.', NULL, 'free-exercise-db/Kettlebell_Pirate_Ships/0.jpg', 'free_exercise_db'),
  ('kettlebell-pistol-squat', 'Pistolet z kettlebell', 'Kettlebell Pistol Squat', 'motor_coach', 'advanced', array['Siłowe', 'Uda'], 'Przysiad na jednej nodze (pistolet) z kettlebell trzymanym przed sobą. Zaawansowane ćwiczenie siły nóg, równowagi i mobilności.', '1. Podnieś kettlebell dwiema rękami, chwytając za „rogi” uchwytu (horns). Unieś jedną nogę nad podłogę i przysiadaj na drugiej.
2. Opuszczaj się, uginając kolano i cofając biodra, trzymając kettlebell uniesiony przed sobą.
3. Przytrzymaj dolną pozycję przez sekundę, a następnie odwróć ruch, odpychając się piętą i trzymając głowę i klatkę piersiową uniesione.
4. Opuść się ponownie i powtórz.', NULL, 'free-exercise-db/Kettlebell_Pistol_Squat/0.jpg', 'free_exercise_db'),
  ('kettlebell-seated-press', 'Wyciskanie kettlebell w siadzie', 'Kettlebell Seated Press', 'motor_coach', 'intermediate', array['Siłowe', 'Barki'], 'Wyciskanie kettlebell nad głowę w siadzie na podłodze z nogami rozstawionymi. Wymusza pracę bez pomocy nóg i angażuje mięśnie głębokie.', '1. Usiądź na podłodze i rozłóż nogi wygodnie na boki.
2. Podrzuć jeden kettlebell na bark.
3. Wyciśnij kettlebell w górę i na zewnątrz, aż ramiona będą całkowicie wyprostowane nad głową. Wróć do pozycji startowej.', NULL, 'free-exercise-db/Kettlebell_Seated_Press/0.jpg', 'free_exercise_db'),
  ('kettlebell-seesaw-press', 'Naprzemienne wyciskanie kettlebell (seesaw press)', 'Kettlebell Seesaw Press', 'motor_coach', 'intermediate', array['Siłowe', 'Barki'], 'Naprzemienne wyciskanie dwóch kettlebelli nad głowę — jak na huśtawce: gdy jedna ręka opuszcza, druga już wyciska. Angażuje barki i mięśnie głębokie.', '1. Podrzuć dwa kettlebelle na barki.
2. Wyciśnij jeden kettlebell.
3. Opuść kettlebell i natychmiast wyciśnij drugi kettlebell. Upewnij się, że wykonujesz tę samą liczbę powtórzeń na obie strony.', NULL, 'free-exercise-db/Kettlebell_Seesaw_Press/0.jpg', 'free_exercise_db'),
  ('kettlebell-sumo-high-pull', 'Sumo high pull z kettlebell', 'Kettlebell Sumo High Pull', 'motor_coach', 'intermediate', array['Siłowe', 'Czworoboczne'], 'Ciągnięcie kettlebell z ziemi do wysokości barków w szerokiej postawie sumo. Dynamiczne ćwiczenie całego ciała angażujące nogi, plecy i barki.', '1. Połóż kettlebell na ziemi między stopami. Ustaw stopy w szerokiej postawie i złap kettlebell dwiema rękami. Cofnij biodra jak najdalej, z kolanami ugiętymi. Trzymaj klatkę piersiową i głowę uniesione. To będzie pozycja startowa.
2. Zacznij od wyprostu bioder i kolan, jednocześnie ciągnąc kettlebell do barków, unosząc łokcie podczas tego ruchu. Odwróć ruch, aby wrócić do pozycji startowej.', NULL, 'free-exercise-db/Kettlebell_Sumo_High_Pull/0.jpg', 'free_exercise_db'),
  ('kettlebell-thruster', 'Thruster z kettlebell', 'Kettlebell Thruster', 'motor_coach', 'intermediate', array['Siłowe', 'Barki'], 'Połączenie przysiadu z wyciskaniem nad głowę: dwa kettlebelle na barkach, przysiad i eksplozywne wyciśnięcie przy prostowaniu. Bardzo wymagające ćwiczenie całego ciała.', '1. Podrzuć dwa kettlebelle na barki. Podrzucenie wykonaj prostując nogi i biodra, ciągnąc kettlebelle w kierunku barków. Obróć nadgarstki podczas tego ruchu. To będzie pozycja startowa.
2. Zacznij przysiad, uginając biodra i kolana, opuszczając biodra między nogi. Utrzymuj wyprostowane, proste plecy, schodząc tak nisko, jak potrafisz.
3. Na dole odwróć kierunek ruchu i wstań z przysiadu, prostując kolana i biodra, odpychając się piętami. Jednocześnie wyciskaj oba kettlebelle nad głowę, prostując ramiona w górę, wykorzystując rozpęd z przysiadu, aby pomóc wypchnąć ciężary.
4. Rozpoczynając kolejne powtórzenie, wróć ciężarami na barki.', NULL, 'free-exercise-db/Kettlebell_Thruster/0.jpg', 'free_exercise_db'),
  ('kettlebell-turkish-get-up-lunge-style', 'Tureckie wstawanie z kettlebell (styl wykroku)', 'Kettlebell Turkish Get-Up (Lunge style)', 'motor_coach', 'intermediate', array['Siłowe', 'Barki'], 'Tureckie wstawanie (Turkish get-up) w wariancie wykroku — sekwencja od leżenia na plecach do stania z kettlebell nad głową, z przejściem przez wykrok. Klasyk siły funkcjonalnej.', '1. Połóż się na plecach na podłodze i wyciśnij kettlebell do pozycji górnej, prostując łokieć. Zegnij kolano po tej samej stronie, po której trzymasz kettlebell.
2. Utrzymując kettlebell zablokowany nad głową przez cały czas, obróć się na przeciwną stronę i użyj niewpracowanej ręki, aby pomóc sobie przejść do przodu do pozycji wykroku. Wolną ręką odepchnij się do siadu, a następnie przejdź na jedno kolano.
3. Patrząc w górę na kettlebell, powoli wstań. Odwróć ruch z powrotem do pozycji startowej i powtórz.', NULL, 'free-exercise-db/Kettlebell_Turkish_Get-Up_Lunge_style/0.jpg', 'free_exercise_db'),
  ('kettlebell-turkish-get-up-squat-style', 'Tureckie wstawanie z kettlebell (styl przysiadu)', 'Kettlebell Turkish Get-Up (Squat style)', 'motor_coach', 'intermediate', array['Siłowe', 'Barki'], 'Tureckie wstawanie w wariancie przysiadu: z leżenia do stania z ciężarem nad głową, wstając przez przysiad zamiast wykroku. Wzmacnia całe ciało i stabilizację barku.', '1. Połóż się na plecach na podłodze i wyciśnij kettlebell do pozycji górnej, prostując łokieć. Zegnij kolano po tej samej stronie, po której trzymasz kettlebell.
2. Utrzymując kettlebell zablokowany nad głową przez cały czas, obróć się na przeciwną stronę i użyj niewpracowanej ręki, aby pomóc sobie przejść do przodu do pozycji wykroku.
3. Wolną ręką odepchnij się do siadu, a następnie przejdź na stopy. Patrząc w górę na kettlebell, powoli wstań. Odwróć ruch z powrotem do pozycji startowej i powtórz.', NULL, 'free-exercise-db/Kettlebell_Turkish_Get-Up_Squat_style/0.jpg', 'free_exercise_db'),
  ('kettlebell-windmill', 'Młyn z kettlebell', 'Kettlebell Windmill', 'motor_coach', 'intermediate', array['Siłowe', 'Brzuch'], 'Młyn (windmill): wyciskasz kettlebell nad głowę, a następnie pochylasz się w bok, dotykając wolną ręką podłogi. Wzmacnia mięśnie głębokie, pośladki i mobilność bioder.', '1. Połóż kettlebell przed stopą prowadzącą i podrzuć go nad głowę przeciwną ręką. Podrzucenie wykonaj prostując nogi i biodra, ciągnąc kettlebell w kierunku barku. Obróć nadgarstek podczas tego ruchu, tak aby dłoń była zwrócona do przodu. Wyciśnij go nad głowę, prostując łokieć.
2. Utrzymując kettlebell zablokowany nad głową przez cały czas, wypchnij biodra w kierunku strony kettlebella nad głową. Skieruj stopy pod kątem 45 stopni od ramienia z uniesionym kettlebellem. Zginając się w biodrze na jedną stronę i wypychając biodra, powoli pochyl się, aż dotkniesz podłogi wolną ręką. Trzymaj wzrok na kettlebellu nad głową przez cały czas.
3. Zatrzymaj się na sekundę po dotknięciu podłogi i odwróć ruch z powrotem do pozycji startowej.', NULL, 'free-exercise-db/Kettlebell_Windmill/0.jpg', 'free_exercise_db'),
  ('kipping-muscle-up', 'Muscle up z wymachem (na kółkach)', 'Kipping Muscle Up', 'motor_coach', 'intermediate', array['Siłowe', 'Najszersze grzbietu'], 'Muscle up na kółkach gimnastycznych z pomocą wymachu nóg (kipping). Z wymachu ciągniesz się w górę i przechodzisz w podpór na wyprostowanych ramionach.', '1. Złap kółka chwytem false grip, podstawą dłoni na wierzchu kółek.
2. Zacznij od ruchu wymachując nogami lekko do tyłu.
3. Przeciwstaw się temu ruchowi, wymachując nogami do przodu i w górę, cofając brodę i klatkę piersiową, ciągnąc się w górę oboma ramionami. Gdy osiągniesz szczyt podciągnięcia, pociągnij kółka do pach, wysuwając barki do przodu i pozwalając łokciom jechać prosto do tyłu za siebie. To ustawi cię w odpowiedniej pozycji, aby przejść do fazy dip (prostowania ramion).
4. Utrzymując kontrolę i stabilność, wyprostuj ramiona w łokciach, aby ukończyć ruch.
5. Schodząc na ziemię, zachowaj ostrożność.', NULL, 'free-exercise-db/Kipping_Muscle_Up/0.jpg', 'free_exercise_db'),
  ('knee-across-the-body', 'Kolano przez ciało', 'Knee Across The Body', 'motor_coach', 'beginner', array['Rozciąganie', 'Pośladki'], 'Rozciąganie dolnego odcinka pleców i pośladków w leżeniu na plecach. Zgięte kolano przenosisz przez linię ciała na drugą stronę i dociskasz je dłonią w dół.', '1. Połóż się na podłodze z prawą nogą wyprostowaną. Zegnij lewą nogę i opuść ją przez linię ciała na drugą stronę, dociskając kolano w dół, w kierunku podłogi, prawą dłonią. (Kolano nie musi dotykać podłogi, jeśli jesteś mało elastyczny.)
2. Połóż lewą rękę wygodnie obok siebie i skręć głowę w lewo. Wyobraź sobie, że do ogonka (kości ogonowej) przywiązany jest ciężarek. Pozwól, aby kość ogonowa opadała w dół, w kierunku podłogi, podczas gdy klatka piersiowa sięga w przeciwnym kierunku, rozciągając dolny odcinek pleców. Zmień strony.', NULL, 'free-exercise-db/Knee_Across_The_Body/0.jpg', 'free_exercise_db'),
  ('knee-circles', 'Krążenia kolan', 'Knee Circles', 'motor_coach', 'beginner', array['Rozciąganie', 'Łydki'], 'Prosta mobilizacja kolan w pozycji stojącej — kolana wykonują okrężne ruchy. Dobre jako rozgrzewka przed treningiem nóg.', '1. Stań ze złączonymi nogami i dłońmi przy talii.
2. Teraz wykonuj kolana ruchem okrężnym, oddychając normalnie.
3. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Knee_Circles/0.jpg', 'free_exercise_db'),
  ('knee-hip-raise-on-parallel-bars', 'Unoszenie kolan/bioder na poręczy (kapitan)', 'Knee/Hip Raise On Parallel Bars', 'motor_coach', 'beginner', array['Siłowe', 'Brzuch'], 'Wzmacnianie brzucha na poręczy z oparciami na przedramiona: unoisz ugięte kolana lub proste nogi w kierunku klatki piersiowej. Mocno angażuje dolną partię brzucha.', '1. Ustaw ciało na stanowisku do unoszenia nóg tak, aby przedramiona spoczywały na podporach obok tułowia, a dłonie trzymały uchwyty. Twoje ramiona będą zgięte pod kątem 90 stopni.
2. Tułów powinien być wyprostowany, z odcinkiem lędźwiowym dociśniętym do podparcia maszyny, a nogi wyprostowane i skierowane w dół. To będzie pozycja startowa.
3. Teraz, robiąc wydech, unoś nogi w górę, trzymając je wyprostowane. Kontynuuj ten ruch, aż nogi znajdą się mniej więcej równolegle do podłogi, a następnie utrzymaj spięcie przez sekundę. Wskazówka: nie wykorzystuj żadnego rozpędu ani wymachu podczas tego ćwiczenia.
4. Powoli wróć do pozycji startowej, robiąc wdech.
5. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Knee_Hip_Raise_On_Parallel_Bars/0.jpg', 'free_exercise_db'),
  ('knee-tuck-jump', 'Wyskok z podciągnięciem kolan', 'Knee Tuck Jump', 'motor_coach', 'beginner', array['Plyometryka', 'Dwugłowe uda'], 'Plyometryczny wyskok z jednoczesnym podciąganiem kolan do klatki piersiowej. Rozwija moc nóg i koordynację.', '1. Zacznij w komfortowej pozycji stojącej z lekko ugiętymi kolanami. Trzymaj dłonie przed sobą, grzbietami w dół, z czubkami palców złączonymi na wysokości klatki piersiowej. To będzie pozycja startowa.
2. Szybko opadnij do półprzysiadu i natychmiast wybij się w górę. Podciągaj kolana w kierunku klatki piersiowej, próbując dotknąć ich dłońmi.
3. Wyskocz jak najwyżej, unosząc kolana w górę, a następnie zapewnij dobre lądowanie ponownie prostując nogi i amortyzując uderzenie poprzez ponowne ugięcie kolan.', NULL, 'free-exercise-db/Knee_Tuck_Jump/0.jpg', 'free_exercise_db'),
  ('kneeling-arm-drill', 'Ćwiczenie pracy ramion w klęku', 'Kneeling Arm Drill', 'motor_coach', 'beginner', array['Plyometryka', 'Barki'], 'Ćwiczenie biegowe w klęku uczące efektywnej pracy ramion podczas biegu. Blokujesz ramiona wahadłowymi ruchami, progresując od truchtu do sprintu.', '1. To ćwiczenie pomaga zwiększyć efektywność pracy ramion podczas biegu. Zacznij w klęku: lewa stopa z przodu, prawe kolano na ziemi. Wywieraj nacisk na przednią piętę, aby utrzymać aktywację pośladków i dwugłowych uda.
2. Zacznij od blokowania ramion długimi, wahadłowymi ruchami. Zmniejszaj kąt w ramionach, blokując je jak podczas truchtu, progresując do biegu, a w końcu do sprintu.
3. Gdy tylko dłonie miną biodro, przyspiesz je do przodu podczas ruchu sprinterskiego, aby poruszały się możliwie jak najszybciej.
4. Zmień kolano i powtórz.', NULL, 'free-exercise-db/Kneeling_Arm_Drill/0.jpg', 'free_exercise_db'),
  ('kneeling-cable-crunch-with-alternating-oblique-twists', 'Skłon w klęku na wyciągu z naprzemiennymi skrętami skośnych brzucha', 'Kneeling Cable Crunch With Alternating Oblique Twists', 'motor_coach', 'beginner', array['Siłowe', 'Brzuch'], 'Skłony tułowia w klęku na wyciągu górnym z liną — z dodatkowym naprzemiennym skrętem łokcia w kierunku przeciwnego kolana, mocniej angażującym mięśnie skośne brzucha.', '1. Podłącz linę do górnego bloku i połóż matę na podłodze przed nim.
2. Złap linę obiema rękami i uklęknij około 60 cm za wieżą.
3. Ustaw linę za głową, z dłońmi przy uszach.
4. Trzymając dłonie w tym samym miejscu, napnij brzuch i ciągnij linę w dół ruchem skłonowym, aż łokcie osiągną kolana.
5. Krótko zatrzymaj się na dole i wznosz się powoli i kontrolowanie, aż osiągniesz pozycję startową.
6. Powtórz ten sam ruch w dół, aż znajdziesz się w połowie drogi, po czym zacznij obracać jeden z łokci w kierunku przeciwnego kolana.
7. Ponownie krótko zatrzymaj się na dole i wznosz się powoli i kontrolowanie, aż osiągniesz pozycję startową.
8. Powtórz ten sam ruch co poprzednio, ale tym razem prowadząc drugi łokieć w kierunku przeciwnego kolana.
9. Kontynuuj tę serię ruchów do upadku mięśniowego.', NULL, 'free-exercise-db/Kneeling_Cable_Crunch_With_Alternating_Oblique_Twists/0.jpg', 'free_exercise_db'),
  ('kneeling-cable-triceps-extension', 'Prostowanie ramion na wyciągu w klęku', 'Kneeling Cable Triceps Extension', 'motor_coach', 'intermediate', array['Siłowe', 'Triceps'], 'Izolacja tricepsa na wyciągu górnym w klęku, z łokciami opartymi o ławkę. Prostujesz ramiona półkolistym ruchem, aż będą równoległe do podłogi.', '1. Ustaw ławkę bokiem przed maszyną z górnym blokiem.
2. Trzymaj prosty uchwyt nad głową, z dłońmi około 15 cm od siebie, chwytem nachwytem.
3. Odwróć się plecami do maszyny i uklęknij.
4. Połóż głowę i tył ramion na ławce. Łokcie powinny być zgięte, z przedramionami skierowanymi w stronę górnego bloku. To będzie pozycja startowa.
5. Trzymając ramiona blisko głowy przez cały czas i łokcie przy głowie, wypychaj drążek półkolistym ruchem, aż łokcie zostaną zablokowane, a ramiona będą równoległe do podłogi. Mocno napnij triceps i utrzymaj tę pozycję przez sekundę. Wykonuj wydech podczas tego ruchu.
6. Powoli wróć do pozycji startowej, robiąc wdech.
7. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Kneeling_Cable_Triceps_Extension/0.jpg', 'free_exercise_db'),
  ('kneeling-forearm-stretch', 'Rozciąganie przedramion w klęku', 'Kneeling Forearm Stretch', 'motor_coach', 'beginner', array['Rozciąganie', 'Przedramiona'], 'Rozciąganie nadgarstków i przedramion: w klęku kładziesz dłonie płasko na macie z palcami skierowanymi ku kolanom i delikatnie się odchylasz.', '1. Zacznij od uklęknięcia na macie z dłońmi płasko na podłodze i palcami skierowanymi do tyłu, w stronę kolan.
2. Powoli odchylaj się do tyłu, trzymając dłonie płasko na podłodze, aż poczujesz rozciąganie w nadgarstkach i przedramionach. Utrzymaj przez 20–30 sekund.', NULL, 'free-exercise-db/Kneeling_Forearm_Stretch/0.jpg', 'free_exercise_db'),
  ('kneeling-high-pulley-row', 'Wiosłowanie na wyciągu górnym w klęku', 'Kneeling High Pulley Row', 'motor_coach', 'beginner', array['Siłowe', 'Najszersze grzbietu'], 'Wiosłowanie liną z górnego bloku w pozycji klęku. Ciągniesz linę do górnej części klatki piersiowej z rozstawionymi łokciami, ściągając łopatki.', '1. Dobierz odpowiedni ciężar na bloku znajdującym się nad twoją głową. Podłącz linę do linki i uklęknij w odległości około metra, trzymając linę z przodu z oboma ramionami wyprostowanymi. To będzie pozycja startowa.
2. Rozpocznij ruch zginając łokcie i w pełni ściągając łopatki, ciągnąc linę w kierunku górnej części klatki piersiowej z łokciami rozstawionymi na boki.
3. Po krótkiej pauzie powoli wróć do pozycji startowej.', NULL, 'free-exercise-db/Kneeling_High_Pulley_Row/0.jpg', 'free_exercise_db'),
  ('kneeling-hip-flexor', 'Rozciąganie zginaczy bioder w klęku', 'Kneeling Hip Flexor', 'motor_coach', 'beginner', array['Rozciąganie', 'Uda'], 'Klasyczne rozciąganie zginaczy biodra w klęku: jedno kolano na ziemi, druga noga z przodu ugięta. Przenosisz ciężar ciała do przodu, aż poczujesz rozciąganie w biodrze.', '1. Uklęknij na macie i unieś prawe kolano tak, aby podeszwa stopy była na podłodze, a lewą nogę wyciągnij za siebie tak, aby grzbiet stopy był na podłodze.
2. Przenieś ciężar ciała do przodu, aż poczujesz rozciąganie w biodrze. Utrzymaj przez 15 sekund, a następnie powtórz na drugą stronę.', NULL, 'free-exercise-db/Kneeling_Hip_Flexor/0.jpg', 'free_exercise_db'),
  ('kneeling-jump-squat', 'Wyskok z przysiadu z klęku', 'Kneeling Jump Squat', 'motor_coach', 'advanced', array['Podnoszenie ciężarów', 'Pośladki'], 'Eksplozywne ćwiczenie plyometryczne: z pozycji klęku z sztangą na barkach wybijasz biodrami w górę, lądując na stopach, i kończysz przysiadem do stania.', '1. Zacznij w klęku na podłodze z sztangą ułożoną na tylnych aktonach barków albo użyj masy własnego ciała. Można to robić w klatce do przysiadów, aby łatwiej zdjąć sztangę ze stojaków.
2. Cofnij biodra do tyłu, aż pośladki dotkną stóp, trzymając głowę i klatkę piersiową uniesione.
3. Wybij w górę biodrami, generując wystarczającą moc, aby wylądować stopami płasko na podłodze.
4. Kontynuuj ruch przysiadu, odpychając się piętami i prostując kolana, aby dojść do pozycji stojącej.', NULL, 'free-exercise-db/Kneeling_Jump_Squat/0.jpg', 'free_exercise_db'),
  ('kneeling-single-arm-high-pulley-row', 'Wiosłowanie jednorącz na wyciągu górnym w klęku', 'Kneeling Single-Arm High Pulley Row', 'motor_coach', 'beginner', array['Siłowe', 'Najszersze grzbietu'], 'Jednorączna wersja wiosłowania z górnego bloku w klęku. Ciągniesz uchwyt do tułowia z rotacją nadgarstka, ściągając łopatkę.', '1. Podłącz pojedynczy uchwyt do górnego bloku i dobierz ciężar.
2. Uklęknij przed wieżą wyciągu, chwytając linkę jedną ręką z wyprostowanym ramieniem. To będzie pozycja startowa.
3. Startując z dłonią zwróconą do przodu, ciągnij ciężar w dół, w kierunku tułowia, zginając łokieć i ściągając łopatkę. Podczas tego ruchu obróć nadgarstek tak, aby po zakończeniu ruchu dłoń była zwrócona ku tobie.
4. Po krótkiej pauzie wróć do pozycji startowej.', NULL, 'free-exercise-db/Kneeling_Single-Arm_High_Pulley_Row/0.jpg', 'free_exercise_db'),
  ('kneeling-squat', 'Przysiad w klęku', 'Kneeling Squat', 'motor_coach', 'intermediate', array['Trójbój', 'Pośladki'], 'Przysiad wykonywany z klęku, ze sztangą na barkach. Izoluje pracę pośladków i dwugłowych uda bez udziału czworogłowych.', '1. Ustaw sztangę na odpowiedniej wysokości w stojaku. Uklęknij za sztangą; korzystnie może być położyć matę, aby podłożyć kolana. Podsuń się pod sztangę, układając ją na tylnych aktonach barków. Łopatki powinny być ściągnięte, a sztanga ciasno przylegać do pleców. Zdejmij ciężar ze stojaków.
2. Patrząc przed siebie, cofaj biodra do tyłu, aż dotkniesz łydek.
3. Odwróć ruch, wracając tułowiem do pozycji pionowej.', NULL, 'free-exercise-db/Kneeling_Squat/0.jpg', 'free_exercise_db'),
  ('landmine-180s', 'Obroty tułowia 180 stopni ze sztangą landmine', 'Landmine 180''s', 'motor_coach', 'beginner', array['Siłowe', 'Brzuch'], 'Rotacyjne ćwiczenie ze sztangą ustawioną w landmine (lub w rogu): przenosisz ciężar szerokim łukiem z jednej strony na drugą, obracając tułów i biodra. Buduje moc rotacyjną mięśni głębokich.', '1. Ustaw sztangę w landmine lub pewnie zakotwicz ją w rogu. Załaduj sztangę odpowiednim ciężarem.
2. Podnieś sztangę z podłogi, prowadząc ją na wysokość barków obiema rękami z wyprostowanymi ramionami przed sobą. Przyjmij szeroką postawę. To będzie pozycja startowa.
3. Wykonuj ruch obracając tułów i biodra, gdy machasz ciężarem aż do jednej strony. Trzymaj ramiona wyprostowane przez całe ćwiczenie.
4. Odwróć ruch, przenosząc ciężar szerokim łukiem na przeciwną stronę.
5. Kontynuuj naprzemienny ruch, aż seria zostanie ukończona.', NULL, 'free-exercise-db/Landmine_180s/0.jpg', 'free_exercise_db')
on conflict (slug) do nothing;

insert into public.exercises
  (slug, name, name_en, persona_type, level, categories, short_description, detail_full, common_mistakes, photo_path, source)
values
  ('landmine-linear-jammer', 'Jammer na sztandze landmine', 'Landmine Linear Jammer', 'motor_coach', 'intermediate', array['Siłowe', 'Barki'], 'Eksplozywne wyciskanie sztangi z pozycji przysiadu na landmine. Siłowe wypchnięcie ciężaru w górę z pełnym wyprostem bioder, kolan i łokci — ćwiczenie mocy całego ciała.', '1. Ustaw sztangę w landmine lub, jeśli go nie masz, pewnie zakotwicz ją w rogu. Załaduj sztangę odpowiednim ciężarem i zamontuj uchwyt na sztandze.
2. Podnieś sztangę z podłogi, doprowadzając uchwyty do barków. To będzie pozycja startowa.
3. W sportowej postawie opuść się w przysiad, uginając biodra i cofając je do tyłu, trzymając ramiona ugięte.
4. Odwróć ruch, mocno prostując biodra, kolana i kostki, jednocześnie prostując łokcie, aż ramiona będą wyprostowane. Ten ruch powinien być wykonywany eksplozywnie, wychodząc z przysiadu do pełnego wyprostu z maksymalną mocą.
5. Wróć do pozycji startowej.', NULL, 'free-exercise-db/Landmine_Linear_Jammer/0.jpg', 'free_exercise_db'),
  ('lateral-bound', 'Skoki boczne (lateral bound)', 'Lateral Bound', 'motor_coach', 'beginner', array['Plyometryka', 'Przywodziciele'], 'Plyometryczne odbicia w bok z nogi na nogę. Rozwijają siłę boczną nóg, stabilizację bioder i zdolność amortyzacji lądowań.', '1. Przyjmij pozycję półprzysiadu, zwrócony 90 stopni względem kierunku ruchu. To będzie pozycja startowa.
2. Pozwól nodze prowadzącej wykonać niewielki ruch przeciwny (do środka), gdy przenosisz ciężar na zewnętrzną nogę.
3. Natychmiast odepchnij się i wyprostuj nogę, próbując odbić się w bok możliwie jak najdalej.
4. Po wylądowaniu natychmiast odepchnij się w przeciwnym kierunku, wracając do pierwotnej pozycji startowej.
5. Kontynuuj ruch w obie strony przez kilka powtórzeń.', NULL, 'free-exercise-db/Lateral_Bound/0.jpg', 'free_exercise_db'),
  ('lateral-box-jump', 'Wskoki na skrzynię bokiem', 'Lateral Box Jump', 'motor_coach', 'beginner', array['Plyometryka', 'Przywodziciele'], 'Boczny wskok plyometryczny na niską skrzynię. Rozwija moc wybicia nóg i precyzję lądowania.', '1. Przyjmij komfortową pozycję stojącą, z niską skrzynią ustawioną obok ciebie. To będzie pozycja startowa.
2. Szybko opadnij do półprzysiadu, aby uruchomić refleks rozciągnięcia, i natychmiast zmień kierunek ruchu, wyskakując w górę i na bok.
3. Unoś kolana wystarczająco wysoko, aby stopy miały dobry prześwit nad skrzynią.
4. Wyląduj na środku skrzyni, amortyzując uderzenie nogami.
5. Ostrożnie wyskocz w dół na drugą stronę skrzyni i kontynuuj ruch w obie strony przez kilka powtórzeń.', NULL, 'free-exercise-db/Lateral_Box_Jump/0.jpg', 'free_exercise_db'),
  ('lateral-cone-hops', 'Przeskoki boczne przez pachołki', 'Lateral Cone Hops', 'motor_coach', 'beginner', array['Plyometryka', 'Przywodziciele'], 'Seria bocznych przeskoków obunóż przez rząd pachołków. Rozwija zwinność, moc nóg i szybkie odbicia w bok.', '1. Ustaw kilka pachołków w rzędzie, w odstępach co kilkadziesiąt centymetrów.
2. Stań obok końca rzędu pachołków, zwrócony 90 stopni do kierunku ruchu. To będzie pozycja startowa.
3. Rozpocznij wyskok od opadu w kolanach, aby uruchomić refleks rozciągnięcia, i natychmiast zmień kierunek, odpychając się od podłoża, wyskakując w górę i w bok nad pachołkiem.
4. Amortyzuj uderzenie nogami przy lądowaniu i odbij się do następnego wyskoku, kontynuując wzdłuż rzędu pachołków.', NULL, 'free-exercise-db/Lateral_Cone_Hops/0.jpg', 'free_exercise_db'),
  ('lateral-raise-with-bands', 'Wznosy ramion na boki z gumą', 'Lateral Raise - With Bands', 'motor_coach', 'beginner', array['Siłowe', 'Barki'], 'Unoszenie ramion w bok stojąc na gumie oporowej — izolacja bocznych aktonów barków. Ruch prowadzisz do wysokości barków, z lekkim ugięciem łokci.', '1. Aby rozpocząć, stań na gumie do ćwiczeń tak, aby napięcie zaczynało się przy wyprostowanych ramionach. Chwyć uchwyty chwytem nachwytem (dłonie zwrócone do ud) nieco wężej niż szerokość barków. Uchwyty powinny spoczywać na bokach ud. Ramiona powinny być wyprostowane z lekkim ugięciem w łokciach, a plecy proste. To będzie pozycja startowa.
2. Użyj bocznych aktonów barków, aby uniósć uchwyty w boki na wydechu. Kontynuuj unoszenie uchwytów, aż znajdą się nieco powyżej poziomu ramion. Wskazówka: unosząc uchwyty, lekko przechyl dłoń, jakbyś przelewał wodę, i trzymaj ramiona wyprostowane. Trzymaj też tułów nieruchomo i zatrzymaj się na sekundę na szczycie ruchu.
3. Opuść uchwyty powoli z powrotem do pozycji startowej. Robiąc wdech podczas tej części ruchu.
4. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Lateral_Raise_-_With_Bands/0.jpg', 'free_exercise_db'),
  ('latissimus-dorsi-smr', 'Rolowanie mięśnia najszerszego grzbietu (SMR)', 'Latissimus Dorsi-SMR', 'motor_coach', 'beginner', array['Rozciąganie', 'Najszersze grzbietu'], 'Automasaż wałkiem mięśnia najszerszego grzbietu (plecy pod pachą). Leżąc na podłodze obciążasz rolę i zatrzymujesz się na miejscach napięcia.', '1. Leżąc na podłodze, umieść wałek pod plecami, z boku, tuż za pachą. To będzie pozycja startowa.
2. Trzymaj rękę rozciąganej strony za sobą i z boku, przenosząc ciężar ciała na najszerszy mięsień grzbietu, z górną częścią ciała oderwaną od ziemi. Utrzymaj przez 10–30 sekund i zmień strony.', NULL, 'free-exercise-db/Latissimus_Dorsi-SMR/0.jpg', 'free_exercise_db'),
  ('leg-extensions', 'Prostowanie nóg na maszynie', 'Leg Extensions', 'motor_coach', 'beginner', array['Siłowe', 'Uda'], 'Izolacja mięśnia czworogłowego uda na maszynie do prostowania nóg. Wyprostowujesz nogi pod wałkiem, napinając czworogłówki, i kontrolowanie opuszczasz ciężar.', '1. Do tego ćwiczenia potrzebujesz maszyny do prostowania nóg. Najpierw dobierz ciężar, usiądź na maszynie z nogami pod wałkiem (palce skierowane do przodu) i dłońmi trzymającymi uchwyty po bokach. To będzie pozycja startowa. Wskazówka: musisz wyregulować wałek tak, aby spoczywał na górnej części łydki (tuż nad stopami). Upewnij się też, że twoje nogi tworzą kąt 90 stopni między goleniem a udem. Jeśli kąt jest mniejszy niż 90 stopni, oznacza to, że kolano wysunięte jest przed palce, co tworzy nadmierne obciążenie stawu kolanowego. Jeśli maszyna jest tak zaprojektowana, poszukaj innej maszyny albo po prostu upewnij się, że podczas wykonywania ćwiczenia przestajesz schodzić, gdy osiągniesz kąt 90 stopni.
2. Używając mięśni czworogłowych uda, wyprostuj nogi do maksimum na wydechu. Upewnij się, że reszta ciała pozostaje nieruchomo na siedzisku. Zatrzymaj się na sekundę w pozycji spięcia.
3. Powoli opuść ciężar z powrotem do pozycji początkowej, robiąc wdech, dbając o to, by nie zejść poniżej limitu kąta 90 stopni.
4. Powtórz zalecaną liczbę razy.', NULL, 'free-exercise-db/Leg_Extensions/0.jpg', 'free_exercise_db'),
  ('leg-lift', 'Unoszenie nogi w tył na stojąco', 'Leg Lift', 'motor_coach', 'beginner', array['Siłowe', 'Pośladki'], 'Izolacja pośladka i dwugłowego uda: stojąc i trzymając się stabilnego oparcia, unoisisz jedną nogę w tył jak w uginaniu nóg, ale na stojąco.', '1. Stojąc wyprostowany ze stopami złączonymi, na szerokość około barków, złap się stabilnego oparcia, takiego jak boki stojaka do przysiadów czy oparcie krzesła, aby się podeprzeć i utrzymać równowagę.
2. Z obciążeniem na kostce lub bez niego unieś jedną nogę za siebie, jakbyś wykonywał uginanie nóg, ale na stojąco, trzymając drugą nogę wyprostowaną. Wykonuj wydech podczas tego ruchu.
3. Powoli opuść uniesioną nogę z powrotem na podłogę, robiąc wdech.
4. Powtórz zalecaną liczbę powtórzeń.
5. Powtórz ruch drugą nogą.', NULL, 'free-exercise-db/Leg_Lift/0.jpg', 'free_exercise_db'),
  ('leg-over-floor-press', 'Wyciskanie kettlebell leżąc na podłodze z nogą przerzuconą przez ciało', 'Leg-Over Floor Press', 'motor_coach', 'intermediate', array['Siłowe', 'Klatka piersiowa'], 'Jednorączne wyciskanie kettlebell w leżeniu na podłodze, z nogą strony roboczej przerzuconą przez drugą. Podłoga ogranicza zakres ruchu i chroni bark.', '1. Połóż się na podłodze z jednym kettlebellem opartym o klatkę piersiową, trzymając go za uchwyt. Wyprostuj nogę strony pracującej ponad nogą strony niewpracowanej. Wolne ramię może być wyciągnięte w bok dla podparcia.
2. Wyciśnij kettlebell w górę, do pozycji z zablokowanym łokciem.
3. Opuść ciężar, aż łokieć dotknie podłogi, trzymając kettlebell nad łokciem. Powtórz żądaną liczbę powtórzeń.', NULL, 'free-exercise-db/Leg-Over_Floor_Press/0.jpg', 'free_exercise_db'),
  ('leg-press', 'Wypychanie na suwnicy (leg press)', 'Leg Press', 'motor_coach', 'beginner', array['Siłowe', 'Uda'], 'Podstawowe ćwiczenie nóg na maszynie: wypychasz platformę z obciążeniem stopami, uginając i prostując kolana. Angażuje czworogłowe, pośladki i dwugłowe uda.', '1. Korzystając z maszyny do wypychania, usiądź na niej i połóż nogi na platformie bezpośrednio przed sobą w średnim rozstawie (szerokość barków). (Uwaga: na potrzeby tego opisu używamy średniego rozstawu opisanego powyżej, który celuje w ogólny rozwój; jednak możesz wybrać dowolny z trzech rozstawów opisanych w sekcji o ułożeniu stóp).
2. Zwolnij zabezpieczenia trzymające obciążoną platformę i wypchnij platformę w górę aż do pełnego wyprostu nóg przed sobą. Wskazówka: upewnij się, że nie blokujesz kolan na sztywno. Twój tułów i nogi powinny tworzyć idealny kąt 90 stopni. To będzie pozycja startowa.
3. Robiąc wdech, powoli opuszczaj platformę, aż górna i dolna część nóg utworzą kąt 90 stopni.
4. Odpychając się głównie piętami i używając mięśni czworogłowych, wróć do pozycji startowej na wydechu.
5. Powtórz zalecaną liczbę powtórzeń i pamiętaj, aby po zakończeniu prawidłowo zamknąć sworznie zabezpieczające. Nie chcesz, aby platforma spadła na ciebie w pełni obciążona.', NULL, 'free-exercise-db/Leg_Press/0.jpg', 'free_exercise_db'),
  ('leg-pull-in', 'Przyciąganie kolan do klatki w siadzie podpartym', 'Leg Pull-In', 'motor_coach', 'beginner', array['Siłowe', 'Brzuch'], 'Wzmacnianie brzucha w siadzie podpartym: przyciągasz ugięte kolana w kierunku tułowia, napinając mięśnie brzucha, i wracasz do pozycji wyjściowej.', '1. Połóż się na macie do ćwiczeń z nogami wyprostowanymi i dłońmi położonymi obok ciała grzbietem w dół lub podwiniętymi pod pośladki. Wskazówka: moją preferencją są dłonie obok ciała. To będzie pozycja startowa.
2. Zegnij kolana i przyciągnij górne uda w kierunku środka ciała, robiąc wydech. Kontynuuj ruch, aż kolana znajdą się mniej więcej na wysokości klatki piersiowej. Napnij mięśnie brzucha podczas wykonywania tego ruchu i utrzymaj spięcie przez sekundę na szczycie. Wskazówka: podczas wykonywania ruchu dolne części nóg (łydki) powinny zawsze pozostać równoległe do podłogi.
3. Wróć do pozycji startowej, robiąc wdech.
4. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Leg_Pull-In/0.jpg', 'free_exercise_db'),
  ('leg-up-hamstring-stretch', 'Rozciąganie dwugłowych uda z nogą w górze', 'Leg-Up Hamstring Stretch', 'motor_coach', 'beginner', array['Rozciąganie', 'Dwugłowe uda'], 'Rozciąganie dwugłowych uda w leżeniu na plecach: jedna noga stabilizuje na podłodze, drugą wyprostowaną przyciągasz w kierunku twarzy.', '1. Połóż się płasko na plecach, zegnij jedno kolano i postaw tę stopę płasko na podłodze, aby ustabilizować kręgosłup.
2. Wyprostuj drugą nogę w górę. Jeśli jesteś mało elastyczny, nie uda ci się jej całkiem wyprostować — to w porządku. Prostuj kolano tak, aby podeszwa uniesionej stopy była skierowana ku sufitowi (lub tak blisko, jak się da).
3. Powoli wyprostuj nogi tak bardzo, jak to możliwe, a następnie pociągnij nogę w kierunku nosa. Zmień strony.', NULL, 'free-exercise-db/Leg-Up_Hamstring_Stretch/0.jpg', 'free_exercise_db'),
  ('leverage-chest-press', 'Wyciskanie na maszynie leverage (klatka)', 'Leverage Chest Press', 'motor_coach', 'beginner', array['Siłowe', 'Klatka piersiowa'], 'Wyciskanie na maszynie dźwigniowej ukierunkowane na klatkę piersiową. Wypychasz uchwyty do przodu, prostując łokcie, i kontrolowanie wracasz, utrzymując napięcie mięśni.', '1. Załaduj odpowiedni ciężar na sworznie i wyreguluj siedzisko do swojego wzrostu. Uchwyty powinny znajdować się przy dolnej lub środkowej części mięśni piersiowych na początku ruchu.
2. Klatka piersiowa i głowa powinny być uniesione, a łopatki ściągnięte. To będzie pozycja startowa.
3. Wypchnij uchwyty do przodu, prostując łokcie.
4. Po krótkiej pauzie na szczycie wróć ciężarem tuż nad pozycję startową, utrzymując napięcie mięśni — nie odkładaj ciężaru na zderzaki, dopóki seria nie zostanie ukończona.', NULL, 'free-exercise-db/Leverage_Chest_Press/0.jpg', 'free_exercise_db'),
  ('leverage-deadlift', 'Martwy ciąg na maszynie leverage', 'Leverage Deadlift', 'motor_coach', 'beginner', array['Siłowe', 'Uda'], 'Martwy ciąg na maszynie dźwigniowej — bezpieczniejsza wersja klasycznego martwego ciągu z prowadzoną trajektorią ruchu. Podnosisz ciężar z prostymi plecami i uniesioną klatką.', '1. Załaduj sworznie odpowiednim ciężarem. Ustaw się dokładnie między uchwytami. Złap dolne uchwyty komfortowym chwytem, a następnie obniż biodra, robiąc wdech. Patrz przed siebie z głową uniesioną i klatką piersiową wypiętą. To będzie pozycja startowa.
2. Wróć ciężarem do pozycji startowej.', NULL, 'free-exercise-db/Leverage_Deadlift/0.jpg', 'free_exercise_db'),
  ('leverage-decline-chest-press', 'Wyciskanie na maszynie leverage (dolna klatka)', 'Leverage Decline Chest Press', 'motor_coach', 'beginner', array['Siłowe', 'Klatka piersiowa'], 'Wyciskanie na maszynie dźwigniowej ukierunkowane na dolną część klatki piersiowej. Wypychasz uchwyty do przodu i kontrolowanie wracasz, utrzymując napięcie mięśni.', '1. Załaduj odpowiedni ciężar na sworznie i wyreguluj siedzisko do swojego wzrostu. Uchwyty powinny znajdować się przy dolnej części mięśni piersiowych na początku ruchu. Klatka piersiowa i głowa powinny być uniesione, a łopatki ściągnięte. To będzie pozycja startowa.
2. Wypchnij uchwyty do przodu, prostując łokcie.
3. Po krótkiej pauzie na szczycie wróć ciężarem tuż nad pozycję startową, utrzymując napięcie mięśni — nie odkładaj ciężaru na zderzaki, dopóki seria nie zostanie ukończona.', NULL, 'free-exercise-db/Leverage_Decline_Chest_Press/0.jpg', 'free_exercise_db'),
  ('leverage-high-row', 'Wiosłowanie wysokim chwytem na maszynie leverage', 'Leverage High Row', 'motor_coach', 'beginner', array['Siłowe', 'Środek pleców'], 'Wiosłowanie na maszynie dźwigniowej chwytem nachwytem, ciągnąc uchwyty w kierunku tułowia. Mocno angażuje górną część pleców i tył obręczy barkowej.', '1. Załaduj odpowiedni ciężar na sworznie i wyreguluj wysokość siedziska tak, aby sięgać uchwytów nad sobą. Wyreguluj podparcie kolan, które pomoże ci utrzymać pozycję. Złap uchwyty chwytem nachwytem. To będzie pozycja startowa.
2. Ciągnij uchwyty w kierunku tułowia, ściągając łopatki podczas zginania łokci.
3. Zatrzymaj się na dole ruchu, a następnie powoli wróć uchwytami do pozycji startowej.
4. Przy wielu powtórzeniach unikaj całkowitego odkładania ciężaru na zderzaki, aby utrzymać napięcie trenowanych mięśni.', NULL, 'free-exercise-db/Leverage_High_Row/0.jpg', 'free_exercise_db'),
  ('leverage-incline-chest-press', 'Wyciskanie na maszynie leverage (górna klatka)', 'Leverage Incline Chest Press', 'motor_coach', 'beginner', array['Siłowe', 'Klatka piersiowa'], 'Wyciskanie na maszynie dźwigniowej ukierunkowane na górną część klatki piersiowej. Uchwyty na wysokości górnych mięśni piersiowych — wypychasz do przodu i kontrolowanie wracasz.', '1. Załaduj odpowiedni ciężar na sworznie i wyreguluj siedzisko do swojego wzrostu. Uchwyty powinny znajdować się przy górnej części mięśni piersiowych na początku ruchu. Klatka piersiowa i głowa powinny być uniesione, a łopatki ściągnięte. To będzie pozycja startowa.
2. Wypchnij uchwyty do przodu, prostując łokcie.
3. Po krótkiej pauzie na szczycie wróć ciężarem tuż nad pozycję startową, utrzymując napięcie mięśni — nie odkładaj ciężaru na zderzaki, dopóki seria nie zostanie ukończona.', NULL, 'free-exercise-db/Leverage_Incline_Chest_Press/0.jpg', 'free_exercise_db'),
  ('leverage-iso-row', 'Wiosłowanie izometryczne na maszynie leverage', 'Leverage Iso Row', 'motor_coach', 'beginner', array['Siłowe', 'Najszersze grzbietu'], 'Wiosłowanie na maszynie dźwigniowej z uchwytami na wysokości klatki piersiowej. Ciągniesz uchwyty do tułowia, ściągając łopatki — buduje grubość pleców.', '1. Załaduj odpowiedni ciężar na sworznie i wyreguluj wysokość siedziska tak, aby uchwyty były na wysokości klatki piersiowej. Złap uchwyty chwytem neutralnym lub nachwytem. To będzie pozycja startowa.
2. Ciągnij uchwyty w kierunku tułowia, ściągając łopatki podczas zginania łokci.
3. Zatrzymaj się na dole ruchu, a następnie powoli wróć uchwytami do pozycji startowej. Przy wielu powtórzeniach unikaj całkowitego odkładania ciężaru na zderzaki, aby utrzymać napięcie trenowanych mięśni.', NULL, 'free-exercise-db/Leverage_Iso_Row/0.jpg', 'free_exercise_db'),
  ('leverage-shoulder-press', 'Wyciskanie na maszynie leverage (barki)', 'Leverage Shoulder Press', 'motor_coach', 'beginner', array['Siłowe', 'Barki'], 'Wyciskanie nad głowę na maszynie dźwigniowej, ukierunkowane na barki. Wypychasz uchwyty w górę i kontrolowanie wracasz, utrzymując napięcie mięśni.', '1. Załaduj odpowiedni ciężar na sworznie i wyreguluj siedzisko do swojego wzrostu. Uchwyty powinny znajdować się przy górnej części barków na początku ruchu. Klatka piersiowa i głowa powinny być uniesione, a uchwyty trzymane chwytem nachwytem. To będzie pozycja startowa.
2. Wypchnij uchwyty w górę, prostując łokcie.
3. Po krótkiej pauzie na szczycie wróć ciężarem tuż nad pozycję startową, utrzymując napięcie mięśni — nie odkładaj ciężaru na zderzaki, dopóki seria nie zostanie ukończona.', NULL, 'free-exercise-db/Leverage_Shoulder_Press/0.jpg', 'free_exercise_db'),
  ('leverage-shrug', 'Szurgi na maszynie leverage', 'Leverage Shrug', 'motor_coach', 'beginner', array['Siłowe', 'Czworoboczne'], 'Wznosy barków na maszynie dźwigniowej — izolacja mięśnia czworobocznego (trapezius). Po podniesieniu ciężaru z pozycji stojącej unosisz barki w górę, w kierunku uszu.', '1. Załaduj sworznie odpowiednim ciężarem. Ustaw się dokładnie między uchwytami.
2. Złap górne uchwyty komfortowym chwytem, a następnie obniż biodra, robiąc wdech. Patrz przed siebie z głową i klatką piersiową uniesionymi.
3. Odpychaj się od podłogi piętami, prostując biodra i kolana, gdy wstajesz do pozycji stojącej. Trzymaj ramiona wyprostowane przez cały ruch, kończąc z barkami cofniętymi. To będzie pozycja startowa.
4. Unieś ciężar unosząc barki w kierunku uszu, poruszając się prosto w górę i w dół.
5. Zatrzymaj się na szczycie ruchu, a następnie wróć ciężarem do pozycji startowej.', NULL, 'free-exercise-db/Leverage_Shrug/0.jpg', 'free_exercise_db'),
  ('linear-3-part-start-technique', 'Technika startu 3-krokowa (liniowa)', 'Linear 3-Part Start Technique', 'motor_coach', 'beginner', array['Plyometryka', 'Dwugłowe uda'], 'Ćwiczenie sprinterskie uczące jak najszybszej akceleracji z postoju. Specjalne ułożenie stóp i rąk pozwala wybić się z pełnym rozpędem w trzech krokach.', '1. To ćwiczenie pomaga przyspieszyć jak najszybciej do sprintu z pełnego postoju. Pomocne jest użycie linii jako punktu startu. Zacznij z obiema stopami na linii. Umieść lewą stopę tak, aby palec był przy prawej kostce. Umieść prawą stopę 10–15 cm za lewą.
2. Połóż prawą dłoń na linii, a następnie zbliż nos do lewego kolana.
3. Opuść się w przysiadzie, pochylając się do przodu — głowa niżej niż biodra, z ciężarem przeniesionym na lewą nogę. To będzie pozycja startowa.
4. Unieś lewą rękę tak, aby była równoległa do podłoża, wskazując za siebie, i wybij się z pełną mocą, gdy będziesz gotowy.', NULL, 'free-exercise-db/Linear_3-Part_Start_Technique/0.jpg', 'free_exercise_db'),
  ('linear-acceleration-wall-drill', 'Drill akceleracji przy ścianie', 'Linear Acceleration Wall Drill', 'motor_coach', 'beginner', array['Plyometryka', 'Dwugłowe uda'], 'Ćwiczenie sprinterskie przy ścianie uczące mechaniki akceleracji: naprzemienne unoszenie i wbijanie kolan w dół, progresujące do szybkich kropli biegowych.', '1. Oprzyj się pod kątem około 45 stopni o ścianę. Stopy powinny być razem, z pośladkami napinanymi.
2. Zacznij od szybkiego uniesienia prawego kolana, pauzy, a następnie wbicia go prosto w dół, w podłoże.
3. Zmień nogi, unosząc przeciwne kolano, a następnie wbijając je prosto w dół.
4. Powtórz jeszcze raz z prawą nogą, a gdy prawa stopa uderzy o podłoże, wyrzucaj stopy naprzemiennie lewą i prawą tak szybko, jak potrafisz.', NULL, 'free-exercise-db/Linear_Acceleration_Wall_Drill/0.jpg', 'free_exercise_db'),
  ('linear-depth-jump', 'Depth jump liniowy (zeskok i wyskok)', 'Linear Depth Jump', 'motor_coach', 'intermediate', array['Plyometryka', 'Uda'], 'Plyometryczny depth jump: zeskakujesz z wysokiej skrzyni na podłogę i natychmiast wyskakujesz na drugą platformę. Rozwija moc reaktywną nóg.', '1. Potrzebujesz dwóch skrzyń lub ławek rozmieszczonych w odległości kilkudziesięciu centymetrów od siebie. Zacznij stojąc na jednej skrzyni, twarzą w stronę drugiej platformy.
2. Aby rozpocząć ruch, delikatnie zeskocz na podłoże między platformami, pozwalając kolanom i biodrom się uginać.
3. Odwróć ruch wybijając się w górę, prostując biodra, kolana i kostki, aby wskoczyć na drugą platformę.
4. Wyląduj miękko, amortyzując uderzenie nogami.', NULL, 'free-exercise-db/Linear_Depth_Jump/0.jpg', 'free_exercise_db'),
  ('log-lift', 'Wyciskanie kłody (log lift)', 'Log Lift', 'motor_coach', 'intermediate', array['Strongman', 'Barki'], 'Klasyk strongmana: podrzucenie ciężkiej kłody na klatkę i wyciśnięcie jej nad głowę push pressem. Buduje siłę całego ciała, barków i technikę wyciskania.', '1. Zacznij stojąc z kłodą przed sobą. Chwyć uchwyty i zacznij podrzucać kłodę. Gdy jesteś pochylony na początku podrzutu, staraj się unieść kłodę możliwie jak najwyżej, przyciągając ją do klatki piersiowej. Wyprostuj biodra i kolana, aby wynieść ją w górę i dokończyć podrzut.
2. Odrzuć głowę do tyłu i patrz w górę, tworząc półkę na klatce piersiowej, na której oprzesz kłodę. Rozpocznij wyciskanie od opadu, lekko uginając kolana i odwracając ruch. Ten push press wygeneruje rozpęd, aby ruszyć kłodę w górę. Kontynuuj, prostując łokcie, aby wycisnąć kłodę ponad głowę. Nie ma tu ścisłych reguł techniki, więc używaj technik, które są dla ciebie najbardziej efektywne. Podczas wyciskania kłody upewnij się, że przepychasz głowę do przodu przy każdym powtórzeniu, patrząc przed siebie.
3. Powtarzaj tyle razy, ile zdołasz. Staraj się kontrolować opadanie kłody, gdy wraca ona na ziemię.', NULL, 'free-exercise-db/Log_Lift/0.jpg', 'free_exercise_db'),
  ('london-bridges', 'London Bridges (zejście po linie)', 'London Bridges', 'motor_coach', 'intermediate', array['Siłowe', 'Najszersze grzbietu'], 'Ćwiczenie siły górnej części ciała i chwytu: opuszczasz ciało w tył, przechodząc ręką nad ręką w dół po linie wspinaczkowej, a potem wracasz do góry. Nazwa pochodzi od mostu londyńskiego.', '1. Podłącz linę wspinaczkową do wysokiej belki lub poprzeczki. Pod nią upewnij się, że sztanga maszyny Smitha jest zablokowana zabezpieczeniami i nie może się poruszać. Alternatywnie można też użyć solidnej skrzyni.
2. Stań na sztandze, balansując się liną. To będzie pozycja startowa.
3. Trzymając ciało prosto, odchyl się do tyłu i opuszczaj ciało, powoli przechodząc ręką nad ręką w dół po linie. Kontynuuj, aż będziesz prostopadle do ziemi.
4. Trzymając ciało prosto, odwróć ruch, przechodząc ręką nad ręką w górę, z powrotem do pozycji startowej.', NULL, 'free-exercise-db/London_Bridges/0.jpg', 'free_exercise_db'),
  ('looking-at-ceiling', 'Patrzenie w sufit', 'Looking At Ceiling', 'motor_coach', 'beginner', array['Rozciąganie', 'Uda'], 'Mobilizacja i wygięcie kręgosłupa w klęku: unosząc pośladki w górę i odchylając głowę, patrzysz w sufit, tworząc wygięcie w plecach.', '1. Uklęknij na podłodze, trzymając pięty obiema rękami.
2. Unoś pośladki w górę i do przodu, jednocześnie odchylając głowę do tyłu, aby patrzeć w sufit, tworząc wygięcie w plecach.', NULL, 'free-exercise-db/Looking_At_Ceiling/0.jpg', 'free_exercise_db'),
  ('low-cable-crossover', 'Rozpiętki na wyciągach dolnych (low cable crossover)', 'Low Cable Crossover', 'motor_coach', 'beginner', array['Siłowe', 'Klatka piersiowa'], 'Rozpiętki klatki piersiowej na dwóch dolnych blokach. Prowadzisz dłonie szerokim łukiem w górę, aż połączą się przed klatką — mocna izolacja mięśni piersiowych.', '1. Aby przejść do pozycji startowej, ustaw bloki na dolnej pozycji, wybierz opór i złap uchwyt w każdej dłoni.
2. Zrób krok do przodu, uzyskując napięcie linek. Dłonie powinny być zwrócone do przodu, poniżej pasa, z ramionami wyprostowanymi. To będzie pozycja startowa.
3. Z lekkim ugięciem ramion poprowadź dłonie w górę i w kierunku linii środkowej ciała. Twoje dłonie powinny połączyć się przed klatką piersiową, dłońmi skierowanymi w górę.
4. Wróć ramionami do pozycji startowej po krótkiej pauzie.', NULL, 'free-exercise-db/Low_Cable_Crossover/0.jpg', 'free_exercise_db'),
  ('low-cable-triceps-extension', 'Prostowanie ramion na wyciągu dolnym w leżeniu', 'Low Cable Triceps Extension', 'motor_coach', 'beginner', array['Siłowe', 'Triceps'], 'Izolacja tricepsa na wyciągu dolnym w leżeniu na plecach. Prostujesz przedramiona w górę, trzymając ramiona nieruchomo, prostopadle do tułowia.', '1. Dobierz żądany ciężar i połóż się na plecach na ławce maszyny do wiosłowania z liną przymocowaną do dolnego bloku. Twoja głowa powinna być skierowana w stronę przyczepu.
2. Złap końce liny z zewnątrz, z dłońmi zwróconymi ku sobie (chwyt neutralny).
3. Ustaw łokcie tak, aby były zgięte pod kątem 90 stopni, a ramiona prostopadłe (pod kątem 90 stopni) do tułowia. Wskazówka: trzymaj łokcie blisko i upewnij się, że ramiona skierowane są ku sufitowi, a przedramiona w stronę bloku nad twoją głową. To będzie pozycja startowa.
4. Na wydechu wyprostuj przedramiona, aż będą proste i pionowe. Ramiona i łokcie pozostają nieruchomo przez cały ruch. Poruszać się powinny tylko przedramiona. Mocno napnij triceps na sekundę.
5. Robiąc wdech, powoli wróć do pozycji startowej.
6. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Low_Cable_Triceps_Extension/0.jpg', 'free_exercise_db'),
  ('low-pulley-row-to-neck', 'Wiosłowanie na dolnym bloku do szyi', 'Low Pulley Row To Neck', 'motor_coach', 'beginner', array['Siłowe', 'Barki'], 'Wariant wiosłowania na dolnym bloku z ciągnięciem liny do wysokości szyi, z łokciami rozstawionymi wysoko na boki. Mocno angażuje górną część pleców i tylny deltoid.', '1. Usiądź na maszynie do wiosłowania na dolnym bloku z przyczepem w postaci liny.
2. Złap końce liny chwytem nachwytem i usiądź z prostymi plecami oraz lekko ugiętymi kolanami. Wskazówka: trzymaj plecy prawie całkowicie pionowo, a ramiona w pełni wyprostowane przed sobą. To będzie pozycja startowa.
3. Trzymając tułów nieruchomo, unoś łokcie i zacznij je uginać, ciągnąc linę w kierunku szyi na wydechu. W trakcie całego ruchu ramiona powinny pozostać równoległe do podłogi. Wskazówka: kontynuuj ten ruch, aż dłonie znajdą się prawie przy uszach (przedramiona nie będą równoległe do podłogi na końcu ruchu, ponieważ będą skierowane nieco w górę), a łokcie odejdą na boki od ciała.
4. Po przytrzymaniu przez około sekundę w pozycji spięcia wróć powoli do pozycji startowej, robiąc wdech. Wskazówka: ponownie, podczas żadnej fazy ruchu tułów nie powinien się poruszać.
5. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Low_Pulley_Row_To_Neck/0.jpg', 'free_exercise_db'),
  ('lower-back-curl', 'Unoszenie klatki w leżeniu (dolne plecy)', 'Lower Back Curl', 'motor_coach', 'beginner', array['Rozciąganie', 'Brzuch'], 'Wzmacnianie prostownika grzbietu w leżeniu na brzuchu: unosisz klatkę piersiową nad podłogę siłą mięśni dolnych pleców, bez pomocy ramion.', '1. Połóż się na brzuchu z ramionami rozłożonymi na boki. To będzie pozycja startowa.
2. Używając mięśni dolnego odcinka pleców, wyprostuj kręgosłup, unosząc klatkę piersiową nad ziemię. Nie używaj ramion, aby się podeprzeć. Trzymaj głowę uniesioną podczas ruchu. Powtórz 10–20 razy.', NULL, 'free-exercise-db/Lower_Back_Curl/0.jpg', 'free_exercise_db'),
  ('lower-back-smr', 'Rolowanie dolnego odcinka pleców (SMR)', 'Lower Back-SMR', 'motor_coach', 'beginner', array['Rozciąganie', 'Dolny odcinek pleców'], 'Automasaż wałkiem mięśni dolnego odcinka pleców, po bokach kręgosłupa. W siadzie obciążasz rolę i toczysz się po dolnych plecach, omijając sam kręgosłup.', '1. W pozycji siedzącej umieść wałek pod dolnym odcinkiem pleców. Skrzyżuj ramiona przed sobą i wysuwaj barki do przodu. To będzie pozycja startowa.
2. Unoś biodra nad podłogę i odchyl się do tyłu, utrzymując ciężar na dolnym odcinku pleców. Teraz przenieś ciężar nieco na jedną stronę, utrzymując ciężar z dala od kręgosłupa, na mięśniach po jego bokach. Tocz się po dolnym odcinku pleców, zatrzymując się na 10–30 sekund w miejscach napięcia. Powtórz na drugiej stronie.', NULL, 'free-exercise-db/Lower_Back-SMR/0.jpg', 'free_exercise_db'),
  ('lunge-pass-through', 'Wykrok z przekazaniem kettlebell pod nogą', 'Lunge Pass Through', 'motor_coach', 'intermediate', array['Siłowe', 'Dwugłowe uda'], 'Wykrok połączony z przekazywaniem kettlebell pod ugiętą nogą do drugiej ręki. Ćwiczenie na nogi, pośladki i koordynację.', '1. Stań z tułowiem wyprostowanym, trzymając kettlebell w prawej ręce. To będzie pozycja startowa.
2. Zrób krok do przodu lewą stopą i opuść górną część ciała w dół, uginając biodro i kolano, trzymając tułów pionowo. Opuść tylne kolano, aż prawie dotknie ziemi.
3. Podczas wykroku przekaż kettlebell pod przednią nogą do przeciwnej ręki.
4. Odpychając się piętą stopy, wróć do pozycji startowej.
5. Powtórz ruch zalecaną liczbę powtórzeń, naprzemiennie nogami.', NULL, 'free-exercise-db/Lunge_Pass_Through/0.jpg', 'free_exercise_db'),
  ('lunge-sprint', 'Wykrok wyskokowy ze sztangą (Smith)', 'Lunge Sprint', 'motor_coach', 'intermediate', array['Siłowe', 'Uda'], 'Plyometryczne wykroki naprzemienne ze sztangą maszyny Smitha na barkach. Z dolnej fazy wykroku wybijasz się w górę i zmieniasz nogi w locie.', '1. Ustaw sztangę maszyny Smitha na odpowiedniej wysokości. Ustaw się pod sztangą, układając ją na tylnych aktonach barków. Zdejmij sztangę ze stojaków, a następnie rozstaw stopy w wykroku — jedna stopa z przodu, druga z tyłu. To będzie pozycja startowa.
2. Opuść tylne kolano prawie do ziemi, uginając kolana i opuszczając biodra podczas tego ruchu.
3. Na dole opadu natychmiast zmień kierunek ruchu. Eksplozywnie odpychaj się piętą przedniej stopy z lekkim naciskiem tylnej stopy. Wyskocz w górę i zamień położenie nóg.
4. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Lunge_Sprint/0.jpg', 'free_exercise_db'),
  ('lying-bent-leg-groin', 'Rozciąganie pachwin z partnerem (ugięte nogi)', 'Lying Bent Leg Groin', 'motor_coach', 'advanced', array['Rozciąganie', 'Przywodziciele'], 'Rozciąganie pachwin z pomocą partnera: leżysz na plecach ze stopami złożonymi podeszwami, partner dociska twoje kolana w dół po serii naprężeń.', '1. Połóż się na plecach z ugiętymi kolanami i podeszwami stóp dociśniętymi do siebie. Partner powinien trzymać twoje kolana. To będzie pozycja startowa.
2. Spróbuj ścisnąć kolana do siebie, podczas gdy partner zapobiega jakimkolwiek ruchowi.
3. Po 10–20 sekundach rozluźnij mięśnie, gdy partner delikatnie dociska twoje kolana w kierunku podłogi. Koniecznie informuj pomocnika, kiedy rozciąganie jest już wystarczające, aby zapobiec urazowi lub przetrenowaniu rozciągania.', NULL, 'free-exercise-db/Lying_Bent_Leg_Groin/0.jpg', 'free_exercise_db'),
  ('lying-cable-curl', 'Uginanie ramion na wyciągu dolnym w leżeniu', 'Lying Cable Curl', 'motor_coach', 'intermediate', array['Siłowe', 'Biceps'], 'Uginanie ramion na wyciągu dolnym w leżeniu na plecach przed stosem ciężarów. Stałe napięcie linki przez cały ruch mocno izoluje biceps.', '1. Złap prosty drążek lub drążek E-Z przymocowany do dolnego bloku obiema rękami, chwytem podchwytem (dłonie zwrócone w górę) na szerokość barków.
2. Połóż się płasko na plecach na macie do ćwiczeń przed stosem ciężarów, ze stopami dociśniętymi do ramy maszyny wyciągu i nogami wyprostowanymi.
3. Z ramionami wyprostowanymi i łokciami blisko ciała lekko ugnij ramiona. To będzie pozycja startowa.
4. Trzymając ramiona nieruchomo i łokcie blisko ciała, uginaj drążek powoli w kierunku klatki piersiowej, robiąc wydech i ściskając bicepsy.
5. Po sekundzie spięcia na szczycie ruchu powoli wróć do pozycji startowej.
6. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Lying_Cable_Curl/0.jpg', 'free_exercise_db'),
  ('lying-cambered-barbell-row', 'Wiosłowanie sztangą cambered w leżeniu na ławce', 'Lying Cambered Barbell Row', 'motor_coach', 'beginner', array['Siłowe', 'Środek pleców'], 'Wiosłowanie specjalną sztangą cambered (z wygięciem) w leżeniu przodem na ławce. Większy zakres ruchu niż zwykłą sztangą — celuje w plecy w zależności od miejsca ciągnięcia.', '1. Połóż sztangę cambered pod ławką do ćwiczeń.
2. Połóż się twarzą w dół na ławce do ćwiczeń i złap sztangę chwytem nachwytem (dłonie zwrócone w dół), szerszym niż szerokość barków. To będzie pozycja startowa.
3. Na wydechu wiośluj sztangę w górę, trzymając łokcie blisko ciała — do klatki piersiowej, aby celować w górną, środkową część pleców, lub do brzucha, jeśli celem są mięśnie najszersze grzbietu.
4. Po sekundzie przytrzymania na szczycie opuszczaj sztangę powoli z powrotem do pozycji startowej, robiąc wdech.', NULL, 'free-exercise-db/Lying_Cambered_Barbell_Row/0.jpg', 'free_exercise_db'),
  ('lying-close-grip-bar-curl-on-high-pulley', 'Ułożone uginanie ramion wąskim chwytem na wysokim pulleyze', 'Lying Close-Grip Bar Curl On High Pulley', 'motor_coach', 'beginner', array['Siłowe', 'Biceps'], 'Uginanie bicepsa w pozycji leżącej z prostym drążkiem podpiętym do górnego wyciągu. Leżysz na ławce głową do wyciągu i przyciągasz sztangę półkolistym ruchem aż do brody.', '1. Ustaw płaską ławkę przed wysokim wyciągiem lub maszyną do ściągania drążka.
2. Chwyć prosto drążek chwytem podchwytem (dłonie do góry) na szerokość mniej więcej barków.
3. Połóż się na plecach tak, aby głowa znajdowała się za końcem ławki.
4. Wyciągnij ramiona prosto nad barki. Twój tułów i ramiona powinny tworzyć kąt 90 stopni, a łokcie powinny być blisko ciała. To Twoja pozycja startowa.
5. Robiąc wydech, uginaj ramiona, prowadząc sztangę półkolistym ruchem w dół, aż dotknie brody. Napnij biceps przez sekundę w szczycie ruchu. Wskazówka: podczas tego ruchu poruszają się tylko przedramiona. Ramiona od barku do łokcia nie mogą się ruszać ani przez moment — przez cały ruch pozostają prostopadłe.
6. Powoli wróć do pozycji startowej.
7. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Lying_Close-Grip_Bar_Curl_On_High_Pulley/0.jpg', 'free_exercise_db'),
  ('lying-close-grip-barbell-triceps-extension-behind-the-head', 'Prostowanie tricepsów wąskim chwytem za głowę w leżeniu', 'Lying Close-Grip Barbell Triceps Extension Behind The Head', 'motor_coach', 'intermediate', array['Siłowe', 'Triceps'], 'Ćwiczenie francuskie wąkim chwytem wykonywane leżąc na ławce, ze sztangą opuszczaną za głowę. Główną pracę wykonują tricepsy, a łokcie pozostają nieruchomo w jednym miejscu.', '1. Trzymając sztangę lub gryf Ez chwytem nachwytem (dłonie skierowane do przodu), połóż się na plecach na płaskiej ławce, blisko jej końca. Wskazówka: zwykłą sztangę chwyć na szerokości barków, a gryf Ez — za wewnętrzne uchwyty.
2. Wyciągnij ramiona przed siebie i powoli cofnij sztangę półkolistym ruchem (trzymając ramiona wyprostowane) do pozycji za głową. Na końcu tego kroku ramiona powinny być nad głową, równolegle do podłogi. To Twoja pozycja startowa. Wskazówka: całą trzymaj łokcie blisko siebie.
3. Robiąc wdech, opuszczaj sztangę, zginając łokcie i utrzymując nieruchomo ramiona od barku do łokcia. Opuszczaj sztangę, aż przedramiona będą prostopadłe do podłogi.
4. Robiąc wydech, wróć sztangą do pozycji startowej, wypychając ją półkolistym ruchem w górę, aż przedramiona znów będą równoległe do podłogi. Mocno napnij triceps na szczycie ruchu na sekundę. Wskazówka: ponownie — ruszają się tylko przedramiona. Ramiona od barku do łokcia muszą pozostać nieruchome przez cały czas.
5. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Lying_Close-Grip_Barbell_Triceps_Extension_Behind_The_Head/0.jpg', 'free_exercise_db'),
  ('lying-close-grip-barbell-triceps-press-to-chin', 'Wyciskanie tricepsów wąskim chwytem do brody w leżeniu', 'Lying Close-Grip Barbell Triceps Press To Chin', 'motor_coach', 'intermediate', array['Siłowe', 'Triceps'], 'Wariant ćwiczenia francuskiego leżąc, w którym opuszczasz sztangę aż lekko dotknie brody. Triceps pracuje intensywnie, bo ramiona pozostają nieruchome nad klatką piersiową.', '1. Trzymając sztangę lub gryf Ez chwytem nachwytem (dłonie skierowane do przodu), połóż się na plecach na płaskiej ławce tak, by głowa była za końcem ławki. Wskazówka: zwykłą sztangę chwyć na szerokości barków, a gryf Ez — za wewnętrzne uchwyty.
2. Wyciągnij ramiona przed siebie, trzymając sztangę nad klatką piersiową. Ramiona powinny być prostopadłe do tułowia (kąt 90 stopni). To Twoja pozycja startowa.
3. Robiąc wdech, opuszczaj sztangę półkolistym ruchem, zginając łokcie, przy czym ramiona od barku do łokcia pozostają nieruchome, a łokcie blisko ciała. Opuszczaj sztangę, aż lekko dotknie brody.
4. Robiąc wydech, wróć sztangą do pozycji startowej, wypychając ją półkolistym ruchem w górę. Mocno napnij triceps na szczycie ruchu na sekundę. Wskazówka: ponownie — ruszają się tylko przedramiona. Ramiona od barku do łokcia muszą pozostać nieruchome przez cały czas.
5. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Lying_Close-Grip_Barbell_Triceps_Press_To_Chin/0.jpg', 'free_exercise_db'),
  ('lying-crossover', 'Rozciąganie bioder w skrzyżowaniu nóg (z partnerem)', 'Lying Crossover', 'motor_coach', 'advanced', array['Rozciąganie', 'Odwodziciele'], 'Ćwiczenie rozciągające z partnerem: leżysz na plecach i przekładasz jedno zgięte kolano przez ciało, próbując dotknąć nim podłogi. Partner przytrzymuje ramię i nogę, aby pogłębić rozciągnięcie mięśni pośladkowych.', '1. Połóż się na plecach z wyprostowanymi nogami.
2. Przełóż jedną nogę przez ciało z zgiętym kolanem, próbując dotknąć nim podłogi. Partner klęczy obok Ciebie, jedną ręką przytrzymując Twoje ramię w dół, a drugą kontrolując przełożoną nogę. To Twoja pozycja startowa.
3. Spróbuj uniesione kolano oderwać od podłogi, podczas gdy partner blokuje faktyczny ruch.
4. Po 10–20 sekundach rozluźnij nogę, a partner delikatnie dociśnie kolano do podłogi. Powtórz na drugą stronę.', NULL, 'free-exercise-db/Lying_Crossover/0.jpg', 'free_exercise_db'),
  ('lying-dumbbell-tricep-extension', 'Prostowanie tricepsów z hantlami w leżeniu', 'Lying Dumbbell Tricep Extension', 'motor_coach', 'intermediate', array['Siłowe', 'Triceps'], 'Klasyczne „francuskie” z dwoma hantlami wykonywane na płaskiej ławce. Opuszczasz hantle obok głowy, zginając tylko łokcie, a potem prostujesz ramiona siłą tricepsów.', '1. Połóż się na płaskiej ławce, trzymając dwie hantle bezpośrednio przed sobą. Ramiona powinny być całkowicie wyprostowane pod kątem 90 stopni względem tułowia i podłogi. Dłonie skierowane do wewnątrz, łokcie blisko ciała. To pozycja startowa.
2. Robiąc wdech i utrzymując ramiona od barku do łokcia nieruchomo oraz łokcie blisko ciała, powoli opuszczaj ciężary, aż hantle znajdą się blisko uszu.
3. W tym punkcie, trzymając łokcie blisko ciała i ramiona od barku do łokcia nieruchomo, użyj tricepsów, by wrócić ciężarem do pozycji startowej robiąc wydech.
4. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Lying_Dumbbell_Tricep_Extension/0.jpg', 'free_exercise_db'),
  ('lying-face-down-plate-neck-resistance', 'Opór szyi obciążnikiem w leżeniu na brzuchu', 'Lying Face Down Plate Neck Resistance', 'motor_coach', 'intermediate', array['Siłowe', 'Kark'], 'Wzmacnianie mięśni karku w leżeniu na brzuchu na ławce, z talerzem obciążającym trzymanym z tyłu głowy. Opuszczasz głowę w dół, a potem unosisz ją z powrotem napinając kark.', '1. Połóż się twarzą w dół całym ciałem prosto na płaskiej ławce, trzymając talerz obciążający z tyłu głowy. Wskazówka: musisz ustawić się tak, by barki były lekko za końcem ławki — wtedy górna część klatki piersiowej, kark i twarz są poza ławką. To Twoja pozycja startowa.
2. Trzymając pewnie talerz na potylicy, powoli opuszczaj głowę (jak przy kiwaniu „tak”), robiąc wdech.
3. Unieś głowę z powrotem do pozycji startowej półkolistym ruchem, robiąc wydech. Utrzymaj napięcie przez sekundę.
4. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Lying_Face_Down_Plate_Neck_Resistance/0.jpg', 'free_exercise_db'),
  ('lying-face-up-plate-neck-resistance', 'Opór szyi obciążnikiem w leżeniu na plecach', 'Lying Face Up Plate Neck Resistance', 'motor_coach', 'intermediate', array['Siłowe', 'Kark'], 'Wzmacnianie przedniej części szyi w leżeniu na plecach na ławce, z talerzem opartym na czole. Opuszczasz głowę do tyłu, a potem wracasz do góry napinając mięśnie karku.', '1. Połóż się na plecach całym ciałem prosto na płaskiej ławce, trzymając talerz obciążający na czole. Wskazówka: musisz ustawić się tak, by barki były lekko za końcem ławki — wtedy kark, szyja i głowa są poza ławką. To Twoja pozycja startowa.
2. Trzymając pewnie talerz na czole, powolio opuszczaj głowę do tyłu półkolistym ruchem, robiąc wdech.
3. Unieś głowę z powrotem do pozycji startowej półkolistym ruchem, robiąc wydech. Utrzymaj napięcie przez sekundę.
4. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Lying_Face_Up_Plate_Neck_Resistance/0.jpg', 'free_exercise_db'),
  ('lying-glute', 'Rozciąganie pośladków w leżeniu (z partnerem)', 'Lying Glute', 'motor_coach', 'advanced', array['Rozciąganie', 'Pośladki'], 'Ćwiczenie rozciągające pośladki wykonywane z partnerem. Unosisz zgiętą nogę i próbujesz nią „pchnąć” w stronę partnera, który stawia opór; potem partner delikatnie dociska nogę do klatki, pogłębiając rozciągnięcie.', '1. Połóż się na plecach z partnerem klęczącym obok Ciebie.
2. Zegnij biodro jednej nogi, unosząc ją z podłogi. Obróć nogę tak, by stopa była nad przeciwnym biodrem, a goleń prostopadle do ciała. Partner powinien przytrzymać kolano i kostkę. To Twoja pozycja startowa.
3. Spróbuj popchnąć nogę w stronę partnera, który blokuje faktyczny ruch nogi.
4. Po 10–20 sekundach całkowicie się rozluźnij, a partner delikatnie dociśnie kostkę i kolano w stronę klatki piersiowej. Koniecznie informuj osobę pomagającą, gdy rozciągnięcie jest już wystarczające, aby uniknąć urazu lub przetrenowania mięśnia.', NULL, 'free-exercise-db/Lying_Glute/0.jpg', 'free_exercise_db'),
  ('lying-hamstring', 'Rozciąganie dwugłowego uda w leżeniu (z partnerem)', 'Lying Hamstring', 'motor_coach', 'advanced', array['Rozciąganie', 'Dwugłowe uda'], 'Rozciąganie tylnej części uda z pomocą partnera. Leżąc na plecach unosisz nogę, próbujesz ją zgiąć w kolanie napinając mięsień, a następnie partner delikatnie dociska nogę w stronę głowy.', '1. Połóż się na plecach z wyprostowanymi nogami. Partner powinien klęczeć obok Ciebie. Unieś jedną nogę w kierunku sufitu i pozwól partnerowi chwycić ją za kostkę. W razie potrzeby partner może podeprzeć swoją nogę barkiem. To Twoja pozycja startowa.
2. Gdy partner przytrzymuje nogę w miejscu, spróbuj zgiąć kolano, napinając mięśnie dwugłowe uda przez 10–20 sekund.
3. Potem rozluźnij nogę, pozwalając partnerowi delikatnie dociśnięcie jej w stronę głowy. Koniecznie informuj osobę pomagającą, gdy rozciągnięcie jest wystarczające, aby uniknąć urazu lub przetrenowania. Po zakończeniu zmień stronę.', NULL, 'free-exercise-db/Lying_Hamstring/0.jpg', 'free_exercise_db'),
  ('lying-high-bench-barbell-curl', 'Uginanie ramion ze sztangą na wysokiej ławce', 'Lying High Bench Barbell Curl', 'motor_coach', 'intermediate', array['Siłowe', 'Biceps'], 'Uginanie bicepsów leżąc przodem na wysokiej ławce, ze sztangą zwisającą przed sobą. Pracują tylko przedramiona, co izoluje biceps bez możliwości oszukiwania.', '1. Połóż się przodem na wysokim płaskim ławce, trzymając sztangę chwytem podchwytem (dłonie do góry). Wskazówka: zwykłą sztangę chwyć na szerokości barków, a gryf Ez — za wewnętrzne uchwyty. Tułów ustaw tak, by górna część klatki piersiowej była za końcem ławki, a sztanga zwisała przed Tobą na wyprostowanych ramionach, prostopadle do podłogi. To Twoja pozycja startowa.
2. Trzymając łokcie blisko ciała i ramiona od barku do łokcia nieruchomo, uginaj ciężar półkolistym ruchem w górę, napinając biceps i robiąc wydech. Zatrzymaj się na szczycie ruchu na sekundę.
3. Robiąc wdech, powoli wróć do pozycji startowej. Wskazówka: przez cały czas zachowuj pełną kontrolę nad ciężarem i unikaj jakiegokolwiek kołysania. Pamiętaj — w całym ruchu poruszają się tylko przedramiona.
4. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Lying_High_Bench_Barbell_Curl/0.jpg', 'free_exercise_db'),
  ('lying-leg-curls', 'Uginanie nóg leżąc na maszynie', 'Lying Leg Curls', 'motor_coach', 'beginner', array['Siłowe', 'Dwugłowe uda'], 'Izolowane ćwiczenie tylnej części uda na maszynie do uginania nóg w leżeniu na brzuchu. Zgina się kolana, przyciągając wałek do pośladków, a potem powoli wraca do startu.', '1. Dostosuj dźwignię maszyny do swojego wzrostu i połóż się twarzą w dół na maszynie do uginania nóg z wałkiem z tyłu nóg (tuż pod łydkami). Wskazówka: najlepiej używać maszyny z pochylonym, a nie płaskim siedziskiem, bo pozycja pod kątem sprzyja lepszej pracy mięśni dwugłowych uda.
2. Trzymając tułów płasko na ławce upewnij się, że nogi są całkowicie wyprostowane, i złap uchwyty po bokach maszyny. Ustaw palce stóp prosto (możesz też użyć innego z dwóch pozostałych ustawień opisanych w sekcji o pozycji stóp). To Twoja pozycja startowa.
3. Robiąc wydech, uginaj nogi maksymalnie wysoko, nie odrywając ud od podparcia. Po osiągnięciu pełnego napięcia zatrzymaj się na sekundę.
4. Robiąc wdech, wróć nogami do pozycji początkowej. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Lying_Leg_Curls/0.jpg', 'free_exercise_db'),
  ('lying-machine-squat', 'Przysiad w maszynie w leżeniu (hack squat)', 'Lying Machine Squat', 'motor_coach', 'intermediate', array['Siłowe', 'Uda'], 'Przysiad wykonywany w maszynie hack squat lub podobnej, w pozycji leżącej na plecach. Wypychasz platformę prostując nogi, mocno napinając czworogłowe uda, a potem powoli opuszczasz.', '1. Dostosuj maszynę do wysokości pozwalającej Ci wejść do niej z zgiętymi kolanami i udami nieco poniżej równoległości.
2. Po wyborze ciężaru ustaw się w maszynie twarzą do góry z zgiętymi kolanami i udami nieco poniżej równoległości względem platformy. Upewnij się, że kolana nie wychodzą poza palce stóp. Kąt między mięśniami dwugłowymi uda a łydkami powinien być nieco mniejszy niż 90 stopni (ponieważ pozycja startowa wymaga rozpoczęcia nieco poniżej równoległości). Plecy i głowa powinny opierać się na maszynie, a barki być dociśnięte pod podpórkami barkowymi.
3. Chwyć uchwyty po bokach i ustaw stopy na szerokość barków, lekko skręcone na zewnątrz. To Twoja pozycja startowa.
4. Odpychając się śródstopiem i robiąc wydech, wyprostuj całe ciało, mocno napinając mięśnie czworogłowe uda. Utrzymaj pozycję napięcia przez sekundę. Wskazówka: ponieważ zaczynasz poniżej równoległości, przy pierwszym powtórzeniu możesz pomóc sobie rękami odpychając się od ud.
5. Powoli uginaj nogi robiąc wdech, ale zamiast schodzić aż do pozycji startowej zatrzymaj się, gdy uda będą równoległe do platformy. Kąt między mięśniami dwugłowymi uda a łydkami powinien wynosić 90 stopni.
6. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Lying_Machine_Squat/0.jpg', 'free_exercise_db'),
  ('lying-one-arm-lateral-raise', 'Wznos jednorącz bokiem w leżeniu na ławce', 'Lying One-Arm Lateral Raise', 'motor_coach', 'intermediate', array['Siłowe', 'Barki'], 'Wznos hantli bokiem wykonywany pojedynczą ręką, leżąc na brzuchu na płaskiej ławce. Izoluje boczną część barku bez możliwości oszukiwania ruchem tułowia.', '1. Trzymając hantel w jednej ręce, połóż się klatką piersiową w dół na płaskiej ławce. Drugą rękę możesz użyć, by trzymać się nogi ławki dla stabilności.
2. Ustaw dłoń trzymającą hantel neutralnie (palce skierowane ku tułowiowi), trzymając ramię wyprostowane z lekko zgiętym łokciem. To Twoja pozycja startowa.
3. Teraz unieś ramię z hantlą na bok, aż łokieć znajdzie się na wysokości barku, a ramię mniej więcej równolegle do podłogi, robiąc wydech. Wskazówka: zachowaj ramię prostopadle do tułowia i wyprostowane przez cały ruch. Dodatkowo utrzymaj napięcie na górze przez sekundę.
4. Powoli opuść hantlę do pozycji startowej, robiąc wdech.
5. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Lying_One-Arm_Lateral_Raise/0.jpg', 'free_exercise_db'),
  ('lying-prone-quadriceps', 'Rozciąganie czworogłowego uda w leżeniu na brzuchu (z partnerem)', 'Lying Prone Quadriceps', 'motor_coach', 'advanced', array['Rozciąganie', 'Uda'], 'Rozciąganie przodu uda z pomocą partnera. Leżysz na brzuchu, zginasz kolano i próbujesz je wyprostować napinając mięsień, a potem partner delikatnie dociśla stopę w stronę pośladka.', '1. Połóż się twarzą w dół na podłodze z partnerem klęczącym obok Ciebie. Zegnij jedno kolano i unieś nogę nad podłogę, próbując dotknąć pośladka stopą. Partner powinien przytrzymać kolano i kostkę. To Twoja pozycja startowa.
2. Spróbuj wyprostować kolano, podczas gdy partner blokuje faktyczny ruch.
3. Po 10–20 sekundach rozluźnij mięśnie, a partner delikatnie dociśnie stopę w stronę pośladka, dodatkowo rozciągając mięsień czworogłowy uda i zginacze biodra.
4. Po kolejnych 10–20 sekundach zmień strony.', NULL, 'free-exercise-db/Lying_Prone_Quadriceps/0.jpg', 'free_exercise_db'),
  ('lying-rear-delt-raise', 'Wznos hantli tyłem w leżeniu na ławce', 'Lying Rear Delt Raise', 'motor_coach', 'intermediate', array['Siłowe', 'Barki'], 'Wznos oburącz na tylny akton barku wykonywany leżąc klatką w dół na płaskiej ławce. Unosisz hantle na boki aż do wysokości barku, napinając tylne partie barków i górną część pleców.', '1. Trzymając hantle w każdej ręce, połóż się klatką piersiową w dół na płaskiej ławce.
2. Ustaw dłonie neutralnie (palce skierowane ku tułowiowi), trzymając ramiona wyprostowane z lekko zgiętymi łokciami. To Twoja pozycja startowa.
3. Teraz unieś ramiona na boki, aż łokcie znajdą się na wysokości barku, a ramiona mniej więcej równolegle do podłogi, robiąc wydech. Wskazówka: utrzymuj ramiona prostopadle do tułowia i wyprostowane przez cały ruch. Dodatkowo utrzymaj napięcie na górze przez sekundę.
4. Powoli opuść hantle do pozycji startowej, robiąc wdech.
5. Powtórz zalecaną liczbę powtórzeń, a potem zmień ramię.', NULL, 'free-exercise-db/Lying_Rear_Delt_Raise/0.jpg', 'free_exercise_db'),
  ('lying-supine-dumbbell-curl', 'Uginanie hantli podchwytem w leżeniu na plecach', 'Lying Supine Dumbbell Curl', 'motor_coach', 'beginner', array['Siłowe', 'Biceps'], 'Uginanie bicepsów leżąc na plecach na ławce, z hantlami trzymanymi po bokach ciała. Ramię pozostaje nieruchome, a Ty uginasz przedramię obracając nadgarstek tak, by dłoń skierowana była ku górze.', '1. Połóż się na płaskiej ławce twarzą do góry, trzymając hantle w każdej ręce na udach.
2. Odsuń hantle na boki z wyprostowanymi ramionami, dłońmi skierowanymi ku udom (chwyt neutralny).
3. Trzymając ramiona blisko tułowia i łokcie przy ciele, powoli opuszczaj ramiona (utrzymując je wyprostowane z lekkim zgięciem w łokciach) jak najniżej w stronę podłogi. Gdy nie możesz zejść już niżej, zablokuj górne ramiona w tej pozycji — to będzie Twoja pozycja startowa.
4. Robiąc wydech, powoli zacznij uginać ciężary, jednocześnie obracając nadgarstki tak, by dłonie były skierowane ku górze. Kontynuuj uginanie, aż biceps zostanie całkowicie napięty i mocno ściśnij mięsień na górze przez sekundę. Wskazówka: ruszać się powinny tylko przedramiona. Ramiona od barku do łokcia muszą pozostać nieruchome, a łokcie blisko ciała przez cały ruch.
5. Bardzo powoli wróć do pozycji startowej.', NULL, 'free-exercise-db/Lying_Supine_Dumbbell_Curl/0.jpg', 'free_exercise_db'),
  ('lying-t-bar-row', 'Wiosłowanie T-bar w leżeniu na maszynie', 'Lying T-Bar Row', 'motor_coach', 'intermediate', array['Siłowe', 'Środek pleców'], 'Wiosłowanie wykonywane leżąc przodem na maszynie T-bar. Ściągasz ciężar do klatki piersiowej, mocno napinając mięśnie pleców, z tułowiem stabilnie oprzymanym na podparciu.', '1. Załaduj maszynę do wiosłowania T-bar odpowiednim ciężarem i ustaw wysokość podparcia nóg tak, aby Twoja górna część klatki piersiowej była na szczycie poduszki. Wskazówka: w niektórych maszynach wystarczy stanąć na właściwym stopniu, który pozwala uzyskać wysokość z górną częścią klatki piersiowej na szczycie poduszki.
2. Połóż się twarzą w dół na poduszce i chwyć uchwyty. Możesz użyć chwytu nachwytem, podchwytem lub neutralnym, w zależności od tego, którą część pleców chcesz mocniej angażować.
3. Oderwij drążek od stojaka i wyciągnij ramiona przed siebie. To Twoja pozycja startowa.
4. Robiąc wydech, powoli ciągnij ciężar w górę i mocno napnij plecy na szczycie ruchu. Wskazówka: trzymaj ramiona od barku do łokcia jak najbliżej tułowia przez cały ruch, aby lepiej angażować mięśnie pleców. Nie odrywaj też ciała od poduszki i nie używaj bicepsów do podnoszenia ciężaru.
5. Po sekundzie napięcia na szczycie ruchu, robiąc wdech, powoli opuść ciężar do pozycji startowej.
6. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Lying_T-Bar_Row/0.jpg', 'free_exercise_db'),
  ('lying-triceps-press', 'Wyciskanie francuskie tricepsów w leżeniu', 'Lying Triceps Press', 'motor_coach', 'intermediate', array['Siłowe', 'Triceps'], 'Wariant ćwiczenia francuskiego, w którym sztangę chwyta się z podłogi za głową. Opuszczasz ją aż dotknie czoła, pracując tylko przedramionami i mocno angażując triceps.', '1. Połóż się na płaskiej ławce, mając za głową na podłodze gryf Ez (preferowany) lub prosty sztangę, ze stopami opartymi o podłogę.
2. Chwyć drążek za sobą średnim chwytem nachwytem (nachwytem) i unieś go przed siebie na wyciągniętych ramionach. Wskazówka: ramiona powinny być prostopadłe do tułowia i podłogi. Łokcie powinny być blisko ciała. To pozycja startowa.
3. Robiąc wdech, powoli opuszczaj ciężar, aż drążek lekko dotknie Twojego czoła, utrzymując ramiona od barku do łokcia i łokcie nieruchomo.
4. W tym punkcie użyj tricepsów, by wrócić ciężarem do pozycji startowej, robiąc wydech.
5. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Lying_Triceps_Press/0.jpg', 'free_exercise_db'),
  ('machine-bench-press', 'Wyciskanie na maszynie (chest press)', 'Machine Bench Press', 'motor_coach', 'beginner', array['Siłowe', 'Klatka piersiowa'], 'Wyciskanie klatki piersiowej na maszynie typu chest press. Siedzisz i wypychasz uchwyty od klatki piersiowej, napinając mięśnie piersiowe — maszyna prowadzi ruch, więc jest bezpieczna bez asekuracji.', '1. Usiądź na maszynie do wyciskania i wybierz ciężar.
2. Wejdź stopą na dźwignię maszyny, ponieważ pomoże Ci ona doprowadzić uchwyty do przodu, tak abyś mógł je chwycić i całkowicie wyprostować ramiona.
3. Chwyć uchwyty chwytem nachwytem i unieś łokcie tak, by ramiona od barku do łokcia były równolegle do podłogi po bokach tułowia. Wskazówka: przedramiona będą skierowane do przodu, ponieważ trzymasz uchwyty. Gdy dociągniesz uchwyty do przodu i wyprostujesz ramiona, będziesz w pozycji startowej.
4. Teraz przyciągnij uchwyty w swoją stronę, robiąc wdech.
5. Wypchnij uchwyty od siebie, napinając mięśnie piersiowe i robiąc wydech. Utrzymaj napięcie przez sekundę przed powrotem do pozycji startowej.
6. Powtórz zalecaną liczbę powtórzeń.
7. Na koniec wejdź ponownie na dźwignię i powoli wróć uchwytami na miejsce.', NULL, 'free-exercise-db/Machine_Bench_Press/0.jpg', 'free_exercise_db'),
  ('machine-bicep-curl', 'Uginanie ramion na maszynie', 'Machine Bicep Curl', 'motor_coach', 'beginner', array['Siłowe', 'Biceps'], 'Izolowane uginanie bicepsów na maszynie z podparciem ramion na poduszkach. Zgina się łokcie, przyciągając przedramię do ramienia, z ciągłym napięciem mięśnia przez całą serię.', '1. Dostosuj wysokość siedziska i wybierz ciężar. Oprzyj górne ramiona na poduszkach i chwyć uchwyty. To Twoja pozycja startowa.
2. Wykonaj ruch zginając łokieć i przyciągając przedramię w stronę ramienia.
3. Zatrzymaj się na szczycie ruchu, a potem powoli wróć ciężarem do pozycji startowej.
4. Unikaj odkładania ciężaru całkiem do zderzaków do końca serii, aby utrzymać napięcie trenowanych mięśni.', NULL, 'free-exercise-db/Machine_Bicep_Curl/0.jpg', 'free_exercise_db'),
  ('machine-preacher-curls', 'Uginanie ramion na modlitewniku maszynowym', 'Machine Preacher Curls', 'motor_coach', 'beginner', array['Siłowe', 'Biceps'], 'Uginanie bicepsów na maszynie typu modlitewnik, z ramionami opartymi na pochyłej poduszce. Podparcie wymusza czystą technikę i pełną izolację bicepsa.', '1. Usiądź na maszynie do uginania na modlitewniku i wybierz ciężar.
2. Połóż tył górnych ramion (tricepsy) na poduszce modlitewnika i chwyć uchwyty chwytem podchwytem (dłonie do góry). Wskazówka: upewnij się, że układając ramiona na poduszce trzymasz łokcie blisko ciała. To Twoja pozycja startowa.
3. Teraz unieś uchwyty robiąc wydech i napinając bicepsy. Na szczycie pozycji koniecznie utrzymaj napięcie przez sekundę. Wskazówka: ruszać się powinny tylko przedramiona. Ramiona od barku do łokcia muszą pozostać nieruchome i na poduszce przez cały czas.
4. Powoli opuść uchwyty do pozycji startowej, robiąc wdech.
5. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Machine_Preacher_Curls/0.jpg', 'free_exercise_db'),
  ('machine-shoulder-military-press', 'Wyciskanie żołnierskie na maszynie', 'Machine Shoulder (Military) Press', 'motor_coach', 'beginner', array['Siłowe', 'Barki'], 'Wyciskanie barków na maszynie. Usiadłeś wypychasz uchwyty ponad głowę, prostując ramiona — maszyna prowadzi tor ruchu i zapewnia bezpieczeństwo.', '1. Usiądź na maszynie do wyciskania nad głowę i wybierz ciężar.
2. Chwyć uchwyty po bokach, trzymając łokcie zgięte i w linii z tułowiem. To Twoja pozycja startowa.
3. Teraz unieś uchwyty robiąc wydech i całkowicie wyprostuj ramiona. Na szczycie pozycji koniecznie utrzymaj napięcie przez sekundę.
4. Powoli opuść uchwyty do pozycji startowej, robiąc wdech.
5. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Machine_Shoulder_Military_Press/0.jpg', 'free_exercise_db'),
  ('machine-triceps-extension', 'Prostowanie ramion na maszynie (triceps)', 'Machine Triceps Extension', 'motor_coach', 'beginner', array['Siłowe', 'Triceps'], 'Izolowane ćwiczenie tricepsa na maszynie z podparciem górnych ramion na poduszkach. Prostujesz łokieć, odsuwając przedramię od ramienia, utrzymując stałe napięcie mięśnia.', '1. Dostosuj wysokość siedziska i wybierz ciężar. Oprzyj górne ramiona na poduszkach i chwyć uchwyty. To Twoja pozycja startowa.
2. Wykonaj ruch prostując łokieć i odsuwając przedramię od ramienia.
3. Zatrzymaj się na końcu ruchu, a potem powoli wróć ciężarem do pozycji startowej.
4. Unikaj odkładania ciężaru całkiem do zderzaków do końca serii, aby utrzymać napięcie trenowanych mięśni.', NULL, 'free-exercise-db/Machine_Triceps_Extension/0.jpg', 'free_exercise_db'),
  ('medicine-ball-chest-pass', 'Podanie piłki lekarskiej z klatki piersiowej', 'Medicine Ball Chest Pass', 'motor_coach', 'beginner', array['Plyometryka', 'Klatka piersiowa'], 'Eksplozywne podanie piłki lekarskiej oburącz od klatki piersiowej do partnera (lub o ścianę). Buduje moc górnej części ciała, szczególnie przydatną w sportach walki i rzutach.', '1. Do tego ćwiczenia potrzebujesz partnera. Bez niego ruch można wykonywać o ścianę.
2. Stań twarzą do partnera, trzymając piłkę lekarską przy tułowiu oburącz.
3. Przyciągnij piłkę do klatki piersiowej, a potem odwróć ruch, wyprostowując ramiona w łokciach. W zastosowaniach sportowych możesz wykonać krok podczas rzutu.
4. Twój partner powinien złapać piłkę i odesłać ją do Ciebie.
5. Przyjmij rzut oburącz na wysokości klatki piersiowej.', NULL, 'free-exercise-db/Medicine_Ball_Chest_Pass/0.jpg', 'free_exercise_db'),
  ('medicine-ball-full-twist', 'Pełny skręt z piłką lekarską', 'Medicine Ball Full Twist', 'motor_coach', 'beginner', array['Plyometryka', 'Brzuch'], 'Ćwiczenie rotacyjne wykonywane z partnerem plecami do pleców. Obaj skręcają tułów w tę samą stronę i przekazują sobie piłkę, budując moc mięśni skośnych brzucha.', '1. Do tego ćwiczenia potrzebujesz piłki lekarskiej i partnera. Stańcie plecami do siebie w odstępie ok. 60–90 cm. To Wasza pozycja startowa.
2. Trzymaj piłkę przed tułowiem. Otwórz biodra i obróć barki jednocześnie z partnerem.
3. Aby wykonać pełny obrót, Ty i Twój partner powinniście skręcać się w tym samym kierunku, np. przeciwnym do wskazówek zegara.
4. Podaj piłkę partnerowi, a potem oboje możecie skręcić się w przeciwnym kierunku i powtórzyć procedurę.', NULL, 'free-exercise-db/Medicine_Ball_Full_Twist/0.jpg', 'free_exercise_db'),
  ('medicine-ball-scoop-throw', 'Rzut piłki lekarskiej zza pleców (scoop throw)', 'Medicine Ball Scoop Throw', 'motor_coach', 'beginner', array['Plyometryka', 'Barki'], 'Eksplozywny rzut piłki lekarskiej za siebie. Z pozycji półprzysiadu wybijasz się w górę, przerzucając piłkę nad głowę jak najdalej za siebie — świetne ćwiczenie mocy całego ciała.', '1. Przyjmij postawę półprzysiadu z piłką lekarską w rękach. Ramiona powinny zwisać tak, by piłka była blisko Twoich stóp.
2. Zacznij od wypchnięcia bioder do przodu, wybijając się nogami i skacząc w górę.
3. Jednocześnie zamachnij się ramionami w górę i nad głowę, trzymając je wyprostowane, i wypuść piłkę na szczycie ruchu. Celem jest rzucenie piłki jak najdalej za siebie.', NULL, 'free-exercise-db/Medicine_Ball_Scoop_Throw/0.jpg', 'free_exercise_db'),
  ('middle-back-shrug', 'Ściąganie łopatek w leżeniu na ławce skośnej (środek pleców)', 'Middle Back Shrug', 'motor_coach', 'intermediate', array['Siłowe', 'Środek pleców'], 'Ćwiczenie na środkową część pleców polegające na ściągnięciu łopatek w leżeniu na brzuchu na ławce skośnej, z hantlami zwisającymi swobodnie. Ruch przypomina odwrotne objęcie.', '1. Połóż się twarzą w dół na ławce skośnej, trzymając hantlę w każdej ręce. Ramiona powinny być całkowicie wyprostowane i zwisać w dół, a dłonie skierowane do siebie. To Twoja pozycja startowa.
2. Robiąc wydech, ściągnij łopatki do siebie i utrzymaj napięcie przez pełną sekundę. Wskazówka: ten ruch jest dokładnie taki sam jak odwrócone objęcie, albo próba wykonania wznosów na tylny akton, gdybyś nie miał ramion.
3. Robiąc wdech, wróć do pozycji startowej.
4. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Middle_Back_Shrug/0.jpg', 'free_exercise_db'),
  ('middle-back-stretch', 'Rozciąganie środkowej części pleców', 'Middle Back Stretch', 'motor_coach', 'beginner', array['Rozciąganie', 'Środek pleców'], 'Proste rozciąganie środkowych partii pleców w staniu. Kręcisz się tułowiem w boki, aż poczujesz rozciągnięcie, i przytrzymujesz pozycję kilka sekund na każdą stronę.', '1. Stań tak, aby stopy były na szerokość barków, a dłonie spoczywały na biodrach.
2. Skręć się w pasie, aż poczujesz rozciągnięcie. Przytrzymaj 10–15 sekund, a potem skręć się na drugą stronę.', NULL, 'free-exercise-db/Middle_Back_Stretch/0.jpg', 'free_exercise_db'),
  ('mixed-grip-chin', 'Podciąganie chwytem mieszanym', 'Mixed Grip Chin', 'motor_coach', 'advanced', array['Siłowe', 'Środek pleców'], 'Podciąganie na drążku chwytem mieszanym — jedna dłoń nachwytem, druga podchwytem. Wymusza silniejszą pracę latissimusów po stronie podchwytu; w kolejnej serii zmieniasz ułożenie dłoni.', '1. Chwytając drążek do podciągania w rozstawie o ok. 2,5 cm szerszym niż szerokość barków, ustaw dłonie jednej ręki dłońmi do przodu, a drugiej — dłońmi ku sobie. To Twoja pozycja startowa.
2. Teraz zacznij podciągać się robiąc wydech. Wskazówka: ręką ułożoną podchwytem skup się na pracy mięśni pleców, wykonując ruch. Łokieć tej ręki powinien pozostać blisko tułowia. Drugą ręką, ułożoną nachwytem, łokcie będą odsunięte, ale w linii z tułowiem. Skup się na używaniu najszerszego mięśnia pleców do podciągnięcia ciała.
3. Po sekundzie napięcia na górze zacznij powoli schodzić robiąc wdech.
4. Powtórz zalecaną liczbę powtórzeń.
5. W kolejnej serii zmień chwyt: jeśli prawa ręka była dłonią ku sobie, a lewa dłonią do przodu, w następnym seria prawej ręce daj chwyt nachwytem, a lewej podchwyt.', NULL, 'free-exercise-db/Mixed_Grip_Chin/0.jpg', 'free_exercise_db'),
  ('monster-walk', 'Spacer potwora (monster walk)', 'Monster Walk', 'motor_coach', 'beginner', array['Siłowe', 'Odwodziciele'], 'Chód boczno-krokowy z gumami oporowymi na kolanach i kostkach. Kroczesz drobnymi kroki do przodu i do tyłu, utrzymując stałe napięcie gumy — świetna aktywacja pośladków.', '1. Załóż gumę oporową na obie kostki, a drugą na oba kolana. Napięcie powinno być takie, by guma była napięta, gdy stopy są na szerokość barków.
2. Zacznij od krótkich kroków do przodu, naprzemiennie lewą i prawą stopą.
3. Po kilku krokach zrzuć dokładnie odwrotnie i wróć tyłem do miejsca startu.', NULL, 'free-exercise-db/Monster_Walk/0.jpg', 'free_exercise_db'),
  ('mountain-climbers', 'Wspinacz górski (mountain climbers)', 'Mountain Climbers', 'motor_coach', 'beginner', array['Plyometryka', 'Uda'], 'Dynamiczne ćwiczenie kondycyjne w podporze przodem. Naprzemiennie przyciągasz kolano pod klatkę piersiową, jakbyś wspinał się na górę — intensywnie angażuje core i spala kalorie.', '1. Przyjmij pozycję podporu przodem, z ciężarem wspartym na dłoniach i palcach stóp. Zginając kolano i biodro, przyciągnij jedną nogę, aż kolano znajdzie się mniej więcej pod biodrem. To Twoja pozycja startowa.
2. Eksplozywnie zamień pozycje nóg: wyprostuj zgiętą nogę aż będzie prosta i podparta palcem stopy, przyciągając drugą stopę w górę z zgiętym biodrem i kolanem. Powtarzaj naprzemiennie przez 20–30 sekund.', NULL, 'free-exercise-db/Mountain_Climbers/0.jpg', 'free_exercise_db'),
  ('moving-claw-series', 'Seria „claw” w biegu (technika sprintu)', 'Moving Claw Series', 'motor_coach', 'beginner', array['Plyometryka', 'Dwugłowe uda'], 'Ćwiczenie techniczne przygotowujące formę biegu do sprintu. Polega na aktywnym zginaniu kolana i „kopnięciu” w pośladek przy wydłużeniu biodra, z energicznym odbiciem od ziemi i pracą ramion.', '1. Ten ruch pomaga przygotować formę biegu, abyś mógł osiągnąć sukces w sprincie. Podczas biegu pamiętaj o zgięciu kolana, celując w kopnięcie piętą w pośladek, gdy biodro się wydłuża.
2. Załaduj ponownie mięsień czworogłowy uda, gdy noga przesuwa się do przodu, atakując podłoże w następnym kroku.
3. Upewnij się, że podczas biegu blokujesz ramionami, bijąc nimi naprzemiennie w szybkim tempie 1-2.', NULL, 'free-exercise-db/Moving_Claw_Series/0.jpg', 'free_exercise_db'),
  ('muscle-snatch', 'Muscle snatch (rwanie bez podrzutu)', 'Muscle Snatch', 'motor_coach', 'intermediate', array['Podnoszenie ciężarów', 'Dwugłowe uda'], 'Olimpijska wersja rwania bez podskoku — sztanga przechodzi od ud nad głowę wyłącznie siłą ramion i bioder. Ćwiczenie rozwija eksplozywność i technikę podniesienia ciężaru nad głowę.', '1. Zacznij z załadowaną sztangą trzymaną w połowie ud na szerokim chwycie. Stopy powinny być dokładnie pod biodrami, lekko skręcone na zewnątrz według potrzeby. Obniż biodra, klatka piersiowa uniesiona, wzrok skierowany do przodu. Barki powinny być tuż przed drążkiem. To pozycja startowa.
2. Rozpocznij ciągnięcie, mocno odpychając się przednią częścią pięt i unosząc sztangę. Przejdź do drugiego ciągu, wydłużając biodra, kolana i kostki, wypychając sztangę w górę jak najszybciej. Drążek powinien być blisko ciała.
3. Kontynuuj unoszenie sztangi do pozycji nad głowę, nie zginając ponownie kolan.', NULL, 'free-exercise-db/Muscle_Snatch/0.jpg', 'free_exercise_db'),
  ('muscle-up', 'Muscle up (wyjście siłowe na kółkach)', 'Muscle Up', 'motor_coach', 'intermediate', array['Siłowe', 'Najszersze grzbietu'], 'Zaawansowane ćwiczenie gimnastyczne łączące podciągnięcie z dipyem na kółkach. Podciągasz się, przenosisz klatkę nad kółka i wypychasz się do góry — wymagający test siły i koordynacji.', '1. Chwyć kółka chwytem fałszywym (false grip), z podstawą dłoni na wierzchu kółek. Rozpocznij podciągnięcie, przyciągając łokcie w dół w stronę bioder i zginając je.
2. Gdy osiągniesz szczytową pozycję podciągnięcia, przyciągnij kółka do pach, przesuwając barki do przodu i pozwalając łoktom przejść prosto do tyłu za siebie. To ustawia Cię we właściwej pozycji do kontynuowania fazy dipa.
3. Utrzymując kontrolę i stabilność, wyprostuj łokcie, kończąc ruch.
4. Schodząc w dół, zachowaj ostrożność.', NULL, 'free-exercise-db/Muscle_Up/0.jpg', 'free_exercise_db'),
  ('narrow-stance-hack-squats', 'Przysiad hack squat wąskim rozstawem', 'Narrow Stance Hack Squats', 'motor_coach', 'intermediate', array['Siłowe', 'Uda'], 'Wariant przysiadu hack squat w maszynie z wąskim rozstawem stóp na platformie. Mocniej angażuje zewnętrzną część czworogłowych ud przy prowadzeniu tułowia po sztywnym torze maszyny.', '1. Oprzyj tył tułowia o oparcie maszyny i zahacz barkami pod poduszki barkowe.
2. Ustaw nogi na platformie wąskim rozstawie mniejszym niż szerokość barków, z palcami lekko skręconymi na zewnątrz. Stopy powinny być ok. 7-8 cm od siebie lub bliżej. Wskazówka: całą trzymaj głowę uniesioną i utrzymuj plecy na oparciu przez cały czas.
3. Połóż ręce na uchwytach bocznych maszyny i zwolnij blokady bezpieczeństwa (w większości konstrukcji robi się to przekręcając uchwyty boczne z pozycji skierowanej do przodu na pozycję skośną).
4. Teraz wyprostuj nogi, nie blokując kolan. To Twoja pozycja startowa.
5. Zacznij powoli opuszczać sanie, zginając kolana i zachowując wyprostowaną postawę z uniesioną głową (plecy cały czas na oparciu). Schodź, aż kąt między udami a łydkami stanie się nieco mniejszy niż 90 stopni (czyli punkt, w którym uda są poniżej równoległości do podłogi). Robiąc wdech wykonuj tę część ruchu.
6. Zacznij unosić sanie robiąc wydech, odpychając się od platformy głównie piętami, ponownie prostując nogi i wracając do pozycji startowej.
7. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Narrow_Stance_Hack_Squats/0.jpg', 'free_exercise_db'),
  ('narrow-stance-leg-press', 'Wypychanie na suwnicy wąskim rozstawem', 'Narrow Stance Leg Press', 'motor_coach', 'intermediate', array['Siłowe', 'Uda'], 'Wariant wypychania ciężaru na suwnicy z wąskim rozstawem stóp na platformie. Mocniej obciąża zewnętrzne partie czworogłowych ud i mięsień obszerny boczny.', '1. Korzystając z maszyny do wypychania, usiądź na niej i połóż nogi na platformie bezpośrednio przed sobą w rozstawie węższym niż szerokość barków, z palcami lekko skręconymi na zewnątrz. Stopy powinny być oddalone ok. 7-8 cm lub mniej. Wskazówka: całą trzymaj głowę uniesioną i utrzymuj plecy na oparciu przez cały czas.
2. Zwolnij blokady bezpieczeństwa trzymające ważoną platformę i wypchnij platformę aż do góry, aż nogi będą całkowicie wyprostowane przed Tobą. Wskazówka: upewnij się, że nie blokujesz kolan. Twój tułów i nogi powinny tworzyć idealny kąt 90 stopni. To Twoja pozycja startowa.
3. Robiąc wdech, powoli opuszczaj platformę, aż górna i dolna część nóg utworzą kąt 90 stopni.
4. Odpychając się głównie piętami i używając mięśni czworogłowych uda, wróć do pozycji startowej robiąc wydech.
5. Powtórz zalecaną liczbę powtórzeń i koniecznie poprawnie załóż bolce bezpieczeństwa po zakończeniu. Nie chcesz, aby platforma spadła na Ciebie w pełni załadowana.', NULL, 'free-exercise-db/Narrow_Stance_Leg_Press/0.jpg', 'free_exercise_db'),
  ('narrow-stance-squats', 'Przysiad ze sztangą wąskim rozstawem', 'Narrow Stance Squats', 'motor_coach', 'intermediate', array['Siłowe', 'Uda'], 'Przysiad ze sztangą na karku wykonywany z wąskim rozstawem stóp. Mocniej angażuje zewnętrzną część ud; wymaga dobrej mobilności i dbałości, by kolana nie schodziły poza palce stóp.', '1. To ćwiczenie najlepiej wykonywać w klatce do przysiadów ze względów bezpieczeństwa. Na początek ustaw drążek na stojaku najlepiej dopasowanym do Twojego wzrostu. Gdy wybierzesz właściwą wysokość i załadujesz sztangę, wejdź pod nią i oprzyj o nią tył barków (nieco poniżej karku).
2. Trzymaj drążek oburącz po bokach i oderwij go ze stojaka, najpierw odpychając się nogami, a jednocześnie prostując tułów.
3. Odejdź od stojaka i ustaw nogi w rozstawie węższym niż szerokość barków, z palcami lekko skręconymi na zewnątrz. Stopy powinny być ok. 7–15 cm od siebie. Całą trzymaj głowę uniesioną (patrzenie w dół zaburzy równowagę) i zachowaj proste plecy. To Twoja pozycja startowa. (Uwaga: w tym opisie używamy średniego rozstawu opisanego powyżej, który angażuje całość mięśni; możesz jednak wybrać dowolne z trzech ustawień omawianych w sekcji o pozycji stóp).
4. Zacznij powoli opuszczać sztangę, zginając kolana i zachowując wyprostowaną postawę z uniesioną głową. Schodź, aż kąt między udami a łydkami stanie się nieco mniejszy niż 90 stopni (czyli punkt, w którym uda są poniżej równoległości do podłogi). Wykonując tę część ruchu, weź wdech. Wskazówka: jeśli wykonałeś ćwiczenie poprawnie, przednia część kolan powinna tworzyć wyobrażoną prostą z palcami stóp, prostopadłą do przodu. Jeśli kolana wychodzą poza tę linię (jeśli są dalej niż palce), to nadmiernie obciążasz kolano i ćwiczenie jest wykonywane niepoprawnie.
5. Zacznij unosić sztangę robiąc wydech, odpychając się od podłogi głównie piętami, ponownie prostując nogi i wracając do pozycji startowej.
6. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Narrow_Stance_Squats/0.jpg', 'free_exercise_db'),
  ('natural-glute-ham-raise', 'Naturalne prostowanie z gięciem (glute ham raise)', 'Natural Glute Ham Raise', 'motor_coach', 'intermediate', array['Siłowe', 'Dwugłowe uda'], 'Wymagające ćwiczenie na tylne uda i pośladki bez specjalnej maszyny — klękasz z kostkami zablokowanymi pod wałkiem i opuszczasz się do przodu, a potem wracasz siłą dwugłowych uda i pośladków.', '1. Korzystając z wałka nóg maszyny do ściągania drążka albo modlitewnika, ustaw się tak, by kostki były pod wałkiem, kolana na siedzisku, a Ty twarzą odwrócona od maszyny. Powinieneś stać wyprostowany, utrzymując dobrą postawę.
2. To będzie Twoja pozycja startowa. Opuszczaj ciało kontrolowanym ruchem, aż kolana będą prawie całkowicie wyprostowane.
3. Pozostając pod kontrolą, unieś ciało z powrotem do pozycji startowej.
4. Jeśli nie jesteś w stanie wykonać pełnego powtórzenia, użyj gumy, partnera albo odbicia z podwyższenia, aby pomóc sobie w wykonaniu powtórzenia.', NULL, 'free-exercise-db/Natural_Glute_Ham_Raise/0.jpg', 'free_exercise_db'),
  ('neck-press', 'Wyciskanie leżąc „na szyję”', 'Neck Press', 'motor_coach', 'intermediate', array['Siłowe', 'Klatka piersiowa'], 'Ekstremalny wariant wyciskania leżąc, w którym opuszczasz sztangę na gardło/szyję zamiast na klatkę piersiową. Ćwiczenie dla bardzo zaawansowanych, mocno angażujące górne partie klatki.', '1. Połóż się na płaskiej ławce. Używając średniego chwytu (takiego, który tworzy kąt 90 stopni między przedramionami a ramionami w środkowej fazie ruchu), zdejmij sztangę ze stojaka i trzymaj ją prosto nad szyją z wyprostowanymi ramionami. To Twoja pozycja startowa.
2. Robiąc wdech, powoli opuszczaj sztangę, aż poczujesz ją na szyi.
3. Po sekundzie pauzy wróć sztangą do pozycji startowej robiąc wydech, wypychając ją mięśniami klatki piersiowej. Zablokuj ramiona i ściśnij klatkę w pozycji napiętej, przytrzymaj sekundę, a potem zacznij znowu powoli schodzić. Wskazówka: zejście powinno zajmować co najmniej dwa razy więcej czasu niż wypchnięcie.
4. Powtórz ruch przez zalecaną liczbę powtórzeń.
5. Po zakończeniu odłóż sztangę z powrotem na stojak.', NULL, 'free-exercise-db/Neck_Press/0.jpg', 'free_exercise_db'),
  ('neck-smr', 'Automasaż szyi rolerem (SMR)', 'Neck-SMR', 'motor_coach', 'intermediate', array['Rozciąganie', 'Kark'], 'Technika samomasażu mięśni szyi (SMR) przy użyciu rollera lub wałka. Rolujesz mięśnie po bokach kręgosłupa szyjnego, zatrzymując się na punktach napięcia.', '1. Używając rollera do masażu albo wałka kuchennego, umieść roller za głową, przyciskając go do szyi. Upewnij się, że nie przykładasz rollera bezpośrednio do kręgosłupa — obróć go lekko tak, by dociskał mięśnie po bokach kręgosłupa. To Twoja pozycja startowa.
2. Zaczynając od góry szyi, powoli tocz roller w dół po mięśniach szyi, zatrzymując się na punktach napięcia na 10–30 sekund.', NULL, 'free-exercise-db/Neck-SMR/0.jpg', 'free_exercise_db'),
  ('oblique-crunches', 'Skręty na mięśnie skośne brzucha', 'Oblique Crunches', 'motor_coach', 'beginner', array['Siłowe', 'Brzuch'], 'Skręty brzucha angażujące mięśnie skośne. Leżąc na plecach unosisz ramię i skręcasz tułów, aż łokieć dotknie przeciwnego kolana — naprzemiennie na obie strony.', '1. Połóż się płasko na podłodze z dolną częścią pleców dociśniętą do ziemi. Do tego ćwiczenia musisz położyć jedną rękę przy głowie, a drugą z boku opartą o podłogę.
2. Upewnij się, że stopy są uniesione i oparte o płaską powierzchnię.
3. Teraz unieś ramię tej strony, której dłoń dotyka głowy.
4. Po prostu unieś ramię i ciało w górę, aż dotkniesz kolana. Przykładowo, jeśli prawa dłoń jest przy głowie, chcesz unieść ciało w górę, aż prawy łokieć dotknie lewego kolana. Ten sam wariant można zastosować odwrotnie, używając lewego łokcia do dotknięcia prawego kolana.
5. Gdy kolano dotknie łokcia, opuść ciało, aż wrócisz do pozycji startowej.
6. Pamiętaj, aby oddychać w trakcie fazy ekscentrycznej (opuszczania) ćwiczenia i wydychać powietrze podczas fazy koncentrycznej (unoszenia) ćwiczenia.
7. Kontynuuj naprzemiennie w ten sposób, aż wykonasz wszystkie zalecane powtórzenia na każdą stronę.', NULL, 'free-exercise-db/Oblique_Crunches/0.jpg', 'free_exercise_db'),
  ('oblique-crunches-on-the-floor', 'Skręty skośne na boku na podłodze', 'Oblique Crunches - On The Floor', 'motor_coach', 'beginner', array['Siłowe', 'Brzuch'], 'Skręty mięśni skośnych brzucha wykonywane leżąc na boku. Unosisz łokieć w górę, skręcając tułów bokiem — świetna izolacja mięśni skośnych bez sprzętu.', '1. Zacznij od położenia się na prawym boku z nogami jedna na drugiej. Upewnij się, że kolana są lekko zgięte.
2. Połóż lewą rękę za głową.
3. Gdy jesteś w tej pozycji, zacznij unosić lewy łokieć w górę, jak przy normalnym skręcie brzucha, ale tym razem główny nacisk jest na mięśnie skośne.
4. Skręć się jak najwyżej, utrzymaj napięcie przez sekundę, a potem powoli opadnij z powrotem do pozycji startowej.
5. Pamiętaj, aby oddychać w trakcie fazy ekscentrycznej (opuszczania) ćwiczenia i wydychać powietrze podczas fazy koncentrycznej (unoszenia) ćwiczenia.', NULL, 'free-exercise-db/Oblique_Crunches_-_On_The_Floor/0.jpg', 'free_exercise_db'),
  ('olympic-squat', 'Przysiad olimpijski', 'Olympic Squat', 'motor_coach', 'intermediate', array['Podnoszenie ciężarów', 'Uda'], 'Wariant przysiadu ze sztangą charakterystyczny dla podnoszenia ciężarów: tułów niemal pionowy, kolana mocno wysunięte do przodu, schodzenie aż do styku ud z łydkami. Mocno angażuje czworogłowe uda.', '1. Zacznij ze sztangą podpartą na szczycie mięśnia czworobocznego (trapeziusa). Klatka piersiowa uniesiona, głowa skierowana do przodu. Przyjmij postawę na szerokość bioder ze stopami skręconymi na zewnątrz według potrzeby.
2. Opuszczaj ciało zginając kolana, starając się jak najmniej cofać biodra. To wymaga wysuwania kolan do przodu — pilnuj, by pozostawały w linii ze stopami. Celem jest utrzymanie tułowia maksymalnie pionowo. Zejdź aż do samego dołu, utrzymując ciężar na przedniej części pięty.
3. W momencie kontaktu górnej części nóg z dolną, odwróć ruch, wypychając ciężar w górę.', NULL, 'free-exercise-db/Olympic_Squat/0.jpg', 'free_exercise_db'),
  ('on-your-back-quad-stretch', 'Rozciąganie czworogłowego uda na plecach', 'On-Your-Back Quad Stretch', 'motor_coach', 'beginner', array['Rozciąganie', 'Uda'], 'Rozciąganie przodu uda wykonywane na plecach na ławce lub stopniu. Chwytasz stopę i przyciągasz ją w dół, opcjonalnie unosząc biodro, aby dodatkowo rozciągnąć zginacz biodra.', '1. Połóż się na płaskiej ławce lub stopniu i zwieś jedną nogę oraz ramię poza jego krawędź.
2. Zegnij kolano i chwyć górną część stopy. Rób to ostrożnie, żeby nie wyginać dolnych pleców.
3. Ściągnij pępek w stronę kręgosłupa, by pozostać neutralnym. Dociśnij stopę w dół i w swoją dłoń. Aby dodać rozciąganie biodra, unieś biodro trzymanej nogi ku sufitowi.
4. Zmień strony.', NULL, 'free-exercise-db/On-Your-Back_Quad_Stretch/0.jpg', 'free_exercise_db'),
  ('on-your-side-quad-stretch', 'Rozciąganie czworogłowego uda na boku', 'On Your Side Quad Stretch', 'motor_coach', 'beginner', array['Rozciąganie', 'Uda'], 'Proste rozciąganie przodu uda wykonywane leżąc na boku. Zginasz kolano i przyciągasz stopę do pośladka, dociągając biodro do przodu dla pogłębienia rozciągnięcia.', '1. Zacznij od położenia się na prawym boku, z prawym kolanem zgiętym pod kątem 90 stopni, opartym na podłodze przed Tobą (to stabilizuje tułów).
2. Zegnij lewe kolano za sobą i złap lewą stopę lewą ręką. Aby rozciągnąć zginacz biodra, wypchnij lewe biodro do przodu, jednocześnie dociągając lewą stopę do tyłu w swoją dłoń. Zmień strony.', NULL, 'free-exercise-db/On_Your_Side_Quad_Stretch/0.jpg', 'free_exercise_db'),
  ('one-arm-against-wall', 'Rozciąganie latissimusów jedną ręką o ścianę', 'One Arm Against Wall', 'motor_coach', 'beginner', array['Rozciąganie', 'Najszersze grzbietu'], 'Proste rozciąganie najszerszego mięśnia pleców. Opierasz zgięte ramię o ścianę lub framugę i pochylasz się w jego stronę, aż poczujesz rozciągnięcie wzdłuż boku pleców.', '1. W pozycji stojącej oprzyj zgięte ramię o ścianę lub framugę drzwi.
2. Powoli pochyl się w stronę ramienia, aż poczujesz rozciągnięcie w latissimusach.', NULL, 'free-exercise-db/One_Arm_Against_Wall/0.jpg', 'free_exercise_db'),
  ('one-arm-chin-up', 'Podciąganie jednorącz (z asystą ręcznika)', 'One Arm Chin-Up', 'motor_coach', 'advanced', array['Siłowe', 'Środek pleców'], 'Podciąganie jedną ręką na drążku z pomocą ręcznika trzymanego drugą ręką. Ekstremalnie trudne ćwiczenie na siłę chwytu i pleców; w kolejnych seriach zmieniasz strony.', '1. Do tego ćwiczenia zacznij od założenia ręcznika przez drążek do podciągania.
2. Chwyć drążek dłonią skierowaną ku sobie. Jedna ręka będzie trzymać drążek do podciągania, a druga — ręcznik.
3. Cofnij tułów o ok. 30 stopni, tworząc wygięcie w dolnych plecach i wypychając klatkę piersiową do przodu. To Twoja pozycja startowa.
4. Podciągnij tułów w górę, aż drążek dotknie górnej części klatki piersiowej, przyciągając barki i górne ramiona w dół i do tyłu. Robiąc tę część ruchu, wypuszczaj powietrze. Wskazówka: skup się na ściskaniu mięśni pleców, gdy osiągniesz pełną pozycję napiętą. Górna część tułowia powinna pozostać nieruchoma podczas poruszania się w przestrzeni, a ruszać się mają tylko ramiona. Przedramiona nie powinny wykonywać żadnej innej pracy niż trzymanie drążka.
5. Po sekundzie w pozycji napiętej zacznij nabierać powietrze i powoli opuszczaj tułów do pozycji startowej, gdy ramiona są całkowicie wyprostowane, a mięśnie najszersze pleców całkowicie rozciągnięte.
6. Powtórz ten ruch przez zalecaną liczbę powtórzeń.
7. Zmień ramiona i powtórz ruch.', NULL, 'free-exercise-db/One_Arm_Chin-Up/0.jpg', 'free_exercise_db'),
  ('one-arm-dumbbell-bench-press', 'Wyciskanie hantli jednorącz na ławce płaskiej', 'One Arm Dumbbell Bench Press', 'motor_coach', 'beginner', array['Siłowe', 'Klatka piersiowa'], 'Wyciskanie hantli pojedynczą ręką leżąc na ławce. Wymusza mocną pracę stabilizatorów core i barku; wolną ręką możesz pomagać w balansowaniu hantlą.', '1. Połóż się na płaskiej ławce z hantlą w jednej ręce spoczywającą na udzie.
2. Używając uda, by pomóc unieść hantlę, podrzuć ją tak, abyś mógł trzymać ją przed sobą na szerokość barków. Użyj ręki, którą nie podnosisz, aby pomóc właściwie ustawić hantlę nad sobą.
3. Gdy jesteś na szerokości barków, obróć nadgarstek do przodu tak, by dłoń była skierowana od Ciebie. To Twoja pozycja startowa.
4. Powoli opuść ciężar na bok robiąc wdech. Zachowuj pełną kontrolę nad hantlą przez cały czas. Wskazówka: użyj ręki, którą nie podnosisz, aby pomóc utrzymać równowagę hantli, ponieważ na początku możesz mieć trochę problemów. Używaj niewspółpracującej ręki tylko wtedy, gdy jest to potrzebne. W przeciwnym razie trzymaj ją opuszczoną z boku.
5. Robiąc wydech, wypchnij hantlę w górę używając mięśni piersiowych. Zablokuj ramiona w pozycji napiętej, ściśnij klatkę piersiową, przytrzymaj sekundę, a potem zacznij schodzić powoli. Wskazówka: zejście powinno zajmować co najmniej dwa razy więcej czasu niż wypchnięcie.
6. Powtórz ruch przez zalecaną liczbę powtórzeń Twojego programu treningowego.
7. Zmień ramiona i powtórz ruch.', NULL, 'free-exercise-db/One_Arm_Dumbbell_Bench_Press/0.jpg', 'free_exercise_db'),
  ('one-arm-dumbbell-preacher-curl', 'Uginanie ramion jednorącz na modlitewniku', 'One Arm Dumbbell Preacher Curl', 'motor_coach', 'beginner', array['Siłowe', 'Biceps'], 'Izolowane uginanie bicepsa jedną ręką na modlitewniku. Ramię jest unieruchomione na pochyłej podporze, więc biceps pracuje bez możliwości oszukiwania.', '1. Chwyć hantlę prawą ręką i połóż górne ramię na modlitewniku albo ławce skośnej. Hantla powinna być trzymana na wysokość barku. To Twoja pozycja startowa.
2. Robiąc wdech, powoli opuszczaj hantlę, aż górne ramię będzie wyprostowane, a biceps całkowicie rozciągnięty.
3. Robiąc wydech, ugnij ciężar w górę siłą bicepsa, aż biceps będzie całkowicie napięty, a hantla na wysokości barku. Ponownie pamiętaj, że dla pełnego napięcia musisz unieść mały palec wyżej niż kciuk.
4. Mocno ściśnij biceps przez sekundę w pozycji napiętej i powtórz zalecaną liczbę powtórzeń.
5. Zmień ramiona i powtórz ruch.', NULL, 'free-exercise-db/One_Arm_Dumbbell_Preacher_Curl/0.jpg', 'free_exercise_db'),
  ('one-arm-dumbbell-row', 'Wiosłowanie hantlą jednorącz', 'One-Arm Dumbbell Row', 'motor_coach', 'beginner', array['Siłowe', 'Środek pleców'], 'Klasyczne wiosłowanie jednorącz w opadzie z podparciem na ławce. Ściągasz hantlę w stronę biodra, mocno napinając plecy — jedno ramię pracuje, drugie stabilizuje pozycję.', '1. Wybierz płaską ławkę i połóż po hantli na każdym jej boku.
2. Połóż prawą nogę na końcu ławki, pochyl tułów w pasie do przodu, aż górna część ciała będzie równoległa do podłogi, i oprzyj prawą dłoń na drugim końcu ławki dla podparcia.
3. Lewą ręką podnieś hantlę z podłogi i trzymaj ciężar z prostymi dolnymi plecami. Dłoń powinna być skierowana ku tułowiowi. To Twoja pozycja startowa.
4. Pociągnij opór prosto w górę do boku klatki piersiowej, trzymając ramię blisko tułowia i utrzymując nieruchomo tułów. Robiąc ten krok, wypuszczaj powietrze. Wskazówka: skup się na ściskaniu mięśni pleców, gdy osiągniesz pełną pozycję napiętą. Upewnij się też, że siła pochodzi od mięśni pleców, a nie ramion. Wreszcie — górna część tułowia musi pozostać nieruchoma, a ruszać się mają tylko ramiona. Przedramiona nie powinny wykonywać żadnej innej pracy niż trzymanie hantli, więc nie próbuj ciągnąć hantli w górę przedramionami.
5. Opuść opór prosto w dół do pozycji startowej. Wykonując ten krok, nabierz powietrza.
6. Powtórz ruch przez określoną liczbę powtórzeń.
7. Zmień strony i powtórz drugim ramieniem.', NULL, 'free-exercise-db/One-Arm_Dumbbell_Row/0.jpg', 'free_exercise_db'),
  ('one-arm-flat-bench-dumbbell-flye', 'Rozpiętki jednorącz na płaskiej ławce', 'One-Arm Flat Bench Dumbbell Flye', 'motor_coach', 'beginner', array['Siłowe', 'Klatka piersiowa'], 'Rozpietki klatki piersiowej wykonywane pojedynczą ręką na płaskiej ławce. Opuszczasz hantlę szerokim łukiem na bok aż poczujesz rozciągnięcie klatki, a potem wracasz napinając mięsień.', '1. Połóż się na płaskiej ławce z hantlą w jednej ręce spoczywającą na udzie. Dłoń trzymająca hantlę powinna być w chwycie neutralnym.
2. Używając ud, by pomóc unieść hantlę, podrzuć ją tak, abyś mógł trzymać ją przed sobą z całkowicie wyprostowanym ramieniem podnoszącym. Pamiętaj o zachowaniu chwytu neutralnego w tym ćwiczeniu. Ręka niewspółpracująca powinna być z boku, trzymając płaską ławkę dla lepszego podparcia. To Twoja pozycja startowa.
3. Ramię z ciężarem powinno mieć lekko zgięty łokieć, aby zapobiec obciążeniu ścięgna bicepsa. Zacznij opuszczać ramię z hantlą szerokim łukiem na bok, aż poczujesz rozciągnięcie w klatce piersiowej. Nabierz powietrza wykonując tę część ruchu. Wskazówka: pamiętaj, że przez cały ruch ramię podnoszące powinno pozostać nieruchome; ruch powinien następować tylko w stawie barkowym.
4. Wróć ramieniem podnoszącym do pozycji startowej, ściskając mięśnie klatki piersiowej i robiąc wydech. Wskazówka: upewnij się, że używasz tego samego łuku ruchu, którym opuszczałeś ciężary.
5. Przytrzymaj sekundę w pozycji napiętej i powtórz ruch przez zalecaną liczbę powtórzeń.
6. Zmień ramiona i powtórz ćwiczenie.', NULL, 'free-exercise-db/One-Arm_Flat_Bench_Dumbbell_Flye/0.jpg', 'free_exercise_db'),
  ('one-arm-floor-press', 'Wyciskanie sztangi z podłogi jednorącz', 'One Arm Floor Press', 'motor_coach', 'intermediate', array['Siłowe', 'Triceps'], 'Wyciskanie sztangi jedną ręką leżąc na podłodze. Ograniczony zakres ruchu chroni barki; chwyt neutralny zmienia pracę ramion względem klasycznego wyciskania.', '1. Połóż się na płaskiej powierzchni z plecami dociśniętymi do podłogi albo maty do ćwiczeń. Upewnij się, że kolana są zgięte.
2. Poproś partnera, by podał Ci drążek do jednej ręki. Na starcie ramię powinno być prawie całkowicie wyprostowane, podobnie jak pozycja startowa klasycznego wyciskania leżąc. Tym razem jednak Twój chwyt będzie neutralny (dłonie skierowane ku tułowiowi).
3. Upewnij się, że ręka, której nie używasz do podnoszenia ciężaru, jest położona przy boku.
4. Zacznij ćwiczenie opuszczając drążek, aż łokieć dotknie podłogi. Pamiętaj o oddychaniu w tej fazie ekscentrycznej (opuszczania) ćwiczenia.
5. Potem zacznij podnosić drążek z powrotem do pierwotnej pozycji startowej. Pamiętaj o wydychaniu powietrza podczas fazy koncentrycznej (podnoszenia) ćwiczenia.
6. Powtarzaj, aż wykonasz swoje zalecane powtórzenia.
7. Zmień ramiona i powtórz ruch.', NULL, 'free-exercise-db/One_Arm_Floor_Press/0.jpg', 'free_exercise_db'),
  ('one-arm-high-pulley-cable-side-bends', 'Skłony boczne jednorącz przy wysokim pulleye', 'One-Arm High-Pulley Cable Side Bends', 'motor_coach', 'beginner', array['Siłowe', 'Brzuch'], 'Skłony boczne z wyciągiem górnym, izolujące mięśnie skośne brzucha. Trzymasz uchwyt przy barku i skręcasz tułów bokiem, przyciągając ciężar skrętem — z ciągłym napięciem linki.', '1. Podłącz standardowy uchwyt do wieży wyciągu. Ustaw linkę na najwyższym pulleym.
2. Stań bokiem do liny. Jedną ręką sięgnij w górę i chwyć uchwyt chwytem podchwytem.
3. Pociągnij linę w dół, aż łokieć dotknie Twojego boku, a uchwyt znajdzie się przy barku.
4. Ustaw stopy na szerokość bioder. Wolną rękę połóż na biodrze, aby lepiej wyczuć punkt obrotu.
5. Trzymaj ramię nieruchomo. Napnij mięsień skośny, aby przyciągnąć ciężar w dół bocznym skrętem.
6. Gdy osiągniesz maksymalne napięcie, powoli puść ciężar do pozycji startowej. Stos ciężarów nigdy nie powinien być odkładany do pozycji odpoczynku. Chodzi o stałe napięcie podczas serii.
7. Powtarzaj do upływu sił.
8. Potem ustaw się po drugiej stronie i powtórz tę samą sekwencję ruchów na przeciwną stronę.', NULL, 'free-exercise-db/One-Arm_High-Pulley_Cable_Side_Bends/0.jpg', 'free_exercise_db'),
  ('one-arm-incline-lateral-raise', 'Wznos bokiem jednorącz na ławce skośnej', 'One-Arm Incline Lateral Raise', 'motor_coach', 'beginner', array['Siłowe', 'Barki'], 'Wznos hantli bokiem leżąc na boku na ławce skośnej. Izolacja bocznego aktonu barku bez możliwości oszukiwania — ramię wędruje prosto do góry, aż wskaże sufit.', '1. Połóż się bokiem na ławce skośnej z hantlą w dolnej ręce. Upewnij się, że bark przylega do ławki skośnej, a ramię leży w poprzek ciała z dłonią mniej więcej przy pępku.
2. Trzymaj hantlę w górnym ramieniu, utrzymując je wyprostowane przed sobą równolegle do podłogi. To Twoja pozycja startowa.
3. Utrzymując hantlę cały czas równolegle do podłogi, wykonaj wznos na bok. Twoje ramię powinno poruszać się prosto w górę, aż wskazuje sufit. Wskazówka: robiając ten ruch, wypuszczaj powietrze. Zatrzymaj hantlę w pozycji i poczuj napięcie w barkach przez sekundę.
4. Nabierając powietrza, opuść ciężar w poprzek ciała z powrotem do pozycji startowej.
5. Powtórz ruch przez zalecaną liczbę powtórzeń.
6. Zmień ramiona i powtórz ruch.', NULL, 'free-exercise-db/One-Arm_Incline_Lateral_Raise/0.jpg', 'free_exercise_db'),
  ('one-arm-kettlebell-clean', 'Czysty podrzut kettlebell jednorącz (clean)', 'One-Arm Kettlebell Clean', 'motor_coach', 'intermediate', array['Siłowe', 'Dwugłowe uda'], 'Podniesienie kettlebell z podłogi na ramię jednym ruchem eksplozywnym. Siła pochodzi z wyprostu nóg i bioder, a nadgarstek obraca się tak, by ciężar spokojnie spoczął na przedramieniu.', '1. Umieść kettlebell między stopami. Kiedy schylasz się, by go chwycić, cofnij pośladek i patrz przed siebie.
2. Podrzuć kettlebell do barków, prostując nogi i biodra, gdy unosisz kettlebell w stronę barku. Nadgarstek powinien się obracać podczas tego ruchu.
3. Wróć ciężarem do pozycji startowej.', NULL, 'free-exercise-db/One-Arm_Kettlebell_Clean/0.jpg', 'free_exercise_db'),
  ('one-arm-kettlebell-clean-and-jerk', 'Clean and jerk z kettlebell jednorącz', 'One-Arm Kettlebell Clean and Jerk', 'motor_coach', 'intermediate', array['Siłowe', 'Barki'], 'Dwufazowe ćwiczenie olimpijskie z kettlebell: najpierw podrzut ciężaru na ramię (clean), potem dynamiczne wypchnięcie nad głowę z wybiciem nóg (jerk). Buduje moc całego ciała.', '1. Trzymaj kettlebell za uchwyt.
2. Podrzuć kettlebell do barku, prostując nogi i biodra, gdy przyciągasz kettlebell w stronę barku. Obróć nadgarstek przy tym tak, by dłoń była skierowana do przodu.
3. Wykonaj dywanie ciała, zginając kolana i utrzymując tułów pionowo.
4. Natychmiast zmień kierunek, odpychając się piętami — w istocie skacząc, by stworzyć rozpęd. Przy tym wypchnij kettlebell nad głowę aż do zablokowania, prostując ramiona i używając rozpędu ciała do przemieszczenia ciężaru.
5. Przyjmij ciężar nad głową, powracając do pozycji przysiadu pod ciężarem.
6. Utrzymując ciężar nad głową, wróć do pozycji stojącej. Opuszczając ciężar na podłogę, wykonaj kolejne powtórzenie.', NULL, 'free-exercise-db/One-Arm_Kettlebell_Clean_and_Jerk/0.jpg', 'free_exercise_db'),
  ('one-arm-kettlebell-floor-press', 'Wyciskanie kettlebell z podłogi jednorącz', 'One-Arm Kettlebell Floor Press', 'motor_coach', 'intermediate', array['Siłowe', 'Klatka piersiowa'], 'Wyciskanie kettlebell jedną ręką w leżeniu na podłodze. Ograniczony zakres ruchu chroni barki, a podłoga stabilizuje łopatkę i angażuje core.', '1. Leżąc na podłodze, trzymaj kettlebell jedną ręką, z górnym ramieniem podpartym przez podłogę. Dłoń powinna być skierowana do wewnątrz.
2. Wypchnij kettlebell prosto w górę ku sufitowi, obracając nadgarstek.
3. Opuść kettlebell z powrotem do pozycji startowej i powtórz.', NULL, 'free-exercise-db/One-Arm_Kettlebell_Floor_Press/0.jpg', 'free_exercise_db'),
  ('one-arm-kettlebell-jerk', 'Wyrzut kettlebell jednorącz (jerk)', 'One-Arm Kettlebell Jerk', 'motor_coach', 'intermediate', array['Siłowe', 'Barki'], 'Dynamiczne wypchnięcie kettlebell nad głowę z wybiciem nóg. Dywasz w przysiadzie, potem eksplozywnie prostujesz nogi i wypychasz ciężar, przyjmując go w pozycji przysiadu.', '1. Trzymaj kettlebell za uchwyt. Podrzuć kettlebell do barku, prostując nogi i biodra, gdy przyciągasz go w stronę barku. Obróć nadgarstek przy tym tak, by dłoń była skierowana do przodu. To Twoja pozycja startowa.
2. Wykonaj dywan ciała, zginając kolana i utrzymując tułów pionowo.
3. Natychmiast zmień kierunek, odpychając się piętami — w istocie skacząc, by stworzyć rozpęd. Przy tym wypchnij kettlebell nad głowę aż do zablokowania, prostując ramiona i używając rozpędu ciała do przemieszczenia ciężaru. Przyjmij ciężar nad głową, powracając do pozycji przysiadu pod nim. Utrzymując ciężar nad głową, wróć do pozycji stojącej.
4. Opuszczając ciężar, wykonaj kolejne powtórzenie.', NULL, 'free-exercise-db/One-Arm_Kettlebell_Jerk/0.jpg', 'free_exercise_db'),
  ('one-arm-kettlebell-military-press-to-the-side', 'Wyciskanie żołnierskie kettlebell bokiem jednorącz', 'One-Arm Kettlebell Military Press To The Side', 'motor_coach', 'intermediate', array['Siłowe', 'Barki'], 'Wariant wyciskania kettlebell nad głowę z łokciem skierowanym na bok. Mocniejsza praca barku przy stabilizacji tułowia — pośladki, brzuch i latissimus są mocno napięte.', '1. Podrzuć kettlebell do barku. Wykonaj to, prostując nogi i biodra, gdy przyciągasz kettlebell w stronę barku. Obróć nadgarstek przy tym tak, by dłoń była skierowana do wewnątrz. To Twoja pozycja startowa.
2. Patrz na kettlebell i wypchnij go w górę i na zewnątrz, aż zostanie zablokowany nad głowę.
3. Kontrolowanie opuść kettlebell z powrotem do barku i powtórz. Koniecznie mocno napnij latissimus, pośladki i brzuch dla dodatkowej stabilności i siły.', NULL, 'free-exercise-db/One-Arm_Kettlebell_Military_Press_To_The_Side/0.jpg', 'free_exercise_db'),
  ('one-arm-kettlebell-para-press', 'Wyciskanie kettlebell „para” jednorącz', 'One-Arm Kettlebell Para Press', 'motor_coach', 'intermediate', array['Siłowe', 'Barki'], 'Wariant wyciskania kettlebell nad głowę, w którym łokieć trzymany jest szeroko na boku. Podobny do wyciskania żołnierskiego bokiem — buduje siłę i stabilność barku.', '1. Podrzuć kettlebell do barku. Wykonaj to, prostując nogi i biodra, gdy przyciągasz kettlebell w stronę barku. Obróć nadgarstek przy tym tak, by dłoń była skierowana do przodu. To Twoja pozycja startowa.
2. Trzymaj kettlebell z łokciem skierowanym na bok i wypchnij go w górę i na zewnątrz, aż zostanie zablokowany nad głowę.
3. Kontrolowanie opuść kettlebell z powrotem do barku i powtórz. Koniecznie mocno napnij latissimus, pośladki i brzuch dla dodatkowej stabilności i siły.', NULL, 'free-exercise-db/One-Arm_Kettlebell_Para_Press/0.jpg', 'free_exercise_db'),
  ('one-arm-kettlebell-push-press', 'Push press z kettlebell jednorącz', 'One-Arm Kettlebell Push Press', 'motor_coach', 'intermediate', array['Siłowe', 'Barki'], 'Wyciskanie kettlebell z pomocą nóg: krótki dywan i dynamiczne wyprost nóg daje rozpęd, którym wypychasz ciężar nad głowę. Pozwala użyć większego ciężaru niż klasyczne wyciskanie.', '1. Trzymaj kettlebell za uchwyt. Podrzuć kettlebell do barku, prostując nogi i biodra, gdy przyciągasz go w stronę barku. Obróć nadgarstek przy tym tak, by dłoń była skierowana do przodu. To Twoja pozycja startowa.
2. Wykonaj dywan ciała, zginając kolana i utrzymując tułów pionowo.
3. Natychmiast zmień kierunek, odpychając się piętami — w istocie skacząc, by stworzyć rozpęd. Przy tym wypchnij kettlebell nad głowę aż do zablokowania, prostując ramiona i używając rozpędu ciała do przemieszczenia ciężaru. Opuszczenie ciężaru pozwoli wykonać kolejne powtórzenie.', NULL, 'free-exercise-db/One-Arm_Kettlebell_Push_Press/0.jpg', 'free_exercise_db'),
  ('one-arm-kettlebell-row', 'Wiosłowanie kettlebell jednorącz', 'One-Arm Kettlebell Row', 'motor_coach', 'intermediate', array['Siłowe', 'Środek pleców'], 'Wiosłowanie kettlebell w silnym pochyleniu tułowia. Ściągasz ciężar do brzucha, ściągając łopatkę — świetne ćwiczenie na grubość pleców.', '1. Umieść kettlebell przed stopami. Lekko ugnij kolana, a potem maksymalnie wypchnij pośladek do tyłu, pochylając się, by przyjąć pozycję startową. Chwyć kettlebell i przyciągnij go do brzucha, ściągając łopatkę i zginając łokieć. Trzymaj plecy prosto. Opuść i powtórz.', NULL, 'free-exercise-db/One-Arm_Kettlebell_Row/0.jpg', 'free_exercise_db'),
  ('one-arm-kettlebell-snatch', 'Rwanie kettlebell jednorącz (snatch)', 'One-Arm Kettlebell Snatch', 'motor_coach', 'advanced', array['Siłowe', 'Barki'], 'Eksplozywna podrzucenie kettlebell z zamachu między nogami prosto nad głowę jednym ruchem. Jedno z najbardziej kompleksowych ćwiczeń z kettlebell — siła, moc i kondycja w jednym.', '1. Umieść kettlebell między stopami. Ugnij kolana i cofnij pośladek, aby przyjąć właściwą pozycję startową.
2. Patrz prosto przed siebie i zamachnij kettlebell do tyłu między nogami.
3. Natychmiast odwróć kierunek i wybij się biodrami i kolanami, przyspieszając kettlebell w górę. Gdy kettlebell dochodzi do wysokości barku, obróć dłoń i uderz prosto w górę, używając rozpędu do przyjęcia ciężaru zablokowanego nad głowę.', NULL, 'free-exercise-db/One-Arm_Kettlebell_Snatch/0.jpg', 'free_exercise_db'),
  ('one-arm-kettlebell-split-jerk', 'Split jerk z kettlebell jednorącz', 'One-Arm Kettlebell Split Jerk', 'motor_coach', 'intermediate', array['Siłowe', 'Barki'], 'Wyrzut kettlebell nad głowę z wypadem (split): dywasz, wypychasz ciężar i przyjmujesz go w pozycji z jedną nogą z przodu, a drugą z tyłu. Dynamiczne ćwiczenie mocy i koordynacji.', '1. Trzymaj kettlebell za uchwyt. Podrzuć kettlebell do barku, prostując nogi i biodra, gdy przyciągasz go w stronę barku. Obróć nadgarstek przy tym tak, by dłoń była skierowana do przodu. To Twoja pozycja startowa.
2. Wykonaj dywan ciała, zginając kolana i utrzymując tułów pionowo.
3. Natychmiast zmień kierunek, odpychając się piętami — w istocie skacząc, by stworzyć rozpęd. Przy tym wypchnij kettlebell nad głowę aż do zablokowania, prostując ramiona i używając rozpędu ciała do przemieszczenia ciężaru.
4. Przyjmij ciężar nad głową, wracając do pozycji przysiadu pod ciężarem, ustawiając jedną nogę z przodu, a drugą z tyłu.
5. Utrzymując ciężar nad głową, wróć do pozycji stojącej i zbliż stopy do siebie. Opuszczając ciężar, wykonaj kolejne powtórzenie.', NULL, 'free-exercise-db/One-Arm_Kettlebell_Split_Jerk/0.jpg', 'free_exercise_db')
on conflict (slug) do nothing;

insert into public.exercises
  (slug, name, name_en, persona_type, level, categories, short_description, detail_full, common_mistakes, photo_path, source)
values
  ('one-arm-kettlebell-split-snatch', 'Split snatch z kettlebell jednorącz', 'One-Arm Kettlebell Split Snatch', 'motor_coach', 'advanced', array['Siłowe', 'Barki'], 'Połączenie rwania z wypadem: wybierasz się z przysiadu, wyrzucając kettlebell nad głowę i łapiesz go w pozycji split (jedna noga z przodu, druga z tyłu). Bardzo wymagające technicznie.', '1. Trzymaj kettlebell w jednej ręce za uchwyt.
2. Schodź w kierunku podłogi w przysiad, a potem odwróć ruch, prostując biodra, kolana i w końcu kostki, aby wyrzucić kettlebell nad głowę.
3. Po całkowitym wyproście ciała opadnij w pozycję wypadu, aby przyjąć ciężary nad głową — jedna noga z przodu, druga z tyłu. Upewnij się, że wybijasz się biodrami i blokujesz kettlebelle nad głowę jednym nieprzerwanym ruchem.
4. Wróć do pozycji stojącej, trzymając ciężar nad głową, i zbliż stopy do siebie. Opuszczając ciężar, wróć do pozycji startowej.', NULL, 'free-exercise-db/One-Arm_Kettlebell_Split_Snatch/0.jpg', 'free_exercise_db'),
  ('one-arm-lat-pulldown', 'Ściąganie drążka wyciągu jednorącz', 'One Arm Lat Pulldown', 'motor_coach', 'beginner', array['Siłowe', 'Najszersze grzbietu'], 'Ściąganie linki wyciągu górnego jedną ręką. Pozwala skupić się na pracy każdego boku pleców osobno i poprawić asymetrie siły.', '1. Wybierz odpowiedni ciężar i dostosuj wałek kolanowy, który pomoże utrzymać Cię w miejscu. Chwyć uchwyt chwytem nachwytem. To Twoja pozycja startowa.
2. Pociągnij uchwyt w dół, przyciskając łokieć do boku, gdy zginasz łokieć.
3. Pauza na dole ruchu, a potem powoli wróć uchwytem do pozycji startowej.
4. Przy wielu powtórzeniach nie odkładaj ciężaru całkiem do końca, aby utrzymać napięcie trenowanych mięśni.', NULL, 'free-exercise-db/One_Arm_Lat_Pulldown/0.jpg', 'free_exercise_db'),
  ('one-arm-long-bar-row', 'Wiosłowanie gryfem w rogu jednorącz (landmine row)', 'One-Arm Long Bar Row', 'motor_coach', 'beginner', array['Siłowe', 'Środek pleców'], 'Wiosłowanie jednorącz gryfem opartym o narożnik lub landmine. Ściągasz sztangę do boku, ściągając łopatkę — solidne ćwiczenie na plecy bez potrzeby stojaka.', '1. Umieść drążek w landmine albo w rogu, aby zapobiec jego przesuwaniu. Załaduj odpowiedni ciężar na swój koniec.
2. Stań obok drążka i chwyć go jedną ręką blisko tulei. Używając bioder i nóg, podnieś się do pozycji stojącej.
3. Przyjmij postawę z lekko ugiętymi kolanami, biodra cofnięte, a klatka piersiowa uniesiona. Ramię powinno być wyprostowane. To Twoja pozycja startowa.
4. Przyciągnij ciężar do swojego boku, ściągając łopatkę i zginając łokieć. Nie szarpaj ciężarem ani nie oszukuj podczas ruchu.
5. Po krótkiej pauzie wróć do pozycji startowej.', NULL, 'free-exercise-db/One-Arm_Long_Bar_Row/0.jpg', 'free_exercise_db'),
  ('one-arm-medicine-ball-slam', 'Slam piłką lekarską jednorącz', 'One-Arm Medicine Ball Slam', 'motor_coach', 'beginner', array['Siłowe', 'Brzuch'], 'Mocne rzucenie piłki lekarskiej o podłogę jedną ręką. Zamach nad głowę z wybiciem bioder, a potem eksplozywny slam przed sobą — świetne ćwiczenie mocy całego ciała.', '1. Zacznij w pozycji stojącej w rozbieżnej, atletycznej postawie. Trzymaj piłkę lekarską w jednej ręce, po tej samej stronie co tylna noga. To Twoja pozycja startowa.
2. Zacznij od zamachu ramieniem, unosząc piłkę ponad głowę. Przy tym prostuj biodra, kolana i kostki, aby załadować się przed slamem.
3. Na szczycie wyprostu zegnij barki, kręgosłup i biodra, mocno rzucając piłką o podłogę bezpośrednio przed sobą.
4. Złap piłkę po odbiciu i kontynuuj przez żądaną liczbę powtórzeń.', NULL, 'free-exercise-db/One-Arm_Medicine_Ball_Slam/0.jpg', 'free_exercise_db'),
  ('one-arm-open-palm-kettlebell-clean', 'Clean kettlebell na otwartą dłoń jednorącz', 'One-Arm Open Palm Kettlebell Clean', 'motor_coach', 'intermediate', array['Siłowe', 'Dwugłowe uda'], 'Wariant cleana z kettlebell, w którym ciężar wylatuje z uchwytu i ląduje na otwartej dłoni. Wymaga precyzji i kontroli — trening chwytu, koordynacji i mocy.', '1. Umieść jeden kettlebell między stopami.
2. Chwyć uchwyt jedną ręką i szybko unieś kettlebell, pozwól mu się przewrócić tak, aby kula kettlebell wylądowała na dłoni Twojej ręki.
3. Wyrzuć kettlebell przed siebie i złap uchwyt jedną ręką.
4. Odłóż kettlebell na podłogę i powtórz. Koniecznie pracuj oboma ramionami.', NULL, 'free-exercise-db/One-Arm_Open_Palm_Kettlebell_Clean/0.jpg', 'free_exercise_db'),
  ('one-arm-overhead-kettlebell-squats', 'Przysiad z kettlebell nad głową jednorącz', 'One-Arm Overhead Kettlebell Squats', 'motor_coach', 'advanced', array['Siłowe', 'Uda'], 'Przysiad z kettlebell trzymanym zablokowanym nad głową jedną ręką. Ogromne wymagania dla core, barków i mobilności — buduje siłę funkcjonalną całego ciała.', '1. Podrzuć i wypchnij kettlebell jedną ręką. Podrzuć kettlebell do barku, prostując nogi i biodra, gdy przyciągasz go w stronę barku. Obróć nadgarstek przy tym. Wypchnij ciężar nad głowę, prostując łokieć. To Twoja pozycja startowa.
2. Patrząc prosto przed siebie i utrzymując kettlebell zablokowany nad sobą, zegnij kolana i biodra, opuszczając tułów między nogi, z głową i klatką piersiową uniesioną.
3. Zatrzymaj się na dole pozycji na sekundę przed powrotem do góry, odpychając się piętami.', NULL, 'free-exercise-db/One-Arm_Overhead_Kettlebell_Squats/0.jpg', 'free_exercise_db'),
  ('one-arm-pronated-dumbbell-triceps-extension', 'Prostowanie ramienia z hantlą nachwytem w leżeniu', 'One Arm Pronated Dumbbell Triceps Extension', 'motor_coach', 'beginner', array['Siłowe', 'Triceps'], 'Jednoramienne „francuskie” z hantlą chwyconą nachwytem (dłoń ku stopom). Izoluje triceps jednej ręki z pełną kontrolą ruchu.', '1. Leżąc płasko na ławce, trzymaj hantlę na wyciągniętym ramieniu. Ramię powinno być prostopadłe do ciała. Dłoń powinna być skierowana ku stopom, ponieważ do tego ćwiczenia wymagany jest chwyt nachwytem.
2. Połóż niedziałającą rękę na bicepsie dla podparcia.
3. Powoli zacznij opuszczać hantlę robiąc wdech.
4. Potem zacznij unosić hantlę w górę napinając triceps. Pamiętaj o wydychaniu powietrza podczas fazy koncentrycznej (podnoszenia) ćwiczenia.
5. Powtarzaj, aż wykonasz zaplanowaną liczbę powtórzeń serii.
6. Zmień ramiona i powtórz ruch.', NULL, 'free-exercise-db/One_Arm_Pronated_Dumbbell_Triceps_Extension/0.jpg', 'free_exercise_db'),
  ('one-arm-side-deadlift', 'Martwy ciąg boczny jednorącz (suitcase deadlift)', 'One-Arm Side Deadlift', 'motor_coach', 'advanced', array['Siłowe', 'Uda'], 'Martwy ciąg sztangi leżącej bokiem, chwytany jak walizkę. Buduje ogromną siłę chwytu i stabilność core, bo tułów musi opierać się skręceniu.', '1. Stań z boku sztangi, przy jej środku. Ugnij kolana i opuść ciało, aż będziesz w stanie dosięgnąć sztangi.
2. Chwyć drążek, jakbyś chwytał walizkę (dłonie skierowane ku Tobie, bo sztanga leży bokiem). Przy znacznym ciężarze może być potrzebna owijka na nadgarstek. To Twoja pozycja startowa.
3. Użyj nóg, aby pomóc w podniesieniu sztangi, robiąc wydech. Ramiona powinny wyprostować się całkowicie, gdy podnosisz sztangę aż do pozycji stojącej.
4. Powoli opuść sztangę z powrotem robiąc wdech. Wskazówka: pamiętaj o zgięciu kolan podczas opuszczania ciężaru, aby uniknąć jakiegokolwiek urazu.
5. Powtórz zalecaną liczbę powtórzeń.
6. Zmień ramiona i powtórz ruch.', NULL, 'free-exercise-db/One-Arm_Side_Deadlift/0.jpg', 'free_exercise_db'),
  ('one-arm-side-laterals', 'Wznos bokiem jednorącz w opadzie', 'One-Arm Side Laterals', 'motor_coach', 'beginner', array['Siłowe', 'Barki'], 'Wznos hantli bokiem jedną ręką z pochyleniem tułowia w stronę pracy. Dodatkowe napięcie w dolnej fazie ruchu daje mocniejszą izolację bocznego aktonu barku.', '1. Wybierz hantlę i umieść ją w jednej ręce. Ręka niewspółpracująca powinna trzymać coś stabilnego, np. ławkę skośną. Pochyl się w stronę ręki podnoszącej, odchylając od ręki trzymającej ławkę — to pozwoli Ci zachować równowagę.
2. Stań z wyprostowanym tułowiem i miej hantlę przy boku na wyciągnięciu ramienia, z dłonią skierowaną ku Tobie. To Twoja pozycja startowa.
3. Utrzymując tułów nieruchomy (bez kołysania), unieś hantlę na bok z lekkim zgięciem łokcia i dłonią lekko pochyloną do przodu, jakbyś przelewał wodę do szklanki. Kontynuuj ruch w górę, aż ramię będzie równoległe do podłogi. Robiąc ten ruch, wypuszczaj powietrze i zatrzymaj się na sekundę na górze.
4. Opuść hantlę powoli z powrotem do pozycji startowej, nabierając powietrza.
5. Powtórz zalecaną liczbę powtórzeń.
6. Zmień ramiona i powtórz ćwiczenie.', NULL, 'free-exercise-db/One-Arm_Side_Laterals/0.jpg', 'free_exercise_db'),
  ('one-arm-supinated-dumbbell-triceps-extension', 'Prostowanie ramienia z hantlą podchwytem w leżeniu', 'One Arm Supinated Dumbbell Triceps Extension', 'motor_coach', 'beginner', array['Siłowe', 'Triceps'], 'Jednoramienne „francuskie” z hantlą chwyconą podchwytem (dłoń ku twarzy). Wariant podchwytu inaczej rozkłada pracę tricepsa; wykonujesz go naprzemiennie oboma ramionami.', '1. Leżąc płasko na ławce, trzymaj hantlę na wyciągniętym ramieniu. Ramię powinno być prostopadłe do ciała. Dłoń powinna być skierowana ku twarzy, ponieważ do tego ćwiczenia wymagany jest chwyt podchwytem.
2. Połóż niedziałającą rękę na bicepsie dla podparcia.
3. Powoli zacznij opuszczać hantlę robiąc wdech.
4. Potem zacznij unosić hantlę w górę napinając triceps. Pamiętaj o wydychaniu powietrza podczas fazy koncentrycznej (podnoszenia) ćwiczenia.
5. Powtarzaj, aż wykonasz zaplanowaną liczbę powtórzeń serii.
6. Zmień ramiona i powtórz ruch.
7. Znów zmień ramiona i powtórz ruch.', NULL, 'free-exercise-db/One_Arm_Supinated_Dumbbell_Triceps_Extension/0.jpg', 'free_exercise_db'),
  ('one-half-locust', 'Pół szarańczy (półmostek)', 'One Half Locust', 'motor_coach', 'beginner', array['Rozciąganie', 'Uda'], 'Ćwiczenie inspirowane jogą: leżąc na brzuchu unoyszysz jedno kolano i ramiona jednocześnie. Rozciąga zginacz biodra, klatkę piersiową i barki.', '1. Połóż się twarzą w dół na podłodze.
2. Wsuń lewą dłoń pod lewą kość biodrową, aby poduszkować biodro i kość łonową.
3. Zegnij prawe kolano tak, aby móc trzymać stopę prawą ręką.
4. Unieś stopę w powietrze i jednocześnie oderwij barki od podłogi. Rozciąga to także prawy zginacz biodra oraz klatkę piersiową i barki. Zmień strony. Jeśli nie przeszkadza to Twoim plecom, spróbuj wykonać to oburącz i z obiema nogami naraz.', NULL, 'free-exercise-db/One_Half_Locust/0.jpg', 'free_exercise_db'),
  ('one-handed-hang', 'Wiszenie jednorącz na drążku', 'One Handed Hang', 'motor_coach', 'beginner', array['Rozciąganie', 'Najszersze grzbietu'], 'Zwis na jednym ramieniu na drążku do podciągania, z nogami opartymi o podłogę. Buduje siłę chwytu i przygotowuje do podciągnięć jednorącz.', '1. Złap drążek do podciągania jedną ręką chwytem nachwytem. Trzymaj stopy na podłodze albo na stopniu. Pozwól większości swojego ciężaru wisieć na tej ręce, utrzymując stopy na ziemi. Przytrzymaj 10–20 sekund i zmień strony.', NULL, 'free-exercise-db/One_Handed_Hang/0.jpg', 'free_exercise_db'),
  ('one-knee-to-chest', 'Kolano do klatki piersiowej', 'One Knee To Chest', 'motor_coach', 'beginner', array['Rozciąganie', 'Pośladki'], 'Delikatne rozciąganie pośladków i dolnych pleców w leżeniu. Przyciągasz jedno kolano do klatki piersiowej, lekko ciągnąc je w stronę nosa, a potem zmieniasz strony.', '1. Zacznij od położenia się na podłodze.
2. Wyprostuj jedną nogę i przyciągnij drugie kolano do klatki piersiowej. Trzymaj pod stawem kolanowym, aby chronić rzepkę.
3. Delikatnie pociągnij kolano w kierunku nosa.
4. Zmień strony. To rozciąga pośladki i dolne plecy zgiętej nogi oraz zginacz biodra wyprostowanej nogi.', NULL, 'free-exercise-db/One_Knee_To_Chest/0.jpg', 'free_exercise_db'),
  ('one-leg-barbell-squat', 'Przysiad bułgarski ze sztangą (jednonóż)', 'One Leg Barbell Squat', 'motor_coach', 'advanced', array['Siłowe', 'Uda'], 'Przysiad na jednej nodze ze sztangą na karku i tylną stopą opartą o ławkę. Bardzo wymagające dla siły, równowagi i stabilizacji core.', '1. Stań ok. 60–90 cm przed płaską ławką tyłem do niej. Miej sztangę przed sobą na podłodze. Wskazówka: stopy powinny być rozstawione na szerokość barków.
2. Zegnij kolana i użyj chwytu nachwytem z rękami szerszymi niż szerokość barków, aby podnieść sztangę aż będziesz mógł oprzeć ją na klatce piersiowej.
3. Potem przenieś sztangę nad głowę i oprzyj ją u podstawy karku. Przesuń jedną stopę do tyłu tak, by palce opierały się o płaską ławkę. Druga stopa powinna stać nieruchomo przed Tobą. Cały czas trzymaj głowę uniesioną, bo patrzenie w dół zaburzy równowagę, i zachowuj proste plecy. Wskazówka: upewnij się, że plecy są proste, a klatka wypchnięta podczas tego ćwiczenia.
4. Robiąc wdech, powoli opuść nogę, aż udo będzie równoległe do podłogi. W tym punkcie kolano powinno być nad palcami stopy. Klatka piersiowa powinna znajdować się bezpośrednio nad środkiem uda.
5. Wypychając klatkę i biodra do przodu oraz napinając mięsień czworogłowy uda, unieś ciało z powrotem do pozycji startowej robiąc wydech.
6. Powtórz zalecaną liczbę powtórzeń.
7. Zmień nogi i powtórz ruch.', NULL, 'free-exercise-db/One_Leg_Barbell_Squat/0.jpg', 'free_exercise_db'),
  ('one-legged-cable-kickback', 'Kopnięcie nogi w tył na wyciągu jednonóż', 'One-Legged Cable Kickback', 'motor_coach', 'intermediate', array['Siłowe', 'Pośladki'], 'Izolacja pośladków: z mankietem na kostce przy niskim pulleyu wypychasz nogę do tyłu półkolistym łukiem. Świetne ćwiczenie modelujące pośladki z ciągłym napięciem liny.', '1. Podłącz skórzany mankiet na kostkę do niskiego pulleya, a potem zapięcie mankietu do swojej kostki.
2. Stań twarzą do stosu ciężarów z odległości około dwóch stóp, trzymając stalową ramę dla podparcia.
3. Utrzymując lekko zgięte kolana i biodra oraz napięty brzuch, napnij pośladki, aby powolio „kopnąć” pracującą nogę do tyłu półkolistym łukiem tak wysoko, jak to możliwe komfortowo, robiąc wydech. Wskazówka: przy pełnym wyproście ściśnij pośladki na sekundę, aby osiągnąć szczytowe napięcie.
4. Teraz powolio przyciągnij pracującą nogę do przodu, opierając się ciągowi liny, aż wrócisz do pozycji startowej.
5. Powtórz zalecaną liczbę powtórzeń.
6. Zmień nogi i powtórz ruch na drugą stronę.', NULL, 'free-exercise-db/One-Legged_Cable_Kickback/0.jpg', 'free_exercise_db'),
  ('open-palm-kettlebell-clean', 'Clean kettlebell na otwarte dłonie', 'Open Palm Kettlebell Clean', 'motor_coach', 'advanced', array['Siłowe', 'Dwugłowe uda'], 'Wariant cleana z kettlebell, w którym ciężar przełącza się między uchwytem a otwartą dłonią. Trening koordynacji, chwytu i kontroli ciężaru.', '1. Umieść jeden kettlebell między stopami. Wykonaj cleana prostując nogi i biodra, gdy unosisz kettlebell w stronę barków.
2. Puść kettlebell, gdy idzie w górę, i pozwól mu się przewrócić tak, aby kula kettlebell wylądowała na dłoniach Twoich rąk.
3. Wyrzuć kettlebell przed siebie i złap uchwyt oburącz. Opuść kettlebell do pozycji startowej i powtórz.', NULL, 'free-exercise-db/Open_Palm_Kettlebell_Clean/0.jpg', 'free_exercise_db'),
  ('otis-up', 'Otis-up (brzuch z ciężarem nad głowę)', 'Otis-Up', 'motor_coach', 'beginner', array['Siłowe', 'Brzuch'], 'Zaawansowany spiętek brzucha z obciążnikiem trzymanym na klatce. Podczas unoszenia tułowia wypychasz ciężar nad głowę — mocna praca core i barków.', '1. Zabezpiecz stopy i połóż się na plecach na podłodze. Kolana powinny być zgięte. Trzymaj ciężar oburącz przy klatce piersiowej. To Twoja pozycja startowa.
2. Rozpocznij ruch zginając biodra i kręgosłup, unosząc tułów z ziemi.
3. Podczas unoszenia wypychaj ciężar w górę tak, aby znalazł się nad głową na szczycie ruchu.
4. Wróć ciężarem do klatki odwracając ruch spiętku, dbając o to, by nie schodzić aż do podłogi.', NULL, 'free-exercise-db/Otis-Up/0.jpg', 'free_exercise_db'),
  ('overhead-cable-curl', 'Uginanie ramion na wyciągu nad głowę', 'Overhead Cable Curl', 'motor_coach', 'intermediate', array['Siłowe', 'Biceps'], 'Uginanie bicepsów oburącz na dwóch pulleyach wyciągu ustawionych ponad wysokość barków. Ramiona są uniesione na boki, a Ty przyciągasz dłonie do głowy — pełna izolacja bicepsów z ciągłym napięciem.', '1. Na początek ustaw komfortowy ciężar po każdej stronie maszyny pulleyowej. Uwaga: upewnij się, że ilość ciężaru jest taka sama po każdej stronie.
2. Teraz dostosuj wysokość pulleyów po obu stronach i upewnij się, że znajdują się powyżej wysokości Twoich barków.
3. Stań pomiędzy obiema stronami i chwyć każdy uchwyt chwytem podchwytem (dłonie skierowane ku sufitowi). Ramiona powinny być całkowicie wyprostowane i równoległe do podłogi, ze stopami rozstawionymi na szerokość barków. Ciało powinno być równo ustawione między uchwytami. To pozycja startowa.
4. Robiąc wydech, powoli napnij biceps po każdej stronie, aż przedramiona dotkną bicepsów.
5. Nabierając powietrza, cofnij przedramiona do pozycji startowej. Uwaga: całe Twoje ciało pozostaje nieruchome podczas tego ćwiczenia z wyjątkiem przedramion.
6. Powtórz zalecaną liczbę powtórzeń przepisaną w Twoim programie.', NULL, 'free-exercise-db/Overhead_Cable_Curl/0.jpg', 'free_exercise_db'),
  ('overhead-lat', 'Rozciąganie latissimusów nad głowę (z partnerem)', 'Overhead Lat', 'motor_coach', 'advanced', array['Rozciąganie', 'Najszersze grzbietu'], 'Rozciąganie najszerszego mięśnia pleców z pomocą partnera. Unosisz ramię i próbujesz zgiąć je za plecy napinając mięsień, a potem partner pogłębia rozciągnięcie.', '1. Usiądź prosto na podłodze z partnerem za sobą. Unieś jedno ramię prosto w górę i zegnij łokieć, próbując dotknąć dłonią pleców. Partner powinien trzymać Twój triceps i nadgarstek. To Twoja pozycja startowa.
2. Spróbuj przyciągnąć górne ramię do boku, podczas gdy partner blokuje faktyczne wykonanie tego ruchu.
3. Po 10–20 sekundach rozluźnij ramię i pozwól partnerowi dodatkowo rozciągnąć latissimusa, delikatnie dociskając triceps. Przytrzymaj 10–20 sekund, a potem zmień strony.', NULL, 'free-exercise-db/Overhead_Lat/0.jpg', 'free_exercise_db'),
  ('overhead-slam', 'Slam piłką lekarską znad głowy', 'Overhead Slam', 'motor_coach', 'beginner', array['Plyometryka', 'Najszersze grzbietu'], 'Klasyczny slam ball: unosisz piłkę nad głowę z pełnym wyprostem ciała, a potem eksplozywnie rozbijasz ją o podłogę przed sobą. Świetne na moc i kondycję.', '1. Trzymaj piłkę lekarską oburącz i stań ze stopami na szerokość barków. To Twoja pozycja startowa.
2. Rozpocznij ruch przeciwny (przygotowanie), unosząc piłkę ponad głowę i całkowicie prostując ciało.
3. Odwróć ruch, rozbijając piłkę o podłogę bezpośrednio przed sobą jak najmocniej.
4. Złap piłkę oburącz po odbiciu i powtórz ruch.', NULL, 'free-exercise-db/Overhead_Slam/0.jpg', 'free_exercise_db'),
  ('overhead-squat', 'Przysiad ze sztangą nad głową (overhead squat)', 'Overhead Squat', 'motor_coach', 'advanced', array['Podnoszenie ciężarów', 'Uda'], 'Przysiad z sztangą trzymaną wyprostowanymi ramionami nad głową. Jeden z najtrudniejszych wariantów przysiadu — wymaga mobilności barków, core i nóg jednocześnie.', '1. Zacznij ze sztangą leżącą przed Tobą na podłodze. Stopy powinny być rozstawione szerzej niż szerokość barków.
2. Zegnij kolana i użyj chwytu nachwytem (dłonie ku Tobie), aby złapać drążek. Dłonie powinny być rozstawione szerzej niż barki przed podniesieniem. Po ustawieniu się podnieś sztangę, aż będziesz mógł oprzeć ją na klatce piersiowej.
3. Przenieś sztangę ponad i lekko za głowę, upewnij się, że ramiona są całkowicie wyprostowane. Cały czas trzymaj głowę uniesioną i zachowuj proste plecy. Ściągnij łopatki. To Twoja pozycja startowa.
4. Powoli opuszczaj ciężar zginając kolana, aż uda będą równoległe do podłogi, robiąc wdech. Wskazówka: zachowuj proste plecy podczas tego ćwiczenia, aby uniknąć urazów, a ramiona muszą pozostać wyprostowane i nad głową przez cały czas.
5. Teraz użyj stóp i nóg, aby pomóc wypchnąć ciężar z powrotem do pozycji startowej, robiąc wydech.
6. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Overhead_Squat/0.jpg', 'free_exercise_db'),
  ('overhead-stretch', 'Rozciąganie tułowia znad głowy', 'Overhead Stretch', 'motor_coach', 'beginner', array['Rozciąganie', 'Brzuch'], 'Proste rozciąganie całego tułowia w staniu. Splot palce, otwórz dłonie ku sufitowi i wyciągnij ręce w górę, rozciągając przód i tył tułowia.', '1. Stojąc prosto, spleć palce obu dłoni i otwórz dłonie ku sufitowi. Trzymaj barki opuszczone, wyciągając ramiona w górę.
2. Aby stworzyć pełne rozciągnięcie tułowia, pociągnij ogon kość w dół i ustabilizuj tułów robiąc to. Rozciągaj mięśnie zarówno z przodu, jak i z tyłu tułowia.', NULL, 'free-exercise-db/Overhead_Stretch/0.jpg', 'free_exercise_db'),
  ('overhead-triceps', 'Rozciąganie tricepsów znad głowy (z partnerem)', 'Overhead Triceps', 'motor_coach', 'advanced', array['Rozciąganie', 'Triceps'], 'Rozciąganie tricepsa z pomocą partnera. Unosisz ramię, zginasz łokieć za plecy i napinasz mięsień, a potem partner delikatnie pogłębia rozciągnięcie dociskając nadgarstek.', '1. Usiądź prosto na podłodze z partnerem za sobą. Unieś jedno ramię prosto w górę i zegnij łokieć, próbując dotknąć dłonią pleców. Partner powinien trzymać Twój łokieć i nadgarstek. To Twoja pozycja startowa.
2. Spróbuj wyprostować ramię prosto w górę, podczas gdy partner blokuje faktyczne wykonanie tego ruchu.
3. Po 10–20 sekundach rozluźnij ramię i pozwól partnerowi dodatkowo rozciągnąć triceps, delikatnie dociskając nadgarstek. Przytrzymaj 10–20 sekund, a potem zmień strony.', NULL, 'free-exercise-db/Overhead_Triceps/0.jpg', 'free_exercise_db'),
  ('pallof-press', 'Pallof press (wyciskanie antyrotacyjne)', 'Pallof Press', 'motor_coach', 'beginner', array['Siłowe', 'Brzuch'], 'Ćwiczenie antyrotacyjne na miśnie głębokie z wyciągiem lub gumą. Trzymasz linkę przy klatce i prostujesz ramiona, opierając się skręceniu tułowia.', '1. Podłącz standardowy uchwyt do wieży wyciągu i, jeśli to możliwe, ustaw linkę na wysokość barków. Jeśli nie, wystarczy niski pulley.
2. Bokiem do liny chwyć uchwyt oburącz i odejdź od wieży. Powinieneś być mniej więcej na długość ramienia od pulleya, z napięciem ciężaru na lince.
3. Ze stopami rozstawionymi na szerokość bioder i lekko zgiętymi kolanami, trzymaj linkę przy środku klatki piersiowej. To Twoja pozycja startowa.
4. Wypchnij linkę od klatki piersiowej, całkowicie prostując oba ramiona. Twój core powinien być napięty i aktywny.
5. Przytrzymaj powtórzenie przez kilka sekund przed powrotem do pozycji startowej.
6. Na koniec serii powtórz, stojąc twarzą w drugą stronę.', NULL, 'free-exercise-db/Pallof_Press/0.jpg', 'free_exercise_db'),
  ('pallof-press-with-rotation', 'Pallof press ze skrętem tułowia', 'Pallof Press With Rotation', 'motor_coach', 'beginner', array['Siłowe', 'Brzuch'], 'Wersja Pallof press wzbogacona o rotację: wypychasz linkę przed siebie, a potem skręcasz tułów od wyciągu. Silna praca mięśni skośnych i core w trybie antyrotacji plus rotacja.', '1. Podłącz standardowy uchwyt do wieży wyciągu i ustaw linkę na wysokość barków.
2. Bokiem do liny chwyć uchwyt jedną ręką i odejdź od wieży. Powinieneś być mniej więcej na długość ramienia od pulleya, z napięciem ciężaru na lince. Wyciągnięte ramię ustaw w linii z linką.
3. Ze stopami rozstawionymi na szerokość bioder przyciągnij linkę do klatki piersiowej i chwyć uchwyt drugą ręką. Obie dłonie powinny teraz być na uchwycie.
4. Twarz zwrócona do przodu, wypchnij linkę od klatki piersiowej. Twój core powinien być napięty i aktywny.
5. Trzymając biodra skierowane do przodu, skręć tułów od pulleya, aż osiągniesz pełny ćwierćobrót.
6. Zachowaj sztywną postawę i proste ramiona. Wróć do pozycji neutralnej w sposób powolny i kontrolowany. Ramiona powinny być wyciągnięte przed Tobą.
7. Z napięciem bocznym wciąż aktywującym Twój core, przyciągnij ręce do klatki i natychmiast wypchnij je na zewnątrz do całkowicie wyprostowanej pozycji. To stanowi jedno powtórzenie.
8. Powtarzaj do upływu sił.
9. Potem ustaw się po drugiej stronie i powtórz tę samą sekwencję ruchów na przeciwną stronę.', NULL, 'free-exercise-db/Pallof_Press_With_Rotation/0.jpg', 'free_exercise_db'),
  ('palms-down-dumbbell-wrist-curl-over-a-bench', 'Uginanie nadgarstków hantlami nachwytem na ławce', 'Palms-Down Dumbbell Wrist Curl Over A Bench', 'motor_coach', 'beginner', array['Siłowe', 'Przedramiona'], 'Izolowane wzmacnianie prostowników nadgarstków. Kładziesz przedramiona na ławce z hantlami w dłoniach i uginasz same nadgarstki w dół i do góry.', '1. Zacznij od ułożenia dwóch hantli po jednej stronie płaskiej ławki.
2. Uklęknij na obu kolanach tak, aby Twoje ciało było zwrócone do płaskiej ławki.
3. Chwyć obiema rękami obie hantle chwytem nachwytem (palce w dół) i unieś je tak, aby przedramiona opierały się o płaską ławkę. Nadgarstki powinny zwisać za jej krawędź.
4. Zacznij od uginania nadgarstków w górę robiąc wydech.
5. Powoli opuść nadgarstki z powrotem do pozycji startowej robiąc wdech.
6. Twoje przedramiona powinny pozostać nieruchome, ponieważ tylko nadgarstki wykonują ruch potrzebny do tego ćwiczenia.
7. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Palms-Down_Dumbbell_Wrist_Curl_Over_A_Bench/0.jpg', 'free_exercise_db'),
  ('palms-down-wrist-curl-over-a-bench', 'Uginanie nadgarstków sztangą nachwytem na ławce', 'Palms-Down Wrist Curl Over A Bench', 'motor_coach', 'beginner', array['Siłowe', 'Przedramiona'], 'Trening prostowników nadgarstków ze sztangą opartą o ławkę. Przedramiona leżą na ławce, a Ty uginasz same nadgarstki — czysta izolacja.', '1. Zacznij od ułożenia sztangi po jednej stronie płaskiej ławki.
2. Uklęknij na obu kolanach tak, aby Twoje ciało było zwrócone do płaskiej ławki.
3. Chwyć sztangę chwytem nachwytem (palce w dół) i unieś ją tak, aby przedramiona opierały się o płaską ławkę. Nadgarstki powinny zwisać za jej krawędź.
4. Zacznij od uginania nadgarstków w górę robiąc wydech.
5. Powoli opuść nadgarstki z powrotem do pozycji startowej robiąc wdech.
6. Twoje przedramiona powinny pozostać nieruchome, ponieważ tylko nadgarstki wykonują ruch potrzebny do tego ćwiczenia.
7. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Palms-Down_Wrist_Curl_Over_A_Bench/0.jpg', 'free_exercise_db'),
  ('palms-up-barbell-wrist-curl-over-a-bench', 'Uginanie nadgarstków sztangą podchwytem na ławce', 'Palms-Up Barbell Wrist Curl Over A Bench', 'motor_coach', 'beginner', array['Siłowe', 'Przedramiona'], 'Trening zginaczy nadgarstków ze sztangą na ławce, chwytem podchwytem. Przedramiona na ławce, nadgarstki zwisają za krawędź i pracują samodzielnie.', '1. Zacznij od ułożenia sztangi po jednej stronie płaskiej ławki.
2. Uklęknij na obu kolanach tak, aby Twoje ciało było zwrócone do płaskiej ławki.
3. Chwyć sztangę chwytem podchwytem (palce w górę) i unieś ją tak, aby przedramiona opierały się o płaską ławkę. Nadgarstki powinny zwisać za jej krawędź.
4. Zacznij od uginania nadgarstków w górę robiąc wydech.
5. Powoli opuść nadgarstki z powrotem do pozycji startowej robiąc wdech.
6. Twoje przedramiona powinny pozostać nieruchome, ponieważ tylko nadgarstki wykonują ruch potrzebny do tego ćwiczenia.
7. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Palms-Up_Barbell_Wrist_Curl_Over_A_Bench/0.jpg', 'free_exercise_db'),
  ('palms-up-dumbbell-wrist-curl-over-a-bench', 'Uginanie nadgarstków hantlami podchwytem na ławce', 'Palms-Up Dumbbell Wrist Curl Over A Bench', 'motor_coach', 'beginner', array['Siłowe', 'Przedramiona'], 'Izolowana praca zginaczy nadgarstków z dwoma hantlami na ławce. Identyczna technika jak wersja ze sztangą, ale każde przedramię pracuje niezależnie.', '1. Zacznij od ułożenia dwóch hantli po jednej stronie płaskiej ławki.
2. Uklęknij na obu kolanach tak, aby Twoje ciało było zwrócone do płaskiej ławki.
3. Chwyć obiema rękami obie hantle chwytem podchwytem (palce w górę) i unieś je tak, aby przedramiona opierały się o płaską ławkę. Nadgarstki powinny zwisać za jej krawędź.
4. Zacznij od uginania nadgarstków w górę robiąc wydech.
5. Powoli opuść nadgarstki z powrotem do pozycji startowej robiąc wdech. Koniecznie weź wdech właśnie w tej fazie ćwiczenia.
6. Twoje przedramiona powinny pozostać nieruchome, ponieważ tylko nadgarstki wykonują ruch potrzebny do tego ćwiczenia.
7. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Palms-Up_Dumbbell_Wrist_Curl_Over_A_Bench/0.jpg', 'free_exercise_db'),
  ('parallel-bar-dip', 'Dipy na poręczach', 'Parallel Bar Dip', 'motor_coach', 'beginner', array['Siłowe', 'Triceps'], 'Klasyczne pompki na poręczach angażujące triceps i klatkę piersiową. Opuść się zginając ramiona do kąta 90 stopni, a potem wypchnij się w górę.', '1. Stań pomiędzy poręczami. Umieść dłoń na każdym drążku, a potem wykonaj mały podskok, który pomoże Ci przyjąć pozycję startową z zablokowanymi ramionami.
2. Zacznij od zgięcia łokci, opuszczając ciało, aż ramiona przejdą kąt 90 stopni. Unikaj kołysania i zachowuj dobrą postawę przez cały czas opuszczania.
3. Odwróć ruch prostując łokcie i wypychając się z powrotem do pozycji startowej.
4. Powtórz żądaną liczbę powtórzeń.', NULL, 'free-exercise-db/Parallel_Bar_Dip/0.jpg', 'free_exercise_db'),
  ('pelvic-tilt-into-bridge', 'Postawienie miednicy do mostka', 'Pelvic Tilt Into Bridge', 'motor_coach', 'intermediate', array['Rozciąganie', 'Dolny odcinek pleców'], 'Łagodne ćwiczenie mobilizujące kręgosłup: najpierw delikatne postawienie miednicy rozluźniające dolne plecy, potem przejście do pełnego mostka biodrowego.', '1. Połóż się ze stopami na podłodze, piętami dokładnie pod kolanami.
2. Unieś do sufitu tylko kość ogonową, aby rozciągnąć dolne plecy. (Nie uność jeszcze całego kręgosłupa.) Ściągnij brzuch.
3. Aby przejść do mostka, unoś cały kręgosłup z wyjątkiem szyi.', NULL, 'free-exercise-db/Pelvic_Tilt_Into_Bridge/0.jpg', 'free_exercise_db'),
  ('peroneals-smr', 'Automasaż mięśni strzałkowych rolerem (SMR)', 'Peroneals-SMR', 'motor_coach', 'intermediate', array['Rozciąganie', 'Łydki'], 'Samomasaż bocznej części podudzi (mięśnie strzałkowe) rolerem piankowym. Leżąc na boku rolujesz od kolana w dół do kostki, zatrzymując się na punktach napięcia.', '1. Połóż się na boku, opierając ciężar ciała na przedramieniu i rollercie piankowym umieszczonym na zewnętrznej stronie podudzia. Górna noga może leżeć na dolnej albo być przekrzyżowana przed Tobą. To Twoja pozycja startowa.
2. Unoś biodra nad ziemię i zacznij toczyć od miejsca poniżej kolana do miejsca nad kostką po zewnętrznej stronie nogi, zatrzymując się na punktach napięcia na 10–30 sekund. Powtórz na drugiej nodze.', NULL, 'free-exercise-db/Peroneals-SMR/0.jpg', 'free_exercise_db'),
  ('peroneals-stretch', 'Rozciąganie mięśni strzałkowych', 'Peroneals Stretch', 'motor_coach', 'intermediate', array['Rozciąganie', 'Łydki'], 'Rozciąganie bocznej części podudzi z pasem lub gumą. Siedząc, przyciągasz stopę do środka (inwersja), rozciągając mięśnie strzałkowe.', '1. W pozycji siedzącej owiń pas, linę albo gumę wokół jednej stopy. To Twoja pozycja startowa.
2. Z wyprostowaną nogą i piętą uniesioną nad ziemią, ciągnij za pas tak, aby stopa wywinęła się do środka, przy czym wewnętrzna strona stopy jest przyciągana ku Tobie. Przytrzymaj 10–20 sekund, a potem zmień strony.', NULL, 'free-exercise-db/Peroneals_Stretch/0.jpg', 'free_exercise_db'),
  ('physioball-hip-bridge', 'Mostek biodrowy na piłce gimnastycznej', 'Physioball Hip Bridge', 'motor_coach', 'beginner', array['Siłowe', 'Pośladki'], 'Mostek biodrowy wykonywany z górnymi plecami opartymi o piłkę gimnastyczną. Unośysz biodra siłą pośladków i dwugłowych uda, budując siłę tylnego łańcucha mięśniowego i stabilność.', '1. Połóż się na piłce tak, aby górne plecy były na piłce, a biodra bez podparcia. Stopy powinny być płasko na podłodze, na szerokość bioder lub szerzej. To Twoja pozycja startowa.
2. Zacznij od wyprostu bioder siłą pośladków i dwugłowych uda, unosząc biodra w górę podczas mostkowania.
3. Zatrzymaj się na szczycie ruchu i wróć do pozycji startowej.', NULL, 'free-exercise-db/Physioball_Hip_Bridge/0.jpg', 'free_exercise_db'),
  ('pin-presses', 'Wyciskanie z bolców (pin presses)', 'Pin Presses', 'motor_coach', 'intermediate', array['Trójbój', 'Triceps'], 'Wyciskanie leżąc z bolców w klatce do przysiadów, eliminujące fazę opuszczania sztangi. Buduje siłę startową i pozwala trenować wybrany zakres ruchu.', '1. Pin presses eliminują fazę ekscentryczną wyciskania leżąc, rozwijając siłę startową. Pozwalają też trenować wybrany zakres ruchu.
2. Ławka powinna być ustawiona w klatce do przysiadów (power rack). Ustaw bolce na pożądanym punkcie zakresu ruchu — czy to samo zablokowanie ramion, czy cal nad klatką. Drążek powinien zostać przeniesiony na bolce i przygotowany do podnoszenia.
3. Zacznij leżąc na ławce, z drążkiem bezpośrednio nad miejscem kontaktu jak przy normalnym wyciskaniu. Wsuń stopy pod siebie i wygnij plecy. Używając drążka jako pomocy w podtrzymaniu ciężaru, oderwij barki od ławki i ściągnij je, ściskając łopatki razem. Użyj stóp, by wbić mięsień czworoboczny w ławkę. Zachowaj tę ciasną pozycję ciała przez cały ruch.
4. Możesz użyć standardowego chwytu do wyciskania albo chwytu na szerokość barków, by skupić się na tricepsach. Drążek, nadgarstek i łokieć powinny pozostawać w linii przez cały czas. Skup się na ściskaniu drążka i próbie rozerwania go na pół.
5. Wypchnij drążek w górę z maksymalną siłą. Łokcie powinny pozostać blisko ciała aż do zablokowania.
6. Opuść drążek z powrotem na bolce, robiąc pauzę przed rozpoczęciem następnego powtórzenia.', NULL, 'free-exercise-db/Pin_Presses/0.jpg', 'free_exercise_db'),
  ('piriformis-smr', 'Automasaż gruszkowatego rolerem (SMR)', 'Piriformis-SMR', 'motor_coach', 'intermediate', array['Rozciąganie', 'Pośladki'], 'Samomasaż mięśnia gruszkowatego (głęboka część pośladka) rolerem piankowym. Siadasz na roller, krzyżujesz kostkę nad kolanem i rolujesz górną część pośladka.', '1. Siądź pośladkami na rollercie piankowym. Zegnij kolana, a potem przełóż jedną nogę tak, aby kostka znalazła się nad kolanem. To Twoja pozycja startowa.
2. Przenieś ciężar na stronę przełożonej nogi, toczenie się po pośladkach, aż poczujesz napięcie w górnej części pośladka. Możesz wspomóc rozciąganie, ciągnąc jedną ręką zgięte kolano w stronę klatki piersiowej. Przytrzymaj tę pozycję 10–30 sekund, a potem zmień strony.', NULL, 'free-exercise-db/Piriformis-SMR/0.jpg', 'free_exercise_db'),
  ('plank', 'Deska (plank)', 'Plank', 'motor_coach', 'beginner', array['Siłowe', 'Brzuch'], 'Izometryczne ćwiczenie na miśnie głębokie: utrzymujesz proste ciało w podporze na przedramionach i palcach stóp tak długo, jak potrafisz.', '1. Przyjmij pozycję na brzuchu na podłodze, wspierając ciężar na palcach stóp i przedramionach. Ramiona są zgięte i dokładnie pod barkami.
2. Trzymaj ciało prosto przez cały czas i utrzymuj tę pozycję jak najdłużej. Aby zwiększyć trudność, można unieść ramię lub nogę.', NULL, 'free-exercise-db/Plank/0.jpg', 'free_exercise_db'),
  ('plate-pinch', 'Szczypienie talerzy (plate pinch)', 'Plate Pinch', 'motor_coach', 'intermediate', array['Siłowe', 'Przedramiona'], 'Trening siły chwytu polegający na trzymaniu dwóch talerzy obciążników ściśniętych palcami. Proste, a bardzo skuteczne ćwiczenie na przedramię.', '1. Weź dwa talerze z szerokim rantem i złóż je razem gładkimi stronami na zewnątrz.
2. Użyj palców do chwycenia zewnętrznej części talerza, a kciuka — drugiej strony, tym samym trzymając oba talerze razem. To pozycja startowa.
3. Ściskaj talerz palcami i kciukiem. Trzymaj tę pozycję tak długo, jak potrafisz.
4. Powtórz zalecaną w programie liczbę serii.
5. Zmień ramiona i powtórz ruchy.', NULL, 'free-exercise-db/Plate_Pinch/0.jpg', 'free_exercise_db'),
  ('plate-twist', 'Skręty tułowia z talerzem', 'Plate Twist', 'motor_coach', 'intermediate', array['Siłowe', 'Brzuch'], 'Dynamiczne ćwiczenie na mięśnie skośne brzucha: siedząc z uniesionymi nogami kręcisz talerzem od podłogi po lewej do podłogi po prawej stronie.', '1. Połóż się na podłodze albo macie do ćwiczeń z całkowicie wyprostowanymi nogami i uniesionym tułowiem. Chwyć talerz za boki oburącz przed brzuchem z lekko zgiętymi ramionami.
2. Powoli skrzyżuj nogi przy kostkach i unoś je nad ziemię. Kolana też powinny być lekko zgięte. Uwaga: lekko cofnij górną część ciała, aby pomóc utrzymać równowagę podczas tego ćwiczenia. To pozycja startowa.
3. Przenieś talerz na lewą stronę i dotknij nim podłogi. Wypuszczaj powietrze wykonując ten ruch.
4. Wróć do pozycji startowej nabierając powietrza, a potem powtórz ruch, ale tym razem na prawą stronę ciała. Wskazówka: zawsze używaj wolnego, kontrolowanego ruchu. Szarpanie może uszkodzić plecy.
5. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Plate_Twist/0.jpg', 'free_exercise_db'),
  ('platform-hamstring-slides', 'Zsuwanie nóg po podłodze (hamstring slides)', 'Platform Hamstring Slides', 'motor_coach', 'beginner', array['Siłowe', 'Dwugłowe uda'], 'Izolacja dwugłowych uda bez sprzętu: leżąc na plecach zsuwasz piętę po gładkiej podłodze (na ręczniku), zginając kolano, a potem wracasz do startu.', '1. Do tego ruchu potrzebna jest drewniana podłoga lub podobna powierzchnia. Połóż się na plecach z wyprostowanymi nogami. Umieść ręcznik gimnastyczny albo lekki ciężar pod piętą. To Twoja pozycja startowa.
2. Rozpocznij ruch zginając kolano, utrzymując drugą nogę prosto.
3. Kontynuuj przyciąganie pięty bliżej siebie, sunąc nią po podłodze.
4. Przy pełnym zgięciu kolana odwróć ruch, aby wrócić do pozycji startowej.', NULL, 'free-exercise-db/Platform_Hamstring_Slides/0.jpg', 'free_exercise_db'),
  ('plie-dumbbell-squat', 'Przysiad sumo z hantlą', 'Plie Dumbbell Squat', 'motor_coach', 'beginner', array['Siłowe', 'Uda'], 'Przysiad w szerokim rozkroku ze stopami skręconymi na zewnątrz i hantlą trzymaną pionowo przy biodrach. Mocno angażuje wewnętrzne partie ud i pośladki.', '1. Trzymaj hantlę u podstawy oburącz i stań prosto. Rozstaw nogi szerzej niż szerokość barków z lekko ugiętymi kolanami.
2. Palce stóp powinny być skierowane na zewnątrz. Uwaga: ramiona powinny pozostać nieruchome podczas wykonywania ćwiczenia. To pozycja startowa.
3. Powoli zginaj kolana i opuszczaj ciało, aż uda będą równoległe do podłogi. Koniecznie nabierz powietrza — to faza ekscentryczna ćwiczenia.
4. Wypchnij ciało z powrotem do pozycji startowej głównie piętą robiąc wydech.
5. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Plie_Dumbbell_Squat/0.jpg', 'free_exercise_db'),
  ('plyo-kettlebell-pushups', 'Plyo pompki na kettlebell', 'Plyo Kettlebell Pushups', 'motor_coach', 'advanced', array['Siłowe', 'Klatka piersiowa'], 'Eksplozywna wersja pompek z kettlebell: przy każdym wypchnięciu przenosisz rękę na drugą stronę kettlebell, przełączając ręce w locie. Buduje moc klatki i stabilność barków.', '1. Umieść kettlebell na podłodze. Przyjmij pozycję pompek, na palcach stóp, z jedną ręką na ziemi, a drugą trzymającą kettlebell, z prostymi łokciami. To Twoja pozycja startowa.
2. Zacznij od opuszczenia się jak najniżej, zachowując proste plecy.
3. Szybko i mocno zmień kierunek, wypychając się na drugą stronę kettlebell, przełączając przy tym ręce. Kontynuuj ruch schodząc w dół i powtarzając naprzemiennie.', NULL, 'free-exercise-db/Plyo_Kettlebell_Pushups/0.jpg', 'free_exercise_db'),
  ('plyo-push-up', 'Pompki plyometryczne (z odbiciem)', 'Plyo Push-up', 'motor_coach', 'beginner', array['Plyometryka', 'Klatka piersiowa'], 'Eksplozywna wersja pompek: wypychasz tułów tak silnie, że dłonie odrywają się od podłogi. Wersja zaawansowana to pompki z klaśnięciem. Świetne na moc górnej części ciała.', '1. Przyjmij pozycję na brzuchu na podłodze, wspierając ciężar na dłoniach i palcach stóp.
2. Ramiona powinny być całkowicie wyprostowane, dłonie mniej więcej na szerokość barków. Zachowuj ciało prosto przez cały ruch. To Twoja pozycja startowa.
3. Opuszczaj ciało zginając łokcie, obniżając klatkę piersiową ku podłodze.
4. Na dole odwróć ruch, wypychając się przez wyprost łokci jak najszybciej. Spróbuj wypchnąć górną część ciała tak, aby dłonie oderwały się od podłogi.
5. Wróć do pozycji startowej i powtórz ćwiczenie.
6. Dla zwiększenia trudności dodaj klaśnięcie do ruchu, gdy jesteś w powietrzu.', NULL, 'free-exercise-db/Plyo_Push-up/0.jpg', 'free_exercise_db'),
  ('posterior-tibialis-stretch', 'Rozciąganie mięśnia piszczelowego tylnego', 'Posterior Tibialis Stretch', 'motor_coach', 'intermediate', array['Rozciąganie', 'Łydki'], 'Rozciąganie mięśnia piszczelowego tylnego z pasem lub gumą. Siedząc, przyciągasz stopę na zewnątrz (everzja), rozciągając tylną część podudzia.', '1. W pozycji siedzącej owiń pas, linę albo gumę wokół jednej stopy. To Twoja pozycja startowa.
2. Z wyprostowaną nogą i piętą uniesioną nad ziemią, ciągnij za pas tak, aby stopa wywinęła się na zewnątrz, przy czym zewnętrzna strona stopy jest przyciągana ku Tobie. Przytrzymaj 10–20 sekund, a potem zmień strony.', NULL, 'free-exercise-db/Posterior_Tibialis_Stretch/0.jpg', 'free_exercise_db'),
  ('power-clean', 'Wytracenie ciężaru (power clean)', 'Power Clean', 'motor_coach', 'intermediate', array['Siłowe', 'Dwugłowe uda'], 'Olimpijskie ćwiczenie mocy: sztanga z podłogi trafia na obojczyk jednym eksplozywnym ciągiem bioder, nóg i barków. Buduje całą moc ciała; technika jest wielofazowa i wymaga precyzji.', '1. Stań ze stopami lekko szerzej niż szerokość barków i palcami skręconymi lekko na zewnątrz.
2. Uklęknij i chwyć drążek pełnym chwytem nachwytem. Dłonie powinny być nieco szerzej niż szerokość barków, na zewnątrz kolan, z całkowicie prostymi łokciami.
3. Umieść drążek ok. 2,5 cm przed goleńiami i nad śródstopiem.
4. Plecy powinny być płaskie lub lekko wygięte, klatka piersiowa uniesiona i wypchnięta, a łopatki ściągnięte.
5. Trzymaj głowę w pozycji neutralnej (w linii kręgosłupa, bez pochylania ani obracania), ze wzrokiem skierowanym prosto przed siebie. Nabierz powietrza w tej fazie.
6. Oderwij drążek od podłogi, mocno prostując biodra i kolana, robiąc wydech. Wskazówka: górna część tułowia powinna zachować ten sam kąt. Nie zginaj się jeszcze w pasie i nie pozwól, by biodra wzbiły się przed barkami (to sprawiłoby, że pośladki pójdą w górę, a dwugłowe uda zostaną naciągnięte).
7. Trzymaj łokcie całkowicie wyprostowane, głowę neutralnie, a barki nad drążkiem.
8. Gdy drążek idzie w górę, utrzymuj go jak najbliżej goleń.
9. Gdy drążek mijają kolana, wypchnij biodra do przodu i lekko ugnij kolana, aby ich nie zablokować. Wskazówka: w tym punkcie Twoje uda powinny dotykać drążka.
10. Trzymaj plecy płaskie lub lekko wygięte, łokcie całkowicie proste, a głowę neutralną. Wskazówka: będziesz wstrzymywał oddech do następnej fazy.
11. Nabierz powietrza, a potem mocno i szybko wyprostuj biodra i kolana oraz wbij się na palce stóp.
12. Utrzymuj drążek jak najbliżej ciała. Wskazówka: plecy powinny być płaskie, łokcie skierowane na boki, głowa neutralna. Trzymaj też barki nad drążkiem i ramiona prosto tak długo, jak to możliwe.
13. Gdy stawy dolnej części ciała są całkowicie wyprostowane, gwałtownie wznieś barki w górę, nie pozwalając jeszcze na zgięcie łokci. Robiąc tę część ruchu, wydychaj powietrze.
14. Gdy barki osiągną najwyższe uniesienie, zegnij łokcie, aby rozpocząć podciąganie ciała pod drążek.
15. Kontynuuj ciągnięcie ramion jak najwyżej i jak najdłużej. Wskazówka: ze względu na eksplozywny charakter tej fazy Twój tułów będzie wyprostowany lub z wygiętymi plecami, głowa będzie lekko odchylona do tyłu, a stopy mogą stracić kontakt z podłogą.
16. Po całkowitym wyproście dolnej części ciała, gdy drążek osiągnie niemal maksymalną wysokość, przeciągnij ciało pod drążek i obróć ramiona wokół i pod drążek.
17. Jednocześnie zegnij biodra i kolana do pozycji ćwierćprzysiadu.
18. Gdy ramiona znajdą się pod drążkiem, nabierz powietrza, a potem unieś łokcie, ustawiając górne ramiona równolegle do podłogi. Przyjmij drążek na przednią część obojczyków i mięśnie przednich partii barków.
19. Złap drążek z wyprostowanym i napiętym tułowiem, neutralnym ustawieniem głowy i płaskimi stopami. Wydychaj powietrze podczas tego ruchu.
20. Wstań prostując biodra i kolana do pozycji całkowicie wyprostowanej.
21. Opuść drążek stopniowo redukując napięcie mięśniowe ramion, aby pozwolić na kontrolowany zjazd drążka do ud. Nabierz powietrza podczas tego ruchu.
22. Jednocześnie zegnij biodra i kolana, aby złagodzić uderzenie drążka o uda.
23. Uklęknij z całkowicie prostymi łokciami, aż drążek dotknie podłogi.
24. Zacznij od nowa fazę 1 i powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Power_Clean/0.jpg', 'free_exercise_db'),
  ('power-clean-from-blocks', 'Wyburzenie z bloków (power clean)', 'Power Clean from Blocks', 'motor_coach', 'intermediate', array['Podnoszenie ciężarów', 'Dwugłowe uda'], 'Olimpijskie ćwiczenie siłowo-szybkościowe wykonywane ze sztangą ustawioną na blokach. Eksplozywnie ciągniesz sztangę w górę całym ciałem i przyjmujesz ją na barkach. Buduje moc nóg, bioder i pleców.', '1. Ze sztangą ustawioną na blokach o żądanej wysokości chwyć drążek tuż na zewnątrz nóg. Obniż biodra z ciężarem przeniesionym na pięty, plecy proste, głowa skierowana do przodu, klatka piersiowa w górze, a barki tuż przed sztangą. To będzie pozycja startowa.
2. Rozpocznij pierwszy ciąg, odpychając się piętami i prostując kolana. Kąt tułowia powinien pozostać bez zmian, a ramiona wyprostowane. Gdy sztanga zbliży się do środka ud, zacznij prostować biodra.
3. W ruchu przypominającym wyskok przyspiesz, prostując biodra, kolana i stawy skokowe, używając prędkości, aby poprowadzić sztangę w górę. Nie ma potrzeby aktywnego podciągania ramionami, aby przyspieszyć ciężar. Na końcu drugiego ciągu ciało powinno być w pełni wyprostowane, lekko odchylone do tyłu, z ramionami nadal wyprostowanymi.
4. Gdy uzyskasz pełny wyprost, przejdź do trzeciego ciągu, agresywnie wykonując szrug i zginając ramiona z łokciami uniesionymi w górę i na boki. W szczycie wyprostu podciągnij się pod sztangę na tyle, aby mogła spocząć na barkach, obracając łokcie pod sztangą. Sztanga powinna spocząć na wysuniętych do przodu barkach, delikatnie dotykając gardła, z rozluźnionymi dłońmi.
5. Natychmiast wróć do góry, odpychając się piętami, trzymając tułów pionowo, a łokcie wysoko. Kontynuuj, aż wstaniesz do pozycji stojącej, i zakończ powtórzenie, odkładając ciężar z powrotem na bloki.', NULL, 'free-exercise-db/Power_Clean_from_Blocks/0.jpg', 'free_exercise_db'),
  ('power-jerk', 'Podrzut bez rozkroku (power jerk)', 'Power Jerk', 'motor_coach', 'advanced', array['Podnoszenie ciężarów', 'Uda'], 'Olimpijska odmiana podrzutu bez rozkroku nóg. Wypychasz sztangę nad głowę mocnym wybiciem z ugiętych kolan i przyjmujesz ją na lekko ugiętych nogach.', '1. Stojąc ze sztangą spoczywającą z przodu na barkach, zacznij od krótkiego przysiadu podszczytowego. Ze stopami bezpośrednio pod biodrami uginaj kolana, nie cofając bioder. Zejdź tylko nieznacznie w dół i jak najmocniej odwróć kierunek ruchu.
2. Odepchnij się piętami, wytwarzając jak największą prędkość i siłę, i pamiętaj, aby odsunąć głowę z toru ruchu, gdy sztanga odrywa się od barków.
3. W momencie, gdy stopy odrywają się od podłogi, muszą zostać ustawione w pozycji przyjęcia jak najszybciej. W krótkiej chwili, gdy stopy nie odpychają aktywnie od platformy, wysiłek włożony w wypchnięcie sztangi w górę pchnie cię w dół. Stopy powinny być przesunięte na nieco szerszą postawę, z częściowo ugiętymi kolanami.
4. Przyjmij sztangę z ramionami zablokowanymi nad głową.
5. Wróć do pozycji stojącej.', NULL, 'free-exercise-db/Power_Jerk/0.jpg', 'free_exercise_db'),
  ('power-partials', 'Unoszenie hantli na boki (power partials)', 'Power Partials', 'motor_coach', 'beginner', array['Siłowe', 'Barki'], 'Unoszenie hantli bokiem do wysokości barków. Ćwiczenie izoluje boczne aktony barków i poprawia szerokość sylwetki.', '1. Stań wyprostowany z tułowiem w pionie, trzymając w każdej dłoni hantlę na długości wyprostowanych ramion. Łokcie powinny być blisko tułowia.
2. Dłonie powinny być zwrócone ku tułowiu. Stopy rozstawione mniej więcej na szerokość barków. To będzie pozycja startowa.
3. Trzymając ramiona proste, a tułów nieruchomo, unieś hantle na boki, aż znajdą się mniej więcej na wysokości barków, robiąc wydech.
4. Poczuj napięcie przez sekundę i zacznij opuszczać hantle z powrotem do pozycji startowej, robiąc wdech. Wskazówka: trzymaj dłonie skierowane w dół, z małym palcem nieco wyżej podczas unoszenia i opuszczania hantli — skupi to obciążenie głównie na barkach.
5. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Power_Partials/0.jpg', 'free_exercise_db'),
  ('power-snatch', 'Rwanie z wyskokiem (power snatch)', 'Power Snatch', 'motor_coach', 'advanced', array['Podnoszenie ciężarów', 'Dwugłowe uda'], 'Rwanie sztangi z podłogi z przyjęciem w częściowym przysiadzie. Wysoce techniczne, eksplozywne ćwiczenie angażujące całe ciało.', '1. Zacznij z obciążoną sztangą na podłodze. Sztanga powinna być blisko lub dotykać piszczeli, a chwyt powinien być szeroki. Stopy powinny być bezpośrednio pod biodrami, wyturniowane na zewnątrz w razie potrzeby. Obniż biodra, z klatką piersiową w górze i wzrokiem skierowanym do przodu. Barki tuż przed sztangą. To będzie pozycja startowa.
2. Rozpocznij pierwszy ciąg, odpychając się przednią częścią pięt i podnosząc sztangę z ziemi. Kąt tułowia powinien pozostać bez zmian, dopóki sztanga nie minie kolan.
3. Przejdź do drugiego ciągu, prostując biodra, kolana i stawy skokowe, pchając sztangę w górę jak najszybciej. Sztanga powinna być blisko ciała. W szczycie wyprostu wykonaj szrug i pozwól łokiom ugiąć się na boki.
4. Przenosząc stopy do pozycji przyjęcia, nieco szerszej, podciągnij się pod sztangę, unosząc ją nad głowę. Sztanga powinna zostać przyjęta w częściowym przysiadzie. Kontynuuj unoszenie sztangi do pozycji nad głową, przyjmując ją z ramionami zablokowanymi nad głową.
5. Wróć do pozycji stojącej z ciężarem nad głową.', NULL, 'free-exercise-db/Power_Snatch/0.jpg', 'free_exercise_db'),
  ('power-snatch-from-blocks', 'Rwanie z wyskokiem z bloków', 'Power Snatch from Blocks', 'motor_coach', 'intermediate', array['Podnoszenie ciężarów', 'Uda'], 'Rwanie z wyskokiem wykonywane ze sztangą na blokach. Pozwala skupić się na drugim ciągu i przyjęciu sztangi nad głowę.', '1. Zacznij z obciążoną sztangą na blokach lub stojakach o żądanej wysokości. Chwyt powinien być szeroki. Stopy bezpośrednio pod biodrami, wyturniowane na zewnątrz w razie potrzeby. Obniż biodra, z klatką piersiową w górze i wzrokiem skierowanym do przodu. Barki tuż przed sztangą, łokcie skierowane na boki. To będzie pozycja startowa.
2. Rozpocznij pierwszy ciąg, odpychając się przednią częścią pięt i podnosząc sztangę z bloków.
3. Przejdź do drugiego ciągu, prostując biodra, kolana i stawy skokowe, pchając sztangę w górę jak najszybciej. Sztanga powinna być blisko ciała. W szczycie wyprostu wykonaj szrug i pozwól łokiom ugiąć się na boki.
4. Przenosząc stopy do pozycji przyjęcia, mocno podciągnij się pod sztangę, unosząc ją nad głowę. Stopy powinny ustawić się tuż na zewnątrz bioder, wyturniowane na zewnątrz w razie potrzeby. Przyjmij sztangę nad pełnym przysiadem z ramionami w pełni wyprostowanymi nad głową.
5. Trzymając sztangę w linii nad przednią częścią pięt, z głową i klatką piersiową w górze, odpychaj się piętami, aby przejść do pozycji stojącej. Ostrożnie odłóż ciężar z powrotem na bloki.', NULL, 'free-exercise-db/Power_Snatch_from_Blocks/0.jpg', 'free_exercise_db'),
  ('power-stairs', 'Wnoszenie ciężaru po schodach (power stairs)', 'Power Stairs', 'motor_coach', 'intermediate', array['Strongman', 'Dwugłowe uda'], 'Ćwiczenie strongman: wnoszenie ciężkiego przedmiotu po schodach. Na treningu można użyć opony lub skrzyni. Buduje siłę całego ciała i wydolność.', '1. W tym ćwiczeniu przedmioty wnosi się po schodach w górę. W celach treningowych można je wykonywać z oponą lub skrzynią.
2. Zacznij od chwycenia przedmiotu oburącz. Ustaw stopy szeroko, z głową i klatką piersiową w górze. Odepchnij się od ziemi piętami, prostując kolana i biodra, aby podnieść ciężar z ziemi.
3. Odchylając się do tyłu, spróbuj przerzucić ciężar na stopień, który ma zwykle około 40–45 cm wysokości. Możesz użyć nóg, aby pomóc wepchnąć ciężar na stopień.
4. Powtórz 3–5 powtórzeń, a następnie kontynuuj z większym ciężarem, poruszając się jak najszybciej.', NULL, 'free-exercise-db/Power_Stairs/0.jpg', 'free_exercise_db'),
  ('preacher-curl', 'Uginanie ramion na modlitewniku', 'Preacher Curl', 'motor_coach', 'beginner', array['Siłowe', 'Biceps'], 'Klasyczne uginanie ramion na biceps na modlitewniku z gryfem E-Z. Izoluje biceps i ogranicza oszukiwanie ruchem tułowia.', '1. Do wykonania tego ćwiczenia potrzebujesz modlitewnika i gryfu E-Z. Chwyć gryf curl na wewnętrznym, wąskim uchwycie (najlepiej niech ktoś poda ci gryf albo złap go z przedniego stojaka, który mają większość modlitewników). Dłonie powinny być zwrócone do przodu i lekko skręcone do środka ze względu na kształt gryfu.
2. Z górnymi ramionami opartymi o poduszkę modlitewnika i klatką piersiową przyciśniętą do niej, trzymaj gryf E-Z na szerokości barków. To będzie pozycja startowa.
3. Robiąc wdech, powoli opuszczaj gryf, aż ramię będzie wyprostowane, a biceps w pełni rozciągnięty.
4. Robiąc wydech, użyj bicepsa, aby ugiąć ramiona, aż biceps będzie w pełni napięty, a gryf na wysokości barków. Mocno zepnij biceps i przytrzymaj tę pozycję przez sekundę.
5. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Preacher_Curl/0.jpg', 'free_exercise_db'),
  ('preacher-hammer-dumbbell-curl', 'Uginanie ramion młotkowe na modlitewniku', 'Preacher Hammer Dumbbell Curl', 'motor_coach', 'beginner', array['Siłowe', 'Biceps'], 'Uginanie ramion chwytem neutralnym (młotkowym) na modlitewniku. Angażuje biceps i mięsień ramienno-promieniowy.', '1. Połóż górną część obu ramion na modlitewniku, trzymając w każdej dłoni hantlę, z dłońmi zwróconymi do siebie (chwyt neutralny).
2. Robiąc wdech, powoli opuszczaj hantle, aż ramię będzie wyprostowane, a biceps w pełni rozciągnięty.
3. Robiąc wydech, użyj bicepsa, aby ugiąć ramiona, aż biceps będzie w pełni napięty, a hantle na wysokości barków.
4. Mocno zepnij biceps na sekundę w pozycji napiętej i powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Preacher_Hammer_Dumbbell_Curl/0.jpg', 'free_exercise_db'),
  ('press-sit-up', 'Brzuszki z wyciskaniem sztangi', 'Press Sit-Up', 'motor_coach', 'advanced', array['Siłowe', 'Brzuch'], 'Brzuszek połączony z wyciskaniem sztangi nad głowę. Łączy pracę mięśni brzucha z wyciskaniem.', '1. Na początek połóż się na ławce ze sztangą spoczywającą na klatce piersiowej. Ustaw nogi tak, aby były zabezpieczone na podpórkach ławki do brzucha. To jest pozycja startowa.
2. Robiąc wdech, napnij mięśnie brzucha i pośladki. Jednocześnie zwijaj tułów, jak przy brzuszkach, i wyciskaj sztangę nad głowę, robiąc wydech. Wskazówka: używaj ramion do wypchnięcia sztangi podczas ćwiczenia, nadal koncentrując się na mięśniach brzucha.
3. Opuść górną część ciała z powrotem do pozycji startowej, jednocześnie ściągając sztangę z powrotem na klatkę piersiową. Pamiętaj o wdechu podczas opuszczania ciała.
4. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Press_Sit-Up/0.jpg', 'free_exercise_db'),
  ('prone-manual-hamstring', 'Uginanie nóg leżąc na brzuchu z oporem partnera', 'Prone Manual Hamstring', 'motor_coach', 'beginner', array['Siłowe', 'Dwugłowe uda'], 'Uginanie nóg leżąc na brzuchu, w którym opór stawia partner dłonią na pięcie. Wzmacnia dwugłowe uda.', '1. Do tego ćwiczenia potrzebujesz partnera. Połóż się na brzuchu z prostymi nogami. Partner położy swoją dłoń na twojej pięcie.
2. Na początek ugnij kolano, przyciągając nogę do góry. Partner powinien stawiać opór, zaczynając delikatnie i zwiększając nacisk w miarę kończenia ruchu. Komunikuj się z partnerem, aby kontrolować odpowiedni poziom oporu.
3. Zatrzymaj się na chwilę na górze i wróć nogą do pozycji startowej, podczas gdy partner stawia opór w przeciwnym kierunku.', NULL, 'free-exercise-db/Prone_Manual_Hamstring/0.jpg', 'free_exercise_db'),
  ('prowler-sprint', 'Sprint z sań treningowych (prowler)', 'Prowler Sprint', 'motor_coach', 'beginner', array['Cardio', 'Dwugłowe uda'], 'Sprint z pchaniem sań treningowych. Rozwija moc nóg, szybkość i wydolność.', '1. Ustaw sanie na odpowiedniej powierzchni, załaduj odpowiedni ciężar. Sanie powinno stawiać wystarczający opór, aby wymagało wysiłku, ale nie na tyle ciężkie, aby cię znacząco spowalniało.
2. Do tego ćwiczenia możesz użyć wysokich lub niskich uchwytów. Chwyć uchwyty wyprostowanymi ramionami, opierając się na saniah.
3. Z dobrą postawą odpychaj się od ziemi krótkimi, naprzemiennymi krokami. Przemieszczaj się jak najszybciej na krótkim dystansie.', NULL, 'free-exercise-db/Prowler_Sprint/0.jpg', 'free_exercise_db'),
  ('pull-through', 'Wyprost bioder z liną wyciągu dolnego (pull through)', 'Pull Through', 'motor_coach', 'beginner', array['Siłowe', 'Pośladki'], 'Wyprost bioder z liną wyciągu dolnego przeciągniętą między nogami. Wzmacnia pośladki i tył uda.', '1. Stań kilka stóp przed wyciągiem dolnym z przymocowaną liną lub uchwytem. Odwróć się plecami do maszyny, okrakiem nad liną, ze stopami szeroko rozstawionymi.
2. Rozpocznij ruch, sięgając między nogami jak najdalej, zginając się w biodrach. Trzymaj kolana lekko ugięte. Z ramionami wyprostowanymi wyprostuj biodra, aby stanąć prosto. Unikaj podciągania w górę barkami; cały ruch powinien pochodzić z bioder.', NULL, 'free-exercise-db/Pull_Through/0.jpg', 'free_exercise_db'),
  ('pullups', 'Podciąganie na drążku', 'Pullups', 'motor_coach', 'beginner', array['Siłowe', 'Najszersze grzbietu'], 'Podciąganie na drążku nachwytem. Podstawowe ćwiczenie na najszersze mięśnie pleców i biceps.', '1. Złap drążek chwytem nachwytem (dłonie skierowane do przodu) w zalecanym rozstawie. Uwaga o chwytach: przy szerokim chwycie dłonie muszą być rozstawione szerzej niż szerokość barków. Przy średnim chwycie dłonie powinny być rozstawione na szerokość barków, a przy wąskim — węziej niż szerokość barków.
2. Z oboma ramionami wyprostowanymi przed sobą i drążkiem trzymanym w wybranym rozstawie odchyl tułów do tyłu o około 30 stopni, tworząc wygięcie w dolnej części pleców i wypychając klatkę piersiową do przodu. To jest pozycja startowa.
3. Podciągnij tułów w górę, aż drążek dotknie górnej części klatki piersiowej, ściągając barki i ramiona w dół i do tyłu. Wydechaj podczas tej części ruchu. Wskazówka: skoncentruj się na zaciśnięciu mięśni pleców, gdy osiągniesz pełną pozycję napiętą. Górna część tułowia powinna pozostać nieruchoma w przestrzeni, a poruszać się powinny tylko ramiona. Przedramiona nie powinny wykonywać żadnej innej pracy poza trzymaniem drążka.
4. Po sekundzie w pozycji napiętej zacznij wdech i powoli opuszczaj tułów do pozycji startowej, aż ramiona będą w pełni wyprostowane, a najszersze mięśnie pleców w pełni rozciągnięte.
5. Powtórz ten ruch zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Pullups/0.jpg', 'free_exercise_db'),
  ('push-press-behind-the-neck', 'Wyciskanie z wybiciem zza karku', 'Push Press - Behind the Neck', 'motor_coach', 'intermediate', array['Podnoszenie ciężarów', 'Barki'], 'Wyciskanie sztangi zza karku z wybiciem nóg. Pozwala użyć większego ciężaru niż wyciskanie ściśle.', '1. Stojąc ze sztangą spoczywającą z tyłu na barkach, zacznij od krótkiego przysiadu. Ze stopami bezpośrednio pod biodrami uginaj kolana, nie cofając bioder. Zejdź tylko nieznacznie i jak najmocniej odwróć kierunek ruchu. Odepchnij się piętami, wytwarzając jak największą prędkość i siłę, prowadząc sztangę po pionowej linii.
2. Wykorzystując wygenerowany rozpęd, dokończ wyciskanie ciężaru nad głowę, prostując ramiona.
3. Wróć do pozycji startowej, amortyzując uderzenie nogami.', NULL, 'free-exercise-db/Push_Press_-_Behind_the_Neck/0.jpg', 'free_exercise_db'),
  ('push-up-to-side-plank', 'Pompka z przejściem do deski bocznej', 'Push Up to Side Plank', 'motor_coach', 'beginner', array['Siłowe', 'Klatka piersiowa'], 'Pompka połączona z obrotem ciała do deski bocznej z uniesionym ramieniem. Angażuje klatkę piersiową i mięśnie głębokie.', '1. Przyjmij pozycję pompki na palcach stóp, z dłońmi tuż na zewnątrz szerokości barków.
2. Wykonaj pompkę, pozwalając łokiom się ugiąć. Podczas opuszczania trzymaj ciało prosto.
3. Zrób jedną pompkę i przy unoszeniu przenieś ciężar ciała na lewą stronę, obracaj się na bok, unosząc prawe ramię ku sufitowi w desce bocznej.
4. Opuść ramię z powrotem do podłogi dla kolejnej pompki, a następnie obróć się na drugą stronę.
5. Powtarzaj serię, naprzemiennie po obu stronach, przez 10 lub więcej powtórzeń.', NULL, 'free-exercise-db/Push_Up_to_Side_Plank/0.jpg', 'free_exercise_db'),
  ('push-up-wide', 'Pompki szerokie', 'Push-Up Wide', 'motor_coach', 'beginner', array['Siłowe', 'Klatka piersiowa'], 'Pompki z dłońmi szeroko rozstawionymi. Mocniej angażują klatkę piersiową niż klasyczne pompki.', '1. Z dłońmi szeroko rozstawionymi podpieraj ciało na palcach stóp i dłoniach w pozycji deski. Łokcie powinny być wyprostowane, a ciało proste. Nie pozwól, aby biodra opadały. To będzie pozycja startowa.
2. Na początek pozwól łokiom się ugiąć, opuszczając klatkę piersiową do podłogi, robiąc wdech.
3. Używając mięśni piersiowych, wypchnij górną część ciała z powrotem do pozycji startowej, prostując łokcie. Wydechaj podczas tego kroku.
4. Po zatrzymaniu w pozycji napiętej powtórz ruch zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Push-Up_Wide/0.jpg', 'free_exercise_db'),
  ('push-ups-close-triceps-position', 'Pompki wąskie (na triceps)', 'Push-Ups - Close Triceps Position', 'motor_coach', 'intermediate', array['Siłowe', 'Triceps'], 'Pompki z dłońmi blisko siebie pod klatką piersiową. Głównym pracującym mięśniem jest triceps.', '1. Połóż się na podłodze twarzą w dół i ustaw dłonie węziej niż szerokość barków, w wąskiej pozycji. Upewnij się, że trzymasz tułów uniesiony na wyprostowanych ramionach.
2. Opuść się, aż klatka piersiowa prawie dotknie podłogi, robiąc wdech.
3. Używając tricepsa i części mięśni piersiowych, wypchnij górną część ciała z powrotem do pozycji startowej i zepnij klatkę piersiową. Wydechaj podczas tego kroku.
4. Po sekundowej pauzie w pozycji napiętej powtórz ruch zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Push-Ups_-_Close_Triceps_Position/0.jpg', 'free_exercise_db'),
  ('push-ups-with-feet-elevated', 'Pompki z nogami na podwyższeniu', 'Push-Ups With Feet Elevated', 'motor_coach', 'beginner', array['Siłowe', 'Klatka piersiowa'], 'Pompki ze stopami opartymi na ławce. Uniesienie nóg zwiększa obciążenie klatki piersiowej i barków.', '1. Połóż się na podłodze twarzą w dół i ustaw dłonie około 90 cm od siebie, trzymając tułów uniesiony na wyprostowanych ramionach.
2. Połóż palce stóp na płaskiej ławce. To uniesie twoje ciało. Uwaga: im wyższe uniesienie płaskiej ławki, tym większy opór ćwiczenia.
3. Opuść się, aż klatka piersiowa prawie dotknie podłogi, robiąc wdech.
4. Używając mięśni piersiowych, wypchnij górną część ciała z powrotem do pozycji startowej i zepnij klatkę piersiową. Wydechaj podczas tego kroku.
5. Po sekundowej pauzie w pozycji napiętej powtórz ruch zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Push-Ups_With_Feet_Elevated/0.jpg', 'free_exercise_db'),
  ('push-ups-with-feet-on-an-exercise-ball', 'Pompki z nogami na piłce gimnastycznej', 'Push-Ups With Feet On An Exercise Ball', 'motor_coach', 'intermediate', array['Siłowe', 'Klatka piersiowa'], 'Pompki ze stopami na piłce gimnastycznej. Niestabilne podparcie dodatkowo angażuje mięśnie głębokie.', '1. Połóż się na podłodze twarzą w dół i ustaw dłonie około 90 cm od siebie, trzymając tułów uniesiony na wyprostowanych ramionach.
2. Połóż palce stóp na piłce gimnastycznej. To uniesie twoje ciało.
3. Opuść się, aż klatka piersiowa prawie dotknie podłogi, robiąc wdech.
4. Używając mięśni piersiowych, wypchnij górną część ciała z powrotem do pozycji startowej i zepnij klatkę piersiową. Wydechaj podczas tego kroku.
5. Po sekundowej pauzie w pozycji napiętej powtórz ruch zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Push-Ups_With_Feet_On_An_Exercise_Ball/0.jpg', 'free_exercise_db'),
  ('pushups', 'Pompki klasyczne', 'Pushups', 'motor_coach', 'beginner', array['Siłowe', 'Klatka piersiowa'], 'Klasyczne pompki na prostych nogach. Budują siłę klatki piersiowej, barków i tricepsa.', '1. Połóż się na podłodze twarzą w dół i ustaw dłonie około 90 cm od siebie, trzymając tułów uniesiony na wyprostowanych ramionach.
2. Następnie opuść się w dół, aż klatka piersiowa prawie dotknie podłogi, robiąc wdech.
3. Teraz zrób wydech i wypchnij górną część ciała z powrotem do pozycji startowej, spinając klatkę piersiową.
4. Po krótkiej pauzie na górze w pozycji napiętej możesz zacząć opuszczać się ponownie w dół, wykonując tyle powtórzeń, ile potrzebujesz.', NULL, 'free-exercise-db/Pushups/0.jpg', 'free_exercise_db'),
  ('pushups-close-and-wide-hand-positions', 'Pompki (pozycja dłoni wąska i szeroka)', 'Pushups (Close and Wide Hand Positions)', 'motor_coach', 'beginner', array['Siłowe', 'Klatka piersiowa'], 'Wariant pompek z dłońmi ustawionymi wąsko albo szeroko. Wersja szeroka angażuje bardziej klatkę, wąska — triceps.', '1. Połóż się twarzą w dół z ciałem prosto, palcami stóp na podłodze i dłońmi szerzej niż szerokość barków (szeroka pozycja) albo węziej niż szerokość barków (wąska pozycja). Upewnij się, że trzymasz tułów uniesiony na wyprostowanych ramionach.
2. Opuść się, aż klatka piersiowa prawie dotknie podłogi, robiąc wdech.
3. Używając mięśni piersiowych, wypchnij górną część ciała z powrotem do pozycji startowej i zepnij klatkę piersiową. Wydechaj podczas tego kroku.
4. Po sekundowej pauzie w pozycji napiętej powtórz ruch zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Pushups_Close_and_Wide_Hand_Positions/0.jpg', 'free_exercise_db'),
  ('pyramid', 'Piramida na piłce gimnastycznej', 'Pyramid', 'motor_coach', 'beginner', array['Rozciąganie', 'Dolny odcinek pleców'], 'Rozwijanie tułowia na piłce gimnastycznej do pozycji odwróconej, z biodrami na szczycie piłki. Buduje siłę stabilizacyjną korpusu i barków.', '1. Na początek przetaczaj tułów do przodu po piłce, aż biodra oprą się na szczycie piłki i staną najwyższym punktem twojego ciała.
2. Oprzyj dłonie i stopy na podłodze. Ramiona i nogi mogą być lekko ugięte lub proste, w zależności od wielkości piłki, twojej gibkości i długości kończyn. To ćwiczenie rozwija też siłę stabilizacyjną tułowia i barków.', NULL, 'free-exercise-db/Pyramid/0.jpg', 'free_exercise_db'),
  ('quad-stretch', 'Rozciąganie czworogłowych uda z pasem', 'Quad Stretch', 'motor_coach', 'intermediate', array['Rozciąganie', 'Uda'], 'Rozciąganie mięśnia czworogłowego uda w leżeniu na boku, z pasem lub gumą założoną na stopę.', '1. Połóż się na boku. Załóż pas, linę lub gumę na górną stopę. Ugnij kolano i wypchnij biodro do przodu, próbując dotknąć stopą pośladka, trzymając pas w dłoniach. To będzie pozycja startowa.
2. Trzymając pas nad barkiem lub nad głową, delikatnie ciągnij, aby zwiększyć rozciąganie czworogłowych uda. Przytrzymaj 10–20 sekund, a następnie zmień stronę.', NULL, 'free-exercise-db/Quad_Stretch/0.jpg', 'free_exercise_db'),
  ('quadriceps-smr', 'Rolowanie czworogłowych uda (SMR)', 'Quadriceps-SMR', 'motor_coach', 'intermediate', array['Rozciąganie', 'Uda'], 'Automasaż miękkości (foam rolling) mięśni czworogłowych uda na wałku. Rozluźnia napięcia i poprawia zakres ruchu.', '1. Połóż się twarzą w dół na podłodze, opierając ciężar na dłoniach lub przedramionach. Umieść wałek pod jednym udem, na mięśniu czworogłowym, i trzymaj stopę uniesioną nad ziemią. Pamiętaj, aby maksymalnie rozluźnić nogę. To będzie pozycja startowa.
2. Przenosząc tyle ciężaru na rolowaną nogę, ile znosisz, przetaczaj się po wałku od miejsca nad kolanem do miejsca poniżej biodra, zatrzymując się w punktach napięcia na 10–30 sekund. Zmień stronę.', NULL, 'free-exercise-db/Quadriceps-SMR/0.jpg', 'free_exercise_db'),
  ('quick-leap', 'Szybki wyskok na skrzynię', 'Quick Leap', 'motor_coach', 'beginner', array['Plyometryka', 'Uda'], 'Eksplozywny wyskok na skrzynię z natychmiastowym odbiciem w górę. Ćwiczenie pliometryczne budujące moc nóg.', '1. Do tego ćwiczenia potrzebujesz skrzyni.
2. Zacznij twarzą do skrzyni, stojąc 30–60 cm od jej krawędzi.
3. Wykorzystując biodra, wyskocz na skrzynię, lądując na obu nogach. Upewnij się, że lądujesz z ugiętymi nogami i płasko ustawionymi stopami.
4. Natychmiast po lądowaniu w pełni wyprostuj całe ciało i wymachnij ramionami nad głowę, odbijając się ze skrzyni w górę. Użyj nóg, aby amortyzować siłę lądowania.', NULL, 'free-exercise-db/Quick_Leap/0.jpg', 'free_exercise_db'),
  ('rack-delivery', 'Podanie sztangi na barki (rack delivery)', 'Rack Delivery', 'motor_coach', 'intermediate', array['Podnoszenie ciężarów', 'Barki'], 'Ćwiczenie techniczne podnoszenia ciężarów: naukę przekładania łokci, by dostawić sztangę do pozycji na barkach. Wykonywane bez obciążenia lub z lekkim gryfem.', '1. To ćwiczenie uczy dostawiania sztangi do pozycji na barkach. Zacznij trzymając gryf w pozycji stracha na wróble: ramiona równolegle do podłogi, przedramiona zwisające w dół. Użyj chwytu hakowego, z palcami owiniętymi nad kciukami.
2. Zacznij od obracania łokci wokół sztangi, doprowadzając ją do barków. Gdy łokcie idą do przodu, rozluźnij chwyt. Barki powinny być wysunięte do przodu, tworząc półkę dla sztangi, która powinna delikatnie dotykać gardła.
3. Ważne, aby sztanga cały czas pozostawała blisko ciała, ponieważ przy większym obciążeniu każda odległość skutkuje niepożądanym zderzeniem. W miarę płynności ruchu można zwiększać prędkość i obciążenie przed przejściem dalej.', NULL, 'free-exercise-db/Rack_Delivery/0.jpg', 'free_exercise_db'),
  ('rack-pull-with-bands', 'Martwy ciąg ze stojaków z gumami', 'Rack Pull with Bands', 'motor_coach', 'intermediate', array['Trójbój', 'Dolny odcinek pleców'], 'Martwy ciąg częściowy ze sztangą na bolcach stojaka, z dodatkowym oporem gum. Buduje ogromną siłę pleców i chwytu.', '1. Ustaw się w racku ze sztangą na bolcach. Bolce powinny być ustawione na żądanej wysokości: tuż pod kolanami, tuż nad nimi lub w połowie uda. Zamocuj gumy u podstawy racka lub przypnij je hantlami. Drugi koniec zamocuj do sztangi. Może być konieczne skrócenie gum, aby zapewnić napięcie.
2. Ustaw się przy sztardze w poprawnej pozycji martwego ciągu. Stopy powinny być pod biodrami, chwyt na szerokość barków, plecy wygięte, a biodra cofnięte, aby zaangażować dwugłowe uda. Ponieważ ciężar jest zwykle duży, możesz użyć chwytu mieszanego, hakowego albo taśm na nadgarstki, aby pomóc w trzymaniu ciężaru.
3. Ze wzrokiem skierowanym do przodu prostuj biodra i kolana, ciągnąc ciężar w górę i do tyłu aż do pełnego wyprostu. Pamiętaj, aby ściągnąć barki do tyłu przy kończeniu ruchu. Odłóż ciężar na bolce i powtórz.', NULL, 'free-exercise-db/Rack_Pull_with_Bands/0.jpg', 'free_exercise_db'),
  ('rack-pulls', 'Martwy ciąg ze stojaków', 'Rack Pulls', 'motor_coach', 'intermediate', array['Trójbój', 'Dolny odcinek pleców'], 'Martwy ciąg częściowy ze sztangą ustawioną na bolcach stojaka. Pozwala użyć bardzo dużych ciężarów i wzmacnia tył ciała.', '1. Ustaw się w racku ze sztangą na bolcach. Bolce powinny być ustawione na żądanej wysokości: tuż pod kolanami, tuż nad nimi lub w połowie uda. Ustaw się przy sztardze w poprawnej pozycji martwego ciągu. Stopy powinny być pod biodrami, chwyt na szerokość barków, plecy wygięte, a biodra cofnięte, aby zaangażować dwugłowe uda. Ponieważ ciężar jest zwykle duży, możesz użyć chwytu mieszanego, hakowego albo taśm na nadgarstki.
2. Ze wzrokiem skierowanym do przodu prostuj biodra i kolana, ciągnąc ciężar w górę i do tyłu aż do pełnego wyprostu. Pamiętaj, aby ściągnąć barki do tyłu przy kończeniu ruchu.
3. Odłóż ciężar na bolce i powtórz.', NULL, 'free-exercise-db/Rack_Pulls/0.jpg', 'free_exercise_db'),
  ('rear-leg-raises', 'Unoszenie nogi w klęku podpartym', 'Rear Leg Raises', 'motor_coach', 'beginner', array['Rozciąganie', 'Uda'], 'W klęku podpartym unoś nogę do tyłu i w górę. Wzmacnia pośladki i dolny odcinek pleców.', '1. Ustaw się na dłoniach i kolanach na macie gimnastycznej. Głowa powinna patrzeć do przodu, a zgięcie kolan powinno tworzyć kąt 90 stopni między udem a łydką. To będzie pozycja startowa.
2. Wyprostuj jedną nogę w górę i do tyłu. Zarówno kolano, jak i biodro powinny się wyprostować. Powtórz 5–10 razy, a następnie zmień stronę.', NULL, 'free-exercise-db/Rear_Leg_Raises/0.jpg', 'free_exercise_db'),
  ('recumbent-bike', 'Rower poziomy', 'Recumbent Bike', 'motor_coach', 'beginner', array['Cardio', 'Uda'], 'Trening cardio na rowerze poziomym z oparciem. Łagodne dla stawów, pozwala spalać kalorie i monitorować tętno.', '1. Na początek usiądź na rowerze i ustaw siodełko odpowiednio do swojego wzrostu.
2. Wybierz żądaną opcję z menu. Może być konieczne rozpoczęcie pedałowania, aby go włączyć. Możesz użyć trybu ręcznego albo wybrać program. Zazwyczaj można wprowadzić swój wiek i wagę, aby oszacować ilość spalonych kalorii podczas ćwiczenia. Poziom oporu można zmieniać w trakcie treningu. Uchwyty mogą służyć do monitorowania tętna, co pomaga utrzymać odpowiednią intensywność.
3. Rowery poziome oferują wygodę, korzyści sercowo-naczyniowe i mniejsze obciążenie stawów niż inne aktywności. Osoba ważąca około 68 kg spali około 230 kalorii jadąc w umiarkowanym tempie przez 30 minut, w porównaniu do 450 lub więcej kalorii podczas biegu.', NULL, 'free-exercise-db/Recumbent_Bike/0.jpg', 'free_exercise_db'),
  ('return-push-from-stance', 'Odbieranie i odrzut piłki z postawy', 'Return Push from Stance', 'motor_coach', 'beginner', array['Plyometryka', 'Barki'], 'Ćwiczenie z partnerem: przyjęcie piłki lekarskiej i natychmiastowy rzut z powrotem z pozycji sportowej. Poprawia refleks i szybkość reakcji.', '1. Do tego ćwiczenia potrzebujesz partnera.
2. Zacznij w sportowej postawie dwupunktowej lub trzypunktowej.
3. Na sygnał rusz się do pozycji, aby odebrać podanie od partnera.
4. Złap piłkę lekarską oburącz i natychmiast odrzuć ją z powrotem do partnera.
5. Możesz modyfikować to ćwiczenie, biegając po różnych trasach.', NULL, 'free-exercise-db/Return_Push_from_Stance/0.jpg', 'free_exercise_db'),
  ('reverse-band-bench-press', 'Wyciskanie leżąc z gumami (reverse band)', 'Reverse Band Bench Press', 'motor_coach', 'intermediate', array['Trójbój', 'Triceps'], 'Wyciskanie sztangi leżąc z gumami zamocowanymi do góry racka, które odciążają dolną fazę ruchu. Pozwala trenować z ciężarami ponadnormatywnymi.', '1. Ustaw ławkę wewnątrz racka, ze sztangą ustawioną na właściwej wysokości. Zacznij od zakotwiczenia gum na kołkach do gum lub na szczycie racka. Upewnij się, że będziesz stał prawidłowo pod gumami. Drugi koniec zamocuj do sztangi.
2. Połóż się na ławce, schowaj stopy pod siebie i wygnij plecy. Używając sztangi do podtrzymania ciężaru, oderwij barki od ławki i ściągnij je, spinając łopatki. Odepchnij się stopami, dociskając mięśnie czworoboczne do ławki. Utrzymuj tę spiętą pozycję ciała przez cały ruch. Niezależnie od szerokości chwytu, powinien on obejmować pierścień na gryfie.
3. Zejmij sztangę ze stojaka bez wysuwania barków do przodu. Skup się na mocnym zaciśnięciu sztangi i próbie jej rozerwania na boki. Opuszczaj sztangę do dolnej części klatki piersiowej lub górnej części brzucha. Sztanga, nadgarstek i łokieć powinny pozostawać w linii przez cały czas.
4. Zatrzymaj się, gdy sztanga dotknie tułowia, a następnie wypchnij ją w górę z jak największą siłą. Łokcie powinny być blisko tułowia aż do pełnego wyprostu.', NULL, 'free-exercise-db/Reverse_Band_Bench_Press/0.jpg', 'free_exercise_db'),
  ('reverse-band-box-squat', 'Przysiad na skrzyni z gumami (reverse band)', 'Reverse Band Box Squat', 'motor_coach', 'intermediate', array['Trójbój', 'Uda'], 'Przysiad na skrzyni z gumami odciążającymi dolną fazę ruchu. Pozwala pracować z cięższymi ciężarami i doskonali technikę przysiadu.', '1. Zacznij w racku ze skrzynią o odpowiedniej wysokości za tobą. Zamontuj gumy na kołkach lub u szczytu racka, upewniając się, że będą znajdować się dokładnie nad sztangą podczas przysiadu. Drugi koniec zamocuj do sztangi.
2. Zacznij od wejścia pod sztangę i położenia jej na tylnych barkach. Zepnij łopatki i obróć łokcie do przodu, próbując ugiąć sztangę na barkach. Zejmij sztangę ze stojaka, tworząc mocne wygięcie w dole pleców, i cofnij się do pozycji. Ustaw stopy szerzej dla większego akcentu na plecy, pośladki, przywodziciele i dwugłowe uda, albo węziej dla większego rozwoju czworogłowych. Trzymaj głowę skierowaną do przodu.
3. Z plecami, barkami i mięśniami głębokimi w napięciu wypchnij kolana i pośladek na zewnątrz, gdy zaczynasz zejście. Usiądź bioder w tył, aż usiądziesz na skrzyni. Idealnie piszczele powinny być prostopadłe do podłoża. Zatrzymaj się po osiągnięciu skrzyni i rozluźnij zginacze bioder. Nigdy nie odbijaj się od skrzyni.
4. Z ciężarem na piętach, wypychając stopy i kolana na zewnątrz, wybij się w górę ze skrzyni prowadząc ruch głową. Kontynuuj w górę, zachowując spięcie od głowy po stopy. Ostrożnie odstaw sztangę na stojak.', NULL, 'free-exercise-db/Reverse_Band_Box_Squat/0.jpg', 'free_exercise_db'),
  ('reverse-band-deadlift', 'Martwy ciąg z gumami (reverse band)', 'Reverse Band Deadlift', 'motor_coach', 'advanced', array['Trójbój', 'Dolny odcinek pleców'], 'Martwy ciąg z gumami zamocowanymi do góry racka, które zmniejszają ciężar przy podłodze. Pozwala przeciążać górną fazę ruchu.', '1. Ustaw sztangę w racku. Zamocuj gumy na szczycie racka, używając kołków lub samej ramy. Drugi koniec gum zamocuj do sztangi.
2. Podejdź do sztangi tak, aby była wycentrowana nad stopami. Stopy powinny być mniej więcej na szerokość bioder. Zegnij się w biodrze, aby chwycić sztangę na szerokość barków, pozwalając łopatkom wysunąć się do przodu. Zazwyczaj używa się chwytu nachwytu lub chwytu mieszanego przy większych seriach.
3. Ze stopami i chwytem ustawionymi weź głęboki oddech, a następnie opuść biodra i ugnij kolana, aż piszczele dotkną sztangi. Patrz do przodu, trzymaj klatkę piersiową w górze i plecy wygięte, i zacznij odpychać się piętami, prowadząc ciężar w górę.
4. Gdy sztanga minie kolana, mocno ściągnij ją do siebie, spinając łopatki, gdy pchasz biodra do przodu w kierunku sztangi.
5. Odłóż sztangę, zginając się w biodrach i prowadząc ją w dół do podłogi.', NULL, 'free-exercise-db/Reverse_Band_Deadlift/0.jpg', 'free_exercise_db'),
  ('reverse-band-power-squat', 'Przysiad siłowy z gumami (reverse band)', 'Reverse Band Power Squat', 'motor_coach', 'advanced', array['Trójbój', 'Uda'], 'Przysiad siłowy z sztangą nisko na plecach, wspomagany gumami odciążającymi dolną fazę ruchu.', '1. Zacznij w racku z bolcami i sztangą ustawionymi na odpowiedniej wysokości. Po załadowaniu sztangi zamontuj gumy na szczycie racka, używając kołków lub samej ramy. Drugi koniec gum zamocuj do sztangi.
2. Zacznij od wejścia pod sztangę i położenia jej na tylnych barkach. Zepnij łopatki i obróć łokcie do przodu, próbując ugiąć sztangę na barkach. Zejmij sztangę ze stojaka, tworząc mocne wygięcie w dole pleców, i cofnij się do pozycji. Ustaw stopy szeroko dla większego akcentu na plecy, pośladki, przywodziciele i dwugłowe uda.
3. Trzymaj głowę skierowaną do przodu. Z plecami, barkami i mięśniami głębokimi w napięciu wypchnij kolana i pośladek na zewnątrz, gdy zaczynasz zejście. Siadaj bioder w tył jak najwięcej. Idealnie piszczele powinny być prostopadłe do podłoża. Niższa pozycja sztangi wymaga większego wychylenia tułowia, aby utrzymać sztangę nad piętami. Kontynuuj, aż złamiesz równoległość, co oznacza, że fałd biodra znajduje się w linii ze szczytem kolana.
4. Z ciężarem na piętach, wypychając stopy i kolana na zewnątrz, wybieraj się w górę prowadząc ruch głową. Kontynuuj w górę, zachowując spięcie od głowy po stopy, aż wrócisz do pozycji startowej.', NULL, 'free-exercise-db/Reverse_Band_Power_Squat/0.jpg', 'free_exercise_db'),
  ('reverse-band-sumo-deadlift', 'Martwy ciąg sumo z gumami (reverse band)', 'Reverse Band Sumo Deadlift', 'motor_coach', 'advanced', array['Trójbój', 'Dwugłowe uda'], 'Martwy ciąg w stylu sumo z bardzo szeroką postawą i gumami odciążającymi start. Angażuje mocno nogi i pośladki.', '1. Zacznij z obciążoną sztangą na podłodze wewnątrz racka. Zamocuj gumy na szczycie racka, używając kołków lub samej ramy. Drugi koniec zamocuj do sztangi.
2. Podejdź do sztangi tak, aby przecinała środek stóp. Stopy powinny być rozstawione bardzo szeroko, blisko nasadek. Zegnij się w biodrach, aby chwycić sztangę. Ramiona powinny znajdować się bezpośrednio pod barkami, wewnątrz nóg, a chwyt może być nachwytem, chwytem mieszanym lub hakowym. Rozluźnij barki, co w efekcie wydłuża ramiona.
3. Weź oddech, a następnie opuść biodra, patrząc do przodu z klatką piersiową w górze. Odepchnij się od podłogi, rozsuwając stopy na boki, z ciężarem na tylnej części stóp. Prostuj biodra i kolana.
4. Gdy sztanga mija kolana, odchyl się do tyłu i pchnij biodra w kierunku sztangi, spinając łopatki.
5. Odłóż ciężar na podłogę, zginając się w biodrach i kontrolując go w drodze w dół.', NULL, 'free-exercise-db/Reverse_Band_Sumo_Deadlift/0.jpg', 'free_exercise_db'),
  ('reverse-barbell-curl', 'Uginanie ramion sztangą nachwytem', 'Reverse Barbell Curl', 'motor_coach', 'beginner', array['Siłowe', 'Biceps'], 'Uginanie ramion sztangą chwytem nachwytem (dłonie w dół). Mocniej angażuje przedramiona i mięsień ramienno-promieniowy.', '1. Stań wyprostowany z tułowiem w pionie, trzymając sztangę na szerokości barków z łokciami blisko tułowia. Dłonie powinny być zwrócone w dół (chwyt nachwytem). To będzie pozycja startowa.
2. Trzymając górne ramiona nieruchomo, uginaj ciężar, napinając biceps, robiąc wydech. Tylko przedramiona powinny się poruszać. Kontynuuj ruch, aż biceps będzie w pełni napięty, a sztanga na wysokości barków. Przytrzymaj pozycję napiętą przez sekundę, spinając mięsień.
3. Powoli zacznij wracać sztangą do pozycji startowej, robiąc wdech.
4. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Reverse_Barbell_Curl/0.jpg', 'free_exercise_db'),
  ('reverse-barbell-preacher-curls', 'Uginanie ramion sztangą nachwytem na modlitewniku', 'Reverse Barbell Preacher Curls', 'motor_coach', 'intermediate', array['Siłowe', 'Biceps'], 'Uginanie ramion na modlitewniku chwytem nachwytem. Izoluje biceps z akcentem na przedramiona.', '1. Chwyć gryf E-Z na szerokość barków chwytem nachwytem (dłonie w dół).
2. Umieść górną część obu ramion na modlitewniku z ramionami wyprostowanymi. To będzie pozycja startowa.
3. Robiąc wydech, użyj bicepsa, aby ugiąć ciężar w górę, aż biceps będzie w pełni napięty, a sztanga na wysokości barków. Mocno zepnij biceps na sekundę w pozycji napiętej.
4. Robiąc wdech, powoli opuszczaj sztangę, aż ramiona będą wyprostowane, a biceps w pełni rozciągnięty.
5. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Reverse_Barbell_Preacher_Curls/0.jpg', 'free_exercise_db'),
  ('reverse-cable-curl', 'Uginanie ramion nachwytem na wyciągu dolnym', 'Reverse Cable Curl', 'motor_coach', 'beginner', array['Siłowe', 'Biceps'], 'Uginanie ramion drążkiem wyciągu dolnego chwytem nachwytem. Stałe napięcie linki dodatkowo obciąża przedramiona.', '1. Stań wyprostowany z tułowiem w pionie, trzymając drążek przymocowany do wyciągu dolnego chwytem nachwytem (dłonie w dół) na szerokości barków. Upewnij się również, że trzymasz łokcie blisko tułowia. To będzie pozycja startowa.
2. Trzymając górne ramiona nieruchomo, uginaj ciężar, napinając biceps, robiąc wydech. Tylko przedramiona powinny się poruszać. Kontynuuj ruch, aż biceps będzie w pełni napięty, a drążek na wysokości barków. Przytrzymaj pozycję napiętą przez sekundę, spinając mięsień.
3. Powoli zacznij wracać drążek do pozycji startowej, robiąc wdech.
4. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Reverse_Cable_Curl/0.jpg', 'free_exercise_db'),
  ('reverse-crunch', 'Spięty brzuch odwrotny (reverse crunch)', 'Reverse Crunch', 'motor_coach', 'beginner', array['Siłowe', 'Brzuch'], 'Odwrócone spięcie brzucha: unosisz nogi i podwijasz miednicę ku klatce piersiowej. Celuje w dolne partie mięśni brzucha.', '1. Połóż się na podłodze z całkowicie wyprostowanymi nogami i ramionami po bokach tułowia, dłońmi na podłodze. Ramiona powinny pozostać nieruchome przez całe ćwiczenie.
2. Podnieś nogi tak, aby uda były prostopadłe do podłogi, a stopy razem i równolegle do podłogi. To jest pozycja startowa.
3. Robiąc wdech, przyciągaj nogi w kierunku tułowia, podwijając miednicę do tyłu i unosząc biodra nad podłogę. Na końcu tego ruchu kolana będą dotykać klatki piersiowej.
4. Przytrzymaj napięcie przez sekundę i wróć nogami do pozycji startowej, robiąc wydech.
5. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Reverse_Crunch/0.jpg', 'free_exercise_db'),
  ('reverse-flyes', 'Unoszenie hantli w opadzie na ławce skośnej', 'Reverse Flyes', 'motor_coach', 'beginner', array['Siłowe', 'Barki'], 'Unoszenie hantli na boki w opadzie tułowia na ławce skośnej. Izoluje tylny akton barków i górne partie pleców.', '1. Na początek połóż się na ławce skośnej, przyciskając klatkę piersiową i brzuch do skosu. Trzymaj hantle w każdej dłoni, z dłońmi zwróconymi do siebie (chwyt neutralny).
2. Wyciągnij ramiona przed sobą tak, aby były prostopadłe do kąta ławki. Nogi powinny pozostać nieruchome, dociskające podłoże palcami stóp. To jest pozycja startowa.
3. Zachowując lekkie ugięcie łokci, rozprowadzaj hantle na boki i od siebie w łukowym ruchu, robiąc wydech. Wskazówka: spróbuj zepnąć łopatki, aby uzyskać najlepsze rezultaty z tego ćwiczenia.
4. Ramiona powinny być unoszone, aż będą równoległe do podłogi.
5. Poczuj napięcie i powoli opuszczaj hantle z powrotem do pozycji startowej, robiąc wdech.
6. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Reverse_Flyes/0.jpg', 'free_exercise_db'),
  ('reverse-flyes-with-external-rotation', 'Unoszenie hantli w opadzie z rotacją zewnętrzną', 'Reverse Flyes With External Rotation', 'motor_coach', 'intermediate', array['Siłowe', 'Barki'], 'Wariant unoszenia w opadzie z rotacją ramion w trakcie ruchu. Mocniej angażuje tylny akton i rotatory barku.', '1. Na początek połóż się na ławce skośnej ustawionej pod kątem 30 stopni, przyciskając klatkę piersiową i brzuch do skosu.
2. Trzymaj hantle w każdej dłoni, z dłońmi skierowanymi w dół do podłogi. Ramiona powinny być przed tobą, prostopadle do kąta ławki. Wskazówka: łokcie powinny być lekko ugięte. Nogi powinny pozostać nieruchome, dociskające podłoże palcami stóp (pięty nie powinny dotykać podłogi). To jest pozycja startowa.
3. Zachowując lekki kąt w łokciach, rozprowadzaj hantle na boki i od siebie w łukowym ruchu, robiąc wydech.
4. Podczas unoszenia ciężaru nadgarstki powinny wykonać rotację zewnętrzną o 90 stopni, tak aby przejść z chwytu nachwytu (dłonie w dół) do chwytu neutralnego (dłonie zwrócone do siebie). Wskazówka: spróbuj zepnąć łopatki, aby uzyskać najlepsze rezultaty z tego ćwiczenia.
5. Ramiona powinny być unoszone, aż znajdą się na wysokości głowy.
6. Poczuj napięcie i powoli opuszczaj hantle z powrotem do pozycji startowej, robiąc wdech.
7. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Reverse_Flyes_With_External_Rotation/0.jpg', 'free_exercise_db'),
  ('reverse-grip-bent-over-rows', 'Wiosłowanie sztangą w opadzie podchwytem', 'Reverse Grip Bent-Over Rows', 'motor_coach', 'intermediate', array['Siłowe', 'Środek pleców'], 'Wiosłowanie sztangą w opadzie tułowia z chwytem podchwytem (dłonie w górę). Mocniej angażuje biceps i dolne partie najszerszych mięśni pleców.', '1. Stań wyprostowany, trzymając sztangę chwytem podchwytem (dłonie zwrócone do góry).
2. Lekko ugnij kolana i pochyl tułów do przodu, zginając się w pasie, trzymając plecy proste, aż będzie prawie równoległy do podłogi. Wskazówka: pamiętaj o utrzymaniu głowy uniesionej. Sztanga powinna zwisać bezpośrednio przed tobą, z ramionami prostopadłymi do podłogi i tułowia. To jest pozycja startowa.
3. Trzymając tułów nieruchomo, podciągaj sztangę w górę, robiąc wydech, z łokciami blisko ciała i bez żadnej siły przedramienia poza trzymaniem ciężaru. W górnej pozycji napiętej zepnij mięśnie pleców i przytrzymaj sekundę.
4. Powoli opuszczaj ciężar z powrotem do pozycji startowej, robiąc wdech.
5. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Reverse_Grip_Bent-Over_Rows/0.jpg', 'free_exercise_db'),
  ('reverse-grip-triceps-pushdown', 'Prostowanie ramion na wyciąg górny podchwytem', 'Reverse Grip Triceps Pushdown', 'motor_coach', 'beginner', array['Siłowe', 'Triceps'], 'Prostowanie ramion na wyciągu górnym chwytem podchwytem (dłonie w górę). Izoluje triceps z akcentem na przedramiona.', '1. Zacznij od zamontowania drążka (prostego lub E-Z) na wyciągu górnym.
2. Zwrócony twarzą do drążka złap go chwytem podchwytem (dłonie w górę) na szerokość barków. Opuszczaj drążek, używając najszerszych mięśni pleców, aż ramiona będą w pełni wyprostowane wzdłuż ciała. Wskazówka: łokcie powinny być blisko ciała, a stopy rozstawione na szerokość barków. To jest pozycja startowa.
3. Powoli unoś drążek w górę, robiąc wdech, aż znajdzie się na wysokości klatki piersiowej. Tylko przedramiona powinny się poruszać, a łokcie i ramiona powinny pozostać nieruchome przy ciele przez cały czas.
4. Następnie zacznij opuszczać drążek z powrotem do pierwotnej pozycji startowej, robiąc wydech i mocno napinając triceps.
5. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Reverse_Grip_Triceps_Pushdown/0.jpg', 'free_exercise_db'),
  ('reverse-hyperextension', 'Unoszenie nóg w leżeniu na brzuchu (reverse hyperextension)', 'Reverse Hyperextension', 'motor_coach', 'intermediate', array['Siłowe', 'Dwugłowe uda'], 'Unoszenie nóg do tyłu na specjalnej maszynie lub ławce z biodrami zwisającymi. Wzmacnia pośladki i dolne plecy bez obciążania kręgosłupa.', '1. Po załadowaniu odpowiedniego ciężaru umieść stopy między poduszkami. Połóż się na górnej poduszce, pozwalając biodrom zwisać z tyłu, i chwyć uchwyty, aby utrzymać pozycję.
2. Aby rozpocząć ruch, zegnij biodra, przyciągając nogi do przodu.
3. Odwróć ruch, prostując biodra i wyrzucając nogi do tyłu. Bardzo ważne jest, aby nie przeprostować biodra w tym ruchu, zatrzymując się przed pełnym zakresem ruchu.
4. Wróć, ponownie zginając biodro i przyciągając sani maszyny do przodu jak najdalej.
5. Powtórz żądaną liczbę powtórzeń.', NULL, 'free-exercise-db/Reverse_Hyperextension/0.jpg', 'free_exercise_db'),
  ('reverse-machine-flyes', 'Odwodzenie ramion na maszynie (tylny akton)', 'Reverse Machine Flyes', 'motor_coach', 'beginner', array['Siłowe', 'Barki'], 'Rozpiętki ramion na maszynie siedząc, skierowane na tylny akton barków. Prostsza alternatywa dla wersji z hantlami.', '1. Ustaw uchwyty tak, aby były w pełni z tyłu. Wybierz odpowiedni ciężar i ustaw wysokość siedziska tak, aby uchwyty były na wysokości barków. Chwyć uchwyty dłońmi skierowanymi do środka. To będzie pozycja startowa.
2. W ruchu po łuku rozprowadź ręce na boki i do tyłu, napinając tylne aktony barków.
3. Trzymaj ramiona lekko ugięte przez cały ruch, przy czym cały ruch powinien następować w stawie barkowym.
4. Zatrzymaj się na końcu ruchu i powoli wróć ciężarem do pozycji startowej.', NULL, 'free-exercise-db/Reverse_Machine_Flyes/0.jpg', 'free_exercise_db'),
  ('reverse-plate-curls', 'Uginanie ramion z talerzem nachwytem', 'Reverse Plate Curls', 'motor_coach', 'beginner', array['Siłowe', 'Biceps'], 'Uginanie ramion z ciężkim talerzem trzymanym oburącz nachwytem. Wzmacnia biceps i przedramiona.', '1. Zacznij stojąc prosto z talerzem trzymanym oburącz i całkowicie wyprostowanymi ramionami. Użyj chwytu nachwytu (dłonie w dół) i upewnij się, że palce chwytają szorstką stronę talerza, a kciuki gładką stronę. Uwaga: dla najlepszych rezultatów chwyć talerz w pozycjach godziny 11:00 i 1:00.
2. Stopy powinny być rozstawione na szerokość barków, a talerz blisko pachwiny. To jest pozycja startowa.
3. Powoli unoś talerz w górę, trzymając łokcie blisko i górne ramiona nieruchomo, aż biceps i przedramiona się dotkną, robiąc wydech. Talerz powinien być w tym punkcie wyrównany z tułowiem.
4. Poczuj napięcie przez sekundę i zacznij opuszczać ciężar z powrotem do pozycji startowej, robiąc wdech.
5. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Reverse_Plate_Curls/0.jpg', 'free_exercise_db'),
  ('reverse-triceps-bench-press', 'Wyciskanie sztangi leżąc wąskim podchwytem', 'Reverse Triceps Bench Press', 'motor_coach', 'intermediate', array['Siłowe', 'Triceps'], 'Wyciskanie sztangi leżąc wąskim chwytem podchwytem. Mocno angażuje triceps.', '1. Połóż się na płaskiej ławce. Używając wąskiego chwytu podchwytem (około szerokości barków), zejmij sztangę ze stojaka i trzymaj ją prosto nad sobą z ramionami zablokowanymi i wyprostowanymi przed sobą, prostopadle do podłogi. To będzie pozycja startowa.
2. Robiąc wdech, schodź powoli, aż poczujesz sztangę na środku klatki piersiowej. Wskazówka: w przeciwieństwie do zwykłego wyciskania leżąc, trzymaj łokcie blisko tułowia przez cały czas, aby zmaksymalizować udział tricepsa.
3. Po sekundowej pauzie wróć sztangą do pozycji startowej, robiąc wydech i wypychając sztangę mięśniami tricepsa. Zablokuj ramiona w pozycji napiętej, przytrzymaj sekundę, a następnie zacznij znów schodzić powoli. Wskazówka: zejście powinno trwać co najmniej dwa razy dłużej niż wypchnięcie.
4. Powtórz ruch zalecaną liczbę powtórzeń.
5. Gdy skończysz, odstaw sztangę z powrotem na stojak.', NULL, 'free-exercise-db/Reverse_Triceps_Bench_Press/0.jpg', 'free_exercise_db'),
  ('rhomboids-smr', 'Rolowanie mięśni międzyłopatkowych (SMR)', 'Rhomboids-SMR', 'motor_coach', 'intermediate', array['Rozciąganie', 'Środek pleców'], 'Automasaż miękkości górnej części pleców na wałku. Rozluźnia mięsień równoległoboczny i okolice międzyłopatkowe.', '1. Połóż się na podłodze na plecach. Umieść wałek pod górną częścią pleców i skrzyżuj ramiona przed sobą, wysuwając barki do przodu. To będzie pozycja startowa.
2. Unieś biodra nad ziemię, przenosząc ciężar na wałek. Przenoś ciężar na jedną stronę na raz, rolowując środkową i górną część pleców. Zatrzymuj się w punktach napięcia na 10–30 sekund.', NULL, 'free-exercise-db/Rhomboids-SMR/0.jpg', 'free_exercise_db'),
  ('rickshaw-carry', 'Niesienie rickshawa (uchwyt sztywny)', 'Rickshaw Carry', 'motor_coach', 'intermediate', array['Strongman', 'Przedramiona'], 'Niesienie ciężkiej ramy chwytowej (rickshaw) na krótkim dystansie. Doskonałe ćwiczenie na siłę chwytu i całego ciała.', '1. Ustaw ramę w punkcie startowym i załaduj odpowiedni ciężar. Stojąc w środku ramy, zacznij od złapania uchwytów i odpychania się piętami, aby podnieść ramę. Upewnij się, że klatka piersiowa i głowa są w górze, a plecy proste.
2. Natychmiast zacznij iść energicznie, szybkimi, kontrolowanymi krokami. Trzymaj klatkę piersiową w górze, a głowę skierowaną do przodu, i pamiętaj o oddychaniu. Postaw ramę na ziemi, gdy dotrzesz do punktu końcowego.', NULL, 'free-exercise-db/Rickshaw_Carry/0.jpg', 'free_exercise_db'),
  ('rickshaw-deadlift', 'Martwy ciąg w rickshawie', 'Rickshaw Deadlift', 'motor_coach', 'intermediate', array['Strongman', 'Uda'], 'Martwy ciąg wykonywany w ramie chwytowej (rickshaw) z neutralnym chwytem uchwytów. Bezpieczna odmiana na siłę chwytu i pleców.', '1. Załaduj ramę żądanym ciężarem. Ustaw się w środku między uchwytami. Stopy powinny być mniej więcej na szerokość bioder. Zegnij się w biodrach, aby chwycić uchwyty, pozwalając łopatkom wysunąć się do przodu.
2. Ze stopami i chwytem ustawionymi weź głęboki oddech, a następnie opuść biodra i ugnij kolana. Patrz do przodu, trzymaj klatkę piersiową w górze i plecy wygięte, i zacznij odpychać się piętami, prowadząc ciężar w górę. W miarę unoszenia ciężaru spinaj łopatki, pchając biodra do przodu.
3. Opuść ciężar, zginając się w biodrach i prowadząc go do ziemi.', NULL, 'free-exercise-db/Rickshaw_Deadlift/0.jpg', 'free_exercise_db'),
  ('ring-dips', 'Pompki na kółkach gimnastycznych', 'Ring Dips', 'motor_coach', 'intermediate', array['Siłowe', 'Triceps'], 'Pompki w podporze na kółkach gimnastycznych. Niestabilne zawieszenie dodatkowo angażuje mięśnie stabilizujące barki.', '1. Chwyć kółko w każdej dłoni, a następnie wykonaj mały podskok, aby wejść w pozycję startową z ramionami zablokowanymi.
2. Zacznij od ugięcia łokci, opuszczając ciało, aż ramiona przejdą kąt 90 stopni. Unikaj bujania i utrzymuj dobrą postawę przez cały czas opuszczania.
3. Odwróć ruch, prostując łokcie i wypychając się z powrotem do pozycji startowej.
4. Powtórz żądaną liczbę powtórzeń.', NULL, 'free-exercise-db/Ring_Dips/0.jpg', 'free_exercise_db'),
  ('rocket-jump', 'Wyskok w górę (rocket jump)', 'Rocket Jump', 'motor_coach', 'beginner', array['Plyometryka', 'Uda'], 'Pliometryczny wyskok z półprzysiadu z wyciągnięciem ramion nad głowę. Rozwija moc nóg i eksplozywność.', '1. Zacznij w rozluźnionej postawie ze stopami na szerokość barków, trzymając ramiona blisko ciała.
2. Aby zainicjować ruch, zejdź do półprzysiadu i wybij się w górę jak najwyżej.
3. W pełni wyprostuj całe ciało, sięgając nad głowę jak najwyżej. Podczas lądowania amortyzuj uderzenie nogami.', NULL, 'free-exercise-db/Rocket_Jump/0.jpg', 'free_exercise_db'),
  ('rocking-standing-calf-raise', 'Wspięcie na palce stojąc z kołysaniem', 'Rocking Standing Calf Raise', 'motor_coach', 'beginner', array['Siłowe', 'Łydki'], 'Wspięcie na palce ze sztangą na plecach, z naprzemienną pracą łydek i piszczeli. Rozwija łydki w pełnym zakresie ruchu.', '1. To ćwiczenie najlepiej wykonywać w racku ze względów bezpieczeństwa. Na początek ustaw sztangę na stojaku najlepiej dopasowanym do twojego wzrostu. Gdy wybierzesz właściwą wysokość i załadujesz sztangę, wejdź pod nią i połóż ją na tylnych barkach (nieco poniżej karku).
2. Trzymaj sztangę obiema rękami po bokach i zejmij ją ze stojaka, najpierw odpychając się nogami i jednocześnie prostując tułów.
3. Odejdź od stojaka i ustaw nogi w średniej postawie na szerokość barków z palcami lekko skierowanymi na zewnątrz. Trzymaj głowę uniesioną przez cały czas, ponieważ patrzenie w dół zaburza równowagę. Utrzymuj też proste plecy i kolana z lekkim ugięciem; nigdy zablokowane. To będzie pozycja startowa.
4. Unoś pięty, robiąc wydech, prostując staw skokowy jak najwyżej i napinając łydkę. Upewnij się, że kolano pozostaje nieruchome przez cały czas. Nie powinno być żadnego ugięcia (poza lekkim początkowym ugięciem, które utworzyliśmy przy ustawieniu) w żadnym momencie. Przytrzymaj pozycję napiętą przez sekundę, zanim zaczniesz schodzić w dół.
5. Wróć powoli do pozycji startowej, robiąc wdech, opuszczając pięty i zginając staw skokowy, aż łydki zostaną rozciągnięte.
6. Teraz unoś palce stóp, napinając mięśnie piszczeli z przodu łydek, robiąc wydech.
7. Przytrzymaj sekundę i opuść je z powrotem w dół, robiąc wdech.
8. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Rocking_Standing_Calf_Raise/0.jpg', 'free_exercise_db'),
  ('rocky-pull-ups-pulldowns', 'Podciąganie „Rocky” (przód i zza karku)', 'Rocky Pull-Ups/Pulldowns', 'motor_coach', 'intermediate', array['Siłowe', 'Najszersze grzbietu'], 'Podciąganie szerokim nachwytem naprzemiennie do klatki piersiowej i za kark. Wariant podciągania Rocky''ego Balboy.', '1. Złap drążek chwytem nachwytem (dłonie skierowane do przodu) w szerokim rozstawie.
2. Z oboma ramionami wyprostowanymi przed sobą i drążkiem trzymanym w wybranym rozstawie odchyl tułów do tyłu o około 30 stopni, tworząc wygięcie w dolnej części pleców i wypychając klatkę piersiową do przodu. To jest pozycja startowa.
3. Podciągnij tułów w górę, aż drążek dotknie górnej części klatki piersiowej, ściągając barki i ramiona w dół i do tyłu. Wydechaj podczas tej części ruchu. Wskazówka: skoncentruj się na zaciśnięciu mięśni pleców, gdy osiągniesz pełną pozycję napiętą. Górna część tułowia powinna pozostać nieruchoma w przestrzeni, a poruszać się powinny tylko ramiona. Przedramiona nie powinny wykonywać żadnej innej pracy poza trzymaniem drążka.
4. Po sekundzie w pozycji napiętej zacznij wdech i powoli opuszczaj tułów do pozycji startowej, aż ramiona będą w pełni wyprostowane, a najszersze mięśnie pleców w pełni rozciągnięte.
5. Teraz powtórz te same ruchy jak wyżej, ale tym razem tułów pozostanie prosty podczas unoszenia, a drążek dotknie tyłu karku zamiast górnej części klatki piersiowej. Wskazówka: pochyl lekko głowę do przodu, co pomoże ci prawidłowo wykonać tę część ćwiczenia.
6. Gdy opuścisz się z powrotem do pozycji startowej, powtórz ćwiczenie zalecaną liczbę powtórzeń w twoim programie.', NULL, 'free-exercise-db/Rocky_Pull-Ups_Pulldowns/0.jpg', 'free_exercise_db')
on conflict (slug) do nothing;

insert into public.exercises
  (slug, name, name_en, persona_type, level, categories, short_description, detail_full, common_mistakes, photo_path, source)
values
  ('romanian-deadlift', 'Martwy ciąg rumuński', 'Romanian Deadlift', 'motor_coach', 'intermediate', array['Siłowe', 'Dwugłowe uda'], 'Martwy ciąg rumuński z akcentem na dwugłowe uda i pośladki. Opuszczasz sztangę z prostymi plecami, przesuwając biodra w tył.', '1. Połóż sztangę przed sobą na ziemi i złap ją chwytem nachwytem (dłonie w dół) nieco szerszym niż szerokość barków. Wskazówka: w zależności od użytego ciężaru możesz potrzebować owijek na nadgarstki do wykonania ćwiczenia, a także podwyższenia, aby umożliwić lepszy zakres ruchu.
2. Lekko ugnij kolana i trzymaj piszczele pionowo, biodra w tył i plecy proste. To będzie pozycja startowa.
3. Trzymając plecy i ramiona całkowicie proste przez cały czas, użyj bioder, aby podnieść sztangę, robiąc wydech. Wskazówka: ruch nie powinien być szybki, lecz płynny i pod kontrolą.
4. Gdy stoisz całkowicie prosto, opuszczaj sztangę, cofając biodra i tylko lekko uginając kolana, w przeciwieństwie do przysiadu. Wskazówka: weź głęboki oddech na początku ruchu i trzymaj klatkę piersiową w górze. Wstrzymaj oddech podczas opuszczania i wydechaj przy kończeniu ruchu.
5. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Romanian_Deadlift/0.jpg', 'free_exercise_db'),
  ('romanian-deadlift-from-deficit', 'Martwy ciąg rumuński z podwyższenia', 'Romanian Deadlift from Deficit', 'motor_coach', 'intermediate', array['Podnoszenie ciężarów', 'Dwugłowe uda'], 'Martwy ciąg rumuński stojąc na podwyższeniu. Większy zakres ruchu daje mocniejsze rozciągnięcie dwugłowych ud.', '1. Zacznij stojąc, trzymając sztangę przed sobą na długości wyprostowanych ramion. Możesz stanąć na podwyższeniu, aby zwiększyć zakres ruchu.
2. Zacznij od lekkiego ugięcia kolan, a następnie zegnij się w biodrze, cofając pośladek jak najdalej i opuszczając tułów, na ile pozwala gibkość. Plecy powinny pozostawać w absolutnym wyproście przez cały czas, a sztanga powinna pozostawać w kontakcie z nogami. Jeśli zrobisz to prawidłowo, poczujesz silne napięcie w dwugłowych udach.
3. Odwróć ruch, aby wrócić do pozycji startowej.', NULL, 'free-exercise-db/Romanian_Deadlift_from_Deficit/0.jpg', 'free_exercise_db'),
  ('rope-climb', 'Wspinaczka po linie', 'Rope Climb', 'motor_coach', 'intermediate', array['Siłowe', 'Najszersze grzbietu'], 'Wspinanie się po wiszącej linie z zaczepem linę nogami. Wzmacnia plecy, ramiona i chwyt.', '1. Złap linę oburącz nad głową. Pociągnij linę w dół, wykonując mały podskok.
2. Owiń linę wokół jednej nogi, zaciskając ją stopami. Sięgnij rękami jak najwyżej, mocno chwytając linę.
3. Uwolnij linę ze stóp, gdy podciągasz się ramionami, przyciągając kolana w kierunku klatki piersiowej.
4. Zapnij ponownie stopy na linie, a następnie stań się, aby sięgnąć po kolejny wysoki chwyt. Kontynuuj, aż osiągniesz górę liny.
5. Aby zejść, rozluźnij chwyt stóp na linie, zsuwając się ruchem ramię nad ramieniem.', NULL, 'free-exercise-db/Rope_Climb/0.jpg', 'free_exercise_db'),
  ('rope-crunch', 'Spięty brzuch na wyciągu z liną', 'Rope Crunch', 'motor_coach', 'beginner', array['Siłowe', 'Brzuch'], 'Spięty brzuch w klęku z liną wyciągu górnego za głową. Skutecznie angażuje mięśnie brzucha w zwijaniu tułowia.', '1. Uklęknij 30–60 cm przed wyciągiem z przymocowaną liną.
2. Po wybraniu odpowiedniego ciężaru złap linę oburącz nad głową. Twój tułów powinien być wyprostowany w pozycji startowej.
3. Na początek zegnij kręgosłup, próbując przyciągnąć klatkę piersiową do nóg, ciągnąc linę w dół.
4. Zatrzymaj się na dole ruchu, a następnie powoli wróć do pozycji startowej.
5. Można je wykonywać ze skrętem tułowia lub w bok, aby zaangażować mięśnie skośne brzucha.', NULL, 'free-exercise-db/Rope_Crunch/0.jpg', 'free_exercise_db'),
  ('rope-jumping', 'Skakanka', 'Rope Jumping', 'motor_coach', 'intermediate', array['Cardio', 'Uda'], 'Skakanie na skakance. Doskonałe cardio, poprawia koordynację i spala dużo kalorii.', '1. Trzymaj koniec skakanki w każdej dłoni. Umieść skakankę za sobą na ziemi. Unoś ramiona i przerzuć skakankę nad głowę, prowadząc ją w dół przed sobą. Gdy dotknie ziemi, przeskocz nad nią. Znajdź dobre tempo obrotów, które można utrzymać. Można użyć różnych prędkości i technik, aby wprowadzić urozmaicenie.
2. Skakanie na skakance jest ekscytujące, rzuca wyzwanie twojej koordynacji i wymaga dużo energii. Osoba ważąca około 68 kg spali około 350 kalorii skacząc na skakance przez 30 minut, w porównaniu do ponad 450 kalorii podczas biegu.', NULL, 'free-exercise-db/Rope_Jumping/0.jpg', 'free_exercise_db'),
  ('rope-straight-arm-pulldown', 'Prostowanie ramion na wyciąg górnym z liną', 'Rope Straight-Arm Pulldown', 'motor_coach', 'beginner', array['Siłowe', 'Najszersze grzbietu'], 'Ściąganie liny wyciągu górnego prostymi ramionami. Izoluje najszersze mięśnie pleców bez pracy bicepsa.', '1. Zamocuj linę do wyciągu górnego i wybierz ciężar. Stań kilka stóp za wyciągiem w rozkroku z jedną nogą z przodu i złap linę oburącz. Pochyl się do przodu od biodra, trzymając plecy proste, z ramionami wyprostowanymi przed sobą w górze. To będzie pozycja startowa.
2. Trzymając ramiona proste, prostuj bark, aby ściągnąć linę w dół do ud.
3. Zatrzymaj się na dole ruchu, spinając najszersze mięśnie pleców.
4. Wróć do pozycji startowej, nie pozwalając, aby ciężar całkowicie spoczął na stosie.', NULL, 'free-exercise-db/Rope_Straight-Arm_Pulldown/0.jpg', 'free_exercise_db'),
  ('round-the-world-shoulder-stretch', 'Rozciąganie barków kijem „round the world”', 'Round The World Shoulder Stretch', 'motor_coach', 'beginner', array['Rozciąganie', 'Barki'], 'Rozciąganie barków kijem lub bodybarem przenoszonym z przodu ciała nad głowę do tyłu. Poprawia ruchomość stawów barkowych.', '1. Stań prosto z nogami razem, trzymając bodybar lub kij od miotły.
2. Trzymaj kij za biodrami chwytem szerszym niż szerokość barków. Dłonie powinny być skierowane w dół, a kciuki na zewnątrz.
3. Powoli unoś ramiona w górę za głowę. Nie wymuszaj, jeśli staje się trudno unieść dalej.', NULL, 'free-exercise-db/Round_The_World_Shoulder_Stretch/0.jpg', 'free_exercise_db'),
  ('rowing-stationary', 'Wiosłowanie na ergometrze', 'Rowing, Stationary', 'motor_coach', 'intermediate', array['Cardio', 'Uda'], 'Trening na ergometrze wiosłowym. Ćwiczenie cardio angażujące całe ciało — nogi, plecy i ramiona.', '1. Na początek usiądź na ergometrze. Upewnij się, że pięty wygodnie opierają się o podstawę pedałów i że pasy są zapięte. Wybierz program, którego chcesz użyć, jeśli dotyczy. Usiądź prosto i zegnij się w biodrach do przodu.
2. Istnieją trzy fazy ruchu podczas korzystania z ergometru. Pierwsza faza to, gdy jedziesz do przodu. Kolana są ugięte i blisko klatki piersiowej. Górna część ciała jest lekko pochylona do przodu, zachowując dobrą postawę. Następnie odpychaj się od pedałów i prostuj nogi, przyciągając dłonie do górnej części brzucha, spinając barki do tyłu. Aby uniknąć przeciążenia pleców, używaj głównie mięśni nóg i bioder.
3. Faza powrotu polega po prostu na wyprostowaniu ramion, ugięciu kolan i przyciągnięciu ciała do przodu, gdy przechodzisz z powrotem do pierwszej fazy.', NULL, 'free-exercise-db/Rowing_Stationary/0.jpg', 'free_exercise_db'),
  ('runners-stretch', 'Rozciąganie biegacza', 'Runner''s Stretch', 'motor_coach', 'beginner', array['Rozciąganie', 'Dwugłowe uda'], 'Rozciąganie z jedną nogą wysuniętą do przodu, angażujące zginacze bioder i dwugłowe uda. Popularne w rozgrzewkach biegaczy.', '1. Najłatwiej wejść w to rozciąganie, zaczynając na stojąco, cofając jedną nogę i powoli opuszczając tułów do podłogi.
2. Trzymaj piętę przedniej nogi na podłodze (jeśli się unosi, przesuń drugą nogę jeszcze dalej do tyłu).
3. Połóż dłonie po obu stronach przedniej nogi. Aby uzyskać więcej z tego rozciągania, wypchnij pośladek w górę ku sufitowi, a następnie stopniowo opuszczaj go z powrotem w kierunku podłogi. Rozciągniesz zginacz biodra tylnej nogi oraz dwugłowe uda i pośladki przedniej.', NULL, 'free-exercise-db/Runners_Stretch/0.jpg', 'free_exercise_db'),
  ('running-treadmill', 'Bieganie na bieżni', 'Running, Treadmill', 'motor_coach', 'beginner', array['Cardio', 'Uda'], 'Trening biegowy na bieżni mechanicznej. Wygodne cardio z regulacją prędkości i nachylenia.', '1. Na początek wejdź na bieżnię i wybierz żądaną opcję z menu. Większość bieżni ma tryb ręczny albo można wybrać program. Zazwyczaj można wprowadzić swój wiek i wagę, aby oszacować spalone kalorie. Nachylenie można regulować, aby zmienić intensywność treningu.
2. Bieżnie oferują wygodę, korzyści sercowo-naczyniowe i zwykle mniejsze obciążenie stawów niż bieganie na zewnątrz. Osoba ważąca około 68 kg spali ponad 450 kalorii biegając z prędkością około 13 km/h przez 30 minut. Utrzymuj prawidłową postawę podczas biegu i trzymaj się uchwytów tylko w razie potrzeby, na przykład przy zsiadaniu lub sprawdzaniu tętna.', NULL, 'free-exercise-db/Running_Treadmill/0.jpg', 'free_exercise_db'),
  ('russian-twist', 'Skręty tułowia (rosyjskie)', 'Russian Twist', 'motor_coach', 'intermediate', array['Siłowe', 'Brzuch'], 'Skręty tułowia w pozycji V z uniesionymi nogami. Angażują mięśnie skośne brzucha.', '1. Połóż się na podłodze, wsuwając stopy pod coś nieruchomego albo prosząc partnera, aby je przytrzymał. Nogi powinny być ugięte w kolanach.
2. Unoś górną część ciała tak, aby tworzyła wyimaginowany kształt litery V z udami. Ramiona powinny być w pełni wyprostowane przed tobą, prostopadle do tułowia, ze splecionymi dłońmi. To jest pozycja startowa.
3. Skręć tułów w prawą stronę, aż ramiona będą równoległe do podłogi, robiąc wydech.
4. Przytrzymaj napięcie przez sekundę i wróć do pozycji startowej, robiąc wydech. Teraz przejdź na przeciwną stronę, wykonując te same techniki, które zastosowałeś po stronie prawej.
5. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Russian_Twist/0.jpg', 'free_exercise_db'),
  ('sandbag-load', 'Wnoszenie worków z piaskiem na platformę', 'Sandbag Load', 'motor_coach', 'beginner', array['Strongman', 'Uda'], 'Ćwiczenie strongman: podnoszenie worków z piaskiem i rzucanie ich na platformę. Buduje siłę całego ciała i wytrzymałość.', '1. Aby ładować worki z piaskiem lub inne przedmioty, zacznij od ustawienia ich w pewnej odległości od platformy załadunkowej, zazwyczaj 15 metrów.
2. Zacznij od podniesienia worka. Worki z piaskiem są niezwykle nieporęczne, a sposób ich podnoszenia może się różnić w zależności od konkretnego worka. Sięgnij jak najdalej wokół niego, prostując biodra i kolana, aby podnieść go wysoko. Rzucanie na bark zwykle nie jest dozwolone.
3. Przemieszczaj się jak najszybciej do platformy i załaduj ją, prostując biodra, kolana i stawy skokowe, aby podnieść ją jak najwyżej. Połóż worek na platformie, upewniając się, że nie spadnie.
4. Wróć do pozycji startowej po następny worek i powtarzaj, aż konkurencja zostanie zakończona.', NULL, 'free-exercise-db/Sandbag_Load/0.jpg', 'free_exercise_db'),
  ('scapular-pull-up', 'Podciąganie łopatkowe (scapular pull-up)', 'Scapular Pull-Up', 'motor_coach', 'beginner', array['Siłowe', 'Czworoboczne'], 'W zwisie na drążku aktywujesz łopatki, ściągając je w dół bez zginania ramion. Buduje siłę stabilizacji łopatek do podciągania.', '1. Złap drążek do podciągania chwytem nachwytem.
2. Z pozycji zwisu unoś siebie o kilka centymetrów, nie używając ramion. Zrób to, obniżając pas barkowy w odwrotnym ruchu szruga.
3. Zatrzymaj się po zakończeniu ruchu, a następnie powoli wróć do pozycji startowej przed wykonaniem kolejnych powtórzeń.', NULL, 'free-exercise-db/Scapular_Pull-Up/0.jpg', 'free_exercise_db'),
  ('scissor-kick', 'Nożyce w leżeniu na plecach', 'Scissor Kick', 'motor_coach', 'beginner', array['Rozciąganie', 'Brzuch'], 'Naprzemienne unoszenie i opuszczanie nóg w leżeniu na plecach, jak ruch nożyc. Angażuje dolne partie mięśni brzucha.', '1. Na początek połóż się z plecami dociśniętymi do podłogi lub na macie gimnastycznej (opcjonalnie). Ramiona powinny być w pełni wyprostowane po bokach, z dłońmi skierowanymi w dół. Uwaga: ramiona powinny być nieruchome przez cały czas.
2. Z lekkim ugięciem w kolanach unoś nogi tak, aby pięty znajdowały się około 15 cm nad ziemią. To jest pozycja startowa.
3. Teraz unoś lewą nogę do około 45 stopni, podczas gdy prawa noga jest opuszczana, aż pięta znajdzie się około 5–8 cm nad ziemią.
4. Zamieniaj ruchy, unosząc prawą nogę w górę i opuszczając lewą. Pamiętaj o oddychaniu podczas wykonywania tego ćwiczenia.
5. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Scissor_Kick/0.jpg', 'free_exercise_db'),
  ('scissors-jump', 'Wyskok z zamianą nóg (scissors jump)', 'Scissors Jump', 'motor_coach', 'beginner', array['Plyometryka', 'Uda'], 'Eksplozywny wyskok z pozycji wykroku z zamianą nóg w powietrzu. Pliometryczne ćwiczenie na moc nóg.', '1. Przyjmij pozycję wykroku z jedną nogą z przodu ugiętą w kolanie i tylnym kolanem prawie dotykającym ziemi.
2. Upewnij się, że przednie kolano znajduje się nad linią środka stopy. Prostując obie nogi, wyskocz jak najwyżej, wymachując ramionami, aby uzyskać wznoszenie.
3. Podczas wyskoku jak najwyżej zmień pozycję nóg, przenosząc przednią nogę do tyłu, a tylną do przodu.
4. Podczas lądowania amortyzuj uderzenie nogami, przyjmując pozycję wykroku, i powtórz.', NULL, 'free-exercise-db/Scissors_Jump/0.jpg', 'free_exercise_db'),
  ('seated-band-hamstring-curl', 'Uginanie nóg siedząc z gumą', 'Seated Band Hamstring Curl', 'motor_coach', 'beginner', array['Siłowe', 'Dwugłowe uda'], 'Uginanie nóg siedząc na ławce z gumą oporową zapiętą za kostkami. Wzmacnia dwugłowe uda bez maszyny.', '1. Zamocuj gumę blisko ziemi i ustaw ławkę kilka stóp od niej.
2. Usiądź na ławce i zapij gumę za kostkami, zaczynając z nogami wyprostowanymi. To będzie pozycja startowa.
3. Ugnij kolana, przyciągając stopy w kierunku ławki. Może być konieczne lekkie odchylenie się do tyłu, aby stopy nie uderzyły o podłogę.
4. Zatrzymaj się po zakończeniu ruchu, a następnie powoli wróć do pozycji startowej.', NULL, 'free-exercise-db/Seated_Band_Hamstring_Curl/0.jpg', 'free_exercise_db'),
  ('seated-barbell-military-press', 'Wyciskanie sztangi siedząc (wojskowe)', 'Seated Barbell Military Press', 'motor_coach', 'intermediate', array['Siłowe', 'Barki'], 'Wyciskanie sztangi siedząc na ławce z oparciem. Klasyczne ćwiczenie na barki i triceps.', '1. Usiądź na ławce do wyciskania ze sztangą za głową i albo poproś asekuratora, aby podał ci sztangę (lepiej dla stożka rotatorów), albo podnieś ją ostrożnie samodzielnie chwytem nachwytem (dłonie skierowane do przodu). Wskazówka: chwyt powinien być szerszy niż szerokość barków i powinien tworzyć kąt 90 stopni między przedramieniem a ramieniem podczas opuszczania sztangi.
2. Po podniesieniu sztangi z prawidłową szerokością chwytu unoś ją nad głowę, blokując ramiona. Przytrzymaj na wysokości barków, lekko przed głową. To jest pozycja startowa.
3. Opuść sztangę powoli do obojczyka, robiąc wdech.
4. Unoś sztangę z powrotem do pozycji startowej, robiąc wydech.
5. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Seated_Barbell_Military_Press/0.jpg', 'free_exercise_db'),
  ('seated-barbell-twist', 'Skręty tułowia ze sztangą siedząc', 'Seated Barbell Twist', 'motor_coach', 'beginner', array['Siłowe', 'Brzuch'], 'Siedząc na ławce trzymasz sztangę na karku i skręcasz tułów na boki. Angażuje mięśnie skośne brzucha.', '1. Zacznij od usadzenia na końcu płaskiej ławki ze sztangą położoną na udach. Stopy powinny być rozstawione na szerokość barków.
2. Chwyć sztangę dłońmi skierowanymi w dół i upewnij się, że ręce są rozstawione szerzej niż szerokość barków. Zacznij unoś sztangę nad głowę, aż ramiona będą w pełni wyprostowane.
3. Teraz opuść sztangę za głowę, aż spocznie u podstawy karku. To jest pozycja startowa.
4. Trzymając stopy i głowę nieruchomo, przenoś pas z boku na bok tak, aby mięśnie skośne brzucha poczuły napięcie. Poruszaj się na boki tylko tak daleko, jak pozwoli pas. Przeprost lub ruch zbyt daleko może spowodować uraz. Wskazówka: używaj wolnego, kontrolowanego ruchu.
5. Pamiętaj o wydechu podczas skręcania ciała w bok i wdechu przy powrocie do pozycji startowej.
6. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Seated_Barbell_Twist/0.jpg', 'free_exercise_db'),
  ('seated-bent-over-one-arm-dumbbell-triceps-extension', 'Prostowanie ramienia z hantlą w opadzie siedząc (jednorącz)', 'Seated Bent-Over One-Arm Dumbbell Triceps Extension', 'motor_coach', 'beginner', array['Siłowe', 'Triceps'], 'Prostowanie jednego ramienia z hantlą w opadzie tułowia siedząc. Izoluje triceps.', '1. Usiądź na końcu płaskiej ławki z hantlą w jednej ręce, używając chwytu neutralnego (dłonie zwrócone ku tobie).
2. Lekko ugnij kolana i pochyl tułów do przodu, zginając się w pasie, trzymając plecy proste, aż będzie prawie równoległy do podłogi. Upewnij się, że trzymasz głowę uniesioną.
3. Górne ramię z hantlą powinno być blisko tułowia i wyrównane z nim (uniesione do równoległości z podłogą, a przedramiona skierowane w dół, gdy dłonie trzymają ciężar). Wskazówka: powinien istnieć kąt 90 stopni między przedramieniem a ramieniem. To jest pozycja startowa.
4. Trzymając górne ramię nieruchomo, użyj tricepsa, aby podnieść ciężar, robiąc wydech, aż przedramię będzie równoległe do podłogi, a całe ramię wyprostowane. Jak w wielu innych ćwiczeniach na ręce, porusza się tylko przedramię.
5. Po sekundzie napięcia na górze powoli opuszczaj hantlę z powrotem do pozycji startowej, robiąc wdech.
6. Powtórz ruch zalecaną liczbę powtórzeń.
7. Zamień ręce i powtórz ćwiczenie.', NULL, 'free-exercise-db/Seated_Bent-Over_One-Arm_Dumbbell_Triceps_Extension/0.jpg', 'free_exercise_db'),
  ('seated-bent-over-rear-delt-raise', 'Unoszenie hantli w opadzie siedząc (tylny akton)', 'Seated Bent-Over Rear Delt Raise', 'motor_coach', 'intermediate', array['Siłowe', 'Barki'], 'Unoszenie hantli na boki w opadzie tułowia siedząc. Izoluje tylny akton barków.', '1. Połóż parę hantli przed płaską ławką, z dłońmi skierowanymi do przodu.
2. Usiądź na końcu ławki z nogami razem i hantlami za łydkami.
3. Zegnij się w pasie, trzymając plecy proste, aby podnieść hantle. Dłonie powinny być zwrócone do siebie podczas podnoszenia. To będzie pozycja startowa.
4. Trzymając tułów pochylony i nieruchomy, a ramiona lekko ugięte w łokciach, unoś hantle prosto na boki, aż oba ramiona będą równoległe do podłogi. Wydechaj unosząc ciężary. (Uwaga: unikaj bujania tułowiem lub cofania ramion zamiast prowadzenia ich na boki.)
5. Po sekundzie napięcia na górze powoli opuszczaj hantle z powrotem do pozycji startowej.
6. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Seated_Bent-Over_Rear_Delt_Raise/0.jpg', 'free_exercise_db'),
  ('seated-bent-over-two-arm-dumbbell-triceps-extension', 'Prostowanie ramion z hantlami w opadzie siedząc (dwurącz)', 'Seated Bent-Over Two-Arm Dumbbell Triceps Extension', 'motor_coach', 'intermediate', array['Siłowe', 'Triceps'], 'Prostowanie obu ramion z hantlami w opadzie tułowia siedząc. Izoluje oba tricepsy jednocześnie.', '1. Usiądź na końcu płaskiej ławki z hantlą w każdej ręce, używając chwytu neutralnego (dłonie zwrócone ku tobie).
2. Lekko ugnij kolana i pochyl tułów do przodu, zginając się w pasie, trzymając plecy proste, aż będzie prawie równoległy do podłogi. Upewnij się, że trzymasz głowę uniesioną.
3. Górne ramiona z hantlami powinny być blisko tułowia i wyrównane z nim (uniesione do równoległości z podłogą, a przedramiona skierowane w dół, gdy dłonie trzymają ciężary). Wskazówka: powinien istnieć kąt 90 stopni między przedramionami a ramionami. To jest pozycja startowa.
4. Trzymając górne ramiona nieruchomo, użyj tricepsa, aby podnieść ciężar, robiąc wydech, aż przedramiona będą równoległe do podłogi, a całe ramiona wyprostowane. Jak w wielu innych ćwiczeniach na ręce, porusza się tylko przedramię.
5. Po sekundzie napięcia na górze powoli opuszczaj hantle z powrotem do pozycji startowej, robiąc wdech.
6. Powtórz ruch zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Seated_Bent-Over_Two-Arm_Dumbbell_Triceps_Extension/0.jpg', 'free_exercise_db'),
  ('seated-biceps', 'Rozciąganie bicepsów z partnerem (siedząco)', 'Seated Biceps', 'motor_coach', 'advanced', array['Rozciąganie', 'Biceps'], 'Ćwiczenie z partnerem: próbujesz ugiąć ramiona, a partner stawia opór, po czym rozciąga biceps. Metoda rozciągania oporowego.', '1. Usiądź na podłodze z ugiętymi kolanami i partnerem stojącym za tobą. Wyciągnij ramiona prosto za siebie z dłońmi zwróconymi do siebie. Partner będzie trzymał twoje nadgarstki. To będzie pozycja startowa.
2. Spróbuj ugiąć łokcie, podczas gdy partner zapobiega faktycznemu ruchowi.
3. Po 10–20 sekundach rozluźnij ramiona, podczas gdy partner delikatnie pociągnie twoje nadgarstki w górę, rozciągając biceps. Pamiętaj, aby dać partnerowi znać, kiedy rozciąganie jest odpowiednie, aby zapobiec urazowi lub przeprostu.', NULL, 'free-exercise-db/Seated_Biceps/0.jpg', 'free_exercise_db'),
  ('seated-cable-rows', 'Wiosłowanie na wyciągu dolnym siedząc', 'Seated Cable Rows', 'motor_coach', 'beginner', array['Siłowe', 'Środek pleców'], 'Wiosłowanie drążkiem V na wyciągu dolnym siedząc. Buduje grubość mięśni środkowych pleców.', '1. Do tego ćwiczenia potrzebujesz dostępu do maszyny z wyciągiem dolnym z drążkiem V. Uwaga: drążek V umożliwia chwyt neutralny, gdzie dłonie są zwrócone do siebie. Aby przyjąć pozycję startową, najpierw usiądź na maszynie i połóż stopy na przedniej platformie lub poprzeczce, upewniając się, że kolana są lekko ugięte i nie zablokowane.
2. Pochyl się do przodu, zachowując naturalne ułożenie pleców, i złap uchwyty drążka V.
3. Z ramionami wyprostowanymi odchyl się do tyłu, aż tułów utworzy kąt 90 stopni względem nóg. Plecy powinny być lekko wygięte, a klatka piersiowa wypchnięta. Powinieneś czuć przyjemne rozciągnięcie najszerszych mięśni pleców, gdy trzymasz drążek przed sobą. To jest pozycja startowa ćwiczenia.
4. Trzymając tułów nieruchomo, przyciągaj uchwyty w kierunku tułowia, trzymając ramiona blisko niego, aż dotkniesz brzucha. Wydechaj podczas tego ruchu. W tym punkcie powinieneś mocno spinac mięśnie pleców. Przytrzymaj to napięcie przez sekundę i powoli wracaj do pierwotnej pozycji, robiąc wdech.
5. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Seated_Cable_Rows/0.jpg', 'free_exercise_db'),
  ('seated-cable-shoulder-press', 'Wyciskanie na wyciągach siedząc', 'Seated Cable Shoulder Press', 'motor_coach', 'beginner', array['Siłowe', 'Barki'], 'Wyciskanie uchwytów wyciągu nad głowę siedząc. Stałe napięcie linki angażuje barki w całym zakresie ruchu.', '1. Dostosuj ciężar do odpowiedniej wartości i usiądź, chwytając uchwyty. Górne ramiona powinny być około pod kątem 90 stopni do ciała, z głową i klatką piersiową w górze. Łokcie również powinny być ugięte około 90 stopni. To będzie pozycja startowa.
2. Zacznij od prostowania łokci, wypychając uchwyty razem nad głowę.
3. Po pauzie na górze wróć uchwytami do pozycji startowej. Upewnij się, że utrzymujesz napięcie linek.
4. Możesz też wykonać ten ruch z plecami odsuniętymi od oparcia i naprzemiennie rękami.', NULL, 'free-exercise-db/Seated_Cable_Shoulder_Press/0.jpg', 'free_exercise_db'),
  ('seated-calf-raise', 'Wspięcia na palce siedząc', 'Seated Calf Raise', 'motor_coach', 'beginner', array['Siłowe', 'Łydki'], 'Wspięcia na palce na specjalnej maszynie siedząc. Izoluje mięsień płaszczkowaty łydki.', '1. Usiądź na maszynie i połóż palce stóp na dolnej części platformy, z piętami wystającymi za krawędź. Wybierz ułożenie palców według własnego preferencji (na zewnątrz, do środka lub prosto).
2. Umieść dolne części ud pod poduszką dźwigni, którą trzeba będzie wyregulować zgodnie z wysokością twoich ud. Teraz połóż dłonie na górze poduszki dźwigni, aby zapobiec jej zsunięciu do przodu.
3. Unoś dźwignię lekko, pchając pięty w górę, i zwolnij blokadę bezpieczeństwa. To będzie pozycja startowa.
4. Powoli opuszczaj pięty, zginając staw skokowy, aż łydki zostaną w pełni rozciągnięte. Robić wdech podczas tego ruchu.
5. Unoś pięty, prostując staw skokowy jak najwyżej, napinając łydki i robiąc wydech. Przytrzymaj napięcie na górze przez sekundę.
6. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Seated_Calf_Raise/0.jpg', 'free_exercise_db'),
  ('seated-calf-stretch', 'Rozciąganie łydek siedząc', 'Seated Calf Stretch', 'motor_coach', 'beginner', array['Rozciąganie', 'Łydki'], 'Rozciąganie łydki siedząc z pasem lub ręcznikiem założonym na stopę. Proste ćwiczenie zwiększające gibkość kostki.', '1. Usiądź prosto na macie gimnastycznej.
2. Ugnij jedno kolano i połóż tę stopę na podłodze, stabilizując tułów.
3. Wyprostuj drugą nogę i zegnij staw skokowy.
4. Używając gumy, ręcznika lub swojej dłoni, jeśli dosięgniesz, przyciągaj palce stopy w swoją stronę. Przytrzymaj 10–20 sekund, a następnie zmień strony.', NULL, 'free-exercise-db/Seated_Calf_Stretch/0.jpg', 'free_exercise_db'),
  ('seated-close-grip-concentration-barbell-curl', 'Uginanie sztangi siedząc wąskim chwytem (koncentryczne)', 'Seated Close-Grip Concentration Barbell Curl', 'motor_coach', 'intermediate', array['Siłowe', 'Biceps'], 'Uginanie ramion gryfem E-Z wąskim chwytem, z ramionami opartymi o wewnętrzną część ud siedząc. Bardzo izolowana praca bicepsa.', '1. Usiądź na płaskiej ławce ze sztangą lub gryfem E-Z przed sobą między nogami. Nogi powinny być rozstawione z ugiętymi kolanami i stopami na podłodze.
2. Użyj ramion, aby podnieść sztangę i położyć tylne części ramion na wewnętrznych stronach ud (około 9 cm od przodu kolana). Potrzebny jest chwyt podchwytem węższy niż szerokość barków. Wskazówka: ramię powinno być wyprostowane na długości ramienia, a sztanga powinna znajdować się nad podłogą. To będzie pozycja startowa.
3. Trzymając górne ramiona nieruchomo, uginaj ciężar do przodu, napinając biceps, robiąc wydech. Tylko przedramiona powinny się poruszać. Kontynuuj ruch, aż biceps będzie w pełni napięty, a sztanga na wysokości barków. Przytrzymaj pozycję napiętą przez sekundę, spinając biceps.
4. Powoli zacznij wracać sztangą do pozycji startowej, robiąc wdech. Wskazówka: unikaj jakiegokolwiek bujania.
5. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Seated_Close-Grip_Concentration_Barbell_Curl/0.jpg', 'free_exercise_db'),
  ('seated-dumbbell-curl', 'Uginanie ramion z hantlami siedząc', 'Seated Dumbbell Curl', 'motor_coach', 'beginner', array['Siłowe', 'Biceps'], 'Klasyczne uginanie ramion hantlami siedząc, z supinacją nadgarstków w trakcie ruchu. Podstawa treningu bicepsa.', '1. Usiądź na płaskiej ławce z hantlą w każdej dłoni trzymaną na długości wyprostowanych ramion. Łokcie powinny być blisko tułowia.
2. Obróć dłonie tak, aby były zwrócone ku tułowiu. To będzie pozycja startowa.
3. Trzymając górne ramiona nieruchomo, uginaj ciężary i zacznij obracać nadgarstki, gdy hantle miną uda, tak aby dłonie były zwrócone do przodu na końcu ruchu. Upewnij się, że napinasz biceps robiąc wydech i że poruszają się tylko przedramiona. Kontynuuj ruch, aż biceps będzie w pełni napięty, a hantle na wysokości barków. Przytrzymaj pozycję napiętą przez sekundę, spinając biceps.
4. Powoli zacznij wracać hantlami do pozycji startowej, robiąc wdech i obracając nadgarstki z powrotem do chwytu neutralnego.
5. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Seated_Dumbbell_Curl/0.jpg', 'free_exercise_db'),
  ('seated-dumbbell-inner-biceps-curl', 'Uginanie hantli siedząc na zewnętrzną głowę bicepsa', 'Seated Dumbbell Inner Biceps Curl', 'motor_coach', 'beginner', array['Siłowe', 'Biceps'], 'Uginanie ramion hantlami siedząc z dłońmi skręconymi na zewnątrz. Akcentuje zewnętrzną (krótką) głowę bicepsa.', '1. Usiądź na końcu płaskiej ławki z hantlą w każdej dłoni trzymaną na długości wyprostowanych ramion. Łokcie powinny być blisko tułowia.
2. Obróć dłonie tak, aby były zwrócone do środka w pozycji neutralnej. To będzie pozycja startowa.
3. Trzymając górne ramiona nieruchomo, unoś hantle na boki i w górę, obracając dłonie na zewnątrz podczas unoszenia i trzymając przedramiona w linii z zewnętrznymi aktonami barków. Wskazówki:
4. Tylko przedramiona powinny się poruszać. Kontynuuj ruch, aż biceps będzie w pełni napięty, a hantle na wysokości barków. Przytrzymaj pozycję napiętą przez sekundę, spinając biceps.
5. Powoli zacznij wracać hantlami do pozycji startowej, robiąc wdech. Pamiętaj, aby obracać ramiona podczas opuszczania hantli, aby móc przejść z powrotem do chwytu neutralnego.
6. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Seated_Dumbbell_Inner_Biceps_Curl/0.jpg', 'free_exercise_db'),
  ('seated-dumbbell-palms-down-wrist-curl', 'Uginanie nadgarstków hantlami nachwytem siedząc', 'Seated Dumbbell Palms-Down Wrist Curl', 'motor_coach', 'beginner', array['Siłowe', 'Przedramiona'], 'Uginanie nadgarstków hantlami dłońmi w dół, z przedramionami na udach. Wzmacnia zginacze nadgarstka.', '1. Zacznij od położenia dwóch hantli na podłodze przed płaską ławką.
2. Usiądź na krawędzi płaskiej ławki z nogami rozstawionymi mniej więcej na szerokość barków. Upewnij się, że stopy trzymasz na podłodze.
3. Użyj ramion, aby złapać obie hantle i przynieść je w górę, tak aby przedramiona opierały się o uda, z dłońmi skierowanymi w dół. Nadgarstki powinny zwisać za krawędzią ud.
4. Zacznij od uginania nadgarstków w górę, robiąc wydech.
5. Powoli opuszczaj nadgarstki z powrotem do pozycji startowej, robiąc wdech. Upewnij się, że robisz wdech podczas tej części ćwiczenia. Wskazówka: przedramiona powinny pozostać nieruchome, ponieważ nadgarstek to jedyny ruch niezbędny do wykonania tego ćwiczenia.
6. Powtórz zalecaną liczbę powtórzeń.
7. Po zakończeniu po prostu opuść hantle na podłogę.', NULL, 'free-exercise-db/Seated_Dumbbell_Palms-Down_Wrist_Curl/0.jpg', 'free_exercise_db'),
  ('seated-dumbbell-palms-up-wrist-curl', 'Uginanie nadgarstków hantlami podchwytem siedząc', 'Seated Dumbbell Palms-Up Wrist Curl', 'motor_coach', 'beginner', array['Siłowe', 'Przedramiona'], 'Uginanie nadgarstków hantlami dłońmi w górę, z przedramionami na udach. Wzmacnia zginacze nadgarstka.', '1. Zacznij od położenia dwóch hantli na podłodze przed płaską ławką.
2. Usiądź na krawędzi płaskiej ławki z nogami rozstawionymi mniej więcej na szerokość barków. Upewnij się, że stopy trzymasz na podłodze.
3. Użyj ramion, aby złapać obie hantle i przynieść je w górę, tak aby przedramiona opierały się o uda, z dłońmi skierowanymi w górę. Nadgarstki powinny zwisać za krawędzią ud.
4. Zacznij od uginania nadgarstków w górę, robiąc wydech.
5. Powoli opuszczaj nadgarstki z powrotem do pozycji startowej, robiąc wdech. Upewnij się, że robisz wdech podczas tej części ćwiczenia. Wskazówka: przedramiona powinny pozostać nieruchome, ponieważ nadgarstek to jedyny ruch niezbędny do wykonania tego ćwiczenia.
6. Powtórz zalecaną liczbę powtórzeń.
7. Po zakończeniu po prostu opuść hantle na podłogę.', NULL, 'free-exercise-db/Seated_Dumbbell_Palms-Up_Wrist_Curl/0.jpg', 'free_exercise_db'),
  ('seated-dumbbell-press', 'Wyciskanie hantli siedząc', 'Seated Dumbbell Press', 'motor_coach', 'beginner', array['Siłowe', 'Barki'], 'Wyciskanie hantli nad głowę siedząc na ławce z oparciem. Podstawowe ćwiczenie na barki.', '1. Weź parę hantli i usiądź na ławce do wyciskania lub uniwersalnej ławce z oparciem, kładąc hantle pionowo na udach.
2. Podrzuć hantle na barki jedną po drugiej, używając ud, aby wynieść je na wysokość barków po obu stronach.
3. Obróć nadgarstki tak, aby dłonie były zwrócone do przodu. To jest pozycja startowa.
4. Robiąc wydech, wypychaj hantle w górę, aż dotkną się na szczycie.
5. Po sekundowej pauzie powoli schodź z powrotem do pozycji startowej, robiąc wdech.
6. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Seated_Dumbbell_Press/0.jpg', 'free_exercise_db'),
  ('seated-flat-bench-leg-pull-in', 'Przyciąganie kolan do klatki piersiowej siedząc na ławce', 'Seated Flat Bench Leg Pull-In', 'motor_coach', 'beginner', array['Siłowe', 'Brzuch'], 'Siedząc na krawędzi ławki przyciągasz kolana do klatki piersiowej. Ćwiczenie na dolne partie mięśni brzucha.', '1. Usiądź na ławce z nogami wyciągniętymi przed sobą nieco poniżej poziomu i ramionami trzymającymi boki ławki. Twój tułów powinien być odchylony do tyłu około pod kątem 45 stopni od ławki. To będzie pozycja startowa.
2. Przyciągaj kolana w swoim kierunku, jednocześnie zbliżając tułów do nich. Wydechaj podczas tego ruchu.
3. Po sekundowej pauzie wróć do pozycji startowej, robiąc wdech.
4. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Seated_Flat_Bench_Leg_Pull-In/0.jpg', 'free_exercise_db'),
  ('seated-floor-hamstring-stretch', 'Rozciąganie dwugłowych uda siedząc na podłodze', 'Seated Floor Hamstring Stretch', 'motor_coach', 'beginner', array['Rozciąganie', 'Dwugłowe uda'], 'Siedząc na macie sięgasz do stopy wyprostowanej nogi, rozciągając tył uda.', '1. Usiądź na macie z prawą nogą wyprostowaną przed sobą, a lewą nogą ugiętą ze stopą opartą o wewnętrzną część prawego uda.
2. Pochyl się do przodu od bioder i sięgaj w kierunku kostki, aż poczujesz rozciąganie w tylnych mięśniach uda. Przytrzymaj 15 sekund, a następnie powtórz na drugą stronę.', NULL, 'free-exercise-db/Seated_Floor_Hamstring_Stretch/0.jpg', 'free_exercise_db'),
  ('seated-front-deltoid', 'Rozciąganie przednich aktonów z partnerem', 'Seated Front Deltoid', 'motor_coach', 'advanced', array['Rozciąganie', 'Barki'], 'Ćwiczenie z partnerem: próbujesz ruszyć ramiona do przodu, a partner stawia delikatny opór, potem pogłębia rozciąganie barków i klatki piersiowej.', '1. Usiądź prosto na podłodze z ugiętymi nogami i partnerem stojącym za tobą. Wyciągnij ramiona prosto na boki, z dłońmi skierowanymi do ziemi. Spróbuj przesunąć je jak najdalej za siebie, podczas gdy asystent trzyma twoje nadgarstki. To będzie pozycja startowa.
2. Trzymając łokcie proste, spróbuj przesunąć ramiona do przodu, podczas gdy partner delikatnie cię powstrzymuje, zapobiegając faktycznemu ruchowi przez 10–20 sekund.
3. Teraz rozluźnij mięśnie i pozwól partnerowi delikatnie zwiększyć rozciąganie barków i klatki piersiowej. Przytrzymaj 10–20 sekund.', NULL, 'free-exercise-db/Seated_Front_Deltoid/0.jpg', 'free_exercise_db'),
  ('seated-glute', 'Rozciąganie pośladków z partnerem (siedząco)', 'Seated Glute', 'motor_coach', 'advanced', array['Rozciąganie', 'Pośladki'], 'Ćwiczenie z partnerem: siedzisz z kostką założoną na przeciwległe kolano, partner pomaga pogłębić rozciąganie pośladka.', '1. W pozycji siedzącej z ugiętymi kolanami załóż jedną kostkę na przeciwległe kolano. Partner stanie za tobą. Teraz pochyl się do przodu, podczas gdy partner podeprze twoje barki dłońmi. To będzie pozycja startowa.
2. Spróbuj wypchnąć tułów do tyłu przez 10–20 sekund, podczas gdy partner zapobiega faktycznemu ruchowi tułowia.
3. Teraz rozluźnij mięśnie, podczas gdy partner zwiększa rozciąganie, delikatnie pchając twój tułów do przodu przez 10–20 sekund.', NULL, 'free-exercise-db/Seated_Glute/0.jpg', 'free_exercise_db'),
  ('seated-good-mornings', 'Good mornings siedząc', 'Seated Good Mornings', 'motor_coach', 'intermediate', array['Trójbój', 'Dolny odcinek pleców'], 'Skłony tułowia do przodu ze sztangą na plecach w pozycji siedzącej. Mocno angażują dolne plecy i dwugłowe uda.', '1. Ustaw skrzynię w racku. Bolce powinny być ustawione na odpowiedniej wysokości. Zacznij od wejścia pod sztangę i położenia jej na tylnych barkach, nie na czworobocznych. Zepnij łopatki i obróć łokcie do przodu, próbując ugiąć sztangę na barkach.
2. Zejmij sztangę ze stojaka, tworząc mocne wygięcie w dole pleców. Trzymaj głowę skierowaną do przodu. Z plecami, barkami i mięśniami głębokimi w napięciu wypchnij kolana i pośladek na zewnątrz i zacznij zejście. Usiadź bioder w tył, aż siądziesz na skrzyni. To będzie pozycja startowa.
3. Trzymając sztangę mocno, zegnij się do przodu w biodrach jak najdalej. Jeśli ustawisz bolce na wysokości równoległości, masz nie tylko zabezpieczenie w razie porażki, ale też punkt, kiedy się zatrzymać.
4. Zatrzymaj się tuż nad bolcami i odwróć ruch, aż tułów będzie wyprostowany.', NULL, 'free-exercise-db/Seated_Good_Mornings/0.jpg', 'free_exercise_db'),
  ('seated-hamstring', 'Rozciąganie dwugłowych uda z partnerem (siedząco)', 'Seated Hamstring', 'motor_coach', 'advanced', array['Rozciąganie', 'Dwugłowe uda'], 'Ćwiczenie z partnerem: próbujesz unieść tułów, a partner stawia delikatny opór, potem pogłębia rozciąganie tyłu ud.', '1. W pozycji siedzącej z wyprostowanymi nogami poproś partnera, aby stanął za tobą. Teraz pochyl się do przodu, podczas gdy partner podeprze twoje barki dłońmi. To będzie pozycja startowa.
2. Spróbuj wypchnąć tułów do tyłu przez 10–20 sekund, podczas gdy partner zapobiega faktycznemu ruchowi tułowia.
3. Teraz rozluźnij mięśnie, podczas gdy partner zwiększa rozciąganie, delikatnie pchając twój tułów do przodu przez 10–20 sekund.', NULL, 'free-exercise-db/Seated_Hamstring/0.jpg', 'free_exercise_db'),
  ('seated-hamstring-and-calf-stretch', 'Rozciąganie dwugłowych uda i łydek siedząc', 'Seated Hamstring and Calf Stretch', 'motor_coach', 'intermediate', array['Rozciąganie', 'Dwugłowe uda'], 'Siedząc z prostymi nogami przyciągasz pasem palce stopy do siebie. Rozciąga tył uda i łydkę.', '1. Załóż pas, linę lub gumę na jedną stopę. Usiądź z obiema nogami wyprostowanymi. To będzie pozycja startowa.
2. Lekko pochylając się do przodu, ciągnij za pas, aby odchylić palce stopy w swoją stronę. Przytrzymaj tę pozycję 10–20 sekund, a następnie powtórz na drugiej nodze.', NULL, 'free-exercise-db/Seated_Hamstring_and_Calf_Stretch/0.jpg', 'free_exercise_db'),
  ('seated-head-harness-neck-resistance', 'Wzmacnianie karku siedząc z uprzężą na głowie', 'Seated Head Harness Neck Resistance', 'motor_coach', 'intermediate', array['Siłowe', 'Kark'], 'Trening karku siedząc ze specjalną uprzężą z obciążeniem na głowie. Wzmacnia mięśnie szyi.', '1. Połóż pasek na podłodze na końcu płaskiej ławki. Po wybraniu obciążeń usiądź na końcu płaskiej ławki ze stopami rozstawionymi szerzej niż szerokość barków. Palce stóp powinny być skierowane na zewnątrz.
2. Powoli przechyl tułów do przodu, aż będzie prawie równoległy do podłogi. Oburącz bezpiecznie umieść uprzęż na swojej głowie. Wskazówka: upewnij się, że ciężary nadal leżą na podłodze, aby zapobiec przeciążeniu karku. Teraz złap ciężar oburącz, unosząc tułów do tyłu, aż będzie prawie prostopadły do podłogi. Uwaga: głowa i tułów muszą być lekko pochylone do przodu, aby wykonać to ćwiczenie.
3. Teraz połóż obie dłonie na kolanach. To jest pozycja startowa.
4. Powoli opuszczaj głowę w dół, aż broda dotknie górnej części klatki piersiowej, robiąc wdech.
5. Robiąc wydech, wróć głową do pozycji startowej.
6. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Seated_Head_Harness_Neck_Resistance/0.jpg', 'free_exercise_db'),
  ('seated-leg-curl', 'Uginanie nóg siedząc na maszynie', 'Seated Leg Curl', 'motor_coach', 'beginner', array['Siłowe', 'Dwugłowe uda'], 'Uginanie nóg na maszynie siedzącej, z poduszką na łydkach. Główna izolacja dwugłowych uda.', '1. Dostosuj dźwignię maszyny do swojego wzrostu i usiądź na maszynie z plecami opartymi o poduszkę.
2. Połóż tył dolnej części nogi na wyściełanej dźwigni (kilka centymetrów pod łydką) i zabezpiecz poduszkę udową na udach tuż nad kolanami. Następnie chwyć boczne uchwyty maszyny, trzymając palce stóp skierowane prosto (możesz też użyć dowolnej z dwóch innych pozycji) i upewnij się, że nogi są całkowicie proste przed tobą. To będzie pozycja startowa.
3. Robiąc wydech, pociągnij dźwignię maszyny jak najdalej w kierunku tyłu ud, uginając kolana. Trzymaj tułów nieruchomo przez cały czas. Przytrzymaj pozycję napiętą przez sekundę.
4. Powoli wracaj do pozycji startowej, robiąc wdech.
5. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Seated_Leg_Curl/0.jpg', 'free_exercise_db'),
  ('seated-leg-tucks', 'Podciąganie kolan siedząc (leg tucks)', 'Seated Leg Tucks', 'motor_coach', 'beginner', array['Siłowe', 'Brzuch'], 'Siedząc na krawędzi ławki przyciągasz kolana do klatki piersiowej. Angażuje dolne partie mięśni brzucha.', '1. Usiądź na ławce z nogami wyciągniętymi przed sobą nieco poniżej poziomu i ramionami trzymającymi boki ławki. Twój tułów powinien być odchylony do tyłu około pod kątem 45 stopni od ławki. To będzie pozycja startowa.
2. Przyciągaj kolana w swoim kierunku, jednocześnie zbliżając tułów do nich. Wydechaj podczas tego ruchu.
3. Po sekundowej pauzie wróć do pozycji startowej, robiąc wdech.
4. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Seated_Leg_Tucks/0.jpg', 'free_exercise_db'),
  ('seated-one-arm-cable-pulley-rows', 'Wiosłowanie na wyciągu dolnym jednorącz siedząc', 'Seated One-arm Cable Pulley Rows', 'motor_coach', 'intermediate', array['Siłowe', 'Środek pleców'], 'Wiosłowanie jednym ramieniem na wyciągu dolnym siedząc, z rotacją nadgarstka przy ściąganiu. Buduje siłę i masę pleców asymetrycznie.', '1. Aby przyjąć pozycję startową, najpierw usiądź na maszynie i połóż stopy na przedniej platformie lub poprzeczce, upewniając się, że kolana są lekko ugięte i nie zablokowane.
2. Pochyl się do przodu, zachowując naturalne ułożenie pleców, i złap pojedynczy uchwyt lewym ramieniem chwytem nachwytem (dłoń w dół).
3. Z ramieniem wyprostowanym odchyl się do tyłu, aż tułów utworzy kąt 90 stopni względem nóg. Plecy powinny być lekko wygięte, a klatka piersiowa wypchnięta. Powinieneś czuć przyjemne rozciągnięcie najszerszego mięśnia pleców, gdy trzymasz drążek przed sobą. Prawe ramię może pozostać przy talii. To jest pozycja startowa ćwiczenia.
4. Trzymając tułów nieruchomo, przyciągaj uchwyt w kierunku tułowia, trzymając ramię blisko niego, obracając nadgarstek tak, aby gdy dłoń znajdzie się przy brzuchu, była w pozycji neutralnej (dłoń zwrócona ku tułowiu). Wydechaj podczas tego ruchu. W tym punkcie powineneś mocno spinac mięśnie pleców.
5. Przytrzymaj to napięcie przez sekundę i powoli wracaj do pierwotnej pozycji, robiąc wdech. Wskazówka: pamiętaj o obróceniu nadgarstka podczas powrotu do pozycji startowej, tak aby dłoń znów była skierowana w dół.
6. Powtórz zalecaną liczbę powtórzeń, a następnie wykonaj ten sam ruch prawą ręką.', NULL, 'free-exercise-db/Seated_One-arm_Cable_Pulley_Rows/0.jpg', 'free_exercise_db'),
  ('seated-one-arm-dumbbell-palms-down-wrist-curl', 'Uginanie nadgarstków jednorącz hantlą nachwytem siedząc', 'Seated One-Arm Dumbbell Palms-Down Wrist Curl', 'motor_coach', 'intermediate', array['Siłowe', 'Przedramiona'], 'Uginanie nadgarstka jedną ręką hantlą dłonią w dół, z przedramieniem na udzie. Wzmacnia zginacze nadgarstka osobno dla każdej strony.', '1. Usiądź na płaskiej ławce z hantlą w prawej dłoni.
2. Postaw stopy płasko na podłodze, w rozstawie nieco szerszym niż szerokość barków.
3. Pochyl się i połóż prawe przedramię na górnej części prawego uda z dłonią skierowaną w dół. Wskazówka: upewnij się, że tył nadgarstka leży na szczycie kolana. To będzie pozycja startowa.
4. Opuszczaj hantlę jak najniżej, zachowując mocny chwyt hantli. Robić wdech podczas tego ruchu.
5. Teraz uginaj hantlę jak najwyżej, napinając przedramiona i robiąc wydech. Przytrzymaj napięcie przez sekundę, zanim opuścisz ponownie. Wskazówka: jedyny ruch powinien następować w nadgarstku.
6. Wykonaj zalecaną liczbę powtórzeń, zamień ręce i powtórz ruch.', NULL, 'free-exercise-db/Seated_One-Arm_Dumbbell_Palms-Down_Wrist_Curl/0.jpg', 'free_exercise_db'),
  ('seated-one-arm-dumbbell-palms-up-wrist-curl', 'Uginanie nadgarstków jednorącz hantlą podchwytem siedząc', 'Seated One-Arm Dumbbell Palms-Up Wrist Curl', 'motor_coach', 'beginner', array['Siłowe', 'Przedramiona'], 'Uginanie nadgarstka jedną ręką hantlą dłonią w górę, z przedramieniem na udzie. Wzmacnia zginacze nadgarstka osobno dla każdej strony.', '1. Usiądź na płaskiej ławce z hantlą w prawej dłoni.
2. Postaw stopy płasko na podłodze, w rozstawie nieco szerszym niż szerokość barków.
3. Pochyl się i połóż prawe przedramię na górnej części prawego uda z dłonią skierowaną w górę. Wskazówka: upewnij się, że przód nadgarstka leży na szczycie kolana. To będzie pozycja startowa.
4. Opuszczaj hantlę jak najniżej, zachowując mocny chwyt hantli. Robić wdech podczas tego ruchu.
5. Teraz uginaj hantlę jak najwyżej, napinając przedramiona i robiąc wydech. Przytrzymaj napięcie przez sekundę, zanim opuścisz ponownie. Wskazówka: jedyny ruch powinien następować w nadgarstku.
6. Wykonaj zalecaną liczbę powtórzeń, zamień ręce i powtórz ruch.', NULL, 'free-exercise-db/Seated_One-Arm_Dumbbell_Palms-Up_Wrist_Curl/0.jpg', 'free_exercise_db'),
  ('seated-overhead-stretch', 'Rozciąganie tułowia w bok siedząc', 'Seated Overhead Stretch', 'motor_coach', 'beginner', array['Rozciąganie', 'Brzuch'], 'Siedząc skrzyżuj stopy i rozciągaj boki tułowia unoszeniem łokcia ku sufitowi.', '1. Usiadź prosto na macie gimnastycznej.
2. Dotykaj się podeszwami stóp, ze stopami 15–20 cm przed biodrami.
3. Połóż jedną dłoń na podłodze obok siebie, a drugą za głową.
4. Unoś łokieć ku sufitowi, pochylając tułów na przeciwną stronę. Przytrzymaj 10–20 sekund, a następnie zmień strony.', NULL, 'free-exercise-db/Seated_Overhead_Stretch/0.jpg', 'free_exercise_db'),
  ('seated-palm-up-barbell-wrist-curl', 'Uginanie nadgarstków sztangą podchwytem siedząc', 'Seated Palm-Up Barbell Wrist Curl', 'motor_coach', 'beginner', array['Siłowe', 'Przedramiona'], 'Uginanie nadgarstków sztangą dłońmi w górę, z przedramionami na udach. Wzmacnia zginacze nadgarstka.', '1. Trzymaj sztangę oburącz z dłońmi skierowanymi w górę; ręce rozstawione około na szerokość barków.
2. Postaw stopy płasko na podłodze, w rozstawie nieco szerszym niż szerokość barków.
3. Pochyl się i połóż przedramiona na górnych częściach ud z dłońmi w górę. Wskazówka: upewnij się, że przody nadgarstków leżą na szczycie kolan. To będzie pozycja startowa.
4. Opuszczaj drążek jak najniżej, robiąc wdech i zachowując mocny chwyt.
5. Teraz uginaj drążek jak najwyżej, napinając przedramiona i robiąc wydech. Przytrzymaj napięcie na górze przez sekundę. Wskazówka: powinien poruszać się tylko nadgarstek.', NULL, 'free-exercise-db/Seated_Palm-Up_Barbell_Wrist_Curl/0.jpg', 'free_exercise_db'),
  ('seated-palms-down-barbell-wrist-curl', 'Uginanie nadgarstków sztangą nachwytem siedząc', 'Seated Palms-Down Barbell Wrist Curl', 'motor_coach', 'beginner', array['Siłowe', 'Przedramiona'], 'Uginanie nadgarstków sztangą dłońmi w dół, z przedramionami na udach. Wzmacnia zginacze nadgarstka.', '1. Trzymaj sztangę oburącz z dłońmi skierowanymi w dół; ręce rozstawione około na szerokość barków.
2. Postaw stopy płasko na podłodze, w rozstawie nieco szerszym niż szerokość barków.
3. Pochyl się i połóż przedramiona na górnych częściach ud z dłońmi w dół. Wskazówka: upewnij się, że tyły nadgarstków leżą na szczycie kolan. To będzie pozycja startowa.
4. Opuszczaj drążek jak najniżej, robiąc wdech i zachowując mocny chwyt.
5. Teraz uginaj drążek jak najwyżej, napinając przedramiona i robiąc wydech. Przytrzymaj napięcie na górze przez sekundę. Wskazówka: powinien poruszać się tylko nadgarstek.', NULL, 'free-exercise-db/Seated_Palms-Down_Barbell_Wrist_Curl/0.jpg', 'free_exercise_db'),
  ('seated-side-lateral-raise', 'Unoszenie hantli bokiem siedząc', 'Seated Side Lateral Raise', 'motor_coach', 'beginner', array['Siłowe', 'Barki'], 'Unoszenie hantli bokiem do wysokości barków w pozycji siedzącej. Klasyczne ćwiczenie na boczne aktony barków.', '1. Weź parę hantli i usiądź na końcu płaskiej ławki ze stopami mocno opartymi o podłogę. Trzymaj hantle z dłońmi skierowanymi do środka i ramionami prostymi wzdłuż ciała. To będzie pozycja startowa.
2. Utrzymując tułów nieruchomo (bez bujania), unoś hantle na boki z lekkim ugięciem łokci i dłońmi lekko przechyloną do przodu, jakbyś przelewał wodę do szklanki. Kontynuuj w górę, aż ramiona będą równoległe do podłogi. Wydechaj wykonując ten ruch i zatrzymaj się na sekundę na górze.
3. Opuszczaj hantle powoli z powrotem do pozycji startowej, robiąc wdech.
4. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Seated_Side_Lateral_Raise/0.jpg', 'free_exercise_db'),
  ('seated-triceps-press', 'Prostowanie ramion hantlą nad głową siedząc', 'Seated Triceps Press', 'motor_coach', 'beginner', array['Siłowe', 'Triceps'], 'Prostowanie ramion z jedną hantlą trzymaną oburącz nad głową siedząc. Izoluje triceps.', '1. Usiądź na ławce z oparciem i chwyć hantlę oburącz, trzymając ją nad głową na długości wyprostowanych ramion. Wskazówka: lepiej jest, aby ktoś podał ci hantlę, zwłaszcza jeśli jest bardzo ciężka. Ciężar powinien spoczywać na dłoniach z kciukami owiniętymi wokół niego. Dłonie powinny być skierowane do środka. To będzie pozycja startowa.
2. Trzymając górne ramiona blisko głowy (łokcie blisko ciała) i prostopadle do podłogi, opuszczaj ciężar w półkolistym ruchu za głowę, aż przedramiona dotkną bicepsów. Wskazówka: górne ramiona powinny pozostać nieruchome, a poruszać się powinny tylko przedramiona. Robić wdech podczas tego kroku.
3. Wróć do pozycji startowej, używając tricepsa do podniesienia hantli. Wydechaj podczas tego kroku.
4. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Seated_Triceps_Press/0.jpg', 'free_exercise_db'),
  ('seated-two-arm-palms-up-low-pulley-wrist-curl', 'Uginanie nadgarstków oburącz na wyciągu dolnym podchwytem', 'Seated Two-Arm Palms-Up Low-Pulley Wrist Curl', 'motor_coach', 'beginner', array['Siłowe', 'Przedramiona'], 'Uginanie nadgarstków drążkiem wyciągu dolnego, siedząc z przedramionami na udach. Wzmacnia zginacze nadgarstka.', '1. Ustaw ławkę przed maszyną z wyciągiem dolnym, która ma drążek lub gryf curl jako uchwyt.
2. Odsuń ławkę wystarczająco daleko, aby gdy przynosisz uchwyt na górę ud, napięcie było tworzone na linie przez unoszący się stos ciężarów.
3. Teraz chwyć uchwyt oburącz, dłońmi w górę, chwytem na szerokość barków.
4. Cofnij się i usiądź na ławce ze stopami około na szerokość barków, mocno na podłodze.
5. Pochyl się i połóż przedramiona na udach z tylnymi częściami nadgarstków ponad kolanami. To będzie pozycja startowa.
6. Opuszczaj drążek jak najniżej, robiąc wdech i zachowując mocny chwyt.
7. Teraz uginaj drążek jak najwyżej, napinając przedramiona. Wskazówka: powinien poruszać się tylko nadgarstek; nie przedramiona.
8. Po sekundzie napięcia na górze wróć do pozycji startowej, robiąc wdech.
9. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Seated_Two-Arm_Palms-Up_Low-Pulley_Wrist_Curl/0.jpg', 'free_exercise_db'),
  ('see-saw-press-alternating-side-press', 'Wyciskanie naprzemienne z wychyleniem w bok (see-saw press)', 'See-Saw Press (Alternating Side Press)', 'motor_coach', 'intermediate', array['Siłowe', 'Barki'], 'Naprzemienne wyciskanie hantli nad głowę z jednoczesnym wychyleniem tułowia w przeciwną stronę. Łączy pracę barków z mięśniami głębokimi.', '1. Złap hantlę w każdą dłoń i stań wyprostowany.
2. Podrzuć (podnieś) hantle do poziomu klatki piersiowej/barków, a następnie obróć nadgarstki tak, aby dłonie były zwrócone ku tobie, jakbyś przygotowywał się do wykonania Arnold Press. To będzie pozycja startowa.
3. Teraz zacznij prostować lewe ramię nad głowę, obracając nadgarstek tak, aby dłoń była skierowana do przodu w miarę unoszenia. Twoje łokcie również powinny wychodzić na boki podczas unoszenia ciężaru. Jednocześnie będziesz się również zaginać od biodra w przeciwną stronę. Wskazówka: jeśli wykonujesz ćwiczenie prawidłowo, powinno wyglądać tak, jakbyś próbował sięgnąć po coś nad głową po prawej stronie ciała, ale lewym ramieniem. Wydechaj podczas wykonywania tego ruchu.
4. Gdy osiągniesz najwyższą pozycję, weź wdech. Następnie, z ciężarem w pełni wyprostowanym nad głową i tobą zagiętym w prawą stronę, rozpocznij ruch w lewą stronę.
5. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/See-Saw_Press_Alternating_Side_Press/0.jpg', 'free_exercise_db'),
  ('shotgun-row', 'Wiosłowanie jednorącz z rotacją (shotgun row)', 'Shotgun Row', 'motor_coach', 'beginner', array['Siłowe', 'Najszersze grzbietu'], 'Wiosłowanie jednym ramieniem na wyciągu dolnym z rotacją nadgarstka przy ściąganiu. Angażuje plecy i tylne barki.', '1. Zamocuj pojedynczy uchwyt do wyciągu dolnego.
2. Po wybraniu właściwego ciężaru stań kilka stóp za wyciągiem w szerokim rozkroku. Ramię powinno być wyprostowane, a bark wysunięty do przodu. To będzie pozycja startowa.
3. Wykonuj ruch, ściągając łopatkę i uginając łokieć. Podczas ciągnięcia supinuj nadgarstek, obracając dłoń do góry.
4. Po krótkiej pauzie wróć do pozycji startowej.', NULL, 'free-exercise-db/Shotgun_Row/0.jpg', 'free_exercise_db'),
  ('shoulder-circles', 'Krążenia barków', 'Shoulder Circles', 'motor_coach', 'beginner', array['Rozciąganie', 'Barki'], 'Wolne krążenia barkami do przodu i do tyłu. Proste ćwiczenie rozgrzewające i rozluźniające barki.', '1. Z barkami rozluźnionymi i ramionami swobodnie opuszczonymi wzdłuż ciała (lub na kolanach, jeśli siedzisz), delikatnie krąż barkami do przodu, w górę, do tyłu i w dół.
2. Odwróć kierunek krążenia. Możesz wykonywać to ćwiczenie naprzemiennie każdym barkiem albo oboma jednocześnie.', NULL, 'free-exercise-db/Shoulder_Circles/0.jpg', 'free_exercise_db'),
  ('shoulder-press-with-bands', 'Wyciskanie gumą ponad głowę', 'Shoulder Press - With Bands', 'motor_coach', 'beginner', array['Siłowe', 'Barki'], 'Ćwiczenie na barki z gumą oporową. Stajesz na gumie i wyciskasz ręce ponad głowę, prostując ramiona.', '1. Na początek stań na gumie ćwiczebnej tak, aby napięcie zaczynało się przy wyciągniętych rękach. Chwyć uchwyty i unieś je, aby dłonie były na wysokości barków po obu stronach.
2. Obróć nadgarstki tak, aby dłonie były skierowane do przodu. Łokcie powinny być zgięte, a ramiona i przedramiona w linii z tułowiem. To Twoja pozycja startowa.
3. Wydechując, unieś uchwyty do góry, aż ramiona będą całkowicie wyprostowane nad głową.', NULL, 'free-exercise-db/Shoulder_Press_-_With_Bands/0.jpg', 'free_exercise_db'),
  ('shoulder-raise', 'Unoszenie barków', 'Shoulder Raise', 'motor_coach', 'beginner', array['Rozciąganie', 'Barki'], 'Proste ćwiczenie rozluźniające barki. Unosisz ramiona wzdłuż ciała, a następnie podnosisz barki w kierunku uszu i opuszczasz je z powrotem.', '1. Rozluźnij ramiona wzdłuż ciała, unieś barki w kierunku uszu, a następnie opuść je z powrotem.', NULL, 'free-exercise-db/Shoulder_Raise/0.jpg', 'free_exercise_db'),
  ('shoulder-stretch', 'Rozciąganie barków', 'Shoulder Stretch', 'motor_coach', 'beginner', array['Rozciąganie', 'Barki'], 'Proste rozciąganie barku i klatki piersiowej. Przekładasz ramię przez ciało i trzymasz je wyprostowane.', '1. Przełóż lewe ramię przez ciało i trzymaj je prosto.', NULL, 'free-exercise-db/Shoulder_Stretch/0.jpg', 'free_exercise_db'),
  ('side-hop-sprint', 'Podskoki bokiem ze sprintem', 'Side Hop-Sprint', 'motor_coach', 'beginner', array['Plyometryka', 'Uda'], 'Ćwiczenie szybkościowo-skoczne przy pachołku lub przeszkodzie. Podskakujesz bokiem nad przeszkodą, a po ostatnim podskoku sprintujesz na krótkim dystansie.', '1. Stań z boku pachołka lub przeszkody.
2. Rozpocznij ćwiczenie od podskoku bokiem nad przeszkodą, odbijając się z lądowania, aby wrócić do punktu startowego.
3. Wykonaj określoną liczbę powtórzeń jak najszybciej, a ćwiczenie zakończ sprintem na krótkim dystansie zaraz po lądowaniu ostatniego podskoku.', NULL, 'free-exercise-db/Side_Hop-Sprint/0.jpg', 'free_exercise_db'),
  ('side-lateral-raise', 'Wznosy hantli bokiem', 'Side Lateral Raise', 'motor_coach', 'beginner', array['Siłowe', 'Barki'], 'Klasyczne ćwiczenie na boczne aktony barków. Unosisz hantle na boki do wysokości ramion, utrzymując tułów nieruchomo i lekko zgięte łokcie.', '1. Weź parę hantli i stań z wyprostowanym tułowiem, hantle swobodnie wzdłuż ciała przy wyciągniętych ramionach, dłonie skierowane do siebie. To będzie Twoja pozycja startowa.
2. Utrzymując tułów nieruchomo (bez bujania), unieś hantle na boki z lekkim zgięciem łokci, dłonie lekko przechylone do przodu, jakbyś przelewał wodę z dzbanka. Podnoś dalej, aż ramiona będą równoległe do podłogi. Wydechuj podczas ruchu i zatrzymaj się na sekundę na górze.
3. Powoli opuść hantle do pozycji startowej, robiąc wdech.
4. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Side_Lateral_Raise/0.jpg', 'free_exercise_db'),
  ('side-laterals-to-front-raise', 'Wznosy boczne z przejściem na przód', 'Side Laterals to Front Raise', 'motor_coach', 'beginner', array['Siłowe', 'Barki'], 'Ćwiczenie łączące wznosy hantli w przód i na boki. Naprzemiennie unosisz ciężary przed sobą i na boki do wysokości barków.', '1. W pozycji stojącej trzymaj parę hantli przy udach. To będzie Twoja pozycja startowa.
2. Utrzymując lekko zgięte łokcie, unieś ciężary prosto przed siebie do wysokości barków, unikając bujania i „oszukiwania”.
3. Na górze ruchu przenieś ciężary na boki, utrzymując ramiona wyprostowane.
4. Opuść ciężary kontrolowanym ruchem.
5. W kolejnym powtórzeniu unieś ciężary przed siebie do wysokości barków, a następnie przenieś je na boki.
6. Opuść ciężary do pozycji startowej.', NULL, 'free-exercise-db/Side_Laterals_to_Front_Raise/0.jpg', 'free_exercise_db'),
  ('side-leg-raises', 'Unoszenie nogi w bok', 'Side Leg Raises', 'motor_coach', 'beginner', array['Rozciąganie', 'Przywodziciele'], 'Ćwiczenie mobilności bioder wykonywane przy krześle dla wsparcia. Unosisz wyprostowaną nogę na bok i wahadłowo opuszczasz ją za drugą nogę.', '1. Stań obok krzesła, o które możesz się podpierać. Stań na jednej nodze. To będzie Twoja pozycja startowa.
2. Utrzymując nogę wyprostowaną, unieś ją jak najdalej w bok, a następnie opuść ruchem wahadłowym, pozwalając jej przekroczyć drugą nogę.
3. Powtórz ten ruch wahadłowy 5–10 razy, stopniowo zwiększając zakres ruchu.', NULL, 'free-exercise-db/Side_Leg_Raises/0.jpg', 'free_exercise_db'),
  ('side-lying-floor-stretch', 'Rozciąganie boczne leżąc na boku', 'Side-Lying Floor Stretch', 'motor_coach', 'beginner', array['Rozciąganie', 'Najszersze grzbietu'], 'Rozciąganie całego boku ciała w pozycji leżennej. Leżysz na jednym boku, a drugą nogę i ramię prostujesz ponad głowę, delikatnie ciągnąc za nadgarstek.', '1. Najpierw połóż się na lewym boku, zginając lewe kolano przed sobą, aby ustabilizować tułów (do utrzymania pionu używaj też mięśni brzucha).
2. Wyprostuj prawą nogę i oprzyj prawą stopę na podłodze za lewą. Wyciągnij prawe ramię ponad głowę i delikatnie pociągnij za prawy nadgarstek, aby rozciągnąć całą prawą stronę ciała. Zmień strony.', NULL, 'free-exercise-db/Side-Lying_Floor_Stretch/0.jpg', 'free_exercise_db'),
  ('side-lying-groin-stretch', 'Rozciąganie pachwin leżąc na boku', 'Side Lying Groin Stretch', 'motor_coach', 'beginner', array['Rozciąganie', 'Przywodziciele'], 'Rozciąganie pachwin i przywodzicieli w pozycji leżennej. Leżysz na boku, unosisz górną nogę i ciągniesz kolano w stronę barku, dociskając stopę lub kolano do podłogi.', '1. Zacznij od położenia się na prawym boku i ugnij prawe kolano przed sobą, aby ustabilizować tułów.
2. Oprzyj głowę na prawej dłoni lub barku. Unieś lewą nogę do góry i chwyć ją pod kolanem (łatwiej) albo za stopę (trudniej).
3. Pociągnij lewe kolano w kierunku lewego barku i jednocześnie dociśnij stopę lub kolano do podłogi. Aby pogłębić rozciąganie, wyprostuj lewą nogę. Zmień strony.', NULL, 'free-exercise-db/Side_Lying_Groin_Stretch/0.jpg', 'free_exercise_db'),
  ('side-neck-stretch', 'Rozciąganie boczne karku', 'Side Neck Stretch', 'motor_coach', 'beginner', array['Rozciąganie', 'Kark'], 'Delikatne rozciąganie bocznej części szyi. Przechylasz głowę w stronę barku i możesz lekko wspomóc ruch dłonią.', '1. Zacznij z rozluźnionymi barkami i delikatnie przechyl głowę w stronę barku.
2. Wspomóż rozciąganie delikatnym pociąganiem głowy za bok.', NULL, 'free-exercise-db/Side_Neck_Stretch/0.jpg', 'free_exercise_db'),
  ('side-standing-long-jump', 'Skok w dal w bok', 'Side Standing Long Jump', 'motor_coach', 'beginner', array['Plyometryka', 'Uda'], 'Ćwiczenie plyometryczne — skok w bok z pozycji stojącej. Wybijasz się biodrami, kolanami i kostkami, aby skoczyć maksymalnie daleko w bok.', '1. Stań ze stopami na szerokość bioder w pozycji atletycznej. Głowa i klatka piersiowa uniesione, kolana i biodra lekko ugięte. To będzie Twoja pozycja startowa.
2. Pochylając się w prawo, wybij się przez wyprost bioder, kolan i kostek, aby skoczyć w powietrze. Prowadź ruch pracą ramion, skacząc jak najdalej w prawo.
3. Wyląduj twarzą w tym samym kierunku, ze stopami na szerokość bioder, amortyzując uderzenie nogami.', NULL, 'free-exercise-db/Side_Standing_Long_Jump/0.jpg', 'free_exercise_db'),
  ('side-to-side-box-shuffle', 'Przeskoki bokiem przez skrzynię', 'Side to Side Box Shuffle', 'motor_coach', 'beginner', array['Plyometryka', 'Uda'], 'Ćwiczenie plyometryczne polegające na szybkich przeskokach bokiem przez skrzynię. Przeskakujesz z jednej strony na drugą, pomagając sobie pracą ramion.', '1. Stań z jednej strony skrzyni z lewą stopą opartą na jej środku.
2. Na start wyskocz w górę i na drugą stronę skrzyni, lądując prawą stopą na skrzyni, a lewą na podłodze. Pomagaj sobie ruchem ramion.
3. Kontynuuj przeskoki tam i z powrotem przez skrzynię.', NULL, 'free-exercise-db/Side_to_Side_Box_Shuffle/0.jpg', 'free_exercise_db'),
  ('side-to-side-chins', 'Podciąganie z przechyłem na boki', 'Side To Side Chins', 'motor_coach', 'intermediate', array['Siłowe', 'Najszersze grzbietu'], 'Zaawansowana wersja podciągania na drążku. Podczas podciągania pochylasz tułów raz w lewo, raz w prawo, tak aby drążek dotknął górnej części klatki piersiowej.', '1. Złap drążek do podciągania nachwytem na szerokość większą niż barki.
2. Mając oba ramiona wyprostowane i szeroki chwyt drążka, cofnij tułów o około 30 stopni, tworząc wygięcie w odcinku lędźwiowym i wypychając klatkę piersiową do przodu. To Twoja pozycja startowa.
3. Podciągnij tułów w górę, pochylając się w lewo, aż drążek prawie dotknie górnej części klatki piersiowej, opuszczając barki i ramiona w dół i do tyłu. Wydechuj podczas tej fazy ruchu. Wskazówka: skup się na spięciu mięśni pleców w pełnym skurczu. Górna część tułowia powinna pozostać nieruchoma (bez bujania) — poruszać powinny się tylko ramiona. Przedramiona nie powinny wykonywać żadnej innej pracy niż trzymanie drążka.
4. Po sekundzie napięcia zrób wdech, wracając do pozycji startowej.
5. Teraz podciągnij tułów w górę, pochylając się w prawo, aż drążek prawie dotknie górnej części klatki piersiowej, opuszczając barki i ramiona w dół i do tyłu. Wydechuj podczas tej fazy ruchu. Wskazówka: skup się na spięciu mięśni pleców w pełnym skurczu. Górna część tułowia powinna pozostać nieruchoma, poruszać się powinny tylko ramiona. Przedramiona nie powinny wykonywać żadnej innej pracy niż trzymanie drążka.
6. Po sekundzie napięcia zrób wdech, wracając do pozycji startowej.
7. Powtarzaj kroki 3–6, aż wykonasz zalecaną liczbę powtórzeń na każdą stronę.', NULL, 'free-exercise-db/Side_To_Side_Chins/0.jpg', 'free_exercise_db'),
  ('side-wrist-pull', 'Rozciąganie z pociąganiem za nadgarstek', 'Side Wrist Pull', 'motor_coach', 'beginner', array['Rozciąganie', 'Barki'], 'Rozciąganie barku i pleców wykonywane najlepiej na stojąco. Przekładasz ramię przez ciało, chwytasz za nadgarstek, prostujesz ramię i unośysz je do wysokości barku.', '1. To rozciąganie działa najlepiej na stojąco. Przełóż lewe ramię przez środek ciała i chwyć lewy nadgarstek prawą dłonią na wysokości bioder. Zacznij rozciąganie z ugiętym lewym ramieniem.
2. Powoli prostuj, ciągnij i unoś ramię do wysokości barku, jak na zdjęciu. Powinieneś czuć rozciąganie w plecach, a nie w barkach, i nie ciągnij zbyt mocno za staw barkowy. Zmień strony.', NULL, 'free-exercise-db/Side_Wrist_Pull/0.jpg', 'free_exercise_db'),
  ('single-arm-cable-crossover', 'Krzyżowanie linek wyciągu jedną ręką', 'Single-Arm Cable Crossover', 'motor_coach', 'beginner', array['Siłowe', 'Klatka piersiowa'], 'Ćwiczenie na klatkę piersiową wykonywane na wyciągu. Jedną ręką prowadzisz uchwyt do środka ciała, podczas gdy druga pozostaje wyciągnięta na bok.', '1. Zacznij od ustawienia bloczków na górnej pozycji, wybierz opór i złap uchwyt w każdą dłoń.
2. Zrób krok do przodu przed oba bloczki z ramionami wyciągniętymi przed sobą, zbliżając dłonie do siebie. Głowa i klatka piersiowa uniesione przy pochyleniu tułowia, nogi w rozkroku (jedna z przodu). To będzie Twoja pozycja startowa.
3. Trzymając lewe ramię w miejscu, pozwól prawemu ramieniu wyprostować się w bok, zachowując lekkie zgięcie w łokciu. Prawe ramię powinno być prostopadłe do ciała mniej więcej na wysokości barku.
4. Wróć ramieniem do pozycji startowej, przyciągając dłoń z powrotem do linii środkowej ciała.
5. Przytrzymaj sekundę w pozycji startowej i powtórz ruch drugą stroną. Kontynuuj naprzemiennie przez zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Single-Arm_Cable_Crossover/0.jpg', 'free_exercise_db'),
  ('single-arm-linear-jammer', 'Wyciskanie sztangi z kąta jedną ręką', 'Single-Arm Linear Jammer', 'motor_coach', 'intermediate', array['Siłowe', 'Barki'], 'Wybuchowe wyciskanie sztangi opartej o kąt lub landmine. Wyciskasz ciężar jedną ręką nad głowę, angażując całe ciało.', '1. Umieść sztangę w landmine lub pewnie podeprzyj ją w kącie. Załaduj odpowiedni ciężar.
2. Podnieś sztangę z podłogi, przenosząc ją na barki jednym lub obiema rękami. Przyjmij szeroką postawę. To będzie Twoja pozycja startowa.
3. Wykonaj ruch poprzez wyprost łokcia, wyciskając ciężar w górę. Ruch ma być wybuchowy, z pełnym wyprostem bioder i kolan, aby wygenerować maksymalną siłę.
4. Wróć do pozycji startowej.', NULL, 'free-exercise-db/Single-Arm_Linear_Jammer/0.jpg', 'free_exercise_db'),
  ('single-arm-push-up', 'Pompka na jednej ręce', 'Single-Arm Push-Up', 'motor_coach', 'intermediate', array['Siłowe', 'Klatka piersiowa'], 'Zaawansowana wersja pompki z podparciem tylko na jednej ręce. Wymaga szerokiego rozstawu nóg i mocnych mięśni głębokich.', '1. Połóż się twarzą w dół na podłodze. Ustaw się w pozycji z podparciem na palcach stóp i jednej ręce. Ramię robocze powinno znajdować się dokładnie pod barkiem, całkowicie wyprostowane. Nogi powinny być wyprostowane, a do tego ćwiczenia możesz potrzebować szerszej bazy — stopy ustawione szerzej niż przy zwykłej pompce.
2. Utrzymuj dobrą postawę i schowaj wolną dłoń za plecami. To będzie Twoja pozycja startowa.
3. Opuszczaj się, uginając łokieć, aż dotkniesz podłogi.
4. Opuszczaj się powoli, a następnie zmień kierunek ruchu, prostując ramię, aby wrócić do pozycji startowej.', NULL, 'free-exercise-db/Single-Arm_Push-Up/0.jpg', 'free_exercise_db'),
  ('single-cone-sprint-drill', 'Ćwiczenie szybkościowe z jednym pachołkiem', 'Single-Cone Sprint Drill', 'motor_coach', 'beginner', array['Plyometryka', 'Uda'], 'Ćwiczenie na szybkość pracy stóp z jednym pachołkiem. Wykonujesz drobne, bardzo szybkie kroki wokół pachołka, pomagając sobie pracą ramion.', '1. To ćwiczenie uczy szybkiej pracy stóp. Potrzebujesz jednego pachołka. Zacznij, stając obok pachołka z jednym ramieniem cofniętym, a drugim wyciągniętym do przodu.
2. Wykonuj drobne kroki jak najszybciej, blokując ruch pracą ramion. Okrążaj pachołek, trzymając kolana wysoko, z energiczną pracą stóp.
3. Odpocznij po trzech okrążeniach pachołka.', NULL, 'free-exercise-db/Single-Cone_Sprint_Drill/0.jpg', 'free_exercise_db'),
  ('single-dumbbell-raise', 'Unoszenie hantla przed sobą dwoma rękami', 'Single Dumbbell Raise', 'motor_coach', 'beginner', array['Siłowe', 'Barki'], 'Wznos jednego hantla trzymanego oburącz ponad głowę. Unosisz ciężar przed sobą do wysokości ponad barki.', '1. W szerokiej postawie trzymaj hantel oburącz, chwytając za jeden jego koniec zamiast za rękojeść. Ramiona wyprostowane, zwisające przed biodrami. To będzie Twoja pozycja startowa.
2. Unoś ciężar aż znajdzie się ponad poziomem barków, trzymając ramiona wyprostowane. Tułów i biodra powinny pozostać nieruchome przez cały ruch.
3. Wróć do pozycji startowej i powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Single_Dumbbell_Raise/0.jpg', 'free_exercise_db'),
  ('single-leg-butt-kick', 'Kopnięcie w pośladek na jednej nodze', 'Single Leg Butt Kick', 'motor_coach', 'beginner', array['Plyometryka', 'Uda'], 'Ćwiczenie plyometryczne — podskok na jednej nodze z kopnięciem piętą w kierunku pośladka. Wybijasz się jednym udem i natychmiast ugięasz kolano.', '1. Zacznij stojąc na jednej nodze z uniesionym kolanem. To będzie Twoja pozycja startowa.
2. Używając wyskoku z zamachem przeciwnym, wybij się w górę prostując biodro, kolano i kostkę nogi podporowej.
3. Natychmiast ugnij kolano i spróbuj dotknąć piętą nogi wybiciowej pośladka.
4. Wróć nogę do częściowo ugiętej pozycji pod biodrami i wyląduj. Noga przeciwna powinna pozostać w mniej więcej tej samej pozycji przez całe ćwiczenie.', NULL, 'free-exercise-db/Single_Leg_Butt_Kick/0.jpg', 'free_exercise_db'),
  ('single-leg-glute-bridge', 'Mostek biodrowy na jednej nodze', 'Single Leg Glute Bridge', 'motor_coach', 'beginner', array['Siłowe', 'Pośladki'], 'Wzmacnianie pośladków w leżeniu na plecach. Unośysz biodra do góry, opierając się tylko na jednej stopie.', '1. Połóż się na podłodze ze stopami płasko na ziemi i ugiętymi kolanami.
2. Unoś jedną nogę nad ziemią, przyciągając kolano do klatki piersiowej. To będzie Twoja pozycja startowa.
3. Wykonaj ruch, odpychając się piętą, prostując biodro w górę i unosząc pośladki nad ziemię.
4. Wyprostuj się maksymalnie, zatrzymaj się na chwilę, a potem wróć do pozycji startowej.', NULL, 'free-exercise-db/Single_Leg_Glute_Bridge/0.jpg', 'free_exercise_db'),
  ('single-leg-high-box-squat', 'Przysiad na wysokiej skrzyni na jednej nodze', 'Single-Leg High Box Squat', 'motor_coach', 'beginner', array['Siłowe', 'Uda'], 'Wchodzenie na wysokie podwyższenie na jednej nodze. Druga noga pozostaje bez podparcia, a równowagę wspomaga guma lub lina.', '1. Ustaw skrzynię w stojaku. Zamocuj gumę lub linę nad skrzynią.
2. Stojąc przed nią, wejdź na skrzynię do pełnego wyprostu, pozwalając drugiej nodze pozostać bez podparcia. Trzymaj się gumy dla równowagi
3. . Kontynuuj wchodzenie i schodzenie na tej samej nodze, zanim zmienisz stronę.', NULL, 'free-exercise-db/Single-Leg_High_Box_Squat/0.jpg', 'free_exercise_db'),
  ('single-leg-hop-progression', 'Postępy podskoków na jednej nodze', 'Single-Leg Hop Progression', 'motor_coach', 'beginner', array['Plyometryka', 'Uda'], 'Podskoki na jednej nodze przez rząd pachołków. Wybijasz się i lądujesz na tej samej nodze, a na końcu wracasz na drugiej.', '1. Ustaw rząd pachołków przed sobą. Przyjmij rozluźnioną pozycję stojącą, wyważoną na jednej nodze. Unieś kolano przeciwnej nogi. To będzie Twoja pozycja startowa.
2. Podskocz w przód, wybijając się i lądując na tej samej nodze nad pachołkiem.
3. Używaj wyskoku z zamachem przeciwnym, aby przeskakiwać z pachołka na pachołek.
4. Na końcu zawróć i wróć na drugiej nodze.', NULL, 'free-exercise-db/Single-Leg_Hop_Progression/0.jpg', 'free_exercise_db'),
  ('single-leg-lateral-hop', 'Podskok boczny na jednej nodze', 'Single-Leg Lateral Hop', 'motor_coach', 'beginner', array['Plyometryka', 'Uda'], 'Ćwiczenie plyometryczne — podskoki bokiem nad przeszkodą na jednej nodze. Wybijasz się, przeskakujesz przeszkodę i odbijasz się do tyłu.', '1. Stań obok pachołka lub przeszkody. Aby przyjąć pozycję startową, stań na jednej nodze z lekko ugiętym kolanem.
2. Na start wykonaj wyskok z zamachem przeciwnym, aby podskoczyć bokiem nad pachołkiem.
3. Wyląduj na nodze wybiciowej i natychmiast odbij się z niej, skacząc z powrotem do pozycji startowej.
4. Kontynuuj podskoki tam i z powrotem.', NULL, 'free-exercise-db/Single-Leg_Lateral_Hop/0.jpg', 'free_exercise_db'),
  ('single-leg-leg-extension', 'Prostowanie nogi jednonóż', 'Single-Leg Leg Extension', 'motor_coach', 'beginner', array['Siłowe', 'Uda'], 'Ćwiczenie na mięśnie czworogłowe uda na maszynie. Prostujesz jedną nogę w kolanie, unosząc ciężar, i kontrolowanie opuszczasz.', '1. Usiądź na maszynie i dostosuj ją tak, aby była prawidłowo ustawiona. Poduszka powinna opierać się o dolną część piszczeli, ale nie stykać się z kostką. Ustaw siedzisko tak, aby punkt obrotu był w linii z Twoim kolanem. Wybierz ciężar odpowiedni do swoich możliwości.
2. Utrzymując dobrą postawę, całkowicie wyprostuj jedną nogę, zatrzymując się na chwilę na górze ruchu.
3. Wróć do pozycji startowej, nie pozwalając ciężarowi się zatrzymać, utrzymując napięcie mięśnia.
4. Powtórz żądaną liczbę powtórzeń.', NULL, 'free-exercise-db/Single-Leg_Leg_Extension/0.jpg', 'free_exercise_db'),
  ('single-leg-push-off', 'Odepchnięcie z podwyższenia jedną nogą', 'Single Leg Push-off', 'motor_coach', 'beginner', array['Plyometryka', 'Uda'], 'Ćwiczenie plyometryczne na siłę wybicia jednej nogi. Stajesz stopą na skrzyni, odepchasz się i lądujesz z powrotem na tej samej nodze.', '1. Stań na podłodze z jedną stopą opartą na skrzyni, piętą blisko krawędzi.
2. Odepcznij się stopą na skrzyni, starając się uzyskać maksymalną wysokość dzięki wyprostowi w biodrze i kolanie.
3. Wyląduj tą samą stopą na skrzyni, wracając drugą stopą do pozycji startowej.', NULL, 'free-exercise-db/Single_Leg_Push-off/0.jpg', 'free_exercise_db'),
  ('single-leg-stride-jump', 'Skok wykroczny na jednej nodze', 'Single-Leg Stride Jump', 'motor_coach', 'beginner', array['Plyometryka', 'Uda'], 'Wybuchowy skok w górę z pozycji z jedną stopą na skrzyni. Wyskakujesz jak najwyżej, unosząc przeciwne kolano.', '1. Stań z boku skrzyni z wewnętrzną stopą na jej powierzchni, blisko krawędzi.
2. Zacznij od zamachu ramionami w górę, odpychając się górną nogą i wyskakując jak najwyżej. Spróbuj unieść przeciwne kolano do góry.
3. Wyląduj w tej samej pozycji, w której zacząłeś, używając nogi wewnętrznej do amortyzacji.', NULL, 'free-exercise-db/Single-Leg_Stride_Jump/0.jpg', 'free_exercise_db'),
  ('sit-squats', 'Przysiady częściowe do krzesła', 'Sit Squats', 'motor_coach', 'beginner', array['Rozciąganie', 'Uda'], 'Częściowy przysiad bez pełnego zejścia poniżej równoległości. Opuszczasz się tylko częściowo i dynamicznie wracasz do góry.', '1. Stań ze stopami na szerokość barków. To będzie Twoja pozycja startowa.
2. Rozpocznij ruch uginając kolana i biodra, cofając biodra do tyłu.
3. Kontynuuj, aż zejdziesz tylko częściowo w dół (pozostając powyżej równoległości), a następnie szybko odwróć ruch, aby wrócić do pozycji startowej. Powtórz 5–10 powtórzeń.', NULL, 'free-exercise-db/Sit_Squats/0.jpg', 'free_exercise_db'),
  ('sit-up', 'Brzuchy', 'Sit-Up', 'motor_coach', 'beginner', array['Siłowe', 'Brzuch'], 'Klasyczne ćwiczenie na mięśnie brzucha w leżeniu na plecach. Unośisz tułów w górę, tworząc literę V z udami.', '1. Połóż się na podłodze, umieszczając stopy pod czymś stabilnym lub poproś partnera, aby je przytrzymał. Nogi powinny być ugięte w kolanach.
2. Połóż dłonie za głową i spleć palce. To pozycja startowa.
3. Unoś tułów tak, aby utworzył wyobrażoną literę V z udami. Wydechuj podczas tej fazy ćwiczenia.
4. Gdy poczujesz napięcie przez sekundę, opuść tułów z powrotem do pozycji startowej, robiąc wdech.
5. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Sit-Up/0.jpg', 'free_exercise_db'),
  ('skating', 'Jazda na wrotkach', 'Skating', 'motor_coach', 'intermediate', array['Cardio', 'Uda'], 'Forma aktywności cardio poprawiająca wydolność oddechową i wytrzymałość mięśniową. Wymaga dobrej równowagi, koordynacji oraz sprzętu ochronnego.', '1. Jazda na wrotkach to zabawna aktywność, która może skutecznie poprawiać wydolność oddechową i wytrzymałość mięśniową. Wymaga względnie dobrej równowagi i koordynacji. Konieczne jest nauczenie się podstaw jazdy, w tym skręcania i hamowania, oraz noszenie ochraniaczy, aby uniknąć ewentualnych urazów.
2. Możesz jeździć komfortowym tempem przez 30 minut. Jeśli chcesz wyzwania cardio, jazda interwałowa — sprintuj 2 minuty co każde 5 minut, używając pozostałych 3 minut na regenerację. Osoba ważąca 68 kg spala zazwyczaj około 175 kcal w 30 minut jazdy komfortowym tempem — podobnie jak szybki marsz.', NULL, 'free-exercise-db/Skating/0.jpg', 'free_exercise_db'),
  ('sled-drag-harness', 'Ciągnięcie saneczek w uprzęży', 'Sled Drag - Harness', 'motor_coach', 'beginner', array['Strongman', 'Uda'], 'Ćwiczenie siłowe polegające na ciągnięciu obciążonych saneczek za pomocą uprzęży lub pasów. Możesz ciągnąć do przodu lub do tyłu.', '1. Na początek załaduj saneczki żądanym ciężarem i podepnij linkę ciągnącą. Możesz ciągnąć za uchwyty, używać uprzęży albo przymocować linkę do pasa obciążającego.
2. Niezależnie od tego, czy ciągniesz do przodu, czy do tyłu, pochyl się w kierunku ruchu i posuwaj naprzód poprzez wyprost bioder i kolan.', NULL, 'free-exercise-db/Sled_Drag_-_Harness/0.jpg', 'free_exercise_db'),
  ('sled-overhead-backward-walk', 'Marsz tyłem z saneczkami nad głową', 'Sled Overhead Backward Walk', 'motor_coach', 'beginner', array['Siłowe', 'Barki'], 'Marsz do tyłu z saneczkami ciągniętymi nad głową. Trzymasz ręce wysoko ponad głową i cofasz się, wzmacniając barki i mięśnie głębokie.', '1. Zamocuj dwa uchwyty do saneczek połączonych liną lub łańcuchem. Załaduj lekkim ciężarem.
2. Odwróć się przodem do saneczek i cofnij, aż w linie pojawi się napięcie. Trzymaj dłonie dokładnie nad głową z wyprostowanymi łokciami. To będzie Twoja pozycja startowa.
3. Chodź do tyłu, utrzymując ramiona uniesione nad głową. Unikaj szarpanych ruchów.', NULL, 'free-exercise-db/Sled_Overhead_Backward_Walk/0.jpg', 'free_exercise_db'),
  ('sled-overhead-triceps-extension', 'Prostowanie ramion z saneczkami nad głową', 'Sled Overhead Triceps Extension', 'motor_coach', 'beginner', array['Siłowe', 'Triceps'], 'Ćwiczenie tricepsów z użyciem saneczek i liny. Prostujesz ramiona nad głową, pokonując opór liny.', '1. Zamocuj dwa uchwyty do saneczek za pomocą łańcucha lub liny. Załaduj odpowiedni ciężar.
2. Tyłem do saneczek, oddal się, aż w linie pojawi się napięcie. Unieś dłonie ponad głowę, trzymając je razem, dłonie zwrócone do siebie. Łokcie powinny być skierowane w górę i ugięte. To będzie Twoja pozycja startowa.
3. Prostuj łokieć, aż ramię będzie wyprostowane. Upewnij się, że górna część ramienia pozostaje w miejscu, aby izolować triceps.
4. Po pełnym wyproście zrób krok do przodu, aby usunąć luz z liny. Możesz ustawić nogi w rozkroku dla lepszej stabilności.', NULL, 'free-exercise-db/Sled_Overhead_Triceps_Extension/0.jpg', 'free_exercise_db'),
  ('sled-push', 'Pchanie saneczek', 'Sled Push', 'motor_coach', 'beginner', array['Strongman', 'Uda'], 'Intensywne ćwiczenie całego ciała — pchanie obciążonych saneczek. Popychasz je jak najszybciej, angażując nogi i pośladki.', '1. Załaduj swoje saneczki żądanym ciężarem.
2. Przyjmij atletyczną postawę, pochylając się na saneczki z całkowicie wyprostowanymi ramionami, chwytając uchwyty. Pchnij saneczki jak najszybciej, koncentrując się na wyproście bioder i kolan, aby wzmacniać tylną taśmę mięśniową.', NULL, 'free-exercise-db/Sled_Push/0.jpg', 'free_exercise_db'),
  ('sled-reverse-flye', 'Rozpiętki odwrotne z saneczkami', 'Sled Reverse Flye', 'motor_coach', 'beginner', array['Siłowe', 'Barki'], 'Ćwiczenie na tylne aktony barków z użyciem saneczek i liny. Unośesz uchwyty w górę i na boki, wykonując ruch rozpiętki.', '1. Zamocuj dwa uchwyty do saneczek połączonych liną lub łańcuchem. Załaduj lekki ciężar.
2. Odwróć się przodem do saneczek i cofnij, aż w linie pojawi się napięcie. Chwyć oba uchwyty przy wyciągniętych ramionach na wysokości bioder. Lekko ugnij kolana, trzymaj klatkę piersiową i głowę uniesione. To będzie Twoja pozycja startowa.
3. Bez uginania łokci pociągnij uchwyty w górę i na boki, wykonując rozpiętkę odwrotną z lekką rotacją zewnętrzną. Twoje dłonie powinny być skierowane do przodu podczas tego ruchu.
4. Wróć do pozycji startowej, robiąc kilka kroków do przodu, aby usunąć luz z liny.', NULL, 'free-exercise-db/Sled_Reverse_Flye/0.jpg', 'free_exercise_db'),
  ('sled-row', 'Wiosłowanie z saneczkami', 'Sled Row', 'motor_coach', 'beginner', array['Siłowe', 'Środek pleców'], 'Wiosłowanie z saneczkami połączonymi liną. Przyciągasz uchwyty do siebie, ściągaając łopatki.', '1. Zamocuj dwa uchwyty do saneczek połączonych liną lub łańcuchem. Załaduj odpowiedni ciężar. Odwróć się przodem do saneczek i cofnij, aż w linie pojawi się napięcie.
2. Z uchwytem w każdej dłoni lekko ugnij kolana, trzymaj głowę i klatkę piersiową uniesione, zacznij z ramionami wyprostowanymi.
3. Aby rozpocząć ruch, ugnij łokcie, ściągając łopatki i przyciągając saneczki do siebie.
4. Zrób krok lub dwa do tyłu, aby napiąć linę, i powtarzaj.', NULL, 'free-exercise-db/Sled_Row/0.jpg', 'free_exercise_db'),
  ('sledgehammer-swings', 'Uderzenia młotem w oponę', 'Sledgehammer Swings', 'motor_coach', 'beginner', array['Plyometryka', 'Brzuch'], 'Wybuchowe uderzenia młotem w leżącą oponę. Angażuje całe ciało — nogi, tułów, barki i ramiona.', '1. Do tego ćwiczenia potrzebujesz opony i młota. Stań przed oponą około dwóch stóp od niej w rozkroku (jedna noga z przodu). Chwyć młot.
2. Jeśli jesteś praworęczny, twoja lewa dłoń powinna znajdować się na końcu trzonka, a prawa bliżej główki młota.
3. Podczas zamachu w górę prawa dłoń przesuwa się w stronę główki; gdy machniesz w dół, prawa dłoń zsunie się w dół, dołączając do lewej. Uderz młotem w oponę z maksymalną siłą. Kontroluj odbicie młota od opony.
4. Powtórz drugą stroną.', NULL, 'free-exercise-db/Sledgehammer_Swings/0.jpg', 'free_exercise_db'),
  ('smith-incline-shoulder-raise', 'Wznosy barków na ławce skośnej w maszynie Smitha', 'Smith Incline Shoulder Raise', 'motor_coach', 'beginner', array['Siłowe', 'Barki'], 'Wznosy przód na barki w maszynie Smitha na ławce skośnej. Leżysz na ławce i unośisz sztangę prosto nad siebie.', '1. Umieść ławkę skośną pod maszyną Smitha. Ustaw sztangę na wysokości, którą osiągniesz leżąc, z niemal całkowicie wyprostowanymi ramionami. Po wybraniu ciężaru połóż się na ławce skośnej i upewnij się, że barki są ustawione dokładnie pod sztangą.
2. Chwytem nachwytem na szerokość barków zdejmij sztangę ze stojaka i trzymaj ją prosto nad sobą z lekkim ugięciem łokci. To będzie Twoja pozycja startowa.
3. Robiąc wydech, unoś sztangę do pełnego wyprostu ramion. Uwaga: napięcie powinno być odczuwalne w okolicy barków.
4. Po sekundzie pauzy opuść sztangę z powrotem do pozycji startowej, robiąc wdech.
5. Powtórz ruch zalecaną liczbę powtórzeń.
6. Po zakończeniu odłóż sztangę z powrotem na stojak.', NULL, 'free-exercise-db/Smith_Incline_Shoulder_Raise/0.jpg', 'free_exercise_db'),
  ('smith-machine-behind-the-back-shrug', 'Szrusztowanie sztangą z tyłu w maszynie Smitha', 'Smith Machine Behind the Back Shrug', 'motor_coach', 'beginner', array['Siłowe', 'Czworoboczne'], 'Unoszenie barków (szruszt) ze sztangą za plecami w maszynie Smitha. Unośesz barki w górę, wzmacniając mięsień czworoboczny.', '1. Przy sztandze na wysokości ud załaduj odpowiedni ciężar.
2. Stań ze sztangą za sobą, chwytając ją nachwytem na szerokość barków, i odepnij ciężar. Powinieneś stać prosto z uniesioną głową i klatką piersiową oraz wyprostowanymi ramionami. To będzie Twoja pozycja startowa.
3. Rozpocznij ruch unosząc barki prosto w górę. Nie uginaj ramion ani nadgarstków podczas ruchu.
4. Po krótkiej pauzie wróć do pozycji startowej.
5. Powtórz żądaną liczbę powtórzeń, po czym zahacz sztangę o haczyki.', NULL, 'free-exercise-db/Smith_Machine_Behind_the_Back_Shrug/0.jpg', 'free_exercise_db'),
  ('smith-machine-bench-press', 'Wyciskanie sztangi leżąc w maszynie Smitha', 'Smith Machine Bench Press', 'motor_coach', 'beginner', array['Siłowe', 'Klatka piersiowa'], 'Wyciskanie leżąc na płaskiej ławce w maszynie Smitha. Bezpieczna wersja klasycznego wyciskania — sztanga porusza się po prowadnicach.', '1. Umieść płaską ławkę pod maszyną Smitha. Ustaw sztangę na wysokości, którą osiągniesz leżąc, z niemal całkowicie wyprostowanymi ramionami. Po wybraniu ciężaru połóż się na płaskiej ławce. Chwytem nachwytem szerszym niż barki odepnij sztangę ze stojaka i trzymaj ją prosto nad sobą z zablokowanymi ramionami. To będzie Twoja pozycja startowa.
2. Robiąc wdech, opuszczaj się powoli, aż poczujesz sztangę na środku klatki piersiowej.
3. Po sekundzie pauzy wróć do pozycji startowej, robiąc wydech i wypychając sztangę mięśniami klatki piersiowej. Zablokuj ramiona w skurczu, przytrzymaj sekundę, a potem znów zacznij opuszczać powoli. Wskazówka: schodzenie powinno trwać co najmniej dwa razy dłużej niż wyciskanie w górę.
4. Powtórz ruch zalecaną liczbę powtórzeń.
5. Po zakończeniu zahacz sztangę z powrotem o stojak.', NULL, 'free-exercise-db/Smith_Machine_Bench_Press/0.jpg', 'free_exercise_db'),
  ('smith-machine-bent-over-row', 'Wiosłowanie sztangą w opadzie w maszynie Smitha', 'Smith Machine Bent Over Row', 'motor_coach', 'beginner', array['Siłowe', 'Środek pleców'], 'Wiosłowanie w opadzie tułowia w maszynie Smitha. Przyciągasz sztangę do brzucha, budując siłę pleców.', '1. Ustaw sztangę w maszynie Smitha na wysokości około 5 cm poniżej kolan.
2. Lekko ugnij kolana i pochyl tułów do przodu, zginając się w biodrach, zachowując prosty grzbiet, aż będzie prawie równoległy do podłogi. Wskazówka: pamiętaj, aby trzymać głowę uniesioną.
3. Teraz złap sztangę nachwytem i odepnij ją ze stojaka maszyny Smitha. Potem pozwól jej swobodnie zwisać przed sobą, z ramionami wyprostowanymi prostopadle do podłogi i tułowia. To Twoja pozycja startowa.
4. Utrzymując tułów nieruchomo, unoś sztangę robiąc wydech, trzymając łokcie blisko ciała i nie wykonując żadnej siły przedramieniem poza trzymaniem ciężaru. Na górze, w pełnym skurczu, spięcie mięśnie pleców i przytrzymaj sekundę.
5. Powoli opuść ciężar z powrotem do pozycji startowej, robiąc wdech.
6. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Smith_Machine_Bent_Over_Row/0.jpg', 'free_exercise_db'),
  ('smith-machine-calf-raise', 'Wspięcia na palce w maszynie Smitha', 'Smith Machine Calf Raise', 'motor_coach', 'beginner', array['Siłowe', 'Łydki'], 'Wzmacnianie łydek w maszynie Smitha. Stajesz na platformie i unośesz pięty maksymalnie w górę.', '1. Umieść blok lub talerz od sztangi pod sztangą maszyny Smitha. Ustaw sztangę na wysokości najlepiej dopasowanej do Twojego wzrostu. Po wybraniu wysokości i załadowaniu sztangi wejdź na talerze śródstopiem i połóż sztangę na tylnych partiach barków.
2. Złap sztangę oburącz, dłońmi skierowanymi do przodu. Obróć sztangę, aby zdjąć ją ze stojaka. To będzie Twoja pozycja startowa.
3. Unoś pięty jak najwyżej, odpychając się śródstopiem i spinając łydkę na szczycie skurczu. Kolana powinny pozostać wyprostowane. Przytrzymaj pozycję napięcia przez sekundę, zanim zaczniesz schodzić w dół.
4. Powoli wróć do pozycji startowej, robiąc wdech i opuszczając pięty.
5. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Smith_Machine_Calf_Raise/0.jpg', 'free_exercise_db'),
  ('smith-machine-close-grip-bench-press', 'Wyciskanie wąskim chwytem w maszynie Smitha', 'Smith Machine Close-Grip Bench Press', 'motor_coach', 'beginner', array['Siłowe', 'Triceps'], 'Wyciskanie leżąc wąskim chwytem w maszynie Smitha. Maksymalnie angażuje tricepsy.', '1. Umieść płaską ławkę pod maszyną Smitha. Ustaw sztangę na wysokości, którą osiągniesz leżąc, z niemal całkowicie wyprostowanymi ramionami. Po wybraniu ciężaru połóż się na płaskiej ławce. Chwytem nachwytem około szerokości barków odepnij sztangę ze stojaka i trzymaj ją prosto nad sobą z zablokowanymi ramionami. To będzie Twoja pozycja startowa.
2. Robiąc wdech, opuszczaj się powoli, aż poczujesz sztangę na środku klatki piersiowej. Wskazówka: w przeciwieństwie do zwykłego wyciskania leżąc, trzymaj łokcie blisko tułowia przez cały czas, aby zmaksymalizować pracę tricepsów.
3. Po sekundzie pauzy wróć do pozycji startowej, robiąc wydech i wypychając sztangę mięśniami tricepsów. Zablokuj ramiona w skurczu, przytrzymaj sekundę, a potem znów zacznij opuszczać powoli. Wskazówka: schodzenie powinno trwać co najmniej dwa razy dłużej niż wyciskanie w górę.
4. Powtórz ruch zalecaną liczbę powtórzeń.
5. Po zakończeniu zahacz sztangę z powrotem o stojak.', NULL, 'free-exercise-db/Smith_Machine_Close-Grip_Bench_Press/0.jpg', 'free_exercise_db'),
  ('smith-machine-decline-press', 'Wyciskanie na ławce negatywnej w maszynie Smitha', 'Smith Machine Decline Press', 'motor_coach', 'beginner', array['Siłowe', 'Klatka piersiowa'], 'Wyciskanie sztangi na ławce z opadem (głowa niżej niż biodra). Angażuje dolne partie klatki piersiowej.', '1. Ustaw ławkę z opadem w stojaku tak, aby sztanga znajdowała się nad Twoją klatką piersiową. Załaduj odpowiedni ciężar i zajmij miejsce na ławce.
2. Obróć sztangę, aby odepnąć ją ze stojaka, i całkowicie wyprostuj ramiona. Plecy powinny być lekko wygięte, a łopatki ściągnięte. To będzie Twoja pozycja startowa.
3. Rozpocznij ruch uginając ramiona, opuszczając sztangę do klatki piersiowej.
4. Krótko się zatrzymaj, a następnie wyprostuj ramiona, wypychając ciężar z powrotem do pozycji startowej.
5. Po wykonaniu żądanej liczby powtórzeń obróć sztangę i odłóż ją na stojak.', NULL, 'free-exercise-db/Smith_Machine_Decline_Press/0.jpg', 'free_exercise_db'),
  ('smith-machine-hang-power-clean', 'Wytracenie z zawisu siłowe w maszynie Smitha', 'Smith Machine Hang Power Clean', 'motor_coach', 'intermediate', array['Siłowe', 'Dwugłowe uda'], 'Wytracenie z zawisu wykonywane w maszynie Smitha. Wybuchowe unoszenie sztangi z wysokości kolan na barki.', '1. Ustaw sztangę na wysokości kolan i załaduj odpowiednim ciężarem.
2. Chwyć sztangę nachwytem na szerokość większą niż barki i odepnij ją od maszyny. Ramiona powinny być całkowicie wyprostowane, głowa i klatka piersiowa uniesione. Łokcie skierowane na zewnątrz, barki cofnięte i opuszczone. Biodra cofnięte, napięcie przenoszone na mięśnie dwugłowe ud. To będzie Twoja pozycja startowa.
3. Rozpocznij ruch gwałtownym wyprostem bioder i kolan, przyspieszając pod sztangę. Upewnij się, że w tej fazie ruchu ramiona pozostają proste.
4. Po pełnym wyproście ponownie ugnij biodra i kolana, aby obniżyć pozycję przyjęcia.
5. Pozwól ramionom ugiąć się w tym momencie, obracając łokcie pod sztangę, aby przyjąć ją na barki.
6. Wyprostuj się w biodrach i kolanach, przyjmując pozycję stojącą ze sztangą na barkach, kończąc ruch.', NULL, 'free-exercise-db/Smith_Machine_Hang_Power_Clean/0.jpg', 'free_exercise_db'),
  ('smith-machine-hip-raise', 'Unoszenie bioder w maszynie Smitha', 'Smith Machine Hip Raise', 'motor_coach', 'beginner', array['Siłowe', 'Brzuch'], 'Ćwiczenie na dolne partie pleców i mięśnie głębokie. Leżąc na ławce, unośysz biodra, napierając stopami na sztangę.', '1. Ustaw ławkę w stojaku i załaduj sztangę odpowiednim ciężarem. Połóż się na ławce, opierając spody stóp o sztangę. Odepnij sztangę i wyprostuj nogi. Może być potrzebna pomoc rąk. Dla dodatkowej stabilności chwyć boki maszyny Smitha. To będzie Twoja pozycja startowa.
2. Rozpocznij ruch obracając miednicę i uginając kręgosłup, aby unieść biodra nad ławkę. Utrzymuj lekkie ugięcie kolan przez cały ruch.
3. Po krótkiej pauzie wróć biodrami na ławkę.
4. Powtórz żądaną liczbę powtórzeń.', NULL, 'free-exercise-db/Smith_Machine_Hip_Raise/0.jpg', 'free_exercise_db')
on conflict (slug) do nothing;

insert into public.exercises
  (slug, name, name_en, persona_type, level, categories, short_description, detail_full, common_mistakes, photo_path, source)
values
  ('smith-machine-incline-bench-press', 'Wyciskanie na ławce skośnej w maszynie Smitha', 'Smith Machine Incline Bench Press', 'motor_coach', 'beginner', array['Siłowe', 'Klatka piersiowa'], 'Wyciskanie sztangi na ławce skośnej w maszynie Smitha. Angażuje górne partie klatki piersiowej.', '1. Umieść ławkę skośną pod maszyną Smitha. Ustaw sztangę na wysokości, którą osiągniesz leżąc, z niemal całkowicie wyprostowanymi ramionami. Po wybraniu ciężaru połóż się na ławce skośnej i upewnij się, że górna część klatki piersiowej jest w linii ze sztangą. Chwytem nachwytem szerszym niż barki odepnij sztangę ze stojaka i trzymaj ją prosto nad sobą z zablokowanymi ramionami. To będzie Twoja pozycja startowa.
2. Robiąc wdech, opuszczaj się powoli, aż poczujesz sztangę na górnej części klatki piersiowej.
3. Po sekundzie pauzy wróć do pozycji startowej, robiąc wydech i wypychając sztangę mięśniami klatki piersiowej. Zablokuj ramiona w skurczu, przytrzymaj sekundę, a potem znów zacznij opuszczać powoli. Wskazówka: schodzenie powinno trwać co najmniej dwa razy dłużej niż wyciskanie w górę.
4. Powtórz ruch zalecaną liczbę powtórzeń.
5. Po zakończeniu odłóż sztangę z powrotem na stojak.', NULL, 'free-exercise-db/Smith_Machine_Incline_Bench_Press/0.jpg', 'free_exercise_db'),
  ('smith-machine-leg-press', 'Wyciskanie nogami w maszynie Smitha', 'Smith Machine Leg Press', 'motor_coach', 'intermediate', array['Siłowe', 'Uda'], 'Wyciskanie ciężaru nogami leżąc pod sztangą maszyny Smitha. Alternatywa dla klasycznego wyciskania na suwnicy.', '1. Ustaw sztangę maszyny Smitha około 60 cm nad ziemią. Upewnij się, że opiera się na zabezpieczeniach. Po załadowaniu odpowiedniego ciężaru połóż się pod sztangą. Połóż środek stóp na sztandze, przyciągając kolana do klatki piersiowej. To będzie Twoja pozycja startowa.
2. Rozpocznij ruch, odpychając się stopami, aby unieść sztangę w górę, prostując biodra i kolana. Nie blokuj kolan na górze.
3. Na szczycie ruchu krótko się zatrzymaj, po czym wróć do pozycji startowej.', NULL, 'free-exercise-db/Smith_Machine_Leg_Press/0.jpg', 'free_exercise_db'),
  ('smith-machine-one-arm-upright-row', 'Wiosłowanie po linii ud jedną ręką w maszynie Smitha', 'Smith Machine One-Arm Upright Row', 'motor_coach', 'beginner', array['Siłowe', 'Barki'], 'Wznos sztangi wzdłuż ciała jedną ręką w maszynie Smitha. Ćwiczy boczne aktony barków i czworoboczny.', '1. Przy sztandze na wysokości ud załaduj odpowiedni ciężar.
2. Złap sztangę szerokim chwytem i odepnij ciężar, zdejmując drugą dłoń ze sztangi. Ramię powinno być wyprostowane, gdy stoisz prosto z uniesioną głową i klatką piersiową. To będzie Twoja pozycja startowa.
3. Rozpocznij ruch uginając łokieć i unosząc ramię z łokciem skierowanym na zewnątrz. Kontynuuj, aż ramię będzie równoległe do podłogi.
4. Po krótkiej pauzie wróć ciężarem do pozycji startowej.
5. Powtórz żądaną liczbę powtórzeń, po czym zahacz sztangę o haczyki.', NULL, 'free-exercise-db/Smith_Machine_One-Arm_Upright_Row/0.jpg', 'free_exercise_db'),
  ('smith-machine-overhead-shoulder-press', 'Wyciskanie ponad głowę w maszynie Smitha', 'Smith Machine Overhead Shoulder Press', 'motor_coach', 'beginner', array['Siłowe', 'Barki'], 'Wyciskanie sztangi siedząc nad głowę w maszynie Smitha. Klasyczne ćwiczenie na barki z prowadnicą dla stabilności.', '1. Na początek umieść płaską ławkę (najlepiej z oparciem) pod maszyną Smitha. Ustaw sztangę na takiej wysokości, aby siedząc na płaskiej ławce musiałeś niemal całkowicie wyprostować ramiona, żeby dosięgnąć sztangi.
2. Gdy wysokość jest prawidłowa, usiądź nieco za sztangą tak, aby od czubka nosa do sztangi biegła wyobrażona prosta linia. Stopy powinny stać nieruchomo. Złap sztangę nachwytem, odepnij ją i unieś w górę, aż ramiona będą całkowicie wyprostowane. To pozycja startowa.
3. Powoli zacznij opuszczać sztangę, aż będzie na poziomie brody, robiąc wdech.
4. Następnie unoś sztangę z powrotem do pozycji startowej mięśniami barków, robiąc wydech.
5. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Smith_Machine_Overhead_Shoulder_Press/0.jpg', 'free_exercise_db'),
  ('smith-machine-pistol-squat', 'Pistolet (przysiad na jednej nodze) w maszynie Smitha', 'Smith Machine Pistol Squat', 'motor_coach', 'intermediate', array['Siłowe', 'Uda'], 'Zaawansowany przysiad na jednej nodze wykonywany w maszynie Smitha. Sztanga pomaga utrzymać równowagę podczas głębokiego przysiadu.', '1. Na początek ustaw sztangę na wysokości najlepiej dopasowanej do Twojego wzrostu. Wejdź pod nią i umieść sztangę na tylnych partiach barków.
2. Złap sztangę dłońmi skierowanymi do przodu, odepnij ją i unieś ze stojaka prostując nogi.
3. Przesuń jedną stopę do przodu, około 30 cm przed sztangę. Drugą nogę wyciągnij przed siebie, unosząc ją nad ziemię. Patrz cały czas przed siebie i utrzymuj neutralny lub lekko wygięty kręgosłup. To będzie Twoja pozycja startowa.
4. Utrzymując dobrą postawę, opuszczaj się, uginając kolano i biodro, schodząc tak nisko, na ile pozwala elastyczność.
5. Krótko się zatrzymaj na dole, a następnie wróć do pozycji startowej, odpychając się piętą i prostując kolano oraz biodro.', NULL, 'free-exercise-db/Smith_Machine_Pistol_Squat/0.jpg', 'free_exercise_db'),
  ('smith-machine-reverse-calf-raises', 'Odwrócone wspięcia na palce w maszynie Smitha', 'Smith Machine Reverse Calf Raises', 'motor_coach', 'beginner', array['Siłowe', 'Łydki'], 'Wspięcia na palce z podparciem na piętach — odwrotność klasycznych wspięć. Wzmacnia przednią część podudzi.', '1. Dostosuj wysokość sztangi w maszynie Smitha do swojego wzrostu i ustaw podwyższenie dokładnie pod sztangą.
2. Stań na platformie opierając się piętami, ze śródstopiem i palcami wystającymi poza jej krawędź. Palce skierowane do przodu, postawa na szerokość barków.
3. Teraz wsuń barki pod sztangę, zachowując opisane ustawienie stóp, i podepnij sztangę, prostując biodra i kolana, aż tułów stanie wyprostowany. Kolana powinny mieć lekki ugięcie; nigdy nie blokowane. To będzie Twoja pozycja startowa. Wskazówka: sztanga na plecach służy tylko do zachowania równowagi.
4. Unoś śródstopie i palce w górę, robiąc wydech, maksymalnie prostując stopy w kostkach i spinając łydki. Upewnij się, że kolana pozostają nieruchome przez cały czas. Nie powinno być żadnego uginania. Przytrzymaj pozycję napięcia sekundę, zanim zaczniesz schodzić.
5. Powoli wróć do pozycji startowej, robiąc wdech, opuszczając śródstopie i palce.
6. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Smith_Machine_Reverse_Calf_Raises/0.jpg', 'free_exercise_db'),
  ('smith-machine-squat', 'Przysiad w maszynie Smitha', 'Smith Machine Squat', 'motor_coach', 'beginner', array['Siłowe', 'Uda'], 'Klasyczny przysiad ze sztangą wykonywany w maszynie Smitha. Bezpieczniejsza wersja przysiadu dzięki prowadnicy.', '1. Na początek ustaw sztangę na wysokości najlepiej dopasowanej do Twojego wzrostu. Gdy wysokość jest dobrana, a sztanga załadowana, wejdź pod nią i umieść tylne partie barków (lekko poniżej szyi) na sztandze.
2. Chwyć sztangę oburącz po bokach (palce skierowane do przodu), odepnij ją i unieś ze stojaka, najpierw odpychając się nogami i jednocześnie prostując tułów.
3. Ustaw nogi na szerokość barków w średnim rozkroku, palce lekko skierowane na zewnątrz. Cały czas trzymaj głowę uniesioną i utrzymuj prosty grzbiet. To będzie Twoja pozycja startowa. (Uwaga: w tym opisie używamy średniego rozkroku, który angażuje całość; jednak możesz wybrać dowolny z trzech rozstawów opisanych w sekcji ustawienia stóp).
4. Zacznij powoli opuszczać sztangę, uginając kolana, zachowując prostą postawę z głową uniesioną. Schodź dalej, aż kąt między udem a łydką będzie nieco mniejszy niż 90 stopni (czyli moment, w którym uda znajdują się poniżej równoległości do podłogi). Wdechuj podczas tej fazy ruchu. Wskazówka: jeśli wykonałeś ćwiczenie poprawnie, przód kolan powinien tworzyć wyobrażoną linię prostą z palcami stóp, prostopadłą do frontu. Jeśli kolana przekroczą tę linię (jeśli są dalej niż palce), to nakładasz nadmierne obciążenie na kolano i ćwiczenie zostało wykonane nieprawidłowo.
5. Zacznij unoś sztangę robiąc wydech, odpychając się piętami od podłogi, prostując ponownie nogi i wracając do pozycji startowej.
6. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Smith_Machine_Squat/0.jpg', 'free_exercise_db'),
  ('smith-machine-stiff-legged-deadlift', 'Martwy ciąg na prostych nogach w maszynie Smitha', 'Smith Machine Stiff-Legged Deadlift', 'motor_coach', 'beginner', array['Siłowe', 'Dwugłowe uda'], 'Martwy ciąg na prostych nogach w maszynie Smitha. Świetne ćwiczenie na dwugłowe ud i pośladki.', '1. Na początek ustaw sztangę w maszynie Smitha na wysokości około środka ud. Gdy wysokość jest dobrana, a sztanga załadowana, złap ją nachwytem na szerokość barków. Przy dużym ciężarze mogą przydać się ochraniacze na nadgarstki.
2. Unieś sztangę całkowicie prostując ramiona, zachowując prosty grzbiet. Stań z tułowiem prosto i nogami na szerokość barków lub węższe. Kolana powinny być lekko ugięte. To pozycja startowa.
3. Trzymając kolana nieruchomo, opuść sztangę nad palce stóp, zginając się w biodrach i zachowując prosty grzbiet. Pochylaj się dalej, jakbyś chciał podnieść coś z podłogi, aż poczujesz rozciąganie w dwugłowych ud. Wydechuj podczas tego ruchu.
4. Zacznij prostować tułów jak najszybciej, gdy poczujesz rozciąganie dwugłowych ud, prostując biodra i talię, aż wrócisz do pozycji startowej. Wdechuj podczas tego ruchu.
5. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Smith_Machine_Stiff-Legged_Deadlift/0.jpg', 'free_exercise_db'),
  ('smith-machine-upright-row', 'Wiosłowanie po linii ud w maszynie Smitha', 'Smith Machine Upright Row', 'motor_coach', 'beginner', array['Siłowe', 'Czworoboczne'], 'Wznos sztangi wzdłuż ciała w maszynie Smitha. Ćwiczy boczne aktony barków i mięsień czworoboczny.', '1. Na początek ustaw sztangę w maszynie Smitha na wysokości około środka ud. Gdy wysokość jest dobrana, a sztanga załadowana, złap ją nachwytem na szerokość barków. Przy dużym ciężarze mogą przydać się ochraniacze na nadgarstki.
2. Unieś sztangę całkowicie prostując ramiona z prostym grzbietem. Łokcie powinny być lekko ugięte. To pozycja startowa.
3. Używając bocznych aktonów barków, unoś sztangę robiąc wydech. Sztanga powinna pozostawać blisko ciała podczas unoszenia. Podnoś ją, aż prawie dotknie brody. Wskazówka: to łokcie powinny prowadzić ruch. Podczas unoszenia sztangi Twoje łokcie powinny zawsze być wyżej niż przedramiona. Ponadto trzymaj tułów nieruchomo i zatrzymaj się na sekundę na szczycie ruchu.
4. Powoli opuść sztangę z powrotem do pozycji startowej. Wdechuj podczas tej fazy ruchu.
5. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Smith_Machine_Upright_Row/0.jpg', 'free_exercise_db'),
  ('smith-single-leg-split-squat', 'Wykroki bułgarskie w maszynie Smitha', 'Smith Single-Leg Split Squat', 'motor_coach', 'beginner', array['Siłowe', 'Uda'], 'Przysiad wykroczny z tylną nogą na ławce w maszynie Smitha. Intensywne ćwiczenie na nogi, szczególnie kwadriceps i pośladki.', '1. Na początek umieść płaską ławkę 60–90 cm za maszyną Smitha. Następnie ustaw sztangę na wysokości najlepiej dopasowanej do Twojego wzrostu. Gdy wysokość jest dobrana, a sztanga załadowana, wejdź pod nią i umieść tylne partie barków (lekko poniżej szyi) na sztandze.
2. Chwyć sztangę oburącz po bokach (palce skierowane do przodu), odepnij ją i unieś ze stojaka, najpierw odpychając się nogami i jednocześnie prostując tułów.
3. Ustaw nogi, przesuwając jedną stopę lekko do przodu pod sztangę, a drugą nogę wyciągając do tyłu i kładąc grzbiet stopy na ławce. To będzie Twoja pozycja startowa.
4. Zacznij powoli opuszczać sztangę, uginając kolano, zachowując prostą postawę z głową uniesioną. Schodź dalej, aż kąt między udem a łydką będzie nieco mniejszy niż 90 stopni (czyli moment, w którym uda znajdują się poniżej równoległości do podłogi). Wdechuj podczas tej fazy ruchu. Wskazówka: jeśli wykonałeś ćwiczenie poprawnie, przód kolana powinien tworzyć wyobrażoną linię prostą z palcami stopy, prostopadłą do frontu. Jeśli kolano przekroczy tę linię (jeśli jest dalej niż palce), to nakładasz nadmierne obciążenie na kolano i ćwiczenie zostało wykonane nieprawidłowo.
5. Zacznij unoś sztangę robiąc wydech, odpychając się głównie piętą od podłogi, prostując ponownie nogę i wracając do pozycji startowej.
6. Powtórz zalecaną liczbę powtórzeń.
7. Zmień nogę i powtórz ruch.', NULL, 'free-exercise-db/Smith_Single-Leg_Split_Squat/0.jpg', 'free_exercise_db'),
  ('snatch', 'Rwanie', 'Snatch', 'motor_coach', 'intermediate', array['Podnoszenie ciężarów', 'Uda'], 'Olimpijskie ćwiczenie siłowe — rwannie sztangi z ziemi nad głowę jednym ruchem. Wymaga techniki, siły i mobilności.', '1. Ustaw stopy na szerokość barków, ze sztangą leżącą bezpośrednio nad połączeniem palców stóp z resztą stopy.
2. Chwytem nadgarstkowym (dłońmi skierowanymi w dół) ugnij kolana, zachowując płaski grzbiet, i złap sztangę chwytem szerokim bardziej niż barki. Opuść biodra i upewnij się, że ciało obniża się tak, jakbyś chciał usiąść na krześle. To będzie Twoja pozycja startowa.
3. Zacznij odpychać się stopami od podłogi, jakby była ruchomą platformą, i jednocześnie zacznij unoś sztangę, trzymając ją blisko nóg.
4. Gdy sztanga osiągnie środek ud, odpychaj się nogami od podłogi i unoś ciało do pełnego wyprostu w wybuchowym ruchu.
5. Odepchnij barki w górę ruchem szrusztowania, unoś sztangę, jednocześnie wyprowadzając łokcie na boki i trzymając je nad sztangą tak długo, jak to możliwe.
6. Teraz bardzo szybkim, ale mocnym ruchem musisz przejść ciałem pod sztangę, gdy osiągnie ona wystarczająco wysoką pozycję, aby można było ją kontrolować, i opaść, blokując ramiona i trzymając sztangę nad głową, przyjmując pozycję przysiadu.
7. Zakończ ruch wstając z przysiadu, aby dokończyć podniesienie. Na końcu obie stopy powinny być w linii, a ramiona całkowicie wyprostowane, trzymające sztangę nad głową.', NULL, 'free-exercise-db/Snatch/0.jpg', 'free_exercise_db'),
  ('snatch-balance', 'Rwanie z dołem pod sztangą (snatch balance)', 'Snatch Balance', 'motor_coach', 'intermediate', array['Podnoszenie ciężarów', 'Uda'], 'Olimpijskie ćwiczenie polegające na szybkim przejściu pod sztangę do przysiadu. Sztanga startuje z barków, chwyt szeroki.', '1. Zacznij ze stopami w pozycji ciągnięcia, ze sztangą na tylnych partiach barków i dłońmi ułożonymi w szerokim chwycie do rwania.
2. Podbij sztangę nagłym dyplomem (krótkim ugięciem) i wybiciem kolan, po czym agresywnie przejdź pod sztangę, przenosząc stopy do pozycji przyjęcia.
3. Przyjmij sztangę zablokowaną nad głową blisko najniższego punktu przysiadu. Tułów powinien pozostać pionowy, opuszczając biodra między nogi.
4. Kontynuuj schodzenie do pełnej głębokości, a następnie wróć do pozycji stojącej. Ostrożnie odłóż ciężar.', NULL, 'free-exercise-db/Snatch_Balance/0.jpg', 'free_exercise_db'),
  ('snatch-deadlift', 'Martwy ciąg stylem rwania', 'Snatch Deadlift', 'motor_coach', 'intermediate', array['Podnoszenie ciężarów', 'Dwugłowe uda'], 'Martwy ciąg wykonywany szerokim chwytem, jak w rwaniu. Wzmacnia pierwszą fazę podnoszenia sztangi z ziemi.', '1. Martwy ciąg stylem rwania wzmacnia pierwszą fazę ciągu w rwaniu. Zacznij z szerokim chwytem do rwania, ze sztangą na platformie. Stopy powinny być dokładnie pod biodrami, lekko skręcone na zewnątrz. Przysiądź do sztangi, utrzymując grzbiet w absolutnym wyproście, z głową skierowaną do przodu.
2. Rozpocznij ruch odpychając się piętami i unosząc biodra. Kąt grzbietu powinien pozostać taki sam, dopóki sztanga nie minie kolan.
3. W tym momencie przebij biodra przez sztangę, odchylając się do tyłu. Wróć sztangę na platformę, odwracając ruch.', NULL, 'free-exercise-db/Snatch_Deadlift/0.jpg', 'free_exercise_db'),
  ('snatch-from-blocks', 'Rwanie z bloków', 'Snatch from Blocks', 'motor_coach', 'advanced', array['Podnoszenie ciężarów', 'Uda'], 'Wariant rwania rozpoczynany z bloków lub stojaków na określonej wysokości. Ułatwia pracę nad konkretnymi fazami ruchu.', '1. Zacznij z załadowaną sztangą na blokach lub stojakach o żądanej wysokości. Na sztandze należy przyjąć szeroki chwyt. Stopy powinny znajdować się dokładnie pod biodrami, skręcone na zewnątrz według potrzeb. Opuść biodra, z klatką piersiową uniesioną i głową patrzącą do przodu. Barki powinny być tuż przed sztangą, z łokciami skierowanymi na zewnątrz. To będzie pozycja startowa.
2. Rozpocznij pierwszą fazę ciągu odpychając się przodem pięt i unosząc sztangę z bloków.
3. Przejdziesz do drugiej fazy ciągu, prostując biodra, kolana i kostki, pchając sztangę w górę jak najszybciej. Sztanga powinna pozostawać blisko ciała. Przy szczytowym wyproście zrusztuj barki i pozwól łokciom ugiąć się na boki.
4. Przenosząc stopy do pozycji przyjęcia, gwałtownie przeciągnij się pod sztangę, unosząc ją nad głowę. Stopy powinny przesunąć się tuż poza biodra, skręcone na zewnątrz według potrzeb. Przyjmij sztangę z ciałem jak najniżej i ramionami całkowicie wyprostowanymi nad głową.
5. Utrzymując sztangę w linii nad przodem pięt, z głową i klatką piersiową uniesioną, odpychaj się piętami, aby przejść do pozycji stojącej. Ostrożnie odłóż ciężar na bloki.', NULL, 'free-exercise-db/Snatch_from_Blocks/0.jpg', 'free_exercise_db'),
  ('snatch-pull', 'Ciąg wysokim chwytem (snatch pull)', 'Snatch Pull', 'motor_coach', 'intermediate', array['Siłowe', 'Dwugłowe uda'], 'Element treningu olimpijskiego — ciąg sztangi szerokim chwytem do pełnego wyprostu. Buduje siłę i technikę rwania.', '1. Ze sztangą na podłodze blisko piszczeli złap ją szerokim chwytem do rwania. Opuść biodra z ciężarem skupionym na piętach, grzbiet prosty, głowa skierowana do przodu, klatka piersiowa uniesiona, z barkami tuż przed sztangą. To będzie Twoja pozycja startowa.
2. Rozpocznij pierwszą fazę ciągu odpychając się piętami i prostując kolana. Kąt grzbietu powinien pozostać ten sam, a ramiona wyprostowane. Przenoś ciężar kontrolowanie, aż przejdzie kolana.
3. Następnie przychodzi druga faza ciągu — główne źródło przyspieszenia. Gdy sztanga zbliża się do środka ud, zacznij prostować biodra. Ruchem wyskokowym przyspiesz, prostując biodra, kolana i kostki, używając szybkości, aby unieść sztangę w górę.
4. Nie ma potrzeby aktywnego ciągnięcia ramionami, aby przyspieszyć ciężar; na końcu drugiej fazy ciągu ciało powinno być całkowicie wyprostowane, lekko odchylone do tyłu. Pełny wyprost powinien być gwałtowny i nagły; upewnij się, że nie przedłużasz wyprostu dłużej, niż to konieczne.', NULL, 'free-exercise-db/Snatch_Pull/0.jpg', 'free_exercise_db'),
  ('snatch-shrug', 'Szrusztowanie szerokim chwytem', 'Snatch Shrug', 'motor_coach', 'intermediate', array['Podnoszenie ciężarów', 'Czworoboczne'], 'Unoszenie barków (szruszt) szerokim chwytem do rwania. Wykonywane z zawisu, na wysokości środka ud.', '1. Zacznij z szerokim chwytem, ze sztangą zwisającą na wysokości środka ud. Możesz użyć chwytu haka lub nachwytu. Grzbiet powinien być prosty i lekko pochylony do przodu.
2. Unoś barki w kierunku uszu. Choć to ćwiczenie zwykle można obciążać większym ciężarem niż rwannię, unikaj przeciążenia do punktu, w którym spowalnia wykonanie.', NULL, 'free-exercise-db/Snatch_Shrug/0.jpg', 'free_exercise_db'),
  ('speed-band-overhead-triceps', 'Szybkie prostowanie ramion z gumą nad głową', 'Speed Band Overhead Triceps', 'motor_coach', 'beginner', array['Siłowe', 'Triceps'], 'Prostowanie ramion z gumą oporową zakotwiczoną nisko. Skupia się na eksplozywnym prostowaniu łokci.', '1. Do tego ćwiczenia zamocuj gumę do podłogi. Użyliśmy ławki skośnej i zamocowaliśmy gumę do jej podstawy, stojąc nad ławką. Alternatywnie można to wykonać stojąc na gumie.
2. Na początek przeciągnij gumę za głowę, trzymając ją nachwytem z uniesionymi łokciami. To będzie Twoja pozycja startowa.
3. Aby wykonać ruch, prostuj łokieć, aż ramiona będą wyprostowane, dbając o to, aby górna część ramienia pozostawała w miejscu.
4. Zatrzymaj się, a następnie wróć do pozycji startowej.', NULL, 'free-exercise-db/Speed_Band_Overhead_Triceps/0.jpg', 'free_exercise_db'),
  ('speed-box-squat', 'Szybki przysiad na skrzyni', 'Speed Box Squat', 'motor_coach', 'intermediate', array['Trójbój', 'Uda'], 'Przysiad na skrzyni wykonywany z maksymalną szybkością, często z gumami. Rozwija mocną siłę wybuchową nóg.', '1. Zamocuj gumy do sztangi, pewnie zakotwiczone blisko podłogi. Może być konieczne skrócenie gum, aby uzyskać odpowiednie napięcie.
2. Użyj skrzyni o odpowiedniej wysokości do tego ćwiczenia. Załaduj sztangę ciężarem, który wymaga wysiłku, ale nie jest tak ciężki, aby kompromitował szybkość. Zazwyczaj będzie to 50–70% Twojego maksimum na jedno powtórzenie.
3. Umieść sztangę na górnych partiach pleców, łopatki ściągnięte, grzbiet wygięty, wszystko spięte od głowy do stóp. To będzie pozycja startowa.
4. Zdejmij sztangę ze stojaka i ustaw się przed skrzynią. Siadaj biodermi do tyłu, aż usiądziesz na skrzyni, dbając o kontrolowane opuszczanie i nie wpadanie na powierzchnię.
5. Krótko się zatrzymaj, a następnie wybuchnij ze skrzyni, prostując biodra i kolana.', NULL, 'free-exercise-db/Speed_Box_Squat/0.jpg', 'free_exercise_db'),
  ('speed-squats', 'Szybkie przysiady', 'Speed Squats', 'motor_coach', 'advanced', array['Siłowe', 'Uda'], 'Przysiady ze sztangą wykonywane z maksymalną szybkością koncentryczną. Buduje moc bez utraty techniki.', '1. To ćwiczenie najlepiej wykonywać w stojaku do przysiadów dla bezpieczeństwa. Na początek ustaw sztangę na stojaku dopasowanym do Twojego wzrostu. Gdy wysokość jest dobrana, a sztanga załadowana, wejdź pod nią i umieść tylne partie barków (lekko poniżej szyi) na sztandze.
2. Chwyć sztangę oburącz po bokach i unieś ją ze stojaka, najpierw odpychając się nogami i jednocześnie prostując tułów.
3. Oddal się od stojaka i ustaw nogi na szerokość barków w średnim rozkroku, palce lekko skierowane na zewnątrz. Trzymaj głowę uniesioną, ponieważ patrzenie w dół zaburzy równowagę, oraz utrzymuj prosty grzbiet. To będzie Twoja pozycja startowa. (Uwaga: w tym opisie używamy średniego rozkroku, który angażuje całość; jednak możesz wybrać dowolny z trzech rozstawów opisanych w sekcji ustawienia stóp).
4. Zacznij opuszczać sztangę, uginając kolana, zachowując prostą postawę z głową uniesioną. Schodź dalej, aż kąt między udem a łydką będzie nieco mniejszy niż 90 stopni (czyli moment, w którym uda znajdują się poniżej równoległości do podłogi). Wdechuj podczas tej fazy ruchu. Wskazówka: jeśli wykonałeś ćwiczenie poprawnie, przód kolan powinien tworzyć wyobrażoną linię prostą z palcami stóp, prostopadłą do frontu. Jeśli kolana przekroczą tę linię (jeśli są dalej niż palce), to nakładasz nadmierne obciążenie na kolano i ćwiczenie zostało wykonane nieprawidłowo.
5. Zacznij unoś sztangę jak najszybciej, bez angażowania rozpędu, robiąc wydech, odpychając się głównie piętami od podłogi, prostując ponownie nogi i wracając do pozycji startowej. Uwaga: te ćwiczenia należy wykonywać jak najszybciej, ale bez psucia idealnej techniki i bez angażowania rozpędu.
6. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Speed_Squats/0.jpg', 'free_exercise_db'),
  ('spell-caster', 'Zaklinacz - rotacje z hantlami', 'Spell Caster', 'motor_coach', 'beginner', array['Siłowe', 'Brzuch'], 'Dynamiczne ćwiczenie na mięśnie skośne brzucha. Trzymając hantle, obracasz tułów z boku na bok.', '1. Trzymaj hantel w każdej dłoni chwytem nachwytem. Stopy szeroko, biodra i kolana wyprostowane. To będzie Twoja pozycja startowa.
2. Rozpocznij ruch przyciągając oba hantle na jedną stronę, obok biodra, obracając tułów.
3. Utrzymując ramiona proste, a hantle równoległe do podłogi, obróć tułów, przenosząc ciężary na przeciwną stronę.
4. Kontynuuj naprzemiennie, obracając się z jednej strony na drugą, aż seria zostanie zakończona.', NULL, 'free-exercise-db/Spell_Caster/0.jpg', 'free_exercise_db'),
  ('spider-crawl', 'Czołganie pająka', 'Spider Crawl', 'motor_coach', 'beginner', array['Siłowe', 'Brzuch'], 'Mobilizacja bioder w podporze przodem. Przyciągasz kolano w kierunku łokcia, angażując mięśnie głębokie.', '1. Zacznij w podporze przodem na podłodze. Podpieraj się na dłoniach i palcach stóp, ze stopami razem i ciałem wyprostowanym. Ramiona powinny być ugięte do 90 stopni. To będzie Twoja pozycja startowa.
2. Rozpocznij ruch unosząc jedną stopę nad ziemię. Obróć nogę na zewnątrz i przyciągnij kolano w kierunku łokcia, jak najdalej do przodu.
3. Wróć nogę do pozycji startowej i powtórz drugą stroną.', NULL, 'free-exercise-db/Spider_Crawl/0.jpg', 'free_exercise_db'),
  ('spider-curl', 'Uginanie ramion na spiderze', 'Spider Curl', 'motor_coach', 'beginner', array['Siłowe', 'Biceps'], 'Uginanie ramion ze sztangą na ławce skośnej twarzą w dół. Maksymalnie izoluje bicepsy.', '1. Zacznij od ustawienia sztangi na części ławki Scotta, na której normalnie się siada. Upewnij się, że sztanga jest dobrze wyśrodkowana, aby była wyważona i nie spadła.
2. Przejdź na przednią stronę ławki Scotta (tam, gdzie zwykle kładzie się ramiona) i ustaw się tak, aby leżeć pod kątem 45 stopni, z tułowiem i brzuchem dociśniętymi do przedniej strony ławki.
3. Upewnij się, że stopy (szczególnie palce) są dobrze ustawione na podłodze, i połóż górne partie ramion na poduszce znajdującej się na wewnętrznej stronie ławki Scotta.
4. Złap sztangę podchwytem (palce skierowane w górę) mniej więcej na szerokość barków lub nieco węższe.
5. Powoli zacznij unoś sztangę w górę, robiąc wydech. Przytrzymaj pozycję napięcia przez sekundę, spinając bicepsy.
6. Powoli zacznij opuszczać sztangę z powrotem do pozycji startowej, robiąc wdech.
7. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Spider_Curl/0.jpg', 'free_exercise_db'),
  ('spinal-stretch', 'Rozciąganie kręgosłupa na krześle', 'Spinal Stretch', 'motor_coach', 'beginner', array['Rozciąganie', 'Środek pleców'], 'Rozciąganie kręgosłupa wykonywane siedząc na krześle. Skręcasz tułów i pochylasz się, dotykając łokciem podłogi przy kolanie.', '1. Usiądź na krześle tak, aby grzbiet był prosty, a stopy opierały się o podłogę.
2. Spleć palce za głową, łokcie na zewnątrz, broda opuszczona.
3. Skręć górną część tułowia na jedną stronę około 3 razy, tak daleko, jak możesz. Potem pochyl się do przodu i skręć tułów, aby dosięgnąć łokciem podłogi po wewnętrznej stronie kolana.
4. Wróć do pozycji pionowej, a następnie powtórz na drugą stronę.', NULL, 'free-exercise-db/Spinal_Stretch/0.jpg', 'free_exercise_db'),
  ('split-clean', 'Wytracenie z wyrzutem nóg (split clean)', 'Split Clean', 'motor_coach', 'intermediate', array['Podnoszenie ciężarów', 'Uda'], 'Wariant wytracenia z przyjęciem sztangi w rozkroku - jedna noga z przodu, druga z tyłu. Wymaga dobrej techniki olimpijskiej.', '1. Ze sztangą na podłodze blisko piszczeli złap ją nachwytem tuż poza nogami. Opuść biodra z ciężarem skupionym na piętach, grzbiet prosty, głowa skierowana do przodu, klatka piersiowa uniesiona, z barkami tuż przed sztangą. To będzie Twoja pozycja startowa.
2. Rozpocznij pierwszą fazę ciągu odpychając się piętami i prostując kolana. Kąt grzbietu powinien pozostać ten sam, a ramiona wyprostowane. Przenoś ciężar kontrolowanie, aż przejdzie kolana.
3. Następnie przychodzi druga faza ciągu - główne źródło przyspieszenia w wytraceniu. Gdy sztanga zbliża się do środka ud, zacznij prostować biodra. Ruchem wyskokowym przyspiesz, prostując biodra, kolana i kostki, używając szybkości, aby unieść sztangę w górę. Nie ma potrzeby aktywnego ciągnięcia ramionami, aby przyspieszyć ciężar; na końcu drugiej fazy ciągu ciało powinno być całkowicie wyprostowane, lekko odchylone do tyłu, z ramionami wciąż wyprostowanymi.
4. Gdy osiągnięty zostanie pełny wyprost, przejdź do trzeciej fazy ciągu, agresywnie szrusztując barkami i uginając ramiona z łokciami uniesionymi i skierowanymi na zewnątrz. Przy szczytowym wyproście agresywnie przeciągnij się w dół, obracając łokcie pod sztangę.
5. Przyjmij sztangę w rozkroku, gwałtownie przenosząc jedną stopę do przodu, a drugą do tyłu. Sztanga powinna zostać przyjęta na wysunięte barki, lekko dotykając gardła, z rozluźnionymi dłońmi. Kontynuuj schodzenie do najniższej pozycji, co pomoże w powrocie do stania.
6. Natychmiast wróć do stania odpychając się piętami, z tułowiem pionowym i łokciami uniesionymi. Zbliż stopy, wstając.', NULL, 'free-exercise-db/Split_Clean/0.jpg', 'free_exercise_db'),
  ('split-jerk', 'Wytracenie z wyrzutem nóg (split jerk)', 'Split Jerk', 'motor_coach', 'intermediate', array['Podnoszenie ciężarów', 'Uda'], 'Olimpijskie wyciskanie sztangi nad głowę z wyrzutem nóg w rozkrok. Szybkie przejście pod sztangę i wyprost ramion.', '1. Stojąc ze sztangą na przednich partiach barków, zacznij od dyploma (krótkiego ugięcia kolan). Ze stopami dokładnie pod biodrami ugnij kolana, nie cofając bioder do tyłu.
2. Schodź tylko nieznacznie, a następnie odwróć ruch jak najmocniej. Odepchnij się piętami, generując jak największą szybkość i siłę, i pamiętaj, aby usunąć głowę z drogi, gdy sztanga opuszcza barki. W tym momencie, gdy stopy odrywają się od podłogi, muszą być przeniesione do pozycji przyjęcia tak szybko, jak to możliwe.
3. W krótkiej chwili, gdy stopy nie odpychają aktywnie od podłoża, wysiłek zawodnika wypychający sztangę w górę pociągnie go w dół. Stopy powinny być przeniesione do rozkroku - jedna stopa z przodu, druga z tyłu, z częściowo ugiętymi kolanami. Przyjmij sztangę z zablokowanymi ramionami nad głową.
4. Wróć do pozycji stojącej, zbliżając stopy.', NULL, 'free-exercise-db/Split_Jerk/0.jpg', 'free_exercise_db'),
  ('split-jump', 'Wykroki z wyskokiem', 'Split Jump', 'motor_coach', 'beginner', array['Plyometryka', 'Uda'], 'Dynamiczne ćwiczenie plyometryczne - wyskok z pozycji wykroku. Naprzemiennie zmieniasz nogi w powietrzu.', '1. Przyjmij pozycję wykroku z jedną stopą z przodu, ugiętym kolanem, i kolanem tylnym prawie dotykającym ziemi.
2. Upewnij się, że przednie kolano znajduje się nad linią środkową stopy.
3. Prostując obie nogi, wyskocz jak najwyżej, machając ramionami dla dodatkowego wybicia.
4. Podczas skoku zbliż stopy do siebie, a przy lądowaniu przenieś je z powrotem do pozycji wyjściowych.
5. Amortyzuj uderzenie wracając do pozycji startowej.', NULL, 'free-exercise-db/Split_Jump/0.jpg', 'free_exercise_db'),
  ('split-snatch', 'Rwanie z wyrzutem nóg (split snatch)', 'Split Snatch', 'motor_coach', 'advanced', array['Podnoszenie ciężarów', 'Dwugłowe uda'], 'Wariant rwania z przyjęciem sztangi w rozkroku nóg. Połączenie rwania i split jerka.', '1. Zacznij z załadowaną sztangą na podłodze. Sztanga powinna być blisko lub dotykać piszczeli, a na sztandze należy przyjąć szeroki chwyt. Stopy powinny znajdować się dokładnie pod biodrami, skręcone na zewnątrz według potrzeb. Opuść biodra, z klatką piersiową uniesioną i głową patrzącą do przodu. Barki powinny być tuż przed sztangą. To będzie pozycja startowa.
2. Rozpocznij pierwszą fazę ciągu odpychając się przodem pięt i unosząc sztangę z ziemi. Kąt grzbietu powinien pozostać taki sam, dopóki sztanga nie minie kolan.
3. Przejdziesz do drugiej fazy ciągu, prostując biodra, kolana i kostki, pchając sztangę w górę jak najszybciej. Sztanga powinna pozostawać blisko ciała. Przy szczytowym wyproście zrusztuj barki i pozwól łokciom ugiąć się na boki.
4. Przenosząc stopy do pozycji przyjęcia, gwałtownie przeciągnij się pod sztangę, unosząc ją nad głowę. Stopy powinny gwałtownie przejść do rozkroku - jedna stopa do przodu, druga do tyłu. Przyjmij sztangę z ciałem jak najniżej i ramionami całkowicie wyprostowanymi nad głową.
5. Utrzymując sztangę w linii nad przodem pięt, z głową i klatką piersiową uniesioną, odpychaj się piętami, aby przejść do pozycji stojącej, zbliżając stopy.
6. Ostrożnie odłóż ciężar na podłogę.', NULL, 'free-exercise-db/Split_Snatch/0.jpg', 'free_exercise_db'),
  ('split-squat-with-dumbbells', 'Przysiad wykroczny z hantlami', 'Split Squat with Dumbbells', 'motor_coach', 'beginner', array['Siłowe', 'Uda'], 'Przysiad w wykroku z tylną nogą na podwyższeniu i hantlami w dłoniach. Wzmacnia kwadricepsy i pośladki.', '1. Ustaw się w rozkroku z tylną nogą na podwyższeniu i przednią nogą z przodu.
2. Trzymaj hantel w każdej dłoni, pozwalając im swobodnie zwisać po bokach. To będzie Twoja pozycja startowa.
3. Zacznij od schodzenia, uginając kolano i biodro, aby opuścić ciało w dół. Utrzymuj dobrą postawę przez cały ruch. Trzymaj przednie kolano w linii ze stopą podczas ćwiczenia.
4. Na dole ruchu odepchnij się piętą, prostując kolano i biodro, aby wrócić do pozycji startowej.', NULL, 'free-exercise-db/Split_Squat_with_Dumbbells/0.jpg', 'free_exercise_db'),
  ('split-squats', 'Wykroki z przysiadem (skoki rozkoczne)', 'Split Squats', 'motor_coach', 'intermediate', array['Rozciąganie', 'Dwugłowe uda'], 'Dynamiczne ćwiczenie - skok do rozkroku z ugięciem kolan, a potem natychmiastowy wyskok ze zmianą nóg.', '1. Zacznij w pozycji stojącej. Wyskocz do rozkroku - jedna noga z przodu, druga z tyłu - uginając kolana i lekko opuszczając biodra.
2. Podczas schodzenia natychmiast odwróć kierunek ruchu, prostując się i wyskakując, zmieniając pozycję nóg. Powtórz 5-10 razy na każdą nogę.', NULL, 'free-exercise-db/Split_Squats/0.jpg', 'free_exercise_db'),
  ('squat-jerk', 'Wytracenie z dołem w przysiad (squat jerk)', 'Squat Jerk', 'motor_coach', 'advanced', array['Siłowe', 'Uda'], 'Wariant wytracenia z przyjęciem sztangi w przysiadzie. Wymaga doskonałej mobilności i szybkości.', '1. Stojąc ze sztangą na przednich partiach barków, zacznij od dyploma (krótkiego ugięcia kolan). Ze stopami dokładnie pod biodrami ugnij kolana, nie cofając bioder do tyłu. Schodź tylko nieznacznie, a następnie odwróć ruch jak najmocniej. Odepchnij się piętami, generując jak największą szybkość i siłę, i pamiętaj, aby usunąć głowę z drogi, gdy sztanga opuszcza barki.
2. W tym momencie, gdy stopy odrywają się od podłogi, muszą być przeniesione do pozycji przyjęcia tak szybko, jak to możliwe. W krótkiej chwili, gdy stopy nie odpychają aktywnie od podłoża, wysiłek zawodnika wypychający sztangę w górę pociągnie go w dół. Stopy powinny gwałtownie przejść tuż poza biodra, skręcone na zewnątrz według potrzeb. Przyjmij sztangę z ciałem w pełnym przysiadzie i ramionami całkowicie wyprostowanymi nad głową.
3. Utrzymując sztangę w linii nad przodem pięt, z głową i klatką piersiową uniesioną, odpychaj się piętami, aby przejść do pozycji stojącej. Ostrożnie odłóż ciężar na podłogę.', NULL, 'free-exercise-db/Squat_Jerk/0.jpg', 'free_exercise_db'),
  ('squat-with-bands', 'Przysiad z gumami', 'Squat with Bands', 'motor_coach', 'intermediate', array['Trójbój', 'Uda'], 'Przysiad ze sztangą obciążaną dodatkowo gumami oporowymi. Opór rośnie wraz z prostowaniem nóg.', '1. Zamocuj gumy na tulejach sztangi, przymocowane do kołków, stojaka lub hantli, tak aby napięcie było odpowiednie.
2. Zacznij od wejścia pod sztangę i umieszczenia jej na tylnych partiach barków. Ściągnij łopatki i obróć łokcie do przodu, próbując zgiąć sztangę na barkach. Zdejmij sztangę ze stojaka, tworząc mocne wygięcie w odcinku lędźwiowym, i zrób krok w tył do pozycji. Ustaw stopy szeroko dla większego nacisku na plecy, pośladki, przywodziciele i dwugłowe ud. Głowa skierowana do przodu.
3. Z plecami, barkami i mięśniami głębokimi spiętymi, wypychaj kolana i pośladki na zewnątrz, rozpoczynając zejście. Siadaj biodrami jak najdalej do tyłu. Idealnie piszczele powinny być prostopadłe do ziemi. Niższe ustawienie sztangi wymaga większego pochylenia tułowia, aby utrzymać sztangę nad piętami. Kontynuuj, aż przekroczysz równoległość, czyli moment, w którym fałd biodra znajduje się w linii z górną krawędzią kolana.
4. Utrzymując ciężar na piętach i wypychając stopy i kolana na zewnątrz, pchaj w górę, prowadząc ruch głową. Kontynuuj w górę, zachowując spięcie od głowy do stóp, aż wrócisz do pozycji startowej.', NULL, 'free-exercise-db/Squat_with_Bands/0.jpg', 'free_exercise_db'),
  ('squat-with-chains', 'Przysiad z łańcuchami', 'Squat with Chains', 'motor_coach', 'intermediate', array['Trójbój', 'Uda'], 'Przysiad ze sztangą obciążaną łańcuchami. Podobnie jak z gumami - opór rośnie w miarę prostowania nóg.', '1. Aby zamocować łańcuchy, zacznij od przełożenia łańcucha głównego przez tuleje sztangi. Ciężki łańcuch powinien być przymocowany karabińczykiem. Dostosuj długość łańcucha głównego tak, aby kilka ogniw pozostawało na podłodze w najwyższym punkcie ruchu.
2. Zacznij od wejścia pod sztangę i umieszczenia jej na tylnych partiach barków. Ściągnij łopatki i obróć łokcie do przodu, próbując zgiąć sztangę na barkach. Zdejmij sztangę ze stojaka, tworząc mocne wygięcie w odcinku lędźwiowym, i zrób krok w tył do pozycji. Ustaw stopy szeroko dla większego nacisku na plecy, pośladki, przywodziciele i dwugłowe ud. Głowa skierowana do przodu.
3. Z plecami, barkami i mięśniami głębokimi spiętymi, wypychaj kolana i pośladki na zewnątrz, rozpoczynając zejście. Siadaj biodrami jak najdalej do tyłu. Idealnie piszczele powinny być prostopadłe do ziemi. Niższe ustawienie sztangi wymaga większego pochylenia tułowia, aby utrzymać sztangę nad piętami. Kontynuuj, aż przekroczysz równoległość, czyli moment, w którym fałd biodra znajduje się w linii z górną krawędzią kolana.
4. Utrzymując ciężar na piętach i wypychając stopy i kolana na zewnątrz, pchaj w górę, prowadząc ruch głową. Kontynuuj w górę, zachowując spięcie od głowy do stóp, aż wrócisz do pozycji startowej.', NULL, 'free-exercise-db/Squat_with_Chains/0.jpg', 'free_exercise_db'),
  ('squat-with-plate-movers', 'Przysiad z przesuwaniem talerza', 'Squat with Plate Movers', 'motor_coach', 'intermediate', array['Siłowe', 'Uda'], 'Przysiad z jedną stopą na talerzu, połączony z przesuwaniem talerza stopą między powtórzeniami.', '1. Na początek ustaw sztangę na stojaku tuż poniżej wysokości barków. Połóż talerz od sztangi na podłodze około 60 cm za stojakiem. Gdy sztanga jest załadowana, wejdź pod nią i umieść tylne partie barków na sztandze.
2. Chwyć sztangę oburącz i unieś ją ze stojaka, najpierw odpychając się nogami i jednocześnie prostując tułów.
3. Oddal się od stojaka i przyjmij szeroką postawę z palcami lekko skierowanymi na zewnątrz, jedną stopą na talerzu. Cały czas trzymaj głowę uniesioną. To będzie Twoja pozycja startowa.
4. Zacznij powoli opuszczać sztangę, uginając kolana i biodra. Schodź dalej, aż kąt między udem a łydką będzie nieco mniejszy niż 90 stopni.
5. Unoś sztangę robiąc wydech, odpychając się piętami od podłogi, prostując biodra i kolana.
6. Na szczycie ruchu zrób krok w bok, zbliżając stopy po przeciwnej stronie talerza.
7. Stopą wewnętrzną odpychaj talerz, przesuwając go po podłodze na miejsce, gdzie właśnie stałeś.
8. Połóż wewnętrzną stopę na talerzu, przyjmując szeroką postawę do następnego powtórzenia.', NULL, 'free-exercise-db/Squat_with_Plate_Movers/0.jpg', 'free_exercise_db'),
  ('squats-with-bands', 'Przysiady z gumą', 'Squats - With Bands', 'motor_coach', 'beginner', array['Siłowe', 'Uda'], 'Przysiady z gumą oporową trzymaną oburącz przy twarzy. Guma zwiększa opór w miarę prostowania nóg.', '1. Na początek upewnij się, że guma ćwiczebna jest równomiernie rozłożona między lewą i prawą stroną ciała. Aby to zrobić, chwyć oba końce gumy dłońmi i połóż obie stopy na środku gumy. Stopy powinny być rozstawione na szerokość barków.
2. Trzymając gumy, powinny one być na tej samej wysokości po obu stronach. Chwyt powinien być nachwytem (palce skierowane do przodu), a uchwyty gumy przy twarzy. To pozycja startowa.
3. Powoli zacznij uginac kolana i opuszczać nogi, aż uda będą równoległe do podłogi, robiąc wdech.
4. Odepchnij się piętami, aby wrócić ciałem do pozycji startowej, robiąc wydech.
5. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Squats_-_With_Bands/0.jpg', 'free_exercise_db'),
  ('stairmaster', 'Stepper schodowy (schody)', 'Stairmaster', 'motor_coach', 'intermediate', array['Cardio', 'Uda'], 'Trening cardio na symulatorze schodów. Symuluje wchodzenie po schodach, wzmacniając nogi i spalając kalorie.', '1. Na początek wejdź na stepper i wybierz żądaną opcję z menu. Możesz wybrać ustawienie ręczne albo program. Zazwyczaj możesz wprowadzić swój wiek i wagę, aby oszacować liczbę spalonych kalorii podczas ćwiczeń.
2. Pompuj nogi w górę i w dół w ustalonym rytmie, dociskając pedały w dół, ale nie do samego końca. Zaleca się utrzymywanie chwytu uchwytów, aby nie upaść. Uchwyty mogą służyć do monitorowania tętna, co pomaga utrzymać odpowiednią intensywność.
3. Steppery oferują wygodę i korzyści sercowo-naczyniowe, a zazwyczaj mają mniejszy wpływ na stawy niż bieganie na zewnątrz. Są zazwyczaj znacznie trudniejsze niż inne urządzenia cardio. Osoba ważąca 68 kg spala zazwyczaj ponad 300 kcal w 30 minut, w porównaniu z około 175 kcal przy marszu.', NULL, 'free-exercise-db/Stairmaster/0.jpg', 'free_exercise_db'),
  ('standing-alternating-dumbbell-press', 'Wyciskanie hantli naprzemiennie na stojąco', 'Standing Alternating Dumbbell Press', 'motor_coach', 'beginner', array['Siłowe', 'Barki'], 'Wyciskanie hantli ponad głowę naprzemiennie każdą ręką na stojąco. Wzmacnia barki i mięśnie głębokie.', '1. Stań z hantlem w każdej dłoni. Unoś hantle do barków z dłońmi skierowanymi do przodu i łokciami skierowanymi na zewnątrz. To będzie Twoja pozycja startowa.
2. Wyprostuj jedno ramię, wyciskając hantel prosto w górę, trzymając drugą dłoń w miejscu. Nie pochylaj się ani nie szarp ciężarem podczas ruchu.
3. Po krótkiej pauzie wróć ciężarem do pozycji startowej.
4. Powtórz drugą stroną, kontynuując naprzemiennie oboma ramionami.', NULL, 'free-exercise-db/Standing_Alternating_Dumbbell_Press/0.jpg', 'free_exercise_db'),
  ('standing-barbell-calf-raise', 'Wspięcia na palce ze sztangą na stojąco', 'Standing Barbell Calf Raise', 'motor_coach', 'beginner', array['Siłowe', 'Łydki'], 'Wspięcia na palce ze sztangą na plecach. Klasyczne ćwiczenie na łydki wykonywane w stojaku do przysiadów.', '1. To ćwiczenie najlepiej wykonywać w stojaku do przysiadów dla bezpieczeństwa. Na początek ustaw sztangę na stojaku dopasowanym do Twojego wzrostu. Gdy wysokość jest dobrana, a sztanga załadowana, wejdź pod nią i połóż sztangę na tylnych partiach barków (lekko poniżej szyi).
2. Chwyć sztangę oburącz po bokach i unieś ją ze stojaka, najpierw odpychając się nogami i jednocześnie prostując tułów.
3. Oddal się od stojaka i ustaw nogi na szerokość barków w średnim rozkroku, palce lekko skierowane na zewnątrz. Trzymaj głowę uniesioną, ponieważ patrzenie w dół zaburzy równowagę, oraz utrzymuj prosty grzbiet. Kolana powinny mieć lekki ugięcie; nigdy nie blokowane. To będzie Twoja pozycja startowa. Wskazówka: dla lepszego zakresu ruchu możesz też położyć śródstopie na drewnianym bloku, ale bądź ostrożny, ponieważ ta opcja wymaga więcej równowagi i solidnego bloku.
4. Unoś pięty robiąc wydech, maksymalnie prostując kostki i spinając łydki. Upewnij się, że kolano pozostaje nieruchome przez cały czas. Nie powinno być żadnego uginania. Przytrzymaj pozycję napięcia sekundę, zanim zaczniesz schodzić w dół.
5. Powoli wróć do pozycji startowej, robiąc wdech, opuszczając pięty i uginając kostki, aż łydki zostaną rozciągnięte.
6. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Standing_Barbell_Calf_Raise/0.jpg', 'free_exercise_db'),
  ('standing-barbell-press-behind-neck', 'Wyciskanie sztangi zza karku na stojąco', 'Standing Barbell Press Behind Neck', 'motor_coach', 'intermediate', array['Siłowe', 'Barki'], 'Wyciskanie sztangi zza karku ponad głowę. Zaawansowane ćwiczenie na barki wymagające dobrej mobilności.', '1. To ćwiczenie najlepiej wykonywać w stojaku do przysiadów dla łatwiejszego podniesienia sztangi. Na początek ustaw sztangę na stojaku dopasowanym do Twojego wzrostu. Gdy wysokość jest dobrana, a sztanga załadowana, wejdź pod nią i umieść tylne partie barków (lekko poniżej szyi) na sztandze.
2. Chwyć sztangę oburącz po bokach i unieś ją ze stojaka, najpierw odpychając się nogami i jednocześnie prostując tułów.
3. Oddal się od stojaka i ustaw nogi na szerokość barków w średnim rozkroku, palce lekko skierowane na zewnątrz. Grzbiet powinien pozostać prosty podczas wykonywania tego ćwiczenia. To będzie Twoja pozycja startowa.
4. Unoś sztangę ponad głowę całkowicie prostując ramiona, robiąc wydech.
5. Przytrzymaj napięcie sekundę i opuść sztangę z powrotem do pozycji startowej, robiąc wdech.
6. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Standing_Barbell_Press_Behind_Neck/0.jpg', 'free_exercise_db'),
  ('standing-bent-over-one-arm-dumbbell-triceps-extension', 'Prostowanie ramienia z hantlem w opadzie', 'Standing Bent-Over One-Arm Dumbbell Triceps Extension', 'motor_coach', 'beginner', array['Siłowe', 'Triceps'], 'Triceps w opadzie - prostowanie jednego ramienia z hantlem za plecami. Izoluje triceps.', '1. Z hantlem w jednej dłoni i dłonią zwróconą w stronę tułowia lekko ugnij kolana i pochyl tułów do przodu, zginając się w biodrach, zachowując prosty grzbiet, aż będzie prawie równoległy do podłogi. Pamiętaj, aby trzymać głowę uniesioną.
2. Górna część ramienia powinna być blisko tułowia i równoległa do podłogi, a przedramię skierowane w dół, gdy dłoń trzyma ciężar. Wskazówka: między przedramieniem a ramieniem powinien być kąt 90 stopni. To Twoja pozycja startowa.
3. Utrzymując górne partie ramion nieruchomo, użyj tricepsa, aby unoś ciężar robiąc wydech, aż przedramię będzie równoległe do podłogi, a całe ramię wyprostowane. Podobnie jak w wielu innych ćwiczeniach na ramiona, porusza się tylko przedramię.
4. Po sekundzie napięcia na górze powoli opuść hantel z powrotem do pozycji startowej, robiąc wdech.
5. Powtórz ruch zalecaną liczbę powtórzeń.
6. Zmień ramię i powtórz ćwiczenie.', NULL, 'free-exercise-db/Standing_Bent-Over_One-Arm_Dumbbell_Triceps_Extension/0.jpg', 'free_exercise_db'),
  ('standing-bent-over-two-arm-dumbbell-triceps-extension', 'Prostowanie obu ramion z hantlami w opadzie', 'Standing Bent-Over Two-Arm Dumbbell Triceps Extension', 'motor_coach', 'beginner', array['Siłowe', 'Triceps'], 'Triceps w opadzie - prostowanie obu ramion z hantlami. Wzmacnia tylną część ramion.', '1. Z hantlem w każdej dłoni i dłońmi zwróconymi w stronę tułowia lekko ugnij kolana i pochyl tułów do przodu, zginając się w biodrach, zachowując prosty grzbiet, aż będzie prawie równoległy do podłogi. Pamiętaj, aby trzymać głowę uniesioną. Górne partie ramion powinny być blisko tułowia i równoległe do podłogi, a przedramiona skierowane w dół, gdy dłonie trzymają ciężary. Wskazówka: między przedramionami a ramionami powinien być kąt 90 stopni. To Twoja pozycja startowa.
2. Utrzymując górne partie ramion nieruchomo, użyj tricepsów, aby unoś ciężary robiąc wydech, aż przedramiona będą równoległe do podłogi, a całe ramiona wyprostowane. Podobnie jak w wielu innych ćwiczeniach na ramiona, poruszają się tylko przedramiona.
3. Po sekundzie napięcia na górze powoli opuść hantle z powrotem do pozycji startowej, robiąc wdech.
4. Powtórz ruch zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Standing_Bent-Over_Two-Arm_Dumbbell_Triceps_Extension/0.jpg', 'free_exercise_db'),
  ('standing-biceps-cable-curl', 'Uginanie ramion na wyciągu dolnym na stojąco', 'Standing Biceps Cable Curl', 'motor_coach', 'beginner', array['Siłowe', 'Biceps'], 'Uginanie ramion z gryfem wyciągu dolnego. Izoluje bicepsy przy stałym napięciu linki przez cały ruch.', '1. Stań prosto z tułowiem wyprostowanym, trzymając gryf do uginania przymocowany do dolnego bloczka. Złap gryf na szerokość barków i trzymaj łokcie blisko tułowia. Dłonie powinny być skierowane w górę (chwyt podchwytem). To będzie Twoja pozycja startowa.
2. Utrzymując górne partie ramion nieruchomo, uginaj ramiona, spinając bicepsy, robiąc wydech. Poruszać powinny się tylko przedramiona. Kontynuuj ruch, aż bicepsy będą całkowicie spięte, a gryf na wysokości barków. Przytrzymaj pozycję napięcia sekundę, spinając mięsień.
3. Powoli zacznij wracać gryfem do pozycji startowej, robiąc wdech.
4. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Standing_Biceps_Cable_Curl/0.jpg', 'free_exercise_db'),
  ('standing-biceps-stretch', 'Rozciąganie bicepsów na stojąco', 'Standing Biceps Stretch', 'motor_coach', 'beginner', array['Rozciąganie', 'Biceps'], 'Proste rozciąganie bicepsów w staniu. Splecione dłonie za plecami, ramiona uniesione do tyłu.', '1. Spleć dłonie za plecami, dłońmi do siebie, wyprostuj ramiona, a następnie obróć je tak, aby dłonie były skierowane w dół.
2. Unoś ramiona w górę i przytrzymaj, aż poczujesz rozciąganie w bicepsach.', NULL, 'free-exercise-db/Standing_Biceps_Stretch/0.jpg', 'free_exercise_db'),
  ('standing-bradford-press', 'Wyciskanie Bradforda na stojąco', 'Standing Bradford Press', 'motor_coach', 'beginner', array['Siłowe', 'Barki'], 'Wyciskanie sztangi, w której przenosisz ją z przodu na tył głowy. Rozwija elastyczność barków.', '1. Połóż załadowaną sztangę na wysokości barków w stojaku. Nachwytem na szerokość barków zacznij ze sztangą opartą z przodu barków. To Twoja pozycja startowa.
2. Rozpocznij podnoszenie prostując łokcie, aby wycisnąć sztangę nad głowę. Unikaj blokowania łokcia, przenosząc ciężar za głowę.
3. Opuść sztangę za głowę, aż łokieć utworzy kąt prosty.
4. Przenieś sztangę z powrotem nad głowę prostując łokcie.
5. Opuść sztangę do pozycji startowej.
6. Naprzemiennie w ten sposób, aż wykonasz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Standing_Bradford_Press/0.jpg', 'free_exercise_db'),
  ('standing-cable-chest-press', 'Wyciskanie na wyciągach na stojąco', 'Standing Cable Chest Press', 'motor_coach', 'beginner', array['Siłowe', 'Klatka piersiowa'], 'Wyciskanie uchwytów wyciągu przed sobą na stojąco. Ćwiczenie na klatkę piersiową z ciągłym napięciem.', '1. Ustaw dwa bloczki na wysokości klatki piersiowej i wybierz odpowiedni ciężar. Stań na stopę lub dwie przed linami, trzymając jeden w każdej dłoni. Możesz ustawić nogi w rozkroku dla lepszej stabilności.
2. Ustaw górną część ramion pod kątem 90 stopni, ze ściągniętymi łopatkami. To będzie Twoja pozycja startowa.
3. Utrzymując resztę ciała nieruchomo, prostuj łokcie, wypychając uchwyty do przodu i zbliżając je do siebie przed sobą.
4. Zatrzymaj się na szczycie ruchu, a następnie wróć do pozycji startowej.', NULL, 'free-exercise-db/Standing_Cable_Chest_Press/0.jpg', 'free_exercise_db'),
  ('standing-cable-lift', 'Podnoszenie na wyciągu (cable lift)', 'Standing Cable Lift', 'motor_coach', 'beginner', array['Siłowe', 'Brzuch'], 'Skrętny ruch wyciągiem od dołu do góry, po skosie ciała. Wzmacnia mięśnie skośne brzucha.', '1. Zamocuj standardowy uchwyt do wieży i ustaw linę na najniższym bloczku.
2. Bokiem do liny złap uchwyt jedną ręką i oddal się od wieży. Powinieneś być około na długość ramienia od bloczka, z napięciem ciężaru na linie. Twoje wyciągnięte ramię powinno być w linii z liną.
3. Ze stopami rozstawionymi na szerokość barków przysiadnij i złap uchwyt oburącz. Ramiona powinny wciąż być całkowicie wyprostowane.
4. Jednym ruchem pociągnij uchwyt w górę i przez ciało, aż ramiona znajdą się w całkowicie wyprostowanej pozycji nad głową.
5. Trzymaj grzbiet prosty i ramiona blisko ciała, obracając tylną stopę i prostując nogi, aby uzyskać pełny zakres ruchu.
6. Cofnij ramiona, a potem ciało. Wróć do pozycji neutralnej w sposób powolny i kontrolowany.
7. Powtarzaj do zmęczenia.
8. Następnie zmień ustawienie i powtórz tę samą serię ruchów po drugiej stronie.', NULL, 'free-exercise-db/Standing_Cable_Lift/0.jpg', 'free_exercise_db'),
  ('standing-cable-wood-chop', 'Rąbanie drewna na wyciągu', 'Standing Cable Wood Chop', 'motor_coach', 'beginner', array['Siłowe', 'Brzuch'], 'Skrętny ruch wyciągiem od góry do dołu, jak rąbanie drewna. Świetne ćwiczenie na mięśnie skośne brzucha.', '1. Zamocuj standardowy uchwyt do wieży i ustaw linę na najwyższym bloczku.
2. Bokiem do liny złap uchwyt jedną ręką i oddal się od wieży. Powinieneś być około na długość ramienia od bloczka, z napięciem ciężaru na linie. Twoje wyciągnięte ramię powinno być w linii z liną.
3. Ze stopami rozstawionymi na szerokość barków wyciągnij drugą rękę w górę i złap uchwyt oburącz. Ramiona powinny wciąż być całkowicie wyprostowane.
4. Jednym ruchem pociągnij uchwyt w dół i przez ciało do przedniego kolana, obracając tułów.
5. Trzymaj grzbiet i ramiona proste, a mięśnie głębokie spięte, obracając tylną stopę i uginając kolana, aby uzyskać pełny zakres ruchu.
6. Utrzymaj postawę i wyprostowane ramiona. Wróć do pozycji neutralnej w sposób powolny i kontrolowany.
7. Powtarzaj do zmęczenia.
8. Następnie zmień ustawienie i powtórz tę samą serię ruchów po drugiej stronie.', NULL, 'free-exercise-db/Standing_Cable_Wood_Chop/0.jpg', 'free_exercise_db'),
  ('standing-calf-raises', 'Wspięcia na palce na maszynie na stojąco', 'Standing Calf Raises', 'motor_coach', 'beginner', array['Siłowe', 'Łydki'], 'Klasyczne wspięcia na palce na maszynie. Wzmacnia łydki przy pełnym zakresie ruchu.', '1. Dostosuj poduszkę maszyny do wspięć na palce do swojego wzrostu.
2. Wsadź barki pod poduszki i ustaw palce stóp skierowane do przodu (lub użyj dowolnej z dwóch innych pozycji opisanych na początku rozdziału). Śródstopie powinno być stabilnie osadzone na bloku, z piętami wystającymi poza jego krawędź. Wypchnij dźwignię w górę prostując biodra i kolana, aż tułów stanie wyprostowany. Kolana powinny mieć lekki ugięcie; nigdy nie blokowane. Palce mogą być skierowane do przodu, na zewnątrz lub do wewnątrz, jak opisano na początku rozdziału. To będzie Twoja pozycja startowa.
3. Unoś pięty robiąc wydech, maksymalnie prostując kostki i spinając łydki. Upewnij się, że kolano pozostaje nieruchome przez cały czas. Nie powinno być żadnego uginania. Przytrzymaj pozycję napięcia sekundę, zanim zaczniesz schodzić w dół.
4. Powoli wróć do pozycji startowej, robiąc wdech, opuszczając pięty i uginając kostki, aż łydki zostaną rozciągnięte.
5. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Standing_Calf_Raises/0.jpg', 'free_exercise_db'),
  ('standing-concentration-curl', 'Uginanie ramion koncentracji na stojąco', 'Standing Concentration Curl', 'motor_coach', 'beginner', array['Siłowe', 'Biceps'], 'Uginanie ramienia z hantlem w pochyleniu, z łokciem opartym o udo. Mocno izoluje biceps.', '1. Biorąc hantel do ręki roboczej, pochyl się do przodu. Pozwól ramieniu roboczemu zwisać prostopadle do ziemi, z łokciem skierowanym na zewnątrz. To będzie Twoja pozycja startowa.
2. Ugnij łokieć, aby unieść ciężar, trzymając górną część ramienia nieruchomo. Na szczycie powtórzenia spięcie biceps i zatrzymaj się.
3. Opuść hantel z powrotem do pozycji startowej.
4. Powtórz ruch zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Standing_Concentration_Curl/0.jpg', 'free_exercise_db'),
  ('standing-dumbbell-calf-raise', 'Wspięcia na palce z hantlami na stojąco', 'Standing Dumbbell Calf Raise', 'motor_coach', 'intermediate', array['Siłowe', 'Łydki'], 'Wspięcia na palce z hantlami w dłoniach, ze śródstopiem na podwyższeniu. Prosta wersja ćwiczenia na łydki.', '1. Stań z tułowiem wyprostowanym, trzymając dwa hantle wzdłuż ciała. Połóż śródstopie na solidnej, stabilnej desce (o wysokości około 5-8 cm), a pięty wystają poza nią i dotykają podłogi. To będzie Twoja pozycja startowa.
2. Z palcami skierowanymi prosto (aby angażować wszystkie części równomiernie), do wewnątrz (akcent na zewnętrzną głowę) lub na zewnątrz (akcent na wewnętrzną głowę), unoś pięty nad ziemię robiąc wydech i spinając łydki. Przytrzymaj napięcie na górze przez sekundę.
3. Robiąc wdech, wróć do pozycji startowej, powoli opuszczając pięty.
4. Powtórz zalecaną liczbę razy.', NULL, 'free-exercise-db/Standing_Dumbbell_Calf_Raise/0.jpg', 'free_exercise_db'),
  ('standing-dumbbell-press', 'Wyciskanie hantli ponad głowę na stojąco', 'Standing Dumbbell Press', 'motor_coach', 'beginner', array['Siłowe', 'Barki'], 'Wyciskanie hantli ponad głowę w staniu. Klasyczne ćwiczenie na barki bez pomocy nóg.', '1. Stojąc ze stopami rozstawionymi na szerokość barków, weź hantel w każdą dłoń. Unoś hantle do wysokości głowy, łokcie na zewnątrz, mniej więcej pod kątem 90 stopni. To będzie Twoja pozycja startowa.
2. Zachowując ścisłą technikę - bez wybicia nóg ani odchylania się do tyłu - prostuj łokcie, unosząc ciężary razem dokładnie nad głowę.
3. Zatrzymaj się, a następnie powoli wróć ciężarami do pozycji startowej.', NULL, 'free-exercise-db/Standing_Dumbbell_Press/0.jpg', 'free_exercise_db'),
  ('standing-dumbbell-reverse-curl', 'Uginanie ramion chwytem odwróconym z hantlami', 'Standing Dumbbell Reverse Curl', 'motor_coach', 'intermediate', array['Siłowe', 'Biceps'], 'Uginanie ramion z hantlami nachwytem (dłonie w dół). Wzmacnia bicepsy i przedramiona.', '1. Na początek stań prosto z hantlem w każdej dłoni, używając chwytu nachwytu (palce skierowane w dół). Ramiona powinny być całkowicie wyprostowane, stopy rozstawione na szerokość barków. To pozycja startowa.
2. Utrzymując górne partie ramion nieruchomo, uginaj ciężary spinając bicepsy i robiąc wydech. Poruszać powinny się tylko przedramiona. Kontynuuj ruch, aż bicepsy będą całkowicie spięte, a hantle na wysokości barków. Przytrzymaj pozycję napięcia sekundę, spinając mięsień.
3. Powoli zacznij wracać hantlami do pozycji startowej, robiąc wdech.
4. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Standing_Dumbbell_Reverse_Curl/0.jpg', 'free_exercise_db'),
  ('standing-dumbbell-straight-arm-front-delt-raise-above-head', 'Wznosy hantli przed siebie z prostymi ramionami ponad głowę', 'Standing Dumbbell Straight-Arm Front Delt Raise Above Head', 'motor_coach', 'intermediate', array['Siłowe', 'Barki'], 'Wznosy przód z prostymi ramionami - unosisz hantle przed sobą aż nad głowę.', '1. Trzymaj hantle przed udami, dłońmi zwróconymi w stronę ud.
2. Trzymaj ramiona proste z lekkim ugięciem w łokciach, ale utrzymuj je zablokowane. To będzie Twoja pozycja startowa.
3. Unoś hantle ruchem półokrężnym do pełnego wyprostu ramion nad głową, robiąc wydech.
4. Powoli wróć do pozycji startowej tą samą drogą, robiąc wdech.
5. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Standing_Dumbbell_Straight-Arm_Front_Delt_Raise_Above_Head/0.jpg', 'free_exercise_db'),
  ('standing-dumbbell-triceps-extension', 'Prostowanie ramion z hantlem nad głową na stojąco', 'Standing Dumbbell Triceps Extension', 'motor_coach', 'beginner', array['Siłowe', 'Triceps'], 'Prostowanie ramion z jednym hantlem trzymanym oburącz nad głową. Izoluje tricepsy.', '1. Na początek stań prosto z hantlem trzymanym w obu dłoniach. Stopy powinny być rozstawione około na szerokość barków. Powoli złap hantel oburącz i unieś go ponad głowę, aż oba ramiona będą całkowicie wyprostowane.
2. Ciężar powinien spoczywać na dłoniach, z kciukami wokół niego. Dłonie powinny być skierowane w górę, ku sufitowi. To będzie Twoja pozycja startowa.
3. Utrzymując górne partie ramion blisko głowy, z łokciami blisko ciała i prostopadle do podłogi, opuszczaj ciężar ruchem półokrężnym za głowę, aż przedramiona dotkną bicepsów. Wskazówka: górne partie ramion powinny pozostać nieruchome, poruszać się powinny tylko przedramiona. Wdechuj podczas tego kroku.
4. Wróć do pozycji startowej używając tricepsów, aby unieść hantel. Wydechuj podczas tego kroku.
5. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Standing_Dumbbell_Triceps_Extension/0.jpg', 'free_exercise_db'),
  ('standing-dumbbell-upright-row', 'Wiosłowanie po linii ud z hantlami na stojąco', 'Standing Dumbbell Upright Row', 'motor_coach', 'beginner', array['Siłowe', 'Czworoboczne'], 'Wznos hantli wzdłuż ciała do brody. Ćwiczy boczne aktony barków i czworoboczny.', '1. Złap hantel w każdą dłoń chwytem nachwytem nieco węższym niż szerokość barków. Hantle powinny spoczywać na udach. Ramiona wyprostowane z lekkim ugięciem w łokciach, grzbiet prosty. To będzie Twoja pozycja startowa.
2. Używając bocznych aktonów barków, unoś hantle robiąc wydech. Hantle powinny pozostawać blisko ciała podczas unoszenia, a to łokcie powinny prowadzić ruch. Podnoś je, aż prawie dotkną brody. Wskazówka: to łokcie powinny prowadzić ruch. Podczas unoszenia hantli Twoje łokcie powinny zawsze być wyżej niż przedramiona. Ponadto trzymaj tułów nieruchomo i zatrzymaj się na sekundę na szczycie ruchu.
3. Powoli opuść hantle z powrotem do pozycji startowej. Wdechuj podczas tej fazy ruchu.
4. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Standing_Dumbbell_Upright_Row/0.jpg', 'free_exercise_db'),
  ('standing-elevated-quad-stretch', 'Rozciąganie czworogłowych z nogą na podwyższeniu', 'Standing Elevated Quad Stretch', 'motor_coach', 'beginner', array['Rozciąganie', 'Uda'], 'Rozciąganie przodu uda ze stopą opartą o ławkę za Tobą. Skuteczna wersja rozciągania kwadricepsów na stojąco.', '1. Zacznij od stania grzbietem około 60-90 cm od ławki lub stopnia.
2. Unieś jedną nogę za siebie i oprzyj stopę na stopniu - na grzbiecie stopy albo śródstopiu, w zależności od tego, co jest dla Ciebie najwygodniejsze.
3. Trzymaj kolano nogi podporowej lekko ugięte i unikaj wysuwania go poza palce stopy. Zmień strony.', NULL, 'free-exercise-db/Standing_Elevated_Quad_Stretch/0.jpg', 'free_exercise_db'),
  ('standing-front-barbell-raise-over-head', 'Wznosy sztangi przed siebie ponad głowę', 'Standing Front Barbell Raise Over Head', 'motor_coach', 'intermediate', array['Siłowe', 'Barki'], 'Unoszenie sztangi przed sobą prostymi ramionami aż ponad głowę. Ćwiczy przednie aktony barków.', '1. Na początek stań prosto ze sztangą w dłoniach. Chwyt nachwytem, nieco węższy niż szerokość barków.
2. Stopy powinny być rozstawione na szerokość barków. Łokcie lekko ugięte. To pozycja startowa.
3. Unoś sztangę, aż będzie dokładnie nad Twoją głową, robiąc wydech. Pamiętaj, aby trzymać łokcie lekko ugięte przy każdym powtórzeniu.
4. Gdy poczujesz napięcie, zacznij opuszczać sztangę z powrotem do pozycji startowej, robiąc wdech.
5. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Standing_Front_Barbell_Raise_Over_Head/0.jpg', 'free_exercise_db'),
  ('standing-gastrocnemius-calf-stretch', 'Rozciąganie łydek (gastroknemiusza) na stojąco', 'Standing Gastrocnemius Calf Stretch', 'motor_coach', 'beginner', array['Rozciąganie', 'Łydki'], 'Rozciąganie łydki z piętą na stopniu. Pociągasz palce stopy w górę, aby pogłębić rozciąganie.', '1. Połóż prawą piętę na stopniu z wyprostowanym kolanem i pochyl się do przodu, aby chwycić palce prawej stopy prawą dłonią. Lewe kolano powinno być lekko ugięte, a grzbiet prosty.
2. Oparty na lewej nodze połóż lewą dłoń na lewym udzie.
3. Pociągnij palce prawej stopy w kierunku kolana, aż poczujesz rozciąganie w łydce.', NULL, 'free-exercise-db/Standing_Gastrocnemius_Calf_Stretch/0.jpg', 'free_exercise_db'),
  ('standing-hamstring-and-calf-stretch', 'Rozciąganie dwugłowych ud i łydek na stojąco', 'Standing Hamstring and Calf Stretch', 'motor_coach', 'beginner', array['Rozciąganie', 'Dwugłowe uda'], 'Rozciąganie tyłu uda i łydki z pomocą pasa lub gumy. Stopa z przodu, palce pociągane pasem do góry.', '1. Zacznij od przełożenia pasa, gumy lub liny przez jedną stopę. Na stojąco umieść tę stopę z przodu.
2. Ugnij tylną nogę, zachowując przednią wyprostowaną. Teraz unoś palce przedniej stopy nad ziemię i pochyl się do przodu.
3. Używając pasa, pociągnij za górną część stopy, aby zwiększyć rozciąganie w łydce. Przytrzymaj 10-20 sekund i powtórz drugą stopą.', NULL, 'free-exercise-db/Standing_Hamstring_and_Calf_Stretch/0.jpg', 'free_exercise_db'),
  ('standing-hip-circles', 'Krążenia biodrem na stojąco', 'Standing Hip Circles', 'motor_coach', 'beginner', array['Rozciąganie', 'Odwodziciele'], 'Mobilizacja biodra - krążenie uniesionym kolanem w dużym łuku. Wykonywane przy podporze dla równowagi.', '1. Zacznij stojąc na jednej nodze, trzymając się pionowego podparcia.
2. Unoś niepodparte kolano do 90 stopni. To będzie Twoja pozycja startowa.
3. Otwieraj biodro jak najdalej, próbując wykonać duże koło kolanem.
4. Wykonuj ten ruch powoli przez określoną liczbę powtórzeń, a następnie powtórz drugą stroną.', NULL, 'free-exercise-db/Standing_Hip_Circles/0.jpg', 'free_exercise_db'),
  ('standing-hip-flexors', 'Rozciąganie zginaczy bioder na stojąco', 'Standing Hip Flexors', 'motor_coach', 'beginner', array['Rozciąganie', 'Uda'], 'Proste rozciąganie zginaczy bioder w staniu. Lekkie zgięcie kolan z wypchnięciem biodra do przodu.', '1. Stań prosto z kręgosłupem pionowym, lewą stopą lekko z przodu prawej.
2. Ugnij oba kolana i unoś piętę tylnej nogi nad podłogę, wypychając prawe biodro do przodu. Nie uzyskasz jednak w tej pozycji głębokiego rozciągania, ponieważ trudno jest rozluźnić zginacz biodra i jednocześnie stać na nim. Zmień strony.', NULL, 'free-exercise-db/Standing_Hip_Flexors/0.jpg', 'free_exercise_db'),
  ('standing-inner-biceps-curl', 'Uginanie ramion chwytem neutralnym (na biceps wewnętrzny)', 'Standing Inner-Biceps Curl', 'motor_coach', 'intermediate', array['Siłowe', 'Biceps'], 'Uginanie hantli chwytem młotkowym, z rotacją nadgarstków na końcu ruchu. Angażuje wewnętrzne części bicepsów.', '1. Stań prosto z hantlem w każdej dłoni, trzymanymi przy wyciągniętych ramionach. Łokcie powinny być blisko tułowia. Nogi rozstawione około na szerokość barków.
2. Obróć dłonie tak, aby były skierowane do wewnątrz, w pozycji neutralnej. To będzie Twoja pozycja startowa.
3. Utrzymując górne partie ramion nieruchomo, uginaj ciężary na zewnątrz, spinając bicepsy, robiąc wydech. Nadgarstki powinny się obracać tak, aby gdy ciężary są całkowicie uniesione, miałeś chwyt podchwytem (palce skierowane w górę).
4. Poruszać powinny się tylko przedramiona. Kontynuuj ruch, aż bicepsy będą całkowicie spięte, a hantle na wysokości barków. Wskazówka: trzymaj przedramiona w linii z zewnętrznymi aktonami barków.
5. Przytrzymaj pozycję napięcia sekundę, spinając bicepsy.
6. Powoli zacznij wracać hantlami do pozycji startowej, robiąc wdech. Pamiętaj, aby obracać nadgarstki podczas opuszczania ciężaru, aby przejść z powrotem do chwytu neutralnego.
7. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Standing_Inner-Biceps_Curl/0.jpg', 'free_exercise_db'),
  ('standing-lateral-stretch', 'Rozciąganie boczne tułowia na stojąco', 'Standing Lateral Stretch', 'motor_coach', 'beginner', array['Rozciąganie', 'Brzuch'], 'Rozciąganie boku ciała w staniu. Jedna ręka za głową, pochylasz tułów w bok.', '1. Przyjmij postawę nieco szerszą niż biodra, z lekko ugiętymi kolanami.
2. Połóż prawą dłoń na prawym biodrze, aby wspierać kręgosłup.
3. Unoś lewe ramię w linii pionowej i połóż lewą dłoń za głową. Trzymaj ją tam, pochylając tułów w prawo.
4. Utrzymuj ciężar równomiernie rozłożony na obie nogi (nie przechylaj się na lewe biodro). Zmień strony.', NULL, 'free-exercise-db/Standing_Lateral_Stretch/0.jpg', 'free_exercise_db'),
  ('standing-leg-curl', 'Uginanie nóg stojąc na maszynie', 'Standing Leg Curl', 'motor_coach', 'beginner', array['Siłowe', 'Dwugłowe uda'], 'Uginanie nóg na maszynie w pozycji stojącej z pochyleniem. Izoluje mięśnie dwugłowe ud.', '1. Dostosuj dźwignię maszyny do swojego wzrostu i ustaw się z tułowiem pochylonym w biodrach do przodu o 30-45 stopni (pozycja pod kątem jest korzystniejsza dla pracy dwugłowych ud), z poduszką dźwigni na tylnej części prawej nogi (kilka centymetrów poniżej łydek) i przodem prawej nogi na poduszce maszyny.
2. Utrzymując tułów pochylony do przodu, upewnij się, że noga jest całkowicie rozciągnięta i chwyć boczne uchwyty maszyny. Ustaw palce stóp prosto. To będzie Twoja pozycja startowa.
3. Robiąc wydech, ugnij prawą nogę jak najdalej, nie unosząc górnej części nogi z poduszki. Gdy osiągniesz pełne napięcie, przytrzymaj je sekundę.
4. Robiąc wdech, wróć nogą do pozycji początkowej. Powtórz zalecaną liczbę powtórzeń.
5. Teraz wykonaj to samo ćwiczenie dla lewej nogi.', NULL, 'free-exercise-db/Standing_Leg_Curl/0.jpg', 'free_exercise_db'),
  ('standing-long-jump', 'Skok w dal z miejsca', 'Standing Long Jump', 'motor_coach', 'beginner', array['Plyometryka', 'Uda'], 'Wybuchowy skok w dal z pozycji stojącej, wykonywany najlepiej na miękkim podłożu. Rozpoczynasz z lekkiego przysiadu, zamachem ramion wybijasz się maksymalnie do przodu i lądujesz na nogach wysuniętych przed siebie.', '1. To ćwiczenie najlepiej wykonywać na piasku lub innej miękkiej powierzchni do lądowania. Upewnij się, że możesz zmierzyć odległość. Stań w pozycji półprzysiadu ze stopami rozstawionymi na szerokość barków.
2. Wykorzystując duży zamach ramion i ruch przeciwbieżny nóg (countermovement), skocz w przód tak daleko, jak tylko potrafisz.
3. Postaraj się wylądować ze stopami wysuniętymi przed siebie, sięgając nogami jak najdalej.
4. Zmierz odległość od miejsca lądowania do punktu startu i zapisuj wyniki.', NULL, 'free-exercise-db/Standing_Long_Jump/0.jpg', 'free_exercise_db'),
  ('standing-low-pulley-deltoid-raise', 'Unoszenie ramienia bokiem przy dolnym bloku', 'Standing Low-Pulley Deltoid Raise', 'motor_coach', 'beginner', array['Siłowe', 'Barki'], 'Izolowane unoszenie jednej ręki w bok za pomocą linki dolnego bloku, angażujące boczny akton barku. Stoisz bokiem do maszyny, chwytasz uchwyt drugą ręką i unosisz go na wysokość barków.', '1. Zacznij od stanięcia po prawej stronie dolnego wyciągu. Lewą ręką przełóż ją przed sobą przez korpus i złap pojedynczy uchwyt przymocowany do dolnego bloku chwytem nachwytem (dłonie skierowane w dół). Opuść swobodnie ramię przed siebie. Prawa dłoń powinna trzymać maszynę dla lepszej stabilizacji i równowagi.
2. Upewnij się, że plecy są wyprostowane, a stody rozstawione na szerokość barków. To jest pozycja startowa.
3. Zacznij unosić lewą rękę przed siebie aż będzie na wysokości barków, wykonując wydech.
4. Wyczuć napięcie na górze przez sekundę i zacznij powoli opuszczać uchwyt z powrotem do pierwotnej pozycji startowej, robiąc wdech.
5. Powtórz zalecaną liczbę powtórzeń.
6. Zmień rękę i powtórz ćwiczenie.', NULL, 'free-exercise-db/Standing_Low-Pulley_Deltoid_Raise/0.jpg', 'free_exercise_db'),
  ('standing-low-pulley-one-arm-triceps-extension', 'Prostowanie ramienia z linką dolnego bloku nad głową', 'Standing Low-Pulley One-Arm Triceps Extension', 'motor_coach', 'intermediate', array['Siłowe', 'Triceps'], 'Jednoręczne francuskie wyciskanie z linką dolnego bloku, celujące w triceps. Ramię jest uniesione pionowo nad głową, a ty prostujesz przedramię, opuszczając i podnosząc obciążenie za głową.', '1. Złap pojedynczy uchwyt lewą ręką obok maszyny dolnego wyciągu. Odwróć się plecami do maszyny, trzymając uchwyt przy boku ciała z całkowicie wyprostowanym ramieniem. Teraz oboma rękami unieś uchwyt bezpośrednio nad głowę, dłonią skierowaną do przodu. Utrzymuj ramię całkowicie pionowo (prostopadle do podłoża) i połóż prawą dłoń na lewym łokciu, aby pomóc utrzymać stabilność. To jest pozycja startowa.
2. Trzymając górne ramiona blisko głowy (łokcie blisko ciała) i prostopadle do podłoża, opuszczaj obciążenie ruchem po półkolu za głowę, aż przedramiona dotkną bicepsów. Wskazówka: Górna część ramion powinna pozostać nieruchoma — poruszać się powinny tylko przedramiona. Wdech wykonaj podczas tego kroku.
3. Wróć do pozycji startowej, używając tricepsa do uniesienia uchwytu. Wydech wykonaj podczas tego kroku.
4. Powtórz zalecaną liczbę powtórzeń.
5. Zmień rękę i powtórz ćwiczenie.', NULL, 'free-exercise-db/Standing_Low-Pulley_One-Arm_Triceps_Extension/0.jpg', 'free_exercise_db'),
  ('standing-military-press', 'Wyciskanie sztangi nad głowę stojąc', 'Standing Military Press', 'motor_coach', 'beginner', array['Siłowe', 'Barki'], 'Klasyczne wojskowe wyciskanie sztangi stojąc, budujące barki i siłę całego górnego ciała. Sztanga trzymana nachwytem lekko szerzej niż barki jest wyciskana znad obojczyka nad głowę.', '1. Zacznij od umieszczenia sztangi na stojaku do przysiadów mniej więcej na wysokości klatki piersiowej. Po dobraniu ciężaru złap sztangę chwytem nachwytem (dłonie skierowane do przodu). Upewnij się, że chwyt jest szerszy niż szerokość barków.
2. Lekko ugnij kolana i połóż sztangę na obojczyku. Podnieś sztangę, trzymając ją na klatce piersiowej. Zrób krok w tył i ustaw stopy na szerokość barków.
3. Kiedy podniesiesz sztangę z odpowiednią szerokością chwytu, unieś sztangę nad głowę, prostując ręce. Zatrzymaj ją mniej więcej na poziomie barków, nieco z przodu głowy. To jest Twoja pozycja startowa.
4. Powoli opuść sztangę na obojczyk, robiąc wdech.
5. Podnieś sztangę z powrotem do pozycji startowej, robiąc wydech.
6. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Standing_Military_Press/0.jpg', 'free_exercise_db'),
  ('standing-olympic-plate-hand-squeeze', 'Ściskanie talerzy owalnych w dłoniach', 'Standing Olympic Plate Hand Squeeze', 'motor_coach', 'beginner', array['Siłowe', 'Przedramiona'], 'Ćwiczenie wzmacniające siłę chwytu polegające na ściskaniu talerza w każdej dłoni. Trzymasz talerze za ranty w opuszczonych rękach, otwierasz palce niemal do granic możliwości, po czym zaciskasz dłonie z powrotem.', '1. Na początku stań prosto, trzymając talerz za rant w każdej dłoni, z rękami wyprostowanymi wzdłuż ciała, w chwycie neutralnym (dłonie skierowane do środka). Stopy powinny być rozstawione na szerokość barków. To będzie Twoja pozycja startowa.
2. Opuszczaj talerze, aż palce są niemal wyprostowane, ale wciąż mogą utrzymać ciężary. Wdech wykonaj podczas opuszczania talerzy.
3. Teraz unieś talerze z powrotem do pozycji startowej, robiąc wydech, zaciskając dłonie.
4. Powtórz zalecaną liczbę powtórzeń przewidzianych w Twoim programie treningowym.', NULL, 'free-exercise-db/Standing_Olympic_Plate_Hand_Squeeze/0.jpg', 'free_exercise_db'),
  ('standing-one-arm-cable-curl', 'Uginanie jednej ręki na modlitewniku przy dolnym bloku', 'Standing One-Arm Cable Curl', 'motor_coach', 'intermediate', array['Siłowe', 'Biceps'], 'Jednoręczne uginanie ramienia z uchwytem dolnego bloku, izolujące biceps. Łokieć pozostaje nieruchomo przy tułowiu, a porusza się tylko przedramię, unosząc i opuszczając uchwyt.', '1. Zacznij od złapania pojedynczego uchwytu obok maszyny dolnego wyciągu. Upewnij się, że jesteś wystarczająco daleko od maszyny, aby ramię pracowało przeciw ciężarowi.
2. Upewnij się, że Twoje ramię jest nieruchome, prostopadłe do podłoża, z łokciami blisko ciała i dłońmi skierowanymi do przodu. Niewpracująca ręka powinna trzymać talię. Pozwoli Ci to zachować równowagę.
3. Powoli zacznij uginać ramię z uchwytem w górę, utrzymując ramię nieruchome, aż przedramię dotknie bicepsa, robiąc wydech. Wskazówka: Poruszać się powinno tylko przedramię.
4. Zatrzymaj napięcie, zaciskając mocno biceps, a następnie opuść uchwyt z powrotem do pozycji startowej, robiąc wdech.
5. Powtórz zalecaną liczbę powtórzeń.
6. Zmień rękę podczas wykonywania tego ćwiczenia.', NULL, 'free-exercise-db/Standing_One-Arm_Cable_Curl/0.jpg', 'free_exercise_db'),
  ('standing-one-arm-dumbbell-curl-over-incline-bench', 'Uginanie jednorącz hantli nad ławką skośną', 'Standing One-Arm Dumbbell Curl Over Incline Bench', 'motor_coach', 'beginner', array['Siłowe', 'Biceps'], 'Uginanie hantli jedną ręką z ramieniem opartym na skośnej ławce, które mocno izoluje biceps. Klatka piersiowa oparta o górny koniec ławki, a porusza się tylko przedramię.', '1. Stań za ławką skośną, tak jakbyś miał asekurować kogoś. Trzymaj hantel w jednej ręce i oprzyj ją na ławce skośnej w chwycie podchwytem (dłonie skierowane do góry).
2. Umieść niewpracującą dłoń na narożniku lub boku ławki skośnej. Klatka piersiowa powinna być przyciśnięta do górnej części ławki, a stopy mocno oparte o podłoże w szerokim rozstawie. To jest pozycja startowa.
3. Utrzymując ramię nieruchome, ugnij ramię z hantlą w górę, napinając biceps podczas wydechu. Poruszać się powinno tylko przedramię. Kontynuuj ruch, aż biceps będzie całkowicie napięty, a hantla na wysokości barków. Przytrzymaj pozycję napiętą przez sekundę.
4. Powoli zacznij opuszczać hantlę z powrotem do pozycji startowej, robiąc wdech.
5. Powtórz zalecaną liczbę powtórzeń.
6. Zmień rękę podczas wykonywania tego ćwiczenia.', NULL, 'free-exercise-db/Standing_One-Arm_Dumbbell_Curl_Over_Incline_Bench/0.jpg', 'free_exercise_db'),
  ('standing-one-arm-dumbbell-triceps-extension', 'Jednoręczne prostowanie ramienia z hantlą nad głowę', 'Standing One-Arm Dumbbell Triceps Extension', 'motor_coach', 'beginner', array['Siłowe', 'Triceps'], 'Francuskie wyciskanie hantli jedną ręką nad głową, celujące w triceps. Ramię pozostaje pionowo przy głowie, a porusza się tylko przedramię, opuszczając hantlę za głowę.', '1. Na początku stań z hantlą trzymaną w jednej ręce. Stopy powinny być rozstawione mniej więcej na szerokość barków. Teraz całkowicie wyprostuj ramię z hantlą nad głową. Wskazówka: Mały palec Twojej dłoni powinien być skierowany ku sufitowi, a wnętrze dłoni skierowane do przodu. Hantla powinna znajdować się nad Twoją głową.
2. To będzie Twoja pozycja startowa.
3. Trzymając ramię blisko głowy (łokcie blisko ciała) i prostopadle do podłoża, opuszczaj obciążenie ruchem po półkolu za głowę, aż przedramię dotknie bicepsa. Wskazówka: Górne ramię powinno pozostać nieruchome — poruszać się powinno tylko przedramię. Wdech wykonaj podczas tego kroku.
4. Wróć do pozycji startowej, używając tricepsa do uniesienia hantli. Wydech wykonaj podczas tego kroku.
5. Powtórz zalecaną liczbę powtórzeń.
6. Zmień rękę i powtórz ćwiczenie.', NULL, 'free-exercise-db/Standing_One-Arm_Dumbbell_Triceps_Extension/0.jpg', 'free_exercise_db'),
  ('standing-overhead-barbell-triceps-extension', 'Francuskie wyciskanie sztangi stojąc', 'Standing Overhead Barbell Triceps Extension', 'motor_coach', 'beginner', array['Siłowe', 'Triceps'], 'Prostowanie ramion ze sztangą nad głową stojąc, mocno angażujące triceps. Szczupły chwyt, łokcie blisko głowy, a poruszają się tylko przedramiona opuszczając sztangę za głowę.', '1. Na początku stań trzymając sztangę lub gryf EZ chwytem nachwytem (dłonie skierowane do przodu), z rękami bliżej niż szerokość barków. Stopy powinny być rozstawione mniej więcej na szerokość barków.
2. Teraz unieś sztangę nad głowę, aż ręce będą całkowicie wyprostowane. Trzymaj łokcie blisko ciała. To będzie Twoja pozycja startowa.
3. Trzymając górne ramiona blisko głowy i łokcie blisko ciała, prostopadle do podłoża, opuszczaj obciążenie ruchem po półkolu za głowę, aż przedramiona dotkną bicepsów. Wskazówka: Górna część ramion powinna pozostać nieruchoma — poruszać się powinny tylko przedramiona. Wdech wykonaj podczas tego kroku.
4. Wróć do pozycji startowej, używając tricepsa do uniesienia sztangi. Wydech wykonaj podczas tego kroku.
5. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Standing_Overhead_Barbell_Triceps_Extension/0.jpg', 'free_exercise_db'),
  ('standing-palm-in-one-arm-dumbbell-press', 'Wyciskanie hantli jednorącz neutralnym chwytem', 'Standing Palm-In One-Arm Dumbbell Press', 'motor_coach', 'beginner', array['Siłowe', 'Barki'], 'Jednoręczne wyciskanie hantli bokiem w górę w chwycie neutralnym, budujące boczne partie barków. Druga ręka trzyma ławkę skośną dla równowagi; ramię prostuje się nad głowę i opuszcza do kąta 90 stopni.', '1. Zacznij od trzymania hantli w jednej ręce z ramieniem całkowicie wyprostowanym w bok, w chwycie neutralnym. Drugą ręką trzymaj się ławki skośnej dla zachowania równowagi.
2. Stopy powinny być rozstawione na szerokość barków. Teraz powoli unieś hantlę w górę, aż stworzysz kąt 90 stopni ramieniem. Uwaga: Przedramię powinno być prostopadłe do podłoża. Zachowuj chwyt neutralny przez cały czas trwania ćwiczenia.
3. Powoli unieś hantlę w górę, aż ramię będzie całkowicie wyprostowane. To jest pozycja startowa.
4. Robiąc wdech, opuść ciężar w dół, aż ramię ponownie utworzy kąt 90 stopni.
5. Wyczuć napięcie przez sekundę, a następnie unieś ciężar z powrotem do pozycji startowej, robiąc wydech. Pamiętaj, żeby trzymać się ławki skośnej i utrzymywać stopy w pozycji zapewniającej równowagę podczas ćwiczenia.
6. Powtórz zalecaną liczbę powtórzeń.
7. Zmień rękę i powtórz ćwiczenie.', NULL, 'free-exercise-db/Standing_Palm-In_One-Arm_Dumbbell_Press/0.jpg', 'free_exercise_db'),
  ('standing-palms-in-dumbbell-press', 'Wyciskanie hantli bokiem neutralnym chwytem', 'Standing Palms-In Dumbbell Press', 'motor_coach', 'intermediate', array['Siłowe', 'Barki'], 'Oburęczne wyciskanie hantli bokiem w chwytach neutralnych, rozwijające boczne aktony. Ramię prostuje się nad głowę i wraca do kąta 90 stopni przy boku.', '1. Zacznij od trzymania hantli w każdej ręce z ramionami całkowicie wyprostowanymi w bok, w chwytach neutralnych. Stopy powinny być rozstawione na szerokość barków. Teraz powoli unieś hantle w górę, aż stworzysz kąt 90 stopni ramionami. Uwaga: Przedramiona powinny być prostopadłe do podłoża. To jest pozycja startowa.
2. Zachowuj chwyt neutralny przez cały czas trwania ćwiczenia. Powoli unieś hantle w górę, aż ramiona będą całkowicie wyprostowane.
3. Robiąc wdech, opuść ciężary w dół, aż ramiona ponownie będą pod kątem 90 stopni.
4. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Standing_Palms-In_Dumbbell_Press/0.jpg', 'free_exercise_db'),
  ('standing-palms-up-barbell-behind-the-back-wrist-curl', 'Nadgarstkowe uginanie sztangi za plecami', 'Standing Palms-Up Barbell Behind The Back Wrist Curl', 'motor_coach', 'beginner', array['Siłowe', 'Przedramiona'], 'Izolacja przedramion przez uginanie nadgarstków ze sztangą trzymaną za plecami. Ruch wykonuje wyłącznie nadgarstek, unosząc sztangę ruchem po półkolu ku sufitowi.', '1. Zacznij od stania prosto i trzymania sztangi za pośladkami, z ramionami wyprostowanymi, w chwycie nachwytem (dłonie skierowane do tyłu, od pośladków), z rękami rozstawionymi na szerokość barków.
2. Powinieneś patrzeć prosto przed siebie, a stopy rozstawione na szerokość barków. To jest pozycja startowa.
3. Robiąc wydech, powoli unoś sztangę w górę, uginając nadgarstek ruchem po półkolu ku sufitowi. Uwaga: Nadgarstek powinien być jedyną ruchomą częścią ciała w tym ćwiczeniu.
4. Przytrzymaj napięcie przez sekundę i opuść sztangę z powrotem do pozycji startowej, robiąc wdech.
5. Powtórz zalecaną liczbę powtórzeń.
6. Po zakończeniu opuść sztangę na stojak do przysiadów lub podłogę, uginając kolana. Wskazówka: Najłatwiej albo wyjąć sztangę ze stojaka, albo poprosić partnera, żeby ją podał.', NULL, 'free-exercise-db/Standing_Palms-Up_Barbell_Behind_The_Back_Wrist_Curl/0.jpg', 'free_exercise_db'),
  ('standing-pelvic-tilt', 'Miedniczne odchylenie miednicy stojąc', 'Standing Pelvic Tilt', 'motor_coach', 'beginner', array['Rozciąganie', 'Dolny odcinek pleców'], 'Delikatne rozciąganie dolnego odcinka kręgosłupa i bioder wykonywane stojąc. Lekko uginasz kolana i poruszasz miednicą przodem i tyłem, kończąc z kością ogonową skierowaną do przodu.', '1. Zacznij ze stopami rozstawionymi na szerokość bioder.
2. Lekko ugnij kolana, aby były miękkie i sprężyste.
3. Możesz poruszać miednicą kilka razy do przodu i do tyłu, zanim zatrzymasz kość ogonową skierowaną do przodu w tym rozciąganiu.', NULL, 'free-exercise-db/Standing_Pelvic_Tilt/0.jpg', 'free_exercise_db'),
  ('standing-rope-crunch', 'Brzuch z linką wyciągu stojąc', 'Standing Rope Crunch', 'motor_coach', 'beginner', array['Siłowe', 'Brzuch'], 'Crunch brzucha stojąc z linką górnego wyciągu założoną przez ramiona na klatkę piersiową. Składasz kręgosłup, ściągając obciążenie w dół maksymalnie.', '1. Zamocuj linkę na górnym bloku i dobierz odpowiedni ciężar.
2. Stań plecami do wieży wyciągu. Weź linkę obiema rękami przez ramiona, trzymając ją na górnej części klatki piersiowej. To będzie Twoja pozycja startowa.
3. Wykonaj ruch, składając kręgosłup, ściągając obciążenie w dół tak daleko, jak potrafisz.
4. Przytrzymaj szczytowe napięcie przez chwilę przed powrotem do pozycji startowej.', NULL, 'free-exercise-db/Standing_Rope_Crunch/0.jpg', 'free_exercise_db'),
  ('standing-soleus-and-achilles-stretch', 'Rozciąganie mięśnia płaszczkowatego i Achillesa', 'Standing Soleus And Achilles Stretch', 'motor_coach', 'beginner', array['Rozciąganie', 'Łydki'], 'Rozciąganie łydek i ścięgna Achillesa wykonywane stojąc z nogami lekko wysuniętymi jedna przed drugą. Uginasz oba kolana, trzymając piłę tylnej nogi przy ziemi, po czym zmieniasz stronę.', '1. Stań ze stopami rozstawionymi na szerokość bioder, jedną stopą lekko z przodu drugiej.
2. Ugnij oba kolana, trzymając piłę tylnej nogi na podłodze. Zmień stronę.', NULL, 'free-exercise-db/Standing_Soleus_And_Achilles_Stretch/0.jpg', 'free_exercise_db'),
  ('standing-toe-touches', 'Skłon dotknąć palców stojąc', 'Standing Toe Touches', 'motor_coach', 'beginner', array['Rozciąganie', 'Dwugłowe uda'], 'Proste rozciąganie tylnej części ciała: stojąc pochylasz się w biodrach z prostymi nogami i pozwolasz górnej części ciała zwisać luźno w dół. Utrzymujesz tę pozycję 10–20 sekund.', '1. Stań zostawiając trochę miejsca przed i za sobą.
2. Pochyl się w biodrach, trzymając nogi proste, aż będziesz mógł się rozluźnić i pozwolić górnej części ciała zwisać luźno przed sobą. Pozwól ramionom i dłoniom zwisać naturalnie. Przytrzymaj przez 10–20 sekund.', NULL, 'free-exercise-db/Standing_Toe_Touches/0.jpg', 'free_exercise_db'),
  ('standing-towel-triceps-extension', 'Francuskie wyciskanie z ręcznikiem z oporem partnera', 'Standing Towel Triceps Extension', 'motor_coach', 'beginner', array['Siłowe', 'Triceps'], 'Prostowanie ramienia nad głowę z ręcznikiem, którego drugi koniec trzyma partner, stawiający opór. Łokcie blisko głowy, a poruszają się tylko przedramiona.', '1. Na początku stań z obiema rękami całkowicie wyprostowanymi nad głową, trzymając jeden koniec ręcznika obiema rękami. Łokcie powinny być blisko ciała, a ramiona prostopadłe do podłoża, z dłońmi skierowanymi ku sobie; stopy powinny być rozstawione na szerokość barków. To jest pozycja startowa.
2. Teraz porozumiewaj się z partnerem, aby mógł złapać drugi koniec ręcznika i stawić opór. Trzymając górne ramiona blisko głowy (łokcie blisko ciała) i prostopadle do podłoża, opuszczaj opór ruchem po półkolu za głowę, aż przedramiona dotkną bicepsów. Wskazówka: Górna część ramion powinna pozostać nieruchoma — poruszać się powinny tylko przedramiona. Wdech wykonaj podczas tego kroku.
3. Wróć do pozycji startowej, używając tricepsa do uniesienia ręcznika. Wydech wykonaj podczas tego kroku.
4. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Standing_Towel_Triceps_Extension/0.jpg', 'free_exercise_db'),
  ('standing-two-arm-overhead-throw', 'Rzut piłką lekarską nad głowę oburącz', 'Standing Two-Arm Overhead Throw', 'motor_coach', 'beginner', array['Plyometryka', 'Barki'], 'Eksplozywny rzut piłki lekarskiej oburącz znad głowy do przodu, angażujący całe ciało. Odrzucając piłkę za głowę i lekko uginając kolana, gwałtownie wyrzucasz ją do partnera lub o ścianę.', '1. Stań ze stopami rozstawionymi na szerokość barków, trzymając piłkę lekarską obiema rękami. Na początek cofnij piłkę lekarską głęboko za głowę, lekko uginając kolana i odchylając się do tyłu.
2. Gwałtownie rzuć piłką do przodu, uginając się w biodrach i używając całego ciała do wykonania ruchu.
3. Piłkę można rzucić do partnera lub w ścianę, łapiąc ją po odbiciu.', NULL, 'free-exercise-db/Standing_Two-Arm_Overhead_Throw/0.jpg', 'free_exercise_db'),
  ('star-jump', 'Skoki gwiazda', 'Star Jump', 'motor_coach', 'beginner', array['Plyometryka', 'Uda'], 'Wybuchowy skok plyometryczny: z półprzysiadu wybijasz się maksymalnie w górę, rozstawiając nogi i ręce na boki jak gwiazda. Przy lądowaniu zbierasz kończyny i amortyzujesz uderzenie nogami.', '1. Zacznij w rozluźnionej postawie ze stopami rozstawionymi na szerokość barków, trzymając ramiona blisko ciała.
2. Aby rozpocząć ruch, zejdź do półprzysiadu i wybij się maksymalnie w górę. Całkowicie wyprostuj całe ciało, rozstawiając nogi i ramiona z dala od tułowia.
3. Przy lądowaniu zbierz kończyny z powrotem i amortyzuj uderzenie nogami.', NULL, 'free-exercise-db/Star_Jump/0.jpg', 'free_exercise_db'),
  ('step-mill', 'Schodostęp (stepmill)', 'Step Mill', 'motor_coach', 'intermediate', array['Cardio', 'Uda'], 'Trening kardio na maszynie schodowej imitującej wspinanie po schodach ruchomych. Świetnie spala kalorie i buduje wydolność, choć jest wymagający — zwykle trudniejszy niż inne urządzenia cardio.', '1. Na początku wejdź na schodostęp i wybierz żądaną opcję z menu. Możesz wybrać tryb ręczny albo program. Zazwyczaj możesz wprowadzić swój wiek i wagę, aby oszacować liczbę kalorii spalanych podczas ćwiczenia. Zachowaj ostrożność, aby się nie potknąć podczas wchodzenia po schodach. Zaleca się utrzymywanie chwytu na poręczach, aby nie upaść.
2. Schodostepy oferują wygodę, korzyści sercowo-naczyniowe i zwykle mniejsze obciążenie stawów niż bieganie na zewnątrz, przy podobnym tempie spalania kalorii. Są zazwyczaj dużo trudniejsze niż inne urządzenia cardio. Osoba ważąca ok. 68 kg spali zazwyczaj ponad 300 kalorii w ciągu 30 minut, w porównaniu do ok. 175 kalorii przy marszu.', NULL, 'free-exercise-db/Step_Mill/0.jpg', 'free_exercise_db'),
  ('step-up-with-knee-raise', 'Wejście na podium z uniesieniem kolana', 'Step-up with Knee Raise', 'motor_coach', 'beginner', array['Siłowe', 'Pośladki'], 'Wejście na skrzynię lub ławkę z uniesieniem kolana drugiej nogi, budujące siłę nóg i równowagę. Wchodzisz na podest jedną nogą, unosząc kolano drugiej maksymalnie wysoko, po czym zmieniasz nogę.', '1. Stań twarzą do skrzyni lub ławki o odpowiedniej wysokości ze stopami razem. To będzie Twoja pozycja startowa.
2. Rozpocznij ruch wchodząc, stawiając lewą stopę na szczycie ławki. Wyprostuj biodro i kolano nogi przedniej, wstając na skrzynię. Stojąc na skrzyni na lewej nodze, ugnij prawe kolano i biodro, unosząc kolano tak wysoko, jak potrafisz.
3. Odwróć ten ruch, aby zejść ze skrzyni, a następnie powtórz sekwencję na drugiej nodze.', NULL, 'free-exercise-db/Step-up_with_Knee_Raise/0.jpg', 'free_exercise_db'),
  ('stiff-leg-barbell-good-morning', 'Good morning ze sztangą na prostych nogach', 'Stiff Leg Barbell Good Morning', 'motor_coach', 'beginner', array['Siłowe', 'Dolny odcinek pleców'], '"Good morning" ze sztangą na barkach: pochylasz się w biodrach z prostymi plecami i niemal prostymi nogami, aż tułów będzie równoległy do podłogi. Mocno angażuje dwugłowe uda, pośladki i dolne plecy.', '1. To ćwiczenie najlepiej wykonywać wewnątrz klatki do przysiadów dla bezpieczeństwa. Na początku ustaw sztangę na stojaku dopasowanym do Twojego wzrostu. Po dobraniu właściwej wysokości i załadowaniu sztangi wejdź pod nią i połóż tylną część barków (nieco poniżej szyi) na gryfie.
2. Trzymaj sztangę obiema rękami po obu stronach i zdejmij ją ze stojaka, najpierw odpychając się nogami, a jednocześnie prostując tułów.
3. Odejdź od stojaka i ustaw nogi w średnim rozstawie na szerokość barków. Cały czas trzymaj głowę uniesioną, ponieważ patrzenie w dół zaburzy Ci równowagę, i utrzymuj proste plecy. To będzie Twoja pozycja startowa.
4. Utrzymując nogi nieruchome, pochyl tułów do przodu, uginając się w biodrach i robiąc wdech. Opuść tułów, aż będzie równoległy do podłogi.
5. Zacznij unosić sztangę, robiąc wydech, prostując tułów z powrotem do pozycji startowej.
6. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Stiff_Leg_Barbell_Good_Morning/0.jpg', 'free_exercise_db'),
  ('stiff-legged-barbell-deadlift', 'Martwy ciąg na prostych nogach ze sztangą', 'Stiff-Legged Barbell Deadlift', 'motor_coach', 'intermediate', array['Siłowe', 'Dwugłowe uda'], 'Martwy ciąg na sztywnych nogach ze sztangą, świetnie rozciągający i wzmacniający dwugłowe uda oraz pośladki. Kolana pozostają niemal proste, a tułów opada z bioder z prostymi plecami, aż poczujesz rozciąganie z tyłu ud.', '1. Chwyć sztangę chwytem nachwytem (dłonie skierowane w dół). Przy dużym ciężarze mogą przydać się ochraniacze na nadgarstki.
2. Stań z tułowiem wyprostowanym i nogami rozstawionymi na szerokość barków lub węższe. Kolana powinny być lekko ugięte. To jest Twoja pozycja startowa.
3. Utrzymując kolana nieruchome, opuść sztangę ponad wierzchem stóp, uginając się w biodrach i zachowując proste plecy. Kontynuuj pochylenie, jakbyś chciał podnieść coś z podłogi, aż poczujesz rozciąganie dwugłowych ud. Wdech wykonaj podczas tego ruchu.
4. Zacznij prostować tułów z powrotem, prostując biodra, aż wrócisz do pozycji startowej. Wydech wykonaj podczas tego ruchu.
5. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Stiff-Legged_Barbell_Deadlift/0.jpg', 'free_exercise_db'),
  ('stiff-legged-dumbbell-deadlift', 'Martwy ciąg na prostych nogach z hantlami', 'Stiff-Legged Dumbbell Deadlift', 'motor_coach', 'beginner', array['Siłowe', 'Dwugłowe uda'], 'Wersja martwego ciągu na sztywnych nogach z hantlami trzymanymi wzdłuż ciała. Opuszczasz hantle z bioder z prostymi plecami i niemal prostymi kolanami, aż poczujesz rozciąganie z tyłu ud.', '1. Chwyć parę hantli, trzymając je przy bokach ciała z wyprostowanymi ramionami.
2. Stań z tułowiem wyprostowanym i nogami rozstawionymi na szerokość barków lub węższe. Kolana powinny być lekko ugięte. To jest Twoja pozycja startowa.
3. Utrzymując kolana nieruchome, opuść hantle ponad wierzchem stóp, uginając się w pasie i zachowując proste plecy. Kontynuuj pochylenie, jakbyś chciał podnieść coś z podłogi, aż poczujesz rozciąganie dwugłowych ud. Wydech wykonaj podczas tego ruchu.
4. Zacznij prostować tułów z powrotem, prostując biodra i pas, aż wrócisz do pozycji startowej. Wdech wykonaj podczas tego ruchu.
5. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Stiff-Legged_Dumbbell_Deadlift/0.jpg', 'free_exercise_db'),
  ('stomach-vacuum', 'Wakuum brzucha', 'Stomach Vacuum', 'motor_coach', 'beginner', array['Rozciąganie', 'Brzuch'], 'Izometryczne ćwiczenie na mięśnie głębokie brzucha: po głębokim wydechu silnie wciągasz żołądek i utrzymujesz pozycję około 20 sekund. Z czasem można wydłużać trzymanie do 40–60 sekund.', '1. Na początku stań prosto ze stopami rozstawionymi na szerokość barków. Połóż dłonie na biodrach. To jest pozycja startowa.
2. Teraz powoli nabierz jak najwięcej powietrza, a następnie zacznij wydychać je maksymalnie, wciągając żołądek jak najmocniej, i utrzymuj tę pozycję. Spróbuj wizualizować sobie pępek dotykający kręgosłupa.
3. Jedno izometryczne napięcie trwa około 20 sekund. Podczas trzymania przez te 20 sekund staraj się oddychać normalnie. Potem nabierz powietrza i wróć żołądkiem do pozycji startowej.
4. Gdy przećwiczysz to ćwiczenie, spróbuj wykonywać je dłużej niż 20 sekund. Wskazówka: Możesz stopniowo dojść do 40–60 sekund.
5. Powtórz zalecaną liczbę serii.', NULL, 'free-exercise-db/Stomach_Vacuum/0.jpg', 'free_exercise_db'),
  ('straight-arm-dumbbell-pullover', 'Przenoszenie hantli za głowę na prostych ramionach', 'Straight-Arm Dumbbell Pullover', 'motor_coach', 'intermediate', array['Siłowe', 'Klatka piersiowa'], 'Pullover z hantlą na prostych ramionach leżąc w poprzek ławki. Opuszczasz hantlę łukiem za głowę, aż poczujesz rozciąganie klatki piersiowej, po czym prowadzisz ją tym samym łukiem z powrotem.', '1. Postaw hantlę pionowo na płaskiej ławce.
2. Upewniając się, że hantla jest pewnie umieszczona na szczycie ławki, połóż się w poprzek ławki (tułów na niej, tworząc krzyż), tak aby na powierzchni leżały tylko barki. Biodra powinny znajdować się poniżej ławki, nogi ugięte ze stopami mocno opartymi o podłogę. Głowa również będzie poza ławką.
3. Złap hantlę obiema rękami i trzymaj ją prosto nad klatką piersiową na wyprostowanych ramionach. Obie dłonie powinny dociskać się do spodu jednego z boków hantli. To będzie Twoja pozycja startowa.
Uwaga: Zawsze upewnij się, że hantla używana do tego ćwiczenia jest pewna. Hantla z poluzowanymi talerzami może się rozpaść i spaść Ci na twarz.
4. Utrzymując ramiona proste, opuszczaj powoli ciężar łukiem za głowę, robiąc wdech, aż poczujesz rozciąganie klatki piersiowej.
5. W tym momencie zawróć hantlę do pozycji startowej tym samym łukiem, którym była opuszczana, robiąc wydech podczas tego ruchu.
6. Przytrzymaj ciężar w pozycji początkowej przez sekundę i powtórz ruch zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Straight-Arm_Dumbbell_Pullover/0.jpg', 'free_exercise_db'),
  ('straight-arm-pulldown', 'Ściąganie drążka na prostych ramionach', 'Straight-Arm Pulldown', 'motor_coach', 'beginner', array['Siłowe', 'Najszersze grzbietu'], 'Ściąganie szerokiego drążka górnego wyciągu na wyprostowanych ramionach, izolujące mięśnie najszersze grzbietu. Tułów pochylony ok. 30 stopni, ramiona proste — ściągasz drążek do ud.', '1. Zacznij od złapania szerokiego drążka górnego bloku maszyny ściągającej chwytem nachwytem (dłonie w dół) szerszym niż szerokość barków. Zrób dwa kroki w tył.
2. Pochyl tułów do przodu w pasie o około 30 stopni, z ramionami całkowicie wyprostowanymi przed Tobą i lekkim ugięciem w łokciach. Jeśli Twoje ramiona nie są całkowicie wyprostowane, musisz zrobić jeszcze krok w tył, aż będą. Kiedy ramiona są w pełni wyprostowane, a tułów lekko pochylony w pasie, napnij najszersze mięśnie grzbietu — wtedy możesz zaczynać.
3. Utrzymując ramiona proste, ściągnij drążek w dół, napinając najszersze mięśnie grzbietu, aż dłonie znajdą się obok boku ud. Wydech wykonaj podczas tego kroku.
4. Utrzymując ramiona proste, wróć do pozycji startowej, robiąc wdech.
5. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Straight-Arm_Pulldown/0.jpg', 'free_exercise_db'),
  ('straight-bar-bench-mid-rows', 'Wiosłowanie sztangą stojąc na ławce', 'Straight Bar Bench Mid Rows', 'motor_coach', 'beginner', array['Siłowe', 'Środek pleców'], 'Wiosłowanie sztangą do tułowia, stojąc na ławce za sztangą. Ściągasz łopatki i uginasz łokcie, przyciągając sztangę kontrolowanym ruchem do torsu.', '1. Połóż załadowaną sztangę na końcu ławki. Stojąc na ławce za sztangą, złap gryf średnim chwytem nachwytem. Stań z biodrami cofniętymi i klatką piersiową uniesioną, zachowując neutralny kręgosłup. To będzie Twoja pozycja startowa.
2. Wiosłuj sztangę do tułowia, ściągając łopatki i uginając łokcie. Używaj kontrolowanego ruchu bez szarpnięć.
3. Po krótkiej pauzie powoli wróć sztangą do pozycji startowej, upewniając się, że schodzi ona do samego dołu.', NULL, 'free-exercise-db/Straight_Bar_Bench_Mid_Rows/0.jpg', 'free_exercise_db'),
  ('straight-raises-on-incline-bench', 'Unoszenie sztangi w przód leżąc na ławce skośnej', 'Straight Raises on Incline Bench', 'motor_coach', 'beginner', array['Siłowe', 'Barki'], 'Leżąc twarzą w dół na ławce skośnej, unosisz sztangę na prostych ramionach przed siebie. Ćwiczenie angażuje przednie aktony i górną partię pleców.', '1. Połóż sztangę na ziemi za głową szczytu ławki skośnej.
2. Połóż się na ławce twarzą w dół. Chwytem nachwytem podnieś sztangę z podłogi, trzymając ramiona proste. Pozwól sztandze swobodnie zwisać w dół. To będzie Twoja pozycja startowa.
3. Na początek unoś sztangę przed głowę, trzymając ramiona wyprostowane.
4. Wróć do pozycji startowej.', NULL, 'free-exercise-db/Straight_Raises_on_Incline_Bench/0.jpg', 'free_exercise_db'),
  ('stride-jump-crossover', 'Przeskok crossover przez skrzynię', 'Stride Jump Crossover', 'motor_coach', 'beginner', array['Plyometryka', 'Uda'], 'Plyometryczny przeskok bokiem przez skrzynię z wymachem ramion i wysokim uniesieniem przeciwległego kolana. Lądujesz po drugiej stronie skrzyni w odwrotnej pozycji i przeskakujesz z powrotem.', '1. Stań z boku skrzyni ze stopą wewnętrzną na jej szczycie, blisko krawędzi.
2. Zacznij od wymachu ramionami w górę, odpychając się górną nogą i skacząc jak najwyżej. Postaraj się dynamicznie unieść przeciwległe kolano w górę.
3. Wyląduj w odwrotnej pozycji niż startowa, po drugiej stronie skrzyni. Stopa, która początkowo była na skrzyni, znajdzie się teraz na ziemi, a przeciwległa stopa na skrzyni.
4. Powtórz ruch, przekładając się z powrotem na drugą stronę.', NULL, 'free-exercise-db/Stride_Jump_Crossover/0.jpg', 'free_exercise_db'),
  ('sumo-deadlift', 'Martwy ciąg sumo', 'Sumo Deadlift', 'motor_coach', 'intermediate', array['Trójbój', 'Dwugłowe uda'], 'Wariant martwego ciągu z bardzo szerokim rozstawem nóg, bardziej angażujący uda i pośladki. Chwytasz sztangę między nogami, opuszczasz biodra i podnosisz sztangę, prostując biodra i kolana.', '1. Zacznij od sztangi załadowanej na ziemi. Podejdź do sztangi tak, aby przetynała środek stóp. Stopy powinny być rozstawione bardzo szeroko, blisko talerzy. Ugnij się w biodrach, aby chwycić sztangę. Ramiona powinny znajdować się bezpośrednio pod barkami, wewnątrz nóg, a możesz zastosować chwyt nachwyt, mieszany lub hakowy. Rozluźnij barki, co w efekcie wydłuża Twoje ramiona.
2. Weź oddech, a następnie opuść biodra, patrząc przed siebie z głową uniesioną i klatką piersiową wypiętą. Odepchnij się od podłogi, rozsuwając stopy na boki, z ciężarem na tylnej połowie stóp. Prostuj biodra i kolana.
3. Gdy sztanga przechodzi przez kolana, odchyl się do tyłu i wepnij biodra w sztangę, ściąga łopatki do siebie.
4. Odłożyć sztangę na ziemię, uginając się w biodrach i kontrolując ciężar podczas opuszczania.', NULL, 'free-exercise-db/Sumo_Deadlift/0.jpg', 'free_exercise_db'),
  ('sumo-deadlift-with-bands', 'Martwy ciąg sumo z gumami oporowymi', 'Sumo Deadlift with Bands', 'motor_coach', 'intermediate', array['Trójbój', 'Dwugłowe uda'], 'Martwy ciąg sumo wzmocniony gumami oporowymi zakładanymi na sztangę pod stopami. Opór rośnie wraz z prostowaniem ciała, dodatkowo obciążając górną fazę ruchu.', '1. Aby robić martwy ciąg z krótkimi gumami, po prostu załóż je na sztangę przed rozpoczęciem i wejdź na nie, aby się ustawić. Upewnij się, że znajdują się pod tylną połową stopy, dokładnie tam, gdzie odpychasz się od podłogi.
2. Zacznij od sztangi załadowanej na ziemi. Podejdź do sztangi tak, aby przetynała środek stóp. Stopy powinny być rozstawione bardzo szeroko, blisko talerzy. Ugnij się w biodrach, aby chwycić sztangę. Ramiona powinny znajdować się bezpośrednio pod barkami, wewnątrz nóg, a możesz zastosować chwyt nachwyt, mieszany lub hakowy.
3. Weź oddech, a następnie opuść biodra, patrząc przed siebie z głową uniesioną i klatką piersiową wypiętą. Odepchnij się od podłogi, rozsuwając stopy na boki, z ciężarem na tylnej połowie stóp. Prostuj biodra i kolana.
4. Gdy sztanga przechodzi przez kolana, odchyl się do tyłu i wepnij biodra w sztangę, ściąga łopatki do siebie.
5. Odłożyć sztangę na ziemię, uginając się w biodrach i kontrolując ciężar podczas opuszczania.', NULL, 'free-exercise-db/Sumo_Deadlift_with_Bands/0.jpg', 'free_exercise_db'),
  ('sumo-deadlift-with-chains', 'Martwy ciąg sumo z łańcuchami', 'Sumo Deadlift with Chains', 'motor_coach', 'intermediate', array['Trójbój', 'Dwugłowe uda'], 'Martwy ciąg sumo obciążony łańcuchami zawieszonymi na sztandze. Im wyżej podnosisz sztangę, tym więcej ogniw unosi się z ziemi i tym większy staje się opór.', '1. Łańcuchy możesz przymocować do tulei sztangi albo po prostu zarzucić ich środek na sztangę, tak aby wzrost ciężaru był większy podczas podnoszenia. Staraj się trzymać końce łańcuchów z dala od talerzy, aby nie uderzać w nie podczas opuszczania ciężaru.
2. Zacznij od sztangi załadowanej na ziemi. Podejdź do sztangi tak, aby przetynała środek stóp. Stopy powinny być rozstawione bardzo szeroko, blisko talerzy. Ugnij się w biodrach, aby chwycić sztangę. Ramiona powinny znajdować się bezpośrednio pod barkami, wewnątrz nóg, a możesz zastosować chwyt nachwyt, mieszany lub hakowy. Rozluźnij barki, co w efekcie wydłuża Twoje ramiona.
3. Weź oddech, a następnie opuść biodra, patrząc przed siebie z głową uniesioną i klatką piersiową wypiętą. Odepchnij się od podłogi, rozsuwając stopy na boki, z ciężarem na tylnej połowie stóp. Prostuj biodra i kolana.
4. Gdy sztanga przechodzi przez kolana, odchyl się do tyłu i wepnij biodra w sztangę, ściąga łopatki do siebie.
5. Odłożyć sztangę na ziemię, uginając się w biodrach i kontrolując ciężar podczas opuszczania.', NULL, 'free-exercise-db/Sumo_Deadlift_with_Chains/0.jpg', 'free_exercise_db'),
  ('superman', 'Superman', 'Superman', 'motor_coach', 'beginner', array['Rozciąganie', 'Dolny odcinek pleców'], 'Wzmocnienie dolnych pleców: leżąc twarzą w dół, jednocześnie unosisz ramiona, nogi i klatkę piersiową nad podłogę i utrzymujesz napięcie przez 2 sekundy. Wyglądasz wtedy niczym lecący Superman.', '1. Na początku połóż się prosto twarzą w dół na podłodze lub macie do ćwiczeń. Twoje ramiona powinny być całkowicie wyciągnięte przed Ciebie. To jest pozycja startowa.
2. Jednocześnie unieś ramiona, nogi i klatkę piersiową nad podłogę i utrzymuj to napięcie przez 2 sekundy. Wskazówka: Napnij dolne plecy, aby uzyskać najlepsze rezultaty z tego ćwiczenia. Pamiętaj o wydechu podczas tego ruchu. Uwaga: Trzymając pozycję napiętą, powinieneś wyglądać jak Superman, gdy leci.
3. Powoli zacznij opuszczać ramiona, nogi i klatkę piersiową z powrotem do pozycji startowej, robiąc wdech.
4. Powtórz zalecaną liczbę powtórzeń przewidzianą w Twoim programie.', NULL, 'free-exercise-db/Superman/0.jpg', 'free_exercise_db'),
  ('supine-chest-throw', 'Rzut piłką lekarską z klatki leżąc na plecach', 'Supine Chest Throw', 'motor_coach', 'beginner', array['Plyometryka', 'Triceps'], 'Eksplozywny wypchnięcie piłki lekarskiej znad klatki piersiowej leżąc na plecach. Piłka wylatuje maksymalnie w górę, a Ty łapiesz ją oburącz po opadnięciu.', '1. To ćwiczenie świetnie sprawdza się przy podaniach z klatki piersiowej, gdy brakuje Ci partnera lub dostatecznie mocnej ściany. Połóż się na plecach z ugiętymi kolanami.
2. Zacznij z piłką na klatce piersiowej, trzymaną obiema rękami od spodu.
3. Wybij się w górę, prostując łokcie, aby rzucić piłkę bezpośrednio nad siebie jak najwyżej.
4. Złap piłkę obiema rękami, gdy opada.', NULL, 'free-exercise-db/Supine_Chest_Throw/0.jpg', 'free_exercise_db'),
  ('supine-one-arm-overhead-throw', 'Jednoręczny rzut piłki znad głowy leżąc', 'Supine One-Arm Overhead Throw', 'motor_coach', 'beginner', array['Plyometryka', 'Brzuch'], 'Rzut piłki lekarskiej jedną ręką znad głowy, leżąc na plecach z ugiętymi kolanami. Siadając, wyrzucasz piłkę maksymalnie daleko przed siebie.', '1. Połóż się na plecach z ugiętymi kolanami. Trzymaj piłkę jedną ręką, całkowicie wyprostowane ramię za głową. To będzie Twoja pozycja startowa.
2. Rozpocznij ruch w barku, rzucając piłkę bezpośrednio przed siebie, gdy siadasz, starając się uzyskać maksymalny dystans.
3. Piłkę można rzucić do partnera lub odbić o ścianę.', NULL, 'free-exercise-db/Supine_One-Arm_Overhead_Throw/0.jpg', 'free_exercise_db'),
  ('supine-two-arm-overhead-throw', 'Oburęczny rzut piłki znad głowy leżąc', 'Supine Two-Arm Overhead Throw', 'motor_coach', 'beginner', array['Plyometryka', 'Brzuch'], 'Rzut piłki lekarskiej oburącz znad głowy, leżąc na plecach z ugiętymi kolanami. Siadając, wyrzucasz piłkę maksymalnie daleko przed siebie, do partnera lub o ścianę.', '1. Połóż się na plecach z ugiętymi kolanami.
2. Trzymaj piłkę obiema rękami, całkowicie wyprostowane ramiona za głową. To będzie Twoja pozycja startowa.
3. Rozpocznij ruch w barkach, rzucając piłkę bezpośrednio przed siebie, gdy siadasz, starając się uzyskać maksymalny dystans.
4. Piłkę można rzucić do partnera lub odbić o ścianę.', NULL, 'free-exercise-db/Supine_Two-Arm_Overhead_Throw/0.jpg', 'free_exercise_db')
on conflict (slug) do nothing;

insert into public.exercises
  (slug, name, name_en, persona_type, level, categories, short_description, detail_full, common_mistakes, photo_path, source)
values
  ('suspended-fallout', 'Fallout na zawieszeniu (TRX)', 'Suspended Fallout', 'motor_coach', 'intermediate', array['Siłowe', 'Brzuch'], 'Zaawansowane ćwiczenie na mięśnie głębokie z uchwytami zawieszonymi na paskach. Trzymając ramiona prosto, pochylasz się coraz dalej w paski, pozwalając barkom się wyprostować, a ramionom unieść się nad głowę.', '1. Dostosuj paski tak, aby uchwyty znajdowały się na odpowiedniej wysokości, poniżej poziomu pasa.
2. Zacznij w staniu, trzymając uchwyty. Pochyl się w paski, przechodząc do pozycji deski do pompień na pochyleniu. To będzie Twoja pozycja startowa.
3. Trzymając ramiona proste, pochyl się jeszcze dalej w paski zawieszenia, przybliżając ciało do ziemi, pozwalając barkom się wyprostować, unosząc ramiona nad głowę.
4. Zachowuj neutralny kręgosłup i trzymaj resztę ciała prosto — barki są jedynymi stawami, które mogą się poruszać.
5. Zatrzymaj się w szczycie napięcia, a następnie wróć do pozycji startowej.', NULL, 'free-exercise-db/Suspended_Fallout/0.jpg', 'free_exercise_db'),
  ('suspended-push-up', 'Pompki na zawieszeniu (TRX)', 'Suspended Push-Up', 'motor_coach', 'beginner', array['Siłowe', 'Klatka piersiowa'], 'Pompki z rękami w uchwytach zawieszonych na paskach, trudniejsze i bardziej angażujące stabilizatory niż klasyczne pompki. Opuszczasz tułów, uginając łokcie, i wracasz do góry.', '1. Zamocuj paski zawieszenia pewnie na szczycie stojaka lub innego obiektu.
2. Pochylając się w paski, weź uchwyt w każdą rękę i przejdź do pozycji deski do pompień. Powinieneś być jak najbliżej równoległości do ziemi, na ile dasz radę, z ramionami całkowicie wyprostowanymi, zachowując dobrą postawę.
3. Utrzymując prosty, usztywniony tułów, opuszczaj się powoli, pozwalając łokciom się ugiąć.
4. Kontynuuj, aż łokcie przełamią kąt 90 stopni, zatrzymaj się na moment przed wyprostem i wróć do pozycji startowej.', NULL, 'free-exercise-db/Suspended_Push-Up/0.jpg', 'free_exercise_db'),
  ('suspended-reverse-crunch', 'Unoszenie kolan do klatki w zawieszeniu (TRX)', 'Suspended Reverse Crunch', 'motor_coach', 'beginner', array['Siłowe', 'Brzuch'], 'Odwrócone spięcie brzucha w pozycji deski z stopami wsuniętymi w uchwyty pasków zawieszenia. Przyciągasz kolana do tułowia, pochylając miednicę i napinając mięśnie brzucha.', '1. Zamocuj zestaw pasków zawieszenia z uchwytami wiszącymi około 30 cm nad ziemią. Ustaw się w pozycji deski do pompień plecami do stojaka.
2. Wsunięte stopy w uchwyty. Powinieneś zachować prostą postawę, nie pozwalając biodrom się zapadać. To będzie Twoja pozycja startowa.
3. Rozpocznij ruch, uginając kolana i biodra, przyciągając kolana do tułowia. Robiąc to, pochyl miednicę do przodu, pozwalając kręgosłupowi się zgiąć.
4. Na szczycie kontrolowanego ruchu wróć do pozycji startowej.', NULL, 'free-exercise-db/Suspended_Reverse_Crunch/0.jpg', 'free_exercise_db'),
  ('suspended-row', 'Wiosłowanie na zawieszeniu (TRX)', 'Suspended Row', 'motor_coach', 'beginner', array['Siłowe', 'Środek pleców'], 'Wiosłowanie własnym ciężarem z uchwytami pasków zawieszenia. Leżysz w pochyleniu z wyprostowanymi ramionami, po czym uginasz łokcie, ściągając ciało do uchwytów.', '1. Zawieś swoje paski na wysokości około klatki piersiowej. Weź uchwyt w każdą rękę i odchyl się do tyłu. Trzymaj ciało wyprostowane, a głowę i klatkę piersiową uniesioną. Twoje ramiona powinny być całkowicie wyprostowane. To będzie Twoja pozycja startowa.
2. Rozpocznij od ugięcia łokci, aby rozpocząć ruch. Jednocześnie wysuwaj łopatki do przodu.
3. Po zakończeniu ruchu zatrzymaj się na moment, a następnie wróć do pozycji startowej.', NULL, 'free-exercise-db/Suspended_Row/0.jpg', 'free_exercise_db'),
  ('suspended-split-squat', 'Wykrok bułgarski na zawieszeniu (TRX)', 'Suspended Split Squat', 'motor_coach', 'intermediate', array['Siłowe', 'Uda'], 'Przysiad wykroczny z tylną nogą w uchwycie pasków zawieszenia. Opuszczasz się uginając przednie kolano i biodro, trzymając ciężar na pięcie nogi przedniej.', '1. Zawieś swoje paski tak, aby uchwyty znajdowały się 45–75 cm od podłogi.
2. Plecami do ustawienia, wsunięte stopę tylną w uchwyt za sobą. Patrz przed siebie z głową uniesioną i klatką piersiową wypiętą, z kolaniem lekko ugiętym. To będzie Twoja pozycja startowa.
3. Opuszczaj się, uginając kolano i biodro, obniżając ciało ku ziemi. Trzymaj ciężar na pięcie stopy i zachowuj postawę przez całe ćwiczenie.
4. Na dole ruchu odwróć ruch, prostując biodro i kolano, aby wrócić do pozycji startowej.', NULL, 'free-exercise-db/Suspended_Split_Squat/0.jpg', 'free_exercise_db'),
  ('svend-press', 'Svend press (ściskanie talerzy)', 'Svend Press', 'motor_coach', 'beginner', array['Siłowe', 'Klatka piersiowa'], 'Wyciskanie dwóch talerzy ściśniętych między dłońmi przed sobą. Izometryczne napięcie utrzymuje klatkę piersiową w pracy przez cały ruch — wypychasz talerze w przód i wracasz do klatki.', '1. Zacznij w pozycji stojącej.
2. Dociśnij do siebie dwa lekkie talerze dłońmi. Trzymaj talerze ściśnięte blisko klatki piersiowej, aby wywołać izometryczne napięcie w mięśniach klatki piersiowej. Palce powinny być skierowane do przodu. To jest pozycja startowa.
3. Ściskając talerze między dłońmi, wypchnij ramiona bezpośrednio przed siebie w kontrolowanym ruchu.
4. Zatrzymaj się na szczycie ruchu, a następnie powoli wróć do pozycji startowej.', NULL, 'free-exercise-db/Svend_Press/0.jpg', 'free_exercise_db'),
  ('t-bar-row-with-handle', 'Wiosłowanie T-bar z uchwytem', 'T-Bar Row with Handle', 'motor_coach', 'beginner', array['Siłowe', 'Środek pleców'], 'Wiosłowanie sztangą typu T-bar osadzoną w landmine lub rogu sali. Ściągasz łopatki i uginasz łokcie, przyciągając ciężar do górnej części brzucha.', '1. Umieść sztangę w landmine lub w rogu, aby uniemożliwić jej przesuwanie. Załaduj odpowiedni ciężar na Twój koniec.
2. Stań nad sztangą i umieść podwójny uchwyt do wiosłowania na sztandze obok tulei. Używając bioder i nóg, podnieś się do pozycji stojącej.
3. Przyjmij szeroki rozstaw z biodrami cofniętymi i klatką piersiową uniesioną. Twoje ramiona powinny być wyprostowane. To będzie Twoja pozycja startowa.
4. Przyciągnij ciężar do górnej części brzucha, ściągając łopatki i uginając łokcie. Nie szarp ciężarem ani nie oszukuj podczas ruchu.
5. Po krótkiej pauzie wróć do pozycji startowej.', NULL, 'free-exercise-db/T-Bar_Row_with_Handle/0.jpg', 'free_exercise_db'),
  ('tate-press', 'Tate press (wyciskanie hantli po skosie)', 'Tate Press', 'motor_coach', 'intermediate', array['Siłowe', 'Triceps'], 'Wariant wyciskania dla tricepsa: leżąc na ławce, opuszczasz hantle ruchem po półkolu do środka, aż dotkną górnej klatki piersiowej, po czym prostujesz ramiona siłą tricepsa.', '1. Połóż się na płaskiej ławce z hantlą w każdej ręce na udach. Dłonie powinny być skierowane ku sobie.
2. Pomagając sobie udami, podrzuć hantle — jedną ręką po drugiej — aby móc trzymać je przed sobą na szerokość barków. Uwaga: trzymając hantle przed sobą, upewnij się, że Twoje ramiona są rozstawione szerzej niż barki, w chwycie nachwyt (dłonie do przodu). Pozwól łokciom skręcić na boki. To jest Twoja pozycja startowa.
3. Utrzymując górne ramiona nieruchome, powoli prowadź hantle do środka i w dół ruchem po półkolu, aż dotkną górnej części klatki piersiowej, robiąc wdech. Zachowuj pełną kontrolę nad hantlami przez cały czas i nie poruszaj górnymi ramionami ani nie opieraj hantli o klatkę piersiową.
4. Robiąc wydech, prowadź hantle w górę, używając tricepsów i tego samego półkolistego ruchu, ale w odwrotnym kierunku. Staraj się utrzymać hantle blisko siebie podczas unoszenia. Zablokuj ramiona w pozycji napiętej, przytrzymaj przez sekundę, a potem zacznij powoli opuszczać znowu. Wskazówka: Opuszczanie powinno trwać co najmniej dwa razy dłużej niż unoszenie.
5. Powtórz ruch zalecaną liczbą powtórzeń z Twojego programu treningowego.', NULL, 'free-exercise-db/Tate_Press/0.jpg', 'free_exercise_db'),
  ('the-straddle', 'Szpagat w przód siedząc (straddle)', 'The Straddle', 'motor_coach', 'beginner', array['Rozciąganie', 'Dwugłowe uda'], 'Rozciąganie przywodzicieli i tylnej części ud: siedząc rozłóż nogi szeroko w literę V i pochyl się do przodu tak daleko, jak to możliwe. Przytrzymaj 10–20 sekund.', '1. Zacznij w pozycji siedzącej, z wyprostowanym tułowiem. Zacznij od wyprostowania nóg przed sobą w literę V.
2. Z dłońmi na podłodze pochyl się do przodu tak daleko, jak to możliwe. Przytrzymaj przez 10–20 sekund.', NULL, 'free-exercise-db/The_Straddle/0.jpg', 'free_exercise_db'),
  ('thigh-abductor', 'Odwodzenie ud na maszynie (abdukcja)', 'Thigh Abductor', 'motor_coach', 'beginner', array['Siłowe', 'Odwodziciele'], 'Ćwiczenie na maszynie odwodzącej nogi na boki, celujące w boczne partie ud i pośladków. Rozsuwasz nogi przeciw oporowi maszyny, a potem kontrolowanie wracasz do pozycji startowej.', '1. Na początku usiądź na maszynie odwodzącej i wybierz ciężar, z którym czujesz się komfortowo. Kiedy nogi są prawidłowo ustawione, złap uchwyty po obu stronach. Cały górny odcinek ciała (od pasa w górę) powinien pozostać nieruchomy. To jest pozycja startowa.
2. Powoli dociskaj nogami maszynę, rozsuwając nogi od siebie, robiąc wydech.
3. Wyczuć napięcie przez sekundę i zacznij wracać nogami do pozycji startowej, robiąc wdech. Uwaga: Pamiętaj, aby trzymać górną część ciała nieruchomo, aby zapobiec kontuzjom.
4. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Thigh_Abductor/0.jpg', 'free_exercise_db'),
  ('thigh-adductor', 'Przywodzenie ud na maszynie (addukcja)', 'Thigh Adductor', 'motor_coach', 'beginner', array['Siłowe', 'Przywodziciele'], 'Ćwiczenie na maszynie przywodzącej nogi do środka, wzmacniające wewnętrzne partie ud. Ściskasz nogi razem przeciw oporowi, a potem powoli wracasz do pozycji startowej.', '1. Na początku usiądź na maszynie przywodzącej i wybierz ciężar, z którym czujesz się komfortowo. Kiedy nogi są prawidłowo ustawione na poduszkach maszyny, złap uchwyty po obu stronach. Cały górny odcinek ciała (od pasa w górę) powinien pozostać nieruchomy. To jest pozycja startowa.
2. Powoli dociskaj nogami maszynę, zbliżając nogi do siebie, robiąc wydech.
3. Wyczuć napięcie przez sekundę i zacznij wracać nogami do pozycji startowej, robiąc wdech. Uwaga: Pamiętaj, aby trzymać górną część ciała nieruchomo i unikać szybkich szarpanych ruchów, aby zapobiec kontuzjom.
4. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Thigh_Adductor/0.jpg', 'free_exercise_db'),
  ('tire-flip', 'Przerzucanie opony', 'Tire Flip', 'motor_coach', 'intermediate', array['Strongman', 'Uda'], 'Silowe przerzucanie ciężkiej opony: wgryzasz się w nią klatką piersiową, podnosisz prostując biodra, kolana i kostki, po czym pchasz ją, doprowadzając do przewrócenia. Powtarzasz w miarę potrzeby.', '1. Zacznij od chwytu dolnej części opony za bieżnik, z stopami cofniętymi nieco do tyłu. Twoja klatka piersiowa powinna wbijać się w oponę.
2. Aby podnieść oponę, prostuj biodra, kolana i kostki, wbijając się w oponę i w górę.
3. Gdy opona osiągnie kąt 45 stopni, zrób krok do przodu i wbij kolano w oponę. Przy okazji zmień chwyt na górną część opony i popchnij ją do przodu jak najmocniej, aby dokończyć przewrócenie. Powtarzaj w miarę potrzeby.', NULL, 'free-exercise-db/Tire_Flip/0.jpg', 'free_exercise_db'),
  ('toe-touchers', 'Dotykanie palców leżąc (toe touchers)', 'Toe Touchers', 'motor_coach', 'beginner', array['Rozciąganie', 'Brzuch'], 'Spięcie brzucha leżąc: z nogami uniesionymi niemal pionowo unosisz tułów i próbujesz dotknąć palców stóp wyprostowanymi ramionami pod kątem 45 stopni. Dolne plecy pozostają dociśnięte do podłogi.', '1. Na początku połóż się na podłodze lub macie z plecami dociśniętymi do podłogi. Twoje ramiona powinny leżeć wzdłuż boków, z dłońmi skierowanymi w dół.
2. Twoje nogi powinny być złączone. Powoli unieś nogi w górę, aż będą niemal prostopadłe do podłoga, z lekkim ugięciem w kolanach. Twoje stopy powinny być równolegle do podłogi.
3. Poruszaj ramionami tak, aby były całkowicie wyprostowane pod kątem 45 stopni od podłogi. To jest pozycja startowa.
4. Trzymając dolne plecy dociśnięte do podłogi, powoli unoś tułów i próbuj dłońmi dotknąć palców stóp. Pamiętaj o wydechu podczas tej części ćwiczenia.
5. Powoli zacznij opuszczać tułów i ramiona z powrotem do pozycji startowej, robiąc wdech. Pamiętaj, aby trzymać ramiona prosto, wskazując ku palcom stóp.
6. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Toe_Touchers/0.jpg', 'free_exercise_db'),
  ('torso-rotation', 'Rotacje tułowia z piłką', 'Torso Rotation', 'motor_coach', 'beginner', array['Rozciąganie', 'Brzuch'], 'Dynamiczna rotacja tułowia z piłką gimnastyczną trzymaną oburącz przed sobą. Obracasz tors na boki, śledząc wzrokiem piłkę, po 10–20 powtórzeń.', '1. Stań prosto, trzymając piłkę gimnastyczną obiema rękami. Wyprostuj ramiona, aby piłka znajdowała się prosto przed Tobą. To będzie Twoja pozycja startowa.
2. Obróć tułów na jedną stronę, śledząc wzrokiem piłkę podczas ruchu. Teraz obróć się z powrotem w przeciwną stronę. Powtórz 10–20 razy.', NULL, 'free-exercise-db/Torso_Rotation/0.jpg', 'free_exercise_db'),
  ('trail-running-walking', 'Bieganie / marsz w terenie', 'Trail Running/Walking', 'motor_coach', 'beginner', array['Cardio', 'Uda'], 'Bieganie lub wędrówki po szlakach natychmiast pobudzają krążenie i serce. Mięśnie łydek i pośladków pracują przy podejściach, a kolana i stawy amortyzują zejścia — warto schodzić mniejszymi krokami z ugiętymi kolanami.', '1. Bieganie lub wędrówka po szlakach natychmiast rozpędza krew i przyspiesza bicie serca. Upewnij się, że masz dobre buty. Kiedy używasz mięśni łydek i pośladków, aby wspinać się pod górę, kolana, stawy i kostki absorbują większość uderzeń przy zejściu. Schodząc w dół, rób mniejsze kroki, utrzymuj kolana ugięte, aby zmniejszyć wstrząsy, i zwolnij, aby uniknąć upadku.
2. Osoba ważąca ok. 68 kg może spalić ponad 200 kalorii w ciągu 30 minut marszu pod górę, w porównaniu do 175 kalorii na płaskim terenie. Jeśli biegniesz po szlaku, ta sama osoba może spalić znacznie ponad 500 kalorii w ciągu 30 minut.', NULL, 'free-exercise-db/Trail_Running_Walking/0.jpg', 'free_exercise_db'),
  ('trap-bar-deadlift', 'Martwy ciąg z trap barem (grifem sześciokątnym)', 'Trap Bar Deadlift', 'motor_coach', 'beginner', array['Siłowe', 'Uda'], 'Martwy ciąg wykonywany grifem sześciokątnym (hex bar), z uchwytami po bokach ciała. Bardziej przyjazny dla pleców niż wersja klasyczna — prostujesz biodra i kolana, odpychając się piętami.', '1. Do tego ćwiczenia załaduj trap bar, znany także jako grif sześciokątny, odpowiednim ciężarem, odpoczywającym na ziemi. Stań w centrum przyrządu i chwyć oba uchwyty.
2. Opuść biodra, patrz przed siebie i utrzymuj klatkę piersiową uniesioną.
3. Rozpocznij ruch, odpychając się piętami i prostując biodra i kolana. Unikaj zaokrąglania pleców przez cały czas.
4. Po zakończeniu ruchu odłożyć ciężar na ziemię pod kontrolą.', NULL, 'free-exercise-db/Trap_Bar_Deadlift/0.jpg', 'free_exercise_db'),
  ('tricep-dumbbell-kickback', 'Prostowanie ramienia w tył z hantlą (kickback)', 'Tricep Dumbbell Kickback', 'motor_coach', 'beginner', array['Siłowe', 'Triceps'], 'Kickback tricepsa: w pochyleniu tułowia z ramieniem przyłożonym do ciała prostujesz przedramię w tył, napinając triceps. Porusza się tylko przedramię.', '1. Zacznij z hantlą w każdej ręce, dłońmi skierowanymi ku tułowiowi. Trzymaj plecy proste z lekkim ugięciem kolan i pochyl się do przodu w pasie. Twój tułów powinien być niemal równoległy do podłogi. Pamiętaj, aby trzymać głowę uniesioną. Twoje górne ramiona powinny być blisko tułowia i równoległe do podłogi. Twoje przedramiona powinny być skierowane ku podłodze, gdy trzymasz ciężary. Między przedramieniem a górnym ramieniem powinien powstać kąt 90 stopni. To jest Twoja pozycja startowa.
2. Teraz, utrzymując górne ramiona nieruchome, zrób wydech i użyj tricepsa, aby unieść ciężary, aż ramię będzie całkowicie wyprostowane. Skup się na poruszaniu przedramieniem.
3. Po krótkiej pauzie w górnym napięciu zrób wdech i powoli opuść hantle z powrotem do pozycji startowej.
4. Powtórz ruch zalecaną liczbą powtórzeń.', NULL, 'free-exercise-db/Tricep_Dumbbell_Kickback/0.jpg', 'free_exercise_db'),
  ('tricep-side-stretch', 'Boczne rozciąganie tricepsa', 'Tricep Side Stretch', 'motor_coach', 'beginner', array['Rozciąganie', 'Triceps'], 'Proste rozciąganie tricepsa: przenosisz ramię przez ciało nad przeciwległym barkiem i delikatnie dociskasz łokieć drugą dłonią, czując rozciąganie z tyłu ramienia. Powtarzasz na drugiej stronie.', '1. Przenieś prawe ramię przez ciało nad lewy bark, trzymając łokieć lewą dłonią, aż poczujesz rozciąganie tricepsa. Następnie powtórz na drugie ramię.', NULL, 'free-exercise-db/Tricep_Side_Stretch/0.jpg', 'free_exercise_db'),
  ('triceps-overhead-extension-with-rope', 'Francuskie wyciskanie z liną dolnego bloku', 'Triceps Overhead Extension with Rope', 'motor_coach', 'beginner', array['Siłowe', 'Triceps'], 'Prostowanie ramion nad głowę z liną dolnego bloku, stojąc tyłem do maszyny. Łokcie skierowane w górę pozostają na miejscu, a Ty prostujesz ramiona, unosząc dłonie nad głowę.', '1. Zamocuj linę na dolnym bloku. Po wybraniu odpowiedniego ciężaru złap linę obiema rękami i odwróć się plecami do wyciągu.
2. Ustaw dłonie za głową z łokciami skierowanymi prosto w górę. Łokcie powinny startować ugięte, a możesz rozstawić nogi i delikatnie odchylić się od maszyny, aby uzyskać większą stabilność. To będzie Twoja pozycja startowa.
3. Aby wykonać ruch, prostuj łokieć, utrzymując górne ramię na miejscu, unosząc dłonie nad głowę.
4. Napnij tricepsy na szczycie ruchu, a następnie powoli opuść ciężar z powrotem do pozycji startowej.', NULL, 'free-exercise-db/Triceps_Overhead_Extension_with_Rope/0.jpg', 'free_exercise_db'),
  ('triceps-pushdown', 'Prostowanie ramion na wyciągu (pushdown)', 'Triceps Pushdown', 'motor_coach', 'beginner', array['Siłowe', 'Triceps'], 'Klasyczne prostowanie ramion na wyciągu górnym z drążkiem w nachwycie. Łokcie przyklejone do tułowia, a Ty ściągasz drążek w dół, aż ramiona są całkowicie wyprostowane przy udach.', '1. Zamocuj prostą lub kanciastą drążkę na górnym bloku i złap ją chwytem nachwytem (dłonie skierowane w dół) na szerokość barków.
2. Stojąc prosto z wyprostowanym tułowiem i bardzo małym pochyleniem do przodu, przyciągnij górne ramiona blisko ciała i prostopadle do podłoża. Przedramiona powinny wskazywać w górę ku bloczkowi, trzymając drążek. To jest Twoja pozycja startowa.
3. Używając tricepsów, ściągnij drążek w dół, aż dotknie przodu ud, a ramiona będą całkowicie wyprostowane, prostopadłe do podłoża. Górne ramiona powinny zawsze pozostawać nieruchomo przy tułowiu, a poruszać się powinny tylko przedramiona. Zrób wydech podczas tego ruchu.
4. Po sekundzie trzymania w pozycji napiętej prowadź drążek powoli w górę do punktu startowego. Zrób wdech podczas tego kroku.
5. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Triceps_Pushdown/0.jpg', 'free_exercise_db'),
  ('triceps-pushdown-rope-attachment', 'Prostowanie ramion na wyciągu z liną', 'Triceps Pushdown - Rope Attachment', 'motor_coach', 'beginner', array['Siłowe', 'Triceps'], 'Wariant pushdown z liną wyciągu górnego w chwycie neutralnym. Na końcu ruchu rozchylasz boki liny na boki ud, mocno napinając tricepsy.', '1. Zamocuj linę na górnym bloku i złap ją chwytem neutralnym (dłonie skierowane ku sobie).
2. Stojąc prosto z wyprostowanym tułowiem i bardzo małym pochyleniem do przodu, przyciągnij górne ramiona blisko ciała i prostopadle do podłoża. Przedramiona powinny wskazywać w górę ku bloczkowi, trzymając linę dłońmi skierowanymi ku sobie. To jest Twoja pozycja startowa.
3. Używając tricepsów, ściągnij linę w dół, rozchylając każdy bok liny ku bokom ud. Na końcu ruchu ramiona są całkowicie wyprostowane i prostopadłe do podłoża. Górne ramiona powinny zawsze pozostawać nieruchomo przy tułowiu, a poruszać się powinny tylko przedramiona. Zrób wydech podczas tego ruchu.
4. Po sekundzie trzymania w pozycji napiętej prowadź linę powoli w górę do punktu startowego. Zrób wdech podczas tego kroku.
5. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Triceps_Pushdown_-_Rope_Attachment/0.jpg', 'free_exercise_db'),
  ('triceps-pushdown-v-bar-attachment', 'Prostowanie ramion na wyciągu z uchwytem V', 'Triceps Pushdown - V-Bar Attachment', 'motor_coach', 'beginner', array['Siłowe', 'Triceps'], 'Pushdown tricepsa z uchwytem w kształcie litery V na górnym bloku. Technika identyczna jak przy drążku: łokcie przy tułowiu, ściągasz uchwyt w dół do pełnego wyprostu ramion.', '1. Zamocuj uchwyt V na górnym bloku i złap go chwytem nachwytem (dłonie skierowane w dół) na szerokość barków.
2. Stojąc prosto z wyprostowanym tułowiem i bardzo małym pochyleniem do przodu, przyciągnij górne ramiona blisko ciała i prostopadle do podłoża. Przedramiona powinny wskazywać w górę ku bloczkowi, trzymając drążek. Kciuki powinny być wyżej niż mały palec. To jest Twoja pozycja startowa.
3. Używając tricepsów, ściągnij drążek w dół, aż dotknie przodu ud, a ramiona będą całkowicie wyprostowane, prostopadłe do podłoża. Górne ramiona powinny zawsze pozostawać nieruchomo przy tułowiu, a poruszać się powinny tylko przedramiona. Zrób wydech podczas tego ruchu.
4. Po sekundzie trzymania w pozycji napiętej prowadź uchwyt V powoli w górę do punktu startowego. Zrób wdech podczas tego kroku.
5. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Triceps_Pushdown_-_V-Bar_Attachment/0.jpg', 'free_exercise_db'),
  ('triceps-stretch', 'Rozciąganie tricepsa', 'Triceps Stretch', 'motor_coach', 'beginner', array['Rozciąganie', 'Triceps'], 'Podstawowe rozciąganie tricepsa: sięgasz dłonią za głowę, chwytasz łokieć i delikatnie pociągasz. Przytrzymujesz 10–20 sekund, po czym zmieniasz stronę.', '1. Sięgnij dłonią za głowę, złap łokieć i delikatnie pociągnij. Przytrzymaj przez 10–20 sekund, a następnie zmień strony.', NULL, 'free-exercise-db/Triceps_Stretch/0.jpg', 'free_exercise_db'),
  ('tuck-crunch', 'Spięcie brzucha ze skrzyżowanymi nogami', 'Tuck Crunch', 'motor_coach', 'beginner', array['Siłowe', 'Brzuch'], 'Crunch brzucha z nogami skrzyżowanymi kostkami i uniesionymi w górę. Z ramionami skrzyżowanymi na klatce piersiowej unosisz tułów, trzymając dolne plecy dociśnięte do podłogi.', '1. Na początku połóż się na podłodze lub macie z plecami dociśniętymi do podłogi. Twoje ramiona powinny leżeć wzdłuż boków, z dłońmi skierowanymi w dół.
2. Twoje nogi powinny być skrzyżowane przez owinięcie jednej kostki wokół drugiej. Powoli unieś nogi w górę, aż uda będą prostopadłe do podłogi, z lekkim ugięciem kolan. Uwaga: Twoje kolana i palce stóp powinny być równolegle do podłogi, w przeciwieństwie do ud.
3. Przenieś ramiona z podłogi i skrzyżuj je tak, aby spoczywały na klatce piersiowej. To jest pozycja startowa.
4. Trzymając dolne plecy dociśnięte do podłogi, powoli unoś tułów. Pamiętaj o wydechu podczas tej części ćwiczenia.
5. Powoli zacznij opuszczać tułów z powrotem do pozycji startowej, robiąc wdech.
6. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Tuck_Crunch/0.jpg', 'free_exercise_db'),
  ('two-arm-dumbbell-preacher-curl', 'Uginanie ramion z hantlami na modlitewniku', 'Two-Arm Dumbbell Preacher Curl', 'motor_coach', 'beginner', array['Siłowe', 'Biceps'], 'Oburęczne uginanie hantli na modlitewniku, mocno izolujące biceps. Z ramionami opartymi na podparciu opuszczasz hantle do pełnego rozciągnięcia bicepsa, a potem uginasz do pełnego napięcia.', '1. Złap hantlę każdą ręką i połóż górne ramiona na modlitewniku lub ławce skośnej. Hantle powinny być trzymane na wysokości barków. To będzie Twoja pozycja startowa.
2. Robiąc wdech, powoli opuszczaj hantle, aż Twoje górne ramię będzie wyprostowane, a biceps całkowicie rozciągnięty.
3. Robiąc wydech, użyj bicepsa, aby ugiąć ciężary w górę, aż biceps będzie całkowicie napięty, a hantle na wysokości barków.
4. Mocno napnij biceps przez sekundę w pozycji napiętej i powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Two-Arm_Dumbbell_Preacher_Curl/0.jpg', 'free_exercise_db'),
  ('two-arm-kettlebell-clean', 'Clean z dwoma kettlebellami', 'Two-Arm Kettlebell Clean', 'motor_coach', 'intermediate', array['Siłowe', 'Barki'], 'Wybuchowe podniesienie dwóch kettlebelli z ziemi na barki jednym ruchem. Siłujesz nogami i biodrami, a przy końcu ruchu obracasz nadgarstki, aby kettlebele spoczęły na barkach.', '1. Połóż dwa kettlebele między stopami. Aby przyjąć pozycję startową, cofnij pośladki i patrz prosto przed siebie.
2. Podnieś kettlebele na barki (clean), prostując nogi i biodra, gdy unosisz kettleble ku barkom. Obróć przy tym nadgarstki.
3. Opuść kettleble z powrotem do pozycji startowej i powtórz.', NULL, 'free-exercise-db/Two-Arm_Kettlebell_Clean/0.jpg', 'free_exercise_db'),
  ('two-arm-kettlebell-jerk', 'Jerck z dwoma kettlebellami', 'Two-Arm Kettlebell Jerk', 'motor_coach', 'intermediate', array['Siłowe', 'Barki'], 'Dynamiczne wyrzut dwóch kettlebelli nad głowę: po cleanie na barki robisz krótki przysiad, wyrzucasz ciężary w górę i wpadasz pod nie drugim przysiadem, kończąc z ramionami zablokowanymi nad głową.', '1. Wykonaj clean dwóch kettlebelli na barki. Podnieś kettleble na barki, prostując nogi i biodra, gdy wymachujesz kettleblami ku barkom. Obróć przy tym nadgarstki tak, aby dłonie były skierowane do przodu. Zejdź do przysiadu o kilka centymetrów i gwałtownie odwróć ruch, wyrzucając oba kettleble nad głowę. Bezpośrednio po pierwszym wybiciu znów zejdź do przysiadu i wpadnij pod kettleble. Gdy kettleble są zablokowane nad głową, wstań prosto, aby zakończyć ćwiczenie.', NULL, 'free-exercise-db/Two-Arm_Kettlebell_Jerk/0.jpg', 'free_exercise_db'),
  ('two-arm-kettlebell-military-press', 'Wojskowe wyciskanie dwóch kettlebelli', 'Two-Arm Kettlebell Military Press', 'motor_coach', 'intermediate', array['Siłowe', 'Barki'], 'Wyciskanie dwóch kettlebelli nad głowę z pozycji na barkach. Gdy ciężary mijają głowę, odchylasz się lekko w tył, a po wyciskaniu napinasz najszersze grzbietu, pośladki i brzuch dla stabilności.', '1. Wykonaj clean dwóch kettlebelli na barki. Podnieś kettleble na barki, prostując nogi i biodra, gdy wymachujesz kettleblami ku barkom. Obróć przy tym nadgarstki tak, aby dłonie były skierowane do przodu.
2. Wyciśnij kettleble w górę i na zewnątrz. Gdy kettleble mijają Twoją głowę, pochyl się w ciężary tak, aby kettleble znalazły się w pozycji rack za głową. Pamiętaj, aby napnąć najszersze mięśnie grzbietu, pośladki i brzuch dla dodatkowej stabilności.', NULL, 'free-exercise-db/Two-Arm_Kettlebell_Military_Press/0.jpg', 'free_exercise_db'),
  ('two-arm-kettlebell-row', 'Wiosłowanie dwoma kettlebellami', 'Two-Arm Kettlebell Row', 'motor_coach', 'intermediate', array['Siłowe', 'Środek pleców'], 'Wiosłowanie oburącz dwoma kettlebellami w pochyleniu. Ściągasz łopatki i uginasz łokcie, przyciągając ciężary do brzucha, z plecami utrzymywanymi prostymi.', '1. Połóż dwa kettleble przed stopami. Lekko ugnij kolana, a następnie maksymalnie wypchnij pośladki do tyłu, pochylając się, aby przyjąć pozycję startową.
2. Złap oba kettleble i przyciągnij je do brzucha, ściągając łopatki i uginając łokcie. Trzymaj plecy proste. Opuść i powtórz.', NULL, 'free-exercise-db/Two-Arm_Kettlebell_Row/0.jpg', 'free_exercise_db'),
  ('underhand-cable-pulldowns', 'Ściąganie drążka podchwytem', 'Underhand Cable Pulldowns', 'motor_coach', 'beginner', array['Siłowe', 'Najszersze grzbietu'], 'Ściąganie szerokiego drążka górnego wyciągu chwytem podchwytem (dłonie do siebie), celujące w mięśnie najszersze grzbietu. Ściągasz drążek do górnej klatki piersiowej, ściągając łokcie w dół i do tyłu.', '1. Usiądź na maszynie ściągającej z szerokim drążkiem zamocowanym na górnym bloczku. Dostosuj poduszkę kolanową maszyny do swojego wzrostu. Te poduszki uniemożliwią uniesienie ciała przez opór przymocowany do drążka.
2. Złap drążek ściągający dłońmi skierowanymi ku tułowiowi (chwyt podchwytem). Upewnij się, że dłonie są umieszczone bliżej niż szerokość barków.
3. Mając oba ramiona wyprostowane przed sobą i trzymając drążek w wybranym rozstawie chwytu, cofnij tułów o około 30 stopni, tworząc wygięcie w odcinku lędźwiowym i wypinając klatkę piersiową. To jest Twoja pozycja startowa.
4. Robiąc wydech, ściągnij drążek w dół, aż dotknie Twojej górnej klatki piersiowej, prowadząc barki i górne ramiona w dół i do tyłu. Wskazówka: Skup się na ściskaniu mięśni pleców, gdy osiągniesz całkowicie napiętą pozycję, i trzymaj łokcie blisko ciała. Górna część tułowia powinna pozostać nieruchoma, gdy przyciągasz drążek do siebie — poruszać się powinny tylko ramiona. Przedramiona nie powinny wykonywać żadnej innej pracy niż trzymanie drążka.
5. Po sekundzie w pozycji napiętej, robiąc wdech, powoli prowadź drążek z powrotem do pozycji startowej, gdy Twoje ramiona są całkowicie wyprostowane, a najszersze mięśnie grzbietu całkowicie rozciągnięte.
6. Powtórz ten ruch zalecaną liczbą powtórzeń.', NULL, 'free-exercise-db/Underhand_Cable_Pulldowns/0.jpg', 'free_exercise_db'),
  ('upper-back-leg-grab', 'Objęcie ud z przodem do kolan', 'Upper Back-Leg Grab', 'motor_coach', 'beginner', array['Rozciąganie', 'Dwugłowe uda'], 'Rozciąganie tyłu ud i środkowych pleców: siedząc pochylasz się do przodu, obejmując uda od spodu obiema rękami, i opuszczasz klatkę piersiową ku kolanom.', '1. Siedząc, pochyl się do przodu, aby objąć uda od spodu obiema rękami.
2. Trzymaj kolana razem i nogi wyprostowane, opuszczając klatkę piersiową ku kolanom. Możesz też rozciągać środkową część pleców, odpychając plecy od kolan, gdy je obejmujesz.', NULL, 'free-exercise-db/Upper_Back-Leg_Grab/0.jpg', 'free_exercise_db'),
  ('upper-back-stretch', 'Rozciąganie górnej części pleców', 'Upper Back Stretch', 'motor_coach', 'beginner', array['Rozciąganie', 'Środek pleców'], 'Szybkie rozciąganie górnej części pleców: splecione palce z kciukami skierowanymi w dół, ramiona zaokrąglone i dłonie wyciągnięte do przodu.', '1. Splić palce z kciukami skierowanymi w dół, zaokrąglij barki, sięgając dłońmi do przodu.', NULL, 'free-exercise-db/Upper_Back_Stretch/0.jpg', 'free_exercise_db'),
  ('upright-barbell-row', 'Wiosłowanie sztangi wzdłuż tułowia', 'Upright Barbell Row', 'motor_coach', 'beginner', array['Siłowe', 'Barki'], 'Unoś sztangi wzdłuż ciała do brody, prowadząc ruch łokciami. Ćwiczenie buduje boczne aktony barków i górną partię pleców (trapez).', '1. Złap sztangę chwytem nachwytem nieco węższym niż szerokość barków. Sztanga powinna spoczywać na wierzchu ud, z ramionami wyprostowanymi i lekkim ugięciem w łokciach. Twoje plecy powinny być również proste. To będzie Twoja pozycja startowa.
2. Teraz zrób wydech i użyj bocznych części barków, aby unieść sztangę, prowadząc łokcie w górę i na boki. Trzymaj sztangę blisko ciała podczas unoszenia. Kontynuuj unoszenie, aż sztanga niemal dotknie Twojej brody. Wskazówka: To łokcie powinny prowadzić ruch i zawsze być wyżej niż przedramiona. Pamiętaj, aby trzymać tułów nieruchomo i zatrzymać się na sekundę na szczycie ruchu.
3. Opuść sztangę powoli z powrotem do pozycji startowej. Zrób wdech podczas tej części ruchu.
4. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Upright_Barbell_Row/0.jpg', 'free_exercise_db'),
  ('upright-cable-row', 'Wiosłowanie na wyciągu wzdłuż tułowia', 'Upright Cable Row', 'motor_coach', 'intermediate', array['Siłowe', 'Czworoboczne'], 'Wariant upright row z drążkiem dolnego wyciągu: unoś drążek wzdłuż ciała do brody, prowadząc ruch łokciami. Angażuje boczne aktony barków i trapez.', '1. Złap prosty uchwyt przymocowany do dolnego bloku chwytem nachwytem (dłonie skierowane ku udom) nieco węższym niż szerokość barków. Drążek powinien spoczywać na wierzchu ud. Twoje ramiona powinny być wyprostowane z lekkim ugięciem w łokciach, a plecy proste. To będzie Twoja pozycja startowa.
2. Użyj bocznych części barków, aby unieść drążek wyciągu, robiąc wydech. Drążek powinien być blisko ciała podczas unoszenia. Kontynuuj unoszenie, aż niemal dotknie Twojej brody. Wskazówka: To łokcie powinny prowadzić ruch. Podczas unoszenia drążka Twoje łokcie powinny zawsze być wyżej niż przedramiona. Ponadto trzymaj tułów nieruchomo i zatrzymaj się na sekundę na szczycie ruchu.
3. Opuść drążek powoli z powrotem do pozycji startowej. Zrób wdech podczas tej części ruchu.
4. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Upright_Cable_Row/0.jpg', 'free_exercise_db'),
  ('upright-row-with-bands', 'Wiosłowanie wzdłuż tułowia z gumą oporową', 'Upright Row - With Bands', 'motor_coach', 'beginner', array['Siłowe', 'Czworoboczne'], 'Upright row wykonywany z gumą oporową stojąc na niej: unoś uchwyty wzdłuż ciała do brody, prowadząc ruch łokciami. Angażuje boczne aktony barków i trapez.', '1. Na początku stań na gumie do ćwiczeń tak, aby napięcie zaczynało się przy wyprostowanych ramionach. Złap uchwyty chwytem nachwytem (dłonie skierowane ku udom) nieco węższym niż szerokość barków. Uchwyty powinny spoczywać na wierzchu ud. Twoje ramiona powinny być wyprostowane z lekkim ugięciem w łokciach, a plecy proste. To będzie Twoja pozycja startowa.
2. Użyj bocznych części barków, aby unieść uchwyty, robiąc wydech. Uchwyty powinny być blisko ciała podczas unoszenia. Kontynuuj unoszenie uchwytów, aż niemal dotkną Twojej brody. Wskazówka: To łokcie powinny prowadzić ruch. Podczas unoszenia uchwytów Twoje łokcie powinny zawsze być wyżej niż przedramiona. Ponadto trzymaj tułów nieruchomo i zatrzymaj się na sekundę na szczycie ruchu.
3. Opuść uchwyty powoli z powrotem do pozycji startowej. Zrób wdech podczas tej części ruchu.
4. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Upright_Row_-_With_Bands/0.jpg', 'free_exercise_db'),
  ('upward-stretch', 'Rozciąganie w górę', 'Upward Stretch', 'motor_coach', 'beginner', array['Rozciąganie', 'Barki'], 'Delikatne rozciąganie ramion i górnej części ciała: wyciągasz obie dłonie prosto nad głowę z dłońmi złączonymi i powoli pchasz je w górę i do tyłu.', '1. Wyprostuj obie dłonie prosto nad głowę, z dłońmi stykającymi się.
2. Powoli pchaj dłonie w górę i do tyłu, trzymając plecy proste.', NULL, 'free-exercise-db/Upward_Stretch/0.jpg', 'free_exercise_db'),
  ('v-bar-pulldown', 'Ściąganie drążka V na wyciągu', 'V-Bar Pulldown', 'motor_coach', 'intermediate', array['Siłowe', 'Najszersze grzbietu'], 'Ściąganie uchwytu V górnego wyciągu chwytem neutralnym, celujące w mięśnie najszersze grzbietu. Ściągasz uchwyt w dół, aż klatka piersiowa niemal go dotknie, ściągając łopatki.', '1. Usiądź na maszynie ściągającej z uchwytem V zamocowanym na górnym bloczku.
2. Dostosuj poduszkę kolanową maszyny do swojego wzrostu. Te poduszki uniemożliwią uniesienie ciała przez opór przymocowany do drążka.
3. Złap uchwyt V dłońmi skierowanymi ku sobie (chwyt neutralny). Wypnij klatkę piersiową i lekko odchyl się do tyłu (o około 30 stopni), aby lepiej zaangażować najszersze mięśnie grzbietu. To będzie Twoja pozycja startowa.
4. Używając najszerszych mięśni grzbietu, ściągnij drążek w dół, ściskając łopatki. Kontynuuj, aż Twoja klatka piersiowa niemal dotknie uchwytu V. Zrób wydech podczas wykonywania tego ruchu. Wskazówka: Trzymaj tułów nieruchomo przez cały ruch.
5. Po sekundzie trzymania w pozycji napiętej powoli prowadź drążek z powrotem do pozycji startowej, robiąc wdech.
6. Powtórz zalecaną liczbą powtórzeń.', NULL, 'free-exercise-db/V-Bar_Pulldown/0.jpg', 'free_exercise_db'),
  ('v-bar-pullup', 'Podciąganie na uchwycie V', 'V-Bar Pullup', 'motor_coach', 'beginner', array['Siłowe', 'Najszersze grzbietu'], 'Podciąganie z uchwytem V zawieszonym na drążku, z neutralnym chwytem. Ściągasz tułów w górę, aż klatka piersiowa niemal dotknie uchwytu, angażując najszersze mięśnie grzbietu.', '1. Zacznij od umieszczenia środka uchwytu V na środku drążka do podciągania (zakładając, że stanowisko, którego używasz, nie ma uchwytów neutralnych). Uchwyty V będą skierowane w dół, dzięki czemu możesz zwisać z drążka, trzymając się uchwytów.
2. Gdy uchwyt V jest pewnie umieszczony, złap go z każdej strony i zwisaj na nim. Wypnij klatkę piersiową i lekko odchyl się do tyłu, aby lepiej zaangażować najszersze mięśnie grzbietu. To będzie Twoja pozycja startowa.
3. Używając najszerszych mięśni grzbietu, przyciągnij tułów w górę, lekko odchylając głowę do tyłu, aby nie uderzyć się o drążek. Kontynuuj, aż Twoja klatka piersiowa niemal dotknie uchwytu V. Zrób wydech podczas wykonywania tego ruchu.
4. Po sekundzie trzymania w pozycji napiętej powoli opuść ciało z powrotem do pozycji startowej, robiąc wdech.
5. Powtórz zalecaną liczbą powtórzeń.', NULL, 'free-exercise-db/V-Bar_Pullup/0.jpg', 'free_exercise_db'),
  ('vertical-swing', 'Wymach hantlą w pionie', 'Vertical Swing', 'motor_coach', 'beginner', array['Plyometryka', 'Dwugłowe uda'], 'Wybuchowy wymach hantlą oburącz: opuszczasz ją między nogi uginając biodra, a potem dynamicznie prostujesz całe ciało, wymachując hantlą nad głowę.', '1. Pozwól hantli zwisać przy wyprostowanych ramionach między nogami, trzymając ją obiema rękami. Trzymaj plecy proste, a głowę uniesioną.
2. Wymachuj hantlą między nogami, uginając się w biodrach i lekko uginając kolana.
3. Dynamicznie odwróć ruch, prostując biodra, kolana i kostki, aby wyrzucić ciało w górę, wymachując hantlą nad głowę.
4. Przy lądowaniu absorbuj uderzenie nogami i przyciągnij hantlę do tułowia przed następnym powtórzeniem.', NULL, 'free-exercise-db/Vertical_Swing/0.jpg', 'free_exercise_db'),
  ('walking-treadmill', 'Marsz na bieżni mechanicznej', 'Walking, Treadmill', 'motor_coach', 'beginner', array['Cardio', 'Uda'], 'Spacer na bieżni mechanicznej w umiarkowanym lub szybkim tempie. Wygodne, przyjazne dla stawów kardio — spala mniej kalorii niż bieganie, ale wciąż daje realne korzyści zdrowotne.', '1. Na początku wejdź na bieżnię i wybierz żądaną opcję z menu. Większość bieżni ma tryb ręczny albo możesz wybrać program. Zazwyczaj możesz wprowadzić swój wiek i wagę, aby oszacować liczbę kalorii spalanych podczas ćwiczenia. Nachylenie można regulować, aby zmienić intensywność treningu.
2. Bieżnie oferują wygodę, korzyści sercowo-naczyniowe i zwykle mniejsze obciążenie stawów niż marsz na zewnątrz. Podczas marszu powinieneś poruszać się w tempie umiarkowanym do szybkiego, nie rekreacyjnym. Jako aktywność o niższej intensywności marsz nie spala tak wielu kalorii jak niektóre inne aktywności, ale nadal przynosi duże korzyści. Osoba ważąca ok. 68 kg spali około 175 kalorii marszując z prędkością 6,4 km/h przez 30 minut, w porównaniu do 450 kalorii przy bieganiu dwa razy szybszym. Zachowuj prawidłową postawę podczas marszu i trzymaj się poręczy tylko w razie potrzeby, np. przy schodzeniu lub sprawdzaniu tętna.', NULL, 'free-exercise-db/Walking_Treadmill/0.jpg', 'free_exercise_db'),
  ('weighted-ball-hyperextension', 'Prostowniki pleców na piłce z talerzem', 'Weighted Ball Hyperextension', 'motor_coach', 'intermediate', array['Siłowe', 'Dolny odcinek pleców'], 'Wzmocnienie dolnych pleców na piłce gimnastycznej z talerzem obciążającym. Leżąc na piłce, unoś tułów uginając się w pasie, napinając dolny odcinek pleców, a potem powoli opuszczasz.', '1. Na początku połóż się na piłce gimnastycznej z tułowiem dociśniętym do piłki i równoległym do podłogi. Palce stóp powinny być dociśnięte do podłogi, aby pomóc Ci zachować równowagę. Umieść obciążony talerz pod brodą lub za karkiem. To jest pozycja startowa.
2. Powoli unoś tułów w górę, uginając się w pasie i odcinku lędźwiowym. Pamiętaj o wydechu podczas tego ruchu.
3. Przytrzymaj napięcie w dolnych plecach przez sekundę i opuść tułów z powrotem do pozycji startowej, robiąc wdech.
4. Powtórz zalecaną liczbę powtórzeń przewidzianą w Twoim programie.', NULL, 'free-exercise-db/Weighted_Ball_Hyperextension/0.jpg', 'free_exercise_db'),
  ('weighted-ball-side-bend', 'Boczne skłony na piłce z talerzem', 'Weighted Ball Side Bend', 'motor_coach', 'intermediate', array['Siłowe', 'Brzuch'], 'Skłony boczne na piłce gimnastycznej z talerzem w dłoni, celujące w mięśnie skośne brzucha. Unoś bok tułowia, zginając się lateralnie w pasie, po czym powoli opuszczasz i zmieniasz stronę.', '1. Na początku połóż się na piłce gimnastycznej lewym bokiem tułowia (talią, biodrami i barkiem) dociśniętym do piłki.
2. Twoje stopy powinny być na podłodze, a nogi skrzyżowane i zwisające z piłki. Trzymaj obciążony talerz prawą dłonią bezpośrednio po prawej stronie głowy. Wskazówka: Upewnij się, że gładka strona talerza opiera się o Twoją głowę.
3. Połóż lewe ramię w poprzek tułowia tak, aby dłoń spoczywała na mięśniach skośnych. Między przedramieniem a górnym ramieniem powinien być kąt prosty. To jest pozycja startowa.
4. Unoś bok tułowia w górę, zginając się lateralnie w pasie, robiąc wydech.
5. Przytrzymaj napięcie przez sekundę i powoli opuść się z powrotem do pozycji startowej, robiąc wdech.
6. Powtórz zalecaną liczbę powtórzeń.
7. Zmień strony i powtórz ćwiczenie.', NULL, 'free-exercise-db/Weighted_Ball_Side_Bend/0.jpg', 'free_exercise_db'),
  ('weighted-bench-dip', 'Dipy na ławce z obciążeniem', 'Weighted Bench Dip', 'motor_coach', 'intermediate', array['Siłowe', 'Triceps'], 'Dipy tricepsa między dwiema ławkami z hantlą na kolanach (najlepiej z pomocą partnera). Opuszczasz ciało uginając łokcie do nieco mniej niż 90 stopni, a potem prostujesz ramiona w górę.', '1. Do tego ćwiczenia musisz ustawić ławkę za plecami i kolejną przed sobą. Z ławkami prostopadłymi do Twojego ciała, trzymaj się krawędzi jednej ławki dłońmi blisko ciała, rozstawionymi na szerokość barków. Twoje ramiona powinny być całkowicie wyprostowane.
2. Nogi będą wyciągnięte do przodu na drugiej ławce. Twoje nogi powinny być równoległe do podłogi, a tułów prostopadły do podłogi. Poproś partnera, aby położył hantlę na Twoich udach. Uwaga: To ćwiczenie najlepiej wykonywać z partnerem, ponieważ położenie ciężaru na udach może być trudne i grozić kontuzją bez asysty. To będzie Twoja pozycja startowa.
3. Powoli opuszczaj ciało, robiąc wdech, uginając łokcie, aż zejdziesz wystarczająco nisko, aby między górnym ramieniem a przedramieniem powstał kąt nieco mniejszy niż 90 stopni. Wskazówka: Trzymaj łokcie jak najbliżej siebie przez cały ruch. Przedramiona powinny zawsze wskazywać w dół.
4. Używając tricepsów, aby podnieść tułów z powrotem, wróć do pozycji startowej, robiąc wydech.
5. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Weighted_Bench_Dip/0.jpg', 'free_exercise_db'),
  ('weighted-crunches', 'Spięcia brzucha z obciążeniem', 'Weighted Crunches', 'motor_coach', 'beginner', array['Siłowe', 'Brzuch'], 'Klasyczne crunch z ciężarem trzymanym przy klatce piersiowej lub nad tułowiem. Oderwij barki od podłogi o kilka centymetrów, napnij brzuch i powoli opuść się z powrotem.', '1. Połóż się płasko na plecach ze stopami płasko na ziemi lub opartymi na ławce, z kolanami ugiętymi pod kątem 90 stopni.
2. Trzymaj ciężar przy klatce piersiowej albo możesz trzymać go wyciągnięty nad tułowiem. To będzie Twoja pozycja startowa.
3. Teraz, robiąc wydech, powoli zacznij oderwać barki od podłogi. Twoje barki powinny unieść się o około 10 cm, podczas gdy dolne plecy pozostają na podłodze.
4. Na szczycie ruchu napnij mięśnie brzucha i przytrzymaj krótką pauzę.
5. Potem zrób wdech i powoli opuść się z powrotem do pozycji startowej.', NULL, 'free-exercise-db/Weighted_Crunches/0.jpg', 'free_exercise_db'),
  ('weighted-jump-squat', 'Przysiad z wyskokiem z obciążeniem', 'Weighted Jump Squat', 'motor_coach', 'intermediate', array['Siłowe', 'Uda'], 'Plyometryczny przysiad z wyskokiem z lekkim obciążeniem (sztanga, kamizelka lub worek). Z ruchu przeciwbieżnego wybijasz się maksymalnie w górę, prostując biodra, kolana i kostki.', '1. Połóż lekko załadowaną sztangę na tylnych partiach barków. Możesz też użyć obciążonej kamizelki, worka z piaskiem lub innego rodzaju oporu do tego ćwiczenia.
2. Ciężar powinien być na tyle lekki, aby nie spowalniał Cię znacząco. Twoje stopy powinny być tuż poza szerokością barków, z głową i klatką piersiową uniesioną. To będzie Twoja pozycja startowa.
3. Używając ruchu przeciwbieżnego, zejdź częściowo do przysiadu i natychmiast odwróć kierunek, wybijając się z ziemi, prostując biodra, kolana i kostki. Zachowuj dobrą postawę przez cały wyskok.
4. Gdy wracasz na ziemię, amortyzuj uderzenie nogami.', NULL, 'free-exercise-db/Weighted_Jump_Squat/0.jpg', 'free_exercise_db'),
  ('weighted-pull-ups', 'Podciąganie z obciążeniem', 'Weighted Pull Ups', 'motor_coach', 'intermediate', array['Siłowe', 'Najszersze grzbietu'], 'Podciąganie nachwytem z ciężarem na pasie do dipów. Cofasz tułów o ok. 30 stopni, wypinasz klatkę piersiową i przyciągasz ciało w górę, aż głowa jest nad dłońmi, ściskając łopatki w dół.', '1. Zamocuj ciężar na pasie do dipów i zabezpiecz go wokół pasa. Złap drążek do podciągania dłońmi skierowanymi do przodu. Dla średniego chwytu Twoje dłonie powinny być rozstawione na szerokość barków. Oba ramiona powinny być wyprostowane przed Tobą, trzymając drążek w wybranym chwycie.
2. Cofnij tułów o około 30 stopni, tworząc wygięcie w odcinku lędźwiowym i wypinając klatkę piersiową. To będzie Twoja pozycja startowa.
3. Teraz, robiąc wydech, przyciągnij tułów w górę, aż Twoja głowa znajdzie się nad dłońmi. Skup się na ściskaniu łopatek do tyłu i w dół, gdy osiągniesz górną napiętą pozycję.
4. Po krótkiej chwili w górnej pozycji napiętej zrób wdech i powoli opuść tułów z powrotem do pozycji startowej, z ramionami wyprostowanymi i najszerszymi mięśniami grzbietu całkowicie rozciągniętymi.', NULL, 'free-exercise-db/Weighted_Pull_Ups/0.jpg', 'free_exercise_db'),
  ('weighted-sissy-squat', 'Przysiad sissy z obciążeniem', 'Weighted Sissy Squat', 'motor_coach', 'advanced', array['Siłowe', 'Uda'], 'Przysiad sissy z talerzem na klatce piersiowej: pochylasz się do tyłu z biodrami i kolanami w przód, aż uda i łydki niemal utworzą kąt 90 stopni, po czym wracasz siłą ud.', '1. Stojąc prosto, ze stopami na szerokość barków i palcami uniesionymi, trzymaj jedną ręką słupki stojaka do przysiadów, a drugą ręką talerz na klatce piersiowej. To jest Twoja pozycja startowa.
2. Używając jednego ramienia do utrzymania się, ugnij kolana i powoli opuszczaj tułów ku ziemi, prowadząc miednicę i kolana do przodu. Wdech wykonaj podczas schodzenia i zatrzymaj się, gdy górna i dolna część nóg niemal utworzą kąt 90 stopni. Przytrzymaj pozycję rozciągania przez sekundę.
3. Po sekundowym trzymaniu użyj mięśni ud, aby podnieść tułów z powrotem do pozycji startowej. Zrób wydech podczas unoszenia się.
4. Powtórz zalecaną liczbę razy.', NULL, 'free-exercise-db/Weighted_Sissy_Squat/0.jpg', 'free_exercise_db'),
  ('weighted-sit-ups-with-bands', 'Brzuszki z gumami oporowymi na ławce skośnej', 'Weighted Sit-Ups - With Bands', 'motor_coach', 'intermediate', array['Siłowe', 'Brzuch'], 'Sit-upy na ławce skośnej z gumami oporowymi przymocowanymi do jej podstawy. Trzymasz uchwyty przy obojczyku w chwycie neutralnym i unosisz tułów do pionu, pokonując opór gum.', '1. Zacznij od przymocowania gum do podstawy ławki skośnej (opadu). Połóż uchwyty wewnątrz ławki tak, aby po położeniu się móc dosięgnąć obu.
2. Przełóż nogi przez maszynę opadu, aż będą zabezpieczone. Teraz sięgnij po gumy do ćwiczeń obiema rękami. Użyj chwytu nachwyt (dłonie do przodu), aby złapać uchwyty. Umieść je blisko obojczyka i obróć nadgarstki do chwytu neutralnego (dłonie skierowane ku tułowiowi). Uwaga: Twoje ramiona powinny pozostać nieruchome przez całe ćwiczenie. To jest pozycja startowa.
3. Unoś tułów w górę, aż górna część ciała będzie prostopadła do podłogi, robiąc wydech. Przytrzymaj napięcie przez sekundę i opuść górną część ciała z powrotem do pozycji startowej, robiąc wdech.
4. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Weighted_Sit-Ups_-_With_Bands/0.jpg', 'free_exercise_db'),
  ('weighted-squat', 'Przysiad z obciążeniem na pasie', 'Weighted Squat', 'motor_coach', 'intermediate', array['Siłowe', 'Uda'], 'Przysiad z ciężarem zawieszonym na pasie, stojąc na dwóch ławkach. Zejdziesz do przysiadu, aż uda znajdą się poniżej równoległości do podłogi, pilnując, by kolana nie wykraczały poza palce stóp.', '1. Zacznij od ustawienia dwóch płaskich ławek na szerokość barków. Stań na nich i owiń pas obciążony wokół pasa z takim ciężarem, jaki uważasz za komfortowy. Upewnij się, że Twoje palce stóp są skierowane na zewnątrz.
2. Kiedy stoisz prosto z ciężarem zwisającym między nogami, ustaw ramiona tak, aby były całkowicie wyprostowane po bokach ciała. To jest pozycja startowa.
3. Zacznij od uginania kolan, zachowując prostą postawę z głową uniesioną. Zejdź w dół, aż kąt między udem a łydką stanie się nieco mniejszy niż 90 stopni (czyli punkt, w którym uda znajdują się poniżej równoległości do podłogi). Wdech wykonaj podczas tej części ruchu. Wskazówka: Jeśli wykonałeś ćwiczenie poprawnie, przód kolan powinien tworzyć umowną prostą z palcami stóp, prostopadłą do przodu. Jeśli Twoje kolana wykraczają poza tę umowną linię (jeśli są dalej niż palce stóp), to nakładasz nadmierne obciążenie na kolano, a ćwiczenie zostało wykonane niepoprawnie.
4. Zacznij prowadzić ciało z powrotem w górę, odpychając podłogę ławki głównie śródstopiem, gdy prostujesz ponownie nogi i wracasz do pozycji startowej. Zrób wydech podczas tej części ćwiczenia.
5. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Weighted_Squat/0.jpg', 'free_exercise_db'),
  ('wide-grip-barbell-bench-press', 'Wyciskanie sztangi leżąc szerokim chwytem', 'Wide-Grip Barbell Bench Press', 'motor_coach', 'intermediate', array['Siłowe', 'Klatka piersiowa'], 'Wyciskanie sztangi leżąc z chwytem ok. 8 cm szerszym niż barki, mocniej angażujące klatkę piersiową. Opuszczasz sztangę na środek klatki, po czym wyciskasz ją w górę z pełnym wyprostem ramion.', '1. Połóż się na płaskiej ławce ze stopami mocno opartymi o podłogę. Używając szerokiego chwytu nachwyt (dłonie do przodu) około 8 cm odległego od szerokości barków (dla każdej dłoni), zdejmij sztangę ze stojaka i trzymaj ją prosto nad sobą z zablokowanymi ramionami. Sztanga będzie prostopadła do tułowia i podłogi. To będzie Twoja pozycja startowa.
2. Robiąc wdech, opuszczaj się powoli, aż poczujesz sztangę na środkowej klatce piersiowej.
3. Po sekundowej pauzie prowadź sztangę z powrotem do pozycji startowej, robiąc wydech, wypychając sztangę mięśniami klatki piersiowej. Zablokuj ramiona i ściskaj klatkę piersiową w pozycji napiętej, przytrzymaj przez sekundę, a potem zacznij znowu opuszczać powoli. Wskazówka: Opuszczanie powinno trwać co najmniej dwa razy dłużej niż wyciskanie.
4. Powtórz ruch zalecaną liczbą powtórzeń.', NULL, 'free-exercise-db/Wide-Grip_Barbell_Bench_Press/0.jpg', 'free_exercise_db'),
  ('wide-grip-decline-barbell-bench-press', 'Wyciskanie sztangi na ławce opuszczonej szerokim chwytem', 'Wide-Grip Decline Barbell Bench Press', 'motor_coach', 'intermediate', array['Siłowe', 'Klatka piersiowa'], 'Wyciskanie sztangi na ławce z opadem, szerokim chwytem, celujące w dolną część klatki piersiowej. Opuszczasz sztangę na dolne partie klatki i wyciskasz ją z powrotem w górę.', '1. Połóż się na ławce z opadem ze stopami pewnie zablokowanymi z przodu ławki. Używając szerokiego chwytu nachwyt (dłonie do przodu) około 8 cm odległego od szerokości barków (dla każdej dłoni), zdejmij sztangę ze stojaka i trzymaj ją prosto nad sobą z zablokowanymi ramionami. Sztanga będzie prostopadła do tułowia i podłogi. To będzie Twoja pozycja startowa.
2. Robiąc wdech, opuszczaj się powoli, aż poczujesz sztangę na dolnej części klatki piersiowej.
3. Po sekundowej pauzie prowadź sztangę z powrotem do pozycji startowej, robiąc wydech, wypychając sztangę mięśniami klatki piersiowej. Zablokuj ramiona i ściskaj klatkę piersiową w pozycji napiętej, przytrzymaj przez sekundę, a potem zacznij znowu opuszczać powoli. Wskazówka: Opuszczanie powinno trwać co najmniej dwa razy dłużej niż wyciskanie.
4. Powtórz ruch zalecaną liczbą powtórzeń.', NULL, 'free-exercise-db/Wide-Grip_Decline_Barbell_Bench_Press/0.jpg', 'free_exercise_db'),
  ('wide-grip-decline-barbell-pullover', 'Pullover ze sztangą na ławce opuszczonej szerokim chwytem', 'Wide-Grip Decline Barbell Pullover', 'motor_coach', 'intermediate', array['Siłowe', 'Klatka piersiowa'], 'Pullover ze sztangą na ławce z opadem: opuszczasz sztangę łukiem za głowę na wyprostowanych ramionach, aż będą równoległe do podłogi, a potem wracasz tym samym łukiem.', '1. Połóż się na ławce z opadem z obiema nogami pewnie zablokowanymi. Sięgnij po sztangę za głowę chwytem nachwytem (dłonie skierowane na zewnątrz). Upewnij się, że chwytasz sztangę szerzej niż szerokość barków w tym ćwiczeniu. Powoli podnieś sztangę z podłogi, używając ramion.
2. Gdy jest prawidłowo ustawiona, Twoje ramiona powinny być całkowicie wyprostowane i prostopadłe do podłogi. To jest pozycja startowa.
3. Zacznij prowadzić sztangę z powrotem w dół ruchem po półkolu, jakbyś chciał położyć ją na podłodze, ale zamiast tego zatrzymaj się, gdy ramiona będą równoległe do podłogi. Wskazówka: Trzymaj ramiona całkowicie wyprostowane przez cały czas. Ruch powinien zachodzić wyłącznie w stawie barkowym. Wdech wykonaj podczas tej części ruchu.
4. Teraz prowadź sztangę w górę, robiąc wydech, aż wrócisz do pozycji startowej. Pamiętaj, aby zachować pełną kontrolę nad sztangą przez cały czas.
5. Powtórz ruch zalecaną liczbą powtórzeń z Twojego programu treningowego.
6. Po zakończeniu serii powoli opuść sztangę z powrotem w dół, aż będzie na wysokości Twojej głowy, i puść ją.', NULL, 'free-exercise-db/Wide-Grip_Decline_Barbell_Pullover/0.jpg', 'free_exercise_db'),
  ('wide-grip-lat-pulldown', 'Ściąganie drążka wyciągu szerokim chwytem', 'Wide-Grip Lat Pulldown', 'motor_coach', 'beginner', array['Siłowe', 'Najszersze grzbietu'], 'Klasyczne ściąganie szerokiego drążka górnego wyciągu, budujące mięśnie najszersze grzbietu. Ściągasz drążek do górnej klatki piersiowej, ściągając łokcie w dół i do tyłu, z tułowiem lekko odchylonym.', '1. Usiądź na maszynie ściągającej z szerokim drążkiem zamocowanym na górnym bloczku. Upewnij się, że dostosowałeś poduszkę kolanową maszyny do swojego wzrostu. Te poduszki uniemożliwią uniesienie ciała przez opór przymocowany do drążka.
2. Złap drążek dłońmi skierowanymi do przodu, stosując zalecany chwyt. Uwaga o chwytach: dla szerokiego chwytu Twoje dłonie muszą być rozstawione szerzej niż szerokość barków. Dla średniego chwytu — na szerokość barków, a dla wąskiego — węższej niż szerokość barków.
3. Mając oba ramiona wyprostowane przed sobą i trzymając drążek w wybranym rozstawie chwytu, cofnij tułów o około 30 stopni, tworząc wygięcie w odcinku lędźwiowym i wypinając klatkę piersiową. To jest Twoja pozycja startowa.
4. Robiąc wydech, ściągnij drążek w dół, aż dotknie Twojej górnej klatki piersiowej, prowadząc barki i górne ramiona w dół i do tyłu. Wskazówka: Skup się na ściskaniu mięśni pleców, gdy osiągniesz całkowicie napiętą pozycję. Górna część tułowia powinna pozostać nieruchoma — poruszać się powinny tylko ramiona. Przedramiona nie powinny wykonywać żadnej innej pracy niż trzymanie drążka, dlatego nie próbuj ściągać drążka przedramionami.
5. Po sekundzie w pozycji napiętej, ściskając łopatki do siebie, powoli unieś drążek z powrotem do pozycji startowej, gdy Twoje ramiona są całkowicie wyprostowane, a najszersze mięśnie grzbietu całkowicie rozciągnięte. Wdech wykonaj podczas tej części ruchu.
6. Powtórz ten ruch zalecaną liczbą powtórzeń.', NULL, 'free-exercise-db/Wide-Grip_Lat_Pulldown/0.jpg', 'free_exercise_db'),
  ('wide-grip-pulldown-behind-the-neck', 'Ściąganie drążka za kark szerokim chwytem', 'Wide-Grip Pulldown Behind The Neck', 'motor_coach', 'intermediate', array['Siłowe', 'Najszersze grzbietu'], 'Wariant ściągania drążka za kark: ściągasz szeroki drążek w dół, aż dotknie tyłu karku. Wymaga dobrej mobilności barków; technika podobna do klasycznego ściągania.', '1. Usiądź na maszynie ściągającej z szerokim drążkiem zamocowanym na górnym bloczku. Upewnij się, że dostosowałeś poduszkę kolanową maszyny do swojego wzrostu. Te poduszki uniemożliwią uniesienie ciała przez opór przymocowany do drążka.
2. Złap drążek dłońmi skierowanymi do przodu, stosując zalecany chwyt. Uwaga o chwytach: dla szerokiego chwytu Twoje dłonie muszą być rozstawione szerzej niż Twoja szerokość barków. Dla średniego chwytu — na szerokość barków, a dla wąskiego — węższej niż szerokość barków.
3. Mając oba ramiona wyprostowane przed sobą i trzymając drążek w wybranym rozstawie chwytu, pochyl tułów i głowę do przodu. Pomyśl o umownej linii od środka drążka w dół do tyłu Twojej karku. To jest Twoja pozycja startowa.
4. Robiąc wydech, ściągnij drążek w dół, aż dotknie tyłu Twojej karku, prowadząc barki i górne ramiona w dół i do tyłu. Wskazówka: Skup się na ściskaniu mięśni pleców, gdy osiągniesz całkowicie napiętą pozycję. Górna część tułowia powinna pozostać nieruchoma — poruszać się powinny tylko ramiona. Przedramiona nie powinny wykonywać żadnej innej pracy niż trzymanie drążka, dlatego nie próbuj ściągać drążka przedramionami.
5. Po sekundzie w pozycji napiętej, ściskając łopatki do siebie, powoli unieś drążek z powrotem do pozycji startowej, gdy Twoje ramiona są całkowicie wyprostowane, a najszersze mięśnie grzbietu całkowicie rozciągnięte. Wdech wykonaj podczas tej części ruchu.
6. Powtórz ten ruch zalecaną liczbą powtórzeń.', NULL, 'free-exercise-db/Wide-Grip_Pulldown_Behind_The_Neck/0.jpg', 'free_exercise_db'),
  ('wide-grip-rear-pull-up', 'Podciąganie za kark szerokim chwytem', 'Wide-Grip Rear Pull-Up', 'motor_coach', 'intermediate', array['Siłowe', 'Najszersze grzbietu'], 'Podciąganie szerokim chwytem prowadzone za kark: przyciągasz ciało w górę, aż drążek zbliży się do tyłu karku. Wymaga dobrej mobilności barków.', '1. Złap drążek do podciągania dłońmi skierowanymi do przodu, szerokim chwytem.
2. Mając oba ramiona wyprostowane przed sobą i trzymając drążek, pochyl tułów i głowę do przodu tak, aby istniała umowna linia od drążka do podciągania do tyłu Twojej karku. To jest Twoja pozycja startowa.
3. Przyciągnij tułów w górę, aż drążek znajdzie się blisko tyłu Twojej karku. Aby to zrobić, prowadź barki i górne ramiona w dół i do tyłu, lekko pochylając głowę do przodu. Zrób wydech podczas tej części ruchu. Wskazówka: Skup się na ściskaniu mięśni pleców, gdy osiągniesz całkowicie napiętą pozycję. Górna część tułowia powinna pozostać nieruchoma podczas przemieszczania się w przestrzeni — poruszać się powinny tylko ramiona. Przedramiona nie powinny wykonywać żadnej innej pracy niż trzymanie drążka.
4. Po sekundzie w pozycji napiętej zacznij robić wdech i powoli opuść tułów z powrotem do pozycji startowej, gdy Twoje ramiona są całkowicie wyprostowane, a najszersze mięśnie grzbietu całkowicie rozciągnięte.
5. Powtórz ten ruch zalecaną liczbą powtórzeń.', NULL, 'free-exercise-db/Wide-Grip_Rear_Pull-Up/0.jpg', 'free_exercise_db'),
  ('wide-grip-standing-barbell-curl', 'Uginanie sztangi stojąc szerokim chwytem', 'Wide-Grip Standing Barbell Curl', 'motor_coach', 'beginner', array['Siłowe', 'Biceps'], 'Uginanie ramion ze sztangą trzymaną za szerokie końce gryfu. Izoluje wewnętrzną część bicepsa; łokcie blisko tułowia, a poruszają się tylko przedramiona.', '1. Stań z wyprostowanym tułowiem, trzymając sztangę za szerokie, zewnętrzne uchwyty. Dłonie powinny być skierowane do przodu. Łokcie powinny być blisko tułowia. To będzie Twoja pozycja startowa.
2. Utrzymując górne ramiona nieruchome, uginaj ciężary do przodu, napinając biceps, robiąc wydech. Wskazówka: Poruszać się powinny tylko przedramiona.
3. Kontynuuj ruch, aż biceps będzie całkowicie napięty, a sztanga na wysokości barków. Przytrzymaj pozycję napiętą przez sekundę i mocno ściskaj biceps.
4. Powoli zacznij prowadzić sztangę z powrotem do pozycji startowej, robiąc wdech.
5. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Wide-Grip_Standing_Barbell_Curl/0.jpg', 'free_exercise_db'),
  ('wide-stance-barbell-squat', 'Przysiad ze sztangą w szerokim rozstawie', 'Wide Stance Barbell Squat', 'motor_coach', 'intermediate', array['Siłowe', 'Uda'], 'Przysiad ze sztangą na karku w szerokim rozstawie stóp z palcami skierowanymi na zewnątrz. Mocniej angażuje wewnętrzne uda, pośladki i przywodziciele; kolana nie mogą wychodzić poza palce stóp.', '1. To ćwiczenie najlepiej wykonywać wewnątrz klatki do przysiadów dla bezpieczeństwa. Na początku ustaw sztangę na stojaku dopasowanym do Twojego wzrostu. Po dobraniu właściwej wysokości i załadowaniu sztangi wejdź pod nią i połóż tylną część barków (nieco poniżej szyi) na gryfie.
2. Trzymaj sztangę obiema rękami po obu stronach i zdejmij ją ze stojaka, najpierw odpychając się nogami, a jednocześnie prostując tułów.
3. Odejdź od stojaka i ustaw nogi w rozstawie szerszym niż szerokość barków, z palcami lekko skierowanymi na zewnątrz. Cały czas trzymaj głowę uniesioną, ponieważ patrzenie w dół zaburzy Ci równowagę, i utrzymuj proste plecy. To będzie Twoja pozycja startowa.
4. Zacznij powoli opuszczać sztangę, uginając kolana i zachowując prostą postawę z głową uniesioną. Kontynuuj zejście, aż kąt między udem a łydką stanie się nieco mniejszy niż 90 stopni (czyli punkt, w którym uda znajdują się poniżej równoległości do podłogi). Wdech wykonaj podczas tej części ruchu. Wskazówka: Jeśli wykonałeś ćwiczenie poprawnie, przód kolan powinien tworzyć umowną prostą z palcami stóp, prostopadłą do przodu. Jeśli Twoje kolana wykraczają poza tę umowną linię (jeśli są dalej niż palce stóp), to nakładasz nadmierne obciążenie na kolano, a ćwiczenie zostało wykonane niepoprawnie.
5. Zacznij unosić sztangę, robiąc wydech, odpychając podłogę piętą, gdy prostujesz ponownie nogi i wracasz do pozycji startowej.
6. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Wide_Stance_Barbell_Squat/0.jpg', 'free_exercise_db'),
  ('wide-stance-stiff-legs', 'Martwy ciąg na prostych nogach w szerokim rozstawie', 'Wide Stance Stiff Legs', 'motor_coach', 'intermediate', array['Podnoszenie ciężarów', 'Dwugłowe uda'], 'Martwy ciąg na sztywnych nogach z bardzo szerokim rozstawem stóp. Cofasz biodra maksymalnie do tyłu z niemal prostymi nogami, po czym prostujesz biodra, unosząc sztangę do pionu.', '1. Zacznij od sztangi załadowanej na podłodze. Przyjmij szeroki rozstaw, a następnie ugnij się w biodrach, aby chwycić sztangę. Twoje biodra powinny być cofnięte maksymalnie do tyłu, a nogi niemal proste. Trzymaj plecy proste, a głowę i klatkę piersiową uniesioną. To będzie Twoja pozycja startowa.
2. Rozpocznij ruch angażując biodra, pchając je do przodu, pozwalając ramionom zwisać prosto. Kontynuuj, aż staniesz całkowicie prosto, a następnie powoli odłożyć ciężar do pozycji startowej. Przy kolejnych powtzeniach ciężar nie musi dotykać podłogi.', NULL, 'free-exercise-db/Wide_Stance_Stiff_Legs/0.jpg', 'free_exercise_db'),
  ('wind-sprints', 'Interwały sprintów (wind sprints)', 'Wind Sprints', 'motor_coach', 'beginner', array['Siłowe', 'Brzuch'], 'Intensywne sprinty interwałowe budujące szybkość i wydolność. Uwaga: instrukcja źródłowa tego ćwiczenia opisuje bieg naprzemienny z podnoszeniem kolan wisząc na drążku — wykonuj zgodnie z zapisem kroków.', '1. Zwisaj z drążka do podciągania chwytem nachwytem. Twoje ramiona i nogi powinny być wyprostowane. To będzie Twoja pozycja startowa.
2. Zacznij od szybkiego podniesienia jednego kolana tak wysoko, jak potrafisz. Nie bujaj ciałem ani nogami.
3. Natychmiast odwróć ruch, wracając tę nogę do pozycji startowej. Jednocześnie unieś przeciwległe kolano tak wysoko, jak to możliwe.
4. Kontynuuj naprzemiennie między nogami, aż seria zostanie zakończona.', NULL, 'free-exercise-db/Wind_Sprints/0.jpg', 'free_exercise_db'),
  ('windmills', 'Wiatraczki leżąc', 'Windmills', 'motor_coach', 'intermediate', array['Rozciąganie', 'Odwodziciele'], 'Rozciąganie i mobilizacja core leżąc na plecach: unosisz wyprostowaną nogę i przekładasz ją przez ciało, próbując dotknąć ziemi przy przeciwległej dłoni. Naprzemiennie po 10–20 powtórzeń.', '1. Połóż się na plecach z ramionami wyciągniętymi na boki i nogami prostymi. To będzie Twoja pozycja startowa.
2. Unieś jedną nogę i szybko przełóż ją przez ciało, próbując dotknąć ziemi w pobliżu przeciwległej dłoni.
3. Wróć do pozycji startowej i powtórz przeciwległą nogą. Kontynuuj naprzemiennie przez 10–20 powtórzeń.', NULL, 'free-exercise-db/Windmills/0.jpg', 'free_exercise_db'),
  ('worlds-greatest-stretch', 'Największe rozciąganie świata', 'World''s Greatest Stretch', 'motor_coach', 'intermediate', array['Rozciąganie', 'Dwugłowe uda'], 'Trzyczęściowe rozciąganie bioder, ud i pachwin: wykrok z opadem bioder, potem rotacja z łokciem przy stopie, na koniec wyprost nogi przedniej z dłońmi po obu stronach stopy. Każdą część trzymasz 10–20 sekund.', '1. To rozciąganie składa się z trzech części. Zacznij od wykroku do przodu, ze stopą przednią płasko na ziemi i na palcach stopy tylnej. Z ugiętymi kolanami zejdź do przysiadu, aż kolano niemal dotknie ziemi. Trzymaj tułów wyprostowany i utrzymaj tę pozycję przez 10–20 sekund.
2. Teraz połóż ramię po tej samej stronie co noga przednia na ziemi, z łokciem obok stopy. Twoja druga dłoń powinna zostać położona na ziemi, równolegle do nogi prowadzącej, aby wspomóc Cię podczas tej części rozciągania.
3. Po 10–20 sekundach połóż dłonie po obu stronach stopy przedniej. Unieś palce stopy przedniej od ziemi i wyprostuj nogę. Może być konieczne przestawienie nogi tylnej, aby to zrobić. Przytrzymaj przez 10–20 sekund, a następnie powtórz całą sekwencję na drugą stronę.', NULL, 'free-exercise-db/Worlds_Greatest_Stretch/0.jpg', 'free_exercise_db'),
  ('wrist-circles', 'Krążenia nadgarstków', 'Wrist Circles', 'motor_coach', 'beginner', array['Rozciąganie', 'Przedramiona'], 'Prosta rozgrzewka nadgarstków: z ramionami wyciągniętymi w bok na wysokość barków krążysz oboma nadgarstkami do przodu ruchem kołowym, oddychając normalnie.', '1. Zacznij od stania prosto ze stopami rozstawionymi na szerokość barków. Unoś ramiona na boki, aż będą całkowicie wyprostowane i równoległe do podłogi, na wysokości równej z barkami. Wskazówka: Twój tułów i ramiona powinny tworzyć literę "T". Twoje dłonie powinny być skierowane w dół. To jest pozycja startowa.
2. Utrzymując całe ciało nieruchome poza nadgarstkami, zacznij obracać oboma nadgarstkami do przodu ruchem kołowym. Wskazówka: Udawaj, że próbujesz rysować koła, używając dłoni jako pędzla. Oddychaj normalnie podczas wykonywania tego ćwiczenia.
3. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Wrist_Circles/0.jpg', 'free_exercise_db'),
  ('wrist-roller', 'Wałek na przedramiona (wrist roller)', 'Wrist Roller', 'motor_coach', 'beginner', array['Siłowe', 'Przedramiona'], 'Klasyczny trener przedramion: nawijasz linę z obciążeniem na wałek, obracając nadgarstki naprzemiennie w górę, a potem kontrolowanie opuszczasz ciężar tym samym ruchem w dół.', '1. Na początku stań prosto, trzymając wrist roller chwytem nachwytem (dłonie skierowane w dół). Twoje stopy powinny być rozstawione na szerokość barków.
2. Powoli unoś oba ramiona, aż będą całkowicie wyprostowane i równoległe do podłogi przed Tobą. Uwaga: Upewnij się, że lina nie jest nawinięta wokół wałka. Twoje całe ciało powinno pozostać nieruchome poza przedramionami. To jest pozycja startowa.
3. Obracaj jedno nadgarstek po drugim ruchem w górę, aby podnieść ciężar do gryfu, nawijając linę wokół wałka.
4. Gdy ciężar osiągnie gryf, powoli zacznij opuszczać ciężar z powrotem w dół, obracając nadgarstek ruchem w dół, aż ciężar osiągnie pozycję startową.
5. Powtórz zalecaną liczbę powtórzeń w Twoim programie.', NULL, 'free-exercise-db/Wrist_Roller/0.jpg', 'free_exercise_db'),
  ('wrist-rotations-with-straight-bar', 'Rotacje nadgarstków z prostym gryfem', 'Wrist Rotations with Straight Bar', 'motor_coach', 'beginner', array['Siłowe', 'Przedramiona'], 'Wzmacnianie przedramion: trzymając sztangę nachwytem, naprzemiennie prostujesz i uginasz nadgarstki, jakbyś zwijał gazetę — do upadku mięśniowego w obu kierunkach.', '1. Trzymaj sztangę obiema rękami, dłońmi skierowanymi w dół; dłonie rozstawione około na szerokość barków. To będzie Twoja pozycja startowa.
2. Naprzemiennie każdą z dłoni wykonuj ruch, prostując nadgarstek, jakbyś zwijał gazetę. Kontynuuj naprzemiennie tam i z powrotem, aż do upadku mięśniowego.
3. Odwróć ruch, uginając nadgarstek i zwijając w przeciwnym kierunku. Kontynuuj ruch naprzemienny, aż do upadku mięśniowego.', NULL, 'free-exercise-db/Wrist_Rotations_with_Straight_Bar/0.jpg', 'free_exercise_db'),
  ('yoke-walk', 'Spacer z yokem (nosidłem)', 'Yoke Walk', 'motor_coach', 'intermediate', array['Strongman', 'Uda'], 'Silowy marsz z ciężkim nosidłem (yoke) na barkach. Idziesz możliwie szybko krótkimi krokami na zadany dystans, zwykle 23–30 metrów, trzymając konstrukcję stabilną.', '1. Yoke zwykle wykonuje się z aparatem nosidła, ale czasem spotyka się go z lodówkami lub innymi ciężkimi przedmiotami.
2. Zacznij od położenia aparatu na tylnych partiach barków. Z głową patrzącą do przodu i wygiętymi plecami unieś yoke, odpychając się piętami.
3. Zacznij chodzić tak szybko, jak to możliwe, krótkimi, szybkimi krokami. Możesz trzymać boczne słupki yoke, aby pomóc mu utrzymać stabilność i pozycję. Kontynuuj na zadany dystans jak najszybciej, zwykle 23–30 metrów.', NULL, 'free-exercise-db/Yoke_Walk/0.jpg', 'free_exercise_db'),
  ('zercher-squats', 'Przysiad zercher', 'Zercher Squats', 'motor_coach', 'advanced', array['Siłowe', 'Uda'], 'Przysiad ze sztangą trzymaną w zgięciach łokci przed klatką piersiową. Bardzo wymagający dla core, ud i górnej części pleców; technika przysiadu jak w wersji klasycznej.', '1. To ćwiczenie najlepiej wykonywać wewnątrz klatki do przysiadów dla bezpieczeństwa. Na początku ustaw sztangę na stojaku dopasowanym do Twojego wzrostu. Właściwa wysokość powinna być gdziekolwiek powyżej pasa, ale poniżej klatki piersiowej. Po dobraniu właściwej wysokości i załadowaniu sztangi, splić dłonie razem i połóż sztangę na wierzchu ramion między przedramieniem a górnym ramieniem.
2. Podnieś sztangę tak, aby spoczywała na wierzchu Twoich przedramion. Jeśli trzymasz sztangę prawidłowo, powinno wyglądać to tak, jakbyś miał ramiona skrzyżowane, ale z sztangą przechodzącą przez nie.
3. Odejdź od stojaka i ustaw nogi w średnim rozstawie na szerokość barków, z palcami lekko skierowanymi na zewnątrz. Cały czas trzymaj głowę uniesioną, ponieważ patrzenie w dół zaburzy Ci równowagę, i utrzymuj proste plecy. To będzie Twoja pozycja startowa. (Uwaga: na potrzeby tego opisu użyjemy średniego rozstawu opisanego powyżej, który celuje w ogólny rozwój; jednak możesz wybrać dowolny z trzech rozstawów omówionych w sekcji rozstawów stóp).
4. Zacznij opuszczać sztangę, uginając kolana i zachowując prostą postawę z głową uniesioną. Kontynuuj zejście, aż kąt między udem a łydką stanie się nieco mniejszy niż 90 stopni (czyli punkt, w którym uda znajdują się poniżej równoległości do podłogi). Wdech wykonaj podczas tej części ruchu. Wskazówka: Jeśli wykonałeś ćwiczenie poprawnie, przód kolan powinien tworzyć umowną prostą z palcami stóp, prostopadłą do przodu. Jeśli Twoje kolana wykraczają poza tę umowną linię (jeśli są dalej niż palce stóp), to nakładasz nadmierne obciążenie na kolano, a ćwiczenie zostało wykonane niepoprawnie.
5. Zacznij unosić sztangę, robiąc wydech, odpychając podłogę głównie śródstopiem, gdy prostujesz ponownie nogi i wracasz do pozycji startowej.
6. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Zercher_Squats/0.jpg', 'free_exercise_db'),
  ('zottman-curl', 'Uginanie Zottmana', 'Zottman Curl', 'motor_coach', 'intermediate', array['Siłowe', 'Biceps'], 'Uginanie Zottmana łączy podchwyt przy unoszeniu i nachwyt przy opuszczaniu, łącznie trenując biceps i przedramiona. Po pełnym napięciu bicepsa obracasz nadgarstki i powoli opuszczasz hantle nachwytem.', '1. Stań z wyprostowanym tułowiem i hantlą w każdej ręce, trzymaną przy wyprostowanych ramionach. Łokcie powinny być blisko tułowia.
2. Upewnij się, że dłonie są skierowane ku sobie. To będzie Twoja pozycja startowa.
3. Utrzymując górne ramiona nieruchome, uginaj ciężary, napinając biceps, robiąc wydech. Poruszać się powinny tylko przedramiona. Twoje nadgarstki powinny się obracać tak, aby mieć chwyt podchwytem (dłonie do góry). Kontynuuj ruch, aż biceps będzie całkowicie napięty, a hantle na wysokości barków.
4. Przytrzymaj pozycję napiętą przez sekundę, ściskając biceps.
5. Teraz w pozycji napiętej obróć nadgarstki, aż będziesz mieć chwyt nachwytem (dłonie skierowane w dół), z kciukiem w wyższej pozycji niż mały palec.
6. Powoli zacznij opuszczać hantle w dół, używając chwytu nachwytu.
7. Gdy hantle zbliżą się do ud, zacznij obracać nadgarstki, aby wrócić do chwytu neutralnego (dłonie skierowane ku ciału).
8. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Zottman_Curl/0.jpg', 'free_exercise_db'),
  ('zottman-preacher-curl', 'Uginanie Zottmana na modlitewniku', 'Zottman Preacher Curl', 'motor_coach', 'intermediate', array['Siłowe', 'Biceps'], 'Wariant Zottmana na modlitewniku: opuszczasz hantle nachwytem do pełnego rozciągnięcia, obracasz nadgarstki na podchwyt i uginasz do pełnego napięcia bicepsa, po czym znów obracasz chwyt.', '1. Złap hantlę w każdą rękę i połóż górne ramiona na modlitewniku lub ławce skośnej. Hantle powinny być trzymane na wysokości barków, a łokcie ugięte. Trzymaj hantle dłońmi skierowanymi w dół. To będzie Twoja pozycja startowa.
2. Robiąc wdech, powoli opuszczaj hantle, trzymając dłonie skierowane w dół, aż Twoje górne ramię będzie wyprostowane, a bicepsy całkowicie rozciągnięte.
3. Teraz obróć nadgarstki, gdy jesteś na dole ruchu, tak aby dłonie były skierowane do góry.
4. Robiąc wydech, użyj bicepsów, aby ugiąć ciężary w górę, aż będą całkowicie napięte, a hantle na wysokości barków. Pamiętaj ponownie, że aby zapewnić pełne napięcie, musisz unieść mały palec wyżej niż kciuk.
5. Mocno napnij biceps przez sekundę w pozycji napiętej i obróć nadgarstki, aby dłonie znów były skierowane w dół.
6. Powtórz zalecaną liczbę powtórzeń.', NULL, 'free-exercise-db/Zottman_Preacher_Curl/0.jpg', 'free_exercise_db')
on conflict (slug) do nothing;
